globalThis.ANDE_CHUNKS["6670b4443f6dbedc509f083297e0e54ae6a5d1e16c799d0fc150e5baee022d30"] = [{"id":"meituan_social:4730813232","sourceKey":"meituan_social","company":"美团","title":"渠道经理","city":"广州市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4730813232&jobShareType=1","duty":"1、制定执行区域拓展策略：基于市场布局，制定所辖区域的业务开拓计划，并推动落地。\n2、开拓管理服务商网络：负责区域内服务商的开发、签约及全生命周期管理，建立稳定健康的服务商网络。\n3、赋能服务商经营提升：作为服务商的长期伙伴，通过培训、辅导与资源协调，提升其运营效率与服务品质，以此驱动所负责区域的业绩目标达成。\n4、反馈市场信息与策略建议：洞察区域市场、竞争动态与服务商需求，为产品与运营策略优化提供有效输入。","requirements":"1、本科及以上学历，3年以上渠道拓展或商户运营经验，能适应高频次出差。\n2、出色的商务沟通与客户关系经营能力，兼具优秀的业务学习与快速适应能力。\n3、能通过分析定位问题、制定策略并拿到业务结果。","description":"部门介绍\n美团酒店旅行业务涵盖酒店、民宿、机票、火车票、旅游度假、景点门票等各类住行游品类，通过与产业上下游的深度合作，为用户提供美好的旅游旅行体验。我们积极打造AI友好型组织，使用AI等新技术提升旅游服务的供需匹配效率，更好满足用户个性化、多样化的出游需求。我们持续深耕产业链，用数字化服务助力实体商家高质量经营，探索自有品牌等供给新模式，打造健康的商家生态，保障用户服务体验。为满足用户日益增长的跨境旅行需求，我们将聚焦亚太区域，打造高品质的住宿、交通、游玩等服务矩阵。\n这里有多元的业务布局、持续的成长空间，无论是向往的远方还是眼前的工作，一路都是风景相伴。加入我们，共同为用户创造旅游旅行中的高光时刻！\n\n岗位职责\n1、制定执行区域拓展策略：基于市场布局，制定所辖区域的业务开拓计划，并推动落地。\n2、开拓管理服务商网络：负责区域内服务商的开发、签约及全生命周期管理，建立稳定健康的服务商网络。\n3、赋能服务商经营提升：作为服务商的长期伙伴，通过培训、辅导与资源协调，提升其运营效率与服务品质，以此驱动所负责区域的业绩目标达成。\n4、反馈市场信息与策略建议：洞察区域市场、竞争动态与服务商需求，为产品与运营策略优化提供有效输入。\n\n岗位基本要求\n1、本科及以上学历，3年以上渠道拓展或商户运营经验，能适应高频次出差。\n2、出色的商务沟通与客户关系经营能力，兼具优秀的业务学习与快速适应能力。\n3、能通过分析定位问题、制定策略并拿到业务结果。\n\n具备以下条件优先\n有本地生活/OTA行业背景，或拥有服务商赋能、管理等相关经验。\n\n岗位亮点\n综合提升：将贯穿“策略制定、商务拓展、深度运营”的业务全链条，在解决复杂商业问题的实践中，实现个人能力的系统化整合与提升。\n职业路径：公司具备成熟的双通道（管理/专业）晋升机制，在此关键业务中持续创造卓越贡献者，将获得广阔的职业发展空间。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4698517614","sourceKey":"meituan_social","company":"美团","title":"财务科技-数据开发工程师","city":"北京市/成都市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4698517614&jobShareType=1","duty":"1.负责投资业务数据仓库建设，围绕投前、投后全流程管理场景，整合被投项目、财务、投后经营及外部市场等多源数据。\n2.面向项目筛选、尽调、立项、投后管理及退出复盘等业务环节，设计数据模型、指标体系和主题数据集。\n3. 与产品团队紧密协作，深入理解投资业务逻辑，制定统一的数据模型与指标口径，支持投资看板及投资分析等应用场景。\n4. 持续优化数据处理性能与开发效率，推进数据治理、数据质量监控及数据资产规范化建设。","requirements":"1. 大学本科及以上学历，计算机、数学、统计学等相关专业。  \n2. 3年以上数据开发或大数据相关工作经验，熟悉 Hadoop、Spark、Flink 等大数据技术栈。  \n3. 精通 SQL，具备复杂数据查询与性能调优能力，熟悉至少一种主流编程语言（如 Java、Python）。  \n4. 有财务、金融或风控领域数据开发经验者优先，了解会计准则或财务系统者优先。","description":"部门介绍\n财务平台负责公司整体和各业务层面的财务管理工作，通过建设专业、全面、复合的财务管理能力和与业务经营的紧密结合来支持公司健康发展。目前财务平台拥有财务会计、财务报告、资金管理、税务管理、财务共享、财务系统、规划分析、财务BP和内控内审等主要工作方向。我们的目标是建设业界一流的财务管理能力和经营支持体系，为公司战略的正确落地、投入效率的持续提升、业务价值的不断增长保驾护航。欢迎加入财务平台，携手一起向未来！\n\n岗位职责\n1.负责投资业务数据仓库建设，围绕投前、投后全流程管理场景，整合被投项目、财务、投后经营及外部市场等多源数据。\n2.面向项目筛选、尽调、立项、投后管理及退出复盘等业务环节，设计数据模型、指标体系和主题数据集。\n3. 与产品团队紧密协作，深入理解投资业务逻辑，制定统一的数据模型与指标口径，支持投资看板及投资分析等应用场景。\n4. 持续优化数据处理性能与开发效率，推进数据治理、数据质量监控及数据资产规范化建设。\n\n岗位基本要求\n1. 大学本科及以上学历，计算机、数学、统计学等相关专业。  \n2. 3年以上数据开发或大数据相关工作经验，熟悉 Hadoop、Spark、Flink 等大数据技术栈。  \n3. 精通 SQL，具备复杂数据查询与性能调优能力，熟悉至少一种主流编程语言（如 Java、Python）。  \n4. 有财务、金融或风控领域数据开发经验者优先，了解会计准则或财务系统者优先。\n\n具备以下条件优先\n有战略投资、产业投资、私募股权、投行、咨询或投后管理相关数据项目经验。\n\n岗位亮点\n1. 参与金融科技核心系统建设，业务场景丰富，成长空间大。  \n2. 团队技术氛围浓厚，鼓励技术创新与知识分享。  \n3. 工作地点灵活，支持北京、成都双城办公。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4691923527","sourceKey":"meituan_social","company":"美团","title":"零售领域产业研究与投资","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4691923527&jobShareType=1","duty":"1.对国内和国外的各种商品零售业态做系统性地战略研究，持续积累零售领域在运营、商品、供应链、履约等维度的认知，为S-team提供前瞻性的信息输入\n2.做好业务BP工作，帮助业务把握新机会\n3.研究上述相关领域业务/投资机会，并进行战略投资","requirements":"1.具备丰富零售公司/餐饮公司战略研究/商业分析经验\n2.扎实的研究基本功，兼具战略思维及对行业深度认知\n3.对商品零售充满热爱，自驱且投入","description":"部门介绍\n战略与投资平台负责美团公司层面的战略方向与行业研究、业务机会的判断、投资并购、业务经营管理、资本市场运作等多个方向。自2014年成立以来，战投不断推动新的战略机会的探索，与各业务紧密协作，推动公司进行战略与讨论决策。我们投资的领域包括前沿科技、消费零售等，近几年来在前沿科技领域加大了投资布局。战略与投资平台的使命是帮助公司抓住战略性机会，为公司建设持续发现机会、实现长期价值的能力。我们欢迎优秀的你和我们一起创造未来，改变世界。\n\n岗位职责\n1.对国内和国外的各种商品零售业态做系统性地战略研究，持续积累零售领域在运营、商品、供应链、履约等维度的认知，为S-team提供前瞻性的信息输入\n2.做好业务BP工作，帮助业务把握新机会\n3.研究上述相关领域业务/投资机会，并进行战略投资\n\n岗位基本要求\n1.具备丰富零售公司/餐饮公司战略研究/商业分析经验\n2.扎实的研究基本功，兼具战略思维及对行业深度认知\n3.对商品零售充满热爱，自驱且投入\n\n岗位亮点\n1.与S-team和各业务负责人交流学习的机会\n2.商品零售领域正面临重大的行业变化，也提供了很多研究转化的做功机会","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4420569939","sourceKey":"meituan_social","company":"美团","title":"品类流量运营","city":"上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4420569939&jobShareType=1","duty":"1、深入理解住吧各房型品类（电竞、影音、好床、按摩等）的产品特性、用户画像与转化逻辑，建立品类视角的流量运营策略\n\n2、负责线下自有场景（如屏权益、门店触点等）的流量运营，通过内容策划、权益设计与触达优化，持续提升线下场景的用户使用率与流量规模\n\n3、持续跟踪平台策略导向与资源节奏，识别品类流量机会窗口，以线下场景的运营成果为依据，主动争取线上平台资源\n\n4、配合中台营销活动，完成选品推荐、货盘组织与活动方案承接，确保住吧品类在平台活动中获得有效曝光与转化\n\n5、搭建品类流量效果监测体系，覆盖线下场景与线上资源位，从商家侧与平台侧双视角评估流量价值，驱动策略持续迭代","requirements":"1.、本科及以上学历，5年以上互联网品类运营/流量运营/营销运营相关工作经验，有OTA、本地生活、电商平台经验优先\n\n2、有大型营销项目或平台级活动的实际操盘经验，扛过明确的流量/GMV指标，能讲清楚怎么拿到的结果\n\n3、具备较强的产品理解能力，能快速吃透品类卖点与用户需求，把产品特性翻译成流量运营策略\n\n4、熟悉平台资源位运营与活动协作机制，善于跨团队协同推动项目落地，能主动争取资源而非被动等分配\n\n5、具备扎实的数据分析能力，能独立完成流量效果归因，习惯用数据驱动决策","description":"部门介绍\n美团酒店旅行业务涵盖酒店、民宿、机票、火车票、旅游度假、景点门票等各类住行游品类，通过与产业上下游的深度合作，为用户提供美好的旅游旅行体验。我们积极打造AI友好型组织，使用AI等新技术提升旅游服务的供需匹配效率，更好满足用户个性化、多样化的出游需求。我们持续深耕产业链，用数字化服务助力实体商家高质量经营，探索自有品牌等供给新模式，打造健康的商家生态，保障用户服务体验。为满足用户日益增长的跨境旅行需求，我们将聚焦亚太区域，打造高品质的住宿、交通、游玩等服务矩阵。\n这里有多元的业务布局、持续的成长空间，无论是向往的远方还是眼前的工作，一路都是风景相伴。加入我们，共同为用户创造旅游旅行中的高光时刻！\n\n岗位职责\n1、深入理解住吧各房型品类（电竞、影音、好床、按摩等）的产品特性、用户画像与转化逻辑，建立品类视角的流量运营策略\n\n2、负责线下自有场景（如屏权益、门店触点等）的流量运营，通过内容策划、权益设计与触达优化，持续提升线下场景的用户使用率与流量规模\n\n3、持续跟踪平台策略导向与资源节奏，识别品类流量机会窗口，以线下场景的运营成果为依据，主动争取线上平台资源\n\n4、配合中台营销活动，完成选品推荐、货盘组织与活动方案承接，确保住吧品类在平台活动中获得有效曝光与转化\n\n5、搭建品类流量效果监测体系，覆盖线下场景与线上资源位，从商家侧与平台侧双视角评估流量价值，驱动策略持续迭代\n\n岗位基本要求\n1.、本科及以上学历，5年以上互联网品类运营/流量运营/营销运营相关工作经验，有OTA、本地生活、电商平台经验优先\n\n2、有大型营销项目或平台级活动的实际操盘经验，扛过明确的流量/GMV指标，能讲清楚怎么拿到的结果\n\n3、具备较强的产品理解能力，能快速吃透品类卖点与用户需求，把产品特性翻译成流量运营策略\n\n4、熟悉平台资源位运营与活动协作机制，善于跨团队协同推动项目落地，能主动争取资源而非被动等分配\n\n5、具备扎实的数据分析能力，能独立完成流量效果归因，习惯用数据驱动决策\n\n岗位亮点\n1、扁平化管理，拥有充分的自主决策空间与创新机会。 \n\n2、主导平台级线上线下融合项目，打造行业标杆案例","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4253447280","sourceKey":"meituan_social","company":"美团","title":"Keeta-营销平台产品运营","city":"北京市/深圳市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4253447280&jobShareType=1","duty":"1. 深入理解各国家、各业务线的经营目标及运营场景，持续开展业务洞察分析，识别真实业务问题，并通过需求管理机制提升产品与业务协同效率，推动重点需求快速落地，为营销平台规划和能力建设持续提供高价值输入。\n2. 围绕重点业务场景，联合业务及产品团队设计场景化解决方案，形成”运营打法+产品工具”的最佳实践，帮助运营高效达成业务目标。\n3. 持续复盘不同业务场景的实践经验，识别跨国家、跨业务的共性能力需求，推动业务经验沉淀为平台通用能力并推广至各国家、各业务线。","requirements":"1. 本科及以上学历，3 年及以上互联网产品运营、策略运营、平台运营、商家运营或相关工作经验。\n2. 具备优秀的业务理解、问题分析和产品思维，能够快速理解业务目标及运营模式，识别业务问题本质，并从复杂场景中抽象共性问题、设计可落地的解决方案。\n3. 具备较强的需求管理、项目推动和跨团队协同能力，能够高效协同业务、产品、研发等多方资源，推动重点事项落地并形成闭环。\n4. 具备良好的沟通表达能力和英文沟通能力，能够支持国际化业务协作，有海外业务或国际化经验者优先。","description":"部门介绍\nKeeta是全球领先外卖平台美团旗下的独立品牌，肩负着“帮大家吃得更好，生活更好”的使命。依托美团深耕中国市场15年的技术与运营积淀，我们正引领全球餐饮与商品即时配送服务的创新与发展。\n\n自2023年成立以来，Keeta始终扎根社区并创造价值。我们为用户提供可靠的外卖体验，以智慧技术助餐厅提升经营效率，在为骑手拓宽收入来源的同时，也充分提供安全保障措施。基于这份多方共赢、共同成长的理念，我们的业务已从中国香港稳步拓展至中东及巴西，并持续向世界迈进。\n\n岗位职责\n1. 深入理解各国家、各业务线的经营目标及运营场景，持续开展业务洞察分析，识别真实业务问题，并通过需求管理机制提升产品与业务协同效率，推动重点需求快速落地，为营销平台规划和能力建设持续提供高价值输入。\n2. 围绕重点业务场景，联合业务及产品团队设计场景化解决方案，形成”运营打法+产品工具”的最佳实践，帮助运营高效达成业务目标。\n3. 持续复盘不同业务场景的实践经验，识别跨国家、跨业务的共性能力需求，推动业务经验沉淀为平台通用能力并推广至各国家、各业务线。\n\n岗位基本要求\n1. 本科及以上学历，3 年及以上互联网产品运营、策略运营、平台运营、商家运营或相关工作经验。\n2. 具备优秀的业务理解、问题分析和产品思维，能够快速理解业务目标及运营模式，识别业务问题本质，并从复杂场景中抽象共性问题、设计可落地的解决方案。\n3. 具备较强的需求管理、项目推动和跨团队协同能力，能够高效协同业务、产品、研发等多方资源，推动重点事项落地并形成闭环。\n4. 具备良好的沟通表达能力和英文沟通能力，能够支持国际化业务协作，有海外业务或国际化经验者优先。\n\n岗位亮点\n1. 深度参与 Keeta 全球营销平台建设，覆盖多个国家和业务场景，拥有广阔的国际化业务视角。\n2. 不局限于需求承接，而是深度参与业务策略、产品规划及解决方案设计，对业务结果产生直接影响。\n3. 从 0 到 1 建设营销平台产品运营体系，打造标准化、平台化运营能力，成长为兼具业务、产品和平台视角的复合型人才。\n4. 与国际化业务、产品、研发团队深度协作，在复杂业务场景中持续提升业务洞察、产品判断及解决方案设计能力。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4486521905","sourceKey":"meituan_social","company":"美团","title":"AI支付产品经理","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4486521905&jobShareType=1","duty":"1. 根据美团在海外的业务场景，将AI和支付相结合，持续提升支付转化率、客单价及复购率，平衡商业价值与用户体验\n2. 负责AI支付产品的全生命周期管理，深度结合大模型能力，设计多模态交互的支付流程，能借助AI进行业务和功能创新\n3. 作为技术与业务的桥梁，将复杂的支付业务需求转化为技术团队可理解的需求文档（PRD）\n4. 协调设计、研发、测试、运营及市场团队，推动AI支付功能在各场景的高质量上线与迭代。","requirements":"1. 本科及以上学历，计算机、经济学、或设计等相关专业优先。3年以上互联网产品经理经验，具备支付、金融科技、复杂交易平台（如OTA、电商）核心模块实战经验者优先。\n2. 深刻理解人工智能技术，熟悉大语言模型（LLM）、AIGC、智能体（Agent）的工作原理及应用边界。具备Prompt工程和数据评测能力，能够独立完成AI产品的效果复盘与迭代。\n3. 对支付业务有深刻理解，能系统性思考功能、体验、技术与商业价值\n4. 具备出色的需求分析与PRD撰写能力。有从0到1主导AI产品或支付功能落地的完整案例者优先。\n5. 具备跨部门沟通与项目推动能力，英语能做为工作语言优先","description":"部门介绍\n美团金融服务平台成立于2016年，以“场景+金融”模式，携手合作伙伴构建开放生态，为美团平台用户和商户提供底层账户、支付通道、信贷、保险和理财等金融解决方案。我们致力于以科技为核心，助力金融机构打通金融普惠“最后一公里”。我们期待与大家共同完成每一件平凡而卓越的事情，一起为用户提供优质的产品体验，守护用户的资金安全，让生活变得更美好。\n\n岗位职责\n1. 根据美团在海外的业务场景，将AI和支付相结合，持续提升支付转化率、客单价及复购率，平衡商业价值与用户体验\n2. 负责AI支付产品的全生命周期管理，深度结合大模型能力，设计多模态交互的支付流程，能借助AI进行业务和功能创新\n3. 作为技术与业务的桥梁，将复杂的支付业务需求转化为技术团队可理解的需求文档（PRD）\n4. 协调设计、研发、测试、运营及市场团队，推动AI支付功能在各场景的高质量上线与迭代。\n\n岗位基本要求\n1. 本科及以上学历，计算机、经济学、或设计等相关专业优先。3年以上互联网产品经理经验，具备支付、金融科技、复杂交易平台（如OTA、电商）核心模块实战经验者优先。\n2. 深刻理解人工智能技术，熟悉大语言模型（LLM）、AIGC、智能体（Agent）的工作原理及应用边界。具备Prompt工程和数据评测能力，能够独立完成AI产品的效果复盘与迭代。\n3. 对支付业务有深刻理解，能系统性思考功能、体验、技术与商业价值\n4. 具备出色的需求分析与PRD撰写能力。有从0到1主导AI产品或支付功能落地的完整案例者优先。\n5. 具备跨部门沟通与项目推动能力，英语能做为工作语言优先\n\n岗位亮点\n美团海外业务2023年正式确认为公司战略，美团金融服务为服务主业出海，与业务深度绑定，提供全方面的Payin & Payout 支付解决方案。我们期待与大家共同完成每一件平凡而卓越的事情，把吃的更好和生活的更好的愿景旗帜插满全球。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3458513997","sourceKey":"meituan_social","company":"美团","title":"KA销售（商家运营方向）","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3458513997&jobShareType=1","duty":"1.负责养老护理行业的招商与运营，为业务结果指标负责。\n2.制定商家运营策略，完成货架和商家成长体系建设。\n3.基于消费者洞察识别核心场景，协同商家完成服务包设计与标准化建设。\n4.监控用户反馈及商家运营数据，提升整体供给质量。\n5.负责跟踪市场动态和流量趋势，持续调整供给策略，保持竞争优势。","requirements":"1.懂用户，懂服务，能识别出与市场适配的服务供给。\n2.具备良好的商务谈判与资源整合能力，能独立推动KA合作落地。\n3.数据敏感，具备良好的基础建设及运营能力，能通过数据驱动商家经营决策。\n4.具备良好的沟通协调能力和团队合作精神。\n5.对商业模式及用户需求有深刻理解和洞察，能够独立思考和解决问题。\n6.具备AI探索热情。","description":"部门介绍\n美团医药健康事业部是美团核心本地商业板块下专注健康领域的业务部门，涵盖美团买药、美团医美和美团医疗三大业务。自创立以来，美团医药健康致力于为用户提供全健康周期产品及服务，满足人民群众多层次多元化医疗健康需求，现已覆盖购药到家、居家检测、问诊挂号、医保支付、求医寻院、医疗美容等核心场景。此外，美团医药健康还为商户提供数字化转型创新解决方案，打造贯穿上游的联动机制，长期参与共建更透明、更可持续的医药健康产业生态圈，目前业务已覆盖25万家药店，收录27万家医疗机构。未来，美团医药康将协同更多行业伙伴，帮助大家变得更健康、更美丽、更养生。\n\n岗位职责\n1.负责养老护理行业的招商与运营，为业务结果指标负责。\n2.制定商家运营策略，完成货架和商家成长体系建设。\n3.基于消费者洞察识别核心场景，协同商家完成服务包设计与标准化建设。\n4.监控用户反馈及商家运营数据，提升整体供给质量。\n5.负责跟踪市场动态和流量趋势，持续调整供给策略，保持竞争优势。\n\n岗位基本要求\n1.懂用户，懂服务，能识别出与市场适配的服务供给。\n2.具备良好的商务谈判与资源整合能力，能独立推动KA合作落地。\n3.数据敏感，具备良好的基础建设及运营能力，能通过数据驱动商家经营决策。\n4.具备良好的沟通协调能力和团队合作精神。\n5.对商业模式及用户需求有深刻理解和洞察，能够独立思考和解决问题。\n6.具备AI探索热情。\n\n岗位亮点\n创新业务发展机会，深度探索银发经济蓝海市场，与头部养老服务机构共同探索行业标准化路径。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4702834658","sourceKey":"meituan_social","company":"美团","title":"智能硬件电池 Pack结构工程师","city":"北京市/深圳市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4702834658&jobShareType=1","duty":"1. Pack结构方案设计：负责电池Pack结构总体方案设计（箱体/上盖/托盘/模组支架/端板/紧固件/密封/防护等），输出结构架构、关键尺寸链与接口定义。\n2. 设计与工程图输出：使用结构设计软件工具完成建模、工程图、装配关系、公差与关键特性定义，确保可制造/可装配/可维护。\n3. 熟悉两轮车的电池Pack结构，具体包括\n1)空间与集成：熟悉两轮车车架/踏板/座桶/中置等布置约束，能完成Pack与整车的安装点、受力路径、维修可达性与接口定义（含线束走向、继电器/保险/充电口等结构协同）。\n2)轻量化与成本平衡：能在续航与成本目标下，主导材料与工艺取舍（铝/钢/工程塑料/复材），推动零件合并、工艺整合、降本并量化收益。\n3)防水防尘与耐候：面向雨淋/涉水/泥沙/高湿/温循/盐雾，能主导密封体系设计（密封面、压缩量、公差链、排气/泄压与防水的矛盾处理），并对IP目标与验证负责。\n4)振动冲击/跌落可靠性：熟悉两轮典型工况（路面冲击、共振、侧倒/跌落）和换电典型工况（装卸冲击），能制定结构可靠性策略并推动仿真与试验闭环（模态、随机振动、冲击、跌落等）。\n5)快换/换电场景（如适用）：理解换电Pack的插拔寿命、定位导向、防呆、锁止/防盗、把手与人机、快速密封等设计要点，能主导关键机构与公差链设计。\n6)安全结构：能将热安全需求落到结构（隔热阻燃、泄压导流、绝缘与爬电间隙、结构防护），并与电芯/热管理协同形成可验证方案。\n4. 面向制造设计与成本优化：推动可制造性/可装配性设计评审，优化零件数量、工艺路线与装配节拍；进行成本拆解与降本方案落地。\n5. 样件试制与问题闭环：支持样件试制、装配导入、工装夹具需求定义；对试制/测试/量产问题进行定位分析，推动设计改进与版本管理。\n6.量产导入：对接供应商完成材料、工艺（冲压/焊接/压铸/挤压/注塑/粘接/密封等）评审与验证；支持量产导入活动。\n7. 测试验证与标准符合：参与结构相关测试计划制定与执行（振动、冲击、跌落、挤压、热扩散相关结构验证等），确保满足行业/客户/法规标准等。\n8. AI能力建设：在工作中使用通用大模型及生成式AI进行生产性工作，协助团队探索AI辅助硬件结构开发方面的相关应用。\n9. 技术文档与跨部门协作：输出设计说明、失效模式分析输入、变更记录、试验报告总结等文档；组织结构评审并推动决策落地。","requirements":"1. 教育背景：本科及以上，机械设计/车辆工程/材料/机电等相关专业。\n2. 工作经验：3年以上电池Pack结构开发经验（或动力/储能相关结构件开发经验），有从概念到量产的完整项目经历优先。有两轮车电池pack开发经验优先。\n3. 专业能力：熟悉电池Pack结构组成与关键设计点：箱体/上盖密封、模组固定、热管理接口、绝缘与爬电间隙、泄压与防护、轻量化等。熟悉常见材料与工艺：铝合金/钢/塑料/复材；冲压、焊接、压铸、挤压、机加工、注塑、粘接、密封等。熟悉公差分析、紧固连接（螺纹/铆接/焊接/粘接）与装配工艺。\n4. 工具能力：熟练使用至少一种三维设计软件工具与二维出图规范；具备基础有限元分析能力（强度/模态/振动），能与仿真团队高效协作。\n5. 工程化与问题解决：具备系统性问题分析与闭环能力，能在试制/测试/量产阶段快速定位结构问题并推动改进。\n6. AI能力：了解通用大模型的基本原理，了解AI行业最新进展，具有使用生成式AI输出工作文档的经验，具有使用AI辅助进行生产性任务的经验。有使用Open Claw类型AI工具的经验优先。\n7. 沟通协作：能与电芯、电池管理系统、电气、热管理、工艺、质量、供应链等多团队协作推进项目。\n8. 通用素质：结果导向、严谨细致、对安全与质量有敬畏心；能在多项目并行下推进关键节点。","description":"部门介绍\n美团的使命是“帮大家吃得更好，生活更好”，公司聚焦“零售 + 科技”战略，和广大商户与各类合作伙伴一起，努力为消费者提供品质生活，推动商品零售和服务零售在需求侧和供给侧的数字化转型。\n2018年9月20日，美团正式在港交所挂牌上市。美团将始终坚持以客户为中心，不断加大在科技研发方面的投入，更好承担社会责任，更多创造社会价值，与广大合作伙伴一起发展共赢。\n\n岗位职责\n1. Pack结构方案设计：负责电池Pack结构总体方案设计（箱体/上盖/托盘/模组支架/端板/紧固件/密封/防护等），输出结构架构、关键尺寸链与接口定义。\n2. 设计与工程图输出：使用结构设计软件工具完成建模、工程图、装配关系、公差与关键特性定义，确保可制造/可装配/可维护。\n3. 熟悉两轮车的电池Pack结构，具体包括\n1)空间与集成：熟悉两轮车车架/踏板/座桶/中置等布置约束，能完成Pack与整车的安装点、受力路径、维修可达性与接口定义（含线束走向、继电器/保险/充电口等结构协同）。\n2)轻量化与成本平衡：能在续航与成本目标下，主导材料与工艺取舍（铝/钢/工程塑料/复材），推动零件合并、工艺整合、降本并量化收益。\n3)防水防尘与耐候：面向雨淋/涉水/泥沙/高湿/温循/盐雾，能主导密封体系设计（密封面、压缩量、公差链、排气/泄压与防水的矛盾处理），并对IP目标与验证负责。\n4)振动冲击/跌落可靠性：熟悉两轮典型工况（路面冲击、共振、侧倒/跌落）和换电典型工况（装卸冲击），能制定结构可靠性策略并推动仿真与试验闭环（模态、随机振动、冲击、跌落等）。\n5)快换/换电场景（如适用）：理解换电Pack的插拔寿命、定位导向、防呆、锁止/防盗、把手与人机、快速密封等设计要点，能主导关键机构与公差链设计。\n6)安全结构：能将热安全需求落到结构（隔热阻燃、泄压导流、绝缘与爬电间隙、结构防护），并与电芯/热管理协同形成可验证方案。\n4. 面向制造设计与成本优化：推动可制造性/可装配性设计评审，优化零件数量、工艺路线与装配节拍；进行成本拆解与降本方案落地。\n5. 样件试制与问题闭环：支持样件试制、装配导入、工装夹具需求定义；对试制/测试/量产问题进行定位分析，推动设计改进与版本管理。\n6.量产导入：对接供应商完成材料、工艺（冲压/焊接/压铸/挤压/注塑/粘接/密封等）评审与验证；支持量产导入活动。\n7. 测试验证与标准符合：参与结构相关测试计划制定与执行（振动、冲击、跌落、挤压、热扩散相关结构验证等），确保满足行业/客户/法规标准等。\n8. AI能力建设：在工作中使用通用大模型及生成式AI进行生产性工作，协助团队探索AI辅助硬件结构开发方面的相关应用。\n9. 技术文档与跨部门协作：输出设计说明、失效模式分析输入、变更记录、试验报告总结等文档；组织结构评审并推动决策落地。\n\n岗位基本要求\n1. 教育背景：本科及以上，机械设计/车辆工程/材料/机电等相关专业。\n2. 工作经验：3年以上电池Pack结构开发经验（或动力/储能相关结构件开发经验），有从概念到量产的完整项目经历优先。有两轮车电池pack开发经验优先。\n3. 专业能力：熟悉电池Pack结构组成与关键设计点：箱体/上盖密封、模组固定、热管理接口、绝缘与爬电间隙、泄压与防护、轻量化等。熟悉常见材料与工艺：铝合金/钢/塑料/复材；冲压、焊接、压铸、挤压、机加工、注塑、粘接、密封等。熟悉公差分析、紧固连接（螺纹/铆接/焊接/粘接）与装配工艺。\n4. 工具能力：熟练使用至少一种三维设计软件工具与二维出图规范；具备基础有限元分析能力（强度/模态/振动），能与仿真团队高效协作。\n5. 工程化与问题解决：具备系统性问题分析与闭环能力，能在试制/测试/量产阶段快速定位结构问题并推动改进。\n6. AI能力：了解通用大模型的基本原理，了解AI行业最新进展，具有使用生成式AI输出工作文档的经验，具有使用AI辅助进行生产性任务的经验。有使用Open Claw类型AI工具的经验优先。\n7. 沟通协作：能与电芯、电池管理系统、电气、热管理、工艺、质量、供应链等多团队协作推进项目。\n8. 通用素质：结果导向、严谨细致、对安全与质量有敬畏心；能在多项目并行下推进关键节点。\n\n具备以下条件优先\n有两轮车（电动摩托车/电动自行车）电池pack开发经验优先。\n\n岗位亮点\n1. 超大规模骑行场景的真实工程挑战：面向高频使用、全天候、复杂路况与高周转的两轮业务工况做结构设计，可靠性与安全问题 反馈真闭环快，成就感强。\n2. 平台化与规模化：不是做一块电池，而是做一套体系。美团骑行车/电池/充电柜体系完整，换电算法基础丰富，电池监控云平台数据充沛，参与美团电池研发能够充分参与体系化电池研发和应用管理。\n3. 从设计到量产再到运营闭环，成长速度快：不止停留在图纸阶段，会深度参与试制、验证、量产导入与售后问题闭环，形成“设计—验证—运营数据反馈—迭代”的完整能力链。\n4. 沉浸式参与AI辅助研发：美团已全面拥抱AI，在研发工作中实际使用AI辅助设计，加入美团研发团队，沉浸式参与AI辅助研发，培养自己的研发龙虾agent！","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3237056764","sourceKey":"meituan_social","company":"美团","title":"Keeta 配送策略负责人","city":"圣保罗","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3237056764&jobShareType=1","duty":"汇报上级：国家D端负责人\n\n负责KEETA配送业务定价与调度等方向的工作，设计符合当地市场的合理定价方案与调度体系；\n设计不同配送模式（众包/加盟）和不同供需市场的策略，包括定价调度策略、合作商管理策略、体验管控策略，最大化配送效率及体验，达成成本目标、促进规模增长；\n完成配送模式的设计，以及对应的配送一体化方案的建设。\n从0到1搭建国家履约配送策略团队，培养并激励团队；沉淀本领域专业能力，加强人才培养。","requirements":"具有履约配送相关工作经验，对定价调度、或合作商管理、或体验管控方向有深入理解。","description":"部门介绍\nKeeta是全球领先外卖平台美团旗下的独立品牌，肩负着“帮大家吃得更好，生活更好”的使命。依托美团深耕中国市场15年的技术与运营积淀，我们正引领全球餐饮与商品即时配送服务的创新与发展。\n\n自2023年成立以来，Keeta始终扎根社区并创造价值。我们为用户提供可靠的外卖体验，以智慧技术助餐厅提升经营效率，在为骑手拓宽收入来源的同时，也充分提供安全保障措施。基于这份多方共赢、共同成长的理念，我们的业务已从中国香港稳步拓展至中东及巴西，并持续向世界迈进。\n\n岗位职责\n汇报上级：国家D端负责人\n\n负责KEETA配送业务定价与调度等方向的工作，设计符合当地市场的合理定价方案与调度体系；\n设计不同配送模式（众包/加盟）和不同供需市场的策略，包括定价调度策略、合作商管理策略、体验管控策略，最大化配送效率及体验，达成成本目标、促进规模增长；\n完成配送模式的设计，以及对应的配送一体化方案的建设。\n从0到1搭建国家履约配送策略团队，培养并激励团队；沉淀本领域专业能力，加强人才培养。\n\n岗位基本要求\n具有履约配送相关工作经验，对定价调度、或合作商管理、或体验管控方向有深入理解。\n\n岗位亮点\n1、参与美团战略级出海业务，与全球优秀玩家正面交手；\n2、从0到1开拓新市场，体验创业激情；\n3、独立负责一条运力线，统筹配送策略与前后线工作；\n4、管理多元化的团队；\n5、未来独立负责一个国家的履约配送业务。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4771701907","sourceKey":"meituan_social","company":"美团","title":"小象超市-门店品类运营-烘焙","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4771701907&jobShareType=1","duty":"1.协助中台各部门有效制定品类营销计划并组织实施，调动门店员工挖掘市场商机，促进销售额增长；\n2.根据营销计划，制定门店内各品类商品营销动作标准，通过定期巡视、监督，有效管理前线达成相关要求；\n3.具备品类经营意识，及时有效反馈各品类现场营销效果并提出针对性改善方案。","requirements":"1.全国零售线下门店品类运营管理经验，关注熟悉各个品类和季节性的需求；\n2.具备经营管理思路和成本运营意识；\n3.具备体系搭建能力，可以制定并落实各环节的流程；\n4.熟悉大型商超/社区零售等领域的商品运营。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1.协助中台各部门有效制定品类营销计划并组织实施，调动门店员工挖掘市场商机，促进销售额增长；\n2.根据营销计划，制定门店内各品类商品营销动作标准，通过定期巡视、监督，有效管理前线达成相关要求；\n3.具备品类经营意识，及时有效反馈各品类现场营销效果并提出针对性改善方案。\n\n岗位基本要求\n1.全国零售线下门店品类运营管理经验，关注熟悉各个品类和季节性的需求；\n2.具备经营管理思路和成本运营意识；\n3.具备体系搭建能力，可以制定并落实各环节的流程；\n4.熟悉大型商超/社区零售等领域的商品运营。\n\n具备以下条件优先\n有线下零售卖场业务前线品类运营管理工作经验优先\n\n岗位亮点\n岗位属于创新型项目，未来成长和发展空间广阔。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4444080630","sourceKey":"meituan_social","company":"美团","title":"Senior Marketing Manager","city":"利雅得","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4444080630&jobShareType=1","duty":"1. 制定并执行品牌营销策略，提升品牌在沙特市场的知名度和影响力。  \n2. 领导团队策划并落地整合营销活动，包括数字营销、内容营销、公关及线下活动。  \n3. 分析市场趋势与消费者行为，优化营销方案以实现业务增长目标。  \n4. 管理跨部门协作，确保营销活动与公司整体战略保持一致。  \n5. 指导并培养团队成员，提升团队整体专业能力与执行效率。\n6. 运用 AI 工具（如 ChatGPT、Copilot 等）辅助日常分析与策略制定，提升产出效率与质量，主动探索 AI 在本岗位的应用最佳实践。","requirements":"1. 大学本科及以上学历，市场营销、传播学或相关专业优先。  \n2. 10年以上市场营销或品牌管理经验，具备国际品牌本地化运营经验。  \n3. 有成功主导大型营销项目并实现显著增长的实际案例。  \n4. 具备优秀的团队管理能力，曾带领3人及以上团队。  \n5. 英语和阿拉伯语流利，具备出色的沟通与跨团队协作能力。\n6. 熟练使用 AI 工具（如 ChatGPT、Copilot 等）辅助日常工作；具备 AI 学习意愿，能主动探索 AI 在业务场景中的应用。","description":"部门介绍\nKeeta是全球领先外卖平台美团旗下的独立品牌，肩负着“帮大家吃得更好，生活更好”的使命。依托美团深耕中国市场15年的技术与运营积淀，我们正引领全球餐饮与商品即时配送服务的创新与发展。\n\n自2023年成立以来，Keeta始终扎根社区并创造价值。我们为用户提供可靠的外卖体验，以智慧技术助餐厅提升经营效率，在为骑手拓宽收入来源的同时，也充分提供安全保障措施。基于这份多方共赢、共同成长的理念，我们的业务已从中国香港稳步拓展至中东及巴西，并持续向世界迈进。\n\n岗位职责\n1. 制定并执行品牌营销策略，提升品牌在沙特市场的知名度和影响力。  \n2. 领导团队策划并落地整合营销活动，包括数字营销、内容营销、公关及线下活动。  \n3. 分析市场趋势与消费者行为，优化营销方案以实现业务增长目标。  \n4. 管理跨部门协作，确保营销活动与公司整体战略保持一致。  \n5. 指导并培养团队成员，提升团队整体专业能力与执行效率。\n6. 运用 AI 工具（如 ChatGPT、Copilot 等）辅助日常分析与策略制定，提升产出效率与质量，主动探索 AI 在本岗位的应用最佳实践。\n\n岗位基本要求\n1. 大学本科及以上学历，市场营销、传播学或相关专业优先。  \n2. 10年以上市场营销或品牌管理经验，具备国际品牌本地化运营经验。  \n3. 有成功主导大型营销项目并实现显著增长的实际案例。  \n4. 具备优秀的团队管理能力，曾带领3人及以上团队。  \n5. 英语和阿拉伯语流利，具备出色的沟通与跨团队协作能力。\n6. 熟练使用 AI 工具（如 ChatGPT、Copilot 等）辅助日常工作；具备 AI 学习意愿，能主动探索 AI 在业务场景中的应用。\n\n岗位亮点\n1. 加入快速发展的国际企业，参与中东市场战略布局。  \n2. 拥有高度自主权，主导品牌建设与市场拓展方向。  \n3. 提供具有竞争力的薪酬与完善的职业发展通道。  \n4. 工作地点位于利雅得核心商务区，办公环境优越。  \n5. 团队氛围开放包容，鼓励创新与数据驱动的决策文化。\n6.身处 AI 赋能的工作环境，配备前沿 AI 工具与资源，帮助你在 AI 时代持续提升竞争力、加速职业成长。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3256738286","sourceKey":"meituan_social","company":"美团","title":"下沉市场 - 场景增长运营","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3256738286&jobShareType=1","duty":"1、负责下沉业务的场景增长策略制定，通过用户消费场景洞察，挖掘增长机会点；\n2、设计并执行场景化营销活动，包括但不限于节点营销、事件营销等，带动用户规模化增长；\n3、搭建场景增长核心指标监控体系，评估策略效果，并通过系统复盘推动策略持续迭代；\n4、具备良好的 AI 应用能力，能结合业务场景探索 AI 工具提效。","requirements":"1、本科及以上学历，3年以上增长/营销/运营经验，有下沉市场或场景增长成功案例；\n2、数据敏感，能通过数据分析发现增长机会；\n3、具备良好的沟通表达、项目推进、执行落地及跨团队协作能力。","description":"部门介绍\n美团核心本地商业-下沉市场发展部于2015年成立，通过招募优质的合作商伙伴并对其业务经营能力、组织能力等赋能，以期为下沉城市提供一站式的本地生活服务。\n下沉市场发展部的业务场景涵盖了外卖餐饮、团购、拼好饭、闪购、医药等多元化的生活服务领域，同时搭建了一套稳定、高效的即时配送网络，为更多本地用户提供品质化、多样化、便捷高效的生活服务体验，为当地商户提供数字化发展机遇、提升数字化水平，为社会创造更多的就地就业机会。\n截至2024年6月，下沉市场发展部已开拓全国4000+县区市，帮助百万商户实现本地生活服务数字化，日订单量突破千万，为数十万名骑手提供就业岗位，让本地生活服务逐渐成长为地方新基建，实现美团“帮助大家吃得更好，生活更好”的使命！\n\n岗位职责\n1、负责下沉业务的场景增长策略制定，通过用户消费场景洞察，挖掘增长机会点；\n2、设计并执行场景化营销活动，包括但不限于节点营销、事件营销等，带动用户规模化增长；\n3、搭建场景增长核心指标监控体系，评估策略效果，并通过系统复盘推动策略持续迭代；\n4、具备良好的 AI 应用能力，能结合业务场景探索 AI 工具提效。\n\n岗位基本要求\n1、本科及以上学历，3年以上增长/营销/运营经验，有下沉市场或场景增长成功案例；\n2、数据敏感，能通过数据分析发现增长机会；\n3、具备良好的沟通表达、项目推进、执行落地及跨团队协作能力。\n\n岗位亮点\n1、发展空间：核心业务从0-1，成长空间不设限。\n2、全能锻炼：从策略制定到执行落地，一站式掌握业务全貌。\n3、团队氛围：扁平管理，资源开放共享，专注增长。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4780423486","sourceKey":"meituan_social","company":"美团","title":"Cyber 大模型研究员／算法工程师","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4780423486&jobShareType=1","duty":"1. 面向 Cyber 场景开展大模型与 Agent 能力研究，提升安全推理、工具使用与复杂攻防任务执行能力。\n2. 研究模型后训练、攻防数据构建、交互环境与奖励设计等方法，结合个人专长推进重点方向。\n3. 建设攻防能力评测，分析模型与 Agent 的能力瓶颈，开展模型与 Harness 的协同优化。","requirements":"1. 具备扎实的机器学习或网络安全基础，对大模型解决复杂攻防任务有深入理解。\n2. 在以下至少一个方向有深入研究或实践经验：Agentic SFT/RL、Cyber 模型后训练、攻防轨迹与数据工程、训练环境与奖励设计、代码与安全能力评测。\n3. 具备良好的研究与工程能力，能够独立开展问题分析、实验设计、技术实现与效果验证。\n4. 有相关论文、开源贡献、模型训练成果或漏洞研究经验者优先。","description":"部门介绍\n基础研发平台是美团的核心技术平台，立足于“零售+科技”的战略定位，通过打造人工智能、大数据、云计算、安全等核心技术能力，以及研发效能平台、企业应用平台等公共服务，为业务提供稳定安全、扩展易用、技术领先的平台技术和产品服务。\n在这里，我们会参与到最前沿的技术研发和探索；能够接触超规模集群、海量数据，挑战高复杂业务场景，有机会与业界一流的工程师一起并肩前行。\n在这里，我们有超强的技术氛围，持续向社区贡献业界实践，加速行业技术发展；我们有完善的互联网学习生态圈，重视底层逻辑和方法论，助力职业生涯的非线性成长。\n真诚地邀请你，和我们一起驱动技术发展，创造行业价值。\n\n岗位职责\n1. 面向 Cyber 场景开展大模型与 Agent 能力研究，提升安全推理、工具使用与复杂攻防任务执行能力。\n2. 研究模型后训练、攻防数据构建、交互环境与奖励设计等方法，结合个人专长推进重点方向。\n3. 建设攻防能力评测，分析模型与 Agent 的能力瓶颈，开展模型与 Harness 的协同优化。\n\n岗位基本要求\n1. 具备扎实的机器学习或网络安全基础，对大模型解决复杂攻防任务有深入理解。\n2. 在以下至少一个方向有深入研究或实践经验：Agentic SFT/RL、Cyber 模型后训练、攻防轨迹与数据工程、训练环境与奖励设计、代码与安全能力评测。\n3. 具备良好的研究与工程能力，能够独立开展问题分析、实验设计、技术实现与效果验证。\n4. 有相关论文、开源贡献、模型训练成果或漏洞研究经验者优先。\n\n具备以下条件优先\n1. 同时具备模型训练与安全攻防经验，能将真实攻防问题转化为训练任务和评价标准。\n2. 有相关高水平论文、具有实际影响力的开源贡献，或高价值漏洞研究、安全竞赛成果。\n3. 有研究成果落地经验，曾在真实场景中验证模型或 Agent 的能力提升。\n\n岗位亮点\n深入 AI 与网络安全交叉的前沿方向，结合真实攻防场景探索 Cyber 模型与 Agent 的能力边界。参与从任务与数据构建、模型训练到实战评测的完整研究过程，积累模型算法与攻防实践相结合的复合能力。根据个人专长，逐步独立负责专项研究方向，推动成果转化为可验证、可复用的攻防能力。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4027697693","sourceKey":"meituan_social","company":"美团","title":"渠道经理","city":"石家庄市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4027697693&jobShareType=1","duty":"1. 负责区域内渠道合作伙伴的开发、现有合作商管理维护与拓展。  \n2. 制定并执行渠道销售策略，完成公司下达的业绩指标。  \n3. 收集市场信息，分析竞争对手动态，提出优化建议。  \n4. 协助渠道合作伙伴开展市场活动，提升品牌影响力。  \n5. 定期汇报渠道运营数据，提出改进方案。","requirements":"1. 大学本科及以上学历，市场营销、工商管理等相关专业优先。  \n2. 1年以上渠道开发或销售相关工作经验。  \n3. 具备良好的沟通能力和团队协作精神。  \n4. 熟悉石家庄市、保定市市场环境，有本地资源者优先。  \n5. 熟练使用办公软件，具备基础数据分析能力。","description":"部门介绍\n美团骑行事业部在全国各个城市开展美团单车、电单车业务，提供绿色、便捷的共享出行服务，是美团出行板块重要的组成部分。我们力求为城市可持续发展提供低碳智能的解决方案，通过技术创新和硬件升级，不断优化全流程骑行体验，为低碳出行提供更好的服务。其中，美团单车旨在为城市居民提供通勤接驳服务，满足用户短途接驳出行需求；美团电单车则满足用户中短途多场景低碳出行需求。\n我们有开放的工作氛围，也有充满韧劲和创造力，心系低碳出行的伙伴。加入我们，一起为用户创造更好的出行体验。\n\n岗位职责\n1. 负责区域内渠道合作伙伴的开发、现有合作商管理维护与拓展。  \n2. 制定并执行渠道销售策略，完成公司下达的业绩指标。  \n3. 收集市场信息，分析竞争对手动态，提出优化建议。  \n4. 协助渠道合作伙伴开展市场活动，提升品牌影响力。  \n5. 定期汇报渠道运营数据，提出改进方案。\n\n岗位基本要求\n1. 大学本科及以上学历，市场营销、工商管理等相关专业优先。  \n2. 1年以上渠道开发或销售相关工作经验。  \n3. 具备良好的沟通能力和团队协作精神。  \n4. 熟悉石家庄市、保定市市场环境，有本地资源者优先。  \n5. 熟练使用办公软件，具备基础数据分析能力。\n\n岗位亮点\n1. 提供系统的渠道管理培训，助力职业成长。  \n2. 扁平化管理，团队氛围开放高效。  \n3. 业绩导向，奖金激励制度完善。  \n4. 有机会参与公司战略级项目。  \n5. 定期组织团队建设活动，提升归属感。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4785852240","sourceKey":"meituan_social","company":"美团","title":"Marketing Manager – User Growth","city":"迪拜","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4785852240&jobShareType=1","duty":"1. Own the User Growth roadmap, with a focus on increasing the active user base through acquisition, activation, retention, reactivation, and higher order frequency.\n2. Drive user acquisition and reactivation across key Performance Marketing channels, including Meta, Google Ads, TikTok, and Snapchat, with a clear understanding of each channel’s impact on traffic, conversion, users, and orders.\n3. Build a bottom-up growth strategy by translating Food growth targets into key user and funnel drivers, including traffic, registrations, new users, active users, conversion, retention, and frequency.\n4. Monitor daily, weekly, and monthly user and traffic performance, identifying gaps, emerging trends, and opportunities to improve growth against business targets.\n5. Apply strong Performance Marketing knowledge across channel mix, audience strategy, CAC, conversion, and ROI to improve acquisition efficiency and overall user growth.\n6. Work closely with CRM and Partnerships teams to strengthen the user journey across onboarding, activation, repeat purchase, retention, and reactivation.\n7. Work closely with the Data Analytics and Product teams to ensure clear visibility of traffic, acquisition, conversion, cohort performance, retention, and overall user growth.\n8. Identify the right growth channels and initiatives based on business needs and market opportunities, including branding, ground activations, and Out-of-Home (OOH), to support user acquisition and market growth.","requirements":"1. Bachelor's degree or above, majoring in Marketing, Business Administration, or related fields preferred.\n10+ years of experience in user growth or product operations, with international market background preferred.\n2. Proven senior team management experience, having led teams of 10+ members and delivered significant growth results.\n3. Proficient in data analysis tools, with strong data-driven insights and strategy formulation capabilities.\n4. Excellent English communication skills, Arabic language ability is a plus, adapting to Dubai's multicultural work environment.","description":"部门介绍\nKeeta是全球领先外卖平台美团旗下的独立品牌，肩负着“帮大家吃得更好，生活更好”的使命。依托美团深耕中国市场15年的技术与运营积淀，我们正引领全球餐饮与商品即时配送服务的创新与发展。\n\n自2023年成立以来，Keeta始终扎根社区并创造价值。我们为用户提供可靠的外卖体验，以智慧技术助餐厅提升经营效率，在为骑手拓宽收入来源的同时，也充分提供安全保障措施。基于这份多方共赢、共同成长的理念，我们的业务已从中国香港稳步拓展至中东及巴西，并持续向世界迈进。\n\n岗位职责\n1. Own the User Growth roadmap, with a focus on increasing the active user base through acquisition, activation, retention, reactivation, and higher order frequency.\n2. Drive user acquisition and reactivation across key Performance Marketing channels, including Meta, Google Ads, TikTok, and Snapchat, with a clear understanding of each channel’s impact on traffic, conversion, users, and orders.\n3. Build a bottom-up growth strategy by translating Food growth targets into key user and funnel drivers, including traffic, registrations, new users, active users, conversion, retention, and frequency.\n4. Monitor daily, weekly, and monthly user and traffic performance, identifying gaps, emerging trends, and opportunities to improve growth against business targets.\n5. Apply strong Performance Marketing knowledge across channel mix, audience strategy, CAC, conversion, and ROI to improve acquisition efficiency and overall user growth.\n6. Work closely with CRM and Partnerships teams to strengthen the user journey across onboarding, activation, repeat purchase, retention, and reactivation.\n7. Work closely with the Data Analytics and Product teams to ensure clear visibility of traffic, acquisition, conversion, cohort performance, retention, and overall user growth.\n8. Identify the right growth channels and initiatives based on business needs and market opportunities, including branding, ground activations, and Out-of-Home (OOH), to support user acquisition and market growth.\n\n岗位基本要求\n1. Bachelor's degree or above, majoring in Marketing, Business Administration, or related fields preferred.\n10+ years of experience in user growth or product operations, with international market background preferred.\n2. Proven senior team management experience, having led teams of 10+ members and delivered significant growth results.\n3. Proficient in data analysis tools, with strong data-driven insights and strategy formulation capabilities.\n4. Excellent English communication skills, Arabic language ability is a plus, adapting to Dubai's multicultural work environment.\n\n岗位亮点\n1.Join a fast-growing international team and participate in strategic expansion in the Middle East market.\n2. Enjoy full decision-making authority and resource support to drive innovative growth initiatives.\n3. Competitive compensation package and clear career development path.\n4. Based in Dubai, experiencing cosmopolitan living and a multicultural environment.\n5. Work alongside top industry talent, continuously expanding your global vision and professional capabilities.","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:2696301666","sourceKey":"meituan_social","company":"美团","title":"电话商务运营专员","city":"武汉市/成都市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=2696301666&jobShareType=1","duty":"1、负责酒店从签约到上线过程中的全链路合作，包含活动策划、方案制定及其他日常运营工作；\n2、通过电话沟通与酒店达成合作，并协调内部不同部门和资源解决酒店客户问题；\n3、进行新商家拓展，发展新商家与美团酒店业务的合作\n4、维护现有商家的发展，帮助现有商家做方案优化，提高商家销量。","requirements":"1、较强的自我管理能力，优秀的表达能力和沟通技巧；\n2、有极强的责任心和服务意识，富有团队合作精神；\n3、有较强的学习能力，善于总结和发现问题；\n4、有酒店行业、电商行业及互联网从业经验者优先。","description":"部门介绍\n美团酒店旅行业务涵盖酒店、民宿、机票、火车票、旅游度假、景点门票等各类住行游品类，通过与产业上下游的深度合作，为用户提供美好的旅游旅行体验。我们积极打造AI友好型组织，使用AI等新技术提升旅游服务的供需匹配效率，更好满足用户个性化、多样化的出游需求。我们持续深耕产业链，用数字化服务助力实体商家高质量经营，探索自有品牌等供给新模式，打造健康的商家生态，保障用户服务体验。为满足用户日益增长的跨境旅行需求，我们将聚焦亚太区域，打造高品质的住宿、交通、游玩等服务矩阵。\n这里有多元的业务布局、持续的成长空间，无论是向往的远方还是眼前的工作，一路都是风景相伴。加入我们，共同为用户创造旅游旅行中的高光时刻！\n\n岗位职责\n1、负责酒店从签约到上线过程中的全链路合作，包含活动策划、方案制定及其他日常运营工作；\n2、通过电话沟通与酒店达成合作，并协调内部不同部门和资源解决酒店客户问题；\n3、进行新商家拓展，发展新商家与美团酒店业务的合作\n4、维护现有商家的发展，帮助现有商家做方案优化，提高商家销量。\n\n岗位基本要求\n1、较强的自我管理能力，优秀的表达能力和沟通技巧；\n2、有极强的责任心和服务意识，富有团队合作精神；\n3、有较强的学习能力，善于总结和发现问题；\n4、有酒店行业、电商行业及互联网从业经验者优先。\n\n具备以下条件优先\n1.有酒店行业、电商行业及互联网从业经验者优先。\n2.有互联网公司策略/项目运营和销售团队管理经验优先。\n\n岗位亮点\n1.面对不同商家，增强销售能力和解决问题的能力，并可以让你对酒店行业有更全面、更深入的了解；\n2.有机会和公司共同成长，个人综合能力将随业务发展及需求变化不断提升。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4800454424","sourceKey":"meituan_social","company":"美团","title":"小象超市-配送自营站长（潮州/汕头/汕尾/河源/梅州）","city":"潮州市/汕头市/汕尾市/河源市/梅州市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4800454424&jobShareType=1","duty":"1、自营站点日常管理\n自营站点日常人员招聘、人员排班、出勤管理和人员异常处置；制定新骑手留存计划，对老骑手进行关怀，提升骑手留存率；搭建站点管理团队，提升组织厚度；\n2、自营站点产能交付\n承接业务的产能目标，根据产能需求调整骑手排班，跟进骑手出勤，追踪各渠道的人员供给情况；\n3、自营站点体验交付\n根据业务需求完成体验交付目标，处置订单异常和骑手异常，提升订单准时率；\n4、市场信息了解和外部协同\n监控站点范围内的竞争情况，上报竞争异动信息；向上沟通服务站，提升协同效率。","requirements":"1、有3年以上商超即时配送行业站长经验，管理骑手数量超过50人；\n2、有一定的数据能力，能完成站点维度的数据统筹工作；\n3、能服从组织安排，接受华南内城市调派工作。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1、自营站点日常管理\n自营站点日常人员招聘、人员排班、出勤管理和人员异常处置；制定新骑手留存计划，对老骑手进行关怀，提升骑手留存率；搭建站点管理团队，提升组织厚度；\n2、自营站点产能交付\n承接业务的产能目标，根据产能需求调整骑手排班，跟进骑手出勤，追踪各渠道的人员供给情况；\n3、自营站点体验交付\n根据业务需求完成体验交付目标，处置订单异常和骑手异常，提升订单准时率；\n4、市场信息了解和外部协同\n监控站点范围内的竞争情况，上报竞争异动信息；向上沟通服务站，提升协同效率。\n\n岗位基本要求\n1、有3年以上商超即时配送行业站长经验，管理骑手数量超过50人；\n2、有一定的数据能力，能完成站点维度的数据统筹工作；\n3、能服从组织安排，接受华南内城市调派工作。\n\n具备以下条件优先\n1，有生鲜即时配送管理经验；\n2，有自营站点管理经验；\n\n岗位亮点\n1、基于生鲜配送新型业态，完善的内部培训以及晋升机制，未来发展空间大； \n2、配送能力是社区生鲜零售行业的核心竞争力，工作重要性高、成长快。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4800506468","sourceKey":"meituan_social","company":"美团","title":"小象超市-配送主管(咸阳)","city":"咸阳市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4800506468&jobShareType=1","duty":"站点日常管理：晨会组织、6S巡查、门前三包、站点文化打造\n运力全生命周期：骑手招募入职、新人带训、排班调度、留存关怀\n履约与体验保障：客诉/差评处理、异常订单施救、实时数据监控干预\n安全与质量：安全事故处理上报、质量监控、满编跟进\n数据复盘：人效复盘、次日排班与天气预判","requirements":"学历：大专及以上\n行业及管理经验：有管理自有骑手团队/快递员的经验，管理规模不低于50人，管理经验不低于2年\n稳定性：未来3-5年计划在当地发展的同学\n素质：责任心强，有较好的辅导培训意识，标准化执行落地意识好","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n站点日常管理：晨会组织、6S巡查、门前三包、站点文化打造\n运力全生命周期：骑手招募入职、新人带训、排班调度、留存关怀\n履约与体验保障：客诉/差评处理、异常订单施救、实时数据监控干预\n安全与质量：安全事故处理上报、质量监控、满编跟进\n数据复盘：人效复盘、次日排班与天气预判\n\n岗位基本要求\n学历：大专及以上\n行业及管理经验：有管理自有骑手团队/快递员的经验，管理规模不低于50人，管理经验不低于2年\n稳定性：未来3-5年计划在当地发展的同学\n素质：责任心强，有较好的辅导培训意识，标准化执行落地意识好\n\n具备以下条件优先\n有朴朴、盒马、叮咚站长管理经验者优先\n\n岗位亮点\n健全的职业发展规划，业务快速发展期晋升机会多多","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4280790162","sourceKey":"meituan_social","company":"美团","title":"KA履约-渠道管理","city":"沈阳市/哈尔滨市/南京市/杭州市/宁波市/济南市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4280790162&jobShareType=1","duty":"岗位职责:\n1.承接品牌运营策略落地和企客品牌销售需求，对接品牌区域客户的履约复盘和异常处理，负责KA自建运力管理和运营，对KA品牌体验和规模负责；\n2.负责与合作伙伴建立良好的合作关系，推动业务合作的深入发展；\n3.完成KA品牌合同目标与履约诉求，确保销售提报门店按时上线、异常订单及时响应，难度门店和区域通过KA自建运力按时按质承接；\n4.监控和分析市场动态，及时调整渠道策略，优化渠道销售效果。","requirements":"岗位要求:\n1.大学本科学历，市场营销、商务管理、物流行业等相关专业优先；\n2.具有3年以上客户经理或渠道管理，有业务开发经验维护经历；\n3.具备较强的团队管理能力和沟通能力，能够有效协调团队工作，达成团队目标；\n4.具备较强的市场洞察力和数据分析能力，能够根据市场情况灵活调整策略。","description":"部门介绍\n美团配送是以科技为内核的即时物流品牌，利用高效、稳定、广阔的配送网络和前沿科技能力为各行业客户提供涵盖商流物流一体化、流量赋能、行业定制化即时配送、末端配送、前置仓等服务在内的全方位同城物流综合解决方案。\n作为科技创新和智慧物流的实践者，美团配送在人工智能（AI）、5G应用、物联网（IoT）、云计算等多维度不断探索科创蓝海，让同城物流进入数智化时代。美团配送在IoT智能设备、外卖柜、换电网络、无人配送体系等硬件设施与服务上不断推陈出新，持续优化骑手、消费者、商家体验；自研同城物流系统，通过智能分析为用户提供更便捷的生活方式，为商家提供更高效的履约服务。\n加入我们，一起把世界送到消费者手中！\n\n岗位职责\n岗位职责:\n1.承接品牌运营策略落地和企客品牌销售需求，对接品牌区域客户的履约复盘和异常处理，负责KA自建运力管理和运营，对KA品牌体验和规模负责；\n2.负责与合作伙伴建立良好的合作关系，推动业务合作的深入发展；\n3.完成KA品牌合同目标与履约诉求，确保销售提报门店按时上线、异常订单及时响应，难度门店和区域通过KA自建运力按时按质承接；\n4.监控和分析市场动态，及时调整渠道策略，优化渠道销售效果。\n\n岗位基本要求\n岗位要求:\n1.大学本科学历，市场营销、商务管理、物流行业等相关专业优先；\n2.具有3年以上客户经理或渠道管理，有业务开发经验维护经历；\n3.具备较强的团队管理能力和沟通能力，能够有效协调团队工作，达成团队目标；\n4.具备较强的市场洞察力和数据分析能力，能够根据市场情况灵活调整策略。\n\n岗位亮点\n岗位亮点:\n1.提供良好的团队管理和业务拓展平台，有机会参与公司业务发展的重要决策；\n2.薪资福利优厚，提供完善的培训体系和晋升机制；\n3.工作地点郑州/天津等，公司氛围融洽，团队氛围好，发展空间大。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4784290825","sourceKey":"meituan_social","company":"美团","title":"小象超市-大连仓经理（储备）","city":"大连市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4784290825&jobShareType=1","duty":"1. 负责仓库日常运营管理，包括入库、出库、库存盘点及仓储流程优化。\n2. 制定并执行仓库管理制度和操作规范，确保作业安全高效。\n3. 管理仓储团队，进行人员培训、绩效考核及工作安排。\n4. 监控库存水平，减少损耗，提升仓储空间利用率。\n5. 协调物流、采购、销售等部门，保障供应链顺畅运行。","requirements":"1. 大学专科及以上学历，物流、供应链或相关专业优先。\n2. 具备5年以上仓储管理经验，有大型仓库或电商仓储背景者优先。\n3. 熟悉WMS系统及仓储自动化设备操作。\n4. 具备较强的团队管理能力和沟通协调能力。\n5. 工作责任心强，能承受一定工作压力。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1. 负责仓库日常运营管理，包括入库、出库、库存盘点及仓储流程优化。\n2. 制定并执行仓库管理制度和操作规范，确保作业安全高效。\n3. 管理仓储团队，进行人员培训、绩效考核及工作安排。\n4. 监控库存水平，减少损耗，提升仓储空间利用率。\n5. 协调物流、采购、销售等部门，保障供应链顺畅运行。\n\n岗位基本要求\n1. 大学专科及以上学历，物流、供应链或相关专业优先。\n2. 具备5年以上仓储管理经验，有大型仓库或电商仓储背景者优先。\n3. 熟悉WMS系统及仓储自动化设备操作。\n4. 具备较强的团队管理能力和沟通协调能力。\n5. 工作责任心强，能承受一定工作压力。\n\n岗位亮点\n1. 提供完善的培训体系与职业发展通道，助力个人成长。\n2. 团队规模稳定，工作氛围积极，管理扁平化。\n3. 享有具有竞争力的薪酬福利与绩效奖金。\n4. 参与公司重点仓储项目，积累大型仓储管理经验。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4500803396","sourceKey":"meituan_social","company":"美团","title":"小象超市-BDM招聘（华东区域）","city":"嘉兴市/南京市/合肥市/宁波市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4500803396&jobShareType=1","duty":"1、快速搭建BD团队：负责招聘、培养和管理销售团队，建立高绩效团队，并制定并执行相关策略、资源分配等，以实现团队的快速成长；\n2、执行公司的销售策略及政策：负责执行公司的销售策略和政策，通过日常闭环管理跟踪业务进展，带领团队达成业绩目标；\n3、与内外部部门协作：与横向协同部门紧密配合，及时解决销售工作中的各类问题，并持续改进和优化销售流程。","requirements":"1、两年以上销售管理经验；\n2、热爱销售，对互联网公司兴趣强烈；\n3、注重长远职业发展，有强烈的晋升欲望；\n4、学习能力强且勤奋努力，吃苦耐劳，执行力强，有较强的进取心;\n5、精力充沛，具备在压力下出色完成任务的能力。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1、快速搭建BD团队：负责招聘、培养和管理销售团队，建立高绩效团队，并制定并执行相关策略、资源分配等，以实现团队的快速成长；\n2、执行公司的销售策略及政策：负责执行公司的销售策略和政策，通过日常闭环管理跟踪业务进展，带领团队达成业绩目标；\n3、与内外部部门协作：与横向协同部门紧密配合，及时解决销售工作中的各类问题，并持续改进和优化销售流程。\n\n岗位基本要求\n1、两年以上销售管理经验；\n2、热爱销售，对互联网公司兴趣强烈；\n3、注重长远职业发展，有强烈的晋升欲望；\n4、学习能力强且勤奋努力，吃苦耐劳，执行力强，有较强的进取心;\n5、精力充沛，具备在压力下出色完成任务的能力。\n\n岗位亮点\n成长空间：有机会接受美团的培养，经过学习，实践，指导，成为中国互联网的重要成员；\n发展前景：BDM岗位为核心管理岗位，为日后重点的人才储备","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3131191773","sourceKey":"meituan_social","company":"美团","title":"商业增值-零售广告算法工程师","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3131191773&jobShareType=1","duty":"1，召回算法：负责触发召回算法优化，探索生成式召回与 LLM-based Agent 在相关性中的应用，攻克百亿级商品场景下冷启动与长尾商品的信息瓶颈；\n2，预估排序：负责 CTR/CVR 多任务多场景预估排序，深度结合零售业务特点探索超长序列建模、精排Scaling、跨域多目标建模、知识蒸馏、多人群学习、Debias、延迟反馈建模等，攻克长尾商品稀疏与多场景复用难题；\n3，机制策略：负责广告机制算法优化，探索生成式拍卖、自回归机制模型、listwise 建模、精排重排联合建模，持续突破机制与排序分离架构的效率上限；\n4，端到端建模：负责统一多场景广告大模型基座建设，探索召粗一体、端到端生成式推荐等新范式，突破级联架构的信息损失天花板；突破百亿参数级预估模型与1M+超长行为序列建模，探索 Scaling 收益边界；\n5，深入理解零售业务场景，与产品、运营团队协作，推动算法策略在商业化场景中的落地与效果验证。","requirements":"1、硕士研究生及以上学历，计算机、数学、统计等相关专业，对大模型原理及应用有深入理解；\n2、3年以上广告、推荐或搜索算法相关工作经验，具备扎实的机器学习理论基础；有LLM微调、后训练或Agent系统开发经验者优先，具备良好的业务sense；\n3、熟练掌握Python、C++或Java等编程语言，熟悉TensorFlow、PyTorch等深度学习框架；熟悉LLM应用开发工具链（如Prompt工程、RAG、微调框架等）者优先；\n4、具备大规模数据处理能力，熟悉Hadoop、Spark等分布式计算工具；有AI模型训练、部署及推理优化经验者加分；\n5、具备良好的逻辑思维与沟通能力，对AI技术有强烈好奇心和探索欲，能够推动AI项目从研究到落地的全流程。","description":"部门介绍\n美团核心本地商业下业务研发平台，基于公司“零售+科技”的战略导向，通过从底层架构到应用系统、从软件到硬件、从传统算法到GenAI的全方位技术研究，以及开发、运维、安全等全流程能力建设，致力于推动美团核心本地商业下需求侧与供给侧的数字化和智能化升级，助力业务实现高质量增长，优化用户使用体验，提升商户经营水平，促进行业生态伙伴关系的持续健康发展。团队秉持务实、自驱、开放以及追求卓越的工程师文化，一方面通过系统和技术体系的持续迭代升级，帮助业务高质量增长；另一方面，密切关注前沿技术趋势变化，积极创新技术能力，为业务未来发展创造新的可能性。期待优秀的你加入我们，在夯实专业、深耕平台的基础上与业务携手同行，一起用技术 “帮大家吃得更好，生活更好”。\n\n岗位职责\n1，召回算法：负责触发召回算法优化，探索生成式召回与 LLM-based Agent 在相关性中的应用，攻克百亿级商品场景下冷启动与长尾商品的信息瓶颈；\n2，预估排序：负责 CTR/CVR 多任务多场景预估排序，深度结合零售业务特点探索超长序列建模、精排Scaling、跨域多目标建模、知识蒸馏、多人群学习、Debias、延迟反馈建模等，攻克长尾商品稀疏与多场景复用难题；\n3，机制策略：负责广告机制算法优化，探索生成式拍卖、自回归机制模型、listwise 建模、精排重排联合建模，持续突破机制与排序分离架构的效率上限；\n4，端到端建模：负责统一多场景广告大模型基座建设，探索召粗一体、端到端生成式推荐等新范式，突破级联架构的信息损失天花板；突破百亿参数级预估模型与1M+超长行为序列建模，探索 Scaling 收益边界；\n5，深入理解零售业务场景，与产品、运营团队协作，推动算法策略在商业化场景中的落地与效果验证。\n\n岗位基本要求\n1、硕士研究生及以上学历，计算机、数学、统计等相关专业，对大模型原理及应用有深入理解；\n2、3年以上广告、推荐或搜索算法相关工作经验，具备扎实的机器学习理论基础；有LLM微调、后训练或Agent系统开发经验者优先，具备良好的业务sense；\n3、熟练掌握Python、C++或Java等编程语言，熟悉TensorFlow、PyTorch等深度学习框架；熟悉LLM应用开发工具链（如Prompt工程、RAG、微调框架等）者优先；\n4、具备大规模数据处理能力，熟悉Hadoop、Spark等分布式计算工具；有AI模型训练、部署及推理优化经验者加分；\n5、具备良好的逻辑思维与沟通能力，对AI技术有强烈好奇心和探索欲，能够推动AI项目从研究到落地的全流程。\n\n具备以下条件优先\n1，有 LLM4Rec/LLM4Ads 或大模型在推荐/广告场景落地经验，熟悉 pre-train/post-train、SFT、RLHF、Agent 等技术体系；\n2，在 KDD/SIGIR/CIKM/WWW/RecSys/NeurIPS 等国际顶级会议发表过论文；\n3，有电商、本地生活或 O2O 广告场景实战经验。\n\n岗位亮点\n1，贴近业务，全链路闭环：召回-预估-机制，全链路自主掌控，完整参与技术方案到业务收益，算法做功直接驱动可见的业务收入；\n2，LLM4Rec 前沿实践场：生成式召回、生成式排序、生成式拍卖、端到端生成式广告大模型——在这里参与定义下一代广告系统的技术范式；\n3，依托美团广告技术体系深厚沉淀：公司级生成式推荐/Scaling Law/超长序列持续投入；组内生成式检索、预估 Scaling Up 基座、多模态商家表征等代表性项目已全量上线，鼓励技术输出与对外影响力建设；\n4，提供有竞争力的薪酬与完善的职业发展通道；鼓励技术创新与学术研究，支持发表高水平论文及AI相关专利，参与AI会议交流。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:2225533627","sourceKey":"meituan_social","company":"美团","title":"商业增值-广告智能营销算法工程师","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=2225533627&jobShareType=1","duty":"1.负责广告全产品线智能投放业务，包含ROI4投放（QCPX），智能出价（OCPX、BCB）、智能定向、智能预算、智能诊断建议等模块，致力于优化客户投放效果，手段包括但不限于深度学习、自动控制、进化策略以及强化学习前沿技术；\n2.负责商家补贴智能营销算法，针对多种补贴活动场景提升补贴效率，手段包括但不限于基于运筹优化、组合优化、uplift model的智能补贴策略和联动策略；\n3.负责广告投放运营平台智能化建设，实现精准营销提高运营效率，为到家广告提供优质供给；\n4.结合以上方向的研究和实践，探索前沿技术，沉淀技术框架和算法能力，增强技术团队影响力。","requirements":"1.熟练掌握机器学习、深度学习和强化学习技术；\n2.熟悉运筹优化、强化学习、uplift model，对LLM Agent应用有一定认知；\n3.对解决业务问题有热情，有较强数据分析和解决问题能力；\n4.具有较强的学习能力和逻辑思维能力，对技术有强烈的好奇心；\n5.具备较强的团队合作意识和沟通能力，能够与业务方协同工作，推动项目进展。","description":"部门介绍\n美团核心本地商业下业务研发平台，基于公司“零售+科技”的战略导向，通过从底层架构到应用系统、从软件到硬件、从传统算法到GenAI的全方位技术研究，以及开发、运维、安全等全流程能力建设，致力于推动美团核心本地商业下需求侧与供给侧的数字化和智能化升级，助力业务实现高质量增长，优化用户使用体验，提升商户经营水平，促进行业生态伙伴关系的持续健康发展。团队秉持务实、自驱、开放以及追求卓越的工程师文化，一方面通过系统和技术体系的持续迭代升级，帮助业务高质量增长；另一方面，密切关注前沿技术趋势变化，积极创新技术能力，为业务未来发展创造新的可能性。期待优秀的你加入我们，在夯实专业、深耕平台的基础上与业务携手同行，一起用技术 “帮大家吃得更好，生活更好”。\n\n岗位职责\n1.负责广告全产品线智能投放业务，包含ROI4投放（QCPX），智能出价（OCPX、BCB）、智能定向、智能预算、智能诊断建议等模块，致力于优化客户投放效果，手段包括但不限于深度学习、自动控制、进化策略以及强化学习前沿技术；\n2.负责商家补贴智能营销算法，针对多种补贴活动场景提升补贴效率，手段包括但不限于基于运筹优化、组合优化、uplift model的智能补贴策略和联动策略；\n3.负责广告投放运营平台智能化建设，实现精准营销提高运营效率，为到家广告提供优质供给；\n4.结合以上方向的研究和实践，探索前沿技术，沉淀技术框架和算法能力，增强技术团队影响力。\n\n岗位基本要求\n1.熟练掌握机器学习、深度学习和强化学习技术；\n2.熟悉运筹优化、强化学习、uplift model，对LLM Agent应用有一定认知；\n3.对解决业务问题有热情，有较强数据分析和解决问题能力；\n4.具有较强的学习能力和逻辑思维能力，对技术有强烈的好奇心；\n5.具备较强的团队合作意识和沟通能力，能够与业务方协同工作，推动项目进展。\n\n具备以下条件优先\n1.有智能出价、智能定向等广告智能投放经验或智能营销算法经验者优先；\n2.在国际顶会（CCF-A）或期刊（SCI-Q1）上发表过学术论文者优先；\n\n岗位亮点\n1.到家核心业务之一，业务和团队发展迅速，成长空间大；\n2.与业务方合作紧密，能够深入了解广告业务的全链路；\n3.有机会探索广告前沿技术领域和研究方向，并快速落地取得业务收益；\n4.团队技术实力强，大牛云集，另外还有校企科研合作等形式开展前沿技术研究；\n5.团队氛围好，有温度，相互理解尊重，相互帮助成长。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4798413890","sourceKey":"meituan_social","company":"美团","title":"生鲜品控专家-重庆","city":"重庆市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4798413890&jobShareType=1","duty":"1. 负责小象超市生鲜供应链环节商品及供应商质量管理，从源头到餐桌，预防和优化商品质量问题，提升用户满意度；\n2. 负责商品验收，存储，包装，配送过程中的质量检测和标准落地，减少各环节的商品质量问题发生；\n3. 负责跟踪解决出现的商品（特别是生鲜产品）质量问题，避免商品质量问题重复出现，影响用户体验；\n4. 负责与采购/客服/品质标准组等相关横向部门配合，解决商品品质异常及潜在食品安全风险。","requirements":"1. 专科以上学历，4年及以上商超零售质量管理经验、或供应链质量管理经验、或门店商品质量运营管理；\n2. 具备跨部门的高效沟通及协作能力，能快速推进项目落地；\n3. 诚信、正直、责任心及上进心强。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1. 负责小象超市生鲜供应链环节商品及供应商质量管理，从源头到餐桌，预防和优化商品质量问题，提升用户满意度；\n2. 负责商品验收，存储，包装，配送过程中的质量检测和标准落地，减少各环节的商品质量问题发生；\n3. 负责跟踪解决出现的商品（特别是生鲜产品）质量问题，避免商品质量问题重复出现，影响用户体验；\n4. 负责与采购/客服/品质标准组等相关横向部门配合，解决商品品质异常及潜在食品安全风险。\n\n岗位基本要求\n1. 专科以上学历，4年及以上商超零售质量管理经验、或供应链质量管理经验、或门店商品质量运营管理；\n2. 具备跨部门的高效沟通及协作能力，能快速推进项目落地；\n3. 诚信、正直、责任心及上进心强。\n\n具备以下条件优先\n1. 热爱互联网和新零售行业，具有极强的快速学习能力，进取心和要性强；\n2. 有较强的质量管理方法论且可以快速结合业务特点落地能力；\n3. 擅长数据分析，自驱力、逻辑思维能力和落地性较强；\n4. 有肉禽蛋、果蔬、标品质量管理经验优先。\n\n岗位亮点\n本岗位直接参与小象超市的超大体量业务商品品质管理。候选人的才华将直接对行业产生影响。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:2348067898","sourceKey":"meituan_social","company":"美团","title":"商业增值-大模型应用算法工程师","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=2348067898&jobShareType=1","duty":"1. 负责商业增值业务场景中大模型的技术落地，支持业务目标提升；\n2. 负责大模型在智能助手、电销、IM等交互式对话场景中的应用，提升场景的自动化与智能化水平，改进商家的交互体验，提升广告供给；\n3. 负责大模型在经营诊断分析、多模态创意生成等内容生成类场景中的应用，降低平台和商家的运营成本，提升运营效率；\n4. 负责大型语言模型的微调、偏好对齐、知识增强等技术探索，积极跟进AIGC业内应用趋势，包括并不限于多模态、RLHF、Agent等方向；\n5. 与其他团队密切合作，包括数据工程师、前后端工程师、产品经理等，实现高质量的产品和解决方案。","requirements":"1. 硕士及以上学历，计算机科学、人工智能、自然语言处理或相关专业；\n2. 具备扎实的算法基础，熟悉自然语言处理相关理论，熟悉Transformer/BERT/GPT等基础模型结构，熟悉大模型的微调和评估方法；\n3. 具备扎实的Agent工程设计与开发能力，熟悉任务规划、工具调用、记忆管理及多Agent协作机制，保障复杂业务场景下Agent运行的可靠性、效率与成本可控；\n4. 熟练掌握至少一种深度学习框架，如PyTorch、TensorFlow等；\n5. 善于分析和发现问题，具备较强的自驱力，具有良好的沟通能力和跨团队协作能力，热衷于追求技术创新，对解决有挑战性的问题充满激情。","description":"部门介绍\n美团核心本地商业下业务研发平台，基于公司“零售+科技”的战略导向，通过从底层架构到应用系统、从软件到硬件、从传统算法到GenAI的全方位技术研究，以及开发、运维、安全等全流程能力建设，致力于推动美团核心本地商业下需求侧与供给侧的数字化和智能化升级，助力业务实现高质量增长，优化用户使用体验，提升商户经营水平，促进行业生态伙伴关系的持续健康发展。团队秉持务实、自驱、开放以及追求卓越的工程师文化，一方面通过系统和技术体系的持续迭代升级，帮助业务高质量增长；另一方面，密切关注前沿技术趋势变化，积极创新技术能力，为业务未来发展创造新的可能性。期待优秀的你加入我们，在夯实专业、深耕平台的基础上与业务携手同行，一起用技术 “帮大家吃得更好，生活更好”。\n\n岗位职责\n1. 负责商业增值业务场景中大模型的技术落地，支持业务目标提升；\n2. 负责大模型在智能助手、电销、IM等交互式对话场景中的应用，提升场景的自动化与智能化水平，改进商家的交互体验，提升广告供给；\n3. 负责大模型在经营诊断分析、多模态创意生成等内容生成类场景中的应用，降低平台和商家的运营成本，提升运营效率；\n4. 负责大型语言模型的微调、偏好对齐、知识增强等技术探索，积极跟进AIGC业内应用趋势，包括并不限于多模态、RLHF、Agent等方向；\n5. 与其他团队密切合作，包括数据工程师、前后端工程师、产品经理等，实现高质量的产品和解决方案。\n\n岗位基本要求\n1. 硕士及以上学历，计算机科学、人工智能、自然语言处理或相关专业；\n2. 具备扎实的算法基础，熟悉自然语言处理相关理论，熟悉Transformer/BERT/GPT等基础模型结构，熟悉大模型的微调和评估方法；\n3. 具备扎实的Agent工程设计与开发能力，熟悉任务规划、工具调用、记忆管理及多Agent协作机制，保障复杂业务场景下Agent运行的可靠性、效率与成本可控；\n4. 熟练掌握至少一种深度学习框架，如PyTorch、TensorFlow等；\n5. 善于分析和发现问题，具备较强的自驱力，具有良好的沟通能力和跨团队协作能力，热衷于追求技术创新，对解决有挑战性的问题充满激情。\n\n具备以下条件优先\n1. 有NIPS、ICML，ACL等NLP领域顶会论文发表经验验，或在具有影响力的NLP比赛中获得top名次，或开源社区项目开发经验；\n2. 具有生成式模型训练及开发经验，如大模型数据处理、模型微调、预训练、强化学习、内容安全等，了解Megatron，verl，vllm等训练或推理加速框架。\n3. 有Openclaw或其他大模型框架开发经验者优先；\n4. 有智能客服、智能助手、Agent相关项目经验者优先。\n\n岗位亮点\n1. 到家核心业务，你将接触到海量的toC和toB数据，业务场景广泛，拥有丰富的实践机会，贴近一线大规模业务应用；\n2. 你将负责前沿大语言模型技术的探索和落地，获得在业内最前沿的大模型认知和技术积累；\n3. 你将加入业界一流的团队，其成员有多篇顶级会议论文发表。\n4. 团队氛围好，有温度，相互理解尊重，相互帮助成长。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4791290631","sourceKey":"meituan_social","company":"美团","title":"商业增值-销售智能化研发工程师","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4791290631&jobShareType=1","duty":"负责参与销售智能化（AIBD）解决方案的设计与开发，推进大模型在外呼对话、话术优化、智能转化等销售核心场景的落地实施。\n1，参与销售智能化外呼/对话系统的架构设计与核心模块开发，覆盖多业务线、多广告产品的智能销售场景；\n2，负责大模型在销售场景的落地实施，包括但不限于：话术生成与优化、意图识别、商家模拟器、离线评测体系、数据飞轮等关键链路的工程建设；\n3，持续跟踪大模型及 AI 领域的前沿动态，关注技术演进与行业应用趋势，为团队引入创新思路与技术视野；\n4，与算法、产品、运营紧密协作，将业务需求拆解为可落地的技术方案，对线上转化效果负责。","requirements":"1，本科及以上学历，3年及以上互联网系统研发经验；\n2，业务理解能力优秀，对数据有较高敏感度，逻辑思维能力强，能从业务指标反推技术优化点；\n3，熟悉 Agent 框架开发，有大模型在真实业务场景的应用经验；\n4，熟悉 AI 驱动的开发范式，有较丰富的研发实践经验，能熟练使用 AI Coding 工具提升交付效率；\n5，善于交流，积极拥抱 AI，乐于学习与分享，具备跨团队推动落地的能力。","description":"部门介绍\n美团核心本地商业下业务研发平台，基于公司“零售+科技”的战略导向，通过从底层架构到应用系统、从软件到硬件、从传统算法到GenAI的全方位技术研究，以及开发、运维、安全等全流程能力建设，致力于推动美团核心本地商业下需求侧与供给侧的数字化和智能化升级，助力业务实现高质量增长，优化用户使用体验，提升商户经营水平，促进行业生态伙伴关系的持续健康发展。团队秉持务实、自驱、开放以及追求卓越的工程师文化，一方面通过系统和技术体系的持续迭代升级，帮助业务高质量增长；另一方面，密切关注前沿技术趋势变化，积极创新技术能力，为业务未来发展创造新的可能性。期待优秀的你加入我们，在夯实专业、深耕平台的基础上与业务携手同行，一起用技术 “帮大家吃得更好，生活更好”。\n\n岗位职责\n负责参与销售智能化（AIBD）解决方案的设计与开发，推进大模型在外呼对话、话术优化、智能转化等销售核心场景的落地实施。\n1，参与销售智能化外呼/对话系统的架构设计与核心模块开发，覆盖多业务线、多广告产品的智能销售场景；\n2，负责大模型在销售场景的落地实施，包括但不限于：话术生成与优化、意图识别、商家模拟器、离线评测体系、数据飞轮等关键链路的工程建设；\n3，持续跟踪大模型及 AI 领域的前沿动态，关注技术演进与行业应用趋势，为团队引入创新思路与技术视野；\n4，与算法、产品、运营紧密协作，将业务需求拆解为可落地的技术方案，对线上转化效果负责。\n\n岗位基本要求\n1，本科及以上学历，3年及以上互联网系统研发经验；\n2，业务理解能力优秀，对数据有较高敏感度，逻辑思维能力强，能从业务指标反推技术优化点；\n3，熟悉 Agent 框架开发，有大模型在真实业务场景的应用经验；\n4，熟悉 AI 驱动的开发范式，有较丰富的研发实践经验，能熟练使用 AI Coding 工具提升交付效率；\n5，善于交流，积极拥抱 AI，乐于学习与分享，具备跨团队推动落地的能力。\n\n具备以下条件优先\n1，熟悉智能销售/智能客服系统，有过 AI 外呼、对话机器人、销售话术优化等建设经验者优先；\n2，了解数据算法，有过 AI Infra、Agent 平台、模型训练 pipeline、评测体系等建设经验者优先。\n\n岗位亮点\n1，全栈组织：团队兼具工程与算法能力，从 AI 工程、数据挖掘、模型研发等全链路闭环，可快速落地验证拿效果；\n2，技术空间充足：团队积极拥抱 Agent、大模型等技术，有充足的空间开展各类 Agent 工作流 → 智能治理体系的探索与落地；\n3，业务前景好、个人机会多：美团广告是公司商业变现重点方向之一，业务涉及变现模式多，前景好机会多；\n4，横跨到家到店业务线，横向拿效果：业务覆盖到家、到店主要业务线，治理场景丰富多样，个人成长与业务影响力双提升。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4795609978","sourceKey":"meituan_social","company":"美团","title":"小象-重庆-生产主管","city":"重庆市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4795609978&jobShareType=1","duty":"1、仓库分拣板块的整体管理工作。\n2、负责审视生产需求，合理化排班保障效率成本最优。\n3、负责拣播员工的作业技能培训、日常管理、关怀、留存等。\n4、负责从链路协同视角，提高生产作业效率和质量。\n5、按时完成订单生产，保证履约时效。\n6、负责本岗位相关的物资，设备，及人员生产安全管理。","requirements":"1、专科及以上学历，物流管理等相关专业优先。\n2、3年及以上物流、仓储相关领域管理工作经验优先。\n3、较好的沟通能力、执行力，熟练使用电脑，熟悉办公软件。\n4、熟悉物流、仓储业务流程，有零售仓储管理工作经验优先\n5. 工作地点为重庆市，能适应倒班工作安排。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1、仓库分拣板块的整体管理工作。\n2、负责审视生产需求，合理化排班保障效率成本最优。\n3、负责拣播员工的作业技能培训、日常管理、关怀、留存等。\n4、负责从链路协同视角，提高生产作业效率和质量。\n5、按时完成订单生产，保证履约时效。\n6、负责本岗位相关的物资，设备，及人员生产安全管理。\n\n岗位基本要求\n1、专科及以上学历，物流管理等相关专业优先。\n2、3年及以上物流、仓储相关领域管理工作经验优先。\n3、较好的沟通能力、执行力，熟练使用电脑，熟悉办公软件。\n4、熟悉物流、仓储业务流程，有零售仓储管理工作经验优先\n5. 工作地点为重庆市，能适应倒班工作安排。\n\n岗位亮点\n1. 加入快速发展的新零售物流平台，拥有广阔的职业发展空间。  \n2. 工作地点位于重庆核心区域。  \n3. 提供完善的培训体系和晋升通道，助力个人能力提升与职业发展。  \n4. 团队氛围积极向上，注重员工成长与工作生活平衡。  \n5. 享有具有竞争力的薪酬福利和绩效激励机制。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4801831610","sourceKey":"meituan_social","company":"美团","title":"小象超市-广州供应链品控主管","city":"广州市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4801831610&jobShareType=1","duty":"1、负责生鲜的供应链环节的商品品质改善，从源头到餐桌，预防和优化商品质量问题，提升用户满意度；\n2、负责质检团队的招募、培训和人员绩效管理，快速搭建质量管理监控体系，输出质量改善建议，推动质量改善；\n3、负责商品收货，存储，包装，配送过程中的质量检测和标准落地，减少各环节的商品质量问题发生；\n4、负责跟踪解决出现的商品（特别是生鲜产品）质量问题，避免商品质量问题重复出现，影响用户体验；\n5、负责解决突发的食品安全问题，降低食品安全风险。","requirements":"1、专科以上学历，3年以上商超零售质量管理经验或供应链质量管理经验；\n2、具备很强的跨部门沟通表达及协作能力，能快速推进项目落地；\n3、有极强的责任心，自驱性强，能承受较强的工作压力；\n4、具备正直诚信的价值观，有较强的原则性。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1、负责生鲜的供应链环节的商品品质改善，从源头到餐桌，预防和优化商品质量问题，提升用户满意度；\n2、负责质检团队的招募、培训和人员绩效管理，快速搭建质量管理监控体系，输出质量改善建议，推动质量改善；\n3、负责商品收货，存储，包装，配送过程中的质量检测和标准落地，减少各环节的商品质量问题发生；\n4、负责跟踪解决出现的商品（特别是生鲜产品）质量问题，避免商品质量问题重复出现，影响用户体验；\n5、负责解决突发的食品安全问题，降低食品安全风险。\n\n岗位基本要求\n1、专科以上学历，3年以上商超零售质量管理经验或供应链质量管理经验；\n2、具备很强的跨部门沟通表达及协作能力，能快速推进项目落地；\n3、有极强的责任心，自驱性强，能承受较强的工作压力；\n4、具备正直诚信的价值观，有较强的原则性。\n\n具备以下条件优先\n1、热爱互联网和新零售行业，具有极强的快速学习能力；\n2、有较强的质量管理方法论且可以快速结合业务特点落地能力；\n3、有创业吃苦精神。\n\n岗位亮点\n美团大平台，开放的管理模式，发展空间大 。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4798272293","sourceKey":"meituan_social","company":"美团","title":"济南CDC运营主管","city":"济南市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4798272293&jobShareType=1","duty":"1. 负责济南CDC日常运营管理工作，确保仓储、分拣、配送等环节高效运转。  \n2. 带领20人团队完成日常作业目标，优化人员排班与绩效考核机制。  \n3. 监控运营数据，分析效率瓶颈并提出改进方案，持续提升运营质量。  \n4. 协调内外部资源，保障订单履约时效，提升客户满意度。  \n5. 落实安全管理制度，确保作业现场符合安全及合规要求。","requirements":"1. 大学本科及以上学历，物流、供应链或相关专业优先。  \n2. 具备5年以上物流或仓储运营管理经验，有团队管理经验。  \n3. 熟悉仓储作业流程及WMS系统操作，具备数据分析能力。  \n4. 具备良好的沟通协调能力。  \n5. 工作地点为济南市，能长期稳定发展。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1. 负责济南CDC日常运营管理工作，确保仓储、分拣、配送等环节高效运转。  \n2. 带领20人团队完成日常作业目标，优化人员排班与绩效考核机制。  \n3. 监控运营数据，分析效率瓶颈并提出改进方案，持续提升运营质量。  \n4. 协调内外部资源，保障订单履约时效，提升客户满意度。  \n5. 落实安全管理制度，确保作业现场符合安全及合规要求。\n\n岗位基本要求\n1. 大学本科及以上学历，物流、供应链或相关专业优先。  \n2. 具备5年以上物流或仓储运营管理经验，有团队管理经验。  \n3. 熟悉仓储作业流程及WMS系统操作，具备数据分析能力。  \n4. 具备良好的沟通协调能力。  \n5. 工作地点为济南市，能长期稳定发展。\n\n具备以下条件优先\n美团内部推荐优先\n\n岗位亮点\n1. 加入快速发展的物流平台，拥有广阔的职业晋升空间。  \n2. 提供完善的培训体系和绩效激励机制。  \n3. 团队氛围积极，注重员工成长与关怀。  \n4. 工作地点位于济南核心物流枢纽，交通便利。  \n5. 享受具有竞争力的薪酬福利及五险一金等全面保障。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:1438249479","sourceKey":"meituan_social","company":"美团","title":"乐生活-休闲行业CKA销售","city":"北京市/天津市/长春市/大连市/济南市/青岛市/沈阳市/太原市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=1438249479&jobShareType=1","duty":"1．通过销售拜访，了解商户的业务现状与实际需求并结合消费者的消费动向，制定个性化营销方案，与商户谈判并达成合作；\n2．执行公司的销售策略及政策，达成业绩目标；\n3．与公司各部门配合，及时处理用户的反馈、投诉和建议，提高用户满意度；\n4．归档和更新所有目标商户拜访、协议、服务条款等有关的文件和数据，确保信息在数据库中得到正确的维护。","requirements":"1．大专及以上学历，有销售工作经验优先。可接受优秀应届毕业生。\n2．有很强的学习能力和适应能力，适应互联网行业的快速发展；\n3．具备较强的人际沟通及逻辑思维能力，思维敏捷，能够准确把握产品优势和客户心理，高效整合内外部资源促成销售业绩；\n4．富有激情和创新理念，追求个人职业发展和公司利益的双赢；\n5．热爱销售，善于挑战，积极乐观，有强烈的成功欲望和企图心；\n6．为人正直，诚实可靠，以公司利益为重。","description":"部门介绍\n美团服务零售事业部下设乐生活业务部、易生活业务部、进场零售业务部以及中小城市发展部四大业务部门，旨在通过提供丰富、可靠、实惠的服务与商品满足用户各类生活需求。我们所处的服务零售行业是一个具有万亿规模的市场，覆盖足疗洗浴、酒吧KTV、运动健身、美发美甲、教育培训、亲子游乐、家政洗涤维修、摄影写真等数十个服务消费细分领域，同时延伸至超市便利、美妆个护、3C数码、服饰珠宝、运动户外、商场购物中心等实体零售到店消费场景，连接数十万品牌商户与线下门店。作为商家和行业的小帮手，我们持续深入服务零售与实体零售产业链，用AI等技术推动行业变革，帮助商家提升经营效率、实现高效的线上化经营与到店转化，优化消费者服务体验，提供安心、放心的履约保障。这里有着多元的业务布局，有着富有挑战和影响力的工作内容，为你提供丰富的视野、持续的成长和发展机会，引领你发现更多可能。期待和你在“随时随地，美好生活”的愿景指引下，共建美好的生活服务体验、健康的商家生态与高质量的经营结果。\n\n岗位职责\n1．通过销售拜访，了解商户的业务现状与实际需求并结合消费者的消费动向，制定个性化营销方案，与商户谈判并达成合作；\n2．执行公司的销售策略及政策，达成业绩目标；\n3．与公司各部门配合，及时处理用户的反馈、投诉和建议，提高用户满意度；\n4．归档和更新所有目标商户拜访、协议、服务条款等有关的文件和数据，确保信息在数据库中得到正确的维护。\n\n岗位基本要求\n1．大专及以上学历，有销售工作经验优先。可接受优秀应届毕业生。\n2．有很强的学习能力和适应能力，适应互联网行业的快速发展；\n3．具备较强的人际沟通及逻辑思维能力，思维敏捷，能够准确把握产品优势和客户心理，高效整合内外部资源促成销售业绩；\n4．富有激情和创新理念，追求个人职业发展和公司利益的双赢；\n5．热爱销售，善于挑战，积极乐观，有强烈的成功欲望和企图心；\n6．为人正直，诚实可靠，以公司利益为重。\n\n岗位亮点\n互联网平台，成长空间大，有机会学习并掌握互联网本地生活的工作方式。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4777373115","sourceKey":"meituan_social","company":"美团","title":"生鲜仓生产主管","city":"杭州市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4777373115&jobShareType=1","duty":"1. 负责生鲜仓日常生产运营管理工作，确保货物高效、准确出入库。  \n2. 制定并优化生产作业流程，提升仓储运作效率与质量。  \n3. 管理100人团队，包括排班、培训、绩效考核及人员激励。  \n4. 监控生鲜商品存储条件，保障食品安全与品质标准。  \n5. 协同采购、配送等部门，确保供应链各环节顺畅衔接。","requirements":"1. 大学专科及以上学历，物流、供应链或相关专业优先。  \n2. 具备5年以上仓储或物流管理经验，有生鲜行业背景者优先。  \n3. 熟悉生鲜仓储作业流程及温控管理要求。  \n4. 具备较强的团队管理与沟通协调能力。  \n5. 责任心强。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1. 负责生鲜仓日常生产运营管理工作，确保货物高效、准确出入库。  \n2. 制定并优化生产作业流程，提升仓储运作效率与质量。  \n3. 管理100人团队，包括排班、培训、绩效考核及人员激励。  \n4. 监控生鲜商品存储条件，保障食品安全与品质标准。  \n5. 协同采购、配送等部门，确保供应链各环节顺畅衔接。\n\n岗位基本要求\n1. 大学专科及以上学历，物流、供应链或相关专业优先。  \n2. 具备5年以上仓储或物流管理经验，有生鲜行业背景者优先。  \n3. 熟悉生鲜仓储作业流程及温控管理要求。  \n4. 具备较强的团队管理与沟通协调能力。  \n5. 责任心强。\n\n岗位亮点\n1. 加入快速发展的生鲜供应链平台，职业成长空间广阔。  \n2. 提供完善的培训体系与晋升通道。  \n3. 工作地点位于杭州，交通便利，办公环境优良。  \n4. 团队氛围积极，注重员工关怀与职业发展。  \n5. 具有竞争力的薪酬福利与绩效激励机制。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4799441483","sourceKey":"meituan_social","company":"美团","title":"小象超市-配送主管(沈阳)","city":"沈阳市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4799441483&jobShareType=1","duty":"1、站点日常管理：晨会组织、6S巡查、门前三包、站点文化打造；\n\n2、运力全生命周期：骑手招募入职、新人带训、排班调度、留存关怀；\n\n3、履约与体验保障：客诉/差评处理、异常订单施救、实时数据监控干预；\n\n4、安全与质量：安全事故处理上报、质量监控、满编跟进；\n\n5、数据复盘：人效复盘、次日排班与天气预判。","requirements":"1、学历：大专及以上\n\n2、经验：有配送主管或前置仓管理经验\n\n3、稳定性：意愿长期在本地发展的人\n\n4、素质：责任心强，能独立处理骑手投诉/规模波动","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1、站点日常管理：晨会组织、6S巡查、门前三包、站点文化打造；\n\n2、运力全生命周期：骑手招募入职、新人带训、排班调度、留存关怀；\n\n3、履约与体验保障：客诉/差评处理、异常订单施救、实时数据监控干预；\n\n4、安全与质量：安全事故处理上报、质量监控、满编跟进；\n\n5、数据复盘：人效复盘、次日排班与天气预判。\n\n岗位基本要求\n1、学历：大专及以上\n\n2、经验：有配送主管或前置仓管理经验\n\n3、稳定性：意愿长期在本地发展的人\n\n4、素质：责任心强，能独立处理骑手投诉/规模波动\n\n具备以下条件优先\n有前置仓或自营快递站业务配送管理经验优先\n\n岗位亮点\n全新业务模式，挑战与机遇并存，具备更广阔的发展空间，晋升通道清晰。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4688085010","sourceKey":"meituan_social","company":"美团","title":"温州生产主管","city":"温州市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4688085010&jobShareType=1","duty":"1、负责城市整体仓储和分拣业务运营和管理，共享冻库的管理，商品收货、存储、拣选和分拣等工作，保障履约的稳定；\n2、负责推进仓储和分拣运营标准落地，提升仓储现场标准化水平；\n3、负责仓储和分拣运营质量提升，改善过程品质防护，降低商品损失和品质客诉；\n4、负责仓储和分拣效率优化，提升业务履约能力；\n5、负责城市仓储组织能力建设。","requirements":"1、大专以上学历，3年相关仓储管理工作经验，有冷链物流仓储管理经验更佳；\n2、熟悉仓储管理流程和仓储作业标准，具备良好的计划和组织能力；\n3、较强的沟通协调能力，能够做好城市进向、招商、配送之间的沟通和协作；\n4、有较强的流程思维，能够不断优化和复制成功经验，带领团队不断提升效率和运营能力；\n5、能够适应快节奏的工作环境和业务场景。","description":"部门介绍\n快驴进货是美团旗下的餐饮供应链平台，帮助餐饮商户以更低成本、更高效率来获取安全可靠的食材供应，让餐饮采购更简单。快驴进货同步发展“自营+平台”的业务模式，在采购环节一方面向上游供应商直采大宗商品，另一方面引入各地批发商，助力平台伙伴共同发展；在销售环节既有自建团队进行市场、客户拓展，又帮助各地批发商拓展业务；同时自建仓储管理系统、配送网络与团队，为客户提供优质履约服务。\n截至2022年，快驴进货布局了全国41个城市，为百万家商户提供“全、省、稳、好”的餐饮供应链服务。我们拥有3000+品牌食材、超5万SKU商品、超28万商品资质，并提供源头严审核、食品安全严把关、24小时无忧售后的全面保障，实现手机下单、送货上门的高效采购模式，帮百万商家节省了采购时间与成本，助力平台伙伴共同发展，在万亿市场共享机遇。\n在这里，你将收获完善的员工发展机制及学习体系，与各界专家一起深度参与餐饮供应链业务的发展。欢迎优秀的你加入美团快驴进货，与我们一起成长，一起更好！\n\n岗位职责\n1、负责城市整体仓储和分拣业务运营和管理，共享冻库的管理，商品收货、存储、拣选和分拣等工作，保障履约的稳定；\n2、负责推进仓储和分拣运营标准落地，提升仓储现场标准化水平；\n3、负责仓储和分拣运营质量提升，改善过程品质防护，降低商品损失和品质客诉；\n4、负责仓储和分拣效率优化，提升业务履约能力；\n5、负责城市仓储组织能力建设。\n\n岗位基本要求\n1、大专以上学历，3年相关仓储管理工作经验，有冷链物流仓储管理经验更佳；\n2、熟悉仓储管理流程和仓储作业标准，具备良好的计划和组织能力；\n3、较强的沟通协调能力，能够做好城市进向、招商、配送之间的沟通和协作；\n4、有较强的流程思维，能够不断优化和复制成功经验，带领团队不断提升效率和运营能力；\n5、能够适应快节奏的工作环境和业务场景。\n\n岗位亮点\n1.一线互联网大厂历练的机会，成为电商物流行业复杂业务运营场景下的管理者；\n2.作为供应链路上的关键节点，是业务增长的坚实后盾，也是成本控制和效率提升的核心，有较为广阔的发挥空间。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4688150383","sourceKey":"meituan_social","company":"美团","title":"厦门冻库生产主管","city":"厦门市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4688150383&jobShareType=1","duty":"1. 负责冷链仓储的日常运营管理，确保货物存储、出入库流程符合温控标准。  \n2. 制定并优化冷链仓储作业流程，提升仓储效率与安全性。  \n3. 监督冷链设备的运行状态，协调维护与故障处理，保障冷链不断链。  \n4. 管理仓储团队，安排人员排班与培训，确保操作规范执行到位。  \n5. 配合质量部门完成冷链相关记录与数据整理，支持审计与合规检查。","requirements":"1. 大学专科及以上学历，物流、供应链管理或相关专业优先。  \n2. 具备5年以上仓储管理经验，其中至少2年冷链仓储相关工作经验。  \n3. 熟悉冷链物流操作规范及温控管理要求，了解GSP等相关法规。  \n4. 具备良好的沟通协调能力与团队管理能力，责任心强。","description":"部门介绍\n快驴进货是美团旗下的餐饮供应链平台，帮助餐饮商户以更低成本、更高效率来获取安全可靠的食材供应，让餐饮采购更简单。快驴进货同步发展“自营+平台”的业务模式，在采购环节一方面向上游供应商直采大宗商品，另一方面引入各地批发商，助力平台伙伴共同发展；在销售环节既有自建团队进行市场、客户拓展，又帮助各地批发商拓展业务；同时自建仓储管理系统、配送网络与团队，为客户提供优质履约服务。\n截至2022年，快驴进货布局了全国41个城市，为百万家商户提供“全、省、稳、好”的餐饮供应链服务。我们拥有3000+品牌食材、超5万SKU商品、超28万商品资质，并提供源头严审核、食品安全严把关、24小时无忧售后的全面保障，实现手机下单、送货上门的高效采购模式，帮百万商家节省了采购时间与成本，助力平台伙伴共同发展，在万亿市场共享机遇。\n在这里，你将收获完善的员工发展机制及学习体系，与各界专家一起深度参与餐饮供应链业务的发展。欢迎优秀的你加入美团快驴进货，与我们一起成长，一起更好！\n\n岗位职责\n1. 负责冷链仓储的日常运营管理，确保货物存储、出入库流程符合温控标准。  \n2. 制定并优化冷链仓储作业流程，提升仓储效率与安全性。  \n3. 监督冷链设备的运行状态，协调维护与故障处理，保障冷链不断链。  \n4. 管理仓储团队，安排人员排班与培训，确保操作规范执行到位。  \n5. 配合质量部门完成冷链相关记录与数据整理，支持审计与合规检查。\n\n岗位基本要求\n1. 大学专科及以上学历，物流、供应链管理或相关专业优先。  \n2. 具备5年以上仓储管理经验，其中至少2年冷链仓储相关工作经验。  \n3. 熟悉冷链物流操作规范及温控管理要求，了解GSP等相关法规。  \n4. 具备良好的沟通协调能力与团队管理能力，责任心强。\n\n岗位亮点\n1. 提供完善的冷链专业培训与职业发展通道。  \n2. 工作环境规范，配备先进的冷链仓储设备。  \n3. 团队氛围积极，注重员工成长与工作生活平衡。  \n4. 享受具有竞争力的薪酬福利与绩效奖金。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4799480664","sourceKey":"meituan_social","company":"美团","title":"小象超市-配送主管(青岛)","city":"青岛市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4799480664&jobShareType=1","duty":"1、站点日常管理：晨会组织、6S巡查、门前三包、站点文化打造\n\n2、运力全生命周期：骑手招募入职、新人带训、排班调度、留存关怀\n\n3、履约与体验保障：客诉/差评处理、异常订单施救、实时数据监控干预\n\n4、安全与质量：安全事故处理上报、质量监控、满编跟进\n\n5、数据复盘：人效复盘、次日排班与天气预判","requirements":"1、学历：大专及以上\n\n2、经验：有配送主管或前置仓管理经验\n\n3、稳定性：意愿长期在本地发展的人\n\n4、素质：责任心强，能独立处理骑手投诉/规模波动","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1、站点日常管理：晨会组织、6S巡查、门前三包、站点文化打造\n\n2、运力全生命周期：骑手招募入职、新人带训、排班调度、留存关怀\n\n3、履约与体验保障：客诉/差评处理、异常订单施救、实时数据监控干预\n\n4、安全与质量：安全事故处理上报、质量监控、满编跟进\n\n5、数据复盘：人效复盘、次日排班与天气预判\n\n岗位基本要求\n1、学历：大专及以上\n\n2、经验：有配送主管或前置仓管理经验\n\n3、稳定性：意愿长期在本地发展的人\n\n4、素质：责任心强，能独立处理骑手投诉/规模波动\n\n具备以下条件优先\n有前置仓或自营快递业务配送管理相关经验优先\n\n岗位亮点\n全新业务模式，挑战与机遇并存，具备更广阔的发展空间，晋升通道清晰。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4313567915","sourceKey":"meituan_social","company":"美团","title":"盈亏改善与资源管理","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4313567915&jobShareType=1","duty":"1、销售资源统筹管理：负责本业务线销售资源的盘点、分配与跟踪，建立资源管理台账和使用效率监控机制，确保有限资源向高价值目标聚焦。\n2、资源投放效果评估：对资源投放结果进行系统性复盘，分析投产比与边际效益，持续优化资源分配模型，为后续资源策略提供数据支撑。\n3、盈亏改善与经营健康管理：建立盈亏预警与改善机制，推动合作商经营风险整体水平下降，守住可持续经营底线。","requirements":"1、大学本科及以上学历，3年以上资源管理或盈亏改善相关经验；\n2、熟练掌握数据分析工具（SQL/Python等），具备建立资源管理模型与投放评估体系能力，对AI工具和新技术有较强的学习意愿和探索兴趣；\n3、思维缜密，对细节敏感，具备良好的跨部门沟通协调能力；\n4、有本地生活、O2O平台或快消行业资源管理或盈亏改善经验者优先；接受一定频率的全国范围出差。","description":"部门介绍\n美团核心本地商业-下沉市场发展部于2015年成立，通过招募优质的合作商伙伴并对其业务经营能力、组织能力等赋能，以期为下沉城市提供一站式的本地生活服务。\n下沉市场发展部的业务场景涵盖了外卖餐饮、团购、拼好饭、闪购、医药等多元化的生活服务领域，同时搭建了一套稳定、高效的即时配送网络，为更多本地用户提供品质化、多样化、便捷高效的生活服务体验，为当地商户提供数字化发展机遇、提升数字化水平，为社会创造更多的就地就业机会。\n截至2024年6月，下沉市场发展部已开拓全国4000+县区市，帮助百万商户实现本地生活服务数字化，日订单量突破千万，为数十万名骑手提供就业岗位，让本地生活服务逐渐成长为地方新基建，实现美团“帮助大家吃得更好，生活更好”的使命！\n\n岗位职责\n1、销售资源统筹管理：负责本业务线销售资源的盘点、分配与跟踪，建立资源管理台账和使用效率监控机制，确保有限资源向高价值目标聚焦。\n2、资源投放效果评估：对资源投放结果进行系统性复盘，分析投产比与边际效益，持续优化资源分配模型，为后续资源策略提供数据支撑。\n3、盈亏改善与经营健康管理：建立盈亏预警与改善机制，推动合作商经营风险整体水平下降，守住可持续经营底线。\n\n岗位基本要求\n1、大学本科及以上学历，3年以上资源管理或盈亏改善相关经验；\n2、熟练掌握数据分析工具（SQL/Python等），具备建立资源管理模型与投放评估体系能力，对AI工具和新技术有较强的学习意愿和探索兴趣；\n3、思维缜密，对细节敏感，具备良好的跨部门沟通协调能力；\n4、有本地生活、O2O平台或快消行业资源管理或盈亏改善经验者优先；接受一定频率的全国范围出差。\n\n岗位亮点\n1、深入参与核心业务运营。  \n2、与多部门协作，拓展业务视野与综合能力。  \n3、提供清晰的职业发展路径与成长空间。  \n4、团队氛围开放，鼓励创新与主动担当。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4683854620","sourceKey":"meituan_social","company":"美团","title":"零售物流方案Leader","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4683854620&jobShareType=1","duty":"1. 全面负责零售某一业务线物流财务运营的整体规划及管理。独立带领团队支持业务部门财务流程跑通及落地，优化成本结构、降低结核算风险、提升运营效率；\n2. 对物流行业结算、核算、业财一体化方案具有丰富的经验，能够对团队在仓储、配送、运输、资产租赁及管理相关的结核算流程、系统建设及方案设计给予方向及方法指导。确保团队能力在结核算方案出具、财务风险监控、计费风险管理、运营效率等方面不断提升；\n3. 良好的多部门协同合作能力，能及时识别项目进展风险，提出解决方案，推动项目顺利开展；与各物流、采购部门配合，推动财务系统与物流系统的数据对接与流程优化； \n4. 完善物流及资产财务运营指标体系及监控机制，定期输出财务运营管理分析报告（资金/结算风险、租赁结构优化、折旧策略等），及时发现异常并推动整改，支撑管理层决策。","requirements":"1. 大学本科及以上学历，财务、会计、物流或相关专业背景；\n2. 良好的自驱力、学习力及韧性；有良好的目标感；\n3. 10年以上财务运营或物流财务相关工作经验，具备零售行业背景者优先；\n4. 具备团队管理经验，能够有效带领10人左右团队顺利达成目标； \n5. 曾独立代领团队完成过业财一体化方案、财务信息化方案落地；\n6. 熟悉ERP系统及物流财务流程，具备较强的沟通协调能力、识别与解决问题的能力；\n7. 对AI有一定了解，能够结合AI工具，提升团队效率与工作质量。","description":"部门介绍\n财务平台负责公司整体和各业务层面的财务管理工作，通过建设专业、全面、复合的财务管理能力和与业务经营的紧密结合来支持公司健康发展。目前财务平台拥有财务会计、财务报告、资金管理、税务管理、财务共享、财务系统、规划分析、财务BP和内控内审等主要工作方向。我们的目标是建设业界一流的财务管理能力和经营支持体系，为公司战略的正确落地、投入效率的持续提升、业务价值的不断增长保驾护航。欢迎加入财务平台，携手一起向未来！\n\n岗位职责\n1. 全面负责零售某一业务线物流财务运营的整体规划及管理。独立带领团队支持业务部门财务流程跑通及落地，优化成本结构、降低结核算风险、提升运营效率；\n2. 对物流行业结算、核算、业财一体化方案具有丰富的经验，能够对团队在仓储、配送、运输、资产租赁及管理相关的结核算流程、系统建设及方案设计给予方向及方法指导。确保团队能力在结核算方案出具、财务风险监控、计费风险管理、运营效率等方面不断提升；\n3. 良好的多部门协同合作能力，能及时识别项目进展风险，提出解决方案，推动项目顺利开展；与各物流、采购部门配合，推动财务系统与物流系统的数据对接与流程优化； \n4. 完善物流及资产财务运营指标体系及监控机制，定期输出财务运营管理分析报告（资金/结算风险、租赁结构优化、折旧策略等），及时发现异常并推动整改，支撑管理层决策。\n\n岗位基本要求\n1. 大学本科及以上学历，财务、会计、物流或相关专业背景；\n2. 良好的自驱力、学习力及韧性；有良好的目标感；\n3. 10年以上财务运营或物流财务相关工作经验，具备零售行业背景者优先；\n4. 具备团队管理经验，能够有效带领10人左右团队顺利达成目标； \n5. 曾独立代领团队完成过业财一体化方案、财务信息化方案落地；\n6. 熟悉ERP系统及物流财务流程，具备较强的沟通协调能力、识别与解决问题的能力；\n7. 对AI有一定了解，能够结合AI工具，提升团队效率与工作质量。\n\n具备以下条件优先\n具有互联网行业背景优先；有零售线下店、仓储物流等行业财务管理经验优先；CPA持证或具备四大会计师事务经验优先；有财务系统搭建、财务流程优化经验者优先。\n\n岗位亮点\n1、学习成长机会大：我们拥有众多的业态，在这里，你可以学习到不同复杂业态下的财务解决方案，带给你前所未有的成长速度；\n2、与行业内优秀的人共舞：我们拥有众多国内外知名企业的优秀人士，和优秀的人共事，让自己变得更加优秀；\n3、简单高效的团队氛围：我们注重结果导向，每个人都凭业绩说话，我们尊重专业，努力构造业界的财务标杆，同时，我们更加重视财务在业务中的价值体现。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4780215757","sourceKey":"meituan_social","company":"美团","title":"AI安全工程师/专家","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4780215757&jobShareType=1","duty":"负责企业安全相关的 AI 红蓝对抗能力建设，利用Agent提升攻击模拟、入侵检测、威胁研判和响应处置的自动化与智能化水平。\n1、建设AI驱动的攻击模拟、入侵检测、威胁分析和自动化响应能力。\n2、探索AI在红蓝对抗、漏洞检测、安全运营等场景中的应用与落地。","requirements":"1、具备扎实的信息安全基础，熟悉常见攻防手段，有实际安全防护、安全事件分析或处置经验。\n2、熟悉常见漏洞、攻击手法及检测思路，了解常见安全产品，具备检测策略制定、告警分析及风险处置能力。\n3、对AI for Security有较深入的理解或实践经验，能够结合安全场景设计并落地智能化检测、研判或响应能力。","description":"部门介绍\n基础研发平台是美团的核心技术平台，立足于“零售+科技”的战略定位，通过打造人工智能、大数据、云计算、安全等核心技术能力，以及研发效能平台、企业应用平台等公共服务，为业务提供稳定安全、扩展易用、技术领先的平台技术和产品服务。\n在这里，我们会参与到最前沿的技术研发和探索；能够接触超规模集群、海量数据，挑战高复杂业务场景，有机会与业界一流的工程师一起并肩前行。\n在这里，我们有超强的技术氛围，持续向社区贡献业界实践，加速行业技术发展；我们有完善的互联网学习生态圈，重视底层逻辑和方法论，助力职业生涯的非线性成长。\n真诚地邀请你，和我们一起驱动技术发展，创造行业价值。\n\n岗位职责\n负责企业安全相关的 AI 红蓝对抗能力建设，利用Agent提升攻击模拟、入侵检测、威胁研判和响应处置的自动化与智能化水平。\n1、建设AI驱动的攻击模拟、入侵检测、威胁分析和自动化响应能力。\n2、探索AI在红蓝对抗、漏洞检测、安全运营等场景中的应用与落地。\n\n岗位基本要求\n1、具备扎实的信息安全基础，熟悉常见攻防手段，有实际安全防护、安全事件分析或处置经验。\n2、熟悉常见漏洞、攻击手法及检测思路，了解常见安全产品，具备检测策略制定、告警分析及风险处置能力。\n3、对AI for Security有较深入的理解或实践经验，能够结合安全场景设计并落地智能化检测、研判或响应能力。\n\n岗位亮点\n1、参与前沿AI安全技术研究。\n2、深入理解大模型与生成式AI的安全挑战。  \n3、工作地点覆盖北京、上海，提供灵活办公选择。  \n4、提供具有竞争力的薪酬与完善的职业发展通道。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4139742640","sourceKey":"meituan_social","company":"美团","title":"快乐猴-绍兴门店副店长","city":"绍兴市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4139742640&jobShareType=1","duty":"1、确保公司营运标准高效在门店落地，提升销售与毛利；\n2、理解商圈和用户，据此对门店品类和商品经营方向有清晰的认知，通过品类/商品经营、拉新、营销、门店布局、商品订货、陈列、服务，售后，库存管控等；\n3、管控店内损耗、提升门店人效，优化可控费用（如物料，水电煤等营运费用），达成主要考核KPI；\n4、对内各协同部门的日常高效交互，达成共识，高效执行总部和区域新项目落地；\n5、对外关系的建立维护，如相关政府职能部门（市场管理、消协等）、物业关系，打造协作融洽的合作伙伴。","requirements":"1、具有传统大型零售运营的思维模式，5年以上工作经验，担任过2年以上传统实体零售门店生鲜副店长及以上级别的管理岗,关注客户价值和客户体验;\n2、诚实正直、品行端正、责任心强、肯吃苦、有激情且执行力强，有商人视角；\n3、勇于承担，乐于分享，指导与培养团队各项能力，能够打造高绩效团队，形成阶梯化人才成长模式；\n4、具备建设组织和体系搭建能力，可以制定并落实各环节的流程。\n5、掌握基本的AI工具，具备数字化运营思维，能快速学习并应用AI辅助工具提升工作效率。","description":"部门介绍\n快乐猴是美团自营社区超市，依托自有供应链和门店管理体系，聚焦家庭用户的三餐所需，为消费者提供高质价比的食杂商品。快乐猴以数字化能力与科学品控为基础，不断满足消费者对“省”和“便利”的需求。\n\n岗位职责\n1、确保公司营运标准高效在门店落地，提升销售与毛利；\n2、理解商圈和用户，据此对门店品类和商品经营方向有清晰的认知，通过品类/商品经营、拉新、营销、门店布局、商品订货、陈列、服务，售后，库存管控等；\n3、管控店内损耗、提升门店人效，优化可控费用（如物料，水电煤等营运费用），达成主要考核KPI；\n4、对内各协同部门的日常高效交互，达成共识，高效执行总部和区域新项目落地；\n5、对外关系的建立维护，如相关政府职能部门（市场管理、消协等）、物业关系，打造协作融洽的合作伙伴。\n\n岗位基本要求\n1、具有传统大型零售运营的思维模式，5年以上工作经验，担任过2年以上传统实体零售门店生鲜副店长及以上级别的管理岗,关注客户价值和客户体验;\n2、诚实正直、品行端正、责任心强、肯吃苦、有激情且执行力强，有商人视角；\n3、勇于承担，乐于分享，指导与培养团队各项能力，能够打造高绩效团队，形成阶梯化人才成长模式；\n4、具备建设组织和体系搭建能力，可以制定并落实各环节的流程。\n5、掌握基本的AI工具，具备数字化运营思维，能快速学习并应用AI辅助工具提升工作效率。\n\n具备以下条件优先\n有硬折扣门店店长经验，传统超商连锁门店营运中层管理经验优先。\n\n岗位亮点\n1、创新型重点项目，从0-1，成长空间广阔，共同推动门店高效营运。\n2、AI数据看板、智能补货预测、数字化稽核系统全面赋能，让你用互联网公司的工具做零售管理。告别凭感觉管店，AI数据告诉你哪里出了问题、该怎么改。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4304758495","sourceKey":"meituan_social","company":"美团","title":"快乐猴-北京门店区域中台","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4304758495&jobShareType=1","duty":"1. 人员及效能管理：负责区域员工培训的工作组织与进度跟踪、区域内产能管理工作协同，以及总部效能提升策略、物耗管理等区域内的落地与跟进。\n2. 标准落地及运营：负责门店标准运营落地与运营分析、顾客体验提升与售后管理，以及陈列的执行监督与异常反馈。\n3. 新店筹建支持：负责新店开业期间的排班规划，对接开店PMO, 协同处理开店相关事宜，确保开业阶段的运营秩序。\n4. 负责承接总部销售提升策略的执行跟进，协助门店进行销售异常诊断和机会挖掘并反馈需求，以及作为区域代表配合总部推进试点和调研在门店的执行。","requirements":"1. 大学本科及以上学历，3年以上连锁零售或门店运营相关工作经验。  \n2. 熟悉门店运营流程，具备较强的数据分析与问题解决能力。  \n3. 具备良好的沟通协调能力，能够跨部门推动项目落地。  \n4. 具备较强的责任心与执行力，能适应快节奏工作环境。  \n5. 熟练使用办公软件，有运营系统使用经验者优先。 \n6. 掌握基本的AI工具，使用工具提升工作流程效率。","description":"部门介绍\n快乐猴是美团自营社区超市，依托自有供应链和门店管理体系，聚焦家庭用户的三餐所需，为消费者提供高质价比的食杂商品。快乐猴以数字化能力与科学品控为基础，不断满足消费者对“省”和“便利”的需求。\n\n岗位职责\n1. 人员及效能管理：负责区域员工培训的工作组织与进度跟踪、区域内产能管理工作协同，以及总部效能提升策略、物耗管理等区域内的落地与跟进。\n2. 标准落地及运营：负责门店标准运营落地与运营分析、顾客体验提升与售后管理，以及陈列的执行监督与异常反馈。\n3. 新店筹建支持：负责新店开业期间的排班规划，对接开店PMO, 协同处理开店相关事宜，确保开业阶段的运营秩序。\n4. 负责承接总部销售提升策略的执行跟进，协助门店进行销售异常诊断和机会挖掘并反馈需求，以及作为区域代表配合总部推进试点和调研在门店的执行。\n\n岗位基本要求\n1. 大学本科及以上学历，3年以上连锁零售或门店运营相关工作经验。  \n2. 熟悉门店运营流程，具备较强的数据分析与问题解决能力。  \n3. 具备良好的沟通协调能力，能够跨部门推动项目落地。  \n4. 具备较强的责任心与执行力，能适应快节奏工作环境。  \n5. 熟练使用办公软件，有运营系统使用经验者优先。 \n6. 掌握基本的AI工具，使用工具提升工作流程效率。\n\n岗位亮点\n1. 参与城市级运营体系建设，发挥关键支持作用。  \n2. 与总部及区域团队紧密协作，拓展职业视野。  \n3. 提供数据驱动的运营优化机会，提升专业能力。  \n4. 工作地点位于北京，享受一线城市资源与发展平台。  \n5. 明确的职业发展路径，适合追求运营深度发展的专业人才。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4736433701","sourceKey":"meituan_social","company":"美团","title":"账号安全专家","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4736433701&jobShareType=1","duty":"1、负责企业级账号风险管控体系建设，包括但不限于：风险场景的感知与定义、自动化识别与处置策略链路的设计与实现、团伙持续对抗的运营能力设计与落地、多智能体协同决策框架的开发等。\n2、利用数表/算法/AI等技术（如深度表征学习、图神经网络、序列建模等）进行深度数据挖掘，发现和对抗新型及潜在的风险模式，驱动账户安全的风险解决方案与产品能力的智能化演进。\n3、设计与开发AI驱动的风险指标监控与归因系统，使Agent能够实时感知风险态势变化，并基于强化学习等技术进行策略自优化，建立智能化的事前预警、事中拦截、事后分析闭环。\n4、构建兼顾账号风控安全与用户体验的智能风控系统，利用相关技术（如强化学习、因果推断）平衡风险管控与用户摩擦，设计体验最优的认证、验证及处置流程。","requirements":"1.计算机及相关专业，本科及以上学历，2年以上工作经验。\n2.具备扎实的AI/ML技术基础，对Agent架构、工作流、智能决策有深入理解或强烈的探索热情。有基于Agent/Skill/Prompt工程构建系统的实践经验者更佳。\n3.对账号、端防、流量类数据敏感，有数据分析挖掘能力，善于思考，能够从多项业务指标中梳理出团队重点目标与主攻方向。\n4. 具备优秀的结构化思维能力，能洞察用户痛点并把握问题本质，设计成可切实落地的方案。\n5.责任心强，能够自我驱动，并带动团队取得业务成果。","description":"部门介绍\n基础研发平台是美团的核心技术平台，立足于“零售+科技”的战略定位，通过打造人工智能、大数据、云计算、安全等核心技术能力，以及研发效能平台、企业应用平台等公共服务，为业务提供稳定安全、扩展易用、技术领先的平台技术和产品服务。\n在这里，我们会参与到最前沿的技术研发和探索；能够接触超规模集群、海量数据，挑战高复杂业务场景，有机会与业界一流的工程师一起并肩前行。\n在这里，我们有超强的技术氛围，持续向社区贡献业界实践，加速行业技术发展；我们有完善的互联网学习生态圈，重视底层逻辑和方法论，助力职业生涯的非线性成长。\n真诚地邀请你，和我们一起驱动技术发展，创造行业价值。\n\n岗位职责\n1、负责企业级账号风险管控体系建设，包括但不限于：风险场景的感知与定义、自动化识别与处置策略链路的设计与实现、团伙持续对抗的运营能力设计与落地、多智能体协同决策框架的开发等。\n2、利用数表/算法/AI等技术（如深度表征学习、图神经网络、序列建模等）进行深度数据挖掘，发现和对抗新型及潜在的风险模式，驱动账户安全的风险解决方案与产品能力的智能化演进。\n3、设计与开发AI驱动的风险指标监控与归因系统，使Agent能够实时感知风险态势变化，并基于强化学习等技术进行策略自优化，建立智能化的事前预警、事中拦截、事后分析闭环。\n4、构建兼顾账号风控安全与用户体验的智能风控系统，利用相关技术（如强化学习、因果推断）平衡风险管控与用户摩擦，设计体验最优的认证、验证及处置流程。\n\n岗位基本要求\n1.计算机及相关专业，本科及以上学历，2年以上工作经验。\n2.具备扎实的AI/ML技术基础，对Agent架构、工作流、智能决策有深入理解或强烈的探索热情。有基于Agent/Skill/Prompt工程构建系统的实践经验者更佳。\n3.对账号、端防、流量类数据敏感，有数据分析挖掘能力，善于思考，能够从多项业务指标中梳理出团队重点目标与主攻方向。\n4. 具备优秀的结构化思维能力，能洞察用户痛点并把握问题本质，设计成可切实落地的方案。\n5.责任心强，能够自我驱动，并带动团队取得业务成果。\n\n具备以下条件优先\n1. 有大型互联网平台AI风控、智能对抗、风险治理系统设计和开发经验者优先。\n2. 有与黑产长期进行业务对抗实践者优先。\n3. 在风控、安全领域有机器学习/深度学习算法（如异常检测、图算法、序列模型、强化学习）研发和落地经验者优先。\n\n岗位亮点\n1. 参与定义和建设下一代以AI为核心驱动力的账号风控基础设施，技术成长与业务影响力空间巨大。\n2. 直面高强度的真实业务对抗，在多元复杂场景中实践并创新Agent、AI大模型等前沿技术，极具挑战性与成就感。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4673652343","sourceKey":"meituan_social","company":"美团","title":"美团-校招-27届商户/客户管理培训生","city":"武汉市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4673652343&jobShareType=1","duty":"1.通过一段时间系统化的培养学习，达到独立承担所负责岗位的职责，具备基础的管理能力；\n2.支持优化客户服务系统，提高客户整体满意度；\n3.协助制定业务标准及流程，负责客服团队一线员工的业务辅导和绩效考核；\n4.将理论应用于实践，及时发现业务的痛点，利用数据分析和智能化手段积极主动优化业务流程。","requirements":"1.27届本科及以上学历；\n2.热爱电子商务行业，有较高的耐心和责任心，工作积极主动；\n3.具有较好的组织协调能力和发展潜力，学习能力强；\n4.具有良好的服务意识和自我调整能力；\n5.具有创新意识、问题解决能力和逻辑思维能力。","description":"部门介绍\n美团平台为用户的基础产品体验负责，还承担了美团的用户增长、市场和品牌营销以及多条业务线的产品设计职责，建立了融合文字、图片、视频和直播等不同形式的內容生态系统，同时整合地图服务部、客户服务和体验部、企业业务部、网约车业务部等部门，致力于用科技提升美团数亿消费者、近千万商家、骑手、司机和团长的服务体验。美团平台拥有高并发、多业务的复杂场景，为技术深度优化提供了最佳实践可能。这里有简单、讲逻辑、有爱的团队，更是一块理想的实战场地，舞台广阔，欢迎你来尽情施展。\n\n岗位职责\n1.通过一段时间系统化的培养学习，达到独立承担所负责岗位的职责，具备基础的管理能力；\n2.支持优化客户服务系统，提高客户整体满意度；\n3.协助制定业务标准及流程，负责客服团队一线员工的业务辅导和绩效考核；\n4.将理论应用于实践，及时发现业务的痛点，利用数据分析和智能化手段积极主动优化业务流程。\n\n岗位基本要求\n1.27届本科及以上学历；\n2.热爱电子商务行业，有较高的耐心和责任心，工作积极主动；\n3.具有较好的组织协调能力和发展潜力，学习能力强；\n4.具有良好的服务意识和自我调整能力；\n5.具有创新意识、问题解决能力和逻辑思维能力。\n\n岗位亮点\n1.具有配套的科学培训体系，培养方案系统且专业；\n2.通过在不同业务线的培训学习，可在短期内达到基础管理岗标准；\n3.团队足够优秀，大家一起学习、交流，共同进步和成长；\n4.通过培养方案打造成最适合美团服务体验部的复合型管理人才，形成文化\n认同、潜力出众、跨专业复合型的优秀管理后备人才梯队，更有利于个人职业规划和长期发展。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4136286716","sourceKey":"meituan_social","company":"美团","title":"快乐猴-宁波门店店长","city":"宁波市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4136286716&jobShareType=1","duty":"1、确保公司营运标准高效在门店落地，提升销售与毛利；\n2、理解商圈和用户，据此对门店品类和商品经营方向有清晰的认知，通过品类/商品经营、拉新、营销、门店布局、商品订货、陈列、服务，售后，库存管控等；\n3、管控店内损耗、提升门店人效，优化可控费用（如物料，水电煤等营运费用），达成主要考核KPI；\n4、对内各协同部门的日常高效交互，达成共识，高效执行总部和区域新项目落地；\n5、对外关系的建立维护，如相关政府职能部门（市场管理、消协等）、物业关系，打造协作融洽的合作伙伴；","requirements":"1、具有传统大型零售运营的思维模式，5年以上工作经验，担任过2年以上传统实体零售门店生鲜副店长及以上级别的管理岗,关注客户价值和客户体验;\n2、诚实正直、品行端正、责任心强、肯吃苦、有激情且执行力强，有商人视角；\n3、勇于承担，乐于分享，指导与培养团队各项能力，能够打造高绩效团队，形成阶梯化人才成长模式；\n4、具备建设组织和体系搭建能力，可以制定并落实各环节的流程；\n5、掌握基本的AI工具，具备数字化运营思维，能快速学习并应用AI辅助工具提升工作效率。","description":"部门介绍\n快乐猴是美团自营社区超市，依托自有供应链和门店管理体系，聚焦家庭用户的三餐所需，为消费者提供高质价比的食杂商品。快乐猴以数字化能力与科学品控为基础，不断满足消费者对“省”和“便利”的需求。\n\n岗位职责\n1、确保公司营运标准高效在门店落地，提升销售与毛利；\n2、理解商圈和用户，据此对门店品类和商品经营方向有清晰的认知，通过品类/商品经营、拉新、营销、门店布局、商品订货、陈列、服务，售后，库存管控等；\n3、管控店内损耗、提升门店人效，优化可控费用（如物料，水电煤等营运费用），达成主要考核KPI；\n4、对内各协同部门的日常高效交互，达成共识，高效执行总部和区域新项目落地；\n5、对外关系的建立维护，如相关政府职能部门（市场管理、消协等）、物业关系，打造协作融洽的合作伙伴；\n\n岗位基本要求\n1、具有传统大型零售运营的思维模式，5年以上工作经验，担任过2年以上传统实体零售门店生鲜副店长及以上级别的管理岗,关注客户价值和客户体验;\n2、诚实正直、品行端正、责任心强、肯吃苦、有激情且执行力强，有商人视角；\n3、勇于承担，乐于分享，指导与培养团队各项能力，能够打造高绩效团队，形成阶梯化人才成长模式；\n4、具备建设组织和体系搭建能力，可以制定并落实各环节的流程；\n5、掌握基本的AI工具，具备数字化运营思维，能快速学习并应用AI辅助工具提升工作效率。\n\n具备以下条件优先\n有主流线下硬折扣门店店长经验，传统超商连锁门店营运中层管理经验优先；\n\n岗位亮点\n1、创新型重点项目，从0-1，成长空间广阔，共同推动门店高效营运\n2、AI数据看板、智能补货预测、数字化稽核系统全面赋能，让你用互联网公司的工具做零售管理。告别凭感觉管店，AI数据告诉你哪里出了问题、该怎么改。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3977107438","sourceKey":"meituan_social","company":"美团","title":"（M）美团酒店民宿流程运营","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3977107438&jobShareType=1","duty":"1.负责为酒店民宿业务线产生的用户问题设计服务流程及解决方案，保障用户的服务体验；\n2.负责对酒店民宿客服工作系统提出优化方案，提升客服工作效率；\n3.负责收集整理用户的痛点问题，推动业务前端优化产品形态、推动供给后台提升供给质量。\n4.引入AI工具辅助酒旅服务流程优化，如运用LLM对VOC数据进行智能分类与根因分析，结合AI智能客服能力缩短用户问题解决时长。","requirements":"1.业务熟悉度：熟悉酒店旅行行业的业务形态、用户的下单、履约链路；\n2.流程设计能力：设计过一条业务线的服务流程，或者业务线关键环节上的服务流程；\n3.项目运营能力：主持过服务优化相关的项目，具备协调资源、推进落地的基本运营能力；\n4.数据分析能力：有VOC分析经验、对服务行业通用服务指标（如问题发生率、接通率、问题解决率、服务满意度等）有一定的认知；\n5.工作经验：5年以上酒旅服务相关工作经验；\n6.了解AI智能客服系统运营方法，具备使用ChatGPT/Claude等工具辅助服务SOP设计、流程优化方案撰写的经验。","description":"部门介绍\n美团平台为用户的基础产品体验负责，还承担了美团的用户增长、市场和品牌营销以及多条业务线的产品设计职责，建立了融合文字、图片、视频和直播等不同形式的內容生态系统，同时整合地图服务部、客户服务和体验部、企业业务部、网约车业务部等部门，致力于用科技提升美团数亿消费者、近千万商家、骑手、司机和团长的服务体验。美团平台拥有高并发、多业务的复杂场景，为技术深度优化提供了最佳实践可能。这里有简单、讲逻辑、有爱的团队，更是一块理想的实战场地，舞台广阔，欢迎你来尽情施展。\n\n岗位职责\n1.负责为酒店民宿业务线产生的用户问题设计服务流程及解决方案，保障用户的服务体验；\n2.负责对酒店民宿客服工作系统提出优化方案，提升客服工作效率；\n3.负责收集整理用户的痛点问题，推动业务前端优化产品形态、推动供给后台提升供给质量。\n4.引入AI工具辅助酒旅服务流程优化，如运用LLM对VOC数据进行智能分类与根因分析，结合AI智能客服能力缩短用户问题解决时长。\n\n岗位基本要求\n1.业务熟悉度：熟悉酒店旅行行业的业务形态、用户的下单、履约链路；\n2.流程设计能力：设计过一条业务线的服务流程，或者业务线关键环节上的服务流程；\n3.项目运营能力：主持过服务优化相关的项目，具备协调资源、推进落地的基本运营能力；\n4.数据分析能力：有VOC分析经验、对服务行业通用服务指标（如问题发生率、接通率、问题解决率、服务满意度等）有一定的认知；\n5.工作经验：5年以上酒旅服务相关工作经验；\n6.了解AI智能客服系统运营方法，具备使用ChatGPT/Claude等工具辅助服务SOP设计、流程优化方案撰写的经验。\n\n岗位亮点\n1.有机会主R复杂业务场景中，跨部门重大项目管理工作；\n2.能够纵向了解业务内服务相关的各职能、环节的工作。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4791969513","sourceKey":"meituan_social","company":"美团","title":"物资和设备供应管理","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4791969513&jobShareType=1","duty":"1. 负责供应链计划的制定与优化，确保非商品供应的及时性与准确性。  \n2. 分析进销存数据与库存情况，制定合理的采购计划，降低库存成本并提升周转效率。  \n3. 协同供应商管理团队，优化供应商结构，提升供应链整体响应能力。  \n4. 监控供应链关键指标，识别潜在风险并提出改进方案，持续优化运营流程。  \n5. 支持新业务拓展中的供应链搭建与落地，保障业务顺利推进。","requirements":"1. 大学本科及以上学历，供应链管理、物流管理、工商管理等相关专业优先。  \n2. 具备5年以上供应链计划、采购或相关工作经验，有零售或快消行业背景者优先。  \n3. 熟悉供应链计划流程，具备较强的数据分析能力与逻辑思维能力。  \n4. 具备良好的沟通协调能力，能够跨部门协作推动项目落地。  \n5. 工作责任心强，具备较强的适应能力与问题解决能力。","description":"部门介绍\n美团的使命是“帮大家吃得更好，生活更好”，公司聚焦“零售 + 科技”战略，和广大商户与各类合作伙伴一起，努力为消费者提供品质生活，推动商品零售和服务零售在需求侧和供给侧的数字化转型。\n2018年9月20日，美团正式在港交所挂牌上市。美团将始终坚持以客户为中心，不断加大在科技研发方面的投入，更好承担社会责任，更多创造社会价值，与广大合作伙伴一起发展共赢。\n\n岗位职责\n1. 负责供应链计划的制定与优化，确保非商品供应的及时性与准确性。  \n2. 分析进销存数据与库存情况，制定合理的采购计划，降低库存成本并提升周转效率。  \n3. 协同供应商管理团队，优化供应商结构，提升供应链整体响应能力。  \n4. 监控供应链关键指标，识别潜在风险并提出改进方案，持续优化运营流程。  \n5. 支持新业务拓展中的供应链搭建与落地，保障业务顺利推进。\n\n岗位基本要求\n1. 大学本科及以上学历，供应链管理、物流管理、工商管理等相关专业优先。  \n2. 具备5年以上供应链计划、采购或相关工作经验，有零售或快消行业背景者优先。  \n3. 熟悉供应链计划流程，具备较强的数据分析能力与逻辑思维能力。  \n4. 具备良好的沟通协调能力，能够跨部门协作推动项目落地。  \n5. 工作责任心强，具备较强的适应能力与问题解决能力。\n\n具备以下条件优先\n熟悉零售/电商行业非商品采购（如包材、MRO、设备）者加分\n\n岗位亮点\n1. 加入快速发展的新零售平台，参与核心供应链体系建设。  \n2. 与行业优秀团队共事，获得专业能力提升与职业发展空间。  \n3. 扁平化管理，鼓励创新与主动担当的工作氛围。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4772301145","sourceKey":"meituan_social","company":"美团","title":"鲜猪肉自营采购-北京","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4772301145&jobShareType=1","duty":"1.主要工作：负责鲜猪肉品类的采购，对市场竞争环境和市场行情变动要有敏锐洞察力和行动力；熟悉建立供应商体系；\n2.供给体系搭建：熟悉本地市场鲜肉工厂和一批商资源，对商品结构和供应商体系，根据不同业务场景需求，选择与之匹配的商品结构组合；\n3.资源整合：管理、整合供应商及采购渠道，控制进价并保持零售价的竞争力；\n4.价格管理：根据市场行情，管控进价和售价，并制定肉禽类商品的促销计划以及品类的销售和利润指标，分析城市端鲜肉毛利，进行反馈并追踪结果；\n5.品类毛利管理：及时收集市场资讯，比值论价，通过供应链不断优化达到采购成本的不断优化","requirements":"1.大专及以上学历，具备5年以上采购经验，且有操盘过鲜肉业务3年以上经验；\n2.熟悉采购工作流程，对价格谈判、订单管理、账务处理、供应商开发等具有丰富的经验；\n3.有较强的数据分析能力，熟练掌握计算机操作，业务思路清晰，有计划性及快速执行力；\n4.诚信可靠，工作态度积极，具有良好的人际沟通能力及协调能力；","description":"部门介绍\n快驴进货是美团旗下的餐饮供应链平台，帮助餐饮商户以更低成本、更高效率来获取安全可靠的食材供应，让餐饮采购更简单。快驴进货同步发展“自营+平台”的业务模式，在采购环节一方面向上游供应商直采大宗商品，另一方面引入各地批发商，助力平台伙伴共同发展；在销售环节既有自建团队进行市场、客户拓展，又帮助各地批发商拓展业务；同时自建仓储管理系统、配送网络与团队，为客户提供优质履约服务。\n截至2022年，快驴进货布局了全国41个城市，为百万家商户提供“全、省、稳、好”的餐饮供应链服务。我们拥有3000+品牌食材、超5万SKU商品、超28万商品资质，并提供源头严审核、食品安全严把关、24小时无忧售后的全面保障，实现手机下单、送货上门的高效采购模式，帮百万商家节省了采购时间与成本，助力平台伙伴共同发展，在万亿市场共享机遇。\n在这里，你将收获完善的员工发展机制及学习体系，与各界专家一起深度参与餐饮供应链业务的发展。欢迎优秀的你加入美团快驴进货，与我们一起成长，一起更好！\n\n岗位职责\n1.主要工作：负责鲜猪肉品类的采购，对市场竞争环境和市场行情变动要有敏锐洞察力和行动力；熟悉建立供应商体系；\n2.供给体系搭建：熟悉本地市场鲜肉工厂和一批商资源，对商品结构和供应商体系，根据不同业务场景需求，选择与之匹配的商品结构组合；\n3.资源整合：管理、整合供应商及采购渠道，控制进价并保持零售价的竞争力；\n4.价格管理：根据市场行情，管控进价和售价，并制定肉禽类商品的促销计划以及品类的销售和利润指标，分析城市端鲜肉毛利，进行反馈并追踪结果；\n5.品类毛利管理：及时收集市场资讯，比值论价，通过供应链不断优化达到采购成本的不断优化\n\n岗位基本要求\n1.大专及以上学历，具备5年以上采购经验，且有操盘过鲜肉业务3年以上经验；\n2.熟悉采购工作流程，对价格谈判、订单管理、账务处理、供应商开发等具有丰富的经验；\n3.有较强的数据分析能力，熟练掌握计算机操作，业务思路清晰，有计划性及快速执行力；\n4.诚信可靠，工作态度积极，具有良好的人际沟通能力及协调能力；\n\n岗位亮点\n跨部门沟通协同，鲜猪肉品类专家，供应链资源丰富，有电商经验优先","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4760648645","sourceKey":"meituan_social","company":"美团","title":"产品设计工程师-AI方向","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4760648645&jobShareType=1","duty":"1、负责业务产品模块从需求到上线的完整交付，能定义目标、交付解决方案、指定验收和评估标准。\n2、能用 AI 工具产出产品设计方案、可运行 Demo、可用于生产的前端代码，完成验证与修正，对产物质量负责。\n3、把设计规范、组件资产与判断标准整理成 AI 可用、可检查的形式，编写并维护相关规则、模板与流程。\n4、组织产物的验证与评测，追踪问题根因，推动方案、资产与流程的改进。\n5、沉淀方法、工具与案例，在团队内推广复用。","requirements":"1、本科及以上学历，有产品设计、体验设计或设计工程经验。\n2、有完整的产品或体验设计经验，能从用户和业务目标出发指定解决方案，有设计系统或设计规范建设经验。\n3、熟练使用编码 Agent 或 AI 生成工具，对 AI 的能力边界有自己的理解，有用 AI 产出并落地的作品（页面、Demo、工具或流程）。","description":"部门介绍\n美团平台为用户的基础产品体验负责，还承担了美团的用户增长、市场和品牌营销以及多条业务线的产品设计职责，建立了融合文字、图片、视频和直播等不同形式的內容生态系统，同时整合地图服务部、客户服务和体验部、企业业务部、网约车业务部等部门，致力于用科技提升美团数亿消费者、近千万商家、骑手、司机和团长的服务体验。美团平台拥有高并发、多业务的复杂场景，为技术深度优化提供了最佳实践可能。这里有简单、讲逻辑、有爱的团队，更是一块理想的实战场地，舞台广阔，欢迎你来尽情施展。\n\n岗位职责\n1、负责业务产品模块从需求到上线的完整交付，能定义目标、交付解决方案、指定验收和评估标准。\n2、能用 AI 工具产出产品设计方案、可运行 Demo、可用于生产的前端代码，完成验证与修正，对产物质量负责。\n3、把设计规范、组件资产与判断标准整理成 AI 可用、可检查的形式，编写并维护相关规则、模板与流程。\n4、组织产物的验证与评测，追踪问题根因，推动方案、资产与流程的改进。\n5、沉淀方法、工具与案例，在团队内推广复用。\n\n岗位基本要求\n1、本科及以上学历，有产品设计、体验设计或设计工程经验。\n2、有完整的产品或体验设计经验，能从用户和业务目标出发指定解决方案，有设计系统或设计规范建设经验。\n3、熟练使用编码 Agent 或 AI 生成工具，对 AI 的能力边界有自己的理解，有用 AI 产出并落地的作品（页面、Demo、工具或流程）。\n\n岗位亮点\n实践 AI 产品设计新范式，新型 AI 类综合岗位。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4758073650","sourceKey":"meituan_social","company":"美团","title":"小象超市-商品研发与运营负责人","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4758073650&jobShareType=1","duty":"1、搭建各品类产品研发体系，制定年度/季度新品研发计划与预算，主导品类规划与产品定位；\n2、制定并落地各业态标准化SOP（研发、生产、履约、运营），确保出品口味统一、品质稳定，支持跨平台/跨仓复制；\n3、建立研发小样与规模化批量生产的工艺转化机制，打通研发室打样、供应链整合、测试、上架的完整闭环；\n4、管控产品成本与毛利结构，协同采购、供应链持续优化原料成本，保障产品竞争力与盈利水平；\n5、跟踪市场趋势动态，建立市场调研与口味风向洞察机制，打造差异化爆品，提升商品竞争力。","requirements":"1、线下连锁零售8年以上管理经验，有研发/运营负责人经历，有产品从研发到全国多门店规模化落地的完整经验；\n2、精通所辖核心品类，有一线研发管理经验；\n3、具备SOP标准化体系搭建经验，擅长标准化与成本控制，熟悉食品安全法规；\n4、熟悉相关供应链（原料/包材/设备/动线），有规模化生产或前置仓运营经验；\n5、具备C端产品洞察力和市场竞争分析能力，有打造爆品的成功案例；\n6、具备优秀的跨部门协同与组织管理能力；有英文能力优先。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1、搭建各品类产品研发体系，制定年度/季度新品研发计划与预算，主导品类规划与产品定位；\n2、制定并落地各业态标准化SOP（研发、生产、履约、运营），确保出品口味统一、品质稳定，支持跨平台/跨仓复制；\n3、建立研发小样与规模化批量生产的工艺转化机制，打通研发室打样、供应链整合、测试、上架的完整闭环；\n4、管控产品成本与毛利结构，协同采购、供应链持续优化原料成本，保障产品竞争力与盈利水平；\n5、跟踪市场趋势动态，建立市场调研与口味风向洞察机制，打造差异化爆品，提升商品竞争力。\n\n岗位基本要求\n1、线下连锁零售8年以上管理经验，有研发/运营负责人经历，有产品从研发到全国多门店规模化落地的完整经验；\n2、精通所辖核心品类，有一线研发管理经验；\n3、具备SOP标准化体系搭建经验，擅长标准化与成本控制，熟悉食品安全法规；\n4、熟悉相关供应链（原料/包材/设备/动线），有规模化生产或前置仓运营经验；\n5、具备C端产品洞察力和市场竞争分析能力，有打造爆品的成功案例；\n6、具备优秀的跨部门协同与组织管理能力；有英文能力优先。\n\n具备以下条件优先\n餐饮食品行业英文能力。同时具有餐饮行业与零售行业的产品开发与运营管理经验。\n\n岗位亮点\n创新业务发展具有行业开拓性，新的商业模型与运营模型有机会开创行业标杆。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4753038134","sourceKey":"meituan_social","company":"美团","title":"无人车业务部-嵌入式软件开发工程师/专家","city":"北京市/深圳市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4753038134&jobShareType=1","duty":"1、开发自研域控制器MCU基础软件，包括硬件驱动、复杂驱动、通信协议栈、存储功能栈、系统服务等功能的开发和配置。\n\n2、开发自研域控制器SOC应用软件及设备驱动，以及跨SOC和MCU的处理器间通信。\n\n3、依照开发流程，组织并参与完成软件需求开发、软件架构/单元设计、编码调试、单元测试及软件集成、调试。\n\n4、分析解决测试阶段和实车运行阶段发现的软件问题。\n\n5、开展软件功能安全分析。根据功能安全分析结果完成软件安全需求的开发和实现。\n\n6、开发DV/PV试验软件和生产测试软件。\n\n7、结合业务需求开发软件工具，提升软件开发效率。","requirements":"1、车辆/计算机/电子/通信类本科及以上学历，5年以上汽车电子控制单元软件开发经验。\n\n2、熟悉汽车电子常用MCU的体系架构和外设功能，具有实际项目应用经验。\n\n3、熟悉Linux环境下APP软件及设备驱动的开发，具有实际项目经验。\n\n4、扎实的C/C++语言基础，具备Python、batch file等常用脚本语言应用能力。\n\n5、具备软件架构设计能力和实际项目软件架构设计经验。\n\n6、熟悉AUTOSAR CP软件架构及开发方法论。深入理解常用BSW标准模块的功能及配置参数。具备硬件输入输出抽象（IoHwAb）和复杂驱动（CDD）模块的开发能力。\n\n7、熟悉FreeRTOS等MCU软件常用的实时操作系统。具备多核、多任务软件调度设计和优化能力。\n\n8、熟悉常用车辆通信方式，如CAN、LIN、以太网。熟悉常用通信协议，如UDS、XCP、DoIP、SOME/IP等，有实际项目开发经验。\n\n9、熟悉ASPICE规范，能够完成规范要求的软件开发各环节工作。\n\n10、了解汽车功能安全规范ISO26262，熟悉ISO26262-6中对软件开发的要求，能够开展相关开发工作。\n\n11、熟悉车辆EE架构，能够理解硬件原理和线束原理。\n\n12、熟练使用主流的AI Agent工具（如Claude Code、CodeX等）进行辅助软件编码、数据分析、问题排查等，能将常规工作形成AI Agent可操作的工作流。","description":"部门介绍\n无人车业务部成立于2016年，旨在用无人驾驶技术提升物流配送的效率和体验。美团无人车以自研L4级自动驾驶软硬件技术为核心，与美团即时零售业务结合，形成满足公开道路、社区、工业园区等室外全场景下的无人配送整体解决方案。自2020年起，无人车已在北京、深圳等多地进入常态化试运营阶段，在城市复杂场景下提供针对餐饮外卖、生鲜食杂等货物的即时配送服务。2025年，美团无人车又踏上了同城货运的新探索，并在2026年持续扩大运营范围和车队数量，为更多城市带来智能配送服务。\n欢迎加入美团无人车团队，与我们一起用科技推动即时零售再升级！\n\n岗位职责\n1、开发自研域控制器MCU基础软件，包括硬件驱动、复杂驱动、通信协议栈、存储功能栈、系统服务等功能的开发和配置。\n\n2、开发自研域控制器SOC应用软件及设备驱动，以及跨SOC和MCU的处理器间通信。\n\n3、依照开发流程，组织并参与完成软件需求开发、软件架构/单元设计、编码调试、单元测试及软件集成、调试。\n\n4、分析解决测试阶段和实车运行阶段发现的软件问题。\n\n5、开展软件功能安全分析。根据功能安全分析结果完成软件安全需求的开发和实现。\n\n6、开发DV/PV试验软件和生产测试软件。\n\n7、结合业务需求开发软件工具，提升软件开发效率。\n\n岗位基本要求\n1、车辆/计算机/电子/通信类本科及以上学历，5年以上汽车电子控制单元软件开发经验。\n\n2、熟悉汽车电子常用MCU的体系架构和外设功能，具有实际项目应用经验。\n\n3、熟悉Linux环境下APP软件及设备驱动的开发，具有实际项目经验。\n\n4、扎实的C/C++语言基础，具备Python、batch file等常用脚本语言应用能力。\n\n5、具备软件架构设计能力和实际项目软件架构设计经验。\n\n6、熟悉AUTOSAR CP软件架构及开发方法论。深入理解常用BSW标准模块的功能及配置参数。具备硬件输入输出抽象（IoHwAb）和复杂驱动（CDD）模块的开发能力。\n\n7、熟悉FreeRTOS等MCU软件常用的实时操作系统。具备多核、多任务软件调度设计和优化能力。\n\n8、熟悉常用车辆通信方式，如CAN、LIN、以太网。熟悉常用通信协议，如UDS、XCP、DoIP、SOME/IP等，有实际项目开发经验。\n\n9、熟悉ASPICE规范，能够完成规范要求的软件开发各环节工作。\n\n10、了解汽车功能安全规范ISO26262，熟悉ISO26262-6中对软件开发的要求，能够开展相关开发工作。\n\n11、熟悉车辆EE架构，能够理解硬件原理和线束原理。\n\n12、熟练使用主流的AI Agent工具（如Claude Code、CodeX等）进行辅助软件编码、数据分析、问题排查等，能将常规工作形成AI Agent可操作的工作流。\n\n具备以下条件优先\n1、跨SOC和MCU的软件功能开发经验。\n\n2、完整负责一款控制器软件开发的经历。\n\n3、通过AI Agent显著提高软件开发工作效率的实践经验。\n\n岗位亮点\n1、深度参与L4级自动驾驶车辆核心域控制器软件开发及规模化应用。\n2、开发工作涉及域控制器MCU和SOC两端软件开发，发展空间广阔。\n3、充足的AI Token支持，可充分探索并落地AI辅助嵌入式软件开发。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4713502739","sourceKey":"meituan_social","company":"美团","title":"鲜肉招商大区负责人","city":"广州市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4713502739&jobShareType=1","duty":"岗位定位：承接大区招商策略，负责所辖城市群的货盘规模与商户质量提升，通过精细化运营与一线团队管理，确保业务目标达成。\n\n核心职责：\n\n策略落地与执行：\n\n承接大区制定的货盘及销量目标，将其拆解为城市可执行的行动计划。\n\n深入本地市场，洞察商户经营现状，针对不同品类制定差异化的招商与运营策略。\n\n确保大区策略有效穿透，及时反馈执行过程中的难点与市场变化。\n\n商户运营与管理：\n\n负责所辖区域内商户的招募、培育与分层管理，提升商户活跃度与货盘竞争力。\n\n通过数据分析，精准识别商户增长动因，指导商户优化经营模式，提升转化效率。\n\n维护良好的本地商户生态，解决商户经营中的痛点，提升商户满意度。\n\n团队管理与辅导：\n\n负责一线招商团队的日常管理，包括目标设定、过程监控及绩效评估。\n\n注重团队能力建设，通过实战辅导、案例复盘等方式，提升团队成员的业务专业度与执行力。\n\n营造积极的团队氛围，通过有效的激励机制，提升团队凝聚力与战斗力。\n\n跨部门协同：\n\n与本地销售、物流、客服等部门紧密协作，整合资源，解决业务推进中的跨部门协同问题。\n\n建立高效的沟通机制，确保信息在内部及上下级之间顺畅流转。","requirements":"经验背景：\n\n具备招商、销售或运营管理经验，熟悉本地市场环境及商户运作逻辑。\n\n具备线下零售业和电商品类管理的知识和经营，具备业务的中长期规划能力；\n\n有鲜肉业务运营经验者优先，对3P货盘管理有一定认知。\n\n核心能力：\n\n执行力： 能够将战略目标转化为具体可执行的动作，并确保按时保质完成。\n\n数据敏感度： 善于从数据中发现问题，具备基础的数据分析与复盘能力。\n\n沟通与辅导： 具备良好选用育励汰管理技巧，能够有效管理团队并进行业务辅导。\n\n跨部门协同：具备项目统筹和较好的跨部门沟通能力，能够协调和推进公司各支持部门完成项目落地及后续效率优化；\n\n素质要求：\n\n具备较强的主人翁意识，能够主动承担责任，解决复杂问题。\n\n适应快节奏工作环境，具备较强的适应能力与学习能力。","description":"部门介绍\n快驴进货是美团旗下的餐饮供应链平台，帮助餐饮商户以更低成本、更高效率来获取安全可靠的食材供应，让餐饮采购更简单。快驴进货同步发展“自营+平台”的业务模式，在采购环节一方面向上游供应商直采大宗商品，另一方面引入各地批发商，助力平台伙伴共同发展；在销售环节既有自建团队进行市场、客户拓展，又帮助各地批发商拓展业务；同时自建仓储管理系统、配送网络与团队，为客户提供优质履约服务。\n截至2022年，快驴进货布局了全国41个城市，为百万家商户提供“全、省、稳、好”的餐饮供应链服务。我们拥有3000+品牌食材、超5万SKU商品、超28万商品资质，并提供源头严审核、食品安全严把关、24小时无忧售后的全面保障，实现手机下单、送货上门的高效采购模式，帮百万商家节省了采购时间与成本，助力平台伙伴共同发展，在万亿市场共享机遇。\n在这里，你将收获完善的员工发展机制及学习体系，与各界专家一起深度参与餐饮供应链业务的发展。欢迎优秀的你加入美团快驴进货，与我们一起成长，一起更好！\n\n岗位职责\n岗位定位：承接大区招商策略，负责所辖城市群的货盘规模与商户质量提升，通过精细化运营与一线团队管理，确保业务目标达成。\n\n核心职责：\n\n策略落地与执行：\n\n承接大区制定的货盘及销量目标，将其拆解为城市可执行的行动计划。\n\n深入本地市场，洞察商户经营现状，针对不同品类制定差异化的招商与运营策略。\n\n确保大区策略有效穿透，及时反馈执行过程中的难点与市场变化。\n\n商户运营与管理：\n\n负责所辖区域内商户的招募、培育与分层管理，提升商户活跃度与货盘竞争力。\n\n通过数据分析，精准识别商户增长动因，指导商户优化经营模式，提升转化效率。\n\n维护良好的本地商户生态，解决商户经营中的痛点，提升商户满意度。\n\n团队管理与辅导：\n\n负责一线招商团队的日常管理，包括目标设定、过程监控及绩效评估。\n\n注重团队能力建设，通过实战辅导、案例复盘等方式，提升团队成员的业务专业度与执行力。\n\n营造积极的团队氛围，通过有效的激励机制，提升团队凝聚力与战斗力。\n\n跨部门协同：\n\n与本地销售、物流、客服等部门紧密协作，整合资源，解决业务推进中的跨部门协同问题。\n\n建立高效的沟通机制，确保信息在内部及上下级之间顺畅流转。\n\n岗位基本要求\n经验背景：\n\n具备招商、销售或运营管理经验，熟悉本地市场环境及商户运作逻辑。\n\n具备线下零售业和电商品类管理的知识和经营，具备业务的中长期规划能力；\n\n有鲜肉业务运营经验者优先，对3P货盘管理有一定认知。\n\n核心能力：\n\n执行力： 能够将战略目标转化为具体可执行的动作，并确保按时保质完成。\n\n数据敏感度： 善于从数据中发现问题，具备基础的数据分析与复盘能力。\n\n沟通与辅导： 具备良好选用育励汰管理技巧，能够有效管理团队并进行业务辅导。\n\n跨部门协同：具备项目统筹和较好的跨部门沟通能力，能够协调和推进公司各支持部门完成项目落地及后续效率优化；\n\n素质要求：\n\n具备较强的主人翁意识，能够主动承担责任，解决复杂问题。\n\n适应快节奏工作环境，具备较强的适应能力与学习能力。\n\n岗位亮点\n1.带领团队实现城市餐饮需求全结构经营； \n\n2.熟悉不同商业模式下不同的品类玩法和中长期业务规划；\n\n3.锻炼业务的框架性思维；","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4701029771","sourceKey":"meituan_social","company":"美团","title":"价格策略专家","city":"北京市/广州市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4701029771&jobShareType=1","duty":"岗位职责\n1、负责制定和优化零售价格管理体系，确保价格策略与公司策略及业务发展阶段相匹配，提高价格竞争力和价格合理性；\n2、负责与商品团队密切合作，确保定价策略与商品的品质、定位和市场定位相匹配；\n3、熟练运营AI工具，协同产研团队，灵活运营不同路径，推进价格管理体系和监控体系的系统化建设，提高价格管理的运营效率。","requirements":"1. 5年以上大型零售、电商企业工作经验，具备品类，价格及用户管理经验，商业分析、咨询公司或者业务策略背景优先；\n2. 具备优秀的逻辑框架和策略拆解能力，对数据有较强的洞察和分析能力，对零售核心指标有良好的理解及应用能力；\n3. 熟悉线上线下消费者行为， 业务运营工作、用户调研有一定的经验和认识；熟悉大型零售行业、电商平台运作方式，良好的跨团队的沟通、协调能力；\n4. 掌握基本的AI工具，使用工具提升工作流程效率。","description":"部门介绍\n美团的使命是“帮大家吃得更好，生活更好”，公司聚焦“零售 + 科技”战略，和广大商户与各类合作伙伴一起，努力为消费者提供品质生活，推动商品零售和服务零售在需求侧和供给侧的数字化转型。\n2018年9月20日，美团正式在港交所挂牌上市。美团将始终坚持以客户为中心，不断加大在科技研发方面的投入，更好承担社会责任，更多创造社会价值，与广大合作伙伴一起发展共赢。\n\n岗位职责\n岗位职责\n1、负责制定和优化零售价格管理体系，确保价格策略与公司策略及业务发展阶段相匹配，提高价格竞争力和价格合理性；\n2、负责与商品团队密切合作，确保定价策略与商品的品质、定位和市场定位相匹配；\n3、熟练运营AI工具，协同产研团队，灵活运营不同路径，推进价格管理体系和监控体系的系统化建设，提高价格管理的运营效率。\n\n岗位基本要求\n1. 5年以上大型零售、电商企业工作经验，具备品类，价格及用户管理经验，商业分析、咨询公司或者业务策略背景优先；\n2. 具备优秀的逻辑框架和策略拆解能力，对数据有较强的洞察和分析能力，对零售核心指标有良好的理解及应用能力；\n3. 熟悉线上线下消费者行为， 业务运营工作、用户调研有一定的经验和认识；熟悉大型零售行业、电商平台运作方式，良好的跨团队的沟通、协调能力；\n4. 掌握基本的AI工具，使用工具提升工作流程效率。\n\n岗位亮点\n美团大平台，核心业务线，同时是核心部门，团队成长空间大","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4699195165","sourceKey":"meituan_social","company":"美团","title":"美团充电宝直营-城市经理-西南（base地多城可选）","city":"合肥市/郑州市/南宁市/柳州市/重庆市/贵阳市/昆明市/大理白族自治州","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4699195165&jobShareType=1","duty":"1. 负责所在城市充电宝业务的商户拓展与维护，完成既定合作目标。  \n2. 管理并带领10人以上团队，有带MM机会，制定执行地推计划，提升商户覆盖率与设备使用率。  \n3. 分析区域市场动态，挖掘潜在合作机会，优化商户结构与运营效率。  \n4. 协同产品、运营团队，推动商户端需求落地，提升用户体验与商户满意度。","requirements":"1. 大学本科及以上学历，5年以上业务拓展或地推团队管理经验。  \n2. 熟悉本地生活服务或共享经济行业，具备商户资源者优先。  \n3. 具备较强的团队管理与跨部门协作能力，能承受高强度工作压力。  \n4. 工作地点为北京市、长春市、合肥市、武汉市、广州市、成都市、南京市之一。","description":"部门介绍\n美团充电宝是服务零售中的共享租赁业务，承接美团使命，致力让大家充电更简单。美团充电宝业务以应急充电功能为服务核心，覆盖吃喝玩乐生活全场景。目前，已在全国超过2000多个城市的餐饮、娱乐、机场、地铁、火车站、医院、学校、景区等公共区域及场所提供充电服务，铺设机柜超过百万，有KA、直营、渠道合作商多种业务模式，随时随地保障和满足消费者的充电需求。我们的业务资产数量多、场景多元化，追求精益管理。我们的团队大咖云集，崇尚自主驱动，求真务实。我们正处在快速发展期，规模持续增长，目标是市场规模和利润水平双第一。我们的管理者关注团队每个成员的成长，为每个人提供适合自身发展的机会。广阔天地、大有作为，美团充电宝期待你的加入！\n\n岗位职责\n1. 负责所在城市充电宝业务的商户拓展与维护，完成既定合作目标。  \n2. 管理并带领10人以上团队，有带MM机会，制定执行地推计划，提升商户覆盖率与设备使用率。  \n3. 分析区域市场动态，挖掘潜在合作机会，优化商户结构与运营效率。  \n4. 协同产品、运营团队，推动商户端需求落地，提升用户体验与商户满意度。\n\n岗位基本要求\n1. 大学本科及以上学历，5年以上业务拓展或地推团队管理经验。  \n2. 熟悉本地生活服务或共享经济行业，具备商户资源者优先。  \n3. 具备较强的团队管理与跨部门协作能力，能承受高强度工作压力。  \n4. 工作地点为北京市、长春市、合肥市、武汉市、广州市、成都市、南京市之一。\n\n具备以下条件优先\n拥抱变化，敢想，对AI有一定思考和正在使用AI交互的人\n\n岗位亮点\n1. 加入高速发展的共享充电宝业务，参与城市级市场布局。  \n2. 拥有明确的晋升通道与完善的培训体系，助力个人成长。  \n3. 团队氛围积极，扁平化管理，鼓励创新与结果导向。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4611269812","sourceKey":"meituan_social","company":"美团","title":"Keeta技术-骑手定价补贴算法负责人","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4611269812&jobShareType=1","duty":"1、负责 Keeta 履约算法骑手定价补贴方向，建设面向多国家、多运力结构的骑手定价、补贴、活动和预算分配算法体系。\n2、围绕运力争夺、精细化降本探索等重点场景，设计补贴工具、骑手分层、区域时段策略、动态定价和效果评估机制。\n3、建立补贴增量和 ROI 评估框架，通过因果实验、准实验、分层分析和供需归因判断策略真实收益，避免只看表面接单率或在线骑手数。\n4、推动定价补贴与调度、供需、ETA、产品运营联动，把人工盯盘和经验投放沉淀为可配置、可自动化、可复用的算法工具。\n5、管理和培养骑手定价补贴团队，建立策略评审、预算复盘和跨地区经验迁移机制。","requirements":"1、具备 marketplace pricing、司机或骑手激励、用户增长补贴、智能营销、广告出价、预算分配或动态定价等相关经验之一；有外卖、网约车、本地生活供需平台经验优先。\n2、具备较强商业判断和成本意识，能判断补贴投入的增量、效率、长期副作用和竞争应对价值。\n3、具备扎实的数据分析、因果推断和实验设计能力，能设计策略评估体系并识别选择偏差、溢出效应干扰。\n4、能主动推动跨团队协作，既能和业务负责人讨论策略，也能和算法、工程、产品团队拆解落地路径。\n5、具备较强学习能力，能在多国并行、竞争动作频繁的环境下持续拿结果。","description":"部门介绍\n美团核心本地商业下业务研发平台，基于公司“零售+科技”的战略导向，通过从底层架构到应用系统、从软件到硬件、从传统算法到GenAI的全方位技术研究，以及开发、运维、安全等全流程能力建设，致力于推动美团核心本地商业下需求侧与供给侧的数字化和智能化升级，助力业务实现高质量增长，优化用户使用体验，提升商户经营水平，促进行业生态伙伴关系的持续健康发展。团队秉持务实、自驱、开放以及追求卓越的工程师文化，一方面通过系统和技术体系的持续迭代升级，帮助业务高质量增长；另一方面，密切关注前沿技术趋势变化，积极创新技术能力，为业务未来发展创造新的可能性。期待优秀的你加入我们，在夯实专业、深耕平台的基础上与业务携手同行，一起用技术 “帮大家吃得更好，生活更好”。\n\n岗位职责\n1、负责 Keeta 履约算法骑手定价补贴方向，建设面向多国家、多运力结构的骑手定价、补贴、活动和预算分配算法体系。\n2、围绕运力争夺、精细化降本探索等重点场景，设计补贴工具、骑手分层、区域时段策略、动态定价和效果评估机制。\n3、建立补贴增量和 ROI 评估框架，通过因果实验、准实验、分层分析和供需归因判断策略真实收益，避免只看表面接单率或在线骑手数。\n4、推动定价补贴与调度、供需、ETA、产品运营联动，把人工盯盘和经验投放沉淀为可配置、可自动化、可复用的算法工具。\n5、管理和培养骑手定价补贴团队，建立策略评审、预算复盘和跨地区经验迁移机制。\n\n岗位基本要求\n1、具备 marketplace pricing、司机或骑手激励、用户增长补贴、智能营销、广告出价、预算分配或动态定价等相关经验之一；有外卖、网约车、本地生活供需平台经验优先。\n2、具备较强商业判断和成本意识，能判断补贴投入的增量、效率、长期副作用和竞争应对价值。\n3、具备扎实的数据分析、因果推断和实验设计能力，能设计策略评估体系并识别选择偏差、溢出效应干扰。\n4、能主动推动跨团队协作，既能和业务负责人讨论策略，也能和算法、工程、产品团队拆解落地路径。\n5、具备较强学习能力，能在多国并行、竞争动作频繁的环境下持续拿结果。\n\n具备以下条件优先\n1. 有海外工作经验/生活经验，英语流利，可作为工作语言者优先\n2. 有用户增长、智能营销、广告机制优化经验优先\n\n岗位亮点\n参与建设并见证国际化业务的告诉发展，直接影响业务走向，技术驱动业务进步的成就感","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4797094313","sourceKey":"meituan_social","company":"美团","title":"配送策略运营","city":"科威特城","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4797094313&jobShareType=1","duty":"1、负责配送调度场景的优化和运营，包括订单骑手匹配、压单调度、时间预估调优等，围绕体验、效率、成本等目标设计多目标优化方案，并推动与供需管理、骑手定价补贴、LBS、产品运营等方向的联动。\n2、负责配送范围的规划与优化，包括商户配送范围划定、配送圈层管理、远距离订单治理等，结合城市运力结构与商圈特征，制定差异化配送范围策略，平衡配送时效、履约成本与订单规模增长。\n3、负责 ETA策略的本地化运营与持续调优，包括时间预估准确性提升、ETA 动态校准与骑手履约体验的平衡，通过常态化数据分析与 A/B 测试验证策略效果。\n4、主动使用各种分析方法（策略运营、A/B 测试、数据分析、竞争调研），结合业务认知提出创造性的优化方案，并推动策略从设计到上线的完整闭环。","requirements":"1、本科及以上学历，3年及以上互联网/O2O 相关工作经验，有配送调度、履约策略、运力管理经验优先。\n2、逻辑清晰，对数据敏感，具备扎实的数据分析能力，能熟练运用 SQL 进行分析。\n3、具备复杂问题拆解能力和跨团队协作能力，能与产品、算法、运营等多方协同推动策略落地。\n4、英语可作为工作语言，可接受外派/驻外工作。","description":"部门介绍\nKeeta是全球领先外卖平台美团旗下的独立品牌，肩负着“帮大家吃得更好，生活更好”的使命。依托美团深耕中国市场15年的技术与运营积淀，我们正引领全球餐饮与商品即时配送服务的创新与发展。\n\n自2023年成立以来，Keeta始终扎根社区并创造价值。我们为用户提供可靠的外卖体验，以智慧技术助餐厅提升经营效率，在为骑手拓宽收入来源的同时，也充分提供安全保障措施。基于这份多方共赢、共同成长的理念，我们的业务已从中国香港稳步拓展至中东及巴西，并持续向世界迈进。\n\n岗位职责\n1、负责配送调度场景的优化和运营，包括订单骑手匹配、压单调度、时间预估调优等，围绕体验、效率、成本等目标设计多目标优化方案，并推动与供需管理、骑手定价补贴、LBS、产品运营等方向的联动。\n2、负责配送范围的规划与优化，包括商户配送范围划定、配送圈层管理、远距离订单治理等，结合城市运力结构与商圈特征，制定差异化配送范围策略，平衡配送时效、履约成本与订单规模增长。\n3、负责 ETA策略的本地化运营与持续调优，包括时间预估准确性提升、ETA 动态校准与骑手履约体验的平衡，通过常态化数据分析与 A/B 测试验证策略效果。\n4、主动使用各种分析方法（策略运营、A/B 测试、数据分析、竞争调研），结合业务认知提出创造性的优化方案，并推动策略从设计到上线的完整闭环。\n\n岗位基本要求\n1、本科及以上学历，3年及以上互联网/O2O 相关工作经验，有配送调度、履约策略、运力管理经验优先。\n2、逻辑清晰，对数据敏感，具备扎实的数据分析能力，能熟练运用 SQL 进行分析。\n3、具备复杂问题拆解能力和跨团队协作能力，能与产品、算法、运营等多方协同推动策略落地。\n4、英语可作为工作语言，可接受外派/驻外工作。\n\n岗位亮点\n参与美团战略级出海业务，直接影响业务走向；在国际化环境中与多国背景同事合作，业务快速成长期的高成长空间。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4797137010","sourceKey":"meituan_social","company":"美团","title":"运力产品运营","city":"科威特城","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4797137010&jobShareType=1","duty":"1、负责排班工具的优化与迭代，提升 3PL 运力排班效率与精准度，包括供需评估能力、智能化的排班能力等，确保运力资源的合理分配。\n2、骑手活动的设计与改造，围绕运力模式目标设计补贴玩法，并持续迭代补贴策略，提升骑手供给规模与履约稳定性。\n3、多运力模式的孵化，包括服务标准更高（履约质量、稳定性）的高端运力模式，以及成本更优的低价运力模式，在体验与成本之间构建多元化的运力供给组合。\n4、通过数据分析、A/B 测试、竞争调研，评估各运力模式与活动策略对核心指标（ATA、C准、履约成本、骑手供给）的影响，推动有效方案的规模化复制。","requirements":"1、本科及以上学历，3年及以上互联网/O2O 相关工作经验，有运力管理、排班运营、3PL/物流供应商管理、骑手活动运营经验优先。\n2、对数据敏感，具备扎实的数据分析和实验设计能力，能熟练运用 SQL，会 Python 者优先。\n3、具备商务合作意识与业务判断力，能与合作方共创共赢方案并拿到结果。\n4、具备良好的跨团队沟通能力，英语可作为工作语言，可接受外派/驻外工作。","description":"部门介绍\nKeeta是全球领先外卖平台美团旗下的独立品牌，肩负着“帮大家吃得更好，生活更好”的使命。依托美团深耕中国市场15年的技术与运营积淀，我们正引领全球餐饮与商品即时配送服务的创新与发展。\n\n自2023年成立以来，Keeta始终扎根社区并创造价值。我们为用户提供可靠的外卖体验，以智慧技术助餐厅提升经营效率，在为骑手拓宽收入来源的同时，也充分提供安全保障措施。基于这份多方共赢、共同成长的理念，我们的业务已从中国香港稳步拓展至中东及巴西，并持续向世界迈进。\n\n岗位职责\n1、负责排班工具的优化与迭代，提升 3PL 运力排班效率与精准度，包括供需评估能力、智能化的排班能力等，确保运力资源的合理分配。\n2、骑手活动的设计与改造，围绕运力模式目标设计补贴玩法，并持续迭代补贴策略，提升骑手供给规模与履约稳定性。\n3、多运力模式的孵化，包括服务标准更高（履约质量、稳定性）的高端运力模式，以及成本更优的低价运力模式，在体验与成本之间构建多元化的运力供给组合。\n4、通过数据分析、A/B 测试、竞争调研，评估各运力模式与活动策略对核心指标（ATA、C准、履约成本、骑手供给）的影响，推动有效方案的规模化复制。\n\n岗位基本要求\n1、本科及以上学历，3年及以上互联网/O2O 相关工作经验，有运力管理、排班运营、3PL/物流供应商管理、骑手活动运营经验优先。\n2、对数据敏感，具备扎实的数据分析和实验设计能力，能熟练运用 SQL，会 Python 者优先。\n3、具备商务合作意识与业务判断力，能与合作方共创共赢方案并拿到结果。\n4、具备良好的跨团队沟通能力，英语可作为工作语言，可接受外派/驻外工作。\n\n岗位亮点\n1、本科及以上学历，3年及以上互联网/O2O 相关工作经验，有运力管理、排班运营、3PL/物流供应商管理、骑手活动运营经验优先。\n2、对数据敏感，具备扎实的数据分析和实验设计能力，能熟练运用 SQL，会 Python 者优先。\n3、具备商务合作意识与业务判断力，能与合作方共创共赢方案并拿到结果。\n4、具备良好的跨团队沟通能力，英语可作为工作语言，可接受外派/驻外工作。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4687174105","sourceKey":"meituan_social","company":"美团","title":"PC 加工仓主管--广州","city":"广州市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4687174105&jobShareType=1","duty":"1. 负责加工仓日常生产运营的组织与协调，确保生产计划按时完成。  \n2. 管理并指导100人团队，提升团队工作效率与作业规范性。  \n3. 监控生产流程，优化作业标准，降低损耗并提高产能。  \n4. 落实安全生产制度，确保工作环境符合安全及合规要求。  \n5. 对接仓储、物流及相关部门，保障物料供应与成品出库顺畅。","requirements":"1. 大学专科及以上学历，物流、仓储、供应链管理等相关专业优先。  \n2. 具备3年以上仓储或生产管理经验，有团队管理背景。  \n3. 熟悉生鲜果蔬加工仓作业流程及现场管理，具备较强的组织协调能力。  \n4. 具备良好的沟通能力和执行力，能承受一定工作压力。  \n5. 熟练使用办公软件，能够独立完成数据分析及解读。\n6.有净菜生产管理经验优先。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1. 负责加工仓日常生产运营的组织与协调，确保生产计划按时完成。  \n2. 管理并指导100人团队，提升团队工作效率与作业规范性。  \n3. 监控生产流程，优化作业标准，降低损耗并提高产能。  \n4. 落实安全生产制度，确保工作环境符合安全及合规要求。  \n5. 对接仓储、物流及相关部门，保障物料供应与成品出库顺畅。\n\n岗位基本要求\n1. 大学专科及以上学历，物流、仓储、供应链管理等相关专业优先。  \n2. 具备3年以上仓储或生产管理经验，有团队管理背景。  \n3. 熟悉生鲜果蔬加工仓作业流程及现场管理，具备较强的组织协调能力。  \n4. 具备良好的沟通能力和执行力，能承受一定工作压力。  \n5. 熟练使用办公软件，能够独立完成数据分析及解读。\n6.有净菜生产管理经验优先。\n\n岗位亮点\n1. 提供完善的培训体系与职业发展通道。  \n2.业务处于快速发展期，管理挑战与成长空间并存。  \n3. 公司重视基层管理人才培养，晋升机制透明。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4793141543","sourceKey":"meituan_social","company":"美团","title":"PC加工主管岗位","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4793141543&jobShareType=1","duty":"1. 负责PC加工车间的日常运营管理，确保生产计划按时完成。  \n2. 组织并协调20人团队的工作安排，监督加工流程的质量与效率。  \n3. 制定并优化PC加工工艺标准，推动生产流程持续改进。  \n4. 负责团队培训与绩效考核，提升员工技能与工作积极性。  \n5. 配合仓储与物流部门，保障原材料供应与成品出库顺畅。","requirements":"1. 大学专科及以上学历，物流、仓储、制造或相关专业优先。  \n2. 具备5年以上PC加工或相关制造行业工作经验。  \n3. 熟悉PC加工流程及质量控制标准，具备现场管理能力。  \n4. 具备良好的沟通协调能力与团队管理经验，能带领20人团队高效运作。  \n5. 工作认真负责，具备较强的业务能力与问题解决能力。","description":"部门介绍\n快驴进货是美团旗下的餐饮供应链平台，帮助餐饮商户以更低成本、更高效率来获取安全可靠的食材供应，让餐饮采购更简单。快驴进货同步发展“自营+平台”的业务模式，在采购环节一方面向上游供应商直采大宗商品，另一方面引入各地批发商，助力平台伙伴共同发展；在销售环节既有自建团队进行市场、客户拓展，又帮助各地批发商拓展业务；同时自建仓储管理系统、配送网络与团队，为客户提供优质履约服务。\n截至2022年，快驴进货布局了全国41个城市，为百万家商户提供“全、省、稳、好”的餐饮供应链服务。我们拥有3000+品牌食材、超5万SKU商品、超28万商品资质，并提供源头严审核、食品安全严把关、24小时无忧售后的全面保障，实现手机下单、送货上门的高效采购模式，帮百万商家节省了采购时间与成本，助力平台伙伴共同发展，在万亿市场共享机遇。\n在这里，你将收获完善的员工发展机制及学习体系，与各界专家一起深度参与餐饮供应链业务的发展。欢迎优秀的你加入美团快驴进货，与我们一起成长，一起更好！\n\n岗位职责\n1. 负责PC加工车间的日常运营管理，确保生产计划按时完成。  \n2. 组织并协调20人团队的工作安排，监督加工流程的质量与效率。  \n3. 制定并优化PC加工工艺标准，推动生产流程持续改进。  \n4. 负责团队培训与绩效考核，提升员工技能与工作积极性。  \n5. 配合仓储与物流部门，保障原材料供应与成品出库顺畅。\n\n岗位基本要求\n1. 大学专科及以上学历，物流、仓储、制造或相关专业优先。  \n2. 具备5年以上PC加工或相关制造行业工作经验。  \n3. 熟悉PC加工流程及质量控制标准，具备现场管理能力。  \n4. 具备良好的沟通协调能力与团队管理经验，能带领20人团队高效运作。  \n5. 工作认真负责，具备较强的业务能力与问题解决能力。\n\n岗位亮点\n1. 工作地点位于北京市，交通便利，办公环境优良。  \n2. 提供完善的培训体系与职业发展通道。  \n3. 团队氛围积极，注重员工成长与激励机制。  \n4. 岗位稳定性高，享有具有竞争力的薪酬福利。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4786652979","sourceKey":"meituan_social","company":"美团","title":"快乐猴仓店品控 - 厦门","city":"厦门市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4786652979&jobShareType=1","duty":"1. 负责厦门市区域内商品品质管理体系的建立与优化，确保供应链各环节符合公司标准。  \n2. 组织开展大仓质检、门店巡检、抽检及问题整改跟进，推动供应商质量提升。 \n3.搭建并管理食品快检实验室，制定检测计划，每日开展检测。 \n4. 协调跨部门资源，处理重大质量投诉与突发事件，制定预防措施并推动落地。","requirements":"1. 大学本科及以上学历，质量管理、供应链管理、食品科学或相关专业优先。  \n2. 具备5年以上商品或供应链品质管理经验，有快消品或零售行业背景者优先。  \n3. 熟悉ISO质量管理体系及国家相关法规，具备较强的数据分析与问题解决能力。  \n4. 具备优秀的沟通协调能力与团队管理经验，能独立承担区域品控工作。","description":"部门介绍\n快乐猴是美团自营社区超市，依托自有供应链和门店管理体系，聚焦家庭用户的三餐所需，为消费者提供高质价比的食杂商品。快乐猴以数字化能力与科学品控为基础，不断满足消费者对“省”和“便利”的需求。\n\n岗位职责\n1. 负责厦门市区域内商品品质管理体系的建立与优化，确保供应链各环节符合公司标准。  \n2. 组织开展大仓质检、门店巡检、抽检及问题整改跟进，推动供应商质量提升。 \n3.搭建并管理食品快检实验室，制定检测计划，每日开展检测。 \n4. 协调跨部门资源，处理重大质量投诉与突发事件，制定预防措施并推动落地。\n\n岗位基本要求\n1. 大学本科及以上学历，质量管理、供应链管理、食品科学或相关专业优先。  \n2. 具备5年以上商品或供应链品质管理经验，有快消品或零售行业背景者优先。  \n3. 熟悉ISO质量管理体系及国家相关法规，具备较强的数据分析与问题解决能力。  \n4. 具备优秀的沟通协调能力与团队管理经验，能独立承担区域品控工作。\n\n岗位亮点\n1. 工作地点位于厦门，享受灵活高效的工作氛围与成长空间。  \n2. 提供具有竞争力的薪酬福利与清晰的职业发展路径。  \n3. 与行业资深团队共事，积累跨区域、多品类的品质管理经验。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4786596504","sourceKey":"meituan_social","company":"美团","title":"快乐猴仓店品控 - 成都","city":"成都市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4786596504&jobShareType=1","duty":"1. 负责成都市区域内商品品质管理体系的建立与优化，确保供应链各环节符合公司标准。  \n2. 组织开展大仓质检、门店巡检、抽检及问题整改跟进，推动供应商质量提升。 \n3.搭建并管理食品快检实验室，制定检测计划，每日开展检测。 \n4. 协调跨部门资源，处理重大质量投诉与突发事件，制定预防措施并推动落地。","requirements":"1. 大学本科及以上学历，质量管理、供应链管理、食品科学或相关专业优先。  \n2. 具备5年以上商品或供应链品质管理经验，有快消品或零售行业背景者优先。  \n3. 熟悉ISO质量管理体系及国家相关法规，具备较强的数据分析与问题解决能力。  \n4. 具备优秀的沟通协调能力与团队管理经验，能独立承担区域品控工作。","description":"部门介绍\n快乐猴是美团自营社区超市，依托自有供应链和门店管理体系，聚焦家庭用户的三餐所需，为消费者提供高质价比的食杂商品。快乐猴以数字化能力与科学品控为基础，不断满足消费者对“省”和“便利”的需求。\n\n岗位职责\n1. 负责成都市区域内商品品质管理体系的建立与优化，确保供应链各环节符合公司标准。  \n2. 组织开展大仓质检、门店巡检、抽检及问题整改跟进，推动供应商质量提升。 \n3.搭建并管理食品快检实验室，制定检测计划，每日开展检测。 \n4. 协调跨部门资源，处理重大质量投诉与突发事件，制定预防措施并推动落地。\n\n岗位基本要求\n1. 大学本科及以上学历，质量管理、供应链管理、食品科学或相关专业优先。  \n2. 具备5年以上商品或供应链品质管理经验，有快消品或零售行业背景者优先。  \n3. 熟悉ISO质量管理体系及国家相关法规，具备较强的数据分析与问题解决能力。  \n4. 具备优秀的沟通协调能力与团队管理经验，能独立承担区域品控工作。\n\n岗位亮点\n1. 工作地点位于成都，享受灵活高效的工作氛围与成长空间。  \n2. 提供具有竞争力的薪酬福利与清晰的职业发展路径。  \n3. 与行业资深团队共事，积累跨区域、多品类的品质管理经验。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4787189649","sourceKey":"meituan_social","company":"美团","title":"小象超市-杭州PC运营主管","city":"杭州市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4787189649&jobShareType=1","duty":"1、负责排产、出勤计划执行，加工进度管控，每日订单达成；\n2、负责加工过程中人员组台、品类拆分、加工数据分析、异常协调等；\n3、负责商品品质提升和工艺改善；\n4、保证部门各项指标达成（人效、客诉、产成、履约率等）；\n5、负责运营和质检板块业务管理和流程改善。","requirements":"1. 背景：有数据分析、数据运营相关工作经验，有生鲜加工和物流仓储经验优先；\n2. 专业技能：熟练使用办公软件，有POWER BI、VBA、SQL经验及熟悉AI办公优先；\n3. 综合：逻辑清晰、责任心强、较好沟通能力、有项目管理相关经验优先。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1、负责排产、出勤计划执行，加工进度管控，每日订单达成；\n2、负责加工过程中人员组台、品类拆分、加工数据分析、异常协调等；\n3、负责商品品质提升和工艺改善；\n4、保证部门各项指标达成（人效、客诉、产成、履约率等）；\n5、负责运营和质检板块业务管理和流程改善。\n\n岗位基本要求\n1. 背景：有数据分析、数据运营相关工作经验，有生鲜加工和物流仓储经验优先；\n2. 专业技能：熟练使用办公软件，有POWER BI、VBA、SQL经验及熟悉AI办公优先；\n3. 综合：逻辑清晰、责任心强、较好沟通能力、有项目管理相关经验优先。\n\n具备以下条件优先\n1、熟练使用数据分析软件，对数据敏感度高；\n2、生鲜加工和物流仓储相关工作经验；\n3、具备项目管理相关经验。\n\n岗位亮点\n1、公司业务快速发展，个人发展和成长空间大；\n2、平台学习资源多样，个人历练机会多多。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4691924464","sourceKey":"meituan_social","company":"美团","title":"2027秋招-Account Management Associate","city":"迪拜","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4691924464&jobShareType=1","duty":"As an Account Management Associate, you’ll support the management and growth of some of Keeta’s largest restaurant partners, including leading QSR groups and multinational F&B brands.\n\nYou’ll work closely with Account Managers and cross-functional teams to understand partner performance, identify growth opportunities, support key commercial initiatives, and help deliver a strong experience for both our restaurant partners and customers.\n\nThis is a great opportunity for a fresh graduate who is commercially minded, analytical, and interested in building a career in strategic account management, e-commerce, or the food delivery industry.\n\nWhat You’ll Do\n\n1. Support Strategic Partner Management: Work closely with leading QSR groups and multinational restaurant brands, supporting day-to-day account management and helping build strong, long-term partnerships.\n\n2. Identify Growth Opportunities: Analyze account performance, identify opportunities to improve sales and operational performance, and support the development of initiatives that drive partner growth.\n\n3. Support Key Commercial Projects: Contribute to high-priority projects such as new brand launches, restaurant expansion, promotional campaigns, exclusive initiatives, and strategic partnerships.\n\n4. Work Across Teams: Collaborate with Marketing, Operations, Product, Finance, and other teams to coordinate resources, solve partner challenges, and execute commercial initiatives.\n\n5. Develop Market & Business Insights: Build an understanding of the F&B and food delivery landscape, monitor industry trends, and contribute ideas that improve partner and customer experience.","requirements":"What We’re Looking For\nRecent graduate or final-year student in Business, Marketing, Economics, Management, Finance, or a related field\nStrong commercial awareness and interest in how businesses grow\nGood analytical and problem-solving skills, with confidence working with data\nStrong communication and stakeholder management skills\nProactive, curious, and comfortable working in a fast-paced environment\nStrong ownership mindset and willingness to learn\nFluent in spoken and written English\nArabic language skills are a plus.\nPrevious internship, university project, or extracurricular experience in account management, consulting, sales, e-commerce, F&B, or a related area is an advantage, but not required","description":"部门介绍\nKeeta是全球领先外卖平台美团旗下的独立品牌，肩负着“帮大家吃得更好，生活更好”的使命。依托美团深耕中国市场15年的技术与运营积淀，我们正引领全球餐饮与商品即时配送服务的创新与发展。\n\n自2023年成立以来，Keeta始终扎根社区并创造价值。我们为用户提供可靠的外卖体验，以智慧技术助餐厅提升经营效率，在为骑手拓宽收入来源的同时，也充分提供安全保障措施。基于这份多方共赢、共同成长的理念，我们的业务已从中国香港稳步拓展至中东及巴西，并持续向世界迈进。\n\n岗位职责\nAs an Account Management Associate, you’ll support the management and growth of some of Keeta’s largest restaurant partners, including leading QSR groups and multinational F&B brands.\n\nYou’ll work closely with Account Managers and cross-functional teams to understand partner performance, identify growth opportunities, support key commercial initiatives, and help deliver a strong experience for both our restaurant partners and customers.\n\nThis is a great opportunity for a fresh graduate who is commercially minded, analytical, and interested in building a career in strategic account management, e-commerce, or the food delivery industry.\n\nWhat You’ll Do\n\n1. Support Strategic Partner Management: Work closely with leading QSR groups and multinational restaurant brands, supporting day-to-day account management and helping build strong, long-term partnerships.\n\n2. Identify Growth Opportunities: Analyze account performance, identify opportunities to improve sales and operational performance, and support the development of initiatives that drive partner growth.\n\n3. Support Key Commercial Projects: Contribute to high-priority projects such as new brand launches, restaurant expansion, promotional campaigns, exclusive initiatives, and strategic partnerships.\n\n4. Work Across Teams: Collaborate with Marketing, Operations, Product, Finance, and other teams to coordinate resources, solve partner challenges, and execute commercial initiatives.\n\n5. Develop Market & Business Insights: Build an understanding of the F&B and food delivery landscape, monitor industry trends, and contribute ideas that improve partner and customer experience.\n\n岗位基本要求\nWhat We’re Looking For\nRecent graduate or final-year student in Business, Marketing, Economics, Management, Finance, or a related field\nStrong commercial awareness and interest in how businesses grow\nGood analytical and problem-solving skills, with confidence working with data\nStrong communication and stakeholder management skills\nProactive, curious, and comfortable working in a fast-paced environment\nStrong ownership mindset and willingness to learn\nFluent in spoken and written English\nArabic language skills are a plus.\nPrevious internship, university project, or extracurricular experience in account management, consulting, sales, e-commerce, F&B, or a related area is an advantage, but not required\n\n岗位亮点\nWhy Join Keeta?\nGain hands-on exposure to some of the region’s leading QSR groups and multinational restaurant brands\nLearn how strategic commercial partnerships are managed and grown\nWork on real business challenges and high-impact projects from the start\nCollaborate with teams across Commercial, Marketing, Operations, Product, and Finance\nBuild practical experience in one of the region’s fastest-moving industries\nWork in an international and entrepreneurial environment with colleagues from diverse backgrounds","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4796300968","sourceKey":"meituan_social","company":"美团","title":"PC大连仓主管","city":"大连市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4796300968&jobShareType=1","duty":"1，负责PC加工仓整体运营管理；\n\n2，主导所管辖的加工中心严格执行公司生鲜质量标准，通过对入水口原料质检管控及成品的良品率达成，确保最终交付商品质量水平；\n\n3，执行总部中台制定的各项SOP，确保团队跟进所属加工中心的现场流程标准化执行落地；\n\n4，承担所属加工仓的成本优化责任，带领团队对加工现场流程进行优化思考，提出并落地优化方案，提升人工效率/标准化运营/安全操作/6S等多方面运营水平，实现人效/安全/作业环境的提升和相关指标达成，提供优化方案，反馈并建议给到总部中台进行落地改善；\n\n5，带领团队执行包材、耗材、周转物资及固资采购和运营策略落地，对进/出/存等环节进行系统及操作管控，按时并高质量执行盘点动作，确保公司所属物资的库存准确和运营供给平稳；\n\n6，带领团队明确各级劳务人员工作内容和分工，做到及时有效的员工培训，提升一线员工留存；\n\n7，培养所属加工仓的自有人员运营团队的组建/管理/培养，形成稳定和体系化的人才梯队管理，持续培养运营人才并向组织内输出；","requirements":"1，具有5年以上团队管理经验，具备较强的团队管理能力与沟通协调能力，以及强大的执行推进能力；\n\n2，责任心强，专注细节，勇于持续改善并寻求更好解决方法；\n\n3，熟悉使用各类电脑办公软件，具备良好的数据分析能力，能熟练操作办公软件；\n\n4，具备较强数据分析能力，并能正确地落实到工作中；","description":"部门介绍\n快驴进货是美团旗下的餐饮供应链平台，帮助餐饮商户以更低成本、更高效率来获取安全可靠的食材供应，让餐饮采购更简单。快驴进货同步发展“自营+平台”的业务模式，在采购环节一方面向上游供应商直采大宗商品，另一方面引入各地批发商，助力平台伙伴共同发展；在销售环节既有自建团队进行市场、客户拓展，又帮助各地批发商拓展业务；同时自建仓储管理系统、配送网络与团队，为客户提供优质履约服务。\n截至2022年，快驴进货布局了全国41个城市，为百万家商户提供“全、省、稳、好”的餐饮供应链服务。我们拥有3000+品牌食材、超5万SKU商品、超28万商品资质，并提供源头严审核、食品安全严把关、24小时无忧售后的全面保障，实现手机下单、送货上门的高效采购模式，帮百万商家节省了采购时间与成本，助力平台伙伴共同发展，在万亿市场共享机遇。\n在这里，你将收获完善的员工发展机制及学习体系，与各界专家一起深度参与餐饮供应链业务的发展。欢迎优秀的你加入美团快驴进货，与我们一起成长，一起更好！\n\n岗位职责\n1，负责PC加工仓整体运营管理；\n\n2，主导所管辖的加工中心严格执行公司生鲜质量标准，通过对入水口原料质检管控及成品的良品率达成，确保最终交付商品质量水平；\n\n3，执行总部中台制定的各项SOP，确保团队跟进所属加工中心的现场流程标准化执行落地；\n\n4，承担所属加工仓的成本优化责任，带领团队对加工现场流程进行优化思考，提出并落地优化方案，提升人工效率/标准化运营/安全操作/6S等多方面运营水平，实现人效/安全/作业环境的提升和相关指标达成，提供优化方案，反馈并建议给到总部中台进行落地改善；\n\n5，带领团队执行包材、耗材、周转物资及固资采购和运营策略落地，对进/出/存等环节进行系统及操作管控，按时并高质量执行盘点动作，确保公司所属物资的库存准确和运营供给平稳；\n\n6，带领团队明确各级劳务人员工作内容和分工，做到及时有效的员工培训，提升一线员工留存；\n\n7，培养所属加工仓的自有人员运营团队的组建/管理/培养，形成稳定和体系化的人才梯队管理，持续培养运营人才并向组织内输出；\n\n岗位基本要求\n1，具有5年以上团队管理经验，具备较强的团队管理能力与沟通协调能力，以及强大的执行推进能力；\n\n2，责任心强，专注细节，勇于持续改善并寻求更好解决方法；\n\n3，熟悉使用各类电脑办公软件，具备良好的数据分析能力，能熟练操作办公软件；\n\n4，具备较强数据分析能力，并能正确地落实到工作中；\n\n具备以下条件优先\n1，具备加工中心及相关行业的管理经验；\n\n2，5年以上食品制造或生鲜加工行业运营管理的经验，熟悉生鲜行业B2B\\B2C模式，熟悉生鲜生产的作业流程；\n\n4，具备生鲜类商品相关知识(蔬果、熟食、水产、海鲜类、肉类、禽类等)，食品类相关专业优先考虑；\n\n岗位亮点\n生鲜加工行业，具备较好的行业发展前景，生鲜供应链体系中重要环节","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4760895105","sourceKey":"meituan_social","company":"美团","title":"快乐猴工程经理","city":"厦门市/广州市/成都市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4760895105&jobShareType=1","duty":"1. 负责快乐猴品牌门店的工程营建项目整体规划、实施与交付，确保项目按时保质完成。  \n2. 统筹门店装修、机电、消防等工程环节，协调设计、施工及供应商资源，控制成本与进度。  \n3. 建立并优化工程营建标准流程与规范，提升门店建设效率与品质一致性。  \n4. 支持新店选址评估，提供工程技术可行性分析与建议。","requirements":"1. 大学本科及以上学历，建筑、工程管理、土木工程等相关专业优先。  \n2. 具备3年以上连锁零售或餐饮行业工程营建管理经验，有完整项目落地经验。  \n3. 熟悉装修施工流程、材料标准及国家相关法规，具备较强的现场管理能力。  \n4. 具备良好的沟通协调能力与沟通能力，能适应阶段性出差。","description":"部门介绍\n快乐猴是美团自营社区超市，依托自有供应链和门店管理体系，聚焦家庭用户的三餐所需，为消费者提供高质价比的食杂商品。快乐猴以数字化能力与科学品控为基础，不断满足消费者对“省”和“便利”的需求。\n\n岗位职责\n1. 负责快乐猴品牌门店的工程营建项目整体规划、实施与交付，确保项目按时保质完成。  \n2. 统筹门店装修、机电、消防等工程环节，协调设计、施工及供应商资源，控制成本与进度。  \n3. 建立并优化工程营建标准流程与规范，提升门店建设效率与品质一致性。  \n4. 支持新店选址评估，提供工程技术可行性分析与建议。\n\n岗位基本要求\n1. 大学本科及以上学历，建筑、工程管理、土木工程等相关专业优先。  \n2. 具备3年以上连锁零售或餐饮行业工程营建管理经验，有完整项目落地经验。  \n3. 熟悉装修施工流程、材料标准及国家相关法规，具备较强的现场管理能力。  \n4. 具备良好的沟通协调能力与沟通能力，能适应阶段性出差。\n\n岗位亮点\n1. 加入快速成长的本土品牌，参与全国门店扩张战略，发展空间广阔。  \n2. 工作氛围轻松有趣，团队年轻有活力，倡导创新与高效协作。  \n3. 提供完善的培训体系与职业发展通道，助力个人专业与管理能力提升。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3786409581","sourceKey":"meituan_social","company":"美团","title":"快乐猴-杭州地推经理BDM","city":"杭州市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3786409581&jobShareType=1","duty":"1.负责制定和执行线下推广策略，实现销售目标；\n2.负责管理线下推广团队，包括团队招聘、培训和绩效考核；\n3.负责与各合作方进行沟通和协调，确保推广活动的顺利进行；\n4.负责监控推广活动效果，及时调整策略和方案。","requirements":"1.大学专科以上学历，市场营销、商务管理等相关专业优先；\n2.三年以上业务运营、销售运营或管理经验，有团队管理经验者优先；\n3.具备较强的沟通协调能力、团队管理能力和执行能力；\n4.对线下推广有深入了解，熟悉市场营销渠道及推广工具。","description":"部门介绍\n快乐猴是美团自营社区超市，依托自有供应链和门店管理体系，聚焦家庭用户的三餐所需，为消费者提供高质价比的食杂商品。快乐猴以数字化能力与科学品控为基础，不断满足消费者对“省”和“便利”的需求。\n\n岗位职责\n1.负责制定和执行线下推广策略，实现销售目标；\n2.负责管理线下推广团队，包括团队招聘、培训和绩效考核；\n3.负责与各合作方进行沟通和协调，确保推广活动的顺利进行；\n4.负责监控推广活动效果，及时调整策略和方案。\n\n岗位基本要求\n1.大学专科以上学历，市场营销、商务管理等相关专业优先；\n2.三年以上业务运营、销售运营或管理经验，有团队管理经验者优先；\n3.具备较强的沟通协调能力、团队管理能力和执行能力；\n4.对线下推广有深入了解，熟悉市场营销渠道及推广工具。\n\n岗位亮点\n1.薪资福利优厚，提供良好的晋升空间和发展平台；\n2.可参与公司战略规划和决策，实现个人价值与公司共同成长；\n3.工作氛围轻松愉快，团队氛围融洽，有机会获得专业培训和职业发展机会。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4496645922","sourceKey":"meituan_social","company":"美团","title":"商业化","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4496645922&jobShareType=1","duty":"1、商业化策略制定：负责业务线的整体商业化策略，围绕品牌广告、效果广告及营销变现等方向，对营收目标负责。深度挖掘客户需求，提供定制化广告解决方案，提升客户长期合作价值。\n2、品效协同推进：整合品牌广告与效果广告资源，为客户提供从品牌建设到效果转化的一体化营销服务，推动品效协同落地，打造差异化竞争优势。\n3、商业化产品管理：直接负责商业化产品的规划与产出，主导广告产品体系搭建，推动产品从需求定义、设计开发到上线迭代的全流程，持续提升变现效率与客户体验。\n4、数据驱动优化：建立营销效果评估体系，监控ROI、LTV等关键指标，通过A/B测试等手段持续优化商业化策略与产品方案。\n5、跨部门协同：协调产品、运营、技术等内外部资源，推动商业化项目从提案、执行到回款全流程顺利落地，并对项目效果负责。","requirements":"1、本科及以上学历。\n2、8年以上互联网广告商业化相关经验，具备品牌广告与效果广告（CPC/CPA/oCPX等）双线运营能力，有大客户管理、销售策略、项目管理等综合经验；有从0到1搭建商业化体系经验优先。\n3、具备商业化产品创新与管理能力，能主导广告产品的需求定义、方案设计与迭代优化。\n4、深刻理解品效协同逻辑，能根据客户业务目标灵活组合广告产品，有效驱动客户GMV增长或品牌价值提升。\n5、数据敏感度高，能够基于数据驱动决策，熟悉营销效果评估方法论。\n6、出色的商务谈判与客户关系管理能力，能有效整合内外部资源，推动复杂需求落地。","description":"部门介绍\n美团骑行事业部在全国各个城市开展美团单车、电单车业务，提供绿色、便捷的共享出行服务，是美团出行板块重要的组成部分。我们力求为城市可持续发展提供低碳智能的解决方案，通过技术创新和硬件升级，不断优化全流程骑行体验，为低碳出行提供更好的服务。其中，美团单车旨在为城市居民提供通勤接驳服务，满足用户短途接驳出行需求；美团电单车则满足用户中短途多场景低碳出行需求。\n我们有开放的工作氛围，也有充满韧劲和创造力，心系低碳出行的伙伴。加入我们，一起为用户创造更好的出行体验。\n\n岗位职责\n1、商业化策略制定：负责业务线的整体商业化策略，围绕品牌广告、效果广告及营销变现等方向，对营收目标负责。深度挖掘客户需求，提供定制化广告解决方案，提升客户长期合作价值。\n2、品效协同推进：整合品牌广告与效果广告资源，为客户提供从品牌建设到效果转化的一体化营销服务，推动品效协同落地，打造差异化竞争优势。\n3、商业化产品管理：直接负责商业化产品的规划与产出，主导广告产品体系搭建，推动产品从需求定义、设计开发到上线迭代的全流程，持续提升变现效率与客户体验。\n4、数据驱动优化：建立营销效果评估体系，监控ROI、LTV等关键指标，通过A/B测试等手段持续优化商业化策略与产品方案。\n5、跨部门协同：协调产品、运营、技术等内外部资源，推动商业化项目从提案、执行到回款全流程顺利落地，并对项目效果负责。\n\n岗位基本要求\n1、本科及以上学历。\n2、8年以上互联网广告商业化相关经验，具备品牌广告与效果广告（CPC/CPA/oCPX等）双线运营能力，有大客户管理、销售策略、项目管理等综合经验；有从0到1搭建商业化体系经验优先。\n3、具备商业化产品创新与管理能力，能主导广告产品的需求定义、方案设计与迭代优化。\n4、深刻理解品效协同逻辑，能根据客户业务目标灵活组合广告产品，有效驱动客户GMV增长或品牌价值提升。\n5、数据敏感度高，能够基于数据驱动决策，熟悉营销效果评估方法论。\n6、出色的商务谈判与客户关系管理能力，能有效整合内外部资源，推动复杂需求落地。\n\n具备以下条件优先\n1、有本地生活、共享服务相关行业商业化经验。\n\n2、有从0到1搭建商业化产品体系并实现规模化变现的经历。\n\n3、操盘过大型商业化项目并拿到超预期结果。\n\n岗位亮点\n1、公司提供完善的培训体系与晋升通道。  \n2、 团队氛围开放，鼓励创新与协作。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4740836422","sourceKey":"meituan_social","company":"美团","title":"业务风控算法工程师","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4740836422&jobShareType=1","duty":"1、构建 AI业务风控能力\n负责核心业务的反作弊、反欺诈与交易安全，综合规则、图算法、异常检测和大模型，对多源数据建模，识别团伙作弊与新型风险，持续优化资损、误伤和处置时效等核心指标；将风险识别、研判、处置、评估能力模块化，支撑跨场景快速复用。\n\n2、探索 Agent 驱动的风控运营范式\n构建“风险感知—证据分析—研判处置—效果复盘”Agent工作流，使Agent能够调用数据与策略工具、基于证据完成研判，并输出可追溯结论；在评测、审计、灰度和回滚机制保障下，逐步从人机协同走向受控自动化运营。\n\n3、推动大模型深度融入风控决策\n将LLM应用于作弊模式发现、异常归因、案例研判、策略建议等关键环节，结合知识检索、工具调用、结构化输出、案例记忆与反馈闭环，提升复杂风险的理解、推理和决策可靠性；建设离线评测与线上监控体系，持续优化效果、成本与时效。\n\n4、前沿技术预研与能力沉淀\n跟踪Agentic风控、主动风险狩猎和AI攻防对抗等方向，验证可落地方案；按业务复杂度探索单Agent或多Agent协作，沉淀可复用的技术组件、评测标准和风控方法论，支撑产品与运营解决实际风险问题。","requirements":"1. 扎实的机器学习/深度学习理论基础，在反作弊、异常检测、社区发现、知识图谱、NLP等至少一个领域有深入的研究和实践经验；\n2. 至少熟练使用Python、Java、C++中一种编程语言，熟练运用多种常用算法与数据结构；\n熟悉主流大模型技术栈（如skill、memory、agent teams等），有大模型应用开发或微调经验者优先；\n3. 对AI Agent、工作流自动化有认知或实践经验，具备将复杂业务流程抽象为可自动化系统的设计思维；\n4. 熟悉各类常见作弊手段与业务风控策略，有互联网风控反作弊模型设计经验者优先；\n具备优秀的逻辑思维能力和数据敏感度，对解决复杂对抗性问题充满热情。","description":"部门介绍\n基础研发平台是美团的核心技术平台，立足于“零售+科技”的战略定位，通过打造人工智能、大数据、云计算、安全等核心技术能力，以及研发效能平台、企业应用平台等公共服务，为业务提供稳定安全、扩展易用、技术领先的平台技术和产品服务。\n在这里，我们会参与到最前沿的技术研发和探索；能够接触超规模集群、海量数据，挑战高复杂业务场景，有机会与业界一流的工程师一起并肩前行。\n在这里，我们有超强的技术氛围，持续向社区贡献业界实践，加速行业技术发展；我们有完善的互联网学习生态圈，重视底层逻辑和方法论，助力职业生涯的非线性成长。\n真诚地邀请你，和我们一起驱动技术发展，创造行业价值。\n\n岗位职责\n1、构建 AI业务风控能力\n负责核心业务的反作弊、反欺诈与交易安全，综合规则、图算法、异常检测和大模型，对多源数据建模，识别团伙作弊与新型风险，持续优化资损、误伤和处置时效等核心指标；将风险识别、研判、处置、评估能力模块化，支撑跨场景快速复用。\n\n2、探索 Agent 驱动的风控运营范式\n构建“风险感知—证据分析—研判处置—效果复盘”Agent工作流，使Agent能够调用数据与策略工具、基于证据完成研判，并输出可追溯结论；在评测、审计、灰度和回滚机制保障下，逐步从人机协同走向受控自动化运营。\n\n3、推动大模型深度融入风控决策\n将LLM应用于作弊模式发现、异常归因、案例研判、策略建议等关键环节，结合知识检索、工具调用、结构化输出、案例记忆与反馈闭环，提升复杂风险的理解、推理和决策可靠性；建设离线评测与线上监控体系，持续优化效果、成本与时效。\n\n4、前沿技术预研与能力沉淀\n跟踪Agentic风控、主动风险狩猎和AI攻防对抗等方向，验证可落地方案；按业务复杂度探索单Agent或多Agent协作，沉淀可复用的技术组件、评测标准和风控方法论，支撑产品与运营解决实际风险问题。\n\n岗位基本要求\n1. 扎实的机器学习/深度学习理论基础，在反作弊、异常检测、社区发现、知识图谱、NLP等至少一个领域有深入的研究和实践经验；\n2. 至少熟练使用Python、Java、C++中一种编程语言，熟练运用多种常用算法与数据结构；\n熟悉主流大模型技术栈（如skill、memory、agent teams等），有大模型应用开发或微调经验者优先；\n3. 对AI Agent、工作流自动化有认知或实践经验，具备将复杂业务流程抽象为可自动化系统的设计思维；\n4. 熟悉各类常见作弊手段与业务风控策略，有互联网风控反作弊模型设计经验者优先；\n具备优秀的逻辑思维能力和数据敏感度，对解决复杂对抗性问题充满热情。\n\n岗位亮点\n1. 定义下一代智能风控：不是在现有框架里做优化，而是参与从0到1构建AI-Native风控体系；\n2. 推动风控运营从\"人驱动\"走向\"Agent驱动\"，这是当前工程领域最有想象力的方向之一；\n3. 最复杂的业务场景，海量数据+高复杂度对抗博弈，与业务方深度协作，深入了解本地生活服务全链路；","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4798502096","sourceKey":"meituan_social","company":"美团","title":"品牌广告大客户销售","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4798502096&jobShareType=1","duty":"1. 经营策略：在保证平台交易效率及用户体验的前提下，推动消费行业品牌在餐饮场景+的整合营销，业务路径覆盖品牌曝光、策略创意、供给运营、商品交易等\n\n2. 目标导向：保持消费行业品牌在平台的投资意愿、投资规模及年度增长等方面策略一致；独立推动高质量客户策略分析、行业洞察报告及提案制作；  \n\n3. 客户开发：具备消快消客户资源及拓展能力，有效的识别行业及客户架构，策略及需求，结合平台能力赋能品牌经营提效\n\n 4. 内部协同：结合市场规律有效的推动产品进程，整合多方资源，场域。跨团队协同推动项目落地和优化；","requirements":"1. 5年左右工作经验，拥有行业头部快消品牌方、互联网平台整合营销/品牌推广/媒介传播/O2O/采销等相关经验；\n\n 2. 关注零售、餐饮等发展趋势，熟悉品牌方投资经营逻辑及平台商业化策略；推动长效，健康的外部合作\n\n 3. 具备良好的商务谈判能力、数据分析能力及策略方案输出和多部门协同配合能力；","description":"部门介绍\n商业增值部是服务于美团核心本地商业客户的增值服务平台，覆盖餐饮、即时零售、医药、休闲娱乐、丽人医美、生活服务、酒旅度假等业务领域。我们致力于构建健康的本地商业生态，通过为平台客户和消费者提供符合其需求的多元、便捷、高效的商业产品和服务，帮助生态伙伴提高效率、优化经营、实现持续健康发展，推动本地商业数字化营销的发展，促进商业生态繁荣。作为本地商业的头部平台，我们为产品、运营、商务、技术、商业分析等领域人才提供广阔的发展空间。诚邀你加入美团商业增值团队，共筑本地商业的健康繁荣生态！\n\n岗位职责\n1. 经营策略：在保证平台交易效率及用户体验的前提下，推动消费行业品牌在餐饮场景+的整合营销，业务路径覆盖品牌曝光、策略创意、供给运营、商品交易等\n\n2. 目标导向：保持消费行业品牌在平台的投资意愿、投资规模及年度增长等方面策略一致；独立推动高质量客户策略分析、行业洞察报告及提案制作；  \n\n3. 客户开发：具备消快消客户资源及拓展能力，有效的识别行业及客户架构，策略及需求，结合平台能力赋能品牌经营提效\n\n 4. 内部协同：结合市场规律有效的推动产品进程，整合多方资源，场域。跨团队协同推动项目落地和优化；\n\n岗位基本要求\n1. 5年左右工作经验，拥有行业头部快消品牌方、互联网平台整合营销/品牌推广/媒介传播/O2O/采销等相关经验；\n\n 2. 关注零售、餐饮等发展趋势，熟悉品牌方投资经营逻辑及平台商业化策略；推动长效，健康的外部合作\n\n 3. 具备良好的商务谈判能力、数据分析能力及策略方案输出和多部门协同配合能力；\n\n具备以下条件优先\n拥有拓客能力；具备快消行业客户品牌/渠道/推广等方向；平台商业化产品策略/售卖等经验\n\n岗位亮点\n依托平台多年沉淀的组织运营能力，基于餐饮场域+和8亿用户规模的广泛商业空间，我们孵化出全新的平台商业化增长模式，旨在帮助快消行业客户打造“餐饮第二增长曲线”。，可培养掌握本地生活O2O模式的前沿发展动向，帮助客户实现生意增长的闭环解决方案，成为兼具多方视角的大客户管理专家","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4796893615","sourceKey":"meituan_social","company":"美团","title":"小象超市—沈阳线上店店长","city":"沈阳市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4796893615&jobShareType=1","duty":"1.负责线上店的商品管理,对于商品的效期管理、品质管理、损耗管理负责,负责门店的水产养殖和销售的整体管理;\n2.负责线上店的进销存管理,负责线上店内门店的收货、上架、库存、库位的管理工作,优化库内的动线和库位,对于商品的周转和资产、设备的安全准确负责;\n3.负责线上店订单的履约,保证在更快的时间保质保量履约客户的订单,不断追求降本提效,致力于为客户提供更好的服务,不断精益求精;配合总部各项营销策略的实施,负责线上各品类商品的日常的促销活动实施;\n4.负责线上店现场的人员管理,包括招聘、培训和效率管理,负责数据管理和异常事件处理,维护周边社区关系;进行日常经营管理工作,包含对各项运营指标进行监控和分析,确保销售达成；\n5.新开门店开业前期筹备相关工作。","requirements":"1.大专以上学历,3-5年连锁门店经营管理经验/仓储运营管理经验；\n2.对生鲜商品有一定的认知,熟悉门店促销管理、损耗控制管理、品类管理等,了解仓储的进销存管理,了解互联网的生产管理；\n3.良好的沟通能力及跨部门团队合作精神,学习能力佳,责任心强,愿意接受挑战,以结果为导向；\n4.善干劳务人员的管理工作,熟悉与零售相关的法律法规；\n5.熟练操作办公软件。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1.负责线上店的商品管理,对于商品的效期管理、品质管理、损耗管理负责,负责门店的水产养殖和销售的整体管理;\n2.负责线上店的进销存管理,负责线上店内门店的收货、上架、库存、库位的管理工作,优化库内的动线和库位,对于商品的周转和资产、设备的安全准确负责;\n3.负责线上店订单的履约,保证在更快的时间保质保量履约客户的订单,不断追求降本提效,致力于为客户提供更好的服务,不断精益求精;配合总部各项营销策略的实施,负责线上各品类商品的日常的促销活动实施;\n4.负责线上店现场的人员管理,包括招聘、培训和效率管理,负责数据管理和异常事件处理,维护周边社区关系;进行日常经营管理工作,包含对各项运营指标进行监控和分析,确保销售达成；\n5.新开门店开业前期筹备相关工作。\n\n岗位基本要求\n1.大专以上学历,3-5年连锁门店经营管理经验/仓储运营管理经验；\n2.对生鲜商品有一定的认知,熟悉门店促销管理、损耗控制管理、品类管理等,了解仓储的进销存管理,了解互联网的生产管理；\n3.良好的沟通能力及跨部门团队合作精神,学习能力佳,责任心强,愿意接受挑战,以结果为导向；\n4.善干劳务人员的管理工作,熟悉与零售相关的法律法规；\n5.熟练操作办公软件。\n\n岗位亮点\n即时零售前置仓头部企业营运核心岗位，与互联网大咖及零售业专家共同发展。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4446359923","sourceKey":"meituan_social","company":"美团","title":"Training Operations","city":"吉达","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4446359923&jobShareType=1","duty":"1. 负责培训项目的日常运营支持，包括培训计划制定、执行跟踪及效果评估。  \n2. 协调内外部资源，确保培训课程按时开展并符合业务需求。  \n3. 管理培训相关数据，定期输出运营报告并提出优化建议。  \n4. 协助建立并完善培训流程与标准，提升培训运营效率。","requirements":"1. 大学本科及以上学历，人力资源管理、工商管理或相关专业优先。  \n2. 具备5年以上培训运营或相关业务运营经验，有团队支持经验者优先。  \n3. 熟悉培训体系搭建及项目管理流程，具备良好的沟通协调能力。  \n4. 熟练使用办公软件，具备较强的数据分析与文档撰写能力。","description":"部门介绍\n美团的使命是“帮大家吃得更好，生活更好”，公司聚焦“零售 + 科技”战略，和广大商户与各类合作伙伴一起，努力为消费者提供品质生活，推动商品零售和服务零售在需求侧和供给侧的数字化转型。\n2018年9月20日，美团正式在港交所挂牌上市。美团将始终坚持以客户为中心，不断加大在科技研发方面的投入，更好承担社会责任，更多创造社会价值，与广大合作伙伴一起发展共赢。\n\n岗位职责\n1. 负责培训项目的日常运营支持，包括培训计划制定、执行跟踪及效果评估。  \n2. 协调内外部资源，确保培训课程按时开展并符合业务需求。  \n3. 管理培训相关数据，定期输出运营报告并提出优化建议。  \n4. 协助建立并完善培训流程与标准，提升培训运营效率。\n\n岗位基本要求\n1. 大学本科及以上学历，人力资源管理、工商管理或相关专业优先。  \n2. 具备5年以上培训运营或相关业务运营经验，有团队支持经验者优先。  \n3. 熟悉培训体系搭建及项目管理流程，具备良好的沟通协调能力。  \n4. 熟练使用办公软件，具备较强的数据分析与文档撰写能力。\n\n岗位亮点\n1. 工作地点位于达曼，提供具有竞争力的薪酬与福利。  \n2. 参与公司核心人才培养项目，积累丰富的运营管理经验。  \n3. 扁平化管理模式，拥有良好的职业发展通道与学习成长机会。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4232927361","sourceKey":"meituan_social","company":"美团","title":"数据治理产品-美团核心本地商业","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4232927361&jobShareType=1","duty":"1.输出方法论、模版、标准规范、治理方案，赋能业务线，协同数据产研支持业务线数据治理落地，并对治理成果进行质量验收及效果评估；\n2.承接核心本地商业 BR数据治理需求，制定公共指标统一规范（口径、标准流程）、对CLC BR 和各业务BR（BM/BM-1层级）指标名称口径、数据结果一致性负责；\n3.承担天机接口人角色，负责天机指标日常口径运维、推动数据接入、口径结果验证，保障天机产品及时展示业务关注的核心指标，且数据与业务线一致。\n4.日常熟练使用AI及搭建Skills开展指标治理提效工作。","requirements":"1.3年以上数据产品相关经验，SQL熟练，对CLC各业务线有一定理解认知，具备快速学习能力，能够精准把握不同业务核心指标需求与应用场景；\n2.出色的跨部门沟通协调能力，擅长与各业务线管理层人员高效沟通，能够清晰宣贯指标框架与口径规则，推动指标标准在 CLC 及各业务层面顺利落地；\n3.具备优秀的需求对接与答疑能力，善于解决指标细节分歧与问题；\n4.熟悉指标体系搭建相关方法论，数据产品优先。\n5.具有使用AI工具能力，对指标规范、指标体量优化、相似指标治理、AI口径优化建议治理相关经验者优先。","description":"部门介绍\n核心本地商业（Core Local Commerce）是美团“零售+科技”战略的重要载体，涵盖了到店餐饮、服务零售、酒店旅行、外卖、履约配送、闪购、医药健康等多个业务，覆盖了超过200个消费场景，致力于通过“随时随地”的商品和服务，满足消费者的多样性需求，帮大家吃得更好，生活更好。核心本地商业扎根本地消费，围绕消费者的“吃、住、行、游、购、娱”进行深度创新，引领发展了即时零售、团购等多种消费业态，并在全国范围内广泛投资发展本地供给、履约平台等设施，助力创造产业、带动就业。基于多年的持续投入，核心本地商业打造了连接全国超过一千万中小微企业的服务体系，以及全球最大的即时配送网络。由核心本地商业所推行的30分钟“万物到家”体系，已覆盖全国2800多个城镇，为数亿用户提供优质的商品与服务。发展过程中，核心本地商业有效助力商超、连锁、本地小店等各类实体经济主体扩大交易规模、降低交易成本。截至目前，核心本地商业日均创造订单量数千万笔，助力千万商户实现了高质量发展。未来，核心本地商业将继续践行美团“零售+科技”战略，通过更大的投资，更多的技术创新，支持、培育消费新业态，为促进消费、服务民生、带动就业作出力所能及的贡献。欢迎优秀的你加入核心本地商业，我们携手助力市场繁荣，为用户创造更好的消费体验。\n\n岗位职责\n1.输出方法论、模版、标准规范、治理方案，赋能业务线，协同数据产研支持业务线数据治理落地，并对治理成果进行质量验收及效果评估；\n2.承接核心本地商业 BR数据治理需求，制定公共指标统一规范（口径、标准流程）、对CLC BR 和各业务BR（BM/BM-1层级）指标名称口径、数据结果一致性负责；\n3.承担天机接口人角色，负责天机指标日常口径运维、推动数据接入、口径结果验证，保障天机产品及时展示业务关注的核心指标，且数据与业务线一致。\n4.日常熟练使用AI及搭建Skills开展指标治理提效工作。\n\n岗位基本要求\n1.3年以上数据产品相关经验，SQL熟练，对CLC各业务线有一定理解认知，具备快速学习能力，能够精准把握不同业务核心指标需求与应用场景；\n2.出色的跨部门沟通协调能力，擅长与各业务线管理层人员高效沟通，能够清晰宣贯指标框架与口径规则，推动指标标准在 CLC 及各业务层面顺利落地；\n3.具备优秀的需求对接与答疑能力，善于解决指标细节分歧与问题；\n4.熟悉指标体系搭建相关方法论，数据产品优先。\n5.具有使用AI工具能力，对指标规范、指标体量优化、相似指标治理、AI口径优化建议治理相关经验者优先。\n\n具备以下条件优先\n数据产品、数据PM优先。\n\n岗位亮点\nCLC业务线数据治理，全面覆盖各业务线核心指标内容，能够从CLC整体高度出发，深入了解CLC各业务核心场景与发展趋势，是熟悉公司整体业务的契机，助于个人构建完整的业务认知体系。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4775964403","sourceKey":"meituan_social","company":"美团","title":"神抢手供给运营","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4775964403&jobShareType=1","duty":"1. 负责美团外卖神抢手业务的供给策略制定与执行，提升神抢手供给规模与质量。\n\n2. 协同商品运营及产品团队，推动神抢手供给招商链路的高效运转。\n\n3. 建立并完善供给运营指标体系，通过数据分析驱动业务增长与效率提升。\n\n4. 探索创新供给模式，提升神抢手业务在平台中的竞争力与用户心智","requirements":"1.5 年以上互联网平台型业务供给运营 / 商家运营 / 策略运营经验；有外卖、本地生活背景者优先；\n\n2.深度理解商品运营逻辑，有爆品运营、限时秒杀 / 闪购 / 抢购频道供给运营经验者优先；\n\n3.具备体系化的策略思维，数据敏感度高，能独立完成复杂业务问题的拆解、归因与建模；\n\n4.自驱力强、结果导向，能适应高速变化的业务节奏","description":"部门介绍\n美团外卖秉承“帮大家吃得更好，生活更好”的使命，始终聚焦于消费者用餐需求。我们通过科技连接消费者和商家，依托庞大的骑手团队，以“线上+线下”的业务模式，为消费者提供品质化、精细化、多样化的餐饮外卖服务。\n外卖事业部是为用户与商家提供全链路交易服务的业务组织，围绕餐饮外卖搭建了包含外卖业务与创新孵化业务在内的多个部门。\n我们的目标是帮助商家开源增收、提高经营效率，促进餐饮行业数字化，以及为更多用户提供更便捷更有品质的外卖服务。加入我们，一起为上亿用户提供更好的用餐体验，帮助大家吃得更好，生活更好！\n\n岗位职责\n1. 负责美团外卖神抢手业务的供给策略制定与执行，提升神抢手供给规模与质量。\n\n2. 协同商品运营及产品团队，推动神抢手供给招商链路的高效运转。\n\n3. 建立并完善供给运营指标体系，通过数据分析驱动业务增长与效率提升。\n\n4. 探索创新供给模式，提升神抢手业务在平台中的竞争力与用户心智\n\n岗位基本要求\n1.5 年以上互联网平台型业务供给运营 / 商家运营 / 策略运营经验；有外卖、本地生活背景者优先；\n\n2.深度理解商品运营逻辑，有爆品运营、限时秒杀 / 闪购 / 抢购频道供给运营经验者优先；\n\n3.具备体系化的策略思维，数据敏感度高，能独立完成复杂业务问题的拆解、归因与建模；\n\n4.自驱力强、结果导向，能适应高速变化的业务节奏\n\n岗位亮点\n1. 团队年轻充满热情，氛围轻松有激情，个人成长共空间大；\n\n2. 能在快速发展的平台级业务中，参与规模化的过程，并在其中担任核心角色。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4794843097","sourceKey":"meituan_social","company":"美团","title":"安全经理","city":"重庆市/青岛市/南昌市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4794843097&jobShareType=1","duty":"安全管理： \n1，执行和推动公司安防管理制度在仓库的运行，落实对各制度执行情况的监督、检查和改善追踪。\n2.负责仓库发生安防事故、事件的应急处理及调查处理工作、上报和改善落实，确保及时结案.。并做好各类事故的统计、分析和培训分享，确保事故率达到公司指标。\n3.负责仓库区域内的现场安全监督管理；检查并消除运营作业风险、管控施工安全风险。\n4.做好当地与消防部门、派出所等政府部门沟通联动工作，及时处理突发政府巡查事项。 \n5. 定期整理、汇总、上报安防方面有关资料、报表，并按要求输出对应周期总结。\n6.确保各项安全工作流程及标准落实执行，做好风险管控，确保事故率达到公司指标。 \n7.定期开展消防/防汛/防暴等安全演练，提升员工安全意识与应急能力，履行安全管理责任人职责。\n8. 根据年度安全培训计划对仓库人员及现场施工人员进行安全教育和培训。 \n损耗管理： \n 1.负责所在运营单位损耗数据分析，制定有效损耗管理措施，确保损耗率达到公司指标。 \n 2.执行总部防损策略，确保损耗管理各项工作及控制方案得到落实。  \n 3.定期开展公司运营关键流程、成本、费用类稽核工作，输出稽核报告，跟进整改闭环，节省运营成本。 \n团队管理：   \n1.负责管辖区域内部门员工的业务培训、指导，确保部门工作开展落实。   \n2.负责团队员工绩效考核，对不达标同事制定绩效改善措施，帮助员工提升工作绩效达到部门指标。","requirements":"1.专科以上学历，具有3年以上安全管理经验、EHS相关工作经验，熟悉安全标准化、ISO45001等安全管理体系，有物流行业经验为佳。\n2.  熟悉安全生产、消防、交通、突发事件处置等相关知识，具备安全管理方案编制和总结复盘的工作能力。\n3.为人正直，具备优秀的职业操守，能独立开展工作，适应能力强4. 具备安全事故事件分析能力，逻辑思维能力强，善于从数据中发现问题。 \n5. 具备良好的沟通协调能力和执行力，文字功底扎实，团队合作精神强。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n安全管理： \n1，执行和推动公司安防管理制度在仓库的运行，落实对各制度执行情况的监督、检查和改善追踪。\n2.负责仓库发生安防事故、事件的应急处理及调查处理工作、上报和改善落实，确保及时结案.。并做好各类事故的统计、分析和培训分享，确保事故率达到公司指标。\n3.负责仓库区域内的现场安全监督管理；检查并消除运营作业风险、管控施工安全风险。\n4.做好当地与消防部门、派出所等政府部门沟通联动工作，及时处理突发政府巡查事项。 \n5. 定期整理、汇总、上报安防方面有关资料、报表，并按要求输出对应周期总结。\n6.确保各项安全工作流程及标准落实执行，做好风险管控，确保事故率达到公司指标。 \n7.定期开展消防/防汛/防暴等安全演练，提升员工安全意识与应急能力，履行安全管理责任人职责。\n8. 根据年度安全培训计划对仓库人员及现场施工人员进行安全教育和培训。 \n损耗管理： \n 1.负责所在运营单位损耗数据分析，制定有效损耗管理措施，确保损耗率达到公司指标。 \n 2.执行总部防损策略，确保损耗管理各项工作及控制方案得到落实。  \n 3.定期开展公司运营关键流程、成本、费用类稽核工作，输出稽核报告，跟进整改闭环，节省运营成本。 \n团队管理：   \n1.负责管辖区域内部门员工的业务培训、指导，确保部门工作开展落实。   \n2.负责团队员工绩效考核，对不达标同事制定绩效改善措施，帮助员工提升工作绩效达到部门指标。\n\n岗位基本要求\n1.专科以上学历，具有3年以上安全管理经验、EHS相关工作经验，熟悉安全标准化、ISO45001等安全管理体系，有物流行业经验为佳。\n2.  熟悉安全生产、消防、交通、突发事件处置等相关知识，具备安全管理方案编制和总结复盘的工作能力。\n3.为人正直，具备优秀的职业操守，能独立开展工作，适应能力强4. 具备安全事故事件分析能力，逻辑思维能力强，善于从数据中发现问题。 \n5. 具备良好的沟通协调能力和执行力，文字功底扎实，团队合作精神强。\n\n具备以下条件优先\n持有注册安全工程师或消防工程师证书。\n\n岗位亮点\n1.已有成熟的安全生产管理体系，具备多种职能横向发展的机会，从安全管理、损耗治理，危机处置，质控运营等职能横向学习。\n2.岗位成长空间大，未来可成长方向可横向到中台策略专家发展，也可往大区运营储备方向发展。\n3.互联网企业更加开放、包容，能充分发挥人才的主观能动性，能使人才迅速成长并勇挑重担，实现人生价值。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:1883063813","sourceKey":"meituan_social","company":"美团","title":"生鲜PC采控负责人","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=1883063813&jobShareType=1","duty":"1、制定PC在进销存上的业务流程规则，与产品能力，支持业务高效运营；\n2、制定订单前缺货、订单后缺货的管理策略，支撑品类销售增长与UE改善；\n3、制定周转、不健康库存的管理策略，提升库存效率，优化库存成本；\n4、搭建进向成本优化的策略与链路能力，支撑商流跃迁；\n5、上级安排的其他工作。","requirements":"1、本科学历及以上，供应链、物流、工业工程等相关专业优先；\n2、5年以上团队管理经验，对零售全链条有深刻认知，了解商品周转及流通业态；\n3、有良好的思维逻辑和策略规划能力，能有效提炼供应链的核心痛点并提供解决方案；\n4、具备数据处理能力，如熟练应用SQL等工具者优先；\n5、良好的沟通协作能力，能适应快速迭代的节奏。","description":"部门介绍\n快驴进货是美团旗下的餐饮供应链平台，帮助餐饮商户以更低成本、更高效率来获取安全可靠的食材供应，让餐饮采购更简单。快驴进货同步发展“自营+平台”的业务模式，在采购环节一方面向上游供应商直采大宗商品，另一方面引入各地批发商，助力平台伙伴共同发展；在销售环节既有自建团队进行市场、客户拓展，又帮助各地批发商拓展业务；同时自建仓储管理系统、配送网络与团队，为客户提供优质履约服务。\n截至2022年，快驴进货布局了全国41个城市，为百万家商户提供“全、省、稳、好”的餐饮供应链服务。我们拥有3000+品牌食材、超5万SKU商品、超28万商品资质，并提供源头严审核、食品安全严把关、24小时无忧售后的全面保障，实现手机下单、送货上门的高效采购模式，帮百万商家节省了采购时间与成本，助力平台伙伴共同发展，在万亿市场共享机遇。\n在这里，你将收获完善的员工发展机制及学习体系，与各界专家一起深度参与餐饮供应链业务的发展。欢迎优秀的你加入美团快驴进货，与我们一起成长，一起更好！\n\n岗位职责\n1、制定PC在进销存上的业务流程规则，与产品能力，支持业务高效运营；\n2、制定订单前缺货、订单后缺货的管理策略，支撑品类销售增长与UE改善；\n3、制定周转、不健康库存的管理策略，提升库存效率，优化库存成本；\n4、搭建进向成本优化的策略与链路能力，支撑商流跃迁；\n5、上级安排的其他工作。\n\n岗位基本要求\n1、本科学历及以上，供应链、物流、工业工程等相关专业优先；\n2、5年以上团队管理经验，对零售全链条有深刻认知，了解商品周转及流通业态；\n3、有良好的思维逻辑和策略规划能力，能有效提炼供应链的核心痛点并提供解决方案；\n4、具备数据处理能力，如熟练应用SQL等工具者优先；\n5、良好的沟通协作能力，能适应快速迭代的节奏。\n\n岗位亮点\n1.全面供应链视角，业务发挥空间大，团队氛围好；\n2.BU级重点项目，能从全链路视角看业务发展。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4796843508","sourceKey":"meituan_social","company":"美团","title":"线下活动执行主管","city":"杭州市/苏州市/扬州市/成都市/重庆市/宁波市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4796843508&jobShareType=1","duty":"1、负责线下活动的现场执行，把控活动流程、物料和人员管理、现场动线与用户体验；\n2、多渠道资源协调，对接内部各协同方，物业管理方、外部供应商，确保各触点按时按质交付；\n3、持续复盘迭代，沉淀SOP，为后续线下活动提供可复用的执行标准。","requirements":"1、学历要求：大专及以上学历；\n2、有销售管理经验，有C端销售管理经验者优先考虑；\n3、学习能力强，敢于应对挑战；\n4、具备出色的沟通与协调能力，能够与团队成员和其他部门有效合作，达成共同目标。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1、负责线下活动的现场执行，把控活动流程、物料和人员管理、现场动线与用户体验；\n2、多渠道资源协调，对接内部各协同方，物业管理方、外部供应商，确保各触点按时按质交付；\n3、持续复盘迭代，沉淀SOP，为后续线下活动提供可复用的执行标准。\n\n岗位基本要求\n1、学历要求：大专及以上学历；\n2、有销售管理经验，有C端销售管理经验者优先考虑；\n3、学习能力强，敢于应对挑战；\n4、具备出色的沟通与协调能力，能够与团队成员和其他部门有效合作，达成共同目标。\n\n岗位亮点\n1、参与公司核心业务，发挥关键作用；\n2、提供广阔的职业发展通道与成长空间。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4737101269","sourceKey":"meituan_social","company":"美团","title":"营销方向 AI Builder","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4737101269&jobShareType=1","duty":"1. 负责营销方向AI产品的规划与设计，深入理解业务需求并转化为产品方案。  \n2. 协同算法、工程、运营等团队，推动AI模型在营销场景中的落地与优化。  \n3. 分析用户行为与市场趋势，持续迭代产品功能，提升用户体验与转化效率。  \n4. 制定产品路线图，明确优先级，确保项目按时高质量交付。  \n5. 关注行业动态发展，探索AI在营销领域的新机会与创新应用。","requirements":"1. 大学本科及以上学历，计算机、市场营销、数据科学等相关专业优先。  \n2. 3年以上产品相关工作经验，有AI产品或营销科技产品背景者优先。  \n3. 熟悉AI技术原理及其在营销场景中的应用，具备较强的逻辑思维与数据分析能力。  \n4. 具备良好的跨团队沟通与项目管理能力，能够推动多方协作达成目标。  \n5. 对用户需求敏感，具备较强的产品sense与商业洞察力。","description":"部门介绍\n美团骑行事业部在全国各个城市开展美团单车、电单车业务，提供绿色、便捷的共享出行服务，是美团出行板块重要的组成部分。我们力求为城市可持续发展提供低碳智能的解决方案，通过技术创新和硬件升级，不断优化全流程骑行体验，为低碳出行提供更好的服务。其中，美团单车旨在为城市居民提供通勤接驳服务，满足用户短途接驳出行需求；美团电单车则满足用户中短途多场景低碳出行需求。\n我们有开放的工作氛围，也有充满韧劲和创造力，心系低碳出行的伙伴。加入我们，一起为用户创造更好的出行体验。\n\n岗位职责\n1. 负责营销方向AI产品的规划与设计，深入理解业务需求并转化为产品方案。  \n2. 协同算法、工程、运营等团队，推动AI模型在营销场景中的落地与优化。  \n3. 分析用户行为与市场趋势，持续迭代产品功能，提升用户体验与转化效率。  \n4. 制定产品路线图，明确优先级，确保项目按时高质量交付。  \n5. 关注行业动态发展，探索AI在营销领域的新机会与创新应用。\n\n岗位基本要求\n1. 大学本科及以上学历，计算机、市场营销、数据科学等相关专业优先。  \n2. 3年以上产品相关工作经验，有AI产品或营销科技产品背景者优先。  \n3. 熟悉AI技术原理及其在营销场景中的应用，具备较强的逻辑思维与数据分析能力。  \n4. 具备良好的跨团队沟通与项目管理能力，能够推动多方协作达成目标。  \n5. 对用户需求敏感，具备较强的产品sense与商业洞察力。\n\n具备以下条件优先\n独立负责某个模块或者产品经验优先\n\n岗位亮点\n1. 参与前沿AI技术在营销领域的创新实践，推动行业变革。  \n2. 深入硬件产业链，有机会发展软硬件结合的AI产品化能力。     \n3. 扁平化管理，鼓励创新与自主决策，激发个人潜能。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4490284563","sourceKey":"meituan_social","company":"美团","title":"仓配BP财务-配送","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4490284563&jobShareType=1","duty":"岗位职责：  \n1. 负责仓配配送业务的财务支持工作，深入理解业务模式，提供财务分析与决策支持。  \n2. 搭建并优化配送业务财务模型，进行成本、利润及预算的精细化分析与管理。  \n3. 协同业务团队制定财务目标，监控关键指标执行情况，及时预警并提出改进建议。  \n4. 带领1人团队完成日常财务BP工作，包括数据整理、报告输出及跨部门协作。  \n5. 推动财务流程在配送业务中的落地与优化，提升财务与业务协同效率。","requirements":"1. 大学本科及以上学历，财务、会计、经济等相关专业背景。  \n2. 5年以上财务分析或财务BP相关工作经验，有物流、配送或供应链行业背景优先。  \n3. 具备扎实的财务分析能力，熟练使用SQL及主流财务系统。  \n4. 具备较强的逻辑思维、沟通能力和团队协作能力，能独立推动项目落地。  \n5. 有带团队经验，具备较强的责任心能力。  \n6、创新与推动力，有主动发现问题、创新解决方案的能力。能推动专项项目落地，跟踪改进效果。\n7、具备AI工具应用能力，能将AI技术融入仓配业务的财务分析与风险管理工作，有AI+供应链/仓配财务实践经验者优先。","description":"部门介绍\n财务平台负责公司整体和各业务层面的财务管理工作，通过建设专业、全面、复合的财务管理能力和与业务经营的紧密结合来支持公司健康发展。目前财务平台拥有财务会计、财务报告、资金管理、税务管理、财务共享、财务系统、规划分析、财务BP和内控内审等主要工作方向。我们的目标是建设业界一流的财务管理能力和经营支持体系，为公司战略的正确落地、投入效率的持续提升、业务价值的不断增长保驾护航。欢迎加入财务平台，携手一起向未来！\n\n岗位职责\n岗位职责：  \n1. 负责仓配配送业务的财务支持工作，深入理解业务模式，提供财务分析与决策支持。  \n2. 搭建并优化配送业务财务模型，进行成本、利润及预算的精细化分析与管理。  \n3. 协同业务团队制定财务目标，监控关键指标执行情况，及时预警并提出改进建议。  \n4. 带领1人团队完成日常财务BP工作，包括数据整理、报告输出及跨部门协作。  \n5. 推动财务流程在配送业务中的落地与优化，提升财务与业务协同效率。\n\n岗位基本要求\n1. 大学本科及以上学历，财务、会计、经济等相关专业背景。  \n2. 5年以上财务分析或财务BP相关工作经验，有物流、配送或供应链行业背景优先。  \n3. 具备扎实的财务分析能力，熟练使用SQL及主流财务系统。  \n4. 具备较强的逻辑思维、沟通能力和团队协作能力，能独立推动项目落地。  \n5. 有带团队经验，具备较强的责任心能力。  \n6、创新与推动力，有主动发现问题、创新解决方案的能力。能推动专项项目落地，跟踪改进效果。\n7、具备AI工具应用能力，能将AI技术融入仓配业务的财务分析与风险管理工作，有AI+供应链/仓配财务实践经验者优先。\n\n岗位亮点\n1. 深入参与仓配核心业务，财务与业务高度融合，成长空间广阔。  \n2. 团队氛围开放，支持创新与主动思考，鼓励专业能力提升。  \n3. 工作地点位于北京核心区域，办公环境优良，福利待遇完善。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4764712927","sourceKey":"meituan_social","company":"美团","title":"供应链解决方案专家","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4764712927&jobShareType=1","duty":"1、从商家到仓配端的供应链端到端角度，制定全链路的解决方案，降低供应链履约成本，提升供应链运营效率；\n2、基于不同品类运营策略，制定差异化的供应链解决方案并推进落地，提升商品供给、降低成本；\n3、基于不同商流模式的特性，持续优化履约链路，提升履约链路的商家体验提升，提高商流与物流沟通运作效率，优化履约成本；\n4、与品、商、仓高效协同，负责组织和推进各品类、商流、物流协同的创新优化项目；\n5、基于业务升级的需求，推动业务系统和流程的不断完善，兼顾供应链系统的优化；\n6、负责物流承运商的开发、引入和商务合作；\n7、协调运力调度，确保运输交付；\n8、负责费用结算和成本分析管控，提出降本优化建议。","requirements":"1、本科学历及以上，供应链、物流、工业工程等相关专业优先；\n2、5年以上供应链规划和解决方案相关经验，对零售全链条有深刻认知，了解商品周转及流通业态；\n3、有良好的思维逻辑和策略规划能力，能有效提炼供应链的核心痛点并提供解决方案，良好的沟通协作能力，能将解决方案协同各方快速落地；\n4、具备数据处理能力，如熟练应用SQL、AI等工具。","description":"部门介绍\n快驴进货是美团旗下的餐饮供应链平台，帮助餐饮商户以更低成本、更高效率来获取安全可靠的食材供应，让餐饮采购更简单。快驴进货同步发展“自营+平台”的业务模式，在采购环节一方面向上游供应商直采大宗商品，另一方面引入各地批发商，助力平台伙伴共同发展；在销售环节既有自建团队进行市场、客户拓展，又帮助各地批发商拓展业务；同时自建仓储管理系统、配送网络与团队，为客户提供优质履约服务。\n截至2022年，快驴进货布局了全国41个城市，为百万家商户提供“全、省、稳、好”的餐饮供应链服务。我们拥有3000+品牌食材、超5万SKU商品、超28万商品资质，并提供源头严审核、食品安全严把关、24小时无忧售后的全面保障，实现手机下单、送货上门的高效采购模式，帮百万商家节省了采购时间与成本，助力平台伙伴共同发展，在万亿市场共享机遇。\n在这里，你将收获完善的员工发展机制及学习体系，与各界专家一起深度参与餐饮供应链业务的发展。欢迎优秀的你加入美团快驴进货，与我们一起成长，一起更好！\n\n岗位职责\n1、从商家到仓配端的供应链端到端角度，制定全链路的解决方案，降低供应链履约成本，提升供应链运营效率；\n2、基于不同品类运营策略，制定差异化的供应链解决方案并推进落地，提升商品供给、降低成本；\n3、基于不同商流模式的特性，持续优化履约链路，提升履约链路的商家体验提升，提高商流与物流沟通运作效率，优化履约成本；\n4、与品、商、仓高效协同，负责组织和推进各品类、商流、物流协同的创新优化项目；\n5、基于业务升级的需求，推动业务系统和流程的不断完善，兼顾供应链系统的优化；\n6、负责物流承运商的开发、引入和商务合作；\n7、协调运力调度，确保运输交付；\n8、负责费用结算和成本分析管控，提出降本优化建议。\n\n岗位基本要求\n1、本科学历及以上，供应链、物流、工业工程等相关专业优先；\n2、5年以上供应链规划和解决方案相关经验，对零售全链条有深刻认知，了解商品周转及流通业态；\n3、有良好的思维逻辑和策略规划能力，能有效提炼供应链的核心痛点并提供解决方案，良好的沟通协作能力，能将解决方案协同各方快速落地；\n4、具备数据处理能力，如熟练应用SQL、AI等工具。\n\n岗位亮点\n1.全面供应链视角，业务发挥空间大，团队氛围好；\n2.BU级重点项目，能从全链路视角看业务发展。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4796300776","sourceKey":"meituan_social","company":"美团","title":"小象超市-分区经理（北京/沈阳）","city":"北京市/沈阳市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4796300776&jobShareType=1","duty":"1.负责多门店的管理工作，配合总部各项营销策略的实施，负责线上APP各品类商品的日常的促销活动实施；\n2.进行日常经营管理工作，包含对各项运营指标进行监控和分析，确保销售达成；\n3.负责多门店月度、季节性活动规划及促销机制的落地；\n4.进行日常损耗管理和设备运营维护工作；\n5.新开门店开业前期筹备相关工作；\n6.对内域内人员的招聘，日常培训和人效管理工作。","requirements":"1.五年以上连锁门店/单体大店经营管理经验，熟悉新零售优先；\n2.对生鲜商品有一定的认知，熟悉门店促销管理、损耗控制管理、品类管理等；\n3.良好的沟通能力及跨部门团队合作精神，学习能力佳，责任心强，愿意接受挑战，以结果为导向；\n4.善于劳务人员的管理工作，熟悉与零售相关的法律法规；\n5.熟练操作办公软件及智能手机，热爱互联网行业。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1.负责多门店的管理工作，配合总部各项营销策略的实施，负责线上APP各品类商品的日常的促销活动实施；\n2.进行日常经营管理工作，包含对各项运营指标进行监控和分析，确保销售达成；\n3.负责多门店月度、季节性活动规划及促销机制的落地；\n4.进行日常损耗管理和设备运营维护工作；\n5.新开门店开业前期筹备相关工作；\n6.对内域内人员的招聘，日常培训和人效管理工作。\n\n岗位基本要求\n1.五年以上连锁门店/单体大店经营管理经验，熟悉新零售优先；\n2.对生鲜商品有一定的认知，熟悉门店促销管理、损耗控制管理、品类管理等；\n3.良好的沟通能力及跨部门团队合作精神，学习能力佳，责任心强，愿意接受挑战，以结果为导向；\n4.善于劳务人员的管理工作，熟悉与零售相关的法律法规；\n5.熟练操作办公软件及智能手机，热爱互联网行业。\n\n具备以下条件优先\n商场、物流大团队相关管理经验\n\n岗位亮点\n大平台，业务快速发展，完善的带训体系快速成长","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4493377685","sourceKey":"meituan_social","company":"美团","title":"设备物资主管-苏州","city":"苏州市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4493377685&jobShareType=1","duty":"日常管理包括片区内负责仓库输送线维保维养包括生产陪产和日常养护，物资申请配置、验收入库、物资存储、物资日常养护、物资维修、物资报废、消耗品日常管理、物资盘点、库存分析与预警以及能耗管理。\n1.生产陪产涉及生产前设备巡查、生产中及时处理设备异常、生产结束后解决无法在生产过程中处理的异常，确保生产运营顺利进行。\n2.日常养护包括制定维养频率、管理设备配件、建立管理台账、处理配件申请与报废工作，确保配件数量合理充足，并在设备质保期内与厂家沟通，确保技术标准统一。\n3.物资申请配置需进行需求分析、遵循配置标准、规范执行申请流程并管理台账。\n4.验收入库涉及到货信息核验、质量检验、系统数据录入及异常问题处理。\n5.物资存储要求设置功能分区并进行精细化运营。\n6.物资日常养护包括制定养护计划、环境监测与调节、物资检查与维护及养护记录与分析。\n7.物资维修需进行故障诊断与评估、协调维修资源、检验维修质量及管理维修台账。\n8.物资报废按照标准检查并申请。\n9.消耗品日常管理包括物资盘点、差异分析处理及提交盘点报告。\n10.水电能耗管理涉及相关操作。","requirements":"1、大专学历、机电一体化、电气类相关专业、持电工证；\n2、两年以上相关设备维护与保养相关经验，能独立分析设备故障原因并排除，具有物流、快递行业（（皮带机、爬坡机、转弯机等)等分拣设备维保工作经验；\n3、有较强的安全意识，具有较强的责任心、吃苦耐劳、品行端正、无不良嗜好，能接受长期晚班。\n4、掌握基本的AI工具，使用工具提升工作流程效率","description":"部门介绍\n快驴进货是美团旗下的餐饮供应链平台，帮助餐饮商户以更低成本、更高效率来获取安全可靠的食材供应，让餐饮采购更简单。快驴进货同步发展“自营+平台”的业务模式，在采购环节一方面向上游供应商直采大宗商品，另一方面引入各地批发商，助力平台伙伴共同发展；在销售环节既有自建团队进行市场、客户拓展，又帮助各地批发商拓展业务；同时自建仓储管理系统、配送网络与团队，为客户提供优质履约服务。\n截至2022年，快驴进货布局了全国41个城市，为百万家商户提供“全、省、稳、好”的餐饮供应链服务。我们拥有3000+品牌食材、超5万SKU商品、超28万商品资质，并提供源头严审核、食品安全严把关、24小时无忧售后的全面保障，实现手机下单、送货上门的高效采购模式，帮百万商家节省了采购时间与成本，助力平台伙伴共同发展，在万亿市场共享机遇。\n在这里，你将收获完善的员工发展机制及学习体系，与各界专家一起深度参与餐饮供应链业务的发展。欢迎优秀的你加入美团快驴进货，与我们一起成长，一起更好！\n\n岗位职责\n日常管理包括片区内负责仓库输送线维保维养包括生产陪产和日常养护，物资申请配置、验收入库、物资存储、物资日常养护、物资维修、物资报废、消耗品日常管理、物资盘点、库存分析与预警以及能耗管理。\n1.生产陪产涉及生产前设备巡查、生产中及时处理设备异常、生产结束后解决无法在生产过程中处理的异常，确保生产运营顺利进行。\n2.日常养护包括制定维养频率、管理设备配件、建立管理台账、处理配件申请与报废工作，确保配件数量合理充足，并在设备质保期内与厂家沟通，确保技术标准统一。\n3.物资申请配置需进行需求分析、遵循配置标准、规范执行申请流程并管理台账。\n4.验收入库涉及到货信息核验、质量检验、系统数据录入及异常问题处理。\n5.物资存储要求设置功能分区并进行精细化运营。\n6.物资日常养护包括制定养护计划、环境监测与调节、物资检查与维护及养护记录与分析。\n7.物资维修需进行故障诊断与评估、协调维修资源、检验维修质量及管理维修台账。\n8.物资报废按照标准检查并申请。\n9.消耗品日常管理包括物资盘点、差异分析处理及提交盘点报告。\n10.水电能耗管理涉及相关操作。\n\n岗位基本要求\n1、大专学历、机电一体化、电气类相关专业、持电工证；\n2、两年以上相关设备维护与保养相关经验，能独立分析设备故障原因并排除，具有物流、快递行业（（皮带机、爬坡机、转弯机等)等分拣设备维保工作经验；\n3、有较强的安全意识，具有较强的责任心、吃苦耐劳、品行端正、无不良嗜好，能接受长期晚班。\n4、掌握基本的AI工具，使用工具提升工作流程效率\n\n具备以下条件优先\n有仓库输送线维保维养包括生产陪产和日常养护知识及电工证优先考虑\n\n岗位亮点\n快速发展的互联网业务，发展空间大，良好的团队氛围，挑战和成长机会多","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4754259832","sourceKey":"meituan_social","company":"美团","title":"区域安全管理专家","city":"广州市/深圳市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4754259832&jobShareType=1","duty":"1. 负责所辖区域物流安全防损体系运营，覆盖生产作业安全、配送交通安全、消防安全三大场景，对区域亿件安全事故数等核心指标负责。\n2. 推动区域隐患排查治理闭环，组织仓内巡检与城市仓自检，识别叉车作业、高位货架、装卸、分拣等场景风险，督促整改落地并验证效果。\n3. 统筹区域事故事件管理，事件响应、调查、根因分析、整改推动，保障风管110等系统填报的及时性与准确性，杜绝迟报漏报。\n4. 运营区域基础安全项目（司机违规治理、培训教育、应急演练等），持续优化项目执行质量。\n5. 对接总部安全策略落地，协同区域仓拣、配送、进向等条线安全标准执行，赋能业务条线履行安全职责。","requirements":"1. 大学专科及以上学历，安全工程等相关专业优先。\n2. 5年以上仓储物流/即时配送行业安全管理经验，有安全体系搭建或多区域管理经验者优先。\n3. 熟悉国家安全生产法规及行业标准，具备风险评估和应急管理能力；能用数据定位问题、验证管理效果，熟练使用办公软件及安全管理系统。\n4. 具备较强的跨部门沟通推动能力，能推动业务条线落实安全要求。\n5. 会用AI工具提效，愿意在AI方面投入精力钻研。","description":"部门介绍\n快驴进货是美团旗下的餐饮供应链平台，帮助餐饮商户以更低成本、更高效率来获取安全可靠的食材供应，让餐饮采购更简单。快驴进货同步发展“自营+平台”的业务模式，在采购环节一方面向上游供应商直采大宗商品，另一方面引入各地批发商，助力平台伙伴共同发展；在销售环节既有自建团队进行市场、客户拓展，又帮助各地批发商拓展业务；同时自建仓储管理系统、配送网络与团队，为客户提供优质履约服务。\n截至2022年，快驴进货布局了全国41个城市，为百万家商户提供“全、省、稳、好”的餐饮供应链服务。我们拥有3000+品牌食材、超5万SKU商品、超28万商品资质，并提供源头严审核、食品安全严把关、24小时无忧售后的全面保障，实现手机下单、送货上门的高效采购模式，帮百万商家节省了采购时间与成本，助力平台伙伴共同发展，在万亿市场共享机遇。\n在这里，你将收获完善的员工发展机制及学习体系，与各界专家一起深度参与餐饮供应链业务的发展。欢迎优秀的你加入美团快驴进货，与我们一起成长，一起更好！\n\n岗位职责\n1. 负责所辖区域物流安全防损体系运营，覆盖生产作业安全、配送交通安全、消防安全三大场景，对区域亿件安全事故数等核心指标负责。\n2. 推动区域隐患排查治理闭环，组织仓内巡检与城市仓自检，识别叉车作业、高位货架、装卸、分拣等场景风险，督促整改落地并验证效果。\n3. 统筹区域事故事件管理，事件响应、调查、根因分析、整改推动，保障风管110等系统填报的及时性与准确性，杜绝迟报漏报。\n4. 运营区域基础安全项目（司机违规治理、培训教育、应急演练等），持续优化项目执行质量。\n5. 对接总部安全策略落地，协同区域仓拣、配送、进向等条线安全标准执行，赋能业务条线履行安全职责。\n\n岗位基本要求\n1. 大学专科及以上学历，安全工程等相关专业优先。\n2. 5年以上仓储物流/即时配送行业安全管理经验，有安全体系搭建或多区域管理经验者优先。\n3. 熟悉国家安全生产法规及行业标准，具备风险评估和应急管理能力；能用数据定位问题、验证管理效果，熟练使用办公软件及安全管理系统。\n4. 具备较强的跨部门沟通推动能力，能推动业务条线落实安全要求。\n5. 会用AI工具提效，愿意在AI方面投入精力钻研。\n\n岗位亮点\n1. 管一个区域的完整安全盘子（仓+配），场景全、链条长，成长快。\n2. 直接对接总部，参与全国安全体系搭建，个人合理建议能直接影响全国策略。\n3. 团队扁平，看结果说话。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4712992731","sourceKey":"meituan_social","company":"美团","title":"配送运营专家","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4712992731&jobShareType=1","duty":"1.制定并执行配送运营策略，确保物流成本、时效体验、质量保障等目标的达成；\n2.与物流内外的各部门间有效合作，推动项目和策略的顺利落地执行；\n3.定位配送作业过程的问题和机会点，优化司机作业工序，提高运营效率和质量；","requirements":"1.大学本科及以上学历，物流、供应链或相关专业优先；\n2.具有5年以上物流运营管理经验，熟悉物流行业的操作流程和规范；\n3.具备良好的跨部门沟通和项目管理能力，能够与内外部各方进行有效沟通和协同；\n4.具备良好的分析问题和解决问题能力，面对复杂的物流场景能够及时发现问题并提出解决方案；\n5.具备较强的适应能力和应变能力，能够积极应对复杂的运营环境和挑战。","description":"部门介绍\n快驴进货是美团旗下的餐饮供应链平台，帮助餐饮商户以更低成本、更高效率来获取安全可靠的食材供应，让餐饮采购更简单。快驴进货同步发展“自营+平台”的业务模式，在采购环节一方面向上游供应商直采大宗商品，另一方面引入各地批发商，助力平台伙伴共同发展；在销售环节既有自建团队进行市场、客户拓展，又帮助各地批发商拓展业务；同时自建仓储管理系统、配送网络与团队，为客户提供优质履约服务。\n截至2022年，快驴进货布局了全国41个城市，为百万家商户提供“全、省、稳、好”的餐饮供应链服务。我们拥有3000+品牌食材、超5万SKU商品、超28万商品资质，并提供源头严审核、食品安全严把关、24小时无忧售后的全面保障，实现手机下单、送货上门的高效采购模式，帮百万商家节省了采购时间与成本，助力平台伙伴共同发展，在万亿市场共享机遇。\n在这里，你将收获完善的员工发展机制及学习体系，与各界专家一起深度参与餐饮供应链业务的发展。欢迎优秀的你加入美团快驴进货，与我们一起成长，一起更好！\n\n岗位职责\n1.制定并执行配送运营策略，确保物流成本、时效体验、质量保障等目标的达成；\n2.与物流内外的各部门间有效合作，推动项目和策略的顺利落地执行；\n3.定位配送作业过程的问题和机会点，优化司机作业工序，提高运营效率和质量；\n\n岗位基本要求\n1.大学本科及以上学历，物流、供应链或相关专业优先；\n2.具有5年以上物流运营管理经验，熟悉物流行业的操作流程和规范；\n3.具备良好的跨部门沟通和项目管理能力，能够与内外部各方进行有效沟通和协同；\n4.具备良好的分析问题和解决问题能力，面对复杂的物流场景能够及时发现问题并提出解决方案；\n5.具备较强的适应能力和应变能力，能够积极应对复杂的运营环境和挑战。\n\n具备以下条件优先\n1.有生鲜物流的行业经验；\n2.有着强烈自驱意识，结果导向；\n3.熟练使用SQL。\n\n岗位亮点\n1. 参与核心业务运营，直接影响运营效率和用户体验；\n2. 团队氛围开放，鼓励创新和技术驱动；  \n3. 有机会接触前沿物流技术和智能化解决方案。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4782958576","sourceKey":"meituan_social","company":"美团","title":"Keemart-物流逆向运营","city":"利雅得","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4782958576&jobShareType=1","duty":"1、负责物流逆向业务全链路流程设计及持续优化，覆盖退仓、退供、残次、临期、过期、报损、报废等业务场景；\n建立逆向业务SOP、作业标准、责任界面及异常处理机制；\n2、负责逆向业务日常运营监控，持续跟进逆向库存规模、库存库龄、处理时效及异常情况；推动仓库及时完成逆向商品收货、分类、暂存、退供、调拨、报废等处理；\n3、建立供应商退供流程及运营机制，明确退供条件、预约、交接、运输、签收及账务处理标准；联动采购及供应商推动退供及时完成，减少退供库存长期占用仓储空间；\n4、对逆向库存进行结构化分析，重点关注长期库存、残次库存、临期/过期库存及高价值异常商品；推动逆向库存及时处置，降低库存积压及仓储占用；\n5、建立并持续优化逆向业务指标体系，包括但不限于：逆向库存金额/数量、退供及时率、逆向处理及时率、超期未处理库存、账实一致率、报损/报废率、逆向库存占比、供应商退供SLA达成率。定期输出运营日报、周报及专项分析，识别业务问题并推动闭环。\n6、协同仓储、运输、采购、商品、库存、财务、质量、防损及系统团队解决逆向业务问题；明确各团队在逆向流程中的职责和责任边界；\n7、梳理逆向业务系统需求，推动WMS、TMS及相关系统能力建设；推动逆向业务从线下人工管理逐步向系统化、数据化管理转变；","requirements":"1、本科及以上学历，物流、供应链、工业工程、工商管理等相关专业优先；3年以上物流、仓储、供应链运营相关经验；\n2、具备较强的流程梳理及SOP建设能力；较强的数据分析能力，能够通过数据识别运营问题；\n3、有大型电商、零售或物流企业逆向物流/库存治理经验；有WMS、TMS或供应链系统建设经验；有供应商退供、库存治理、损耗治理等专项经验；","description":"部门介绍\n美团的使命是“帮大家吃得更好，生活更好”，公司聚焦“零售 + 科技”战略，和广大商户与各类合作伙伴一起，努力为消费者提供品质生活，推动商品零售和服务零售在需求侧和供给侧的数字化转型。\n2018年9月20日，美团正式在港交所挂牌上市。美团将始终坚持以客户为中心，不断加大在科技研发方面的投入，更好承担社会责任，更多创造社会价值，与广大合作伙伴一起发展共赢。\n\n岗位职责\n1、负责物流逆向业务全链路流程设计及持续优化，覆盖退仓、退供、残次、临期、过期、报损、报废等业务场景；\n建立逆向业务SOP、作业标准、责任界面及异常处理机制；\n2、负责逆向业务日常运营监控，持续跟进逆向库存规模、库存库龄、处理时效及异常情况；推动仓库及时完成逆向商品收货、分类、暂存、退供、调拨、报废等处理；\n3、建立供应商退供流程及运营机制，明确退供条件、预约、交接、运输、签收及账务处理标准；联动采购及供应商推动退供及时完成，减少退供库存长期占用仓储空间；\n4、对逆向库存进行结构化分析，重点关注长期库存、残次库存、临期/过期库存及高价值异常商品；推动逆向库存及时处置，降低库存积压及仓储占用；\n5、建立并持续优化逆向业务指标体系，包括但不限于：逆向库存金额/数量、退供及时率、逆向处理及时率、超期未处理库存、账实一致率、报损/报废率、逆向库存占比、供应商退供SLA达成率。定期输出运营日报、周报及专项分析，识别业务问题并推动闭环。\n6、协同仓储、运输、采购、商品、库存、财务、质量、防损及系统团队解决逆向业务问题；明确各团队在逆向流程中的职责和责任边界；\n7、梳理逆向业务系统需求，推动WMS、TMS及相关系统能力建设；推动逆向业务从线下人工管理逐步向系统化、数据化管理转变；\n\n岗位基本要求\n1、本科及以上学历，物流、供应链、工业工程、工商管理等相关专业优先；3年以上物流、仓储、供应链运营相关经验；\n2、具备较强的流程梳理及SOP建设能力；较强的数据分析能力，能够通过数据识别运营问题；\n3、有大型电商、零售或物流企业逆向物流/库存治理经验；有WMS、TMS或供应链系统建设经验；有供应商退供、库存治理、损耗治理等专项经验；\n\n岗位亮点\n1、业务影响大：逆向运营直接影响库存健康、仓储空间、商品损耗及资金占用，是物流降本增效的重要抓手；\n2、业务视角广：岗位不仅关注仓内执行，还会深度参与商品、采购、供应商、财务、库存及系统等多个环节；\n3、结果导向明确：能够通过流程优化、数据治理和机制建设，直接看到库存下降、时效提升及损耗改善的业务结果；\n4、成长空间大：岗位兼具运营、供应链、库存管理、项目管理及系统产品能力，有机会成长为独立的供应链业务Owner；\n5、海外业务场景丰富：在快速发展的海外零售及物流业务中，参与解决供应商能力、履约差异、本地化运营等复杂问题。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4794229723","sourceKey":"meituan_social","company":"美团","title":"美团评价策略产品","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4794229723&jobShareType=1","duty":"1. 深入洞察美团本地生活不同业务的用户看评场景，通过对用户看评诉求分析及本地生活各行业的决策特征理解，制定行业的有用性标准与标签体系，提升评价内容的真实性、丰富度及对用户的决策参考价值。\n\n2. 通过用户行为分析及体感洞察，精准定位用户在选店决策路径中的痛点，针对评价排序、双端（美团/点评）供给差异等场景进行分析下探，抽象业务规则，推动算法模型迭代，并验证策略上线后的增量价值。\n\n3. 结合AI/大模型能力探索评价智能化方向，推动AI辅助内容理解、智能总结、效果归因等链路的产品化落地，评估AI应用对运营效率与用户体验的实际提升效果。  \n\n4. 作为业务与算法、产品、运营等多团队之间的桥梁，在模糊的业务场景中高效推动策略落地，建立策略实验与效果评估的标准化闭环，通过持续迭代验证策略有效性。","requirements":"1. 3年以上内容平台、搜索、推荐或评价体系的策略产品经理经验，熟悉流量分发、排序权重调优及内容相关性、真实性等核心策略逻辑，有评价/内容生态相关经验者优先。\n\n2. 兼具良好的数据分析和用户洞察能力，对指标含义、用户价值、行业价值有足够的思考和理解，能从千万级用户行为数据中抽象出产品策略，能够敏锐洞察用户价值与行业差异，并将其转化为可量化的策略指标。\n\n3. 对AI在内容理解、智能交互等场景的应用有实践或深度思考，能够快速理解AI技术边界并找到与业务场景的结合点。\n\n4. 具备较强的跨团队沟通协作能力和项目推动力，对本地生活行业有基本认知，能从用户视角判断策略价值，在用户体验、商户价值与平台生态之间找到平衡点。","description":"部门介绍\n美团平台为用户的基础产品体验负责，还承担了美团的用户增长、市场和品牌营销以及多条业务线的产品设计职责，建立了融合文字、图片、视频和直播等不同形式的內容生态系统，同时整合地图服务部、客户服务和体验部、企业业务部、网约车业务部等部门，致力于用科技提升美团数亿消费者、近千万商家、骑手、司机和团长的服务体验。美团平台拥有高并发、多业务的复杂场景，为技术深度优化提供了最佳实践可能。这里有简单、讲逻辑、有爱的团队，更是一块理想的实战场地，舞台广阔，欢迎你来尽情施展。\n\n岗位职责\n1. 深入洞察美团本地生活不同业务的用户看评场景，通过对用户看评诉求分析及本地生活各行业的决策特征理解，制定行业的有用性标准与标签体系，提升评价内容的真实性、丰富度及对用户的决策参考价值。\n\n2. 通过用户行为分析及体感洞察，精准定位用户在选店决策路径中的痛点，针对评价排序、双端（美团/点评）供给差异等场景进行分析下探，抽象业务规则，推动算法模型迭代，并验证策略上线后的增量价值。\n\n3. 结合AI/大模型能力探索评价智能化方向，推动AI辅助内容理解、智能总结、效果归因等链路的产品化落地，评估AI应用对运营效率与用户体验的实际提升效果。  \n\n4. 作为业务与算法、产品、运营等多团队之间的桥梁，在模糊的业务场景中高效推动策略落地，建立策略实验与效果评估的标准化闭环，通过持续迭代验证策略有效性。\n\n岗位基本要求\n1. 3年以上内容平台、搜索、推荐或评价体系的策略产品经理经验，熟悉流量分发、排序权重调优及内容相关性、真实性等核心策略逻辑，有评价/内容生态相关经验者优先。\n\n2. 兼具良好的数据分析和用户洞察能力，对指标含义、用户价值、行业价值有足够的思考和理解，能从千万级用户行为数据中抽象出产品策略，能够敏锐洞察用户价值与行业差异，并将其转化为可量化的策略指标。\n\n3. 对AI在内容理解、智能交互等场景的应用有实践或深度思考，能够快速理解AI技术边界并找到与业务场景的结合点。\n\n4. 具备较强的跨团队沟通协作能力和项目推动力，对本地生活行业有基本认知，能从用户视角判断策略价值，在用户体验、商户价值与平台生态之间找到平衡点。\n\n具备以下条件优先\n1. 有评价/评论领域 或 大型本地生活平台 相关经验\n\n2. 主导或深度参与过 AI 赋能产品的全链路尝试\n\n岗位亮点\n1. 这是一个深度参与评价业务核心策略的岗位，你将直接负责评价体系的策略设计与效果优化，驱动用户评价行为和内容生态的健康发展。\n\n2. 评价是用户消费决策中最关键的信任资产之一，你将有机会重新定义“什么是高质量评价”，通过精细化策略运营，提升评价内容的质量和可信度，让优质评价更好地服务用户决策。\n\n3. 岗位横跨用户、商户、审核治理、算法分发等多个关键环节，能够完整锻炼平台型产品的系统设计和跨团队推动能力。\n\n4. 这是一个非常适合结合 AI 提效的场景，内容理解、智能总结、效果归因等链路都有大量 AI 工具赋能运营效率的创新空间。 \n\n5. 你将面对真实的大规模用户场景，产出的策略能力可以被上亿用户使用，并直接影响用户体验、交易效率和平台生态健康度。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4785418744","sourceKey":"meituan_social","company":"美团","title":"软硬件服务业务内控","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4785418744&jobShareType=1","duty":"1、参与内控风险评估，确定重大风险领域，对相关任务进行优先级排序，制定对应工作计划；对内控特定领域的风险管控有一定认知和沉淀；\n2、开展内控评价工作，对业财流程设计和执行有效性开展端到端的检查，评价财务结果的真实性、完整性、准确性，以及财务风险管控效果；\n3、开展各种内控项目，工作内容包含流程访谈、方案制定、数据分析、控制测试、底稿编制、问题确认以及沟通等；能够与业务建立良好的沟通和协作关系，针对发现的风险制定改进计划，并督促/跟踪完成整改；\n4、对风险管理有效性进行综合评估，识别重大控制缺陷和风险提出专业意见，通过制度和流程优化、风险管理和监督责任落实、系统化风险识别和预警能力建设等；\n5、通过数字化手段、数据分析、建模等方式发现与监控风险，及时预警，推动业务部门有效改进；\n6、负责简单闭环业务，能熟练运用逻辑思考和专业知识，应用各种分析方法和逻辑解决复杂问题；\n7、做好与负责业务线管理团队的沟通及价值输出；\n8、培养人才\n9、完成上级主管安排的其他事项","requirements":"1、本科或以上学历，良好的英语听说读写能力；\n2、8年以上大中型企业、事务所、咨询公司内控、审计、账务等工作经验；系统审计的丰富经验；熟悉COSO,SOX，中国企业内控控制基本规范和指引，并不断更新掌握前沿知识；\n3、CISA、CPA、ACCA、CIA、CMA优先。会计师事务所、咨询公司经验+甲方内控优先，过往职业经历涉及互联网、制造业经验尤佳。\n4、具备AI思维与工具应用能力，能将AI能力主动引入风险识别、数据分析、治理措施等内控日常工作场景中，持续进行AI应用探索与落地。","description":"部门介绍\n财务平台负责公司整体和各业务层面的财务管理工作，通过建设专业、全面、复合的财务管理能力和与业务经营的紧密结合来支持公司健康发展。目前财务平台拥有财务会计、财务报告、资金管理、税务管理、财务共享、财务系统、规划分析、财务BP和内控内审等主要工作方向。我们的目标是建设业界一流的财务管理能力和经营支持体系，为公司战略的正确落地、投入效率的持续提升、业务价值的不断增长保驾护航。欢迎加入财务平台，携手一起向未来！\n\n岗位职责\n1、参与内控风险评估，确定重大风险领域，对相关任务进行优先级排序，制定对应工作计划；对内控特定领域的风险管控有一定认知和沉淀；\n2、开展内控评价工作，对业财流程设计和执行有效性开展端到端的检查，评价财务结果的真实性、完整性、准确性，以及财务风险管控效果；\n3、开展各种内控项目，工作内容包含流程访谈、方案制定、数据分析、控制测试、底稿编制、问题确认以及沟通等；能够与业务建立良好的沟通和协作关系，针对发现的风险制定改进计划，并督促/跟踪完成整改；\n4、对风险管理有效性进行综合评估，识别重大控制缺陷和风险提出专业意见，通过制度和流程优化、风险管理和监督责任落实、系统化风险识别和预警能力建设等；\n5、通过数字化手段、数据分析、建模等方式发现与监控风险，及时预警，推动业务部门有效改进；\n6、负责简单闭环业务，能熟练运用逻辑思考和专业知识，应用各种分析方法和逻辑解决复杂问题；\n7、做好与负责业务线管理团队的沟通及价值输出；\n8、培养人才\n9、完成上级主管安排的其他事项\n\n岗位基本要求\n1、本科或以上学历，良好的英语听说读写能力；\n2、8年以上大中型企业、事务所、咨询公司内控、审计、账务等工作经验；系统审计的丰富经验；熟悉COSO,SOX，中国企业内控控制基本规范和指引，并不断更新掌握前沿知识；\n3、CISA、CPA、ACCA、CIA、CMA优先。会计师事务所、咨询公司经验+甲方内控优先，过往职业经历涉及互联网、制造业经验尤佳。\n4、具备AI思维与工具应用能力，能将AI能力主动引入风险识别、数据分析、治理措施等内控日常工作场景中，持续进行AI应用探索与落地。\n\n岗位亮点\n头部互联网公司内控团队，能博采各家所长，磨炼与精进专业技能，成长发展空间大、内部发展前景佳；能深入了解业务、行业，掌握业务规律和本质；公司提供内外多元化学习交流机会，与优秀团队探索共创，共同成长","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4632069236","sourceKey":"meituan_social","company":"美团","title":"物流水产运营华东区域负责人","city":"上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4632069236&jobShareType=1","duty":"1.策略规划与执行：根据总部整体策略，制定并执行区域运营策略，确保鲜活水产物流运营的高效性和可持续性。\n2.运营管理：负责区域内水产物流的日常运营管理，包括仓储、运输、配送等环节。优化物流流程，提高运营效率，降低运营成本。\n3.团队管理：组建、培训和管理区域运营团队，确保团队成员具备必要的技能和知识，提升团队行业竞争力。激励团队，提升员工士气和工作效率。\n4.质量控制：确保水产产品在运输和暂养过程中的质量与安全，遵守相关法律法规和行业标准。定期进行质量检查和评估，及时解决质量问题。\n5.数据分析与报告：收集、分析运营数据，评估运营绩效，提出改进建议。定期向总部汇报区域运营情况，提供决策支持。\n6.风险管理：识别和评估运营过程中的潜在风险，制定应急预案，确保运营安全。\n7.合规管理：确保运营流程、业务管理、人员行为等作符合相关法律法规和公司政策。","requirements":"1.物流管理、供应链管理或相关专业本科及以上学历。\n2.5年以上水产物流或相关领域工作经验，其中至少3年以上区域或总部管理经验。\n3.熟悉物流运作流程，具备较强的运营管理能力。\n4.优秀的团队领导能力和沟通协调能力。\n5.较强的数据分析能力和问题解决能力。\n6.良好的客户服务意识和危机处理能力。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1.策略规划与执行：根据总部整体策略，制定并执行区域运营策略，确保鲜活水产物流运营的高效性和可持续性。\n2.运营管理：负责区域内水产物流的日常运营管理，包括仓储、运输、配送等环节。优化物流流程，提高运营效率，降低运营成本。\n3.团队管理：组建、培训和管理区域运营团队，确保团队成员具备必要的技能和知识，提升团队行业竞争力。激励团队，提升员工士气和工作效率。\n4.质量控制：确保水产产品在运输和暂养过程中的质量与安全，遵守相关法律法规和行业标准。定期进行质量检查和评估，及时解决质量问题。\n5.数据分析与报告：收集、分析运营数据，评估运营绩效，提出改进建议。定期向总部汇报区域运营情况，提供决策支持。\n6.风险管理：识别和评估运营过程中的潜在风险，制定应急预案，确保运营安全。\n7.合规管理：确保运营流程、业务管理、人员行为等作符合相关法律法规和公司政策。\n\n岗位基本要求\n1.物流管理、供应链管理或相关专业本科及以上学历。\n2.5年以上水产物流或相关领域工作经验，其中至少3年以上区域或总部管理经验。\n3.熟悉物流运作流程，具备较强的运营管理能力。\n4.优秀的团队领导能力和沟通协调能力。\n5.较强的数据分析能力和问题解决能力。\n6.良好的客户服务意识和危机处理能力。\n\n具备以下条件优先\n1.对鲜活水产品有不错的知识和经验积累。2.具备区域或总部物流运营管理经验。\n\n岗位亮点\n1.专业挑战：面对鲜活水产物流的复杂性和多变性，通过专业管理和技术手段实现高效运营。\n解决鲜活水产在运输、储存和销售过程中的一系列特殊问题，确保产品新鲜度和质量。\n2.职业发展：在鲜活水产物流领域积累丰富经验，为未来晋升至更高级管理岗位打下坚实基础。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4227184766","sourceKey":"meituan_social","company":"美团","title":"小象超市-布局规划仓容管理专家","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4227184766&jobShareType=1","duty":"1. 负责小象超市前置仓的仓容管理，优化空间利用率和供应链到货情况。  \n2. 制定并执行仓容管理策略，提升仓储效率与商品周转率。  \n3. 分析门店运营数据，识别布局与仓容方面的改进机会并推动落地。  \n4. 协同采购、物流及运营团队，确保商品陈列与库存配置符合业务需求。  \n5. 建立并完善布局规划与仓容管理的标准流程与工具体系。","requirements":"1. 大学本科及以上学历，零售管理、供应链管理或相关专业优先。  \n2. 具备5年以上零售行业门店运营或仓储规划相关工作经验。  \n3. 熟悉门店布局设计原则与仓储管理逻辑，具备数据分析能力。  \n4. 具备良好的沟通协调能力与项目管理能力，能推动跨部门协作。  \n5. 有生鲜零售或连锁超市背景者优先。\n6. 掌握基本的AI工具，能使用工具提升工作流程效率。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1. 负责小象超市前置仓的仓容管理，优化空间利用率和供应链到货情况。  \n2. 制定并执行仓容管理策略，提升仓储效率与商品周转率。  \n3. 分析门店运营数据，识别布局与仓容方面的改进机会并推动落地。  \n4. 协同采购、物流及运营团队，确保商品陈列与库存配置符合业务需求。  \n5. 建立并完善布局规划与仓容管理的标准流程与工具体系。\n\n岗位基本要求\n1. 大学本科及以上学历，零售管理、供应链管理或相关专业优先。  \n2. 具备5年以上零售行业门店运营或仓储规划相关工作经验。  \n3. 熟悉门店布局设计原则与仓储管理逻辑，具备数据分析能力。  \n4. 具备良好的沟通协调能力与项目管理能力，能推动跨部门协作。  \n5. 有生鲜零售或连锁超市背景者优先。\n6. 掌握基本的AI工具，能使用工具提升工作流程效率。\n\n岗位亮点\n1. 参与核心业务模块，直接影响门店运营效率与顾客体验。  \n2. 工作成果可量化，具备清晰的职业发展路径。  \n3. 团队氛围开放，鼓励创新与数据驱动决策。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4439540334","sourceKey":"meituan_social","company":"美团","title":"Food Category Manager","city":"迪拜/科威特城/利雅得","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4439540334&jobShareType=1","duty":"1.负责商品与供应链管理-招商采购领域的业务规划和战略制定。\n2.负责供应商的筛选、评估、谈判和合同管理，确保供应商的质量、价格和交货时间符合公司的要求。\n3.负责市场调研和竞争对手分析，及时了解市场动态和趋势，制定相关的采购策略。\n4.管理采购团队，指导团队成员的工作，确保团队目标的达成。\n5.配合供应链团队，协调内外部资源，优化采购流程，提高效率和降低成本。\n6.与其他部门合作，确保供应链的顺畅运作，满足公司业务的需求。\n\n1. Responsible for business planning and strategy development in the food procurement sector.including water and beverages, grain and oil, non-staple foods, snacks, instant drinks, frozen foods & ice products, and maternal & baby products\n2. Responsible for supplier screening, evaluation, negotiation, and contract management to ensure that suppliers meet the company’s requirements for quality, price, and delivery times.\n3. Responsible for market research and competitor analysis to stay abreast of market dynamics and trends and formulate relevant procurement strategies.\n4. Manage the procurement team, provide guidance to team members, and ensure that team goals are met.\n5. Collaborate with the supply chain team to coordinate internal and external resources, optimize procurement processes, improve efficiency, and reduce costs.\n6. Work with other departments to ensure the smooth operation of the supply chain and meet the company’s business needs.","requirements":"1.大学本科及以上学历，专业背景为商品与供应链管理、采购管理或相关领域。\n2.具备丰富的招商采购工作经验，至少5年以上相关岗位经验。\n3.具备良好的市场洞察力和分析能力，能够熟练运用市场调研和数据分析工具。\n4.具备出色的谈判和沟通能力，能够与供应商建立良好的合作关系。\n5.具备良好的团队管理能力，能够有效指导和激励团队成员，达成团队目标。\n6.具备较强的问题解决能力和决策能力，能够在复杂环境下做出准确的判断和决策。\n7.具备优秀的计划和组织能力，能够合理安排工作，有效管理时间和资源。\n\n1. Bachelor’s degree or above, preferably in marketing, supply chain management, food science, or related fields;\n2. 5+ years of experience in food procurement, preferably with exposure to diverse categories (e.g., FMCG, retail, or consumer goods).;\n3. Strong understanding of market trends, supply chain systems, and category management methods in the food industry;\n4. Excellent negotiation, data analysis, and market insight skills;\n5. Strong communication, coordination, and team management experience;\n6. High sense of responsibility, strong ability to work under pressure, and keen business acumen with an innovative mindset;\n7. Proficient in offic systems, and other data analysis tools.","description":"部门介绍\n美团的使命是“帮大家吃得更好，生活更好”，公司聚焦“零售 + 科技”战略，和广大商户与各类合作伙伴一起，努力为消费者提供品质生活，推动商品零售和服务零售在需求侧和供给侧的数字化转型。\n2018年9月20日，美团正式在港交所挂牌上市。美团将始终坚持以客户为中心，不断加大在科技研发方面的投入，更好承担社会责任，更多创造社会价值，与广大合作伙伴一起发展共赢。\n\n岗位职责\n1.负责商品与供应链管理-招商采购领域的业务规划和战略制定。\n2.负责供应商的筛选、评估、谈判和合同管理，确保供应商的质量、价格和交货时间符合公司的要求。\n3.负责市场调研和竞争对手分析，及时了解市场动态和趋势，制定相关的采购策略。\n4.管理采购团队，指导团队成员的工作，确保团队目标的达成。\n5.配合供应链团队，协调内外部资源，优化采购流程，提高效率和降低成本。\n6.与其他部门合作，确保供应链的顺畅运作，满足公司业务的需求。\n\n1. Responsible for business planning and strategy development in the food procurement sector.including water and beverages, grain and oil, non-staple foods, snacks, instant drinks, frozen foods & ice products, and maternal & baby products\n2. Responsible for supplier screening, evaluation, negotiation, and contract management to ensure that suppliers meet the company’s requirements for quality, price, and delivery times.\n3. Responsible for market research and competitor analysis to stay abreast of market dynamics and trends and formulate relevant procurement strategies.\n4. Manage the procurement team, provide guidance to team members, and ensure that team goals are met.\n5. Collaborate with the supply chain team to coordinate internal and external resources, optimize procurement processes, improve efficiency, and reduce costs.\n6. Work with other departments to ensure the smooth operation of the supply chain and meet the company’s business needs.\n\n岗位基本要求\n1.大学本科及以上学历，专业背景为商品与供应链管理、采购管理或相关领域。\n2.具备丰富的招商采购工作经验，至少5年以上相关岗位经验。\n3.具备良好的市场洞察力和分析能力，能够熟练运用市场调研和数据分析工具。\n4.具备出色的谈判和沟通能力，能够与供应商建立良好的合作关系。\n5.具备良好的团队管理能力，能够有效指导和激励团队成员，达成团队目标。\n6.具备较强的问题解决能力和决策能力，能够在复杂环境下做出准确的判断和决策。\n7.具备优秀的计划和组织能力，能够合理安排工作，有效管理时间和资源。\n\n1. Bachelor’s degree or above, preferably in marketing, supply chain management, food science, or related fields;\n2. 5+ years of experience in food procurement, preferably with exposure to diverse categories (e.g., FMCG, retail, or consumer goods).;\n3. Strong understanding of market trends, supply chain systems, and category management methods in the food industry;\n4. Excellent negotiation, data analysis, and market insight skills;\n5. Strong communication, coordination, and team management experience;\n6. High sense of responsibility, strong ability to work under pressure, and keen business acumen with an innovative mindset;\n7. Proficient in offic systems, and other data analysis tools.\n\n岗位亮点\n1.能够在招商采购领域发挥专业水准。\n2.工作城市为利雅得，具备较好的发展平台和机会。\n3.可以独挡一面负责招商采购工作，发挥能力和创造价值。\n4.具备丰富的工作经验和学历要求的背景，能够在该岗位上展现自己的专业知识和技能。\n5.岗位涉及到供应链管理和业务规划等多个领域，能够全面提升自己的综合能力。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4776662318","sourceKey":"meituan_social","company":"美团","title":"境外渠道管理负责人-港澳/日韩/东南亚/澳洲/欧美","city":"上海市/东京/香港特别行政区","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4776662318&jobShareType=1","duty":"1.负责制定和执行境外美食类目的渠道发展战略，除广告模式外，探索各区域供给模式。实现业务收入增长，达成目标。\n2.负责开拓和管理境外渠道合作伙伴，建立稳固的合作关系，拓展销售渠道。\n3.负责监控和分析市场动态，及时调整策略，优化渠道管理方案。\n4.协调内外部资源，推动项目实施，确保项目按时完成。","requirements":"1.大学本科及以上学历，具备丰富的业务开发和渠道管理经验。\n2.至少5年相关工作经验，有成功的渠道拓展和管理经验。有境内到餐、到综KA/CKA经验\n3.具备良好的团队管理能力和沟通协调能力，能有效带领团队实现业绩目标。\n4.具备较强的市场分析能力和战略规划能力，能够制定有效的发展计划。\n5.具备良好的跨部门协作能力，能够协调内外部资源，推动项目顺利进行。","description":"部门介绍\n大众点评作为国内重要的本地生活消费决策参考平台，多年来深耕本地生活消费领域，深受广大用户的信任和喜爱。我们的业务覆盖了吃喝玩乐游购娱等生活场景，通过极具辨识度和公信力的”星级“和”评价“产品，为数亿用户提供了全面、可信的消费决策依据。为更好满足用户探索城市的需求，大众点评在原有星级和评价的基础上，以信息流产品形式，助力用户发现更多好去处。大量优秀年轻同学的加入，为我们的团队注入了澎湃活力。我们相信，真实的生活是不可替代的，真实的感受是值得记录的，真实的美好是要被看到的。希望优秀的你能和我们一起，帮助广大用户在大众点评上发现更多好去处，找到属于自己的人间烟火气，共创美好生活。\n\n岗位职责\n1.负责制定和执行境外美食类目的渠道发展战略，除广告模式外，探索各区域供给模式。实现业务收入增长，达成目标。\n2.负责开拓和管理境外渠道合作伙伴，建立稳固的合作关系，拓展销售渠道。\n3.负责监控和分析市场动态，及时调整策略，优化渠道管理方案。\n4.协调内外部资源，推动项目实施，确保项目按时完成。\n\n岗位基本要求\n1.大学本科及以上学历，具备丰富的业务开发和渠道管理经验。\n2.至少5年相关工作经验，有成功的渠道拓展和管理经验。有境内到餐、到综KA/CKA经验\n3.具备良好的团队管理能力和沟通协调能力，能有效带领团队实现业绩目标。\n4.具备较强的市场分析能力和战略规划能力，能够制定有效的发展计划。\n5.具备良好的跨部门协作能力，能够协调内外部资源，推动项目顺利进行。\n\n岗位亮点\n大众点评作为国内重要的本地生活消费决策参考平台，多年来深耕本地生活消费领域，深受广大用户的信任和喜爱。我们的业务覆盖了吃喝玩乐游购娱等生活场景，通过极具辨识度和公信力的”星级“和”评价“产品，为数亿用户提供了全面、可信的消费决策依据。为更好满足用户探索城市的需求，大众点评在原有星级和评价的基础上，以信息流产品形式，助力用户发现更多好去处。大量优秀年轻同学的加入，为我们的团队注入了澎湃活力。我们相信，真实的生活是不可替代的，真实的感受是值得记录的，真实的美好是要被看到的。希望优秀的你能和我们一起，帮助广大用户在大众点评上发现更多好去处，找到属于自己的人间烟火气，共创美好生活。\n1.丰富的业务开发和渠道管理经验，有机会参与和推动公司境外业务的发展。\n2.工作地点可以在上海或者香港，负责境外多区域，了解全球业态差异，拓展人际关系和视野。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4419209700","sourceKey":"meituan_social","company":"美团","title":"品类采控负责人","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4419209700&jobShareType=1","duty":"1.带领团队基于需求预测，输出品类备货计划，并通过备货策略调整、供应商履约/起订周转优化等策略，优交付品类缺货/周转/不健康优化的目标；\n2.带领团队探索供应链进向成本优化的机会点，提升自提渗透率、装载率、大车型占比等指标，优化进向成本；\n3.带领团队探索自动化的机会点，提升团队运营效率；\n4.与品类采购深度共建，探索供应链优化机会点，推动品类销售增长与UE改善。","requirements":"1、具备3年以上团队管理经验，具备较好的供应链专业知识，积极主动，有较强的自驱力；\n2、熟练掌握各类办公软件，具有较强的逻辑思考能力、数据分析能力、复杂问题的拆解能力；\n3、具备沟通、协同、推动影响力。\n4、从事过酒饮/蛋品采控经验优先；","description":"部门介绍\n快驴进货是美团旗下的餐饮供应链平台，帮助餐饮商户以更低成本、更高效率来获取安全可靠的食材供应，让餐饮采购更简单。快驴进货同步发展“自营+平台”的业务模式，在采购环节一方面向上游供应商直采大宗商品，另一方面引入各地批发商，助力平台伙伴共同发展；在销售环节既有自建团队进行市场、客户拓展，又帮助各地批发商拓展业务；同时自建仓储管理系统、配送网络与团队，为客户提供优质履约服务。\n截至2022年，快驴进货布局了全国41个城市，为百万家商户提供“全、省、稳、好”的餐饮供应链服务。我们拥有3000+品牌食材、超5万SKU商品、超28万商品资质，并提供源头严审核、食品安全严把关、24小时无忧售后的全面保障，实现手机下单、送货上门的高效采购模式，帮百万商家节省了采购时间与成本，助力平台伙伴共同发展，在万亿市场共享机遇。\n在这里，你将收获完善的员工发展机制及学习体系，与各界专家一起深度参与餐饮供应链业务的发展。欢迎优秀的你加入美团快驴进货，与我们一起成长，一起更好！\n\n岗位职责\n1.带领团队基于需求预测，输出品类备货计划，并通过备货策略调整、供应商履约/起订周转优化等策略，优交付品类缺货/周转/不健康优化的目标；\n2.带领团队探索供应链进向成本优化的机会点，提升自提渗透率、装载率、大车型占比等指标，优化进向成本；\n3.带领团队探索自动化的机会点，提升团队运营效率；\n4.与品类采购深度共建，探索供应链优化机会点，推动品类销售增长与UE改善。\n\n岗位基本要求\n1、具备3年以上团队管理经验，具备较好的供应链专业知识，积极主动，有较强的自驱力；\n2、熟练掌握各类办公软件，具有较强的逻辑思考能力、数据分析能力、复杂问题的拆解能力；\n3、具备沟通、协同、推动影响力。\n4、从事过酒饮/蛋品采控经验优先；\n\n岗位亮点\n1.岗位视野广，涉及自营+平台模式，供应链进向、采购、库存、履约等多模块能力视野；\n2.团队氛围好，驱动力强；","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4794656917","sourceKey":"meituan_social","company":"美团","title":"用户体验产品","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4794656917&jobShareType=1","duty":"1. 端到端旅程体验Owner：对境外住宿用户全旅程的转化与体验指标负责，通过漏斗指标定位流失问题定位结构性问题并优化、\n2. 指标体系驱动迭代：基于旅程漏斗指标 + 一致性综合指数 ，识别影响规模×严重度的体验断点，输出有效的产品方案优化指标结果；\n3. 跨职能协作推进：在POD小团队内与数据分析、运营、工程紧密协作；同时横向协同供应链、客服、商家治理团队，推动归因边界外的上下游问题被正确认领和解决；\n4. 学习对标：可以通过内外部优秀解决方案学习输出适配业务发展阶段的产品方案及业务建议；","requirements":"1. 跨境业务经验，理解跨境预订的确认时效、多币种、多市场规则差异\n2. 有指标体系从0到1搭建经验\n3. 有Pod/Feature Team/跨职能小队工作模式经验，习惯小团队闭环而非大瀑布\n4. 数据能力较强，能与工程师对齐埋点与口径设计","description":"部门介绍\n美团酒店旅行业务涵盖酒店、民宿、机票、火车票、旅游度假、景点门票等各类住行游品类，通过与产业上下游的深度合作，为用户提供美好的旅游旅行体验。我们积极打造AI友好型组织，使用AI等新技术提升旅游服务的供需匹配效率，更好满足用户个性化、多样化的出游需求。我们持续深耕产业链，用数字化服务助力实体商家高质量经营，探索自有品牌等供给新模式，打造健康的商家生态，保障用户服务体验。为满足用户日益增长的跨境旅行需求，我们将聚焦亚太区域，打造高品质的住宿、交通、游玩等服务矩阵。\n这里有多元的业务布局、持续的成长空间，无论是向往的远方还是眼前的工作，一路都是风景相伴。加入我们，共同为用户创造旅游旅行中的高光时刻！\n\n岗位职责\n1. 端到端旅程体验Owner：对境外住宿用户全旅程的转化与体验指标负责，通过漏斗指标定位流失问题定位结构性问题并优化、\n2. 指标体系驱动迭代：基于旅程漏斗指标 + 一致性综合指数 ，识别影响规模×严重度的体验断点，输出有效的产品方案优化指标结果；\n3. 跨职能协作推进：在POD小团队内与数据分析、运营、工程紧密协作；同时横向协同供应链、客服、商家治理团队，推动归因边界外的上下游问题被正确认领和解决；\n4. 学习对标：可以通过内外部优秀解决方案学习输出适配业务发展阶段的产品方案及业务建议；\n\n岗位基本要求\n1. 跨境业务经验，理解跨境预订的确认时效、多币种、多市场规则差异\n2. 有指标体系从0到1搭建经验\n3. 有Pod/Feature Team/跨职能小队工作模式经验，习惯小团队闭环而非大瀑布\n4. 数据能力较强，能与工程师对齐埋点与口径设计\n\n岗位亮点\n1. 跨职能小队模式，离业务决策最近，产品+运营+研发坐在一起，数据闭环、高频实验、快速迭代。不需要用「向上汇报」换资源，团队本身就是决策单元。\n1. 真正的端到端，为从搜索到入住的完整用户旅程负责。没有「提需求→排队→等排期」的传统链路，你做的每个决策都能在指标上看","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4780306680","sourceKey":"meituan_social","company":"美团","title":"无人车业务部-廊坊城市BDM","city":"廊坊市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4780306680&jobShareType=1","duty":"1. 负责城市的无人车业务地面商户拓展与合作关系建立。\n2. 管理团队成员，进行团队建设和培训，提升团队销售能力和绩效。\n3. 跟进销售进展，协调内外部资源，确保销售工作顺利进行。\n4. 参与制定销售策略和市场推广活动，提升品牌知名度，牵引业绩冲高。","requirements":"1. 大学专科及以上学历，具备3年以上业务开发或地面拓展相关工作经验。\n2. 熟悉当地市场环境，具备较强的商户谈判与资源整合能力。\n3. 具备团队管理经验，能够有效激励团队并推动目标达成。\n4. 具备较强的执行力与目标要性。\n5. 具备物流、配送及共享出行行业经验者优先。","description":"部门介绍\n无人车业务部成立于2016年，旨在用无人驾驶技术提升物流配送的效率和体验。美团无人车以自研L4级自动驾驶软硬件技术为核心，与美团即时零售业务结合，形成满足公开道路、社区、工业园区等室外全场景下的无人配送整体解决方案。自2020年起，无人车已在北京、深圳等多地进入常态化试运营阶段，在城市复杂场景下提供针对餐饮外卖、生鲜食杂等货物的即时配送服务。2025年，美团无人车又踏上了同城货运的新探索，并在2026年持续扩大运营范围和车队数量，为更多城市带来智能配送服务。\n欢迎加入美团无人车团队，与我们一起用科技推动即时零售再升级！\n\n岗位职责\n1. 负责城市的无人车业务地面商户拓展与合作关系建立。\n2. 管理团队成员，进行团队建设和培训，提升团队销售能力和绩效。\n3. 跟进销售进展，协调内外部资源，确保销售工作顺利进行。\n4. 参与制定销售策略和市场推广活动，提升品牌知名度，牵引业绩冲高。\n\n岗位基本要求\n1. 大学专科及以上学历，具备3年以上业务开发或地面拓展相关工作经验。\n2. 熟悉当地市场环境，具备较强的商户谈判与资源整合能力。\n3. 具备团队管理经验，能够有效激励团队并推动目标达成。\n4. 具备较强的执行力与目标要性。\n5. 具备物流、配送及共享出行行业经验者优先。\n\n岗位亮点\n1. 加入前沿科技领域，参与无人车商业化落地的重要环节。\n2. 提供完善的培养体系和职业发展通道。\n3. 扁平化管理模式，拥有充分的自主决策与成长空间。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4756489254","sourceKey":"meituan_social","company":"美团","title":"小象超市-武汉线上店分区经理","city":"武汉市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4756489254&jobShareType=1","duty":"1.负责多门店的管理工作，配合总部各项营销策略的实施，负责线上APP各品类商品的日常的促销活动实施；\n2.进行日常经营管理工作，包含对各项运营指标进行监控和分析，确保销售达成；\n3.负责多门店月度、季节性活动规划及促销机制的落地；\n4.进行日常损耗管理和设备运营维护工作；\n5.新开门店开业前期筹备相关工作；\n6.对内域内人员的招聘，日常培训和人效管理工作。","requirements":"1.五年以上连锁门店/单体大店经营管理经验，熟悉新零售优先；\n2.对生鲜商品有一定的认知，熟悉门店促销管理、损耗控制管理、品类管理等；\n3.良好的沟通能力及跨部门团队合作精神，学习能力佳，责任心强，愿意接受挑战，以结果为导向；\n4.善于劳务人员的管理工作，熟悉与零售相关的法律法规；\n5.熟练操作办公软件及智能手机，热爱互联网行业。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1.负责多门店的管理工作，配合总部各项营销策略的实施，负责线上APP各品类商品的日常的促销活动实施；\n2.进行日常经营管理工作，包含对各项运营指标进行监控和分析，确保销售达成；\n3.负责多门店月度、季节性活动规划及促销机制的落地；\n4.进行日常损耗管理和设备运营维护工作；\n5.新开门店开业前期筹备相关工作；\n6.对内域内人员的招聘，日常培训和人效管理工作。\n\n岗位基本要求\n1.五年以上连锁门店/单体大店经营管理经验，熟悉新零售优先；\n2.对生鲜商品有一定的认知，熟悉门店促销管理、损耗控制管理、品类管理等；\n3.良好的沟通能力及跨部门团队合作精神，学习能力佳，责任心强，愿意接受挑战，以结果为导向；\n4.善于劳务人员的管理工作，熟悉与零售相关的法律法规；\n5.熟练操作办公软件及智能手机，热爱互联网行业。\n\n岗位亮点\n大平台，业务快速发展，完善的带训体系快速成长","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4795589848","sourceKey":"meituan_social","company":"美团","title":"招商经理","city":"南昌市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4795589848&jobShareType=1","duty":"1. 负责南昌市及周边地区的水果招商工作，拓展优质供应商资源。  \n2. 对接潜在合作商户，进行商务谈判并推动合作落地。  \n3. 协助制定品类招商策略，完成阶段性招商目标。  \n4. 维护现有商户关系，收集市场反馈并优化合作模式。","requirements":"1. 大学专科及以上学历，市场营销、工商管理或相关专业优先。  \n2. 具备3年以上招商或商务拓展相关工作经验。  \n3. 熟悉本地市场环境，具备较强的沟通谈判能力。  \n4. 具备良好的执行力和品类运营能力。","description":"部门介绍\n快驴进货是美团旗下的餐饮供应链平台，帮助餐饮商户以更低成本、更高效率来获取安全可靠的食材供应，让餐饮采购更简单。快驴进货同步发展“自营+平台”的业务模式，在采购环节一方面向上游供应商直采大宗商品，另一方面引入各地批发商，助力平台伙伴共同发展；在销售环节既有自建团队进行市场、客户拓展，又帮助各地批发商拓展业务；同时自建仓储管理系统、配送网络与团队，为客户提供优质履约服务。\n截至2022年，快驴进货布局了全国41个城市，为百万家商户提供“全、省、稳、好”的餐饮供应链服务。我们拥有3000+品牌食材、超5万SKU商品、超28万商品资质，并提供源头严审核、食品安全严把关、24小时无忧售后的全面保障，实现手机下单、送货上门的高效采购模式，帮百万商家节省了采购时间与成本，助力平台伙伴共同发展，在万亿市场共享机遇。\n在这里，你将收获完善的员工发展机制及学习体系，与各界专家一起深度参与餐饮供应链业务的发展。欢迎优秀的你加入美团快驴进货，与我们一起成长，一起更好！\n\n岗位职责\n1. 负责南昌市及周边地区的水果招商工作，拓展优质供应商资源。  \n2. 对接潜在合作商户，进行商务谈判并推动合作落地。  \n3. 协助制定品类招商策略，完成阶段性招商目标。  \n4. 维护现有商户关系，收集市场反馈并优化合作模式。\n\n岗位基本要求\n1. 大学专科及以上学历，市场营销、工商管理或相关专业优先。  \n2. 具备3年以上招商或商务拓展相关工作经验。  \n3. 熟悉本地市场环境，具备较强的沟通谈判能力。  \n4. 具备良好的执行力和品类运营能力。\n\n岗位亮点\n1. 提供完善的培训体系和职业发展通道。  \n2. 团队氛围开放，鼓励创新与主动担当。  \n3. 享有具有竞争力的薪酬及绩效激励机制。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4794524042","sourceKey":"meituan_social","company":"美团","title":"新行业行业运营","city":"上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4794524042&jobShareType=1","duty":"1、负责新行业的探索和研究，分析用户痛点，挖掘用户的核心需求；\n2、基于用户的需求及对商家和服务的充分理解，根据行业发展目标，制定并迭代相关运营规则、策略，并高效落地执行；\n3、协助制定并拆解阶段性目标，追踪完成效果，深入进行数据分析，发现问题，及时干预；\n4、迭代行业规则，牵引商家提供优质服务，治理违规行为，保障用户履约质量\n5、与产品、服务、上下游协作，保障业务运转效率和客户体验；","requirements":"1. 大学本科及以上学历，3年以上产品运营或商家运营相关工作经验。  \n2. 具备新行业探索能力，有从0到1搭建行业运营体系经验者优先。  \n3. 数据敏感度高，熟练使用SQL等工具进行数据分析与策略制定。  \n4. 具备优秀的沟通协调能力与跨团队协作能力，能推动多方达成共识。  \n5. 逻辑清晰，具备较强的项目管理能力 \n6、强大好奇心与探索精神、强烈的责任心和自我驱动力。","description":"部门介绍\n美团服务零售事业部下设乐生活业务部、易生活业务部、进场零售业务部以及中小城市发展部四大业务部门，旨在通过提供丰富、可靠、实惠的服务与商品满足用户各类生活需求。我们所处的服务零售行业是一个具有万亿规模的市场，覆盖足疗洗浴、酒吧KTV、运动健身、美发美甲、教育培训、亲子游乐、家政洗涤维修、摄影写真等数十个服务消费细分领域，同时延伸至超市便利、美妆个护、3C数码、服饰珠宝、运动户外、商场购物中心等实体零售到店消费场景，连接数十万品牌商户与线下门店。作为商家和行业的小帮手，我们持续深入服务零售与实体零售产业链，用AI等技术推动行业变革，帮助商家提升经营效率、实现高效的线上化经营与到店转化，优化消费者服务体验，提供安心、放心的履约保障。这里有着多元的业务布局，有着富有挑战和影响力的工作内容，为你提供丰富的视野、持续的成长和发展机会，引领你发现更多可能。期待和你在“随时随地，美好生活”的愿景指引下，共建美好的生活服务体验、健康的商家生态与高质量的经营结果。\n\n岗位职责\n1、负责新行业的探索和研究，分析用户痛点，挖掘用户的核心需求；\n2、基于用户的需求及对商家和服务的充分理解，根据行业发展目标，制定并迭代相关运营规则、策略，并高效落地执行；\n3、协助制定并拆解阶段性目标，追踪完成效果，深入进行数据分析，发现问题，及时干预；\n4、迭代行业规则，牵引商家提供优质服务，治理违规行为，保障用户履约质量\n5、与产品、服务、上下游协作，保障业务运转效率和客户体验；\n\n岗位基本要求\n1. 大学本科及以上学历，3年以上产品运营或商家运营相关工作经验。  \n2. 具备新行业探索能力，有从0到1搭建行业运营体系经验者优先。  \n3. 数据敏感度高，熟练使用SQL等工具进行数据分析与策略制定。  \n4. 具备优秀的沟通协调能力与跨团队协作能力，能推动多方达成共识。  \n5. 逻辑清晰，具备较强的项目管理能力 \n6、强大好奇心与探索精神、强烈的责任心和自我驱动力。\n\n具备以下条件优先\n1、具备商务服务、金融等行业运营者优先 2、有平台行业产品运营经验者优先\n\n岗位亮点\n1、能够覆盖多种行业的全链路研究，端到端地深入产业；\n2、优秀的团队伙伴，良好的学习分享氛围。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4766572279","sourceKey":"meituan_social","company":"美团","title":"快驴厦门餐厨用品招商专员","city":"厦门市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4766572279&jobShareType=1","duty":"1.负责区域的餐厨用品招商业务的开展，根据公司战略和市场需求，制定并执行招商计划。\n\n2.研究市场供应情况，寻找并评估潜在的供应商，建立并维护供应商数据库。\n\n3.负责与供应商进行谈判，确保招商工作正常开展并拿到结果。\n\n4.跟踪市场价格变化，掌握行业动态，及时调整招商策略和供应链管理方案。\n\n5.对本地市场及产地资源熟悉，能自主开拓新的优质商家，完成公司招商任务；\n\n6.监督商品质量，确保供应商商品符合公司标准和客户需求。\n\n7.协调与其他部门的合作，保证招商流程的顺利进行，提高效率和成本控制。\n\n8.领导安排的其他工作。","requirements":"1.大学专科以上学历，专业不限，有供应链管理或相关领域背景者优先考虑。\n\n2.具备3年以上招商采购或相关工作经验，熟悉餐厨酒饮市场行情和供应链管理流程。\n\n3.具备良好的市场洞察力和商业谈判能力，能够准确判断市场需求和供应商的能力。\n\n4. 熟悉采购工作流程，对价格谈判、订单管理、供应商开发等具有丰富的经验；\n\n5.具备较强的团队合作能力和沟通协调能力，能够与供应商和内部各部门有效配合。\n\n6.具备较强的分析和解决问题的能力，能够及时应对采购过程中的各种挑战和风险。\n\n7. 工作态度积极，适应弹性工作，搭建和管理好在线商品，肯吃苦耐劳。","description":"部门介绍\n快驴进货是美团旗下的餐饮供应链平台，帮助餐饮商户以更低成本、更高效率来获取安全可靠的食材供应，让餐饮采购更简单。快驴进货同步发展“自营+平台”的业务模式，在采购环节一方面向上游供应商直采大宗商品，另一方面引入各地批发商，助力平台伙伴共同发展；在销售环节既有自建团队进行市场、客户拓展，又帮助各地批发商拓展业务；同时自建仓储管理系统、配送网络与团队，为客户提供优质履约服务。\n截至2022年，快驴进货布局了全国41个城市，为百万家商户提供“全、省、稳、好”的餐饮供应链服务。我们拥有3000+品牌食材、超5万SKU商品、超28万商品资质，并提供源头严审核、食品安全严把关、24小时无忧售后的全面保障，实现手机下单、送货上门的高效采购模式，帮百万商家节省了采购时间与成本，助力平台伙伴共同发展，在万亿市场共享机遇。\n在这里，你将收获完善的员工发展机制及学习体系，与各界专家一起深度参与餐饮供应链业务的发展。欢迎优秀的你加入美团快驴进货，与我们一起成长，一起更好！\n\n岗位职责\n1.负责区域的餐厨用品招商业务的开展，根据公司战略和市场需求，制定并执行招商计划。\n\n2.研究市场供应情况，寻找并评估潜在的供应商，建立并维护供应商数据库。\n\n3.负责与供应商进行谈判，确保招商工作正常开展并拿到结果。\n\n4.跟踪市场价格变化，掌握行业动态，及时调整招商策略和供应链管理方案。\n\n5.对本地市场及产地资源熟悉，能自主开拓新的优质商家，完成公司招商任务；\n\n6.监督商品质量，确保供应商商品符合公司标准和客户需求。\n\n7.协调与其他部门的合作，保证招商流程的顺利进行，提高效率和成本控制。\n\n8.领导安排的其他工作。\n\n岗位基本要求\n1.大学专科以上学历，专业不限，有供应链管理或相关领域背景者优先考虑。\n\n2.具备3年以上招商采购或相关工作经验，熟悉餐厨酒饮市场行情和供应链管理流程。\n\n3.具备良好的市场洞察力和商业谈判能力，能够准确判断市场需求和供应商的能力。\n\n4. 熟悉采购工作流程，对价格谈判、订单管理、供应商开发等具有丰富的经验；\n\n5.具备较强的团队合作能力和沟通协调能力，能够与供应商和内部各部门有效配合。\n\n6.具备较强的分析和解决问题的能力，能够及时应对采购过程中的各种挑战和风险。\n\n7. 工作态度积极，适应弹性工作，搭建和管理好在线商品，肯吃苦耐劳。\n\n具备以下条件优先\n数据分析能力\n\n岗位亮点\n1.参与城市内部市场的发展，有机会与一线供应商合作，积累丰富的行业经验。2.承担城市内部招商业务的全面责任，能够在工作中发挥较大的自主性和创造力。3.通过与内外部团队的合作，能够提升自身的团队管理和项目管理能力，为个人职业发展打下坚实基础。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4632187022","sourceKey":"meituan_social","company":"美团","title":"仓储主管","city":"深圳市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4632187022&jobShareType=1","duty":"1、现场运营管理\n负责仓内日常运营管理，确保生产作业正常有序进行；\n根据业务量合理安排分拣计划、班次及人员配置；\n监督分拣流程执行情况，保障货物及时、准确分拣；\n协调收货、码拖、装车等环节，提高整体作业效率。\n2、人员管理\n负责分拣员工的排班、考勤及工作安排；\n组织员工岗前培训及技能提升培训；\n监督员工操作规范，提升团队执行力；\n负责团队绩效考核及员工日常管理。\n3、质量与效率控制\n监控分拣准确率、错分率、破损率等关键指标；\n分析运营数据，持续优化分拣效率和流程；\n及时处理异常件、滞留件及客户投诉问题；\n推动现场标准化作业管理。\n4、安全管理\n负责现场安全生产管理，落实安全操作规范；\n定期检查设备、消防及作业环境安全；\n预防和处理现场突发事件及安全隐患；\n督导员工正确使用分拣设备和工具。\n5、设备与物资管理\n负责分拣设备日常检查与维护协调；\n管理现场耗材、工具及物资使用情况；\n降低运营损耗，控制运营成本。\n6、跨部门沟通协调\n与订货、运输、服务站等部门保持沟通；\n协调处理订单异常及物流问题；\n配合公司完成各项运营指标及专项任务。","requirements":"1. 大学专科及以上学历，物流、供应链或相关专业优先。  \n2. 3年以上物流仓储或运营支持相关工作经验。  \n3. 熟悉仓储管理系统及办公软件，具备基础数据分析能力。  \n4. 具备较强的沟通协调能力和团队协作精神。  \n5. 能适应快节奏工作环境，学习能力强。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1、现场运营管理\n负责仓内日常运营管理，确保生产作业正常有序进行；\n根据业务量合理安排分拣计划、班次及人员配置；\n监督分拣流程执行情况，保障货物及时、准确分拣；\n协调收货、码拖、装车等环节，提高整体作业效率。\n2、人员管理\n负责分拣员工的排班、考勤及工作安排；\n组织员工岗前培训及技能提升培训；\n监督员工操作规范，提升团队执行力；\n负责团队绩效考核及员工日常管理。\n3、质量与效率控制\n监控分拣准确率、错分率、破损率等关键指标；\n分析运营数据，持续优化分拣效率和流程；\n及时处理异常件、滞留件及客户投诉问题；\n推动现场标准化作业管理。\n4、安全管理\n负责现场安全生产管理，落实安全操作规范；\n定期检查设备、消防及作业环境安全；\n预防和处理现场突发事件及安全隐患；\n督导员工正确使用分拣设备和工具。\n5、设备与物资管理\n负责分拣设备日常检查与维护协调；\n管理现场耗材、工具及物资使用情况；\n降低运营损耗，控制运营成本。\n6、跨部门沟通协调\n与订货、运输、服务站等部门保持沟通；\n协调处理订单异常及物流问题；\n配合公司完成各项运营指标及专项任务。\n\n岗位基本要求\n1. 大学专科及以上学历，物流、供应链或相关专业优先。  \n2. 3年以上物流仓储或运营支持相关工作经验。  \n3. 熟悉仓储管理系统及办公软件，具备基础数据分析能力。  \n4. 具备较强的沟通协调能力和团队协作精神。  \n5. 能适应快节奏工作环境，学习能力强。\n\n岗位亮点\n1. 参与核心运营环节，快速积累行业经验。  \n2. 提供系统化培训，助力个人职业发展。  \n3. 团队氛围开放，注重员工成长与反馈。  \n4. 工作地点位于深圳，交通便利。  \n5. 有机会接触前沿物流技术与管理实践。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4736467765","sourceKey":"meituan_social","company":"美团","title":"流量安全专家","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4736467765&jobShareType=1","duty":"1、负责美团新一代“以Agent为核心”的智能流量风控能力构建，规划并推进流量防护能力（前端+服务端）的智能化运营，向业务线提供基于服务端及各类前端（app、小程序、H5等）的流量防护能力。\n2、运用数据分析和AI工具（Agent、Skill等），持续发现、分析和对抗线上各类流量攻击，并利用技术手段进行深度情报分析与溯源，定位攻击源。\n3、主动跟进业界在AI安全运营（如安全智能、自动化响应）中的最佳实践，结合美团业务实际，制定智能化运营的演进路径与建设规划。\n4、协调各安全协同团队和业务方，提升流量安全的纵深防御以及运营效率，并持续优化迭代。","requirements":"1、本科及以上学历，2年以上前端、账号或流量安全相关工作经验；\n2、有长期流量风险对抗经验，对常见的防御措施（策略、前端、API、行为、产品形态等任一）有深入理解；\n3、具备较强的风险洞察能力和责任心，能够根据业务诉求，评估风险严重程度并制定解决方案；\n4、具备良好的沟通能力和项目推进能力，能主动协调多部门成员，建设项目效果衡量指标，确保方案高效落地。 \n5、具备明确的AI技术应用经验，熟悉AI Agent的基本架构与工作流，能够将业务问题转化为AI可解的任务范式。","description":"部门介绍\n基础研发平台是美团的核心技术平台，立足于“零售+科技”的战略定位，通过打造人工智能、大数据、云计算、安全等核心技术能力，以及研发效能平台、企业应用平台等公共服务，为业务提供稳定安全、扩展易用、技术领先的平台技术和产品服务。\n在这里，我们会参与到最前沿的技术研发和探索；能够接触超规模集群、海量数据，挑战高复杂业务场景，有机会与业界一流的工程师一起并肩前行。\n在这里，我们有超强的技术氛围，持续向社区贡献业界实践，加速行业技术发展；我们有完善的互联网学习生态圈，重视底层逻辑和方法论，助力职业生涯的非线性成长。\n真诚地邀请你，和我们一起驱动技术发展，创造行业价值。\n\n岗位职责\n1、负责美团新一代“以Agent为核心”的智能流量风控能力构建，规划并推进流量防护能力（前端+服务端）的智能化运营，向业务线提供基于服务端及各类前端（app、小程序、H5等）的流量防护能力。\n2、运用数据分析和AI工具（Agent、Skill等），持续发现、分析和对抗线上各类流量攻击，并利用技术手段进行深度情报分析与溯源，定位攻击源。\n3、主动跟进业界在AI安全运营（如安全智能、自动化响应）中的最佳实践，结合美团业务实际，制定智能化运营的演进路径与建设规划。\n4、协调各安全协同团队和业务方，提升流量安全的纵深防御以及运营效率，并持续优化迭代。\n\n岗位基本要求\n1、本科及以上学历，2年以上前端、账号或流量安全相关工作经验；\n2、有长期流量风险对抗经验，对常见的防御措施（策略、前端、API、行为、产品形态等任一）有深入理解；\n3、具备较强的风险洞察能力和责任心，能够根据业务诉求，评估风险严重程度并制定解决方案；\n4、具备良好的沟通能力和项目推进能力，能主动协调多部门成员，建设项目效果衡量指标，确保方案高效落地。 \n5、具备明确的AI技术应用经验，熟悉AI Agent的基本架构与工作流，能够将业务问题转化为AI可解的任务范式。\n\n具备以下条件优先\n1、有大型互联网公司流量安全建设和运营者经验。\n2、有高强度风控领域对抗经验，深入理解各类型风控防御措施，并能够灵活应用。\n3、有使用Agent框架 或基于大模型构建行业解决方案（如智能问答、决策引擎、代码生成）的实践经验者优先。\n\n岗位亮点\n1、参与构建以AI和Agent技术为核心的下一代智能流量安全系统，技术挑战与成长空间兼具。\n2、为业务发展提供关键的数据防护能力，受到业务和公司的高度关注和认可。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4735731096","sourceKey":"meituan_social","company":"美团","title":"客服大模型评测负责人","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4735731096&jobShareType=1","duty":"评测体系建设：面向用户交互场景，设计覆盖基座模型、端到端Agent、用户体验等场景的评测框架和标准，保障评测可解释可复现，并主导Benchmark数据集构建与持续迭代，防控数据污染与评测失效\n\n搭建自动化评测工程：通过judge model等自动评测流水线，设计多评委协作机制，控制评测偏见，持续提升自动评测与人工标注的一致性，推动评测提效\n\n数据生产与质量管控：主导评测/训练数据合成方案设计，建立标注规范与质检体系，同时与数据团队协作，保障大规模数据生产的稳定性与准确性\n\n模型迭代支撑：输出结构化评测报告，将评测结论转化为可落地的优化建议，与模型训练团队深度协作，建立\"评测→优化→再评测\"闭环\n\n沉淀团队评测方法论，输出可复用框架与工具","requirements":"计算机、人工智能、统计学、数学或相关专业,本科及以上学历，3年大模型评测工作经验以上优先\n\n熟悉业界主流评测工具集和评测集，有独立设计评测框架和评测标准经验\n\n了解Python语言，有实际开发、测试开发或评测工具开发经验优先\n\n具备模型和AI产品分析能力，根据评测结论提出优化建议，驱动优化落地\n\n关注业界前沿AI模型和产品发展，关注AI前沿评测方法发展，并转化为内部评测实践，并且能够熟练借助AI工具进行快速验证，具备Vibe coding或自动化流程搭建能力，支持方案快速验证与落地迭代\n\n积极主动，对AI和大模型领域有激情，喜欢找办法解决问题，具备较强的团队协作能力、组织协调能力、复杂问题解决能力","description":"部门介绍\n核心本地商业（Core Local Commerce）是美团“零售+科技”战略的重要载体，涵盖了到店餐饮、服务零售、酒店旅行、外卖、履约配送、闪购、医药健康等多个业务，覆盖了超过200个消费场景，致力于通过“随时随地”的商品和服务，满足消费者的多样性需求，帮大家吃得更好，生活更好。核心本地商业扎根本地消费，围绕消费者的“吃、住、行、游、购、娱”进行深度创新，引领发展了即时零售、团购等多种消费业态，并在全国范围内广泛投资发展本地供给、履约平台等设施，助力创造产业、带动就业。基于多年的持续投入，核心本地商业打造了连接全国超过一千万中小微企业的服务体系，以及全球最大的即时配送网络。由核心本地商业所推行的30分钟“万物到家”体系，已覆盖全国2800多个城镇，为数亿用户提供优质的商品与服务。发展过程中，核心本地商业有效助力商超、连锁、本地小店等各类实体经济主体扩大交易规模、降低交易成本。截至目前，核心本地商业日均创造订单量数千万笔，助力千万商户实现了高质量发展。未来，核心本地商业将继续践行美团“零售+科技”战略，通过更大的投资，更多的技术创新，支持、培育消费新业态，为促进消费、服务民生、带动就业作出力所能及的贡献。欢迎优秀的你加入核心本地商业，我们携手助力市场繁荣，为用户创造更好的消费体验。\n\n岗位职责\n评测体系建设：面向用户交互场景，设计覆盖基座模型、端到端Agent、用户体验等场景的评测框架和标准，保障评测可解释可复现，并主导Benchmark数据集构建与持续迭代，防控数据污染与评测失效\n\n搭建自动化评测工程：通过judge model等自动评测流水线，设计多评委协作机制，控制评测偏见，持续提升自动评测与人工标注的一致性，推动评测提效\n\n数据生产与质量管控：主导评测/训练数据合成方案设计，建立标注规范与质检体系，同时与数据团队协作，保障大规模数据生产的稳定性与准确性\n\n模型迭代支撑：输出结构化评测报告，将评测结论转化为可落地的优化建议，与模型训练团队深度协作，建立\"评测→优化→再评测\"闭环\n\n沉淀团队评测方法论，输出可复用框架与工具\n\n岗位基本要求\n计算机、人工智能、统计学、数学或相关专业,本科及以上学历，3年大模型评测工作经验以上优先\n\n熟悉业界主流评测工具集和评测集，有独立设计评测框架和评测标准经验\n\n了解Python语言，有实际开发、测试开发或评测工具开发经验优先\n\n具备模型和AI产品分析能力，根据评测结论提出优化建议，驱动优化落地\n\n关注业界前沿AI模型和产品发展，关注AI前沿评测方法发展，并转化为内部评测实践，并且能够熟练借助AI工具进行快速验证，具备Vibe coding或自动化流程搭建能力，支持方案快速验证与落地迭代\n\n积极主动，对AI和大模型领域有激情，喜欢找办法解决问题，具备较强的团队协作能力、组织协调能力、复杂问题解决能力\n\n具备以下条件优先\n对ClaudeCode和OpenClaw等agent框架有深入了解或丰富使用经验者优先\n\n岗位亮点\n紧跟人工智能行业进展，接触到前沿技术和行业趋势，磨练出对人工智能的独到见解\n\n参与大模型评测的全流程体系，了解从理论到工程实践的全面技能\n\n与一流的人工智能团队合作，快速成长，提升自身能力\n\n有机会参与部门的重点项目，跨足不同领域，拓宽人工智能技术的应用范围","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4766503451","sourceKey":"meituan_social","company":"美团","title":"快驴杭州餐厨用品招商专员","city":"杭州市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4766503451&jobShareType=1","duty":"1.负责区域的餐厨用品招商业务的开展，根据公司战略和市场需求，制定并执行招商计划。\n\n2.研究市场供应情况，寻找并评估潜在的供应商，建立并维护供应商数据库。\n\n3.负责与供应商进行谈判，确保招商工作正常开展并拿到结果。\n\n4.跟踪市场价格变化，掌握行业动态，及时调整招商策略和供应链管理方案。\n\n5.对本地市场及产地资源熟悉，能自主开拓新的优质商家，完成公司招商任务；\n\n6.监督商品质量，确保供应商商品符合公司标准和客户需求。\n\n7.协调与其他部门的合作，保证招商流程的顺利进行，提高效率和成本控制。\n\n8.领导安排的其他工作。","requirements":"1.大学专科以上学历，专业不限，有供应链管理或相关领域背景者优先考虑。\n\n2.具备3年以上招商采购或相关工作经验，熟悉餐厨用品市场行情和供应链管理流程。\n\n3.具备良好的市场洞察力和商业谈判能力，能够准确判断市场需求和供应商的能力。\n\n4. 熟悉采购工作流程，对价格谈判、订单管理、供应商开发等具有丰富的经验；\n\n5.具备较强的团队合作能力和沟通协调能力，能够与供应商和内部各部门有效配合。\n\n6.具备较强的分析和解决问题的能力，能够及时应对采购过程中的各种挑战和风险。\n\n7. 工作态度积极，适应弹性工作，搭建和管理好在线商品，肯吃苦耐劳。","description":"部门介绍\n快驴进货是美团旗下的餐饮供应链平台，帮助餐饮商户以更低成本、更高效率来获取安全可靠的食材供应，让餐饮采购更简单。快驴进货同步发展“自营+平台”的业务模式，在采购环节一方面向上游供应商直采大宗商品，另一方面引入各地批发商，助力平台伙伴共同发展；在销售环节既有自建团队进行市场、客户拓展，又帮助各地批发商拓展业务；同时自建仓储管理系统、配送网络与团队，为客户提供优质履约服务。\n截至2022年，快驴进货布局了全国41个城市，为百万家商户提供“全、省、稳、好”的餐饮供应链服务。我们拥有3000+品牌食材、超5万SKU商品、超28万商品资质，并提供源头严审核、食品安全严把关、24小时无忧售后的全面保障，实现手机下单、送货上门的高效采购模式，帮百万商家节省了采购时间与成本，助力平台伙伴共同发展，在万亿市场共享机遇。\n在这里，你将收获完善的员工发展机制及学习体系，与各界专家一起深度参与餐饮供应链业务的发展。欢迎优秀的你加入美团快驴进货，与我们一起成长，一起更好！\n\n岗位职责\n1.负责区域的餐厨用品招商业务的开展，根据公司战略和市场需求，制定并执行招商计划。\n\n2.研究市场供应情况，寻找并评估潜在的供应商，建立并维护供应商数据库。\n\n3.负责与供应商进行谈判，确保招商工作正常开展并拿到结果。\n\n4.跟踪市场价格变化，掌握行业动态，及时调整招商策略和供应链管理方案。\n\n5.对本地市场及产地资源熟悉，能自主开拓新的优质商家，完成公司招商任务；\n\n6.监督商品质量，确保供应商商品符合公司标准和客户需求。\n\n7.协调与其他部门的合作，保证招商流程的顺利进行，提高效率和成本控制。\n\n8.领导安排的其他工作。\n\n岗位基本要求\n1.大学专科以上学历，专业不限，有供应链管理或相关领域背景者优先考虑。\n\n2.具备3年以上招商采购或相关工作经验，熟悉餐厨用品市场行情和供应链管理流程。\n\n3.具备良好的市场洞察力和商业谈判能力，能够准确判断市场需求和供应商的能力。\n\n4. 熟悉采购工作流程，对价格谈判、订单管理、供应商开发等具有丰富的经验；\n\n5.具备较强的团队合作能力和沟通协调能力，能够与供应商和内部各部门有效配合。\n\n6.具备较强的分析和解决问题的能力，能够及时应对采购过程中的各种挑战和风险。\n\n7. 工作态度积极，适应弹性工作，搭建和管理好在线商品，肯吃苦耐劳。\n\n具备以下条件优先\n数据分析能力\n\n岗位亮点\n1.参与城市内部市场的发展，有机会与一线供应商合作，积累丰富的行业经验。2.承担城市内部招商业务的全面责任，能够在工作中发挥较大的自主性和创造力。3.通过与内外部团队的合作，能够提升自身的团队管理和项目管理能力，为个人职业发展打下坚实基础。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4791893659","sourceKey":"meituan_social","company":"美团","title":"榜单运营","city":"上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4791893659&jobShareType=1","duty":"1、负责大众点评指数榜单的运营工作，以提升榜单影响力为目标，结合榜单定位输出营销运营计划并推进落地。\n2、积极联动市场和业务团队，进行持续的榜单活动运营，扩大用户的使用规模、强化榜单的认知和心智。\n3、深入本地生活行业，挖掘用户场景，探索榜单在低线城市及各细分场景的增长机会，为榜单的规模增长负责。","requirements":"1、本科及以上学历，5年以上互联网运营工作经验，喜欢吃喝玩乐，有榜单或营销活动运营经验更佳\n2、熟悉本地生活行业，对用户的不同找店场景有认知，能制定有效的执行策略和解决方案\n3、对事物具有强烈的好奇心和自驱力，能从复杂业务中发现核心痛点并推动优化\n4、较好的团队协作意识与项目管理能力，积极促成跨团队之间的高效合作","description":"部门介绍\n大众点评作为国内重要的本地生活消费决策参考平台，多年来深耕本地生活消费领域，深受广大用户的信任和喜爱。我们的业务覆盖了吃喝玩乐游购娱等生活场景，通过极具辨识度和公信力的”星级“和”评价“产品，为数亿用户提供了全面、可信的消费决策依据。为更好满足用户探索城市的需求，大众点评在原有星级和评价的基础上，以信息流产品形式，助力用户发现更多好去处。大量优秀年轻同学的加入，为我们的团队注入了澎湃活力。我们相信，真实的生活是不可替代的，真实的感受是值得记录的，真实的美好是要被看到的。希望优秀的你能和我们一起，帮助广大用户在大众点评上发现更多好去处，找到属于自己的人间烟火气，共创美好生活。\n\n岗位职责\n1、负责大众点评指数榜单的运营工作，以提升榜单影响力为目标，结合榜单定位输出营销运营计划并推进落地。\n2、积极联动市场和业务团队，进行持续的榜单活动运营，扩大用户的使用规模、强化榜单的认知和心智。\n3、深入本地生活行业，挖掘用户场景，探索榜单在低线城市及各细分场景的增长机会，为榜单的规模增长负责。\n\n岗位基本要求\n1、本科及以上学历，5年以上互联网运营工作经验，喜欢吃喝玩乐，有榜单或营销活动运营经验更佳\n2、熟悉本地生活行业，对用户的不同找店场景有认知，能制定有效的执行策略和解决方案\n3、对事物具有强烈的好奇心和自驱力，能从复杂业务中发现核心痛点并推动优化\n4、较好的团队协作意识与项目管理能力，积极促成跨团队之间的高效合作\n\n岗位亮点\n1、随着市场的快速变化，榜单业务需要不断进行新机会的探索和突破，有机会锻炼全链路的运营能力\n2、能够参与到本地生活行业前沿的榜单产品运营工作，在对应领域有较大的发挥空间和职业发展机会\n3、工作环境轻松愉快，团队氛围融洽，注重员工的成长和发展","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4772873963","sourceKey":"meituan_social","company":"美团","title":"商家运营管理专员（履约方向）","city":"上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4772873963&jobShareType=1","duty":"1.基于业务对商家的管理机制，根据业务需求持续进行管理指标考核输出和管控动作落地执行；\n2.完善监控体系，监督商家落地的过程，确保商家按标准完成服务；\n3.定期组织城市及内部相关方进行复盘及培训，提升规则意识，优化商家管理与风险防控机制。","requirements":"1.3年以上工作经验，有商家管理或商家治理经验，具备本地生活行业服务商管理经验或有相关行业服务商从业经验者优先；\n2.具有较强的思维逻辑、沟通能力、职业敏感度、风控意识及极强的责任心；\n3.具备较强的项目管理能力，能够高效完成项目的规划和执行；\n4.善于发现问题和通过规则的手段解决问题；\n5.熟练使用日常办公软件，具有较强的数据分析能力，熟练使用SQL者更佳。","description":"部门介绍\n美团服务零售事业部下设乐生活业务部、易生活业务部、进场零售业务部以及中小城市发展部四大业务部门，旨在通过提供丰富、可靠、实惠的服务与商品满足用户各类生活需求。我们所处的服务零售行业是一个具有万亿规模的市场，覆盖足疗洗浴、酒吧KTV、运动健身、美发美甲、教育培训、亲子游乐、家政洗涤维修、摄影写真等数十个服务消费细分领域，同时延伸至超市便利、美妆个护、3C数码、服饰珠宝、运动户外、商场购物中心等实体零售到店消费场景，连接数十万品牌商户与线下门店。作为商家和行业的小帮手，我们持续深入服务零售与实体零售产业链，用AI等技术推动行业变革，帮助商家提升经营效率、实现高效的线上化经营与到店转化，优化消费者服务体验，提供安心、放心的履约保障。这里有着多元的业务布局，有着富有挑战和影响力的工作内容，为你提供丰富的视野、持续的成长和发展机会，引领你发现更多可能。期待和你在“随时随地，美好生活”的愿景指引下，共建美好的生活服务体验、健康的商家生态与高质量的经营结果。\n\n岗位职责\n1.基于业务对商家的管理机制，根据业务需求持续进行管理指标考核输出和管控动作落地执行；\n2.完善监控体系，监督商家落地的过程，确保商家按标准完成服务；\n3.定期组织城市及内部相关方进行复盘及培训，提升规则意识，优化商家管理与风险防控机制。\n\n岗位基本要求\n1.3年以上工作经验，有商家管理或商家治理经验，具备本地生活行业服务商管理经验或有相关行业服务商从业经验者优先；\n2.具有较强的思维逻辑、沟通能力、职业敏感度、风控意识及极强的责任心；\n3.具备较强的项目管理能力，能够高效完成项目的规划和执行；\n4.善于发现问题和通过规则的手段解决问题；\n5.熟练使用日常办公软件，具有较强的数据分析能力，熟练使用SQL者更佳。\n\n岗位亮点\n探索项目，参与0-1建设过程，快速迭代策略能力。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4685979678","sourceKey":"meituan_social","company":"美团","title":"绩效策略","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4685979678&jobShareType=1","duty":"1.绩效管理：根据业务发展阶段变化，聚焦核心策略导向，建立科学合理的绩效管理框架和评价体系，设计外卖业务考核方案，开展PDCA并持续优化以确保绩效体系的激励性，推动策略落地；\n\n2.目标管理：结合公司经营要求和各市场策略，搭建和迭代策略目标测算模型，负责事前、事中、事后目标管理；\n\n3.专项分析：主动发现业务经营问题，推进业务专题研究，快速拆解问题、搭建研究思路，利用有效的数据分析方法，输出有洞察力的分析结论并做好呈现；\n\n4.流程优化：对绩效管理流程及框架进行梳理分析，推进过程管理产品化，帮助业务相关方实时了解绩效进展，进行业绩的过程改善。","requirements":"1.本科或以上学历，商业分析、统计学、数学、财经类或理工科相关专业优先；\n\n2.3年以上数据/商业分析相关经验，有目标制定和绩效管理经历者优先；\n\n3.具有扎实的数理统计基本功，熟练掌握SQL进行数据提取与处理，能独立完成复杂业务分析 \n\n4.擅长结构化思维，能对业务目标及达成路径进行系统性拆解，输出可落地的策略建议；\n\n5.具备优秀的跨团队沟通能力，能清晰传递数据洞察并推动策略落地；自驱力强，能主动协调资源解决问题。\n\n6.了解AI工具，并可以应用AI工具为工作赋能提效。","description":"部门介绍\n美团外卖秉承“帮大家吃得更好，生活更好”的使命，始终聚焦于消费者用餐需求。我们通过科技连接消费者和商家，依托庞大的骑手团队，以“线上+线下”的业务模式，为消费者提供品质化、精细化、多样化的餐饮外卖服务。\n外卖事业部是为用户与商家提供全链路交易服务的业务组织，围绕餐饮外卖搭建了包含外卖业务与创新孵化业务在内的多个部门。\n我们的目标是帮助商家开源增收、提高经营效率，促进餐饮行业数字化，以及为更多用户提供更便捷更有品质的外卖服务。加入我们，一起为上亿用户提供更好的用餐体验，帮助大家吃得更好，生活更好！\n\n岗位职责\n1.绩效管理：根据业务发展阶段变化，聚焦核心策略导向，建立科学合理的绩效管理框架和评价体系，设计外卖业务考核方案，开展PDCA并持续优化以确保绩效体系的激励性，推动策略落地；\n\n2.目标管理：结合公司经营要求和各市场策略，搭建和迭代策略目标测算模型，负责事前、事中、事后目标管理；\n\n3.专项分析：主动发现业务经营问题，推进业务专题研究，快速拆解问题、搭建研究思路，利用有效的数据分析方法，输出有洞察力的分析结论并做好呈现；\n\n4.流程优化：对绩效管理流程及框架进行梳理分析，推进过程管理产品化，帮助业务相关方实时了解绩效进展，进行业绩的过程改善。\n\n岗位基本要求\n1.本科或以上学历，商业分析、统计学、数学、财经类或理工科相关专业优先；\n\n2.3年以上数据/商业分析相关经验，有目标制定和绩效管理经历者优先；\n\n3.具有扎实的数理统计基本功，熟练掌握SQL进行数据提取与处理，能独立完成复杂业务分析 \n\n4.擅长结构化思维，能对业务目标及达成路径进行系统性拆解，输出可落地的策略建议；\n\n5.具备优秀的跨团队沟通能力，能清晰传递数据洞察并推动策略落地；自驱力强，能主动协调资源解决问题。\n\n6.了解AI工具，并可以应用AI工具为工作赋能提效。\n\n岗位亮点\n1. 核心业务下的核心团队，能站在外卖核心经营管理视角，成长空间大，能力发展全面；\n\n2. 工作内容兼具业务视角及全局视角，与业务方强协同、落地性好； \n\n3. 团队融洽和谐开放，学习氛围浓厚。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4486608927","sourceKey":"meituan_social","company":"美团","title":"大客户区域经理","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4486608927&jobShareType=1","duty":"业务管理：负责市场调研和竞争对手分析，制定区域/品类增长策略，主导连锁品牌客户全生命周期价值挖掘，从产品售卖、履约服务到跨品类渗透，持续提升客户粘性。\n团队管理：管理和指导销售团队，通过团队赋能提升团队销售能力和绩效。协调内部资源，解决销售过程中的各种难题。\n项目管理：重点推进高价值项目，联动报价策略、运力运营、商分、产研部门制定头部客户解决方案。\n业务探索：沉淀品类收入增长方案，探索创新收入场景。","requirements":"1. 拥有对应行业品牌方或互联网平台的配送履约/O2O/采销等相关经验，有3-5年以上团队管理经验。\n2. 关注零售、餐饮等行业发展趋势，熟悉品牌方投资经营逻辑及平台经营策略。\n3. 具备良好的商务谈判能力和数据分析能力，熟悉AI辅助的经营分析工具（如智能归因、效果预测模型等），能将数据洞察转化为客户经营策略。\n4. 优秀的跨部门协同与资源整合能力，能推动多方协作高效落地。\n5. 持续关注AI在履约领域的应用趋势，能将新能力快速转化为客户解决方案。","description":"部门介绍\n美团配送是以科技为内核的即时物流品牌，利用高效、稳定、广阔的配送网络和前沿科技能力为各行业客户提供涵盖商流物流一体化、流量赋能、行业定制化即时配送、末端配送、前置仓等服务在内的全方位同城物流综合解决方案。\n作为科技创新和智慧物流的实践者，美团配送在人工智能（AI）、5G应用、物联网（IoT）、云计算等多维度不断探索科创蓝海，让同城物流进入数智化时代。美团配送在IoT智能设备、外卖柜、换电网络、无人配送体系等硬件设施与服务上不断推陈出新，持续优化骑手、消费者、商家体验；自研同城物流系统，通过智能分析为用户提供更便捷的生活方式，为商家提供更高效的履约服务。\n加入我们，一起把世界送到消费者手中！\n\n岗位职责\n业务管理：负责市场调研和竞争对手分析，制定区域/品类增长策略，主导连锁品牌客户全生命周期价值挖掘，从产品售卖、履约服务到跨品类渗透，持续提升客户粘性。\n团队管理：管理和指导销售团队，通过团队赋能提升团队销售能力和绩效。协调内部资源，解决销售过程中的各种难题。\n项目管理：重点推进高价值项目，联动报价策略、运力运营、商分、产研部门制定头部客户解决方案。\n业务探索：沉淀品类收入增长方案，探索创新收入场景。\n\n岗位基本要求\n1. 拥有对应行业品牌方或互联网平台的配送履约/O2O/采销等相关经验，有3-5年以上团队管理经验。\n2. 关注零售、餐饮等行业发展趋势，熟悉品牌方投资经营逻辑及平台经营策略。\n3. 具备良好的商务谈判能力和数据分析能力，熟悉AI辅助的经营分析工具（如智能归因、效果预测模型等），能将数据洞察转化为客户经营策略。\n4. 优秀的跨部门协同与资源整合能力，能推动多方协作高效落地。\n5. 持续关注AI在履约领域的应用趋势，能将新能力快速转化为客户解决方案。\n\n岗位亮点\n依托平台外卖餐饮&闪购商家和用户的广泛商业空间，参与行业品牌\"餐饮&闪购第二增长曲线\"的前沿商业模式搭建。\n深度参与AI驱动的履约产品在客户侧的落地应用，通过履约模式的搭建和优化迭代赋能品牌O2O增长。\n团队管理岗位，带队攻坚头部行业品牌，培养兼具客户视角、平台视角与技术视角的综合管理能力。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4770627885","sourceKey":"meituan_social","company":"美团","title":"履约配送-智能调度高级算法专家","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4770627885&jobShareType=1","duty":"美团配送承担着美团外卖旗下每日超过4000万单的履约职责，建设了千万订单级别的分钟级配送网络，并打造了高度自动化与智能化的实时调度系统，负责万人万单的秒级匹配决策，优化配送效率，提升用户与骑手体验。本岗位的具体职责如下:\n\n（1）负责实时调度系统中关键模块的研发与优化，针对即时配送实时调度问题存在的多目标、不确定性、动态性与超大规模等特点，综合使用组合优化、机器学习、强化学习、因果推断等技术手段，持续创新迭代，提升人单匹配决策质量，优化核心业务指标。\n\n（2）针对即时配送领域特点，颠覆创新传统供应链物流技术体系，探索即时配送履约新模式，提升降本增效天花板。\n\n（3）负责Agent能力建设，以及其在运力招募、运营、交互与分单等智能决策领域应用，优化系统运力供给，提升骑手履约体验，提升决策天花板。","requirements":"（1）计算机、工业工程、自动化、应用数学等相关专业；\n（2）较好的编程能力，熟悉JAVA/Python等任一语言，熟悉常用数据结构和算法，熟练使用hive、spark等工具；\n（3）在机器学习或数据挖掘或运筹优化或Agent构建方向有深入理解与落地经验，在广告推荐、资源分配、库存管理、需求预估、强化学习等方面有实践经验；\n（4）在复杂业务场景策略优化方面具备3年及以上年经验；\n（5）能够深入思考、勇于创新，具有优秀的业务理解、目标制定能力，以及较强的跨团队沟通和协调能力。","description":"部门介绍\n美团核心本地商业下业务研发平台，基于公司“零售+科技”的战略导向，通过从底层架构到应用系统、从软件到硬件、从传统算法到GenAI的全方位技术研究，以及开发、运维、安全等全流程能力建设，致力于推动美团核心本地商业下需求侧与供给侧的数字化和智能化升级，助力业务实现高质量增长，优化用户使用体验，提升商户经营水平，促进行业生态伙伴关系的持续健康发展。团队秉持务实、自驱、开放以及追求卓越的工程师文化，一方面通过系统和技术体系的持续迭代升级，帮助业务高质量增长；另一方面，密切关注前沿技术趋势变化，积极创新技术能力，为业务未来发展创造新的可能性。期待优秀的你加入我们，在夯实专业、深耕平台的基础上与业务携手同行，一起用技术 “帮大家吃得更好，生活更好”。\n\n岗位职责\n美团配送承担着美团外卖旗下每日超过4000万单的履约职责，建设了千万订单级别的分钟级配送网络，并打造了高度自动化与智能化的实时调度系统，负责万人万单的秒级匹配决策，优化配送效率，提升用户与骑手体验。本岗位的具体职责如下:\n\n（1）负责实时调度系统中关键模块的研发与优化，针对即时配送实时调度问题存在的多目标、不确定性、动态性与超大规模等特点，综合使用组合优化、机器学习、强化学习、因果推断等技术手段，持续创新迭代，提升人单匹配决策质量，优化核心业务指标。\n\n（2）针对即时配送领域特点，颠覆创新传统供应链物流技术体系，探索即时配送履约新模式，提升降本增效天花板。\n\n（3）负责Agent能力建设，以及其在运力招募、运营、交互与分单等智能决策领域应用，优化系统运力供给，提升骑手履约体验，提升决策天花板。\n\n岗位基本要求\n（1）计算机、工业工程、自动化、应用数学等相关专业；\n（2）较好的编程能力，熟悉JAVA/Python等任一语言，熟悉常用数据结构和算法，熟练使用hive、spark等工具；\n（3）在机器学习或数据挖掘或运筹优化或Agent构建方向有深入理解与落地经验，在广告推荐、资源分配、库存管理、需求预估、强化学习等方面有实践经验；\n（4）在复杂业务场景策略优化方面具备3年及以上年经验；\n（5）能够深入思考、勇于创新，具有优秀的业务理解、目标制定能力，以及较强的跨团队沟通和协调能力。\n\n岗位亮点\n（1）业务核心，创新场景丰富，负责每日超过9000万单与数百万骑手匹配决策，覆盖全国几百个城市，涉及即时配送体验、效率等核心业务指标优化；\n（2）团队汇聚了运筹优化和机器学习背景的技术大牛，通过共同学习可快速成长为落地实战经验丰富的跨学科复合型人才。团队近年已有部分成果发表在KDD/CIKM等顶会上，并入围2023年Franz Edelman奖（被誉为工业工程界的“诺贝尔”奖）。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4791077239","sourceKey":"meituan_social","company":"美团","title":"Keeta-用户增长产品经理","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4791077239&jobShareType=1","duty":"1. 基于不同区域的业务阶段与用户分层，识别增长机会，制定并落地用户获取与新客转化的产品方案。\n2. 负责全渠道用户触达工具的建设与迭代，通过持续的产品化提效，提升用户规模和消费频次。\n3. 与区域运营、数据、算法等团队协同，推动产品从方案设计、上线落地到效果复盘的完整闭环，并探索AI在用户增长及运营提效中的应用，持续优化增长ROI。","requirements":"1. 5年以上互联网产品经验，具备用户增长方向相关产品经验；有电商、外卖、出行等交易型业务经验者优先。\n2. 熟悉用户增长常用方法，理解获客转化、用户分层、权益激励、任务体系、留存提频等产品机制。\n3. 具备较强的结构化思考、数据分析、跨团队协作能力，能适应海外多region协作节奏，能在复杂业务环境下独立推进项目并拿到结果。","description":"部门介绍\nKeeta是全球领先外卖平台美团旗下的独立品牌，肩负着“帮大家吃得更好，生活更好”的使命。依托美团深耕中国市场15年的技术与运营积淀，我们正引领全球餐饮与商品即时配送服务的创新与发展。\n\n自2023年成立以来，Keeta始终扎根社区并创造价值。我们为用户提供可靠的外卖体验，以智慧技术助餐厅提升经营效率，在为骑手拓宽收入来源的同时，也充分提供安全保障措施。基于这份多方共赢、共同成长的理念，我们的业务已从中国香港稳步拓展至中东及巴西，并持续向世界迈进。\n\n岗位职责\n1. 基于不同区域的业务阶段与用户分层，识别增长机会，制定并落地用户获取与新客转化的产品方案。\n2. 负责全渠道用户触达工具的建设与迭代，通过持续的产品化提效，提升用户规模和消费频次。\n3. 与区域运营、数据、算法等团队协同，推动产品从方案设计、上线落地到效果复盘的完整闭环，并探索AI在用户增长及运营提效中的应用，持续优化增长ROI。\n\n岗位基本要求\n1. 5年以上互联网产品经验，具备用户增长方向相关产品经验；有电商、外卖、出行等交易型业务经验者优先。\n2. 熟悉用户增长常用方法，理解获客转化、用户分层、权益激励、任务体系、留存提频等产品机制。\n3. 具备较强的结构化思考、数据分析、跨团队协作能力，能适应海外多region协作节奏，能在复杂业务环境下独立推进项目并拿到结果。\n\n具备以下条件优先\n1. 有国际化业务经验，或支持过多国家、多区域、多业态业务；\n2. 英语可作为工作语言。\n\n岗位亮点\n1. 全球化业务，国际化视野，拓宽职业边界；\n2. 快速发展的业务阶段，更多的实践和决策机会。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4791057807","sourceKey":"meituan_social","company":"美团","title":"商家策略运营","city":"上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4791057807&jobShareType=1","duty":"1、负责头部客户（高价值连锁品牌、框架合作客户）的营销策略设计，包括权益设计、返利/激励方案、品类×城市差异化策略，并推动策略在直营销售团队落地；\n2、与各区域销售团队紧密协作，负责策略的宣贯、SOP沉淀、落地过程的问题诊断与纠偏，确保策略执行一致性；\n3、搭建策略效果评估体系，通过数据分析验证策略ROI，持续迭代优化打法，沉淀可复用的方法论；\n4、基于经营数据（交易规模、渗透率、营销投入产出等）输出客户分层洞察与机会点识别，为策略设计提供输入；\n5、与产品/研发协作，推动销售策略工具的产品化建设，提升策略触达与执行效率。","requirements":"1、本科及以上学历，2年及以上销售运营/策略运营/商业分析相关经验，有O2O、本地生活或广告行业背景优先；\n2、数据功底扎实：熟练使用SQL，具备独立完成数据提取、分析、归因的能力，能用数据说话、以数据决策；\n3、产运&AI基本功：具备产品化思维，具备AI协同经验，有策略工具、工作台、流程机制等产品运营经验者优先；\n4、能独立完成策略方案设计（客户分层、权益设计、激励方案），并推动复杂策略在多层级销售组织中落地；\n5、擅长跨团队协作，能横向拉通销售、产品、财务等多方角色；接受一定频率的出差走访（一线市场调研）；\n6、有大客户/KA策略运营、返利激励方案设计经验者，或熟悉直营销售管理体系者，优先考虑。","description":"部门介绍\n美团服务零售事业部下设乐生活业务部、易生活业务部、进场零售业务部以及中小城市发展部四大业务部门，旨在通过提供丰富、可靠、实惠的服务与商品满足用户各类生活需求。我们所处的服务零售行业是一个具有万亿规模的市场，覆盖足疗洗浴、酒吧KTV、运动健身、美发美甲、教育培训、亲子游乐、家政洗涤维修、摄影写真等数十个服务消费细分领域，同时延伸至超市便利、美妆个护、3C数码、服饰珠宝、运动户外、商场购物中心等实体零售到店消费场景，连接数十万品牌商户与线下门店。作为商家和行业的小帮手，我们持续深入服务零售与实体零售产业链，用AI等技术推动行业变革，帮助商家提升经营效率、实现高效的线上化经营与到店转化，优化消费者服务体验，提供安心、放心的履约保障。这里有着多元的业务布局，有着富有挑战和影响力的工作内容，为你提供丰富的视野、持续的成长和发展机会，引领你发现更多可能。期待和你在“随时随地，美好生活”的愿景指引下，共建美好的生活服务体验、健康的商家生态与高质量的经营结果。\n\n岗位职责\n1、负责头部客户（高价值连锁品牌、框架合作客户）的营销策略设计，包括权益设计、返利/激励方案、品类×城市差异化策略，并推动策略在直营销售团队落地；\n2、与各区域销售团队紧密协作，负责策略的宣贯、SOP沉淀、落地过程的问题诊断与纠偏，确保策略执行一致性；\n3、搭建策略效果评估体系，通过数据分析验证策略ROI，持续迭代优化打法，沉淀可复用的方法论；\n4、基于经营数据（交易规模、渗透率、营销投入产出等）输出客户分层洞察与机会点识别，为策略设计提供输入；\n5、与产品/研发协作，推动销售策略工具的产品化建设，提升策略触达与执行效率。\n\n岗位基本要求\n1、本科及以上学历，2年及以上销售运营/策略运营/商业分析相关经验，有O2O、本地生活或广告行业背景优先；\n2、数据功底扎实：熟练使用SQL，具备独立完成数据提取、分析、归因的能力，能用数据说话、以数据决策；\n3、产运&AI基本功：具备产品化思维，具备AI协同经验，有策略工具、工作台、流程机制等产品运营经验者优先；\n4、能独立完成策略方案设计（客户分层、权益设计、激励方案），并推动复杂策略在多层级销售组织中落地；\n5、擅长跨团队协作，能横向拉通销售、产品、财务等多方角色；接受一定频率的出差走访（一线市场调研）；\n6、有大客户/KA策略运营、返利激励方案设计经验者，或熟悉直营销售管理体系者，优先考虑。\n\n岗位亮点\n1、参与平台核心商家运营策略，直接影响业务增长方向。  \n2、与多部门协同合作，积累丰富的跨职能项目经验。  \n3、公司提供完善的培训体系与职业发展通道。  \n4、团队氛围开放，鼓励创新与数据驱动决策。  \n5、工作地点位于上海核心商圈，交通便利，办公环境优越。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4793038028","sourceKey":"meituan_social","company":"美团","title":"酒店民宿商分-用户方向","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4793038028&jobShareType=1","duty":"1、负责创新场景经营分析：辅助产运进行营销产品、玩法、策略的0-1探索，搭建I/O指标体系并自主迭代，进行关键指标异动解读、风险预警、目标拆解等，能够兼顾业务视角和C端用户视角，牵引业务做功；\n2、挖掘增长策略：发挥数据分析优势，自主探查流量转化提效、客群分层及精细化运营、用户留存等关键策略，协助业务进行AB测、专题复盘等深度分析工作；\n3、探索AI工具：探索AI提效路径，搭建业务协同机制，通过人机协同完善预警、播报，举措追踪等。","requirements":"1、3年商业分析经验，有较好的数据处理能力，熟练使用office、SQL、python等传统工具，并在AI工具应用上有一定研究；\n2、具备主人翁精神，有较好的沟通协同能力，并能够交付结果。","description":"部门介绍\n美团酒店旅行业务涵盖酒店、民宿、机票、火车票、旅游度假、景点门票等各类住行游品类，通过与产业上下游的深度合作，为用户提供美好的旅游旅行体验。我们积极打造AI友好型组织，使用AI等新技术提升旅游服务的供需匹配效率，更好满足用户个性化、多样化的出游需求。我们持续深耕产业链，用数字化服务助力实体商家高质量经营，探索自有品牌等供给新模式，打造健康的商家生态，保障用户服务体验。为满足用户日益增长的跨境旅行需求，我们将聚焦亚太区域，打造高品质的住宿、交通、游玩等服务矩阵。\n这里有多元的业务布局、持续的成长空间，无论是向往的远方还是眼前的工作，一路都是风景相伴。加入我们，共同为用户创造旅游旅行中的高光时刻！\n\n岗位职责\n1、负责创新场景经营分析：辅助产运进行营销产品、玩法、策略的0-1探索，搭建I/O指标体系并自主迭代，进行关键指标异动解读、风险预警、目标拆解等，能够兼顾业务视角和C端用户视角，牵引业务做功；\n2、挖掘增长策略：发挥数据分析优势，自主探查流量转化提效、客群分层及精细化运营、用户留存等关键策略，协助业务进行AB测、专题复盘等深度分析工作；\n3、探索AI工具：探索AI提效路径，搭建业务协同机制，通过人机协同完善预警、播报，举措追踪等。\n\n岗位基本要求\n1、3年商业分析经验，有较好的数据处理能力，熟练使用office、SQL、python等传统工具，并在AI工具应用上有一定研究；\n2、具备主人翁精神，有较好的沟通协同能力，并能够交付结果。\n\n岗位亮点\n深度参与发展期业务成长过程，个人能力提升快，技能点全面","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4764776828","sourceKey":"meituan_social","company":"美团","title":"小象超市-沈阳PC加工主管","city":"沈阳市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4764776828&jobShareType=1","duty":"1、负责排产、排班、出勤计划执行，加工进度管控、每日订单目标交付达成；\n2、负责加工过程中人员组台、品类拆分、原料进度追踪、异常协调等业务；\n3、负责加工品质保障、加工数据准确性管理、上下游入库准确性管理；\n4、负责设备高效使用，员工积极性策略推动与执行；\n5、负责加工区域6S、生产安全、消防安全、食品安全等管理；\n6、负责促成部门各指标达成（品质、原料成本、人力成本、员工留存等）\n7、负责班次团队组织架构搭建、招聘计划、人员培养汰换，每日生产会议。","requirements":"1.具备物流或仓储相关领域的大学专科及以上学历。\n2.至少5年以上物流或仓储管理经验，有生鲜加工管理经验者优先考虑。\n3.熟悉生鲜产品的质量标准和加工工艺，具备相关品控知识。\n4.具备较好的团队管理能力，能够激励团队成员，提高工作效率。\n5.具备良好的沟通协调能力，能够与不同部门和供应商进行有效的合作。\n6.具备一定的问题解决能力和应变能力，能够灵活应对工作中的各种挑战。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1、负责排产、排班、出勤计划执行，加工进度管控、每日订单目标交付达成；\n2、负责加工过程中人员组台、品类拆分、原料进度追踪、异常协调等业务；\n3、负责加工品质保障、加工数据准确性管理、上下游入库准确性管理；\n4、负责设备高效使用，员工积极性策略推动与执行；\n5、负责加工区域6S、生产安全、消防安全、食品安全等管理；\n6、负责促成部门各指标达成（品质、原料成本、人力成本、员工留存等）\n7、负责班次团队组织架构搭建、招聘计划、人员培养汰换，每日生产会议。\n\n岗位基本要求\n1.具备物流或仓储相关领域的大学专科及以上学历。\n2.至少5年以上物流或仓储管理经验，有生鲜加工管理经验者优先考虑。\n3.熟悉生鲜产品的质量标准和加工工艺，具备相关品控知识。\n4.具备较好的团队管理能力，能够激励团队成员，提高工作效率。\n5.具备良好的沟通协调能力，能够与不同部门和供应商进行有效的合作。\n6.具备一定的问题解决能力和应变能力，能够灵活应对工作中的各种挑战。\n\n具备以下条件优先\n1、具备100人以上一线团队管理经验；\n2、有食品/农产品等生产制造或者机械专业工作经历优先；\n3、有大型食品企业5年以上管理经验；\n4、有数据分析改善落地经验优先；\n5、沟通表达协调，逻辑思维能力良好；\n6、有精益管理经验优先；\n7、有较清晰的自我定位，职业发展规划；\n8、有上进心。\n\n岗位亮点\n1、成长空间大：业务发展速度快，可同共公司业务公共同成长；\n2、学习资源多，可以快速提升个人能力。\n3、可以学习到美团先进线上数据化系统分析逻辑。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4735585523","sourceKey":"meituan_social","company":"美团","title":"无人车业务部-数据管理工程师","city":"上海市/深圳市/北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4735585523&jobShareType=1","duty":"建立和维护整车数据管理体系，定义数据分类、编码规则、属性规范，负责整车工程数据（3D 模型、2D 图纸、技术参数、配置信息）的录入、更新、版本控制，管理车型配置数据，确保配置逻辑准确。\n\nBOM 数据维护与管理：负责整车BOM的信息收集、单车/超级结构搭建、版本发布及变更维护；对BOM数据规范性、准确性进行评审与管控，确保数据源头标准统一。\n\n变更管理：负责各车型设计变更管理，包括变更流程建设、变更点识别、ECR评审会议组织、ECN的各节点推进、变更断点及效果确认；协同研发、供应链、制造等上下游，确保变更流程的高效协同。\n\n数据服务器运维管理：包括数据服务器账户及权限管理、数据外发审批，结合无人车业务需求，协同数字化对PLM/ERP等系统进行功能模块的开发和持续改进。\n\nAI及数字化开发：负责AI及数字化工具在数据管理领域的开发及应用，通过AI及数字化工具引入提高数据管理效率，优化数据管理流程，确保数据管理工作的高效运行。","requirements":"本科及以上，车辆工程、机械、工业工程、自动化、电子等理工科相关专业。\n\n本科5年以上、硕士3年以上数据管理相关经验，至少1个完整整车项目开发经历。\n\n熟悉整车开发流程，熟悉整车数据管理在整车开发流程中各节点的工作内容及交付物\n\n熟悉整车及底盘等数据结构及零部件分层，熟悉主流的整车配置管理方案。\n\n熟练使用车辆设计等办公软件，具备PLM/ERP数据管理模块功能搭建和维护能力。\n\n优秀的跨团队沟通、技术决策及项目管理能力，能主导数据管理相关问题的解决方案。\n\n学习能力强，对AI在数据管理领域的应用有前瞻思考能力。","description":"部门介绍\n无人车业务部成立于2016年，旨在用无人驾驶技术提升物流配送的效率和体验。美团无人车以自研L4级自动驾驶软硬件技术为核心，与美团即时零售业务结合，形成满足公开道路、社区、工业园区等室外全场景下的无人配送整体解决方案。自2020年起，无人车已在北京、深圳等多地进入常态化试运营阶段，在城市复杂场景下提供针对餐饮外卖、生鲜食杂等货物的即时配送服务。2025年，美团无人车又踏上了同城货运的新探索，并在2026年持续扩大运营范围和车队数量，为更多城市带来智能配送服务。\n欢迎加入美团无人车团队，与我们一起用科技推动即时零售再升级！\n\n岗位职责\n建立和维护整车数据管理体系，定义数据分类、编码规则、属性规范，负责整车工程数据（3D 模型、2D 图纸、技术参数、配置信息）的录入、更新、版本控制，管理车型配置数据，确保配置逻辑准确。\n\nBOM 数据维护与管理：负责整车BOM的信息收集、单车/超级结构搭建、版本发布及变更维护；对BOM数据规范性、准确性进行评审与管控，确保数据源头标准统一。\n\n变更管理：负责各车型设计变更管理，包括变更流程建设、变更点识别、ECR评审会议组织、ECN的各节点推进、变更断点及效果确认；协同研发、供应链、制造等上下游，确保变更流程的高效协同。\n\n数据服务器运维管理：包括数据服务器账户及权限管理、数据外发审批，结合无人车业务需求，协同数字化对PLM/ERP等系统进行功能模块的开发和持续改进。\n\nAI及数字化开发：负责AI及数字化工具在数据管理领域的开发及应用，通过AI及数字化工具引入提高数据管理效率，优化数据管理流程，确保数据管理工作的高效运行。\n\n岗位基本要求\n本科及以上，车辆工程、机械、工业工程、自动化、电子等理工科相关专业。\n\n本科5年以上、硕士3年以上数据管理相关经验，至少1个完整整车项目开发经历。\n\n熟悉整车开发流程，熟悉整车数据管理在整车开发流程中各节点的工作内容及交付物\n\n熟悉整车及底盘等数据结构及零部件分层，熟悉主流的整车配置管理方案。\n\n熟练使用车辆设计等办公软件，具备PLM/ERP数据管理模块功能搭建和维护能力。\n\n优秀的跨团队沟通、技术决策及项目管理能力，能主导数据管理相关问题的解决方案。\n\n学习能力强，对AI在数据管理领域的应用有前瞻思考能力。\n\n具备以下条件优先\n有商用车或无人车数据管理开发经验。\n\n有AI工具开发/应用经验。\n\n熟悉主流PLM系统。\n\n岗位亮点\n🤖 AI赋能工具链：公司AI工具完善，用AI替代重复劳动（文档/报告/对标），精力聚焦在有价值的设计决策\n\n🌏 整车厂+自动驾驶双重经历，商用车/智能驾驶背景，个人市场价值显著提升","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4792870549","sourceKey":"meituan_social","company":"美团","title":"商户运营专家","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4792870549&jobShareType=1","duty":"1、负责美团无人车的商户/用户运营，围绕用户全生命周期开展精细化运营，基于不同阶段用户特征制定差异化的增长策略，推动用户使用频次、ARPU值、留存、补贴效率等核心业务目标达成。\n2、深入分析用户行为和需求，识别高潜力重点人群并进行分层、分群运营，从供给匹配、需求激发、用户体验等关键环节持续优化，提升用户黏性、活跃度和长期价值。\n3、搭建并迭代商户运营策略体系，持续沉淀人群运营方法论，形成可复制、可评估、可迭代的运营机制。\n4、与商分、产品、研发等团队紧密协同，整合跨部门资源，推动运营策略高质量落地，并对最终效果负责。\n5、持续关注行业动态、竞争对手及关键玩家的策略变化，结合市场洞察与业务现状识别新的增长机会，为业务决策提供支持。\n6.探索和运用AI工具辅助数据专题分析和报告产出等工作，提高分析效能。","requirements":"1、大学本科及以上学历，3年以上用户运营或者策略运营经验。\n2、具备较强的数据能力和经营意识。\n3、有较强的逻辑思维能力，能从全局的角度看问题并协调各方达成一致。\n4、学习能力强，有好奇心，有足够的责任感和主人翁精神，能从全链路最优而非单一岗位视角去设计解决方案。\n5.了解AI基础知识，有使用AI工具提效个人或团队工作的经验和想法。","description":"部门介绍\n无人车业务部成立于2016年，旨在用无人驾驶技术提升物流配送的效率和体验。美团无人车以自研L4级自动驾驶软硬件技术为核心，与美团即时零售业务结合，形成满足公开道路、社区、工业园区等室外全场景下的无人配送整体解决方案。自2020年起，无人车已在北京、深圳等多地进入常态化试运营阶段，在城市复杂场景下提供针对餐饮外卖、生鲜食杂等货物的即时配送服务。2025年，美团无人车又踏上了同城货运的新探索，并在2026年持续扩大运营范围和车队数量，为更多城市带来智能配送服务。\n欢迎加入美团无人车团队，与我们一起用科技推动即时零售再升级！\n\n岗位职责\n1、负责美团无人车的商户/用户运营，围绕用户全生命周期开展精细化运营，基于不同阶段用户特征制定差异化的增长策略，推动用户使用频次、ARPU值、留存、补贴效率等核心业务目标达成。\n2、深入分析用户行为和需求，识别高潜力重点人群并进行分层、分群运营，从供给匹配、需求激发、用户体验等关键环节持续优化，提升用户黏性、活跃度和长期价值。\n3、搭建并迭代商户运营策略体系，持续沉淀人群运营方法论，形成可复制、可评估、可迭代的运营机制。\n4、与商分、产品、研发等团队紧密协同，整合跨部门资源，推动运营策略高质量落地，并对最终效果负责。\n5、持续关注行业动态、竞争对手及关键玩家的策略变化，结合市场洞察与业务现状识别新的增长机会，为业务决策提供支持。\n6.探索和运用AI工具辅助数据专题分析和报告产出等工作，提高分析效能。\n\n岗位基本要求\n1、大学本科及以上学历，3年以上用户运营或者策略运营经验。\n2、具备较强的数据能力和经营意识。\n3、有较强的逻辑思维能力，能从全局的角度看问题并协调各方达成一致。\n4、学习能力强，有好奇心，有足够的责任感和主人翁精神，能从全链路最优而非单一岗位视角去设计解决方案。\n5.了解AI基础知识，有使用AI工具提效个人或团队工作的经验和想法。\n\n具备以下条件优先\n有商分+业务结合背景的候选人优先。\n\n岗位亮点\n1、行业机遇：自动驾驶+AI最前沿科技的探索，深入参与无人车对生活服务的改变，建设比见证更值得期待。\n2、岗位特点：作为最前线参与无人车业务增长，直接影响业务效率和成本优化。  \n3、团队氛围：坦诚、直接、开放的沟通环境，积极、简单、高效的团队工作氛围。\n4、个人成长：人才密度高，有机会跟行业里优秀的产研、运营同学共事，我们坚信“优秀+优秀=优秀的N次方”。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4695428238","sourceKey":"meituan_social","company":"美团","title":"酒店供应链采购经理（运营物资）","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4695428238&jobShareType=1","duty":"1. 根据业务目标，倒推动作，结合品类策略制定采购策略、价格策略达成结果，熟悉OEM\\ODM运营方式；\n2. 负责供应商筛选、合作洽谈、考察、合同签约等；\n3. 负责供应商履约管理与投诉管理，核实投诉与履约问题，督促问题整改、执行处罚；\n4. 负责供应商产品/服务质量监督检查，不定期抽检、公示度、督导改进一级处罚执行；\n5. 与公司各部门配合，及时处理客户/各部门的反馈、投诉和建议，提高服务满意度。","requirements":"1. 本科及以上学历；\n2. 5以上采购管理经验；\n3. 熟悉采购工作流程，拥有较强的产品资源开拓、商务洽谈等能力；\n4. 良好的沟通能力，逻辑清晰，跨部门沟通顺畅，具有良好额团队合作精神，善于学习与思考，执行力强；\n5. 过往从事过酒店运营物资采购、零售百货采购经验优先；","description":"部门介绍\n美团酒店旅行业务涵盖酒店、民宿、机票、火车票、旅游度假、景点门票等各类住行游品类，通过与产业上下游的深度合作，为用户提供美好的旅游旅行体验。我们积极打造AI友好型组织，使用AI等新技术提升旅游服务的供需匹配效率，更好满足用户个性化、多样化的出游需求。我们持续深耕产业链，用数字化服务助力实体商家高质量经营，探索自有品牌等供给新模式，打造健康的商家生态，保障用户服务体验。为满足用户日益增长的跨境旅行需求，我们将聚焦亚太区域，打造高品质的住宿、交通、游玩等服务矩阵。\n这里有多元的业务布局、持续的成长空间，无论是向往的远方还是眼前的工作，一路都是风景相伴。加入我们，共同为用户创造旅游旅行中的高光时刻！\n\n岗位职责\n1. 根据业务目标，倒推动作，结合品类策略制定采购策略、价格策略达成结果，熟悉OEM\\ODM运营方式；\n2. 负责供应商筛选、合作洽谈、考察、合同签约等；\n3. 负责供应商履约管理与投诉管理，核实投诉与履约问题，督促问题整改、执行处罚；\n4. 负责供应商产品/服务质量监督检查，不定期抽检、公示度、督导改进一级处罚执行；\n5. 与公司各部门配合，及时处理客户/各部门的反馈、投诉和建议，提高服务满意度。\n\n岗位基本要求\n1. 本科及以上学历；\n2. 5以上采购管理经验；\n3. 熟悉采购工作流程，拥有较强的产品资源开拓、商务洽谈等能力；\n4. 良好的沟通能力，逻辑清晰，跨部门沟通顺畅，具有良好额团队合作精神，善于学习与思考，执行力强；\n5. 过往从事过酒店运营物资采购、零售百货采购经验优先；\n\n具备以下条件优先\n优先亚朵运营物资采购经验，其次华住、锦江运营物资采购经验。\n\n岗位亮点\n具备成长空间，深度接触酒店产品研发的机会。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4583041624","sourceKey":"meituan_social","company":"美团","title":"商品经营产品经理（非餐品类）","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4583041624&jobShareType=1","duty":"1、负责新业务线（非餐品类）的商品产品规划、方案设计及交付落地，对商品信息质量和供给丰富度负责。\n2、负责商家发品相关产品能力建设，包括发品工具、商品审核机制、AI辅助发布等，持续提升发品效率和成功率。\n3、建设商品信息治理相关产品能力，提升商品信息质量；能够深入理解用户选购决策和搜索推荐逻辑，持续丰富完善商品信息，促进交易转化。\n4、对商品供给策略深入洞察，围绕供给诊断、商机识别、选品推荐、爆品培育、库存准确度等建设产品能力，赋能商家经营提升。","requirements":"1、3年以上电商/零售领域的商品产品经验，对商品信息、供给策略、商品经营有深入理解。\n2、英语口语好，能够和商家进行调研访谈，能接受高频出差。\n3、有使用AI工具的工作实践，有主动探索AI的学习意愿。 \n4、有扎实的逻辑思维和结构化表达能力。 \n\n【我们最看重的特质】 \n1、能够从供给和需求双视角理解商品经营逻辑\n2、强自驱力","description":"部门介绍\nKeeta是全球领先外卖平台美团旗下的独立品牌，肩负着“帮大家吃得更好，生活更好”的使命。依托美团深耕中国市场15年的技术与运营积淀，我们正引领全球餐饮与商品即时配送服务的创新与发展。\n\n自2023年成立以来，Keeta始终扎根社区并创造价值。我们为用户提供可靠的外卖体验，以智慧技术助餐厅提升经营效率，在为骑手拓宽收入来源的同时，也充分提供安全保障措施。基于这份多方共赢、共同成长的理念，我们的业务已从中国香港稳步拓展至中东及巴西，并持续向世界迈进。\n\n岗位职责\n1、负责新业务线（非餐品类）的商品产品规划、方案设计及交付落地，对商品信息质量和供给丰富度负责。\n2、负责商家发品相关产品能力建设，包括发品工具、商品审核机制、AI辅助发布等，持续提升发品效率和成功率。\n3、建设商品信息治理相关产品能力，提升商品信息质量；能够深入理解用户选购决策和搜索推荐逻辑，持续丰富完善商品信息，促进交易转化。\n4、对商品供给策略深入洞察，围绕供给诊断、商机识别、选品推荐、爆品培育、库存准确度等建设产品能力，赋能商家经营提升。\n\n岗位基本要求\n1、3年以上电商/零售领域的商品产品经验，对商品信息、供给策略、商品经营有深入理解。\n2、英语口语好，能够和商家进行调研访谈，能接受高频出差。\n3、有使用AI工具的工作实践，有主动探索AI的学习意愿。 \n4、有扎实的逻辑思维和结构化表达能力。 \n\n【我们最看重的特质】 \n1、能够从供给和需求双视角理解商品经营逻辑\n2、强自驱力\n\n具备以下条件优先\n1、有零售/电商等场景的商品中台或商品管理产品经验。 \n2、对AI工具有深度使用经验，有AI交付产品功能的实践案例。\n3、有海外生活经历，了解海外消费习惯和文化背景。\n\n岗位亮点\n1、业务发展快，非餐品类在海外市场增长迅速，跟随业务发展的成长天花板高。 \n2、我们鼓励用AI工具替代重复劳动，一起实践AI-Native的新工作范式，致力于成为超级个体。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4552713652","sourceKey":"meituan_social","company":"美团","title":"Keeta-首页产品运营","city":"深圳市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4552713652&jobShareType=1","duty":"1、负责Keeta多国首页流量机制建设与运营，制定流量体系建设的规划和目标，通过机制和项目确保多国流量资源利用充分、首页分发和转化效率最大化。建设和维护流量分析体系，提供准确的流量数据和分析报告，为业务决策提供支持。\n2、有效通过用户调研、访谈等方式，科学分析多国用户消费偏好，设计需求、场景、品类分层和对应承接策略，提升全景用户需求满足度和满足效率，探索更多激发用户弹性需求的方式，提升Keeta用户的选购体验。\n3、和多国业务团队建立良好互信的协作关系，管理与统筹多国流量端需求，提供科学合理的前置评估。独立完成运营方案设计，协调产品、研发、其他业务部门等各方资源，推进上线。通过敏捷AB实验和数据分析，快速拿到认知，持续进行策略迭代。\n4、对行业动态、业界标杆平台、海外产品趋势保持关注，深入理解其产品功能迭代的表层考量和底层逻辑，为产品优化和创新提供指导。","requirements":"1、本科及以上学历，3-5年以上工作经验，有产品或增长相关工作经验优先；\n2、良好的逻辑思维，了解互联网流量玩法，具有良好的问题解决能力和复盘能力；\n3、具有主人翁意识，自驱力强，执行力高，善于跨部门沟通和协同；\n4、具备良优秀的数据分析能力，数据敏感性高，善于从数据中发现问题。","description":"部门介绍\nKeeta是全球领先外卖平台美团旗下的独立品牌，肩负着“帮大家吃得更好，生活更好”的使命。依托美团深耕中国市场15年的技术与运营积淀，我们正引领全球餐饮与商品即时配送服务的创新与发展。\n\n自2023年成立以来，Keeta始终扎根社区并创造价值。我们为用户提供可靠的外卖体验，以智慧技术助餐厅提升经营效率，在为骑手拓宽收入来源的同时，也充分提供安全保障措施。基于这份多方共赢、共同成长的理念，我们的业务已从中国香港稳步拓展至中东及巴西，并持续向世界迈进。\n\n岗位职责\n1、负责Keeta多国首页流量机制建设与运营，制定流量体系建设的规划和目标，通过机制和项目确保多国流量资源利用充分、首页分发和转化效率最大化。建设和维护流量分析体系，提供准确的流量数据和分析报告，为业务决策提供支持。\n2、有效通过用户调研、访谈等方式，科学分析多国用户消费偏好，设计需求、场景、品类分层和对应承接策略，提升全景用户需求满足度和满足效率，探索更多激发用户弹性需求的方式，提升Keeta用户的选购体验。\n3、和多国业务团队建立良好互信的协作关系，管理与统筹多国流量端需求，提供科学合理的前置评估。独立完成运营方案设计，协调产品、研发、其他业务部门等各方资源，推进上线。通过敏捷AB实验和数据分析，快速拿到认知，持续进行策略迭代。\n4、对行业动态、业界标杆平台、海外产品趋势保持关注，深入理解其产品功能迭代的表层考量和底层逻辑，为产品优化和创新提供指导。\n\n岗位基本要求\n1、本科及以上学历，3-5年以上工作经验，有产品或增长相关工作经验优先；\n2、良好的逻辑思维，了解互联网流量玩法，具有良好的问题解决能力和复盘能力；\n3、具有主人翁意识，自驱力强，执行力高，善于跨部门沟通和协同；\n4、具备良优秀的数据分析能力，数据敏感性高，善于从数据中发现问题。\n\n具备以下条件优先\n1、具备3年以上用户运营经验，有成功案例\n2、SQL精通\n3、英语熟练可作为工作语言\n\n岗位亮点\n国际化业务，英文工作环境，从0-1的业务经验，极大的成长空间。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4605068348","sourceKey":"meituan_social","company":"美团","title":"武汉调味品干货招商采购专家","city":"武汉市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4605068348&jobShareType=1","duty":"岗位职责:\n1.负责标品招商工作，包括开发新的供应商资源，筛选合适供应商入驻等。\n2.负责建立和维护与供应商的良好关系，确保供应链畅通，保证商品的质量和交货准时。\n3.负责监控市场动态，分析竞争对手的招商策略，制定相应的应对措施。\n4.协调内部各部门，确保招商工作与公司整体战略的协调一致。","requirements":"1.大学本科及以上学历，专业不限，有相关供应链管理、招商采购经验者优先。\n2.有3年以上商品招商经验，熟悉市场招商流程和规则，具备一定的谈判技巧和沟通能力。\n3.具备团队合作精神，能够带领团队高效完成工作，有较强的执行力和解决问题能力。\n4.对商品市场有敏锐的洞察力，有较强的商业敏感度和商业分析能力","description":"部门介绍\n快驴进货是美团旗下的餐饮供应链平台，帮助餐饮商户以更低成本、更高效率来获取安全可靠的食材供应，让餐饮采购更简单。快驴进货同步发展“自营+平台”的业务模式，在采购环节一方面向上游供应商直采大宗商品，另一方面引入各地批发商，助力平台伙伴共同发展；在销售环节既有自建团队进行市场、客户拓展，又帮助各地批发商拓展业务；同时自建仓储管理系统、配送网络与团队，为客户提供优质履约服务。\n截至2022年，快驴进货布局了全国41个城市，为百万家商户提供“全、省、稳、好”的餐饮供应链服务。我们拥有3000+品牌食材、超5万SKU商品、超28万商品资质，并提供源头严审核、食品安全严把关、24小时无忧售后的全面保障，实现手机下单、送货上门的高效采购模式，帮百万商家节省了采购时间与成本，助力平台伙伴共同发展，在万亿市场共享机遇。\n在这里，你将收获完善的员工发展机制及学习体系，与各界专家一起深度参与餐饮供应链业务的发展。欢迎优秀的你加入美团快驴进货，与我们一起成长，一起更好！\n\n岗位职责\n岗位职责:\n1.负责标品招商工作，包括开发新的供应商资源，筛选合适供应商入驻等。\n2.负责建立和维护与供应商的良好关系，确保供应链畅通，保证商品的质量和交货准时。\n3.负责监控市场动态，分析竞争对手的招商策略，制定相应的应对措施。\n4.协调内部各部门，确保招商工作与公司整体战略的协调一致。\n\n岗位基本要求\n1.大学本科及以上学历，专业不限，有相关供应链管理、招商采购经验者优先。\n2.有3年以上商品招商经验，熟悉市场招商流程和规则，具备一定的谈判技巧和沟通能力。\n3.具备团队合作精神，能够带领团队高效完成工作，有较强的执行力和解决问题能力。\n4.对商品市场有敏锐的洞察力，有较强的商业敏感度和商业分析能力\n\n具备以下条件优先\n具备干货、调味品行业经验和资源。较好的控商能力\n\n岗位亮点\n1.所在城市：武汉，商业氛围浓厚，市场潜力大。\n2.机会：作为初级标品招商，可以在这个岗位上锻炼和提升自己的招商能力，为未来的职业发展奠定基础。\n3.发展：公司提供良好的晋升机会和培训体系，可以在这里实现个人职业目标并获得个人成长。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4390862532","sourceKey":"meituan_social","company":"美团","title":"小象超市-配送渠道经理（重庆）","city":"重庆市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4390862532&jobShareType=1","duty":"1.制定区域配送管理的方案，监督现场执行情况，检查小象超市站点配送的日常管理，流程上的监督、纠正；\n2.推动本区域业务运营落地工作，监控日常运营、服务质量、指标数据；\n3.负责区域的履约问题收集、反馈和解决工作，运营运作异常事件的跟进处理、总结分析、监督改进；\n4.负责区域内督导、骑手的培训工作，提高员工的综合素质和业务能力；\n5.负责区域内站点的服务质量，分析配送客诉，采取有效措施把控客诉，提供专业、高效、高质量的配送服务，提升顾客满意度。","requirements":"1.本科及以上学历，物流管理或供应链管理专业或3年以上配送运营相关工作经验；\n2.具有良好的沟通协调技巧和团队合作意识，跨部门协调能力，能与其他部门或者外部单位良好的沟通，踏实认真，有责任感；\n3.对数据变化敏感，有优秀的数据分析能力和学习能力，熟练使用各类办公软件；\n4.具备一定的文档处理能力，熟练操作常用办公软件；\n5.具备较强执行力，能适应高强度的工作和阶段性出差；\n6.具备较强的市场开拓性，有项目管理能力，思路清晰，管理协调能力佳。\n7.掌握基本的AI工具，使用工具提升工作流程效率。\n具备以下优先：\n有即时配送相关从业经验优先","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1.制定区域配送管理的方案，监督现场执行情况，检查小象超市站点配送的日常管理，流程上的监督、纠正；\n2.推动本区域业务运营落地工作，监控日常运营、服务质量、指标数据；\n3.负责区域的履约问题收集、反馈和解决工作，运营运作异常事件的跟进处理、总结分析、监督改进；\n4.负责区域内督导、骑手的培训工作，提高员工的综合素质和业务能力；\n5.负责区域内站点的服务质量，分析配送客诉，采取有效措施把控客诉，提供专业、高效、高质量的配送服务，提升顾客满意度。\n\n岗位基本要求\n1.本科及以上学历，物流管理或供应链管理专业或3年以上配送运营相关工作经验；\n2.具有良好的沟通协调技巧和团队合作意识，跨部门协调能力，能与其他部门或者外部单位良好的沟通，踏实认真，有责任感；\n3.对数据变化敏感，有优秀的数据分析能力和学习能力，熟练使用各类办公软件；\n4.具备一定的文档处理能力，熟练操作常用办公软件；\n5.具备较强执行力，能适应高强度的工作和阶段性出差；\n6.具备较强的市场开拓性，有项目管理能力，思路清晰，管理协调能力佳。\n7.掌握基本的AI工具，使用工具提升工作流程效率。\n具备以下优先：\n有即时配送相关从业经验优先\n\n岗位亮点\n1、基于生鲜配送新型业态，完善的内部培训以及晋升机制，未来发展空间大\n2、配送能力是社区生鲜零售行业的核心竞争力，工作重要性高、成长快","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4744115270","sourceKey":"meituan_social","company":"美团","title":"核心本地商业-招聘经理","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4744115270&jobShareType=1","duty":"1. 规划所负责业务的招聘策略并实施。主导从岗位分析、定制人才画像、制定寻访策略、筛选评估、流程推进到人才吸引的全流程招聘工作。  \n2. 能够与业务管理者定期对话，深入理解业务战略与组织规划，主动输出人才市场洞察与招聘策略建议\n3. 通过校招建设所业务面向未来的人才梯队，联动各方分析并推动校招需求落地，持续校准优化流程，定制出牌吸引策略，支持业务发展。\n4. 通过组织研究等方法了解行业内信息，促进业务发展。建立战略性人脉圈，成为公司和行业资深人士的连接者。\n5. 数据驱动持续优化： 基于 AI 输出的招聘漏斗分析，诊断瓶颈环节并提出改进方案；定期复盘招聘效果，推动流程优化。","requirements":"1. 本科以上学历，5年左右HR经验，3年以上招聘工作经验；\n2. 熟悉HR全领域的相关基础知识，能够独立负责招聘全流程；\n3. 熟悉招聘流程及招聘技巧，良好的沟通能力，韧性足；\n4. 具备良好的学习和沟通能力，良好的团队协作精神，主动学习、积极驱动的能力，反应灵敏，责任心强；\n5. AI 工具应用意识：愿意拥抱 AI 工具，善于利用技术手段提升工作效率；至少有使用 AI 辅助工作的实际经验（如 ChatGPT、Copilot 或类似工具）","description":"部门介绍\n核心本地商业（Core Local Commerce）是美团“零售+科技”战略的重要载体，涵盖了到店餐饮、服务零售、酒店旅行、外卖、履约配送、闪购、医药健康等多个业务，覆盖了超过200个消费场景，致力于通过“随时随地”的商品和服务，满足消费者的多样性需求，帮大家吃得更好，生活更好。核心本地商业扎根本地消费，围绕消费者的“吃、住、行、游、购、娱”进行深度创新，引领发展了即时零售、团购等多种消费业态，并在全国范围内广泛投资发展本地供给、履约平台等设施，助力创造产业、带动就业。基于多年的持续投入，核心本地商业打造了连接全国超过一千万中小微企业的服务体系，以及全球最大的即时配送网络。由核心本地商业所推行的30分钟“万物到家”体系，已覆盖全国2800多个城镇，为数亿用户提供优质的商品与服务。发展过程中，核心本地商业有效助力商超、连锁、本地小店等各类实体经济主体扩大交易规模、降低交易成本。截至目前，核心本地商业日均创造订单量数千万笔，助力千万商户实现了高质量发展。未来，核心本地商业将继续践行美团“零售+科技”战略，通过更大的投资，更多的技术创新，支持、培育消费新业态，为促进消费、服务民生、带动就业作出力所能及的贡献。欢迎优秀的你加入核心本地商业，我们携手助力市场繁荣，为用户创造更好的消费体验。\n\n岗位职责\n1. 规划所负责业务的招聘策略并实施。主导从岗位分析、定制人才画像、制定寻访策略、筛选评估、流程推进到人才吸引的全流程招聘工作。  \n2. 能够与业务管理者定期对话，深入理解业务战略与组织规划，主动输出人才市场洞察与招聘策略建议\n3. 通过校招建设所业务面向未来的人才梯队，联动各方分析并推动校招需求落地，持续校准优化流程，定制出牌吸引策略，支持业务发展。\n4. 通过组织研究等方法了解行业内信息，促进业务发展。建立战略性人脉圈，成为公司和行业资深人士的连接者。\n5. 数据驱动持续优化： 基于 AI 输出的招聘漏斗分析，诊断瓶颈环节并提出改进方案；定期复盘招聘效果，推动流程优化。\n\n岗位基本要求\n1. 本科以上学历，5年左右HR经验，3年以上招聘工作经验；\n2. 熟悉HR全领域的相关基础知识，能够独立负责招聘全流程；\n3. 熟悉招聘流程及招聘技巧，良好的沟通能力，韧性足；\n4. 具备良好的学习和沟通能力，良好的团队协作精神，主动学习、积极驱动的能力，反应灵敏，责任心强；\n5. AI 工具应用意识：愿意拥抱 AI 工具，善于利用技术手段提升工作效率；至少有使用 AI 辅助工作的实际经验（如 ChatGPT、Copilot 或类似工具）\n\n具备以下条件优先\n1. 有 AI 工具在招聘场景的落地实践经验（如 AI 简历筛选、智能外呼、自动化 sourcing 等）\n2. 有系统化的人才 Mapping / 市场情报搜集方法论/项目运营经验\n3. 具备良好的沟通表达能力，逻辑思考能力和项目管理能力（含进程推进能力），拥有良好的客户需求沟通和管理能力；\n4. 具备较强的自驱力，责任心，学习能力强，良好的团队协作精神、主动学习、积极驱动的能力、反应灵敏等。\n\n岗位亮点\n1. 支持美团核心的业务团队，有挑战有成长\n2. 团队氛围好，沟通坦诚开放","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4601070831","sourceKey":"meituan_social","company":"美团","title":"物流策略运营-新国","city":"利雅得","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4601070831&jobShareType=1","duty":"1. 负责制定并优化新国物流运营策略，提升整体运营效率与成本效益。  \n2. 分析物流数据与市场趋势，识别运营瓶颈并提出改进方案。  \n3. 协调仓储、运输及关务等环节，确保物流流程顺畅并符合当地法规要求。  \n4. 推动物流系统数字化升级，提升自动化与智能化水平。","requirements":"1. 大学本科及以上学历，物流、供应链、管理或相关专业优先。  \n2. 至少4年物流运营或策略规划相关工作经验，有中东地区经验者优先。  \n3. 熟悉国际物流流程、海关政策及沙特本地物流环境。  \n4. 具备较强的数据分析能力与项目管理能力。  \n5. 英语流利，阿拉伯语能力为加分项。","description":"部门介绍\n美团的使命是“帮大家吃得更好，生活更好”，公司聚焦“零售 + 科技”战略，和广大商户与各类合作伙伴一起，努力为消费者提供品质生活，推动商品零售和服务零售在需求侧和供给侧的数字化转型。\n2018年9月20日，美团正式在港交所挂牌上市。美团将始终坚持以客户为中心，不断加大在科技研发方面的投入，更好承担社会责任，更多创造社会价值，与广大合作伙伴一起发展共赢。\n\n岗位职责\n1. 负责制定并优化新国物流运营策略，提升整体运营效率与成本效益。  \n2. 分析物流数据与市场趋势，识别运营瓶颈并提出改进方案。  \n3. 协调仓储、运输及关务等环节，确保物流流程顺畅并符合当地法规要求。  \n4. 推动物流系统数字化升级，提升自动化与智能化水平。\n\n岗位基本要求\n1. 大学本科及以上学历，物流、供应链、管理或相关专业优先。  \n2. 至少4年物流运营或策略规划相关工作经验，有中东地区经验者优先。  \n3. 熟悉国际物流流程、海关政策及沙特本地物流环境。  \n4. 具备较强的数据分析能力与项目管理能力。  \n5. 英语流利，阿拉伯语能力为加分项。\n\n岗位亮点\n1. 参与公司海外战略布局，推动区域物流体系升级。  \n2. 与多元文化团队合作，拓展国际视野与职业发展空间。  \n3. 提供具有竞争力的薪酬与完善的福利保障。  \n4. 工作地点位于利雅得核心区域，办公环境优越。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4781234064","sourceKey":"meituan_social","company":"美团","title":"休食采购开发","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4781234064&jobShareType=1","duty":"1. 负责休食品类（糖巧、膨化、饼干曲奇、方便面、冲调饮品、罐头/火腿肠、豆干素食、果干蜜饯、肉干肉脯、坚果炒货、糕点面包、新式速食等）的自有品牌产品开发与采购工作；\n2. 完成新品立项、供应商筛选、工厂访厂评估，推动新品从立项到上架的全流程落地；\n3. 进行市场调研与分析，输出选品策略和价格带规划；\n4. 管理供应商关系，负责成本谈判、品质管控及供应链稳定性保障；\n5. 跟踪单品动销数据，完成上架后复盘，推动滞销品优化与迭代；\n6. 协助完成品类货架规划、SKU汰换及毛利优化。","requirements":"1. 大学本科及以上学历，5年以上休食或快消品行业采购开发相关工作经验，有自有品牌（PB）开发经验者优先。  \n2. 熟悉休闲食品行业供应链体系，了解代工体系、成本结构、包材及物流成本构成，具备丰富的供应商资源与谈判能力。  \n3. 具备工厂访厂评估能力，能从\"硬件+软件\"双维度评估供应商综合竞争力；\n4. 具备良好的沟通协调能力与跨部门协作经验，执行力好，能同时推进多支单品并行开发。  \n5. 工作地点为北京市，能适应一定频率的出差安排。\n6. 具备数据分析能力，能通过动销数据驱动品类决策；","description":"部门介绍\n快乐猴是美团自营社区超市，依托自有供应链和门店管理体系，聚焦家庭用户的三餐所需，为消费者提供高质价比的食杂商品。快乐猴以数字化能力与科学品控为基础，不断满足消费者对“省”和“便利”的需求。\n\n岗位职责\n1. 负责休食品类（糖巧、膨化、饼干曲奇、方便面、冲调饮品、罐头/火腿肠、豆干素食、果干蜜饯、肉干肉脯、坚果炒货、糕点面包、新式速食等）的自有品牌产品开发与采购工作；\n2. 完成新品立项、供应商筛选、工厂访厂评估，推动新品从立项到上架的全流程落地；\n3. 进行市场调研与分析，输出选品策略和价格带规划；\n4. 管理供应商关系，负责成本谈判、品质管控及供应链稳定性保障；\n5. 跟踪单品动销数据，完成上架后复盘，推动滞销品优化与迭代；\n6. 协助完成品类货架规划、SKU汰换及毛利优化。\n\n岗位基本要求\n1. 大学本科及以上学历，5年以上休食或快消品行业采购开发相关工作经验，有自有品牌（PB）开发经验者优先。  \n2. 熟悉休闲食品行业供应链体系，了解代工体系、成本结构、包材及物流成本构成，具备丰富的供应商资源与谈判能力。  \n3. 具备工厂访厂评估能力，能从\"硬件+软件\"双维度评估供应商综合竞争力；\n4. 具备良好的沟通协调能力与跨部门协作经验，执行力好，能同时推进多支单品并行开发。  \n5. 工作地点为北京市，能适应一定频率的出差安排。\n6. 具备数据分析能力，能通过动销数据驱动品类决策；\n\n岗位亮点\n1. 加入快速发展的消费品牌，参与核心品类建设，成长空间广阔。  \n2. 扁平化管理，决策高效，个人贡献直接影响业务成果。  \n3. 提供具有市场竞争力的薪酬与完善的福利体系。  \n4. 团队氛围开放积极，注重专业能力与职业素养的双重提升。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4782803128","sourceKey":"meituan_social","company":"美团","title":"酒水饮料品类运营","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4782803128&jobShareType=1","duty":"1. 深入调研行业及市场信息，洞察供给端及用户需求变化的规律及趋势，负责酒水饮料品类的全年商品规划、跟进产品的全生命周期管理，孵化新品和打造爆品\n2. 分析市场趋势与行业动态，结合平台用户画像，制定并执行品类运营策略与营销方案 \n3. 定期输出品类运营数据分析报告，为业务决策提供数据支持\n4.协同采购、供应链、供应商管理团队，为品类规模和UE负责 \n5.及时快速的响应、解决相关业务团队的问题，优化工作流程及工作方法","requirements":"1. 大学本科及以上学历，5年以上零售行业商品运营经验，有酒水饮料品类经验者优先。  \n2. 熟悉酒水饮料行业供应链与商品特性，具备敏锐的市场洞察力与数据分析能力。  \n3. 具备较强的策略思维与项目管理能力，能独立推动跨部门协作与复杂项目落地。","description":"部门介绍\n快乐猴是美团自营社区超市，依托自有供应链和门店管理体系，聚焦家庭用户的三餐所需，为消费者提供高质价比的食杂商品。快乐猴以数字化能力与科学品控为基础，不断满足消费者对“省”和“便利”的需求。\n\n岗位职责\n1. 深入调研行业及市场信息，洞察供给端及用户需求变化的规律及趋势，负责酒水饮料品类的全年商品规划、跟进产品的全生命周期管理，孵化新品和打造爆品\n2. 分析市场趋势与行业动态，结合平台用户画像，制定并执行品类运营策略与营销方案 \n3. 定期输出品类运营数据分析报告，为业务决策提供数据支持\n4.协同采购、供应链、供应商管理团队，为品类规模和UE负责 \n5.及时快速的响应、解决相关业务团队的问题，优化工作流程及工作方法\n\n岗位基本要求\n1. 大学本科及以上学历，5年以上零售行业商品运营经验，有酒水饮料品类经验者优先。  \n2. 熟悉酒水饮料行业供应链与商品特性，具备敏锐的市场洞察力与数据分析能力。  \n3. 具备较强的策略思维与项目管理能力，能独立推动跨部门协作与复杂项目落地。\n\n岗位亮点\n1. 与行业头部品牌/供应商深度合作，拓展资源与专业视野  \n2. 扁平化管理机制，提供快速成长与晋升通道。  \n3. 团队氛围开放，鼓励创新与数据驱动决策。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4493540702","sourceKey":"meituan_social","company":"美团","title":"客服大模型产品运营","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4493540702&jobShareType=1","duty":"1.  根据业务的服务场景和知识，设计制定大模型机器人的解决方案，确保用户体验的连贯性和有效性。\n2. 与产品、算法、运营、业务方保持协同，制定业务规划、梳理需求MRD文档，参与需求和方案评审及讲解，共同优化模型及agent体验效果。\n3. 基于数据分析评估各业务的产品功能使用情况并调整运营策略，设计合理的工具系统产品方案并落地。","requirements":"1.本科及以上学历，3年以上客户服务行业经验。\n2. 有agent搭建，AI数据生产和评估相关领域背景、对主流大模型有一定了解。技能项至少具备其一（模型训练SFT，评测，数据处理 or prompt工程、大模型产品经验）；\n3. 熟练使用数据分析工具，具备数据获取、分类和分析能力；\n4. 能准确理解业务诉求，对数据变化敏锐，能通过独到的视角或科学的方法发现并解决问题，推动业务指标达成和策略落地；","description":"部门介绍\n美团平台为用户的基础产品体验负责，还承担了美团的用户增长、市场和品牌营销以及多条业务线的产品设计职责，建立了融合文字、图片、视频和直播等不同形式的內容生态系统，同时整合地图服务部、客户服务和体验部、企业业务部、网约车业务部等部门，致力于用科技提升美团数亿消费者、近千万商家、骑手、司机和团长的服务体验。美团平台拥有高并发、多业务的复杂场景，为技术深度优化提供了最佳实践可能。这里有简单、讲逻辑、有爱的团队，更是一块理想的实战场地，舞台广阔，欢迎你来尽情施展。\n\n岗位职责\n1.  根据业务的服务场景和知识，设计制定大模型机器人的解决方案，确保用户体验的连贯性和有效性。\n2. 与产品、算法、运营、业务方保持协同，制定业务规划、梳理需求MRD文档，参与需求和方案评审及讲解，共同优化模型及agent体验效果。\n3. 基于数据分析评估各业务的产品功能使用情况并调整运营策略，设计合理的工具系统产品方案并落地。\n\n岗位基本要求\n1.本科及以上学历，3年以上客户服务行业经验。\n2. 有agent搭建，AI数据生产和评估相关领域背景、对主流大模型有一定了解。技能项至少具备其一（模型训练SFT，评测，数据处理 or prompt工程、大模型产品经验）；\n3. 熟练使用数据分析工具，具备数据获取、分类和分析能力；\n4. 能准确理解业务诉求，对数据变化敏锐，能通过独到的视角或科学的方法发现并解决问题，推动业务指标达成和策略落地；\n\n具备以下条件优先\n大模型客服系统相关经验；agent应用经验；\n\n岗位亮点\n1.深度参与AI革新，成为科技先锋：近距离接触先进的大模型技术，深度参与客服大模型应用，与优秀团队共同成长。\n2.引领客服未来，成就非凡事业：参与具有战略意义的项目，携手构建开创性的大模型智能客服应用。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4791703023","sourceKey":"meituan_social","company":"美团","title":"班组负责人","city":"广州市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4791703023&jobShareType=1","duty":"1. 负责班组日常运营管理，确保仓储作业流程高效、安全执行。  \n2. 带领团队完成出入库、分拣、盘点等物流任务，保障作业时效与准确性。  \n3. 监督现场操作规范，落实安全生产制度，预防和减少作业事故。  \n4. 协调与其他部门的工作对接，优化仓储资源配置，提升整体运营效率。","requirements":"1. 大学专科及以上学历，物流、供应链或相关专业优先。  \n2. 具备3年以上仓储或物流现场管理经验，有团队管理背景。  \n3. 熟悉仓储管理系统及作业流程，具备较强的组织协调能力。  \n4. 工作细致有较强责任心","description":"部门介绍\n快乐猴是美团自营社区超市，依托自有供应链和门店管理体系，聚焦家庭用户的三餐所需，为消费者提供高质价比的食杂商品。快乐猴以数字化能力与科学品控为基础，不断满足消费者对“省”和“便利”的需求。\n\n岗位职责\n1. 负责班组日常运营管理，确保仓储作业流程高效、安全执行。  \n2. 带领团队完成出入库、分拣、盘点等物流任务，保障作业时效与准确性。  \n3. 监督现场操作规范，落实安全生产制度，预防和减少作业事故。  \n4. 协调与其他部门的工作对接，优化仓储资源配置，提升整体运营效率。\n\n岗位基本要求\n1. 大学专科及以上学历，物流、供应链或相关专业优先。  \n2. 具备3年以上仓储或物流现场管理经验，有团队管理背景。  \n3. 熟悉仓储管理系统及作业流程，具备较强的组织协调能力。  \n4. 工作细致有较强责任心\n\n具备以下条件优先\n优先仓储物流管理经验者\n\n岗位亮点\n1. 提供完善的培训体系和职业发展通道。  \n2. 团队规模大，管理实践机会丰富，利于个人成长。  \n3. 工作地点位于广州市，交通便利，配套设施齐全。  \n4. 享有具有竞争力的薪酬福利及绩效激励机制。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4792485979","sourceKey":"meituan_social","company":"美团","title":"Global Mobility 全球派遣运营专员","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4792485979&jobShareType=1","duty":"- 全球派遣（外派）台账与日常运营维护：负责外派人员日常运营台账的更新与维护，确保每日新增外派人员信息及时、准确落账，并同步至下游 local ops 团队（如沙特工签台账、GCC 国家 onboarding 台账），保障信息传递零遗漏。\n- 外派协议全生命周期管理：负责外派协议的发放、签署跟进与催办，及存量协议的核查、扫描与归档，确保协议签署及时率与归档完整率达到团队标准。\n- 跨团队信息同步：基于外派发薪台账，定期更新财务报表及 HRBP 维度表格，保障下游团队获取的外派信息准确一致。\n- 外派数据质检与校正：结合每月 payroll cutoff 对外派数据进行异常核查（如员工入境信息），跟进员工确认；配合质检组定期校正台账与底盘数据，持续提升基础数据质量。\n- 外派数据分析支持：支持不定期的外派数据分析需求（如年度复盘中外派基础现状分析），沉淀可复用的数据模板。","requirements":"本科及以上学历，0-2 年工作经验，人力资源、行政管理、财务、数据或相关专业优先。\n有 HR 共享服务中心、人事运营或涉外事务实习/工作经验者加分。\n细心踏实、责任心强，对数据和数字敏感，能在重复性事务中保持高准确率。\n有基础的数据整理和核对能力。\n具备良好的跨团队沟通与跟进能力，能主动推动事项闭环。\n英语具备读写能力，能处理境外员工信息、与海外团队进行日常书面沟通。","description":"部门介绍\n美团HR的使命是“建设有生命力的组织，为客户和社会创造价值。” 我们认为HR的工作不是以自身“专业”为中心，而是要建设有助于员工发挥创造力的环境，支持他们更好地为外部客户和社会创造价值，也实现组织自身的进化和传承。在这个过程中，我们的每位HR同学都是“业务的战略合作伙伴、组织能力的建设者、美团精神的布道者、员工的成长伙伴”。我们要设计面向长期支撑组织有效运转的机制，我们要求真务实地帮业务解决发展中的问题和阵痛，我们要支持每一位员工历经磨炼收获成长。我们要影响和驱动让世界更美好的变化发生。如果这也是你追求的，欢迎加入美团HR，与我们一路同行！\n\n岗位职责\n- 全球派遣（外派）台账与日常运营维护：负责外派人员日常运营台账的更新与维护，确保每日新增外派人员信息及时、准确落账，并同步至下游 local ops 团队（如沙特工签台账、GCC 国家 onboarding 台账），保障信息传递零遗漏。\n- 外派协议全生命周期管理：负责外派协议的发放、签署跟进与催办，及存量协议的核查、扫描与归档，确保协议签署及时率与归档完整率达到团队标准。\n- 跨团队信息同步：基于外派发薪台账，定期更新财务报表及 HRBP 维度表格，保障下游团队获取的外派信息准确一致。\n- 外派数据质检与校正：结合每月 payroll cutoff 对外派数据进行异常核查（如员工入境信息），跟进员工确认；配合质检组定期校正台账与底盘数据，持续提升基础数据质量。\n- 外派数据分析支持：支持不定期的外派数据分析需求（如年度复盘中外派基础现状分析），沉淀可复用的数据模板。\n\n岗位基本要求\n本科及以上学历，0-2 年工作经验，人力资源、行政管理、财务、数据或相关专业优先。\n有 HR 共享服务中心、人事运营或涉外事务实习/工作经验者加分。\n细心踏实、责任心强，对数据和数字敏感，能在重复性事务中保持高准确率。\n有基础的数据整理和核对能力。\n具备良好的跨团队沟通与跟进能力，能主动推动事项闭环。\n英语具备读写能力，能处理境外员工信息、与海外团队进行日常书面沟通。\n\n具备以下条件优先\n有 HR 共享服务中心、人事运营或涉外事务实习/工作经验者加分。\n\n岗位亮点\n深入接触全球派遣（Global Mobility）全流程，覆盖工签、协议、薪酬数据、合规等完整链路；\n与财务、HRBP、海外 local ops 等多方协作的历练，快速建立全局视野；\n表现优秀者可向 Global Mobility 运营专家或数据运营方向发展。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4604203093","sourceKey":"meituan_social","company":"美团","title":"医疗服务业务部/口腔全国销售中心/口腔CBD区域","city":"郑州市/武汉市/深圳市/北京市/上海市/杭州市/广州市/成都市/西安市/厦门市/济南市/石家庄市/重庆市/天津市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4604203093&jobShareType=1","duty":"1.负责口腔行业产品在所负责区域的销售业绩达成。\n2.维护现有客户关系，提升客户满意度。\n3.负责制定销售计划和执行方案，确保销售目标的达成。\n4.协调内部资源，提供客户定制化的解决方案。\n5.分析市场竞争情况，及时调整销售策略，通过对行业经营诊断、投放指南、优化广告消耗计划，提升交易线上化、行业广告产品渗透率等。","requirements":"1.大学本科及以上学历，市场营销、KA经验优先。\n2.具备良好的沟通能力和团队合作精神。\n3.具备一定的销售经验，口腔、眼部健康和眼镜行业销售经验者优先。\n4.具备良好的学习能力和适应能力，能够适应高强度的工作压力。\n5.具备较强的市场洞察力和分析能力。","description":"部门介绍\n美团医药健康事业部是美团核心本地商业板块下专注健康领域的业务部门，涵盖美团买药、美团医美和美团医疗三大业务。自创立以来，美团医药健康致力于为用户提供全健康周期产品及服务，满足人民群众多层次多元化医疗健康需求，现已覆盖购药到家、居家检测、问诊挂号、医保支付、求医寻院、医疗美容等核心场景。此外，美团医药健康还为商户提供数字化转型创新解决方案，打造贯穿上游的联动机制，长期参与共建更透明、更可持续的医药健康产业生态圈，目前业务已覆盖25万家药店，收录27万家医疗机构。未来，美团医药康将协同更多行业伙伴，帮助大家变得更健康、更美丽、更养生。\n\n岗位职责\n1.负责口腔行业产品在所负责区域的销售业绩达成。\n2.维护现有客户关系，提升客户满意度。\n3.负责制定销售计划和执行方案，确保销售目标的达成。\n4.协调内部资源，提供客户定制化的解决方案。\n5.分析市场竞争情况，及时调整销售策略，通过对行业经营诊断、投放指南、优化广告消耗计划，提升交易线上化、行业广告产品渗透率等。\n\n岗位基本要求\n1.大学本科及以上学历，市场营销、KA经验优先。\n2.具备良好的沟通能力和团队合作精神。\n3.具备一定的销售经验，口腔、眼部健康和眼镜行业销售经验者优先。\n4.具备良好的学习能力和适应能力，能够适应高强度的工作压力。\n5.具备较强的市场洞察力和分析能力。\n\n具备以下条件优先\n具备医疗行业经验，有过大客户服务经验优先\n\n岗位亮点\n1.在口腔领域有广阔的发展空间。\n2.薪资福利待遇优厚，晋升空间大。\n3.能够接触到新的产品和技术，不断提升专业能力。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3457891059","sourceKey":"meituan_social","company":"美团","title":"Keeta技术-高级/资深广告投放工程师（AI 与智能投放方向）","city":"深圳市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3457891059&jobShareType=1","duty":"1、负责海外广告投放平台建设，覆盖素材生产、广告管理、投放策略、数据分析与归因等核心环节。\n2、推动 AI 在广告业务中的应用，包括智能素材生产、广告创编、投放分析、异常诊断和策略辅助。\n3、对接 Meta、Google、TikTok 等主流媒体平台，建设稳定、高效的广告创建、管理和效果回收能力。\n4、参与智能投放策略建设，围绕预算、出价、素材和人群等要素，提升投放效率与效果。\n5、建设海外广告归因与效果评估体系，完成 MMP、媒体转化接口及隐私归因方案的设计与落地。\n6、与投放、设计、产品、数据和算法团队协作，推动素材、策略、执行与效果分析形成业务闭环。","requirements":"1、5 年以上广告技术、增长平台、营销数据或归因系统相关经验，有复杂系统设计及落地经验。\n2、熟悉海外广告业务，在素材生产、投放策略、数据分析与归因等方向具备完整认知，并至少在一个方向有深入实践。\n3、熟悉 Meta、Google、TikTok 等主流媒体的广告体系、优化机制及相关 API。\n4、了解生成式 AI、大模型或 Agent 的应用方式，有将 AI 能力落地到真实业务场景的经验。\n5、熟悉 AppsFlyer、Adjust 等 MMP，理解主流归因模型以及 iOS ATT、SKAdNetwork 等隐私归因机制。\n6、精通 Java 或 Python，熟练掌握 SQL，熟悉 Kafka、Flink、Hive/Spark 等数据处理技术。\n7、数据敏感、逻辑清晰，能够结合实验和业务指标分析问题，具备良好的跨团队协作能力。","description":"部门介绍\n美团核心本地商业下业务研发平台，基于公司“零售+科技”的战略导向，通过从底层架构到应用系统、从软件到硬件、从传统算法到GenAI的全方位技术研究，以及开发、运维、安全等全流程能力建设，致力于推动美团核心本地商业下需求侧与供给侧的数字化和智能化升级，助力业务实现高质量增长，优化用户使用体验，提升商户经营水平，促进行业生态伙伴关系的持续健康发展。团队秉持务实、自驱、开放以及追求卓越的工程师文化，一方面通过系统和技术体系的持续迭代升级，帮助业务高质量增长；另一方面，密切关注前沿技术趋势变化，积极创新技术能力，为业务未来发展创造新的可能性。期待优秀的你加入我们，在夯实专业、深耕平台的基础上与业务携手同行，一起用技术 “帮大家吃得更好，生活更好”。\n\n岗位职责\n1、负责海外广告投放平台建设，覆盖素材生产、广告管理、投放策略、数据分析与归因等核心环节。\n2、推动 AI 在广告业务中的应用，包括智能素材生产、广告创编、投放分析、异常诊断和策略辅助。\n3、对接 Meta、Google、TikTok 等主流媒体平台，建设稳定、高效的广告创建、管理和效果回收能力。\n4、参与智能投放策略建设，围绕预算、出价、素材和人群等要素，提升投放效率与效果。\n5、建设海外广告归因与效果评估体系，完成 MMP、媒体转化接口及隐私归因方案的设计与落地。\n6、与投放、设计、产品、数据和算法团队协作，推动素材、策略、执行与效果分析形成业务闭环。\n\n岗位基本要求\n1、5 年以上广告技术、增长平台、营销数据或归因系统相关经验，有复杂系统设计及落地经验。\n2、熟悉海外广告业务，在素材生产、投放策略、数据分析与归因等方向具备完整认知，并至少在一个方向有深入实践。\n3、熟悉 Meta、Google、TikTok 等主流媒体的广告体系、优化机制及相关 API。\n4、了解生成式 AI、大模型或 Agent 的应用方式，有将 AI 能力落地到真实业务场景的经验。\n5、熟悉 AppsFlyer、Adjust 等 MMP，理解主流归因模型以及 iOS ATT、SKAdNetwork 等隐私归因机制。\n6、精通 Java 或 Python，熟练掌握 SQL，熟悉 Kafka、Flink、Hive/Spark 等数据处理技术。\n7、数据敏感、逻辑清晰，能够结合实验和业务指标分析问题，具备良好的跨团队协作能力。\n\n具备以下条件优先\n1、从 0 到 1 建设过广告投放、智能策略、归因或素材生产平台。\n2、有多模态生成、图片/视频处理、智能分析或广告 Agent 的落地经验。\n3、有预算优化、出价策略、A/B 测试、因果推断或增量评估经验。\n4、有 O2O、外卖、本地生活、电商或全球化业务经验。\n\n岗位亮点\n1、参与 Keeta 海外业务从 0 到 1，深入参与广告增长核心系统建设。\n2、团队正在将 AI 应用于素材生产、投放策略和数据分析等真实业务场景，能够参与从方案设计到生产落地的全过程。\n3、岗位覆盖广告完整链路，不局限于单一归因、数据或平台对接模块。\n4、面向多个海外市场和主流媒体平台，具备丰富的全球化业务与技术挑战。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4597518210","sourceKey":"meituan_social","company":"美团","title":"餐饮SaaS HRBP","city":"北京市/成都市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4597518210&jobShareType=1","duty":"岗位职责：\n1.作为业务部门的HR合作伙伴，理解公司战略和业务目标，在人才招聘、人才发展、组织发展等领域提供专业支持。善于借助AI工具提升工作质量和效率——不是“了解AI”，是已经在用AI改变自己的工作方式；\n2.关注业务部门人员配置合理性，协助优化团队结构、搭建人才梯队。能用数据和AI辅助判断：哪些岗位需要扩、哪些角色在变化、人才供给的瓶颈在哪里——而不是只靠经验和感觉；\n3.通过人才盘点、人才发展等方法，识别、培养和留任关键人才。在这个过程中，关注团队成员对AI工具的接受度和使用深度——谁在主动用AI重构自己的工作方式，谁还停在原地，这本身就是人才识别的新维度；\n4.推动人力资源各项制度在部门的落地执行，并持续反馈和改进。愿意用AI优化自己在制度宣贯、数据追踪、流程跟进等环节的效率，把省下来的时间花在更需要判断力的事情上；\n5.协助完成人力资源其他模块的工作。","requirements":"1.本科及以上学历，5年及以上人力资源工作经验，在组织发展、人才发展等方面有深入理解和实际产出；\n2.自己就是AI的真实用户——日常工作中已经在用AI，能说清楚它帮你改变了什么、省下的时间你拿来做了什么；\n3.能在信息不完整的时候自己定义问题，不等业务方给明确需求，主动看到问题、形成假设、推动验证；\n4.对业务有真实的好奇心，愿意花时间搞懂销售团队在做什么、客户为什么来或走，不满足于只在HR的圈子里转；\n互联网行业工作经验优先；\n5.沟通清晰，逻辑好，有同理心，能平衡多任务多角色。","description":"部门介绍\n美团HR的使命是“建设有生命力的组织，为客户和社会创造价值。” 我们认为HR的工作不是以自身“专业”为中心，而是要建设有助于员工发挥创造力的环境，支持他们更好地为外部客户和社会创造价值，也实现组织自身的进化和传承。在这个过程中，我们的每位HR同学都是“业务的战略合作伙伴、组织能力的建设者、美团精神的布道者、员工的成长伙伴”。我们要设计面向长期支撑组织有效运转的机制，我们要求真务实地帮业务解决发展中的问题和阵痛，我们要支持每一位员工历经磨炼收获成长。我们要影响和驱动让世界更美好的变化发生。如果这也是你追求的，欢迎加入美团HR，与我们一路同行！\n\n岗位职责\n岗位职责：\n1.作为业务部门的HR合作伙伴，理解公司战略和业务目标，在人才招聘、人才发展、组织发展等领域提供专业支持。善于借助AI工具提升工作质量和效率——不是“了解AI”，是已经在用AI改变自己的工作方式；\n2.关注业务部门人员配置合理性，协助优化团队结构、搭建人才梯队。能用数据和AI辅助判断：哪些岗位需要扩、哪些角色在变化、人才供给的瓶颈在哪里——而不是只靠经验和感觉；\n3.通过人才盘点、人才发展等方法，识别、培养和留任关键人才。在这个过程中，关注团队成员对AI工具的接受度和使用深度——谁在主动用AI重构自己的工作方式，谁还停在原地，这本身就是人才识别的新维度；\n4.推动人力资源各项制度在部门的落地执行，并持续反馈和改进。愿意用AI优化自己在制度宣贯、数据追踪、流程跟进等环节的效率，把省下来的时间花在更需要判断力的事情上；\n5.协助完成人力资源其他模块的工作。\n\n岗位基本要求\n1.本科及以上学历，5年及以上人力资源工作经验，在组织发展、人才发展等方面有深入理解和实际产出；\n2.自己就是AI的真实用户——日常工作中已经在用AI，能说清楚它帮你改变了什么、省下的时间你拿来做了什么；\n3.能在信息不完整的时候自己定义问题，不等业务方给明确需求，主动看到问题、形成假设、推动验证；\n4.对业务有真实的好奇心，愿意花时间搞懂销售团队在做什么、客户为什么来或走，不满足于只在HR的圈子里转；\n互联网行业工作经验优先；\n5.沟通清晰，逻辑好，有同理心，能平衡多任务多角色。\n\n具备以下条件优先\n逻辑性好、有好奇心、有AI实际使用经验\n\n岗位亮点\n1.快速发展的to B业务，职业发展空间大；\n2.志同道合的HRBP伙伴，在工作中实现能力的大幅提升；\n3.团队正在探索AI融入HR日常工作的实践路径——你不只是用AI，也在参与定义“AI时代的HRBP应该怎么工作”。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4790953766","sourceKey":"meituan_social","company":"美团","title":"工程财务BP","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4790953766&jobShareType=1","duty":"1. 工程造价与预算\n- 根据工程组提报的设计施工方案，审核工程造价、概算预算合理性；\n- 审核工程量清单、计价依据合理性；\n- 熟练使用AI辅助工具（如大模型、智能造价软件）进行工程量清单核查、预算合理性分析，提升审核效率；\n- 能够结合AI预测模型，对工程造价趋势进行预判，辅助决策。\n2. 成本及风险管理\n- 审核设计标准合理性，结构化门店配置清单，建立合理化成本评估标准；\n- 参与集采招标，评估报价方案，选择最优供应商；\n- 监控施工进度、成本变化，识别工程管理中的风险点；\n- 建立工程、设备全生命周期成本评估机制；\n- 持续完善优化工程结算流程；\n- 运用AI/数据分析工具对供应商报价、采购数据进行智能比价与风险识别；\n- 借助AI手段构建门店成本评估模型，实现成本异常的自动预警与识别；\n- 推动AI工具在工程结算流程中的落地应用，持续提升工作自动化水平。\n3. 行业研究\n- 通过行业调研了解行业通行的门店工程设计方案、功能标准、成本水平，结合公司业务要求，持续寻求合理优化机会；\n- 能够利用AI工具进行行业信息检索，辅助行业研究与洞察提炼。","requirements":"1. 工程造价、工程管理、工程经济、审计学专业，大学本科及以上学历；\n2. 有大型建筑企业、会计师事务所工程审计部门从业经历优先；\n3. 熟悉工程施工工艺、工程量计算规则、造价软件；\n4. 掌握内控、审计方法流程，熟练使用办公室软件处理大规模工程数据；\n5. 良好的沟通能力、逻辑思维能力；\n6. 有AI工具使用经验或数据分析能力优先（如熟悉大模型应用、BI工具、Python数据处理等）。","description":"部门介绍\n财务平台负责公司整体和各业务层面的财务管理工作，通过建设专业、全面、复合的财务管理能力和与业务经营的紧密结合来支持公司健康发展。目前财务平台拥有财务会计、财务报告、资金管理、税务管理、财务共享、财务系统、规划分析、财务BP和内控内审等主要工作方向。我们的目标是建设业界一流的财务管理能力和经营支持体系，为公司战略的正确落地、投入效率的持续提升、业务价值的不断增长保驾护航。欢迎加入财务平台，携手一起向未来！\n\n岗位职责\n1. 工程造价与预算\n- 根据工程组提报的设计施工方案，审核工程造价、概算预算合理性；\n- 审核工程量清单、计价依据合理性；\n- 熟练使用AI辅助工具（如大模型、智能造价软件）进行工程量清单核查、预算合理性分析，提升审核效率；\n- 能够结合AI预测模型，对工程造价趋势进行预判，辅助决策。\n2. 成本及风险管理\n- 审核设计标准合理性，结构化门店配置清单，建立合理化成本评估标准；\n- 参与集采招标，评估报价方案，选择最优供应商；\n- 监控施工进度、成本变化，识别工程管理中的风险点；\n- 建立工程、设备全生命周期成本评估机制；\n- 持续完善优化工程结算流程；\n- 运用AI/数据分析工具对供应商报价、采购数据进行智能比价与风险识别；\n- 借助AI手段构建门店成本评估模型，实现成本异常的自动预警与识别；\n- 推动AI工具在工程结算流程中的落地应用，持续提升工作自动化水平。\n3. 行业研究\n- 通过行业调研了解行业通行的门店工程设计方案、功能标准、成本水平，结合公司业务要求，持续寻求合理优化机会；\n- 能够利用AI工具进行行业信息检索，辅助行业研究与洞察提炼。\n\n岗位基本要求\n1. 工程造价、工程管理、工程经济、审计学专业，大学本科及以上学历；\n2. 有大型建筑企业、会计师事务所工程审计部门从业经历优先；\n3. 熟悉工程施工工艺、工程量计算规则、造价软件；\n4. 掌握内控、审计方法流程，熟练使用办公室软件处理大规模工程数据；\n5. 良好的沟通能力、逻辑思维能力；\n6. 有AI工具使用经验或数据分析能力优先（如熟悉大模型应用、BI工具、Python数据处理等）。\n\n岗位亮点\n加入快速发展的业务团队，锻炼全面工程管理能力，提升行业认知，迭代最佳实践，借事修人。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4738134363","sourceKey":"meituan_social","company":"美团","title":"产品经理（点评打卡方向）","city":"上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4738134363&jobShareType=1","duty":"1.负责大众点评打卡发布工具的产品规划与建设，围绕用户到店后的记录场景，持续优化从触发、拍摄/选图、内容编辑、地点关联到发布完成的完整链路；\n2.深入理解用户在餐饮、休闲娱乐、丽人、亲子、旅游等不同场景下的记录需求，持续降低打卡内容生产门槛，提升用户发布意愿、发布效率及内容质量；\n3.负责发布工具核心能力建设，包括但不限于：图片拍摄及编辑能力，文案内容表达能力，智能推荐与创作辅助能力，活动、权益、商家任务等场景化发布能力；\n4.结合AI、多模态等新技术，探索智能选图、文案辅助、内容理解、场景识别等能力，提升用户创作体验及内容生产效率；\n5.建立发布链路核心指标体系，围绕发布转化率、带图率、内容完整度、用户留存及打卡频次等指标持续开展实验、分析和产品迭代。\n6.与设计、研发、算法、数据、运营及商家产品等团队紧密协作，推动复杂项目落地，并持续复盘产品效果。","requirements":"1.3年以上互联网产品经理经验，有内容创作、UGC社区、发布工具、相机/图片视频编辑、生活服务等相关产品经验优先；\n2.对用户创作行为和内容生产链路有较强理解，能够准确识别影响用户发布意愿和效率的关键问题；\n3.具备较强的数据分析和实验意识，能够通过数据拆解问题、形成假设并推动产品验证；\n4.具备较好的交互和产品体验判断能力，对产品细节敏感，能够持续打磨复杂发布链路；\n5.具备良好的项目推动和跨团队协作能力，能够协调设计、研发、算法、运营等多角色完成项目落地；\n6.具备AI工具使用意识和实践经验（如ChatGPT/Claude/Copilot等），能主动将AI能力融入日常工作流。","description":"部门介绍\n大众点评作为国内重要的本地生活消费决策参考平台，多年来深耕本地生活消费领域，深受广大用户的信任和喜爱。我们的业务覆盖了吃喝玩乐游购娱等生活场景，通过极具辨识度和公信力的”星级“和”评价“产品，为数亿用户提供了全面、可信的消费决策依据。为更好满足用户探索城市的需求，大众点评在原有星级和评价的基础上，以信息流产品形式，助力用户发现更多好去处。大量优秀年轻同学的加入，为我们的团队注入了澎湃活力。我们相信，真实的生活是不可替代的，真实的感受是值得记录的，真实的美好是要被看到的。希望优秀的你能和我们一起，帮助广大用户在大众点评上发现更多好去处，找到属于自己的人间烟火气，共创美好生活。\n\n岗位职责\n1.负责大众点评打卡发布工具的产品规划与建设，围绕用户到店后的记录场景，持续优化从触发、拍摄/选图、内容编辑、地点关联到发布完成的完整链路；\n2.深入理解用户在餐饮、休闲娱乐、丽人、亲子、旅游等不同场景下的记录需求，持续降低打卡内容生产门槛，提升用户发布意愿、发布效率及内容质量；\n3.负责发布工具核心能力建设，包括但不限于：图片拍摄及编辑能力，文案内容表达能力，智能推荐与创作辅助能力，活动、权益、商家任务等场景化发布能力；\n4.结合AI、多模态等新技术，探索智能选图、文案辅助、内容理解、场景识别等能力，提升用户创作体验及内容生产效率；\n5.建立发布链路核心指标体系，围绕发布转化率、带图率、内容完整度、用户留存及打卡频次等指标持续开展实验、分析和产品迭代。\n6.与设计、研发、算法、数据、运营及商家产品等团队紧密协作，推动复杂项目落地，并持续复盘产品效果。\n\n岗位基本要求\n1.3年以上互联网产品经理经验，有内容创作、UGC社区、发布工具、相机/图片视频编辑、生活服务等相关产品经验优先；\n2.对用户创作行为和内容生产链路有较强理解，能够准确识别影响用户发布意愿和效率的关键问题；\n3.具备较强的数据分析和实验意识，能够通过数据拆解问题、形成假设并推动产品验证；\n4.具备较好的交互和产品体验判断能力，对产品细节敏感，能够持续打磨复杂发布链路；\n5.具备良好的项目推动和跨团队协作能力，能够协调设计、研发、算法、运营等多角色完成项目落地；\n6.具备AI工具使用意识和实践经验（如ChatGPT/Claude/Copilot等），能主动将AI能力融入日常工作流。\n\n具备以下条件优先\n1.有内容型产品、生活记录/社区/本地生活等相关产品运营经验\n2.对用户记录、分享的底层动机有较强洞察能力，能转化为具体运营策略\n\n岗位亮点\n1.打卡产品是点评事业部最重要的项目之一，有充足的资源配备。\n2.拥有较大的创新空间，可以主导设计全新的用户玩法、活动机制和增长策略。\n3.从0到1参与打卡产品成长，深度参与产品定位、运营体系及增长模式建设。\n4.团队积极拥抱AI，鼓励用AI工具提效和创新，有丰富的AI落地场景和实践机会。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4766975053","sourceKey":"meituan_social","company":"美团","title":"高级测试开发工程师","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4766975053&jobShareType=1","duty":"1. 负责小象超市相关系统的质量保障工作，保障系统稳定性和用户体验。\n2. 开发并维护测试工具和平台，推动测试流程标准化、平台化，提升团队测试质效。\n3. 协助开发团队定位并跟踪缺陷，推动问题闭环解决，并建立质量复盘与问题预防机制，持续提升系统稳定性。\n4. 关注行业前沿技术与 AI 技术发展趋势，探索并落地 AI 在测试领域的应用，提升测试智能化水平。","requirements":"1. 大学本科及以上学历，计算机或相关专业背景。\n2. 具备1-3年软件测试或测试开发经验，熟悉测试理论与流程，使用常用测试工具，熟练操作数据库，了解互联网相关协议，熟悉常见互联网架构。\n3. 熟练掌握至少一种编程语言，如Python、Java等，具备自动化测试开发能力。\n4. 了解大模型、Agent相关理论和实践，有大模型在测试领域的应用经验。\n5. 有良好的逻辑分析能力和沟通能力，快速学习能力，对新技术有好奇心，有责任感主动性强，良好的团队合作精神，能适应一定压力的工作。","description":"部门介绍\n美团的使命是“帮大家吃得更好，生活更好”，公司聚焦“零售 + 科技”战略，和广大商户与各类合作伙伴一起，努力为消费者提供品质生活，推动商品零售和服务零售在需求侧和供给侧的数字化转型。\n2018年9月20日，美团正式在港交所挂牌上市。美团将始终坚持以客户为中心，不断加大在科技研发方面的投入，更好承担社会责任，更多创造社会价值，与广大合作伙伴一起发展共赢。\n\n岗位职责\n1. 负责小象超市相关系统的质量保障工作，保障系统稳定性和用户体验。\n2. 开发并维护测试工具和平台，推动测试流程标准化、平台化，提升团队测试质效。\n3. 协助开发团队定位并跟踪缺陷，推动问题闭环解决，并建立质量复盘与问题预防机制，持续提升系统稳定性。\n4. 关注行业前沿技术与 AI 技术发展趋势，探索并落地 AI 在测试领域的应用，提升测试智能化水平。\n\n岗位基本要求\n1. 大学本科及以上学历，计算机或相关专业背景。\n2. 具备1-3年软件测试或测试开发经验，熟悉测试理论与流程，使用常用测试工具，熟练操作数据库，了解互联网相关协议，熟悉常见互联网架构。\n3. 熟练掌握至少一种编程语言，如Python、Java等，具备自动化测试开发能力。\n4. 了解大模型、Agent相关理论和实践，有大模型在测试领域的应用经验。\n5. 有良好的逻辑分析能力和沟通能力，快速学习能力，对新技术有好奇心，有责任感主动性强，良好的团队合作精神，能适应一定压力的工作。\n\n具备以下条件优先\n有电商零售行业、供应链相关业务QA经验优先；\n有AI相关应用落地经验者优先。\n\n岗位亮点\n1. 有机会全身心地参与新零售业态，体验并掌握供应链、仓配、销售、履约等各个环节的核心技术要素，与团队共同推动新零售业务智能化升级与重构。\n2. 团队技术实力雄厚，技术氛围开放，鼓励探索大模型、AI Agent、AI Coding 等前沿方向，支持技术创新与流程优化，能够在真实业务场景中快速积累 AI 工程化与落地经验，加速个人成长。\n3. 提供完善的培训体系与职业发展通道，帮助员工持续提升 AI 与业务双栈能力。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4242519838","sourceKey":"meituan_social","company":"美团","title":"用增产品leader-互动方向","city":"上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4242519838&jobShareType=1","duty":"1、基于大模型用户行为预测能力，负责点评互动用户的全生命周期管理，包括策略方案设计、功能规划、上线落地及效果复盘。通过AI驱动的用户分层与行为价值分析，对用户规模渗透、质量与关键行为价值负责，持续优化用户结构与互动生态健康度；\n2、结合业务场景、用户结构与产品核心特性，利用AI算法和大模型能力，定制差异化的数值策略。通过AI自动化调优成长值获取与消耗规则，动态匹配不同用户群体的成长路径，提升关键行为转化效率和用户生命周期价值（LTV）；\n3、关注用户生命周期价值和增长成本投入，能结合不同业务场景和用户行为价值制定合理有效策略方案，保持互动生态健康度和可持续性；\n4、深度协同产品、策略算法、推荐等团队，将互动数值策略与算法模型优化有机结合；探索基于强化学习、因果推断等AI技术的策略自动化能力，持续提升获客钱效与获客质量，推动增长飞轮高效运转。","requirements":"1、本科及以上学历，5年以上增长策略产品经验，数学、统计学、计算机专业等相关专业优先，有大型增长策略经验优先；\n2、具备敏锐的数据洞察力，深入理解转化漏斗、用户画像构成及用户分层等策略经验，有使用大模型进行用户分层预测或智能策略自动生成的实际经验，能将AI预测结果转化为可落地的数值策略方案；\n3、逻辑思维缜密，具备优秀的目标拆解能力与判断能力，可高质量完成复杂项目的统筹推进；\n4、目标导向，有良好的跨部门沟通和整合资源能力，对业务有自己的理解和思考。","description":"部门介绍\n大众点评作为国内重要的本地生活消费决策参考平台，多年来深耕本地生活消费领域，深受广大用户的信任和喜爱。我们的业务覆盖了吃喝玩乐游购娱等生活场景，通过极具辨识度和公信力的”星级“和”评价“产品，为数亿用户提供了全面、可信的消费决策依据。为更好满足用户探索城市的需求，大众点评在原有星级和评价的基础上，以信息流产品形式，助力用户发现更多好去处。大量优秀年轻同学的加入，为我们的团队注入了澎湃活力。我们相信，真实的生活是不可替代的，真实的感受是值得记录的，真实的美好是要被看到的。希望优秀的你能和我们一起，帮助广大用户在大众点评上发现更多好去处，找到属于自己的人间烟火气，共创美好生活。\n\n岗位职责\n1、基于大模型用户行为预测能力，负责点评互动用户的全生命周期管理，包括策略方案设计、功能规划、上线落地及效果复盘。通过AI驱动的用户分层与行为价值分析，对用户规模渗透、质量与关键行为价值负责，持续优化用户结构与互动生态健康度；\n2、结合业务场景、用户结构与产品核心特性，利用AI算法和大模型能力，定制差异化的数值策略。通过AI自动化调优成长值获取与消耗规则，动态匹配不同用户群体的成长路径，提升关键行为转化效率和用户生命周期价值（LTV）；\n3、关注用户生命周期价值和增长成本投入，能结合不同业务场景和用户行为价值制定合理有效策略方案，保持互动生态健康度和可持续性；\n4、深度协同产品、策略算法、推荐等团队，将互动数值策略与算法模型优化有机结合；探索基于强化学习、因果推断等AI技术的策略自动化能力，持续提升获客钱效与获客质量，推动增长飞轮高效运转。\n\n岗位基本要求\n1、本科及以上学历，5年以上增长策略产品经验，数学、统计学、计算机专业等相关专业优先，有大型增长策略经验优先；\n2、具备敏锐的数据洞察力，深入理解转化漏斗、用户画像构成及用户分层等策略经验，有使用大模型进行用户分层预测或智能策略自动生成的实际经验，能将AI预测结果转化为可落地的数值策略方案；\n3、逻辑思维缜密，具备优秀的目标拆解能力与判断能力，可高质量完成复杂项目的统筹推进；\n4、目标导向，有良好的跨部门沟通和整合资源能力，对业务有自己的理解和思考。\n\n岗位亮点\n1、从0到1主导核心项目落地，快速积累完整的增长策略方法论与AI产品化经验。\n2、团队氛围好，与一群有爱，有梦想的小伙伴一起共事，综合学习，共同进步。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4775166968","sourceKey":"meituan_social","company":"美团","title":"小象超市-用户与活动运营","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4775166968&jobShareType=1","duty":"1.付费流量投放：负责点金推广、铂金展位等CPC产品的投放策略与日常操盘——分城市/分厨房/分时段的预算分配、关键词出价、定向策略，对投放ROI和单均获客成本负责；\n2.搜索与排序优化：优化影响自然流量的权重项——搜索关键词覆盖（菜名、品类词、场景词）、营业时长管理、出餐速度与接单率维护、活动配置率等，持续提升店铺在搜索和推荐场景的排名；\n3.站内外活动资源运营：负责平台活动的报名与承接，以及站外引流素材配合，确保活动资源位的收益最大化；\n4.营销活动与复购设计：设计满减/折扣/代金券/配送费补贴等店内营销结构，配置回购券、老客召回券、会员权益，拉升复购率与下单频次；\n5.用户分层运营：基于新客/老客、高频/低频用户分层，设计差异化的触达与权益策略，管理用户生命周期价值；\n6.数据复盘与迭代：建立投放与活动的数据复盘机制（曝光→进店→下单→复购全链路），持续迭代投放与活动策略。","requirements":"1.本科及以上学历，3年以上外卖/电商流量运营或用户增长经验，有付费投放操盘经验（CPC/OCPM）；\n2.熟悉美团外卖流量分发逻辑与排序权重项，有点金/展位投放实操案例，能清晰讲出ROI优化路径；\n3.具备用户运营方法论（分层、生命周期、权益设计），有复购率/频次提升的案例；\n4.数据能力强，熟练使用数据分析工具，能独立完成投放归因与活动复盘；\n5.有连锁品牌多门店投放经验优先，会用AI工具辅助投放策略与素材生成加分；\n6.自驱力强，结果导向，适应快节奏放量期。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1.付费流量投放：负责点金推广、铂金展位等CPC产品的投放策略与日常操盘——分城市/分厨房/分时段的预算分配、关键词出价、定向策略，对投放ROI和单均获客成本负责；\n2.搜索与排序优化：优化影响自然流量的权重项——搜索关键词覆盖（菜名、品类词、场景词）、营业时长管理、出餐速度与接单率维护、活动配置率等，持续提升店铺在搜索和推荐场景的排名；\n3.站内外活动资源运营：负责平台活动的报名与承接，以及站外引流素材配合，确保活动资源位的收益最大化；\n4.营销活动与复购设计：设计满减/折扣/代金券/配送费补贴等店内营销结构，配置回购券、老客召回券、会员权益，拉升复购率与下单频次；\n5.用户分层运营：基于新客/老客、高频/低频用户分层，设计差异化的触达与权益策略，管理用户生命周期价值；\n6.数据复盘与迭代：建立投放与活动的数据复盘机制（曝光→进店→下单→复购全链路），持续迭代投放与活动策略。\n\n岗位基本要求\n1.本科及以上学历，3年以上外卖/电商流量运营或用户增长经验，有付费投放操盘经验（CPC/OCPM）；\n2.熟悉美团外卖流量分发逻辑与排序权重项，有点金/展位投放实操案例，能清晰讲出ROI优化路径；\n3.具备用户运营方法论（分层、生命周期、权益设计），有复购率/频次提升的案例；\n4.数据能力强，熟练使用数据分析工具，能独立完成投放归因与活动复盘；\n5.有连锁品牌多门店投放经验优先，会用AI工具辅助投放策略与素材生成加分；\n6.自驱力强，结果导向，适应快节奏放量期。\n\n岗位亮点\n探索零售行业最前沿业务的第二增长曲线，在解决业务问题的同时，可以充分提升思考深度、认知高度。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4775200508","sourceKey":"meituan_social","company":"美团","title":"小象超市-外卖店铺与商品运营","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4775200508&jobShareType=1","duty":"1.店铺装修与运营管理：负责外卖店铺的头图、海报、品牌页装修，确保品牌调性在外卖渠道端一致呈现，并持续迭代AB测试优化点击率；\n2.菜单结构与排序优化：基于品类规划的300-400个SKU货盘，设计菜单分类逻辑（档口维度vs场景维度vs品类维度）、排序策略、置顶推荐位管理，平衡爆品引流与高毛利品动销；\n3.商品详情页优化：负责菜品图片、名称、卖点文案、规格设置（份量/餐盒费/起送价联动）、套餐组合呈现，持续优化商品点击与转化；\n4.爆品打造：协同品类规划和用户与活动运营，从货盘中选品打造渠道爆品，负责爆品的页面呈现、卖点包装、上架节奏与推广承接；\n5.评分星级维护：建立评分监控与差评处理机制——差评归类分析（口味/包装/配送/服务）、复购引导好评，维护店铺星级在目标水位以上；\n6.批量运营落地：将上述动作模板化、SOP化，支撑多厨房批量复制，借助AI工具实现文案批量生成与装修批量管理。","requirements":"1.本科及以上学历，3年以上外卖店铺运营/商品运营经验，有餐饮或新零售连锁品牌经验优先；\n2.熟悉美团外卖店铺运营全链路（装修、菜单、商品、评分规则），有点击率/转化率优化实操案例；\n3.对数据敏感，能基于漏斗数据诊断店铺问题（是进店少还是下单少）并给出优化方案；\n4.有爆品打造或菜品页面优化的成功案例；\n5.细致、执行力强，能适应多店并行的批量运营工作方式；\n6.会用AI工具提效（文案生成、图片处理）加分。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1.店铺装修与运营管理：负责外卖店铺的头图、海报、品牌页装修，确保品牌调性在外卖渠道端一致呈现，并持续迭代AB测试优化点击率；\n2.菜单结构与排序优化：基于品类规划的300-400个SKU货盘，设计菜单分类逻辑（档口维度vs场景维度vs品类维度）、排序策略、置顶推荐位管理，平衡爆品引流与高毛利品动销；\n3.商品详情页优化：负责菜品图片、名称、卖点文案、规格设置（份量/餐盒费/起送价联动）、套餐组合呈现，持续优化商品点击与转化；\n4.爆品打造：协同品类规划和用户与活动运营，从货盘中选品打造渠道爆品，负责爆品的页面呈现、卖点包装、上架节奏与推广承接；\n5.评分星级维护：建立评分监控与差评处理机制——差评归类分析（口味/包装/配送/服务）、复购引导好评，维护店铺星级在目标水位以上；\n6.批量运营落地：将上述动作模板化、SOP化，支撑多厨房批量复制，借助AI工具实现文案批量生成与装修批量管理。\n\n岗位基本要求\n1.本科及以上学历，3年以上外卖店铺运营/商品运营经验，有餐饮或新零售连锁品牌经验优先；\n2.熟悉美团外卖店铺运营全链路（装修、菜单、商品、评分规则），有点击率/转化率优化实操案例；\n3.对数据敏感，能基于漏斗数据诊断店铺问题（是进店少还是下单少）并给出优化方案；\n4.有爆品打造或菜品页面优化的成功案例；\n5.细致、执行力强，能适应多店并行的批量运营工作方式；\n6.会用AI工具提效（文案生成、图片处理）加分。\n\n岗位亮点\n探索零售行业最前沿业务的第二增长曲线，在解决业务问题的同时，可以充分提升思考深度、认知高度。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4775835930","sourceKey":"meituan_social","company":"美团","title":"小象超市-物流城市用工负责人（广州）","city":"广州市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4775835930&jobShareType=1","duty":"1、负责城市招聘目标与需求的达成，并制定对应招聘方向与策略；\n2、深入了解用人部门发展规划与需求，评估需求并提出配置建议； \n3、负责城市招聘团队人员管理，提升城市招聘团队专业能力与效能；\n4、招聘渠道管理与建设，包括渠道的拓展维护，招聘费用管控； \n5、定期与业务部门进行沟通与协作，为招聘提供解决方案；\n6、掌握基本的AI工具，使用工具提升工作流程效率。","requirements":"1、本科以上学历，人力资源管理、心理学专业优先；\n2、5年以上大型企业人力资源招聘工作经验，并能对招聘结果负责；团队管理经验至少1年以上；\n3、有一定的招聘渠道拓展搭建经验及资源；\n4、有互联网、快消零售连锁、物流等大型企业招聘经验优先；\n5、具有优秀的学习能力、主动和开创精神、优秀的文字能力、出色的沟通协调能力；\n6、对AI工具研究和使用经验。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1、负责城市招聘目标与需求的达成，并制定对应招聘方向与策略；\n2、深入了解用人部门发展规划与需求，评估需求并提出配置建议； \n3、负责城市招聘团队人员管理，提升城市招聘团队专业能力与效能；\n4、招聘渠道管理与建设，包括渠道的拓展维护，招聘费用管控； \n5、定期与业务部门进行沟通与协作，为招聘提供解决方案；\n6、掌握基本的AI工具，使用工具提升工作流程效率。\n\n岗位基本要求\n1、本科以上学历，人力资源管理、心理学专业优先；\n2、5年以上大型企业人力资源招聘工作经验，并能对招聘结果负责；团队管理经验至少1年以上；\n3、有一定的招聘渠道拓展搭建经验及资源；\n4、有互联网、快消零售连锁、物流等大型企业招聘经验优先；\n5、具有优秀的学习能力、主动和开创精神、优秀的文字能力、出色的沟通协调能力；\n6、对AI工具研究和使用经验。\n\n岗位亮点\n策略落地、全面锻炼自身、从招聘到留存全面参与管理、聚焦单城市成长速度快，前沿AI工具学习与使用。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4474504563","sourceKey":"meituan_social","company":"美团","title":"User operation expert","city":"圣保罗","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4474504563&jobShareType=1","duty":"Responsible for the development and execution of new user strategy in Brazil, understanding user growth logic, and building a sustainable user growth system\n1. Deeply understand emerging traffic and new approaches, explore effective new user acquisition channels and strategies with continuous optimization to reach target users; Design and optimize end-to-end growth funnels: from new user registration → first order completion → early habit formation.\n2. Manage new user incentive programs and subsidy plans (coupons, referral campaigns, first-order promos), balancing growth efficiency and ROI., and fine-tuning the cost of acquiring customers (CAC) and the lifetime value (LTV) of users.\n3. Plan and manage both online and offline user acquisition campaigns (such as TikTok, field promotion)\n4. Analyze user behavior data to understand user needs and behaviors, providing user data analysis dashboard to keep track of key metrics and identify user growth opportunities, formulating corresponding user growth plans, and run A/B tests on growth initiatives.\n5. Collaborate with the merchant, product, and others teams to align resources and promote project implementation.\n6. Localize growth strategies for the Brazilian market, incorporating knowledge of local consumer behavior, culture, and competitive landscape.","requirements":"1. At least 5 years of experience in internet user operation strategy in Brazil, preferably with a background in major platforms (like e-commerce, O2O, two-sided markets).\n2. Well-versed in growth hacking techniques, with hands-on experience in new customer growth, traffic channel operations, and subsidy plans.\n3. Proficient in data analysis tools and able to perform attribution analysis using data.\n4. Highly attuned to user psychology, skilled at motivating behavior change through incentive design.\n5. Goal-oriented, with a proven track record of overcoming growth bottlenecks from scratch.","description":"部门介绍\nKeeta是全球领先外卖平台美团旗下的独立品牌，肩负着“帮大家吃得更好，生活更好”的使命。依托美团深耕中国市场15年的技术与运营积淀，我们正引领全球餐饮与商品即时配送服务的创新与发展。\n\n自2023年成立以来，Keeta始终扎根社区并创造价值。我们为用户提供可靠的外卖体验，以智慧技术助餐厅提升经营效率，在为骑手拓宽收入来源的同时，也充分提供安全保障措施。基于这份多方共赢、共同成长的理念，我们的业务已从中国香港稳步拓展至中东及巴西，并持续向世界迈进。\n\n岗位职责\nResponsible for the development and execution of new user strategy in Brazil, understanding user growth logic, and building a sustainable user growth system\n1. Deeply understand emerging traffic and new approaches, explore effective new user acquisition channels and strategies with continuous optimization to reach target users; Design and optimize end-to-end growth funnels: from new user registration → first order completion → early habit formation.\n2. Manage new user incentive programs and subsidy plans (coupons, referral campaigns, first-order promos), balancing growth efficiency and ROI., and fine-tuning the cost of acquiring customers (CAC) and the lifetime value (LTV) of users.\n3. Plan and manage both online and offline user acquisition campaigns (such as TikTok, field promotion)\n4. Analyze user behavior data to understand user needs and behaviors, providing user data analysis dashboard to keep track of key metrics and identify user growth opportunities, formulating corresponding user growth plans, and run A/B tests on growth initiatives.\n5. Collaborate with the merchant, product, and others teams to align resources and promote project implementation.\n6. Localize growth strategies for the Brazilian market, incorporating knowledge of local consumer behavior, culture, and competitive landscape.\n\n岗位基本要求\n1. At least 5 years of experience in internet user operation strategy in Brazil, preferably with a background in major platforms (like e-commerce, O2O, two-sided markets).\n2. Well-versed in growth hacking techniques, with hands-on experience in new customer growth, traffic channel operations, and subsidy plans.\n3. Proficient in data analysis tools and able to perform attribution analysis using data.\n4. Highly attuned to user psychology, skilled at motivating behavior change through incentive design.\n5. Goal-oriented, with a proven track record of overcoming growth bottlenecks from scratch.\n\n岗位亮点\nBe a founding team member in a high-growth market with massive upside.\nDirect impact on business outcomes — your work shapes Keeta Brazil's growth trajectory.\nAccelerated career development in a global, multi-cultural team.","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4763504561","sourceKey":"meituan_social","company":"美团","title":"GUI Agent 技术专家（浏览器/桌面端方向）","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4763504561&jobShareType=1","duty":"负责 GUI Agent 的架构设计与规模化落地，覆盖感知、规划、执行、反馈和异常恢复。\n\n构建基于浏览器与桌面应用的智能操作能力，结合视觉理解、DOM、工具调用和任务编排完成复杂流程。\n\n优化 Agent 在动态页面、弹窗、多窗口、长流程及复杂运行环境下的稳定性。\n\n建设多账号、多任务、多终端场景下的调度、隔离、监控、评测和人工接管体系。\n\n研究平台安全策略、异常行为识别及复杂对抗环境下的稳健性问题，完善限流、风控、权限和审计机制。","requirements":"具备 GUI Agent、LLM Agent、浏览器自动化或 RPA 产品的生产落地经验。\n\n熟悉 TypeScript/Python/Java、Electron、Playwright/Puppeteer，以及 CDP、Chrome Profile、DOM 事件等浏览器机制。\n\n有多账号、多任务、多终端或大规模客户端的规模化实践经验。\n\n对平台安全、异常行为识别、风险治理及复杂环境下的系统稳健性有实践经验。\n\n具备良好的工程与沟通能力，能够围绕成功率、稳定性、性能和风险指标持续优化系统。","description":"部门介绍\n美团核心本地商业下业务研发平台，基于公司“零售+科技”的战略导向，通过从底层架构到应用系统、从软件到硬件、从传统算法到GenAI的全方位技术研究，以及开发、运维、安全等全流程能力建设，致力于推动美团核心本地商业下需求侧与供给侧的数字化和智能化升级，助力业务实现高质量增长，优化用户使用体验，提升商户经营水平，促进行业生态伙伴关系的持续健康发展。团队秉持务实、自驱、开放以及追求卓越的工程师文化，一方面通过系统和技术体系的持续迭代升级，帮助业务高质量增长；另一方面，密切关注前沿技术趋势变化，积极创新技术能力，为业务未来发展创造新的可能性。期待优秀的你加入我们，在夯实专业、深耕平台的基础上与业务携手同行，一起用技术 “帮大家吃得更好，生活更好”。\n\n岗位职责\n负责 GUI Agent 的架构设计与规模化落地，覆盖感知、规划、执行、反馈和异常恢复。\n\n构建基于浏览器与桌面应用的智能操作能力，结合视觉理解、DOM、工具调用和任务编排完成复杂流程。\n\n优化 Agent 在动态页面、弹窗、多窗口、长流程及复杂运行环境下的稳定性。\n\n建设多账号、多任务、多终端场景下的调度、隔离、监控、评测和人工接管体系。\n\n研究平台安全策略、异常行为识别及复杂对抗环境下的稳健性问题，完善限流、风控、权限和审计机制。\n\n岗位基本要求\n具备 GUI Agent、LLM Agent、浏览器自动化或 RPA 产品的生产落地经验。\n\n熟悉 TypeScript/Python/Java、Electron、Playwright/Puppeteer，以及 CDP、Chrome Profile、DOM 事件等浏览器机制。\n\n有多账号、多任务、多终端或大规模客户端的规模化实践经验。\n\n对平台安全、异常行为识别、风险治理及复杂环境下的系统稳健性有实践经验。\n\n具备良好的工程与沟通能力，能够围绕成功率、稳定性、性能和风险指标持续优化系统。\n\n具备以下条件优先\n有多模态模型、视觉定位、OCR、轨迹理解或桌面操作经验。\n\n有 Agent 评测集、轨迹回放和自动化评测平台建设经验。\n\n有反滥用、账号安全、风险治理或复杂环境攻防经验。\n\n有招聘、客服、销售等企业效率工具经验。\n\n岗位亮点\n美团AI核心重点项目，创新型组织，负责核心Agent harness构建，AI native组织。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4776463144","sourceKey":"meituan_social","company":"美团","title":"医美咨询师","city":"上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4776463144&jobShareType=1","duty":"1. 理解医美用户需求，医美用户进行一对一咨询和沟通，理解用户的变美诉求、预算、项目经历、顾虑及决策因素。通过用户表达和行为，判断其真实需求、决策阶段和潜在机会。\n2. 熟悉主流医美项目、产品、品牌及适用人群，能够根据用户实际情况提供专业、客观的项目建议，拿到销售结果。\n3. 围绕术前、到店、术后恢复、效果反馈、疗程管理等做好用户陪伴。促进合理转化与复购，关注长期用户价值，持续挖掘同项目复购及跨项目需求，而非追求一次性成交。\n4. 持续总结用户常见问题、决策障碍、转化节点及服务经验，将一线用户洞察反馈给运营团队，共同优化用户服务体验。","requirements":"1、3年以上医美行业一线咨询经验优先，有丰富真实用户服务经验；\n2、有医美平台咨询经验者优先，优秀医美机构咨询师亦可；\n3、熟悉主流医美项目，包括但不限于光电、水光等；用户感知力强，能够快速理解用户真正关心的问题，对用户情绪、意愿和需求变化敏感；","description":"部门介绍\n美团医药健康事业部是美团核心本地商业板块下专注健康领域的业务部门，涵盖美团买药、美团医美和美团医疗三大业务。自创立以来，美团医药健康致力于为用户提供全健康周期产品及服务，满足人民群众多层次多元化医疗健康需求，现已覆盖购药到家、居家检测、问诊挂号、医保支付、求医寻院、医疗美容等核心场景。此外，美团医药健康还为商户提供数字化转型创新解决方案，打造贯穿上游的联动机制，长期参与共建更透明、更可持续的医药健康产业生态圈，目前业务已覆盖25万家药店，收录27万家医疗机构。未来，美团医药康将协同更多行业伙伴，帮助大家变得更健康、更美丽、更养生。\n\n岗位职责\n1. 理解医美用户需求，医美用户进行一对一咨询和沟通，理解用户的变美诉求、预算、项目经历、顾虑及决策因素。通过用户表达和行为，判断其真实需求、决策阶段和潜在机会。\n2. 熟悉主流医美项目、产品、品牌及适用人群，能够根据用户实际情况提供专业、客观的项目建议，拿到销售结果。\n3. 围绕术前、到店、术后恢复、效果反馈、疗程管理等做好用户陪伴。促进合理转化与复购，关注长期用户价值，持续挖掘同项目复购及跨项目需求，而非追求一次性成交。\n4. 持续总结用户常见问题、决策障碍、转化节点及服务经验，将一线用户洞察反馈给运营团队，共同优化用户服务体验。\n\n岗位基本要求\n1、3年以上医美行业一线咨询经验优先，有丰富真实用户服务经验；\n2、有医美平台咨询经验者优先，优秀医美机构咨询师亦可；\n3、熟悉主流医美项目，包括但不限于光电、水光等；用户感知力强，能够快速理解用户真正关心的问题，对用户情绪、意愿和需求变化敏感；\n\n具备以下条件优先\n• 有高净值医美用户、长期老客运营或私域用户运营经验；\n• 有用户访谈、用户需求分析或一线经验沉淀能力；\n• 对AI咨询、智能客服、AI+医美等新型服务模式感兴趣。\n\n岗位亮点\n参与美团医美创新项目孵化和实践，团队氛围好。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3987991080","sourceKey":"meituan_social","company":"美团","title":"销量预测专家","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3987991080&jobShareType=1","duty":"1、销量预测：负责城市、多品类长短周期的销量预测工作。需综合历史销售数据、运营策略、区域特色及市场竞争态势，主动运用AI/ML预测工具（如时序模型、梯度提升、神经网络等），输出精准预测结果，为订货、库存调配及人力资源安排提供核心数据支持；\n2、闭环与优化：持续监控并分析预测准确率，借助AI手段自动识别偏差根因，快速推动整改措施落地。通过预测模型的持续迭代和AI驱动的自动化闭环机制，不断提升预测精准度，并对核心预测指标负责；\n3、数据体系与归因分析：构建和完善覆盖城市、仓等多维度的预测监控与数据分析体系。能独立运用AI工具对业务运营结果进行深度下钻归因分析，沉淀有效策略，并主导推进预测流程或工具的产品化、自动化，提升整体效率；\n4、业务协同：深度融入运营模式，理解商品运营策略、促销规划及库存管理逻辑。通过AI赋能的精准预测，有效协同采购、供应链及运营团队，优化库存水平，保障商品充足供给（尤其是爆款与新品），降低滞销风险，提升库存周转效率，助力用户体验与经营效率双提升。","requirements":"1、经验背景：3年及以上大型零售企业（商超、便利店、品牌连锁等）供应链计划或需求预测相关经验；熟悉线下零售业务运作流程和关键指标者优先；有AI/ML预测项目落地经验者优先；\n2、数据与AI能力：具备扎实的数据统计和分析能力，能熟练使用数据分析工具进行数据提取、清洗和分析；熟悉常用预测模型及其应用场景；能独立使用或评估AI/ML工具（如Python、时序模型、AutoML等），有自动化预测体系搭建经验者加分；\n3、业务与逻辑思维：具备严谨的逻辑分析和系统性思维能力，对线下零售业务有高度敏感度；能洞察内外部因素对销量的潜在影响；能将业务洞察转化为AI模型输入，推动预测结果持续迭代；\n4、沟通与推动力：具备出色的跨部门沟通协调能力，能主动协同采购、运营、供应链等团队推动预测落地；具备AI工具推广和赋能团队的意愿与能力，有强烈责任心和自驱力。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1、销量预测：负责城市、多品类长短周期的销量预测工作。需综合历史销售数据、运营策略、区域特色及市场竞争态势，主动运用AI/ML预测工具（如时序模型、梯度提升、神经网络等），输出精准预测结果，为订货、库存调配及人力资源安排提供核心数据支持；\n2、闭环与优化：持续监控并分析预测准确率，借助AI手段自动识别偏差根因，快速推动整改措施落地。通过预测模型的持续迭代和AI驱动的自动化闭环机制，不断提升预测精准度，并对核心预测指标负责；\n3、数据体系与归因分析：构建和完善覆盖城市、仓等多维度的预测监控与数据分析体系。能独立运用AI工具对业务运营结果进行深度下钻归因分析，沉淀有效策略，并主导推进预测流程或工具的产品化、自动化，提升整体效率；\n4、业务协同：深度融入运营模式，理解商品运营策略、促销规划及库存管理逻辑。通过AI赋能的精准预测，有效协同采购、供应链及运营团队，优化库存水平，保障商品充足供给（尤其是爆款与新品），降低滞销风险，提升库存周转效率，助力用户体验与经营效率双提升。\n\n岗位基本要求\n1、经验背景：3年及以上大型零售企业（商超、便利店、品牌连锁等）供应链计划或需求预测相关经验；熟悉线下零售业务运作流程和关键指标者优先；有AI/ML预测项目落地经验者优先；\n2、数据与AI能力：具备扎实的数据统计和分析能力，能熟练使用数据分析工具进行数据提取、清洗和分析；熟悉常用预测模型及其应用场景；能独立使用或评估AI/ML工具（如Python、时序模型、AutoML等），有自动化预测体系搭建经验者加分；\n3、业务与逻辑思维：具备严谨的逻辑分析和系统性思维能力，对线下零售业务有高度敏感度；能洞察内外部因素对销量的潜在影响；能将业务洞察转化为AI模型输入，推动预测结果持续迭代；\n4、沟通与推动力：具备出色的跨部门沟通协调能力，能主动协同采购、运营、供应链等团队推动预测落地；具备AI工具推广和赋能团队的意愿与能力，有强烈责任心和自驱力。\n\n具备以下条件优先\n可以熟练使用sql等技能优先\n\n岗位亮点\n1、深入核心业务，全面掌握新零售背景下的运作逻辑与挑战，直接参与AI预测体系的从0到1搭建；\n2、在真实复杂业务场景中，以AI工具为杠杆，锤炼兼具广度和深度的供应链计划与预测能力；\n3、与多元背景的专业团队协作，共同推动零售行业的AI化、智能化升级，站在行业变革前沿。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4522007160","sourceKey":"meituan_social","company":"美团","title":"商品产品经理（非餐品类）","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4522007160&jobShareType=1","duty":"1、负责新业务线（非餐品类）的商家端产品规划、方案设计及交付落地。 \n\n2、围绕核心交易链路和商家经营，构建门店运营、订单管理、售后服务等核心能力，提升商家运营效率。 \n\n3、基于对商家经营链路的深度理解，识别关键问题和机会，持续迭代完善商家端产品能力。 \n\n4、探索并推进商家Agent的能力建设，使用AI赋能商家经营管理，降低商家运营门槛。 \n\n5、能够使用AI工具辅助需求撰写和产品功能交付，提升业产研的协同效率。","requirements":"【必要条件】 \n\n1、5年以上商家端产品经验，对商品有一定理解，对商家经营有深入认知。\n\n2、英语口语好，能够和商家进行调研访谈，能接受高频出差。\n\n3、有使用AI工具的工作实践，有主动探索AI的学习意愿。 \n\n4、有扎实的逻辑思维和结构化表达能力。 \n\n【我们最看重的特质】 \n\n1、能从商家的经营者视角出发理解业务痛点\n\n2、愿意深入一线\n\n3、自驱","description":"部门介绍\nKeeta是全球领先外卖平台美团旗下的独立品牌，肩负着“帮大家吃得更好，生活更好”的使命。依托美团深耕中国市场15年的技术与运营积淀，我们正引领全球餐饮与商品即时配送服务的创新与发展。\n\n自2023年成立以来，Keeta始终扎根社区并创造价值。我们为用户提供可靠的外卖体验，以智慧技术助餐厅提升经营效率，在为骑手拓宽收入来源的同时，也充分提供安全保障措施。基于这份多方共赢、共同成长的理念，我们的业务已从中国香港稳步拓展至中东及巴西，并持续向世界迈进。\n\n岗位职责\n1、负责新业务线（非餐品类）的商家端产品规划、方案设计及交付落地。 \n\n2、围绕核心交易链路和商家经营，构建门店运营、订单管理、售后服务等核心能力，提升商家运营效率。 \n\n3、基于对商家经营链路的深度理解，识别关键问题和机会，持续迭代完善商家端产品能力。 \n\n4、探索并推进商家Agent的能力建设，使用AI赋能商家经营管理，降低商家运营门槛。 \n\n5、能够使用AI工具辅助需求撰写和产品功能交付，提升业产研的协同效率。\n\n岗位基本要求\n【必要条件】 \n\n1、5年以上商家端产品经验，对商品有一定理解，对商家经营有深入认知。\n\n2、英语口语好，能够和商家进行调研访谈，能接受高频出差。\n\n3、有使用AI工具的工作实践，有主动探索AI的学习意愿。 \n\n4、有扎实的逻辑思维和结构化表达能力。 \n\n【我们最看重的特质】 \n\n1、能从商家的经营者视角出发理解业务痛点\n\n2、愿意深入一线\n\n3、自驱\n\n具备以下条件优先\n1、有零售/电商/本地生活领域的商家产品经验。 \n\n2、对AI工具有深度使用经验，有AI交付产品功能的实践案例。\n\n3、有海外生活经历，了解海外消费习惯和文化背景。\n\n岗位亮点\n1、负责非餐品类商家产品的0到1建设，直接参与产品全链路设计，发挥空间大。 \n\n2、业务发展快，非餐品类在海外市场增长迅速，跟随业务发展的成长天花板高。 \n\n3、我们鼓励用AI工具替代重复劳动，一起实践AI-Native的新工作范式，致力于成为超级个体。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4786837534","sourceKey":"meituan_social","company":"美团","title":"快乐猴-成本经理","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4786837534&jobShareType=1","duty":"1. 负责门店工程营建项目的成本预算编制、审核及动态管控，确保项目成本在合理范围内。  \n2. 参与供应商比选、合同谈判及成本优化方案制定，提升项目成本效益。  \n3. 跟踪项目执行过程中的成本变化，及时预警并推动问题解决。  \n4. 建立并完善成本管理体系，输出成本分析报告，支持经营决策。","requirements":"1. 大学本科及以上学历，工程管理、工程造价、土木工程等相关专业优先。  \n2. 具备3年以上工程营建或零售门店发展相关成本管理经验。  \n3. 熟悉工程预算、招投标流程及合同管理，具备较强的数据分析能力。  \n4. 具备良好的沟通协调能力和数据分析能力，能适应快节奏工作环境。","description":"部门介绍\n快乐猴是美团自营社区超市，依托自有供应链和门店管理体系，聚焦家庭用户的三餐所需，为消费者提供高质价比的食杂商品。快乐猴以数字化能力与科学品控为基础，不断满足消费者对“省”和“便利”的需求。\n\n岗位职责\n1. 负责门店工程营建项目的成本预算编制、审核及动态管控，确保项目成本在合理范围内。  \n2. 参与供应商比选、合同谈判及成本优化方案制定，提升项目成本效益。  \n3. 跟踪项目执行过程中的成本变化，及时预警并推动问题解决。  \n4. 建立并完善成本管理体系，输出成本分析报告，支持经营决策。\n\n岗位基本要求\n1. 大学本科及以上学历，工程管理、工程造价、土木工程等相关专业优先。  \n2. 具备3年以上工程营建或零售门店发展相关成本管理经验。  \n3. 熟悉工程预算、招投标流程及合同管理，具备较强的数据分析能力。  \n4. 具备良好的沟通协调能力和数据分析能力，能适应快节奏工作环境。\n\n岗位亮点\n1. 参与公司核心门店拓展项目，直接影响业务布局与发展。  \n2. 与跨职能团队紧密协作，提升综合管理能力。  \n3. 提供清晰的职业发展路径和内部晋升机会。  \n4. 工作地点位于北京，享受一线城市资源与便利。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4402809516","sourceKey":"meituan_social","company":"美团","title":"闪购-歪马-督导经理（山东/辽宁/吉林/黑龙江）","city":"济南市/沈阳市/长春市/哈尔滨市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4402809516&jobShareType=1","duty":"1.协助合作商组建和管理团队，辅导和监督合作商做好团队管理工作；\n2.对合作商各级人员形成有效赋能，在履约配送、推广获客、商品运营、门店经营等模块实现标准化管理、业绩达成和盈利管理；\n3.稽核门店在仓内管理履约体验地推获客标准化落地，提升各个环节效率；\n4.结合商管政策做上传下达，做好门店全生命周期管控，达成总部目标；\n5.收集行业和竞争信息，做好战场动态传达。\n6.负责管理省内各城市商及门店。","requirements":"1.本科及以上学历，市场营销、商务管理或相关专业优先考虑。\n2.具备丰富的渠道管理经验，熟悉渠道销售流程和渠道拓展方法。\n3.具备较强的市场分析能力和数据分析能力，能够准确判断市场需求和销售趋势。\n4.具备良好的沟通能力和团队合作精神，能够与不同部门和合作伙伴进行有效沟通和协调。\n5.具备较强的计划和执行能力，能够制定并执行有效的渠道销售策略。\n6.具备较强的问题解决能力，保持良好的工作状态。","description":"部门介绍\n美团闪购是美团旗下的即时零售平台，依托即时配送能力，连接本地零售供给，满足消费者30分钟万物到家的即时需求。美团闪购涵盖超市便利、食材、水果、鲜花绿植、休闲零食、酒水饮料、数码家电、美妆个护、母婴玩具、日用百货、服饰鞋帽、宠物等诸多品类，业务覆盖全国近3,000个县市区旗，每日百万级在岗骑手，以高效的配送、丰富的品类和广泛的覆盖，为美团数亿用户带来便捷的生活体验，积极助力实体零售线上化转型，提升本地商业活力。\n\n岗位职责\n1.协助合作商组建和管理团队，辅导和监督合作商做好团队管理工作；\n2.对合作商各级人员形成有效赋能，在履约配送、推广获客、商品运营、门店经营等模块实现标准化管理、业绩达成和盈利管理；\n3.稽核门店在仓内管理履约体验地推获客标准化落地，提升各个环节效率；\n4.结合商管政策做上传下达，做好门店全生命周期管控，达成总部目标；\n5.收集行业和竞争信息，做好战场动态传达。\n6.负责管理省内各城市商及门店。\n\n岗位基本要求\n1.本科及以上学历，市场营销、商务管理或相关专业优先考虑。\n2.具备丰富的渠道管理经验，熟悉渠道销售流程和渠道拓展方法。\n3.具备较强的市场分析能力和数据分析能力，能够准确判断市场需求和销售趋势。\n4.具备良好的沟通能力和团队合作精神，能够与不同部门和合作伙伴进行有效沟通和协调。\n5.具备较强的计划和执行能力，能够制定并执行有效的渠道销售策略。\n6.具备较强的问题解决能力，保持良好的工作状态。\n\n具备以下条件优先\n具备以下优先:\n1.有酒水连锁门店管理经验者优先；\n2.有前置仓行业经验者优先。\n\n岗位亮点\n1.能够接触到全面的渠道管理工作，为个人职业发展提供广阔的空间。\n2.可以与各类合作伙伴进行广泛的合作，提升沟通和协调能力。\n3.可以参与制定并执行渠道营销方案，提升销售业绩和市场份额。\n4.可以通过分析市场动态和销售数据，提供有针对性的销售策略和决策支持。\n5.可以在团队协作中提升自己的团队合作和领导能力。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4775134587","sourceKey":"meituan_social","company":"美团","title":"美团外卖渠道策略与增长负责人","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4775134587&jobShareType=1","duty":"1.渠道经营目标与打法制定：制定美团外卖渠道的年度/季度经营策略，将单量与GMV目标拆解到城市、门店、时间节奏，明确各阶段增长杠杆（自然流量、付费流量、活动、复购）的配比与优先级；\n2.分城市扩张节奏管理：基于前置仓的铺设节奏，制定分城市的入驻优先级与爬坡目标，确保“开一个成一个”，沉淀可复制的单城市启动SOP；\n3.预算分配与ROI管理：统筹渠道营销预算（投放、补贴、活动）的分配与调整，建立投放效果评估体系，对渠道整体ROI和单均获客成本负责；\n4.平台关系维护与资源争取：对接美团外卖平台侧（品牌经理、资源运营），争取平台活动资源位、大促坑位、新店流量扶持等政策资源，维护平台的评级与合作生态；\n5.运营体系搭建：搭建“一拖N”的批量运营体系——店铺运营SOP、活动SOP、差评与评分维护SOP、数据预警看板，确保长期运营体系可复用；\n6.团队管理：管理外卖运营团队，明确分工与协作机制，培养团队能力，支撑业务放量期扩编。","requirements":"1.本科及以上学历，5年以上外卖/即时零售/本地生活渠道运营经验，有连锁品牌外卖操盘或多门店批量运营经验；\n2.熟悉美团外卖平台规则与流量逻辑（排序权重、点金/展位产品、活动机制），有平台侧资源或生态背景加分；\n3.数据驱动，具备完整的漏斗分析（曝光→进店→下单）与ROI管理能力；\n4.有0-1搭建渠道运营体系、跨部门协同拿结果的案例；\n5.有AI工具应用习惯，能带领团队用AI提效（批量文案、投放诊断、数据洞察）；\n6.结果导向，做事有韧性，能适应创新业务快节奏爬坡。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1.渠道经营目标与打法制定：制定美团外卖渠道的年度/季度经营策略，将单量与GMV目标拆解到城市、门店、时间节奏，明确各阶段增长杠杆（自然流量、付费流量、活动、复购）的配比与优先级；\n2.分城市扩张节奏管理：基于前置仓的铺设节奏，制定分城市的入驻优先级与爬坡目标，确保“开一个成一个”，沉淀可复制的单城市启动SOP；\n3.预算分配与ROI管理：统筹渠道营销预算（投放、补贴、活动）的分配与调整，建立投放效果评估体系，对渠道整体ROI和单均获客成本负责；\n4.平台关系维护与资源争取：对接美团外卖平台侧（品牌经理、资源运营），争取平台活动资源位、大促坑位、新店流量扶持等政策资源，维护平台的评级与合作生态；\n5.运营体系搭建：搭建“一拖N”的批量运营体系——店铺运营SOP、活动SOP、差评与评分维护SOP、数据预警看板，确保长期运营体系可复用；\n6.团队管理：管理外卖运营团队，明确分工与协作机制，培养团队能力，支撑业务放量期扩编。\n\n岗位基本要求\n1.本科及以上学历，5年以上外卖/即时零售/本地生活渠道运营经验，有连锁品牌外卖操盘或多门店批量运营经验；\n2.熟悉美团外卖平台规则与流量逻辑（排序权重、点金/展位产品、活动机制），有平台侧资源或生态背景加分；\n3.数据驱动，具备完整的漏斗分析（曝光→进店→下单）与ROI管理能力；\n4.有0-1搭建渠道运营体系、跨部门协同拿结果的案例；\n5.有AI工具应用习惯，能带领团队用AI提效（批量文案、投放诊断、数据洞察）；\n6.结果导向，做事有韧性，能适应创新业务快节奏爬坡。\n\n岗位亮点\n管理小象超市核心品类，直接影响品类生意规模和用户购物体验；深度参与小象超市战略制定，与业务负责人共同驱动品类增长。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4780465156","sourceKey":"meituan_social","company":"美团","title":"AI Agent 产品经理","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4780465156&jobShareType=1","duty":"负责小团 Agent 核心产品能力建设，围绕真实用户问题持续提升 Agent 的理解、决策、工具调用和任务完成能力。\n你需要做的不是“接需求、写 PRD、跟进上线”，而是：\n1. 从用户问题和业务结果出发，主动发现值得解决的问题，并能持续追到根因；\n2. 独立负责一个完整方向，从问题定义、方案设计、跨团队协作到最终结果闭环；\n3. 深入理解 Agent 完整链路，包括模型、搜索、知识、Skill、MCP、Harness、评测等能力，能够和算法、研发一起讨论方案，而不是只负责产品层；\n4. 对线上问题追到底，即使最终由其他团队解决，也需要搞清楚问题为什么发生、用了什么方案、效果如何；\n5. 与研发、算法及平台团队共同推进复杂项目，在边界不完全清晰、信息不足够完整的情况下，全力推动事情直至落地。","requirements":"1. 大学本科及以上学历，计算机、人工智能、等相关专业优先。  \n2. 3年以上产品经理经验，有AI、智能体或对话系统相关产品背景者优先。  \n3. 具备较强的逻辑思维、数据分析能力和用户洞察力，能独立推动项目进展。  \n4. 对 AI / Agent 有真实兴趣，愿意深入技术细节，而不是停留在概念层。\n5. 主动性强，不是等别人分活，拿到问题会自己往上下游追，把整条链路搞清楚。\n6. 技术理解不错，对 Harness、Tool、Context、Eval 有理解，不能说这是技术的事。\n7. 能独立负责一个模块，有推动能力；面对一个比较模糊的问题，能定义、定位协同方、推进，直至拿到结果。\n8. 有自己的判断，但 ego 低，能和研发、算法、平台团队一起把事做成。\n9. 对结果敏感，愿意持续追问“为什么”“到底解决没有”“还能不能做得更好”。","description":"部门介绍\n美团平台为用户的基础产品体验负责，还承担了美团的用户增长、市场和品牌营销以及多条业务线的产品设计职责，建立了融合文字、图片、视频和直播等不同形式的內容生态系统，同时整合地图服务部、客户服务和体验部、企业业务部、网约车业务部等部门，致力于用科技提升美团数亿消费者、近千万商家、骑手、司机和团长的服务体验。美团平台拥有高并发、多业务的复杂场景，为技术深度优化提供了最佳实践可能。这里有简单、讲逻辑、有爱的团队，更是一块理想的实战场地，舞台广阔，欢迎你来尽情施展。\n\n岗位职责\n负责小团 Agent 核心产品能力建设，围绕真实用户问题持续提升 Agent 的理解、决策、工具调用和任务完成能力。\n你需要做的不是“接需求、写 PRD、跟进上线”，而是：\n1. 从用户问题和业务结果出发，主动发现值得解决的问题，并能持续追到根因；\n2. 独立负责一个完整方向，从问题定义、方案设计、跨团队协作到最终结果闭环；\n3. 深入理解 Agent 完整链路，包括模型、搜索、知识、Skill、MCP、Harness、评测等能力，能够和算法、研发一起讨论方案，而不是只负责产品层；\n4. 对线上问题追到底，即使最终由其他团队解决，也需要搞清楚问题为什么发生、用了什么方案、效果如何；\n5. 与研发、算法及平台团队共同推进复杂项目，在边界不完全清晰、信息不足够完整的情况下，全力推动事情直至落地。\n\n岗位基本要求\n1. 大学本科及以上学历，计算机、人工智能、等相关专业优先。  \n2. 3年以上产品经理经验，有AI、智能体或对话系统相关产品背景者优先。  \n3. 具备较强的逻辑思维、数据分析能力和用户洞察力，能独立推动项目进展。  \n4. 对 AI / Agent 有真实兴趣，愿意深入技术细节，而不是停留在概念层。\n5. 主动性强，不是等别人分活，拿到问题会自己往上下游追，把整条链路搞清楚。\n6. 技术理解不错，对 Harness、Tool、Context、Eval 有理解，不能说这是技术的事。\n7. 能独立负责一个模块，有推动能力；面对一个比较模糊的问题，能定义、定位协同方、推进，直至拿到结果。\n8. 有自己的判断，但 ego 低，能和研发、算法、平台团队一起把事做成。\n9. 对结果敏感，愿意持续追问“为什么”“到底解决没有”“还能不能做得更好”。\n\n具备以下条件优先\n1. 有 Agent、AI Coding、搜索/RAG、Skill/MCP、工作流、智能助理等相关经验；\n2. 有技术背景，能写代码或有较强工程理解；\n3. 有从 0 到 1 产品经验；\n4. 有复杂跨团队项目 owner 经历；\n5. 对 Agent Runtime / Harness / Tool Use / Eval 等方向有深入理解。\n\n岗位亮点\n1. 参与前沿AI Agent产品的打造，推动人工智能技术在真实场景中的应用。  \n2. 与技术团队共同成长，获得技术深度与产品广度的双重提升。  \n3. 工作地点位于北京核心区域，提供具有竞争力的薪酬与发展空间。  \n4. 扁平化管理，鼓励创新与快速试错，为优秀人才提供广阔发展平台。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4533895233","sourceKey":"meituan_social","company":"美团","title":"无人车业务部-嵌入式硬件负责人","city":"深圳市/北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4533895233&jobShareType=1","duty":"一、团队管理与战略规划\n•\t统筹管理 15 人嵌入式硬件团队，制定团队年度目标、绩效考核与人才梯队建设计划\n•\t建立硬件产品研发流程与方法论，制定硬件产品路线图，输出产品方案与技术策略\n•\t主导硬件技术选型与架构评审，把控关键里程碑节点，确保项目按时高质量交付\n\n二、控制器硬件开发（主攻）\n•\t主导自动配送嵌入式计算平台及控制器的硬件架构设计，完成从需求分析到量产交付的全流程\n•\t负责 MCU/SoC 选型，完成电源管理、时钟、复位、高速总线（CAN/LIN/Ethernet）等核心电路原理图设计\n•\t提供 Layout Guide 及 PCB 布线检查，协作产线完成 PCBA 生产及板卡 Bring Up 调试\n•\t主导电机驱动与执行器控制电路设计，覆盖功能安全（ISO 26262）硬件设计要求\n•\t具备控制器从 0 到 1 自研成功经历，能够独立主导新型控制器产品的立项、设计与量产\n\n三、传感器硬件开发\n•\t负责传感器处理平台的硬件架构与系统设计，覆盖激光雷达、毫米波雷达、摄像头、IMU、超声波等多类传感器\n•\t完成 MIPI/GMSL 摄像头接口、信号调理与 ADC 采样电路设计，支撑传感器融合平台硬件需求\n•\t设计多传感器同步时序方案，配合算法团队完成传感器标定与验证\n\n四、研发支撑与生态建设\n•\t完成相关设计文档编写及专利申请，持续跟踪前沿硬件技术并推动研究成果落地\n•\t与供应商、产线、算法、软件等团队高效协同，推动问题快速闭环\n•\t以管理者角色推动团队 AI 化工作方式转型，识别并落地研发协作、文档管理、决策支持等环节的 AI 增效场景，建立团队 AI 使用文化\n★ 核心硬性要求  候选人须具备自研控制器从 0 到 1 的完整成功经历，包括硬件架构设计、原理图/PCB 设计、Bring Up 调试及量产交付全流程。","requirements":"•\t本科及以上学历，电子工程、通信工程、计算机科学或相关专业\n•\t10 年以上嵌入式硬件开发经验，其中 3 年以上硬件团队管理经验\n•\t深厚的控制器硬件设计功底，熟悉 MCU/SoC 架构、电源管理、高速信号完整性设计\n•\t熟悉 CAN/LIN/Ethernet/SPI/I2C 等主流嵌入式总线协议及接口电路设计\n•\t具备 PCBA 生产协作及板卡 Bring Up 调试经验，能独立定位并解决硬件问题\n•\t具备良好的跨团队沟通与协调能力，能与供应商、产线、算法、软件等部门高效协作\n•\t有意愿并具备能力带领团队完成 AI 化转型，以管理者视角推动 AI 工具系统性落地\n\n核心加分项\n•\t具备控制器自研从 0 到 1 完整成功经历（硬件架构 → 原理图 → PCB → Bring Up → 量产）\n•\t具备无人驾驶、高阶智驾或自动配送场景嵌入式硬件开发经验\n•\t熟悉功能安全标准（ISO 26262）硬件设计要求\n•\t有多传感器融合平台硬件设计经验（激光雷达、毫米波雷达、摄像头等）\n•\t有专利申请或核心技术论文发表经历","description":"部门介绍\n无人车业务部成立于2016年，旨在用无人驾驶技术提升物流配送的效率和体验。美团无人车以自研L4级自动驾驶软硬件技术为核心，与美团即时零售业务结合，形成满足公开道路、社区、工业园区等室外全场景下的无人配送整体解决方案。自2020年起，无人车已在北京、深圳等多地进入常态化试运营阶段，在城市复杂场景下提供针对餐饮外卖、生鲜食杂等货物的即时配送服务。2025年，美团无人车又踏上了同城货运的新探索，并在2026年持续扩大运营范围和车队数量，为更多城市带来智能配送服务。\n欢迎加入美团无人车团队，与我们一起用科技推动即时零售再升级！\n\n岗位职责\n一、团队管理与战略规划\n•\t统筹管理 15 人嵌入式硬件团队，制定团队年度目标、绩效考核与人才梯队建设计划\n•\t建立硬件产品研发流程与方法论，制定硬件产品路线图，输出产品方案与技术策略\n•\t主导硬件技术选型与架构评审，把控关键里程碑节点，确保项目按时高质量交付\n\n二、控制器硬件开发（主攻）\n•\t主导自动配送嵌入式计算平台及控制器的硬件架构设计，完成从需求分析到量产交付的全流程\n•\t负责 MCU/SoC 选型，完成电源管理、时钟、复位、高速总线（CAN/LIN/Ethernet）等核心电路原理图设计\n•\t提供 Layout Guide 及 PCB 布线检查，协作产线完成 PCBA 生产及板卡 Bring Up 调试\n•\t主导电机驱动与执行器控制电路设计，覆盖功能安全（ISO 26262）硬件设计要求\n•\t具备控制器从 0 到 1 自研成功经历，能够独立主导新型控制器产品的立项、设计与量产\n\n三、传感器硬件开发\n•\t负责传感器处理平台的硬件架构与系统设计，覆盖激光雷达、毫米波雷达、摄像头、IMU、超声波等多类传感器\n•\t完成 MIPI/GMSL 摄像头接口、信号调理与 ADC 采样电路设计，支撑传感器融合平台硬件需求\n•\t设计多传感器同步时序方案，配合算法团队完成传感器标定与验证\n\n四、研发支撑与生态建设\n•\t完成相关设计文档编写及专利申请，持续跟踪前沿硬件技术并推动研究成果落地\n•\t与供应商、产线、算法、软件等团队高效协同，推动问题快速闭环\n•\t以管理者角色推动团队 AI 化工作方式转型，识别并落地研发协作、文档管理、决策支持等环节的 AI 增效场景，建立团队 AI 使用文化\n★ 核心硬性要求  候选人须具备自研控制器从 0 到 1 的完整成功经历，包括硬件架构设计、原理图/PCB 设计、Bring Up 调试及量产交付全流程。\n\n岗位基本要求\n•\t本科及以上学历，电子工程、通信工程、计算机科学或相关专业\n•\t10 年以上嵌入式硬件开发经验，其中 3 年以上硬件团队管理经验\n•\t深厚的控制器硬件设计功底，熟悉 MCU/SoC 架构、电源管理、高速信号完整性设计\n•\t熟悉 CAN/LIN/Ethernet/SPI/I2C 等主流嵌入式总线协议及接口电路设计\n•\t具备 PCBA 生产协作及板卡 Bring Up 调试经验，能独立定位并解决硬件问题\n•\t具备良好的跨团队沟通与协调能力，能与供应商、产线、算法、软件等部门高效协作\n•\t有意愿并具备能力带领团队完成 AI 化转型，以管理者视角推动 AI 工具系统性落地\n\n核心加分项\n•\t具备控制器自研从 0 到 1 完整成功经历（硬件架构 → 原理图 → PCB → Bring Up → 量产）\n•\t具备无人驾驶、高阶智驾或自动配送场景嵌入式硬件开发经验\n•\t熟悉功能安全标准（ISO 26262）硬件设计要求\n•\t有多传感器融合平台硬件设计经验（激光雷达、毫米波雷达、摄像头等）\n•\t有专利申请或核心技术论文发表经历\n\n岗位亮点\n🔧  主导自动配送核心控制器自研，从 0 到 1 打造公司自主可控的嵌入式硬件能力\n🚗  深度参与无人配送前沿场景，硬件成果直接落地真实商业化产品\n👥  带领 15 人专业硬件团队，拥有充分的技术决策权与资源支持\n🤖  公司大力推进 AI 化转型，硬件负责人将成为 AI 工具落地的核心推动者\n📈  清晰的晋升通道，有机会成长为公司嵌入式硬件领域的专家与管理者","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4212278585","sourceKey":"meituan_social","company":"美团","title":"电池采购专家","city":"深圳市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4212278585&jobShareType=1","duty":"（1）依业务需求、产品规划和行业情况，负责制定电池、充电柜等品类采购策略，搭建和拓展有竞争力的供应商池；\n（2）负责项目开发初期介入，参与方案评估和技术选型；\n（3）负责制定供应商引入计划，组织供应商引入工作；\n（4）负责供应商商务谈判，签署商务协议；\n（5）负责根据项目需求进行产能规划，保证产能供应安全有效；\n（6）可独自进行正向成本分析，建立或优化成本模型和成本基线，制定并落实降本计划，保障项目目标成本达成；\n（7）关注行业动态，组织内外部学习交流，持续更新行业分析报告；\n（8）支持电池、充电柜等品类全生命周期的供应商管理工作，保障供应商在产品成本、供应、质量管理的配合度；\n（9）作为专家给团队指导，提升团队采购能力，开发供应链课程，给新进员工或是年轻员工进行专业化指导和培养，形成团队人才梯队。","requirements":"（1）本科及以上学历，供应链专业优先；\n（2）8年以上电池、充电电柜品类采购经验，例如电芯、电池、储电柜、充电柜等品类，具备丰富的智能硬件电子物料选型、供应商开发经验；\n（3）熟悉两轮出行行业和产品优先，或是具有消费、共享、汽车、移动产品（机器人等）的智能硬件类电池、充电器（柜）采购经验；\n（4）具备电子品类成本分析和拆解能力；\n（5）具备较强的沟通、协调及组织能力，风险识别及控制能力；\n（6）有正确的廉正价值观和韧性。","description":"部门介绍\n美团的使命是“帮大家吃得更好，生活更好”，公司聚焦“零售 + 科技”战略，和广大商户与各类合作伙伴一起，努力为消费者提供品质生活，推动商品零售和服务零售在需求侧和供给侧的数字化转型。\n2018年9月20日，美团正式在港交所挂牌上市。美团将始终坚持以客户为中心，不断加大在科技研发方面的投入，更好承担社会责任，更多创造社会价值，与广大合作伙伴一起发展共赢。\n\n岗位职责\n（1）依业务需求、产品规划和行业情况，负责制定电池、充电柜等品类采购策略，搭建和拓展有竞争力的供应商池；\n（2）负责项目开发初期介入，参与方案评估和技术选型；\n（3）负责制定供应商引入计划，组织供应商引入工作；\n（4）负责供应商商务谈判，签署商务协议；\n（5）负责根据项目需求进行产能规划，保证产能供应安全有效；\n（6）可独自进行正向成本分析，建立或优化成本模型和成本基线，制定并落实降本计划，保障项目目标成本达成；\n（7）关注行业动态，组织内外部学习交流，持续更新行业分析报告；\n（8）支持电池、充电柜等品类全生命周期的供应商管理工作，保障供应商在产品成本、供应、质量管理的配合度；\n（9）作为专家给团队指导，提升团队采购能力，开发供应链课程，给新进员工或是年轻员工进行专业化指导和培养，形成团队人才梯队。\n\n岗位基本要求\n（1）本科及以上学历，供应链专业优先；\n（2）8年以上电池、充电电柜品类采购经验，例如电芯、电池、储电柜、充电柜等品类，具备丰富的智能硬件电子物料选型、供应商开发经验；\n（3）熟悉两轮出行行业和产品优先，或是具有消费、共享、汽车、移动产品（机器人等）的智能硬件类电池、充电器（柜）采购经验；\n（4）具备电子品类成本分析和拆解能力；\n（5）具备较强的沟通、协调及组织能力，风险识别及控制能力；\n（6）有正确的廉正价值观和韧性。\n\n具备以下条件优先\n（1）获得国际或国内采购师认证者（CPSM或CPPM）加分\n（2）获得项目管理认证者PMP、产品经理师认证者NPDP加分\n（3）具有内部讲师经验的加分\n\n岗位亮点\n500强企业里学习和成长，支持在不同领域的相互学习和轮岗","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4484924716","sourceKey":"meituan_social","company":"美团","title":"机器人-Linux内核/平台软件工程专家","city":"北京市/深圳市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4484924716&jobShareType=1","duty":"1. 架构并开发高可靠性、高性能的Linux操作系统/平台；\n2. 与硬件、算法等部门及外部供应商协作，参与芯片选型、EE与软件架构设计、传感器选型布局，为MTUAV硬件产品提供底层平台支持；\n3. 负责BSP开发与系统集成，确保高质量的 NPI board bring-up 以及 Linux 基础平台功能交付，包括 Kernel 裁剪定制化，驱动架构和开发； \n4. 诊断优化内核问题，如系统稳定性、调度性能、内存分配、功耗等，从软硬件架构设计系统方案，确保平台性能稳定、确定、可观测；\n5. 设计开发高效调试工具，提升团队问题排查与分析效率；\n6. 跟踪 Linux Kernel 前沿技术，探索 Kernel 以及 Cross Layer 创新技术，不断优化 Linux 平台性能；\n7. 制定MTUAV操作系统/平台技术路线图，统筹工程优先级规划、scoping、planning及交付成果管理；\n8. 熟练使用AI工具，融入开发设计流程，探索提升团队效率的方法，输出可复用的实践案例；\n9. 指导培养初级工程师，在设计实现、代码审查、测试验证、部署维护全流程中展现优秀的工程能力与技术领导力。","requirements":"1. 计算机科学、电子工程或相关专业，6年以上Linux内核/平台开发经验，精通C/C++及Shell脚本开发，Linux内核定制开发、驱动编程、内核级调试及性能调优；\n2. 熟悉主流SoC厂商BSP集成，具备board bring-up开发经验（涵盖传感器、ISP、网络接口、外设及加速器等模块）；\n3. 具备商用硬件产品全生命周期发布经验；\n4. 作为核心开发者或技术负责人，完整主导过Linux系统平台的产品化项目，包括上市后迭代优化；\n5. 深耕工程专业，兼具产品与全局系统化思维，关注工作如何与业务和产品结合，确保专业工作的统筹、优先级和方向与业务目标一致；\n6. 拥有通过优秀工程实践推动团队技术提升的成功案例；\n7. 具备优秀的跨部门沟通能力、系统化思维及复杂问题解决能力；\n8. 具备成熟健康的职业素养，高度自驱，兼具技术领导力与强烈的结果责任感；\n9. 熟练使用AI主流工具，能将AI工具有效融入开发日常工作流。","description":"部门介绍\n为了更好地提升城市即时配送的效率与体验，2017年，美团启动了无人机配送服务的探索，通过科技创新推动履约工具变革，加快建设空地协同的本地即时配送网络。\n在过去的六年里，美团无人机完成了飞行器、自动化机场及智能调度系统的研发工作，实现了研发设计、生产制造、运营运维全链条布局，达成了城市复杂场景物流无人机高频次、高密度、多天时、多天侯运行。\n2023年7月，美团无人机在上海发布了自主研发的第四代无人机，跟此前机型相比，新机型升级了环境适应能力，可在“零下20度至50度”的中雨、中雪、6级风、弱光等环境中稳定飞行，能够适应97%以上国内城市的自然环境要求。\n截至2024年12月，美团无人机已在深圳、北京、上海、广州、南京、迪拜等城市开通53条航线，并累计完成订单超40万单。即时零售配送服务覆盖了办公、社区、景区、市政公园、校园、医疗、图书馆等多种场景。在医疗场景中，美团无人机可围绕医疗血液、检验样本、院前急救物资、特殊药品等医疗物资配送需求建设端到端的全天时急送网络。\n\n岗位职责\n1. 架构并开发高可靠性、高性能的Linux操作系统/平台；\n2. 与硬件、算法等部门及外部供应商协作，参与芯片选型、EE与软件架构设计、传感器选型布局，为MTUAV硬件产品提供底层平台支持；\n3. 负责BSP开发与系统集成，确保高质量的 NPI board bring-up 以及 Linux 基础平台功能交付，包括 Kernel 裁剪定制化，驱动架构和开发； \n4. 诊断优化内核问题，如系统稳定性、调度性能、内存分配、功耗等，从软硬件架构设计系统方案，确保平台性能稳定、确定、可观测；\n5. 设计开发高效调试工具，提升团队问题排查与分析效率；\n6. 跟踪 Linux Kernel 前沿技术，探索 Kernel 以及 Cross Layer 创新技术，不断优化 Linux 平台性能；\n7. 制定MTUAV操作系统/平台技术路线图，统筹工程优先级规划、scoping、planning及交付成果管理；\n8. 熟练使用AI工具，融入开发设计流程，探索提升团队效率的方法，输出可复用的实践案例；\n9. 指导培养初级工程师，在设计实现、代码审查、测试验证、部署维护全流程中展现优秀的工程能力与技术领导力。\n\n岗位基本要求\n1. 计算机科学、电子工程或相关专业，6年以上Linux内核/平台开发经验，精通C/C++及Shell脚本开发，Linux内核定制开发、驱动编程、内核级调试及性能调优；\n2. 熟悉主流SoC厂商BSP集成，具备board bring-up开发经验（涵盖传感器、ISP、网络接口、外设及加速器等模块）；\n3. 具备商用硬件产品全生命周期发布经验；\n4. 作为核心开发者或技术负责人，完整主导过Linux系统平台的产品化项目，包括上市后迭代优化；\n5. 深耕工程专业，兼具产品与全局系统化思维，关注工作如何与业务和产品结合，确保专业工作的统筹、优先级和方向与业务目标一致；\n6. 拥有通过优秀工程实践推动团队技术提升的成功案例；\n7. 具备优秀的跨部门沟通能力、系统化思维及复杂问题解决能力；\n8. 具备成熟健康的职业素养，高度自驱，兼具技术领导力与强烈的结果责任感；\n9. 熟练使用AI主流工具，能将AI工具有效融入开发日常工作流。\n\n具备以下条件优先\n1. 熟悉Linux性能观测和优化相关工具，并理解其内部机制细节；\n2. 精通相关硬件/软件安全架构；\n3. 拥有机器人研发经验，包括无人机、自动驾驶汽车或通用机器人等领域；\n4. 具备硬件产品工厂工具及制造流程相关经验；\n5. 具有在工程项目中定制，集成 AI 工具，并为项目以及研发团队提效，有具体落地案例；\n6. 有团队管理经验，并保持技术一线的敏锐性。\n\n岗位亮点\n这是一个早期快速发展的项目，岗位可参与产品到工程全链条的探索和发展，影响力大。技术深度足，业务可见度高，战略价值真实。\n平台软件OS作为美团无人机所有产品的软硬件基础，在工程和业务领域发挥着基础性的关键作用。    \n我们正在建设一支一流平台软件团队，为持续演进的硬件、传感器和算力平台，提供统一、高效、稳定的 OS 底座。 \n我们诚邀行业内的杰出人才，在帮助我们达成这个工程目标的同时，建立起一个高效的工程团队。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4281542707","sourceKey":"meituan_social","company":"美团","title":"整合营销","city":"圣保罗","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4281542707&jobShareType=1","duty":"1. 负责整合营销策略的制定与执行，基于本地化洞察，消费者需求与机会点研究，制定年度整合营销规划。协同市场，推动品牌声量与用户增长。  \n2. 带领团队，负责营销方案落地，能够联动供给侧，深度协同业务各端，针对不同品类、节日进行爆款打造，推动供给端的营销配合。  \n3. 监控营销活动效果，建立数据评估体系，持续迭代优化运营策略与执行方案。\n4.运用AI工具辅助市场洞察分析、营销策划文档撰写及活动效果复盘，探索AI在整合营销场景的落地实践","requirements":"1、经验要求：本科及以上学历，8年以上市场营销经验。拥有互联网平台（电商/外卖）背景者优先；具备巴西本地市场操盘经验优先。\n2、核心能力：\n· 整合思维： 能打破渠道壁垒，将品牌、效果、商家运营整合进同一个大 Campaign 中。\n· 数据敏锐度： 善于分析巴西复杂的用户数据，清晰区分 CAC（用户获取成本）、LTV（用户生命周期价值）与补贴效率的关系。\n· 创意审美： 对巴西本土的视觉语言（如色彩搭配、桑巴/放克音乐元素）有高敏感度，能指导代理商产出“原生感”强的素材。\n· 语言能力： 英文可作为工作语言者优先\n· 能熟练使用至少一种AI工具辅助日常工作（市场分析、内容创作、方案撰写等），具备主动探索AI新能力的意愿","description":"部门介绍\nKeeta是全球领先外卖平台美团旗下的独立品牌，肩负着“帮大家吃得更好，生活更好”的使命。依托美团深耕中国市场15年的技术与运营积淀，我们正引领全球餐饮与商品即时配送服务的创新与发展。\n\n自2023年成立以来，Keeta始终扎根社区并创造价值。我们为用户提供可靠的外卖体验，以智慧技术助餐厅提升经营效率，在为骑手拓宽收入来源的同时，也充分提供安全保障措施。基于这份多方共赢、共同成长的理念，我们的业务已从中国香港稳步拓展至中东及巴西，并持续向世界迈进。\n\n岗位职责\n1. 负责整合营销策略的制定与执行，基于本地化洞察，消费者需求与机会点研究，制定年度整合营销规划。协同市场，推动品牌声量与用户增长。  \n2. 带领团队，负责营销方案落地，能够联动供给侧，深度协同业务各端，针对不同品类、节日进行爆款打造，推动供给端的营销配合。  \n3. 监控营销活动效果，建立数据评估体系，持续迭代优化运营策略与执行方案。\n4.运用AI工具辅助市场洞察分析、营销策划文档撰写及活动效果复盘，探索AI在整合营销场景的落地实践\n\n岗位基本要求\n1、经验要求：本科及以上学历，8年以上市场营销经验。拥有互联网平台（电商/外卖）背景者优先；具备巴西本地市场操盘经验优先。\n2、核心能力：\n· 整合思维： 能打破渠道壁垒，将品牌、效果、商家运营整合进同一个大 Campaign 中。\n· 数据敏锐度： 善于分析巴西复杂的用户数据，清晰区分 CAC（用户获取成本）、LTV（用户生命周期价值）与补贴效率的关系。\n· 创意审美： 对巴西本土的视觉语言（如色彩搭配、桑巴/放克音乐元素）有高敏感度，能指导代理商产出“原生感”强的素材。\n· 语言能力： 英文可作为工作语言者优先\n· 能熟练使用至少一种AI工具辅助日常工作（市场分析、内容创作、方案撰写等），具备主动探索AI新能力的意愿\n\n岗位亮点\n在Keeta，有快速发展的业务，有更高更远的国际化视野，\n有丰富的工作和生活体验，有志同道合的伙伴并肩前行，\n你将不仅是见证者，更是参与者、创造者！\n你的每一步努力，都将为 Keeta 添上浓墨重彩的一笔；\n你的每一个梦想，都将在这里生根发芽，绽放光彩","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4777289650","sourceKey":"meituan_social","company":"美团","title":"用户增长策略运营专家（补贴与活动增长方向）","city":"北京市/上海市/麦纳麦","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4777289650&jobShareType=1","duty":"1、通过策划日、周、月维度活动期爆发方案，对订单量提升结果负责。\n\n2、基于用户分层、画像与行为特征，制定差异化补贴/权益策略，持续优化补贴成本与ROI。\n\n3、探索低成本或零补贴增长路径，通过新玩法、互动、品牌渗透、线上线下结合等方式带来增量。\n\n4、主导创新活动从创意、方案、落地到复盘，沉淀可复用增长机制\n\n5、协同数据、产品、市场、品牌、供给等团队，推进实验与项目落地，确保结果交付。","requirements":"1、本科及以上，5年以上用户增长、活动运营、补贴策略等相关经验。\n\n2、数据驱动，能独立完成用户分层、补贴效率分析、活动复盘，熟练使用SQL和AI者优先。\n\n3、具备创新意识和品牌渗透思维，能设计新玩法，并平衡成本、体验与转化；有脉冲订单、大促、爆款活动或补贴增长成功案例，强结果导向。\n\n4、项目管理和跨团队沟通的能力，能持续迭代优化。","description":"部门介绍\nKeeta是全球领先外卖平台美团旗下的独立品牌，肩负着“帮大家吃得更好，生活更好”的使命。依托美团深耕中国市场15年的技术与运营积淀，我们正引领全球餐饮与商品即时配送服务的创新与发展。\n\n自2023年成立以来，Keeta始终扎根社区并创造价值。我们为用户提供可靠的外卖体验，以智慧技术助餐厅提升经营效率，在为骑手拓宽收入来源的同时，也充分提供安全保障措施。基于这份多方共赢、共同成长的理念，我们的业务已从中国香港稳步拓展至中东及巴西，并持续向世界迈进。\n\n岗位职责\n1、通过策划日、周、月维度活动期爆发方案，对订单量提升结果负责。\n\n2、基于用户分层、画像与行为特征，制定差异化补贴/权益策略，持续优化补贴成本与ROI。\n\n3、探索低成本或零补贴增长路径，通过新玩法、互动、品牌渗透、线上线下结合等方式带来增量。\n\n4、主导创新活动从创意、方案、落地到复盘，沉淀可复用增长机制\n\n5、协同数据、产品、市场、品牌、供给等团队，推进实验与项目落地，确保结果交付。\n\n岗位基本要求\n1、本科及以上，5年以上用户增长、活动运营、补贴策略等相关经验。\n\n2、数据驱动，能独立完成用户分层、补贴效率分析、活动复盘，熟练使用SQL和AI者优先。\n\n3、具备创新意识和品牌渗透思维，能设计新玩法，并平衡成本、体验与转化；有脉冲订单、大促、爆款活动或补贴增长成功案例，强结果导向。\n\n4、项目管理和跨团队沟通的能力，能持续迭代优化。\n\n具备以下条件优先\nSQL能力，商业分析能力，英语沟通的能力\n\n岗位亮点\n1、核心增长岗位，直接对订单增量和补贴效率负责，成果清晰可见。\n\n2、补贴预算与策略空间大，鼓励创新玩法和品牌渗透，支持从0到1探索新增长路径，可验证用户分层、差异化补贴和增长实验。\n\n3、与数据、产品、市场、品牌紧密协作，成长速度快、影响面广。\n\n4、可base 海外，更强有力的薪资竞争力，获得不同的工作、生活体验。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4788548017","sourceKey":"meituan_social","company":"美团","title":"供应商与采购规则管理专家","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4788548017&jobShareType=1","duty":"1. 统筹供应商全生命周期管理体系：\n• 主导\"2+4+2\"供应商分类运营体系落地\n• 完善供应商全生命周期管理 SOP：准入→评估→分级→激励→退出\n• 设计供应商绩效评估体系与战略供应商差异化管理机制\n• 推动供应商主数据治理，统一跨系统数据标准\n2. 采购制度流程设计与运营\n• 维护采购制度体系，负责版本管理与修订机制\n• 持续识别采购流程中的效率瓶颈与风险点，推动流程优化与系统化\n• 建立制度例外与豁免审批机制，处理业务侧例外申请\n• 主导制度宣贯与培训\n3. 部门运营指标体系建设与管理\n• 设计采购运营的分层指标体系（结果/过程/健康度指标）\n• 明确指标口径定义、数据来源、责任人，与数据团队协作搭建看板\n• 建立指标Review机制，驱动业务改进与异动归因\n4. AI 应用探索与落地（Co-Owner with AI 团队）\n• 识别 AI 应用机会\n• 将业务规则翻译为 AI 可执行的逻辑\n• 参与知识库 / Agent 在供应商管理与风险治理场景的搭建与效果验证\n5. 跨部门协同与体系推广，推动体系标准在 BG/BU 的一致性落地。","requirements":"【硬性门槛】\n• 本科及以上学历，8 年以上采购/供应链/运营相关经验\n• 其中 3 年以上专注于供应商管理 / 采购运营 / 制度流程管理方向\n• 1-3 年团队管理经验，或主导过大型体系性项目（供应商体系/制度体系/指标体系任选一）\n• 大型互联网 / 头部企业采购中台或运营中台背景优先\n【专业能力】\n• 供应商管理：熟悉全生命周期管理方法论，有供应商分类管理或战略供应商管理实操经验\n• 风险与规则治理：理解 COSO / ISO 31000 等风险管理框架，能落地为业务规则；熟悉采购合规制度设计\n• 数据思维与系统认知：熟悉 SRM / ERP / CM 等系统，能用数据发现问题\n• 指标体系：熟悉分层指标体系等方法论，有经营分析或指标体系搭建经验\n• 项目管理：能独立推动跨部门项目，具备矩阵组织影响力\n【AI 协同能力】\n• 有将业务流程拆解为标准化规则的经验\n• 对 RAG / Agent / 知识图谱在管理场景的应用有基本认知\n• 优先：有知识库 / Ontology / AI 风控项目经验","description":"部门介绍\n公司事务平台负责构建公司的公共战略体系，助力业务可持续发展及公司对外影响力的提升。通过内外部风险管理，确保公司合规发展；通过深耕公共战略，推动内外良好沟通，连接公司发展与社会期待，助力业务高质量发展；通过管理社会责任议题、公益投入等，助力公司创造更多社会价值；同时为公司提供行政、采购等基础服务。我们坚持“懂业务、拿结果，勇担当、善协同，不唯上、只唯真”的工作理念，期待具有公共战略素养、了解公司治理逻辑的你加入！\n\n岗位职责\n1. 统筹供应商全生命周期管理体系：\n• 主导\"2+4+2\"供应商分类运营体系落地\n• 完善供应商全生命周期管理 SOP：准入→评估→分级→激励→退出\n• 设计供应商绩效评估体系与战略供应商差异化管理机制\n• 推动供应商主数据治理，统一跨系统数据标准\n2. 采购制度流程设计与运营\n• 维护采购制度体系，负责版本管理与修订机制\n• 持续识别采购流程中的效率瓶颈与风险点，推动流程优化与系统化\n• 建立制度例外与豁免审批机制，处理业务侧例外申请\n• 主导制度宣贯与培训\n3. 部门运营指标体系建设与管理\n• 设计采购运营的分层指标体系（结果/过程/健康度指标）\n• 明确指标口径定义、数据来源、责任人，与数据团队协作搭建看板\n• 建立指标Review机制，驱动业务改进与异动归因\n4. AI 应用探索与落地（Co-Owner with AI 团队）\n• 识别 AI 应用机会\n• 将业务规则翻译为 AI 可执行的逻辑\n• 参与知识库 / Agent 在供应商管理与风险治理场景的搭建与效果验证\n5. 跨部门协同与体系推广，推动体系标准在 BG/BU 的一致性落地。\n\n岗位基本要求\n【硬性门槛】\n• 本科及以上学历，8 年以上采购/供应链/运营相关经验\n• 其中 3 年以上专注于供应商管理 / 采购运营 / 制度流程管理方向\n• 1-3 年团队管理经验，或主导过大型体系性项目（供应商体系/制度体系/指标体系任选一）\n• 大型互联网 / 头部企业采购中台或运营中台背景优先\n【专业能力】\n• 供应商管理：熟悉全生命周期管理方法论，有供应商分类管理或战略供应商管理实操经验\n• 风险与规则治理：理解 COSO / ISO 31000 等风险管理框架，能落地为业务规则；熟悉采购合规制度设计\n• 数据思维与系统认知：熟悉 SRM / ERP / CM 等系统，能用数据发现问题\n• 指标体系：熟悉分层指标体系等方法论，有经营分析或指标体系搭建经验\n• 项目管理：能独立推动跨部门项目，具备矩阵组织影响力\n【AI 协同能力】\n• 有将业务流程拆解为标准化规则的经验\n• 对 RAG / Agent / 知识图谱在管理场景的应用有基本认知\n• 优先：有知识库 / Ontology / AI 风控项目经验\n\n具备以下条件优先\n大型互联网供应商管理 / 采购运营体系搭建经验（主导或核心参与）；有 SRM / 风控系统的业务侧建设经验；持有 CIPS / CPSM / CPM / CIA / CRMA 等任一认证\n\n岗位亮点\n体系建设主导者 / AI+管理交叉领域复合价值高 / 跨部门核心枢纽视野广","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4631014029","sourceKey":"meituan_social","company":"美团","title":"魔数Data Agent研发工程师","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4631014029&jobShareType=1","duty":"1. 参与并负责BI+AI方向建设，探索并落地AI重构BI的新范式，推动Data Agent等AI技术与BI平台的深度融合，引领数据消费方式的智能化升级\n2. 参与并负责BI系统架构优化、构建AI友好的系统架构。深度参与商业智能平台（魔数BI）的系统架构设计与研发，通过技术优化持续提升BI平台的迭代效率、系统稳定性与查询性能。\n3. 参与并负责BI应用侧建设，带领/协同团队持续迭代多维分析、可视化报表等核心BI能力，打造好的的数据使用体验，提升数万研发和业务人员的数据效率","requirements":"1. 本科及以上学历，计算机相关专业，3 年以上后端或 AI 工程开发经验。\n2. 扎实的工程基础，熟练掌握 Java / Python / Go 至少一门，熟悉主流服务端框架，有高并发、高性能服务的设计与优化经验，能写出高质量、可维护的代码。\n3. 有 LLM 应用开发实际经验，熟悉 OpenAI / Anthropic / 主流开源模型的 API 使用，了解 Function Calling、Tool Use 机制，理解 ReAct、Plan-and-Execute 等 Agent 范式。\n4. 有 Agent 框架开发或使用经验（LangGraph、OpenAI Agents SDK、Claude Agent SDK 或自研框架），熟悉上下文工程与 RAG 系统设计，包括知识库构建、向量检索、上下文管理等。\n5. 有 SQL 与数据建模基础，理解数仓维度建模与指标体系，能将模糊的业务问题拆解为明确的定义、测试用例与验收标准。\n6. 有生产级 AI 系统落地经验，了解 Prompt 版本管理、Trace / Log 可观测性、评估体系建设等工程实践。\n7. 良好的沟通能力与团队合作精神，有强烈的责任心，有独立负责系统级服务开发的经验。","description":"部门介绍\n基础研发平台是美团的核心技术平台，立足于“零售+科技”的战略定位，通过打造人工智能、大数据、云计算、安全等核心技术能力，以及研发效能平台、企业应用平台等公共服务，为业务提供稳定安全、扩展易用、技术领先的平台技术和产品服务。\n在这里，我们会参与到最前沿的技术研发和探索；能够接触超规模集群、海量数据，挑战高复杂业务场景，有机会与业界一流的工程师一起并肩前行。\n在这里，我们有超强的技术氛围，持续向社区贡献业界实践，加速行业技术发展；我们有完善的互联网学习生态圈，重视底层逻辑和方法论，助力职业生涯的非线性成长。\n真诚地邀请你，和我们一起驱动技术发展，创造行业价值。\n\n岗位职责\n1. 参与并负责BI+AI方向建设，探索并落地AI重构BI的新范式，推动Data Agent等AI技术与BI平台的深度融合，引领数据消费方式的智能化升级\n2. 参与并负责BI系统架构优化、构建AI友好的系统架构。深度参与商业智能平台（魔数BI）的系统架构设计与研发，通过技术优化持续提升BI平台的迭代效率、系统稳定性与查询性能。\n3. 参与并负责BI应用侧建设，带领/协同团队持续迭代多维分析、可视化报表等核心BI能力，打造好的的数据使用体验，提升数万研发和业务人员的数据效率\n\n岗位基本要求\n1. 本科及以上学历，计算机相关专业，3 年以上后端或 AI 工程开发经验。\n2. 扎实的工程基础，熟练掌握 Java / Python / Go 至少一门，熟悉主流服务端框架，有高并发、高性能服务的设计与优化经验，能写出高质量、可维护的代码。\n3. 有 LLM 应用开发实际经验，熟悉 OpenAI / Anthropic / 主流开源模型的 API 使用，了解 Function Calling、Tool Use 机制，理解 ReAct、Plan-and-Execute 等 Agent 范式。\n4. 有 Agent 框架开发或使用经验（LangGraph、OpenAI Agents SDK、Claude Agent SDK 或自研框架），熟悉上下文工程与 RAG 系统设计，包括知识库构建、向量检索、上下文管理等。\n5. 有 SQL 与数据建模基础，理解数仓维度建模与指标体系，能将模糊的业务问题拆解为明确的定义、测试用例与验收标准。\n6. 有生产级 AI 系统落地经验，了解 Prompt 版本管理、Trace / Log 可观测性、评估体系建设等工程实践。\n7. 良好的沟通能力与团队合作精神，有强烈的责任心，有独立负责系统级服务开发的经验。\n\n具备以下条件优先\n1. 有 Data Agent、ChatBI、Text-to-SQL、智能数据助手等数据智能产品的研发经验，理解语义层 / 指标层对准确性的价值。\n2. 有 BI 工具、多维分析、报表系统、指标平台、元数据管理或数据治理工具的开发经验。\n3. 有 MCP（Model Context Protocol）协议开发或集成经验，或有多 Agent 协同、Agent 编排系统的设计经验。\n4. 有 Agent 评测（Evaluation）、LLM 可观测性或 Guardrails 的生产实践。\n5. 熟悉 Hive、Spark、Doris 等分布式计算与 OLAP 引擎。\n6. 是 Coding Agent 等 AI 工具的深度用户，熟悉大模型的能力边界与失败模式。\n7. 参与过开源 Agent 项目，或有自己的相关作品。\n\n岗位亮点\n1. 主导核心项目：超大规模BI平台核心项目等你来驱动，直接影响数万研发与业务人员的数据使用体验，技术价值清晰可见、可量化\n2. 深度参与前沿Data Agent技术：有机会亲身参与从敏捷BI到Data Agent新BI范式的改造落地，探索AI重构数据消费方式的前沿实践，见证并推动BI行业新一代架构的演进\n3. 全链路数据视野：深度参与亿级用户规模的数据平台建设，从技术与业务双视角理解数据从生产到消费的完整链路，快速建立大型互联网公司数据体系的系统认知","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4674316957","sourceKey":"meituan_social","company":"美团","title":"PC加工专家","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4674316957&jobShareType=1","duty":"1.加工工艺标准化与优化 — 负责PC加工全品类工艺标准的制定与持续优化；运用IE方法论（动作研究、时间研究、ECRS等）系统性识别效率瓶颈，设计改善方案并推动落地（如切台时长压缩、工序合并、辅助工装设计等）\n2.场地布局与动线优化 — 主导存量加工仓的布局优化，从工艺视角输出动线设计方案；优化人员走动路径、物料流转效率、台面/设备摆放，降低非增值时间占比（新建仓/搬迁仓图纸规划由规划岗负责）\n3.加工流程优化 — 端到端梳理加工流程（收货→定品定台→加工→打包→交接），识别浪费和断点；输出标准化SOP并推动多城市/多仓复制推广\n4.标准体系建设与迭代 — 搭建加工工艺标准体系，建立持续迭代机制；沉淀各城市/各品类优秀实践，抽象为可复制的标准方案，驱动全国统一推广落地","requirements":"1. 本科及以上学历，5年以上生鲜加工/食品加工/制造业产线运营或工艺优化经验\n2. 必须有一线现场管理经验，熟悉加工工序流和产线布局逻辑\n3. 系统掌握IE（工业工程）方法论：动作研究、时间研究、产线平衡、布局设计、ECRS、价值流图（VSM）等，能独立主导工艺改善项目\n4. 有从0到1设计或大幅优化工艺流程的成功案例，能量化改善效果（如工时降低X%、动线缩短X米、产能提升X%）\n5. 具备标准化抽象和跨区域推广能力——能把单仓优秀实践提炼为可复制方案，推动多城市落地","description":"部门介绍\n快驴进货是美团旗下的餐饮供应链平台，帮助餐饮商户以更低成本、更高效率来获取安全可靠的食材供应，让餐饮采购更简单。快驴进货同步发展“自营+平台”的业务模式，在采购环节一方面向上游供应商直采大宗商品，另一方面引入各地批发商，助力平台伙伴共同发展；在销售环节既有自建团队进行市场、客户拓展，又帮助各地批发商拓展业务；同时自建仓储管理系统、配送网络与团队，为客户提供优质履约服务。\n截至2022年，快驴进货布局了全国41个城市，为百万家商户提供“全、省、稳、好”的餐饮供应链服务。我们拥有3000+品牌食材、超5万SKU商品、超28万商品资质，并提供源头严审核、食品安全严把关、24小时无忧售后的全面保障，实现手机下单、送货上门的高效采购模式，帮百万商家节省了采购时间与成本，助力平台伙伴共同发展，在万亿市场共享机遇。\n在这里，你将收获完善的员工发展机制及学习体系，与各界专家一起深度参与餐饮供应链业务的发展。欢迎优秀的你加入美团快驴进货，与我们一起成长，一起更好！\n\n岗位职责\n1.加工工艺标准化与优化 — 负责PC加工全品类工艺标准的制定与持续优化；运用IE方法论（动作研究、时间研究、ECRS等）系统性识别效率瓶颈，设计改善方案并推动落地（如切台时长压缩、工序合并、辅助工装设计等）\n2.场地布局与动线优化 — 主导存量加工仓的布局优化，从工艺视角输出动线设计方案；优化人员走动路径、物料流转效率、台面/设备摆放，降低非增值时间占比（新建仓/搬迁仓图纸规划由规划岗负责）\n3.加工流程优化 — 端到端梳理加工流程（收货→定品定台→加工→打包→交接），识别浪费和断点；输出标准化SOP并推动多城市/多仓复制推广\n4.标准体系建设与迭代 — 搭建加工工艺标准体系，建立持续迭代机制；沉淀各城市/各品类优秀实践，抽象为可复制的标准方案，驱动全国统一推广落地\n\n岗位基本要求\n1. 本科及以上学历，5年以上生鲜加工/食品加工/制造业产线运营或工艺优化经验\n2. 必须有一线现场管理经验，熟悉加工工序流和产线布局逻辑\n3. 系统掌握IE（工业工程）方法论：动作研究、时间研究、产线平衡、布局设计、ECRS、价值流图（VSM）等，能独立主导工艺改善项目\n4. 有从0到1设计或大幅优化工艺流程的成功案例，能量化改善效果（如工时降低X%、动线缩短X米、产能提升X%）\n5. 具备标准化抽象和跨区域推广能力——能把单仓优秀实践提炼为可复制方案，推动多城市落地\n\n岗位亮点\n1.提供0-1搭建PC加工中心经验和团队管理经验的机会；\n2.可以在物流/物流运营领域发展，拓展专业技能和管理能力；","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4640769408","sourceKey":"meituan_social","company":"美团","title":"商业分析师-业务BP","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4640769408&jobShareType=1","duty":"本岗位隶属美团企业业务的经营规划团队，直接向业务负责人负责，从全局视角统筹业务资源。每名商业分析师 BP 一个一线业务单元，通过考核激励、资源配置和产品定价等核心抓手，帮助业务团队看清方向、找准路径、取得成果。你既是业务蓝图的规划师，也是业务攻坚克难的策略伙伴。\n\n具体岗位职责：\n\n1、绩效与激励机制：承接年度战略，设计并迭代团队考核激励机制；测算投入产出，优化指标、目标与资源配置，牵引团队行为与业务目标一致。\n\n2、核心业务策略：围绕定价、客户分层、资源投放等议题开展专项分析，识别增长机会或经营瓶颈，形成影响可测算、路径可执行的方案；协同销售、产研、财务推动落地并复盘。\n\n3、行业研究与外部对标：跟踪行业动态和优秀实践，围绕定价模型、销售激励、客户管理开展研究，为业务判断和策略设计提供外部参照。","requirements":"1、经验背景：本科及以上学历，3 年以上互联网商业分析、策略运营或管理咨询经验；有 ToB 业务、绩效考核或商业化定价经验者优先。\n\n2、业务理解与商业判断：能够快速理解业务目标、经营模式和一线动作，从模糊现象中识别关键问题；具备结构化思考能力，能结合事实形成独立判断，并提出有依据的不同意见。\n\n3、AI 实操能力：具备 AI 工具实际动手能力，能使用 AI 或零代码工具搭建自动化工作流、数据处理工具或可视化应用；有完整项目经验者优先。\n\n4、协同与落地：具备良好的跨部门沟通和项目推进能力，能协调销售、产研、财务等角色，将分析结论转化为行动，并对落地结果负责。\n\n招聘流程说明：流程中包含远程笔试，将重点考查业务理解、结构化思考和 AI 工具实际动手能力。","description":"部门介绍\n美团平台为用户的基础产品体验负责，还承担了美团的用户增长、市场和品牌营销以及多条业务线的产品设计职责，建立了融合文字、图片、视频和直播等不同形式的內容生态系统，同时整合地图服务部、客户服务和体验部、企业业务部、网约车业务部等部门，致力于用科技提升美团数亿消费者、近千万商家、骑手、司机和团长的服务体验。美团平台拥有高并发、多业务的复杂场景，为技术深度优化提供了最佳实践可能。这里有简单、讲逻辑、有爱的团队，更是一块理想的实战场地，舞台广阔，欢迎你来尽情施展。\n\n岗位职责\n本岗位隶属美团企业业务的经营规划团队，直接向业务负责人负责，从全局视角统筹业务资源。每名商业分析师 BP 一个一线业务单元，通过考核激励、资源配置和产品定价等核心抓手，帮助业务团队看清方向、找准路径、取得成果。你既是业务蓝图的规划师，也是业务攻坚克难的策略伙伴。\n\n具体岗位职责：\n\n1、绩效与激励机制：承接年度战略，设计并迭代团队考核激励机制；测算投入产出，优化指标、目标与资源配置，牵引团队行为与业务目标一致。\n\n2、核心业务策略：围绕定价、客户分层、资源投放等议题开展专项分析，识别增长机会或经营瓶颈，形成影响可测算、路径可执行的方案；协同销售、产研、财务推动落地并复盘。\n\n3、行业研究与外部对标：跟踪行业动态和优秀实践，围绕定价模型、销售激励、客户管理开展研究，为业务判断和策略设计提供外部参照。\n\n岗位基本要求\n1、经验背景：本科及以上学历，3 年以上互联网商业分析、策略运营或管理咨询经验；有 ToB 业务、绩效考核或商业化定价经验者优先。\n\n2、业务理解与商业判断：能够快速理解业务目标、经营模式和一线动作，从模糊现象中识别关键问题；具备结构化思考能力，能结合事实形成独立判断，并提出有依据的不同意见。\n\n3、AI 实操能力：具备 AI 工具实际动手能力，能使用 AI 或零代码工具搭建自动化工作流、数据处理工具或可视化应用；有完整项目经验者优先。\n\n4、协同与落地：具备良好的跨部门沟通和项目推进能力，能协调销售、产研、财务等角色，将分析结论转化为行动，并对落地结果负责。\n\n招聘流程说明：流程中包含远程笔试，将重点考查业务理解、结构化思考和 AI 工具实际动手能力。\n\n岗位亮点\n你将获得：\n\n1、业务影响力：掌握绩效考核资源，深度参与产品定价策略，分析结论直接进入业务决策与执行过程。\n\n2、完整商业视角：深度参与客户策略、产品定价、供给管理和财税结构等经营全链路，建立完整的商业认知和判断力。\n\n3、氛围与成长：团队背景多元、管理扁平，重视专业判断和有效产出，尊重个体；已有丰富的内部课程，并不定期开展专项培训，为成员成长提供持续支持。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4586879715","sourceKey":"meituan_social","company":"美团","title":"HRBP·AI转型方向（金融科技）","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4586879715&jobShareType=1","duty":"1.金融场景AI转型的HRBP定位\n\n深入理解金服各业务线的AI应用场景（风控、支付、信贷、保险等），识别AI转型带来的组织变化需求\n陪伴业务负责人完成AI时代的组织调整、团队重构和人才策略升级\n从能力建设角度，支持金服在AI时代的人才结构优化与能力模型迭代\n\n2. AI时代的人才策略\n\n洞察AI对金融科技人才能力模型的重塑，推动HRBP团队自身的能力升级\n建立AI相关的招聘策略和人才画像，吸引既懂金融又理解AI应用的复合型人才\n推动内部人才在AI方向的能力转型\n\n3. 用AI手段革新组织自身工作流程和范式\n\n探索AI在HR场景中的应用（组织诊断、人才盘点、离职预警、招聘提效等）\n将AI工具融入日常HRBP工作流，提升信息获取、数据分析、报告输出的效率\n同时推动HR团队建立AI应用能力\n\n4. 组织变革推动者\n\n识别AI转型带来的组织挑战（岗位变化、能力差距、文化适配等）\n设计变革沟通和组织适配方案，降低转型阻力\n与业务负责人、HR团队协同，确保组织变革平稳落地","requirements":"• 3年以上HRBP经验，有陪伴业务快速变化或转型的实战经历\n\n• 对AI有真实的好奇和实际使用习惯（不需写代码，但需要真正在用）\n\n• 理解金融业务场景优先，有科技/互联网行业HRBP经验优先\n\n• 心力强、有冲劲，能在模糊中自驱找方向\n\n• 积极主动、聪明好学、情商高，善于跨团队协同","description":"部门介绍\n美团HR的使命是“建设有生命力的组织，为客户和社会创造价值。” 我们认为HR的工作不是以自身“专业”为中心，而是要建设有助于员工发挥创造力的环境，支持他们更好地为外部客户和社会创造价值，也实现组织自身的进化和传承。在这个过程中，我们的每位HR同学都是“业务的战略合作伙伴、组织能力的建设者、美团精神的布道者、员工的成长伙伴”。我们要设计面向长期支撑组织有效运转的机制，我们要求真务实地帮业务解决发展中的问题和阵痛，我们要支持每一位员工历经磨炼收获成长。我们要影响和驱动让世界更美好的变化发生。如果这也是你追求的，欢迎加入美团HR，与我们一路同行！\n\n岗位职责\n1.金融场景AI转型的HRBP定位\n\n深入理解金服各业务线的AI应用场景（风控、支付、信贷、保险等），识别AI转型带来的组织变化需求\n陪伴业务负责人完成AI时代的组织调整、团队重构和人才策略升级\n从能力建设角度，支持金服在AI时代的人才结构优化与能力模型迭代\n\n2. AI时代的人才策略\n\n洞察AI对金融科技人才能力模型的重塑，推动HRBP团队自身的能力升级\n建立AI相关的招聘策略和人才画像，吸引既懂金融又理解AI应用的复合型人才\n推动内部人才在AI方向的能力转型\n\n3. 用AI手段革新组织自身工作流程和范式\n\n探索AI在HR场景中的应用（组织诊断、人才盘点、离职预警、招聘提效等）\n将AI工具融入日常HRBP工作流，提升信息获取、数据分析、报告输出的效率\n同时推动HR团队建立AI应用能力\n\n4. 组织变革推动者\n\n识别AI转型带来的组织挑战（岗位变化、能力差距、文化适配等）\n设计变革沟通和组织适配方案，降低转型阻力\n与业务负责人、HR团队协同，确保组织变革平稳落地\n\n岗位基本要求\n• 3年以上HRBP经验，有陪伴业务快速变化或转型的实战经历\n\n• 对AI有真实的好奇和实际使用习惯（不需写代码，但需要真正在用）\n\n• 理解金融业务场景优先，有科技/互联网行业HRBP经验优先\n\n• 心力强、有冲劲，能在模糊中自驱找方向\n\n• 积极主动、聪明好学、情商高，善于跨团队协同\n\n具备以下条件优先\n特别欢迎有产品或技术背景志同道合的伙伴加入——对于AI极度热衷、擅用各种AI工具、理解大模型和Agent的工程原理等\n\n岗位亮点\n1. 深度参与金服AI战略转型，站在科技与金融融合的前沿，拓展职业视野。  \n2. 与行业优秀的技术团队和业务leader紧密合作，积累高价值人脉与经验。  \n3. 提供广阔的成长空间与学习资源，支持个人在HR专业与业务理解上的双重提升。  \n4. 工作地点覆盖北京、上海，享受一线城市优质职业发展平台与福利待遇。  \n5. 扁平化管理氛围，鼓励创新与主动担当，打造高绩效、高成长的工作环境。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:2969912391","sourceKey":"meituan_social","company":"美团","title":"公共事务专家","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=2969912391&jobShareType=1","duty":"1、政策研究与分析：持续跟踪国内外人工智能相关法规、政策动态，形成系统性政策分析报告，为公司战略决策提供参考\n2、政策沟通材料撰写：起草向政府机关提交的意见建议、白皮书、政策评论等专业文件，清晰表达公司立场\n3、对外传播与倡导：代表或支持公司参与行业协会、智库论坛、学术研讨等场合，有效传递公司在AI治理领域的理念与实践\n4、跨部门协同：与法务、公共关系、产品、技术等团队紧密配合，确保政策传播内容的准确性与一致性\n5、关系维护：维护并拓展与政策研究机构、行业智库及相关媒体的合作关系。","requirements":"1、本科及以上学历，具备理工科背景且同时有法律、公共政策、新闻传播等跨学科经历者尤佳；\n2、8年以上工作经验，有政府事务、公共政策、智库研究或科技政策传播相关背景；\n3、对人工智能领域政策法规有深入了解，熟悉国内外AI技术发展趋势，能理解AI技术原理，可与技术团队顺畅沟通；\n4、有互联网科技公司政府事务、公共政策相关经验者优先；有AI/大模型产品或研究从业经历者加分；","description":"部门介绍\n公司事务平台负责构建公司的公共战略体系，助力业务可持续发展及公司对外影响力的提升。通过内外部风险管理，确保公司合规发展；通过深耕公共战略，推动内外良好沟通，连接公司发展与社会期待，助力业务高质量发展；通过管理社会责任议题、公益投入等，助力公司创造更多社会价值；同时为公司提供行政、采购等基础服务。我们坚持“懂业务、拿结果，勇担当、善协同，不唯上、只唯真”的工作理念，期待具有公共战略素养、了解公司治理逻辑的你加入！\n\n岗位职责\n1、政策研究与分析：持续跟踪国内外人工智能相关法规、政策动态，形成系统性政策分析报告，为公司战略决策提供参考\n2、政策沟通材料撰写：起草向政府机关提交的意见建议、白皮书、政策评论等专业文件，清晰表达公司立场\n3、对外传播与倡导：代表或支持公司参与行业协会、智库论坛、学术研讨等场合，有效传递公司在AI治理领域的理念与实践\n4、跨部门协同：与法务、公共关系、产品、技术等团队紧密配合，确保政策传播内容的准确性与一致性\n5、关系维护：维护并拓展与政策研究机构、行业智库及相关媒体的合作关系。\n\n岗位基本要求\n1、本科及以上学历，具备理工科背景且同时有法律、公共政策、新闻传播等跨学科经历者尤佳；\n2、8年以上工作经验，有政府事务、公共政策、智库研究或科技政策传播相关背景；\n3、对人工智能领域政策法规有深入了解，熟悉国内外AI技术发展趋势，能理解AI技术原理，可与技术团队顺畅沟通；\n4、有互联网科技公司政府事务、公共政策相关经验者优先；有AI/大模型产品或研究从业经历者加分；\n\n岗位亮点\n1、有机会成为新时代互联网平台企业公共战略工作的探索者和实践者；\n2、有空间充分释放和锻炼个人能力，宏观与微观兼具是该工作的突出亮点，有充分锻炼宏观与战略思维能力的机会。\n3、平台成长空间良好，给个人较大成长机遇。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4764861766","sourceKey":"meituan_social","company":"美团","title":"广州冻肉招商采购","city":"广州市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4764861766&jobShareType=1","duty":"1、负责冻肉品类的招商工作，包括品类策略的执行与落地；\n2、优质供应商的开发及运营管理，建立长期合作关系，确保货源品质与供给连续性；\n3、推动跨部门联动，促进销售达成，包括客户需求对齐、商品培训、联合市调、销售资源协调等；\n4、业务异常定位与改进：根据日常经营数据，定位分析业务问题，协助品类调整经营策略及制定提升计划，担当城市经营目标；","requirements":"1、大学本科以上学历，具备3年以上招商采购相关经验，熟悉冻品品类和经营链路；\n2、具备良好的谈判和沟通能力，能够与合作商建立良好的合作关系；\n3、具备较强的分析和解决问题的能力，能协调各部门事项，并有效推动工作；\n4、具备较强的团队合作意识和责任心；","description":"部门介绍\n快驴进货是美团旗下的餐饮供应链平台，帮助餐饮商户以更低成本、更高效率来获取安全可靠的食材供应，让餐饮采购更简单。快驴进货同步发展“自营+平台”的业务模式，在采购环节一方面向上游供应商直采大宗商品，另一方面引入各地批发商，助力平台伙伴共同发展；在销售环节既有自建团队进行市场、客户拓展，又帮助各地批发商拓展业务；同时自建仓储管理系统、配送网络与团队，为客户提供优质履约服务。\n截至2022年，快驴进货布局了全国41个城市，为百万家商户提供“全、省、稳、好”的餐饮供应链服务。我们拥有3000+品牌食材、超5万SKU商品、超28万商品资质，并提供源头严审核、食品安全严把关、24小时无忧售后的全面保障，实现手机下单、送货上门的高效采购模式，帮百万商家节省了采购时间与成本，助力平台伙伴共同发展，在万亿市场共享机遇。\n在这里，你将收获完善的员工发展机制及学习体系，与各界专家一起深度参与餐饮供应链业务的发展。欢迎优秀的你加入美团快驴进货，与我们一起成长，一起更好！\n\n岗位职责\n1、负责冻肉品类的招商工作，包括品类策略的执行与落地；\n2、优质供应商的开发及运营管理，建立长期合作关系，确保货源品质与供给连续性；\n3、推动跨部门联动，促进销售达成，包括客户需求对齐、商品培训、联合市调、销售资源协调等；\n4、业务异常定位与改进：根据日常经营数据，定位分析业务问题，协助品类调整经营策略及制定提升计划，担当城市经营目标；\n\n岗位基本要求\n1、大学本科以上学历，具备3年以上招商采购相关经验，熟悉冻品品类和经营链路；\n2、具备良好的谈判和沟通能力，能够与合作商建立良好的合作关系；\n3、具备较强的分析和解决问题的能力，能协调各部门事项，并有效推动工作；\n4、具备较强的团队合作意识和责任心；\n\n具备以下条件优先\n品类运营或商家运营能力；\n\n岗位亮点\n大平台，提供稳定的工作环境和良好的职业发展平台；","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4788020258","sourceKey":"meituan_social","company":"美团","title":"商家策略分析","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4788020258&jobShareType=1","duty":"1、品类策略与产品适配\n\n-基于鲜花蛋糕品类特性（节日爆发强、时效性敏感、配送场景差异化大），研究商家发单习惯与发单流程，识别品类发单痛点，推动产品迭代，持续提高品类发单适配度\n\n-制定季度/年度品类策略规划，明确核心增长方向与达成路径\n\n2、权益体系与服务包建设\n\n-设计品类专属权益体系，丰满跑腿鲜花、蛋糕合同服务包，提升商家合作粘性与经营确定性\n\n-基于商家分层（规模、品类属性、经营能力），设计差异化权益方案并推动落地\n\n3、配送体验打造\n\n-持续研究品类配送体验差（时效、货损、服务标准等）的成因，设计并验证体验打造的可行性路径\n\n-联动配送、品控等团队推动品类配送体验差的改善与标准化落地，包括节日/旺季节点（情人节、七夕、母亲节等）的体验保障规划\n\n4、数据驱动\n\n-建立品类核心指标体系（发单量、发单适配度、权益使用率、履约体验指标、商家活跃率等），定期输出经营诊断与复盘报告，定位增长瓶颈、完成异动归因\n\n-基于数据洞察持续迭代策略与资源配置，沉淀可复用的品类策略方法论，支撑跨品类横向拓展","requirements":"1、本科及以上学历，2年以上本地生活/电商/配送行业运营经验，有鲜花、烘焙、快消品类运营背景优先。\n\n2、业务敏感度高，具备优秀的分析能力，能熟练使用SQL等数据分析工具，善于从数据中发现问题并提出解决方案，文字写作功底出色是重要加分项。\n\n3、具备较强的沟通能力和团队协作能力，能够有效协调各部门资源，驱动多方团队达成共识并推进项目；\n\n4、结果导向，对业务有强烈的责任心和ownership，能在快节奏环境下工作。","description":"部门介绍\n美团配送是以科技为内核的即时物流品牌，利用高效、稳定、广阔的配送网络和前沿科技能力为各行业客户提供涵盖商流物流一体化、流量赋能、行业定制化即时配送、末端配送、前置仓等服务在内的全方位同城物流综合解决方案。\n作为科技创新和智慧物流的实践者，美团配送在人工智能（AI）、5G应用、物联网（IoT）、云计算等多维度不断探索科创蓝海，让同城物流进入数智化时代。美团配送在IoT智能设备、外卖柜、换电网络、无人配送体系等硬件设施与服务上不断推陈出新，持续优化骑手、消费者、商家体验；自研同城物流系统，通过智能分析为用户提供更便捷的生活方式，为商家提供更高效的履约服务。\n加入我们，一起把世界送到消费者手中！\n\n岗位职责\n1、品类策略与产品适配\n\n-基于鲜花蛋糕品类特性（节日爆发强、时效性敏感、配送场景差异化大），研究商家发单习惯与发单流程，识别品类发单痛点，推动产品迭代，持续提高品类发单适配度\n\n-制定季度/年度品类策略规划，明确核心增长方向与达成路径\n\n2、权益体系与服务包建设\n\n-设计品类专属权益体系，丰满跑腿鲜花、蛋糕合同服务包，提升商家合作粘性与经营确定性\n\n-基于商家分层（规模、品类属性、经营能力），设计差异化权益方案并推动落地\n\n3、配送体验打造\n\n-持续研究品类配送体验差（时效、货损、服务标准等）的成因，设计并验证体验打造的可行性路径\n\n-联动配送、品控等团队推动品类配送体验差的改善与标准化落地，包括节日/旺季节点（情人节、七夕、母亲节等）的体验保障规划\n\n4、数据驱动\n\n-建立品类核心指标体系（发单量、发单适配度、权益使用率、履约体验指标、商家活跃率等），定期输出经营诊断与复盘报告，定位增长瓶颈、完成异动归因\n\n-基于数据洞察持续迭代策略与资源配置，沉淀可复用的品类策略方法论，支撑跨品类横向拓展\n\n岗位基本要求\n1、本科及以上学历，2年以上本地生活/电商/配送行业运营经验，有鲜花、烘焙、快消品类运营背景优先。\n\n2、业务敏感度高，具备优秀的分析能力，能熟练使用SQL等数据分析工具，善于从数据中发现问题并提出解决方案，文字写作功底出色是重要加分项。\n\n3、具备较强的沟通能力和团队协作能力，能够有效协调各部门资源，驱动多方团队达成共识并推进项目；\n\n4、结果导向，对业务有强烈的责任心和ownership，能在快节奏环境下工作。\n\n岗位亮点\n1、深度参与跑腿业务品类策略，策略自主空间大，产出落地性强、影响力大，可见度高。\n2、鲜花蛋糕是跑腿特色品类（节日爆发、高时效要求、高情感价值），有机会在真实的复杂履约场景中打磨策略与产品协同能力，成长路径清晰\n3、与行业内最优秀的配送履约团队共事，氛围开放务实，团队氛围轻松，获得快速的个人成长与职业发展。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4785417824","sourceKey":"meituan_social","company":"美团","title":"开放平台API产品运营","city":"圣保罗","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4785417824&jobShareType=1","duty":"1. 主导巴西外卖服务商与连锁餐饮合作伙伴的API端到端集成策略，推动可扩展的入驻流程并确保技术无缝落地。  \n2. 深度分析连锁餐饮客户的运营需求，主动识别集成痛点，利用AI工具设计数据驱动的解决方案，显著提升商户入驻效率及API使用率。  \n3. 构建并管理本地生态合作伙伴关系，定义集成标准并推动联合创新以扩展平台能力。持续丰富与完善场景接口能力，直接对接研发团队，推动开放平台API产品落地与使用。\n4. 定义并监控服务商与商家的关键指标，通过数据洞察优化运营手册，推动服务商能力建设，提升商家平台表现。","requirements":"1. 计算机科学、信息系统等相关领域的本科及以上学历。  \n2. 至少3年产品、产品运营或平台集成经验，具备跨境或新兴市场成功案例。  \n3. 充分了解API生态、系统集成模式及大型数字平台的数据流架构。  \n4. 熟练建设与使用AI工具，有将AI嵌入运营流程并产生可量化业务影响的实战经验。  \n5. 英语流利，具备与全球技术/业务团队高效协作的书面及口头沟通能力。","description":"部门介绍\nKeeta是全球领先外卖平台美团旗下的独立品牌，肩负着“帮大家吃得更好，生活更好”的使命。依托美团深耕中国市场15年的技术与运营积淀，我们正引领全球餐饮与商品即时配送服务的创新与发展。\n\n自2023年成立以来，Keeta始终扎根社区并创造价值。我们为用户提供可靠的外卖体验，以智慧技术助餐厅提升经营效率，在为骑手拓宽收入来源的同时，也充分提供安全保障措施。基于这份多方共赢、共同成长的理念，我们的业务已从中国香港稳步拓展至中东及巴西，并持续向世界迈进。\n\n岗位职责\n1. 主导巴西外卖服务商与连锁餐饮合作伙伴的API端到端集成策略，推动可扩展的入驻流程并确保技术无缝落地。  \n2. 深度分析连锁餐饮客户的运营需求，主动识别集成痛点，利用AI工具设计数据驱动的解决方案，显著提升商户入驻效率及API使用率。  \n3. 构建并管理本地生态合作伙伴关系，定义集成标准并推动联合创新以扩展平台能力。持续丰富与完善场景接口能力，直接对接研发团队，推动开放平台API产品落地与使用。\n4. 定义并监控服务商与商家的关键指标，通过数据洞察优化运营手册，推动服务商能力建设，提升商家平台表现。\n\n岗位基本要求\n1. 计算机科学、信息系统等相关领域的本科及以上学历。  \n2. 至少3年产品、产品运营或平台集成经验，具备跨境或新兴市场成功案例。  \n3. 充分了解API生态、系统集成模式及大型数字平台的数据流架构。  \n4. 熟练建设与使用AI工具，有将AI嵌入运营流程并产生可量化业务影响的实战经验。  \n5. 英语流利，具备与全球技术/业务团队高效协作的书面及口头沟通能力。\n\n具备以下条件优先\n（1）有开放平台产品岗位经验者优先。\n（2）能简单使用葡萄牙语进行日常沟通者优先。\n\n岗位亮点\n1. 全球影响与本地深耕结合：在极具潜力与挑战的市场建设外卖基础设施，同时贡献全球平台策略。  \n2. 综合性跨域角色：在产品、产运与本地化交叉领域拥有自主权，可定义最佳实践并从零推动创新。  \n3. AI优先运营模式：探索与开创合作伙伴集成的AI应用新标准，为新兴市场树立效率标杆。  \n4. 高成长路径：加入高速发展的国际团队，获得显著的跨职能曝光与影响力发展机会。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4674646517","sourceKey":"meituan_social","company":"美团","title":"小象超市-机电设备工程师","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4674646517&jobShareType=1","duty":"1. 机电方案设计（强电主导）：负责制定门店/中央厨房的机电设备整体方案和技术标准，以强电专业为核心主导——包括配电系统（低压配电柜、回路分配、负荷计算、容量报装）、用电安全（漏电保护、接地系统、防雷）、设备用电匹配（电压等级、功率、接线制式）以及燃气、排烟新风、给排水等配套专业的集成设计；同时覆盖热食设备（炒灶、蒸烤箱、炒菜机器人等）、快餐设备和冷链设备、暖同设备的选型与用电合规审查。\n2. 强电提资与图纸会审：独立完成强电专业提资（用电容量、点位、荷载、桥架路由），主导强电图纸会审，审核设计师输出的一二次配电图纸、施工图与现场深化设计的一致性，把关设备选型与配电方案的技术匹配。\n3. 需求对接与管理：协助研发、工程和业务方梳理机电设备需求和技术参数，前置评估用电负荷与配电条件，输出专业意见，避免容量不足、回路冲突等返工问题。\n4. TCO 成本管理：建立并负责机电设备全生命周期总拥有成本（TCO）管理体系——不仅管控设备采购价格，更覆盖安装调试成本、能源消耗成本（用电/燃气功率优化）、维保维修成本、备件成本、停机损失和报废残值；通过负荷优化与功率因数管理降低电费支出，通过可靠性和易维护性设计降低运维成本，通过标准化模组化降低采购与备件成本，输出设备 TCO 测算模型和选型比价依据，为业务投资决策提供数据支撑。\n5. 标准与制度建设：负责输出机电设备引入、安装、验收、维保等全生命周期的技术标准和制度（重点包括强电施工验收规范、用电安全管理规范），对设计、工程、维保、运营等相关方开展专业培训。\n6. 质量管理：负责机电设备交付质量，制定验收标准和测试方案（含强电绝缘测试、接地测试、带载测试等专项验收），联动内部质量、工程团队及供应商资源，跟进重大质量问题闭环。\n7. 数字化与能耗管理：在方案阶段前置考虑设备数字化和智能化需求（远程监控、分项计量、能耗采集、故障告警、物联网接入等），协助业务方搭建设备运行与能耗数据看板，以实际能耗数据反哺 TCO 测算和预防性维保策略。\n8. 测试与迭代创新：结合业务需求负责机电设备迭代创新，推进打样测试、小范围试点和批量交付，跟踪投运设备的能耗表现、故障率和维保成本，形成“运行数据 → TCO 复盘 → 迭代优化”的闭环。\n9. 行业调研：调研餐饮/零售行业机电设备现状和市场情况，跟踪配电设备、节能技术（变频、余热回收、高效设备）和主流供应商动态，推进设备标准化和供应多元化，持续挖掘降本机会。","requirements":"1. 大学本科及以上学历，电气工程及其自动化、机电一体化、电气自动化、制冷与低温工程等相关专业优先，持电工证或注册电气工程师资格者优先。\n2. 5年以上连锁餐饮、中央厨房、商业厨房工程或建筑机电工程相关行业工作经验，其中 3 年以上强电专业（配电设计、施工管理或用电安全管理）实操经验。\n3. 熟悉低压配电系统设计、负荷计算、一二次图纸识读和现场施工验收，熟悉《低压配电设计规范》《民用建筑电气设计标准》等相关国家标准。\n4. 熟悉厨房设备、冷链系统及水电气配套专业的技术参数和选型逻辑，具备跨专业提资和图纸会审的统筹能力。\n5. 具备 TCO 或全生命周期成本分析能力，能独立完成设备投资测算、能耗测算和选型比价，有以数据驱动降本落地的实践案例。\n6. 具备洞察和引导设备需求的能力，能指导业务方明确需求，挖掘设备迭代创新机会点。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1. 机电方案设计（强电主导）：负责制定门店/中央厨房的机电设备整体方案和技术标准，以强电专业为核心主导——包括配电系统（低压配电柜、回路分配、负荷计算、容量报装）、用电安全（漏电保护、接地系统、防雷）、设备用电匹配（电压等级、功率、接线制式）以及燃气、排烟新风、给排水等配套专业的集成设计；同时覆盖热食设备（炒灶、蒸烤箱、炒菜机器人等）、快餐设备和冷链设备、暖同设备的选型与用电合规审查。\n2. 强电提资与图纸会审：独立完成强电专业提资（用电容量、点位、荷载、桥架路由），主导强电图纸会审，审核设计师输出的一二次配电图纸、施工图与现场深化设计的一致性，把关设备选型与配电方案的技术匹配。\n3. 需求对接与管理：协助研发、工程和业务方梳理机电设备需求和技术参数，前置评估用电负荷与配电条件，输出专业意见，避免容量不足、回路冲突等返工问题。\n4. TCO 成本管理：建立并负责机电设备全生命周期总拥有成本（TCO）管理体系——不仅管控设备采购价格，更覆盖安装调试成本、能源消耗成本（用电/燃气功率优化）、维保维修成本、备件成本、停机损失和报废残值；通过负荷优化与功率因数管理降低电费支出，通过可靠性和易维护性设计降低运维成本，通过标准化模组化降低采购与备件成本，输出设备 TCO 测算模型和选型比价依据，为业务投资决策提供数据支撑。\n5. 标准与制度建设：负责输出机电设备引入、安装、验收、维保等全生命周期的技术标准和制度（重点包括强电施工验收规范、用电安全管理规范），对设计、工程、维保、运营等相关方开展专业培训。\n6. 质量管理：负责机电设备交付质量，制定验收标准和测试方案（含强电绝缘测试、接地测试、带载测试等专项验收），联动内部质量、工程团队及供应商资源，跟进重大质量问题闭环。\n7. 数字化与能耗管理：在方案阶段前置考虑设备数字化和智能化需求（远程监控、分项计量、能耗采集、故障告警、物联网接入等），协助业务方搭建设备运行与能耗数据看板，以实际能耗数据反哺 TCO 测算和预防性维保策略。\n8. 测试与迭代创新：结合业务需求负责机电设备迭代创新，推进打样测试、小范围试点和批量交付，跟踪投运设备的能耗表现、故障率和维保成本，形成“运行数据 → TCO 复盘 → 迭代优化”的闭环。\n9. 行业调研：调研餐饮/零售行业机电设备现状和市场情况，跟踪配电设备、节能技术（变频、余热回收、高效设备）和主流供应商动态，推进设备标准化和供应多元化，持续挖掘降本机会。\n\n岗位基本要求\n1. 大学本科及以上学历，电气工程及其自动化、机电一体化、电气自动化、制冷与低温工程等相关专业优先，持电工证或注册电气工程师资格者优先。\n2. 5年以上连锁餐饮、中央厨房、商业厨房工程或建筑机电工程相关行业工作经验，其中 3 年以上强电专业（配电设计、施工管理或用电安全管理）实操经验。\n3. 熟悉低压配电系统设计、负荷计算、一二次图纸识读和现场施工验收，熟悉《低压配电设计规范》《民用建筑电气设计标准》等相关国家标准。\n4. 熟悉厨房设备、冷链系统及水电气配套专业的技术参数和选型逻辑，具备跨专业提资和图纸会审的统筹能力。\n5. 具备 TCO 或全生命周期成本分析能力，能独立完成设备投资测算、能耗测算和选型比价，有以数据驱动降本落地的实践案例。\n6. 具备洞察和引导设备需求的能力，能指导业务方明确需求，挖掘设备迭代创新机会点。\n\n具备以下条件优先\n有前置仓、商超冷链设备方案编制、施工管理、运维经验优先。\n\n岗位亮点\n可与一线厂商进行技术交流，并深入业务场景中实践和探索研究。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4785617188","sourceKey":"meituan_social","company":"美团","title":"小象超市-大连仓物资主管","city":"大连市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4785617188&jobShareType=1","duty":"1、处理仓储物资管理事务、执行和落实相关规则制度\n2、每日跟进物资周转运营以及盘点情况，保障仓储物资正常运营\n3、定期抽查账物相符情况、监督数据系统录入与手工登记情况、确保仓储系统和台账登记数据准确\n4、对接总部、大区、仓储上下游环节处理物资问题","requirements":"1、大专以上学历、物流、运输仓储等相关专业优先\n2、有较强的数据分析、逻辑判断能力、组织协调、沟通表达及执行力度强、具有团队合作意识和一定危机处理能力\n3、有5年以上的仓储物流管理经验\n4、熟悉电子商务仓储管理、熟悉仓储物流运营模式、有熟练的的操作管理经验","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1、处理仓储物资管理事务、执行和落实相关规则制度\n2、每日跟进物资周转运营以及盘点情况，保障仓储物资正常运营\n3、定期抽查账物相符情况、监督数据系统录入与手工登记情况、确保仓储系统和台账登记数据准确\n4、对接总部、大区、仓储上下游环节处理物资问题\n\n岗位基本要求\n1、大专以上学历、物流、运输仓储等相关专业优先\n2、有较强的数据分析、逻辑判断能力、组织协调、沟通表达及执行力度强、具有团队合作意识和一定危机处理能力\n3、有5年以上的仓储物流管理经验\n4、熟悉电子商务仓储管理、熟悉仓储物流运营模式、有熟练的的操作管理经验\n\n岗位亮点\n大公司，业务在高速发展中，福利好，发展空间大","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4786959491","sourceKey":"meituan_social","company":"美团","title":"Staff Software Engineer","city":"旧金山/西雅图","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4786959491&jobShareType=1","duty":"Collaborate with cross-functional teams, including product, design, operations, and infrastructure, to translate requirements into technical plans and deliver application features.\nDrive technical projects from planning through launch by defining milestones, managing dependencies, resolving blockers, and communicating progress.\nTake a hands-on role in designing, coding, testing, debugging, and deploying software.\nBuild and maintain user interfaces and backend services using modern programming languages and frameworks.\nMake practical design decisions that balance delivery timelines, performance, scalability, and maintainability.\nInvestigate and resolve technical issues, including production bugs and performance bottlenecks.\nImprove code quality through code reviews, automated testing, refactoring, and targeted technical debt reduction.\nOwn key components and features end to end, including implementation, integration, release, and ongoing operation.\nProvide practical technical guidance to teammates and help resolve implementation challenges.","requirements":"Bachelor’s degree in Computer Science, Computer Engineering, or a related technical field, or equivalent practical experience.\n3+ years of relevant software development experience.\nStrong programming skills in at least one relevant language and hands-on experience building and shipping software.\nExperience driving technical projects or substantial features from requirements through delivery.\nExperience with software design, testing, debugging, and performance optimization.\nAbility to work independently, manage technical dependencies, and collaborate effectively across teams.","description":"部门介绍\n基础研发平台是美团的核心技术平台，立足于“零售+科技”的战略定位，通过打造人工智能、大数据、云计算、安全等核心技术能力，以及研发效能平台、企业应用平台等公共服务，为业务提供稳定安全、扩展易用、技术领先的平台技术和产品服务。\n在这里，我们会参与到最前沿的技术研发和探索；能够接触超规模集群、海量数据，挑战高复杂业务场景，有机会与业界一流的工程师一起并肩前行。\n在这里，我们有超强的技术氛围，持续向社区贡献业界实践，加速行业技术发展；我们有完善的互联网学习生态圈，重视底层逻辑和方法论，助力职业生涯的非线性成长。\n真诚地邀请你，和我们一起驱动技术发展，创造行业价值。\n\n岗位职责\nCollaborate with cross-functional teams, including product, design, operations, and infrastructure, to translate requirements into technical plans and deliver application features.\nDrive technical projects from planning through launch by defining milestones, managing dependencies, resolving blockers, and communicating progress.\nTake a hands-on role in designing, coding, testing, debugging, and deploying software.\nBuild and maintain user interfaces and backend services using modern programming languages and frameworks.\nMake practical design decisions that balance delivery timelines, performance, scalability, and maintainability.\nInvestigate and resolve technical issues, including production bugs and performance bottlenecks.\nImprove code quality through code reviews, automated testing, refactoring, and targeted technical debt reduction.\nOwn key components and features end to end, including implementation, integration, release, and ongoing operation.\nProvide practical technical guidance to teammates and help resolve implementation challenges.\n\n岗位基本要求\nBachelor’s degree in Computer Science, Computer Engineering, or a related technical field, or equivalent practical experience.\n3+ years of relevant software development experience.\nStrong programming skills in at least one relevant language and hands-on experience building and shipping software.\nExperience driving technical projects or substantial features from requirements through delivery.\nExperience with software design, testing, debugging, and performance optimization.\nAbility to work independently, manage technical dependencies, and collaborate effectively across teams.\n\n具备以下条件优先\nSeattle and San Francisco are the preferred work locations.\n\n岗位亮点\nThe role provides extensive room for growth through hands-on project ownership, cross-functional collaboration, and progressively broader technical responsibilities.","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4786709585","sourceKey":"meituan_social","company":"美团","title":"Principal Software Engineer","city":"西雅图","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4786709585&jobShareType=1","duty":"Responsibilities\n\nCollaborate with cross-functional teams (product, design, operations, infrastructure) to build innovative application experiences\nImplement custom user interfaces using latest programming techniques and technologies\nAnalyze and optimize code for quality, efficiency, and performance, and provide feedback to peers during code reviews\nSet direction and goals for teams, lead major initiatives, provide technical guidance and mentorship to peers, and help onboard new team members\nArchitect efficient and scalable systems that drive complex applications\nIdentify and resolve performance and scalability issues, and drive large efforts to reduce technical debt\nWork on a variety of coding languages and technologies\nEstablish ownership of components, features, or systems with expert end-to-end understanding","requirements":"Demonstrated experience driving change within an organization and leading complex technical projects\nMaster's degree in Computer Science, Computer Engineering, relevant technical field, or equivalent practical experience\n5+ years of programming experience in a relevant language OR 3+ years experience with a PhD\nExperience utilizing data and analysis to explain technical problems and provide detailed feedback and solutions","description":"部门介绍\n基础研发平台是美团的核心技术平台，立足于“零售+科技”的战略定位，通过打造人工智能、大数据、云计算、安全等核心技术能力，以及研发效能平台、企业应用平台等公共服务，为业务提供稳定安全、扩展易用、技术领先的平台技术和产品服务。\n在这里，我们会参与到最前沿的技术研发和探索；能够接触超规模集群、海量数据，挑战高复杂业务场景，有机会与业界一流的工程师一起并肩前行。\n在这里，我们有超强的技术氛围，持续向社区贡献业界实践，加速行业技术发展；我们有完善的互联网学习生态圈，重视底层逻辑和方法论，助力职业生涯的非线性成长。\n真诚地邀请你，和我们一起驱动技术发展，创造行业价值。\n\n岗位职责\nResponsibilities\n\nCollaborate with cross-functional teams (product, design, operations, infrastructure) to build innovative application experiences\nImplement custom user interfaces using latest programming techniques and technologies\nAnalyze and optimize code for quality, efficiency, and performance, and provide feedback to peers during code reviews\nSet direction and goals for teams, lead major initiatives, provide technical guidance and mentorship to peers, and help onboard new team members\nArchitect efficient and scalable systems that drive complex applications\nIdentify and resolve performance and scalability issues, and drive large efforts to reduce technical debt\nWork on a variety of coding languages and technologies\nEstablish ownership of components, features, or systems with expert end-to-end understanding\n\n岗位基本要求\nDemonstrated experience driving change within an organization and leading complex technical projects\nMaster's degree in Computer Science, Computer Engineering, relevant technical field, or equivalent practical experience\n5+ years of programming experience in a relevant language OR 3+ years experience with a PhD\nExperience utilizing data and analysis to explain technical problems and provide detailed feedback and solutions\n\n具备以下条件优先\nPhD in Computer Science or a related technical field\nExperience with frameworks like TensorFlow, PyTorch, or Scikit-learn\nDemonstrated grasp of data structures and algorithms, including graph theory and optimization techniques\nKnowledge of NLP techniques, including text preprocessing, tokenization, and sentiment analysis\nDemonstrated ability to integrate AI tools to optimize/redesign workflows and drive measurable impact (e.g., efficiency gains, quality improvements)\nSeattle is the preferred work location\n\n岗位亮点\nThis Architect role offers the opportunity to shape the technical roadmap and scalable architecture of the division’s platforms and products. It draws on the beneficiary’s experience with similar software products to guide cross-team engineering decisions, solve complex technical challenges, and accelerate product delivery.","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4589013137","sourceKey":"meituan_social","company":"美团","title":"国际支付-商务合作经理（AI金融生态拓展与赋能）","city":"上海市/北京市/利雅得","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4589013137&jobShareType=1","duty":"1、在香港、中东、拉美等核心市场建立稳固的金融机构商务关系，维护与银行、卡组织、收单公司的长期合作\n2、基于业务目标与支付行业上下游机构进行有效沟通和谈判，以最优条件达成合作；结合 AI Agent 工具进行谈判策略分析与材料准备，提升商务效率\n3、持续关注 AI 支付领域的行业动态与技术趋势，识别新型合作机会（如 AI 收单、智能支付路由、B 端 AI Agent 支付等），推动美团国际支付在 AI 时代的前瞻布局\n4、建立合作机构与国际支付团队间的长期高效沟通机制；借助 RAG 知识库构建与 AI Agent 自动化工具，推动合作伙伴关系管理的智能化提升\n5、分析市场需求和竞争情况，制定相应商务合作策略；善用 AI 工具进行市场信息整合与洞察","requirements":"1、AI能力要求：具备对 AI 支付领域的行业认知，了解 AI Agent 收单、智能支付路由、大模型在金融场景应用等前沿趋势；能在日常工作中熟练运用 AI Agent 提升效率，包括但不限于 RAG 知识库构建、Prompt Engineering、自动化工作流搭建等；有 AI 工具深度使用经验者优先\n2、专业经验：5年以上国际支付行业商务经验，大学本科及以上，深入理解国际支付底层商业逻辑\n3、核心能力：熟悉中东或拉美支付市场，在本地具备银行、卡组和收单机构资源；熟练英语沟通能力；具备强大的商业逻辑及敏锐的商业洞察力，与合作伙伴共同寻求双赢的创新和合作机会\n4、软性素质：学习能力强，能快速适应变化，在高强度工作环境下找到最有效解决方案；优秀的沟通表达与跨部门协调能力；务实、结果导向\n5、英语能作为工作语言","description":"部门介绍\n美团金融服务平台成立于2016年，以“场景+金融”模式，携手合作伙伴构建开放生态，为美团平台用户和商户提供底层账户、支付通道、信贷、保险和理财等金融解决方案。我们致力于以科技为核心，助力金融机构打通金融普惠“最后一公里”。我们期待与大家共同完成每一件平凡而卓越的事情，一起为用户提供优质的产品体验，守护用户的资金安全，让生活变得更美好。\n\n岗位职责\n1、在香港、中东、拉美等核心市场建立稳固的金融机构商务关系，维护与银行、卡组织、收单公司的长期合作\n2、基于业务目标与支付行业上下游机构进行有效沟通和谈判，以最优条件达成合作；结合 AI Agent 工具进行谈判策略分析与材料准备，提升商务效率\n3、持续关注 AI 支付领域的行业动态与技术趋势，识别新型合作机会（如 AI 收单、智能支付路由、B 端 AI Agent 支付等），推动美团国际支付在 AI 时代的前瞻布局\n4、建立合作机构与国际支付团队间的长期高效沟通机制；借助 RAG 知识库构建与 AI Agent 自动化工具，推动合作伙伴关系管理的智能化提升\n5、分析市场需求和竞争情况，制定相应商务合作策略；善用 AI 工具进行市场信息整合与洞察\n\n岗位基本要求\n1、AI能力要求：具备对 AI 支付领域的行业认知，了解 AI Agent 收单、智能支付路由、大模型在金融场景应用等前沿趋势；能在日常工作中熟练运用 AI Agent 提升效率，包括但不限于 RAG 知识库构建、Prompt Engineering、自动化工作流搭建等；有 AI 工具深度使用经验者优先\n2、专业经验：5年以上国际支付行业商务经验，大学本科及以上，深入理解国际支付底层商业逻辑\n3、核心能力：熟悉中东或拉美支付市场，在本地具备银行、卡组和收单机构资源；熟练英语沟通能力；具备强大的商业逻辑及敏锐的商业洞察力，与合作伙伴共同寻求双赢的创新和合作机会\n4、软性素质：学习能力强，能快速适应变化，在高强度工作环境下找到最有效解决方案；优秀的沟通表达与跨部门协调能力；务实、结果导向\n5、英语能作为工作语言\n\n具备以下条件优先\n1、熟悉葡萄牙语、西班牙语等小语种者优先\n2、拥有收单、信用卡、信贷、BNPL等零售金融领域经验者优先\n\n岗位亮点\n1、AI支付前沿阵地：直接参与 AI 支付领域的商务布局与生态搭建，有机会接触 AI 原生支付机构、大模型厂商等新型合作伙伴，站在支付行业 AI 化变革的最前线\n2、业务快速发展：美团出海核心战略，Keeta已覆盖香港、中东、巴西等市场，国际支付处于高速增长阶段，平台资源充足","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4592399602","sourceKey":"meituan_social","company":"美团","title":"信贷政府事务专家-消保方向（AI工具驱动）","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4592399602&jobShareType=1","duty":"1.政府事务与外部对接（主责）：与金监总局、人民银行等金融消费者权益主管部门的常态化沟通、拜访策划与关系维护；对接中互金协会、中贷协等行业自律组织，参与行业标准制定、信息披露及评优评先等事务；消保方向重大事项的对上汇报、问询响应与应对策略制定。\n\n2.金监总局消保中心专项对接：负责12378专线日常处置、报表及报告撰写；推动AI辅助报告生成，提升沟通材料的准备效率和质量。\n\n3.消保内部PMO：统筹跨部门消保整改协调，主持体验双周会并追踪整改事项落地；汇总全口径消保数据并输出消保管理月报；借助AI工具实现整改台账自动更新、月报自动生成和逾期预警。\n\n4.AI工具落地：主导AI工具在报告撰写、客诉数据归因分析、整改追踪等场景的实际落地，持续沉淀提示词和工作流，提升团队整体AI应用水位。","requirements":"1、熟知消保合规政策和管理措施，具有相关主管部门资源，能够与对外保持良好沟通，及时准确解读合规政策趋势和要点，为业务稳健发展提出消保合规解决方案，做好消保日常事务。\n2.AI能力要求：能熟练使用主流AI工具辅助报告撰写、数据整理和信息汇总；有意愿和能力探索AI在消保运营场景的落地应用。\n3.专业经验：熟悉信贷、支付、保险业务消保管理体系，具有较强的消保管理专业能力，了解市场和同业消保工作良好做法，金融科技/银行/互联网金融/政府机构背景优先。\n3.核心能力：跨部门协调推动能力强，擅长结构化信息汇总与报告撰写；熟悉消费金融管理体系（金监总局、人行、网信办等），消保项目经验者优先；数据处理能力扎实，能独立完成多口径数据汇总分析；具有较强的沟通协作能力，能够承担重要事项对外沟通协调任务，为业务发展创造良好的外部环境；\n4.软性素质：高度自驱，能在模糊和多变环境中独立推进工作；沟通协调能力强，能有效推动跨部门协作；细致严谨，对数据准确性和时效性有高要求。","description":"部门介绍\n美团金融服务平台成立于2016年，以“场景+金融”模式，携手合作伙伴构建开放生态，为美团平台用户和商户提供底层账户、支付通道、信贷、保险和理财等金融解决方案。我们致力于以科技为核心，助力金融机构打通金融普惠“最后一公里”。我们期待与大家共同完成每一件平凡而卓越的事情，一起为用户提供优质的产品体验，守护用户的资金安全，让生活变得更美好。\n\n岗位职责\n1.政府事务与外部对接（主责）：与金监总局、人民银行等金融消费者权益主管部门的常态化沟通、拜访策划与关系维护；对接中互金协会、中贷协等行业自律组织，参与行业标准制定、信息披露及评优评先等事务；消保方向重大事项的对上汇报、问询响应与应对策略制定。\n\n2.金监总局消保中心专项对接：负责12378专线日常处置、报表及报告撰写；推动AI辅助报告生成，提升沟通材料的准备效率和质量。\n\n3.消保内部PMO：统筹跨部门消保整改协调，主持体验双周会并追踪整改事项落地；汇总全口径消保数据并输出消保管理月报；借助AI工具实现整改台账自动更新、月报自动生成和逾期预警。\n\n4.AI工具落地：主导AI工具在报告撰写、客诉数据归因分析、整改追踪等场景的实际落地，持续沉淀提示词和工作流，提升团队整体AI应用水位。\n\n岗位基本要求\n1、熟知消保合规政策和管理措施，具有相关主管部门资源，能够与对外保持良好沟通，及时准确解读合规政策趋势和要点，为业务稳健发展提出消保合规解决方案，做好消保日常事务。\n2.AI能力要求：能熟练使用主流AI工具辅助报告撰写、数据整理和信息汇总；有意愿和能力探索AI在消保运营场景的落地应用。\n3.专业经验：熟悉信贷、支付、保险业务消保管理体系，具有较强的消保管理专业能力，了解市场和同业消保工作良好做法，金融科技/银行/互联网金融/政府机构背景优先。\n3.核心能力：跨部门协调推动能力强，擅长结构化信息汇总与报告撰写；熟悉消费金融管理体系（金监总局、人行、网信办等），消保项目经验者优先；数据处理能力扎实，能独立完成多口径数据汇总分析；具有较强的沟通协作能力，能够承担重要事项对外沟通协调任务，为业务发展创造良好的外部环境；\n4.软性素质：高度自驱，能在模糊和多变环境中独立推进工作；沟通协调能力强，能有效推动跨部门协作；细致严谨，对数据准确性和时效性有高要求。\n\n具备以下条件优先\n具有金监总局、人行、证监会等政府部门，银行等持牌金融机构总部或互联网平台企业消保工作经历。\n\n岗位亮点\n1.AI机会：在消保运营这一高频、信息密集型领域，从0到1探索AI工具落地，有机会主导消保月报自动化、整改追踪智能化等实际项目，积累AI增强型运营管理的前沿实践。\n2.业务基本盘：美团金融服务平台体量大、内部资源丰富，消保工作直接对接政府部门，视野和资源优于同业大多数同等岗位；随外部环境持续加码，消保专业能力的市场价值持续提升。\n3.成长与资源：直接汇报团队负责人，决策链短，参与感强；团队扁平高效，鼓励用AI工具替代重复劳动；有机会参与跨政府层级的对外协调，快速积累高层对接工作。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4784218946","sourceKey":"meituan_social","company":"美团","title":"小象超市-大连仓收退主管","city":"大连市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4784218946&jobShareType=1","duty":"1.负责做好仓库逆向收货的处理及跟踪。\n2.负责供应商预约的合理性，提高员工的工作效率。\n3.监督各项管理制的执行，检查和审核员工的工作进度，负责员工的考勤及绩效考核。\n4.对员工进行必要的岗位知识培训，同时对员工工作结果进行评价。\n5.周盘、月盘保障库存准确。\n6.库存商品小区管理。","requirements":"1.专科及以上学历，物流管理等相关专业优先。\n2.3年及以上物流、仓储相关领域管理工作经验优先。\n3.较好的沟通能力、执行力，熟练使用电脑，熟悉办公软件。\n4.熟悉物流、仓储业务流程，有零售仓储管理工作经验优先。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1.负责做好仓库逆向收货的处理及跟踪。\n2.负责供应商预约的合理性，提高员工的工作效率。\n3.监督各项管理制的执行，检查和审核员工的工作进度，负责员工的考勤及绩效考核。\n4.对员工进行必要的岗位知识培训，同时对员工工作结果进行评价。\n5.周盘、月盘保障库存准确。\n6.库存商品小区管理。\n\n岗位基本要求\n1.专科及以上学历，物流管理等相关专业优先。\n2.3年及以上物流、仓储相关领域管理工作经验优先。\n3.较好的沟通能力、执行力，熟练使用电脑，熟悉办公软件。\n4.熟悉物流、仓储业务流程，有零售仓储管理工作经验优先。\n\n岗位亮点\n1. 提供完善的培训体系与职业发展通道，助力个人成长。\n2. 团队规模稳定，工作氛围积极，管理扁平化。\n3. 享有具有竞争力的薪酬福利与绩效奖金。\n4. 参与公司重点仓储项目，积累大型仓储管理经验。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4784334680","sourceKey":"meituan_social","company":"美团","title":"小象超市-大连仓生产主管","city":"大连市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4784334680&jobShareType=1","duty":"1.负责仓内生产管理工作。并对人效，质量和履约负责。\n2.持续员工培训，并监督有效执行。\n3.横向部门沟通协调工作。\n4.不断优化现有作业流程。提高人效.减低差异。\n5.仓内员工的正负激励措施及执行。\n6.现场6S管理。\n7.直接上级安排的其它工作。","requirements":"具备较强团队管理能力，激发员工工作热情。\n熟悉仓库管理各操作流程。\n熟练使用仓库WMS操作系统和办公软件。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1.负责仓内生产管理工作。并对人效，质量和履约负责。\n2.持续员工培训，并监督有效执行。\n3.横向部门沟通协调工作。\n4.不断优化现有作业流程。提高人效.减低差异。\n5.仓内员工的正负激励措施及执行。\n6.现场6S管理。\n7.直接上级安排的其它工作。\n\n岗位基本要求\n具备较强团队管理能力，激发员工工作热情。\n熟悉仓库管理各操作流程。\n熟练使用仓库WMS操作系统和办公软件。\n\n岗位亮点\n团队稳定，大平台，晋升空间大，模块仓库，便于个人能力发挥。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4783988949","sourceKey":"meituan_social","company":"美团","title":"质量主管","city":"广州市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4783988949&jobShareType=1","duty":"1. 负责仓储物流环节的质量管理工作，制定并执行质量控制标准和流程。  \n2. 监督日常操作中的质量合规性，及时发现并纠正质量问题。  \n3. 组织质量培训，提升团队成员的质量意识和操作规范性。  \n4. 主导质量异常事件的调查与分析，推动改进措施落地。  \n5. 定期输出质量报告，向上级汇报质量状况及改进建议。","requirements":"1. 大学专科及以上学历，物流、供应链或相关专业优先。  \n2. 具备3年以上物流或仓储质量管理相关工作经验。  \n3. 熟悉质量管理体系及常用工具，具备较强的数据分析能力。  \n4. 具备良好的沟通协调能力，能够有效带领10人团队开展工作。  \n5. 工作认真负责，具备较强的执行力和问题解决能力。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1. 负责仓储物流环节的质量管理工作，制定并执行质量控制标准和流程。  \n2. 监督日常操作中的质量合规性，及时发现并纠正质量问题。  \n3. 组织质量培训，提升团队成员的质量意识和操作规范性。  \n4. 主导质量异常事件的调查与分析，推动改进措施落地。  \n5. 定期输出质量报告，向上级汇报质量状况及改进建议。\n\n岗位基本要求\n1. 大学专科及以上学历，物流、供应链或相关专业优先。  \n2. 具备3年以上物流或仓储质量管理相关工作经验。  \n3. 熟悉质量管理体系及常用工具，具备较强的数据分析能力。  \n4. 具备良好的沟通协调能力，能够有效带领10人团队开展工作。  \n5. 工作认真负责，具备较强的执行力和问题解决能力。\n\n岗位亮点\n1. 工作地点位于广州市，交通便利，办公环境优良。  \n2. 提供完善的培训体系和职业发展通道。  \n3. 团队氛围积极，注重员工成长与能力提升。  \n4. 享有具有竞争力的薪酬福利和绩效奖励机制。  \n5. 参与公司重点项目，积累丰富的质量管理实战经验。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4686031628","sourceKey":"meituan_social","company":"美团","title":"快乐猴-规划策略TL","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4686031628&jobShareType=1","duty":"1. 制定门店选址核心策略与中长期发展规划，支撑公司区域扩张与业务增长目标。  \n2. 构建并持续优化选址方法论体系，推动数据驱动与AI模型在选址决策中的应用。  \n3. 带领10人团队开展商圈分析、客群画像、竞争格局等深度研究，输出高价值策略建议。  \n4. 协同营运、设计、工程等前台与中台部门，确保选址策略高效落地与闭环反馈。  \n5. 跟踪门店运营表现，建立评估机制，通过数据分析反哺策略迭代与模型优化。","requirements":"1. 大学本科及以上学历，城市规划、地理信息系统、统计学、数据科学或相关专业优先。  \n2. 具备5年以上零售、连锁品牌或商业地产中台策略经验，有团队管理经验。  \n3. 精通数据分析与建模，熟悉AI在商业选址中的应用场景，具备相关项目经验者优先。  \n4. 熟练使用各种AI工具，具备较强的逻辑思维与抽象建模能力。  \n5. 具备优秀的跨部门沟通与策略推动能力，能独立主导复杂项目并输出专业成果。","description":"部门介绍\n快乐猴是美团自营社区超市，依托自有供应链和门店管理体系，聚焦家庭用户的三餐所需，为消费者提供高质价比的食杂商品。快乐猴以数字化能力与科学品控为基础，不断满足消费者对“省”和“便利”的需求。\n\n岗位职责\n1. 制定门店选址核心策略与中长期发展规划，支撑公司区域扩张与业务增长目标。  \n2. 构建并持续优化选址方法论体系，推动数据驱动与AI模型在选址决策中的应用。  \n3. 带领10人团队开展商圈分析、客群画像、竞争格局等深度研究，输出高价值策略建议。  \n4. 协同营运、设计、工程等前台与中台部门，确保选址策略高效落地与闭环反馈。  \n5. 跟踪门店运营表现，建立评估机制，通过数据分析反哺策略迭代与模型优化。\n\n岗位基本要求\n1. 大学本科及以上学历，城市规划、地理信息系统、统计学、数据科学或相关专业优先。  \n2. 具备5年以上零售、连锁品牌或商业地产中台策略经验，有团队管理经验。  \n3. 精通数据分析与建模，熟悉AI在商业选址中的应用场景，具备相关项目经验者优先。  \n4. 熟练使用各种AI工具，具备较强的逻辑思维与抽象建模能力。  \n5. 具备优秀的跨部门沟通与策略推动能力，能独立主导复杂项目并输出专业成果。\n\n岗位亮点\n1. 主导中台核心策略建设，深度参与公司战略决策，影响力覆盖全国业务布局。  \n2. 聚焦AI与数据智能在选址领域的创新应用，推动技术驱动业务升级。  \n3. 拥有高自主性的工作环境与资源支持，鼓励前沿探索与跨领域协作。  \n4. 工作地点位于北京核心区域，团队专业度高，协作氛围开放高效。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4754069268","sourceKey":"meituan_social","company":"美团","title":"政府事务经理-陕西片区","city":"西安市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4754069268&jobShareType=1","duty":"1.负责陕西省骑行业务政府事务工作，与政府各级主管部门保持良好沟通合作关系。\n2.结合当地政府在公共交通、城市管理等相关领域政策法规和管理要求，制定公司在当地政府关系工作的策略和计划，并操作执行。\n3.掌握出现领域行业信息、企业动态，推动与本地相关企业、协会等机构合作。\n4.做好骑行业务拓展，并为业务落地及健康发展取得良好的外部环境。\n5.完成公司交办的其他工作。","requirements":"1.大学本科及以上学历，政治、法律等相关专业优先。\n2.五年以上政府事务管理经验，熟悉陕西省及西安市政府相关政策法规，具备丰富的政府关系处理经验。\n3.具备较强的沟通协调能力和团队管理能力，有较强的应变能力。\n4.具备良好的文字表达能力和文件处理能力，熟练使用办公软件。","description":"部门介绍\n美团骑行事业部在全国各个城市开展美团单车、电单车业务，提供绿色、便捷的共享出行服务，是美团出行板块重要的组成部分。我们力求为城市可持续发展提供低碳智能的解决方案，通过技术创新和硬件升级，不断优化全流程骑行体验，为低碳出行提供更好的服务。其中，美团单车旨在为城市居民提供通勤接驳服务，满足用户短途接驳出行需求；美团电单车则满足用户中短途多场景低碳出行需求。\n我们有开放的工作氛围，也有充满韧劲和创造力，心系低碳出行的伙伴。加入我们，一起为用户创造更好的出行体验。\n\n岗位职责\n1.负责陕西省骑行业务政府事务工作，与政府各级主管部门保持良好沟通合作关系。\n2.结合当地政府在公共交通、城市管理等相关领域政策法规和管理要求，制定公司在当地政府关系工作的策略和计划，并操作执行。\n3.掌握出现领域行业信息、企业动态，推动与本地相关企业、协会等机构合作。\n4.做好骑行业务拓展，并为业务落地及健康发展取得良好的外部环境。\n5.完成公司交办的其他工作。\n\n岗位基本要求\n1.大学本科及以上学历，政治、法律等相关专业优先。\n2.五年以上政府事务管理经验，熟悉陕西省及西安市政府相关政策法规，具备丰富的政府关系处理经验。\n3.具备较强的沟通协调能力和团队管理能力，有较强的应变能力。\n4.具备良好的文字表达能力和文件处理能力，熟练使用办公软件。\n\n岗位亮点\n1.有机会与陕西省及西安市政府部门高层建立良好合作关系。\n2.参与公司政府事务工作，为公司发展提供重要支持。\n3.有较大的发展空间和晋升机会，是一份具有挑战性和发展潜力的工作。\n4.公司Ai工具多多帮你从事务工作中解放出来。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:2318526709","sourceKey":"meituan_social","company":"美团","title":"大模型推理服务工程师","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=2318526709&jobShareType=1","duty":"岗位职责:\n1.负责AI Agent核心架构设计与开发，不断优化和提升大模型Agent的技术框架，构建高可用、低延时的分布式系统；\n2.开发多智能体协作系统，实现复杂场景下的任务拆解、工具调用，包括DeepResearch、通用智能体等Multi Agent；\n3.关注公司内外AI Agent领域的技术发展趋势，积极开展前瞻性技术研究，探索将新技术和理念融入现有系统的可行性，持续推动公司Agent技术的创新升级与竞争力提升；\n4.与算法团队紧密配合，推动LLM、RAG等技术与工程系统的深度集成，持续迭代项目能力，提高服务质量。","requirements":"岗位要求:\n1.具备5年以上Java/Python开发经验，精通分布式系统开发与性能优化；\n2.有AI应用框架或平台研发经验，熟悉大语言模型应用开发流程，了解LangChain、Auto GPT等主流框架，掌握Prompt工程、RAG及大模型工具集成与调用；\n3.拥有大模型应用开发或相关人工智能项目经验，优先有对话系统、搜索推荐系统、大规模机器学习系统等领域经验者；\n4.对新技术充满好奇心和敏锐度，具备出色的复杂问题分析与解决能力，拥有良好的沟通能力和团队协作精神，能够高效推动跨团队合作。","description":"部门介绍\n基础研发平台是美团的核心技术平台，立足于“零售+科技”的战略定位，通过打造人工智能、大数据、云计算、安全等核心技术能力，以及研发效能平台、企业应用平台等公共服务，为业务提供稳定安全、扩展易用、技术领先的平台技术和产品服务。\n在这里，我们会参与到最前沿的技术研发和探索；能够接触超规模集群、海量数据，挑战高复杂业务场景，有机会与业界一流的工程师一起并肩前行。\n在这里，我们有超强的技术氛围，持续向社区贡献业界实践，加速行业技术发展；我们有完善的互联网学习生态圈，重视底层逻辑和方法论，助力职业生涯的非线性成长。\n真诚地邀请你，和我们一起驱动技术发展，创造行业价值。\n\n岗位职责\n岗位职责:\n1.负责AI Agent核心架构设计与开发，不断优化和提升大模型Agent的技术框架，构建高可用、低延时的分布式系统；\n2.开发多智能体协作系统，实现复杂场景下的任务拆解、工具调用，包括DeepResearch、通用智能体等Multi Agent；\n3.关注公司内外AI Agent领域的技术发展趋势，积极开展前瞻性技术研究，探索将新技术和理念融入现有系统的可行性，持续推动公司Agent技术的创新升级与竞争力提升；\n4.与算法团队紧密配合，推动LLM、RAG等技术与工程系统的深度集成，持续迭代项目能力，提高服务质量。\n\n岗位基本要求\n岗位要求:\n1.具备5年以上Java/Python开发经验，精通分布式系统开发与性能优化；\n2.有AI应用框架或平台研发经验，熟悉大语言模型应用开发流程，了解LangChain、Auto GPT等主流框架，掌握Prompt工程、RAG及大模型工具集成与调用；\n3.拥有大模型应用开发或相关人工智能项目经验，优先有对话系统、搜索推荐系统、大规模机器学习系统等领域经验者；\n4.对新技术充满好奇心和敏锐度，具备出色的复杂问题分析与解决能力，拥有良好的沟通能力和团队协作精神，能够高效推动跨团队合作。\n\n岗位亮点\n岗位亮点:\n1.你将加入优秀的团队，一起成长：团队高阶研发密度大，汇聚行业大牛，分享交流活动多； \n2.你将负责前沿技术的探究：和迅速发展的大模型行业一起成长，未来拥有广阔的应用前景； \n3.你将拥有快速成长的空间，一起见证技术落地的喜悦，部门业务处于快速发展阶段，应用场景广泛，业务落地场景丰富，复杂度高，挑战性大； \n4.你将拥有更广阔的视野：有行业影响力的培训和学习交流机会、参加国际优质学术会议等。\n具备以下优先:\n1.有技术钻研精神，熟悉主流大模型架构（如Transformer，Bert等），理解其底层原理（自注意力机制、位置编码、训练和推理优化等）者优先；\n2.有较强的逻辑思维能力，善于分析、归纳、描述、沟通、和解决问题。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4784285886","sourceKey":"meituan_social","company":"美团","title":"快乐猴-选址拓展经理-华东3","city":"杭州市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4784285886&jobShareType=1","duty":"1.负责美团食杂零售快乐猴业务的选址工作，对所管辖区域的新店选址做现场考察、商圈评估及市场调研工作；\n2.根据本地市场的特点以及公司开店的要求制定战区规划与开店策略；\n3.负责项目的商务谈判、合同谈判、基本工程条件的谈判以及风险预估；\n4.利用相关工具对预选址进行详细分析，做出逻辑清晰、条理分明的选址报告；\n5.负责跟进项目签约、接场、开业的流程，具备处理门店开业前施工过程中遇到的各种问题的能力。","requirements":"1.5年及以上零售拓展行业的相关工作经验，具备商超便利店、街边及商场店铺选址工作经验者优先；\n2.较强的专业能力，能够独立完成项目的评估、选址、谈判、签约及进场工作，具备制定战区图的能力；\n3.熟悉所负责区域的商业地产及房产市场，有一定的人脉资源；\n4.掌握与租赁合同相关的基本法律、法规问题，与房东洽谈时能够辨别和规避法律风险、保障公司权益；\n5.掌握基本的工程常识，做选址评估时能够辨别较为明显的工程隐患；\n6.较强的沟通、谈判、协调能力，具备一定的谈判技巧及处理公共关系的能力。","description":"部门介绍\n快乐猴是美团自营社区超市，依托自有供应链和门店管理体系，聚焦家庭用户的三餐所需，为消费者提供高质价比的食杂商品。快乐猴以数字化能力与科学品控为基础，不断满足消费者对“省”和“便利”的需求。\n\n岗位职责\n1.负责美团食杂零售快乐猴业务的选址工作，对所管辖区域的新店选址做现场考察、商圈评估及市场调研工作；\n2.根据本地市场的特点以及公司开店的要求制定战区规划与开店策略；\n3.负责项目的商务谈判、合同谈判、基本工程条件的谈判以及风险预估；\n4.利用相关工具对预选址进行详细分析，做出逻辑清晰、条理分明的选址报告；\n5.负责跟进项目签约、接场、开业的流程，具备处理门店开业前施工过程中遇到的各种问题的能力。\n\n岗位基本要求\n1.5年及以上零售拓展行业的相关工作经验，具备商超便利店、街边及商场店铺选址工作经验者优先；\n2.较强的专业能力，能够独立完成项目的评估、选址、谈判、签约及进场工作，具备制定战区图的能力；\n3.熟悉所负责区域的商业地产及房产市场，有一定的人脉资源；\n4.掌握与租赁合同相关的基本法律、法规问题，与房东洽谈时能够辨别和规避法律风险、保障公司权益；\n5.掌握基本的工程常识，做选址评估时能够辨别较为明显的工程隐患；\n6.较强的沟通、谈判、协调能力，具备一定的谈判技巧及处理公共关系的能力。\n\n岗位亮点\n1. 参与公司核心业务拓展，直接影响业务增长与战略布局。  \n2. 提供广阔的职业发展平台与专业能力提升机会。  \n3. 扁平化管理，高效协作的团队氛围。  \n4. 具有市场竞争力的薪酬福利体系。  \n5. 工作地点位于杭州核心区域，交通便利。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4629413354","sourceKey":"meituan_social","company":"美团","title":"AI产品增长专家","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4629413354&jobShareType=1","duty":"1、负责Agent原生产品的用户增长体系搭建，从用户获取、激活、留存到传播，设计并落地完整的增长飞轮，对核心增长指标（DAU、留存率、用户活跃度）负责\n2、定义并验证产品的核心价值传递路径，找到产品关键的\"Aha Moment\"，明确用户在最短路径内感知产品差异化价值的关键节点，推动产品侧配合优化\n3、设计并执行增长实验，建立\"假设-验证-迭代\"的增长实验机制，用数据驱动决策，快速淘汰无效动作，放大有效杠杆\n4、探索AI Agent社区的创新获客模式，AI原生产品作为全新品类，没有现成教科书，需要创造性地定义渠道策略、内容策略和病毒传播机制\n5、搭建社区运营体系，负责种子用户运营、内容生态建设、KOL/KOC培育，构建社区的自生长能力和内容供给机制\n6、跨团队协同推动增长落地，与产品、技术、设计团队深度协作，将增长策略转化为产品功能和技术方案，推动端到端落地","requirements":"1、3-5年互联网产品增长/用户运营经验（特别优秀者不限年限），至少主导过1个产品从冷启动到规模化增长的完整周期\n2、对AI产品（尤其是AI Agent、AI应用、AI社区）有深刻理解，不是\"听过\"，而是\"用过、拆过、想过\"\n3、具备扎实的数据分析能力，能用数据发现问题、验证假设、指导决策，熟练使用主流数据分析工具\n4、有打破常规的勇气和能力，需要的不是执行\"行业最佳实践\"的人，而是能创造新实践的人\n5、优秀的跨团队沟通协作能力，能推动产品和技术团队配合增长目标\n6、本科及以上学历","description":"部门介绍\n基础研发平台是美团的核心技术平台，立足于“零售+科技”的战略定位，通过打造人工智能、大数据、云计算、安全等核心技术能力，以及研发效能平台、企业应用平台等公共服务，为业务提供稳定安全、扩展易用、技术领先的平台技术和产品服务。\n在这里，我们会参与到最前沿的技术研发和探索；能够接触超规模集群、海量数据，挑战高复杂业务场景，有机会与业界一流的工程师一起并肩前行。\n在这里，我们有超强的技术氛围，持续向社区贡献业界实践，加速行业技术发展；我们有完善的互联网学习生态圈，重视底层逻辑和方法论，助力职业生涯的非线性成长。\n真诚地邀请你，和我们一起驱动技术发展，创造行业价值。\n\n岗位职责\n1、负责Agent原生产品的用户增长体系搭建，从用户获取、激活、留存到传播，设计并落地完整的增长飞轮，对核心增长指标（DAU、留存率、用户活跃度）负责\n2、定义并验证产品的核心价值传递路径，找到产品关键的\"Aha Moment\"，明确用户在最短路径内感知产品差异化价值的关键节点，推动产品侧配合优化\n3、设计并执行增长实验，建立\"假设-验证-迭代\"的增长实验机制，用数据驱动决策，快速淘汰无效动作，放大有效杠杆\n4、探索AI Agent社区的创新获客模式，AI原生产品作为全新品类，没有现成教科书，需要创造性地定义渠道策略、内容策略和病毒传播机制\n5、搭建社区运营体系，负责种子用户运营、内容生态建设、KOL/KOC培育，构建社区的自生长能力和内容供给机制\n6、跨团队协同推动增长落地，与产品、技术、设计团队深度协作，将增长策略转化为产品功能和技术方案，推动端到端落地\n\n岗位基本要求\n1、3-5年互联网产品增长/用户运营经验（特别优秀者不限年限），至少主导过1个产品从冷启动到规模化增长的完整周期\n2、对AI产品（尤其是AI Agent、AI应用、AI社区）有深刻理解，不是\"听过\"，而是\"用过、拆过、想过\"\n3、具备扎实的数据分析能力，能用数据发现问题、验证假设、指导决策，熟练使用主流数据分析工具\n4、有打破常规的勇气和能力，需要的不是执行\"行业最佳实践\"的人，而是能创造新实践的人\n5、优秀的跨团队沟通协作能力，能推动产品和技术团队配合增长目标\n6、本科及以上学历\n\n具备以下条件优先\n1、有Character.AI、Replika、Discord、即刻、小红书、豆瓣等社区型产品的增长运营经验\n2、有Hugging Face、Civitai、Coze/扣子、Dify等AI平台/开发者社区的运营经验\n3、有AI Native产品的增长经验（而非传统互联网产品简单套AI）\n4、了解AI Agent生态，熟悉Prompt Engineering、Agent编排等概念\n5、有从0到1搭建社区冷启动的实战经历\n\n岗位亮点\n1、定义一个全新品类，AI for Agent产品全球刚起步，你做的事可能成为行业标杆，而不是做微调优化\n2、美团的资源 + 创业的速度，大平台的资源支持与小团队的决策效率兼具，不内卷、不内耗\n3、直接向产品负责人汇报，扁平汇报结构，你的判断和声音直接影响产品方向\n4、站在AI浪潮的最前沿，不是\"用AI优化旧业务\"，而是在AI原生场景里探索未来","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4786809257","sourceKey":"meituan_social","company":"美团","title":"业务运营岗","city":"上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4786809257&jobShareType=1","duty":"1、房东体验改善：分析房东体验数据与案例，通过体验分析报告抽象总结业务运营、产品策略、业务规则的优化建议；基于优化建议，跟进房东体验问题推进改善方案落地，为体验指标负责；\n2、供应商管理：负责房东上房审核业务落地，管理预算、供应商执行质量与效率；\n3、机制建设：通过建立体验协同机制与产品业务部门密切合作，共同推动房东全链路体验的改进和优化；","requirements":"1、业务流程体系搭建：具备基本体系搭建能力，能够站在客户视角，挖掘客户痛点，通过问题结合业务能够看本质、抓重点；\n2、问题洞察与分析解决：发现问题并推动改善，能够在现有流程框架下，主动、结构化的发现问题和痛点，制定改进计划，并能够使用数据进行根因分析，效果验证，有较为成熟的数据分析能力，会SQL为佳；\n3、项目推进及管理：独立完成项目，能够独立进行简单项目的推进和管理，成功项目管理经验，住宿行业或非标业务相关经验者为加分项；\n4、5年及以上的互联网流程运营、体验运营经验，本科以上学历；擅长总结复盘体验改善策略带来的效果，沉淀经验。","description":"部门介绍\n美团酒店旅行业务涵盖酒店、民宿、机票、火车票、旅游度假、景点门票等各类住行游品类，通过与产业上下游的深度合作，为用户提供美好的旅游旅行体验。我们积极打造AI友好型组织，使用AI等新技术提升旅游服务的供需匹配效率，更好满足用户个性化、多样化的出游需求。我们持续深耕产业链，用数字化服务助力实体商家高质量经营，探索自有品牌等供给新模式，打造健康的商家生态，保障用户服务体验。为满足用户日益增长的跨境旅行需求，我们将聚焦亚太区域，打造高品质的住宿、交通、游玩等服务矩阵。\n这里有多元的业务布局、持续的成长空间，无论是向往的远方还是眼前的工作，一路都是风景相伴。加入我们，共同为用户创造旅游旅行中的高光时刻！\n\n岗位职责\n1、房东体验改善：分析房东体验数据与案例，通过体验分析报告抽象总结业务运营、产品策略、业务规则的优化建议；基于优化建议，跟进房东体验问题推进改善方案落地，为体验指标负责；\n2、供应商管理：负责房东上房审核业务落地，管理预算、供应商执行质量与效率；\n3、机制建设：通过建立体验协同机制与产品业务部门密切合作，共同推动房东全链路体验的改进和优化；\n\n岗位基本要求\n1、业务流程体系搭建：具备基本体系搭建能力，能够站在客户视角，挖掘客户痛点，通过问题结合业务能够看本质、抓重点；\n2、问题洞察与分析解决：发现问题并推动改善，能够在现有流程框架下，主动、结构化的发现问题和痛点，制定改进计划，并能够使用数据进行根因分析，效果验证，有较为成熟的数据分析能力，会SQL为佳；\n3、项目推进及管理：独立完成项目，能够独立进行简单项目的推进和管理，成功项目管理经验，住宿行业或非标业务相关经验者为加分项；\n4、5年及以上的互联网流程运营、体验运营经验，本科以上学历；擅长总结复盘体验改善策略带来的效果，沉淀经验。\n\n岗位亮点\n1、从体验运营的体验设计与规划，对话层级高，能够全面理解业务、行业；\n2、开放、直接的工作氛围，丰富的知识库和方法论，鼓励思考迭代成长。\n3、业务发展潜力大，团队建立初期，发展空间大。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4781310303","sourceKey":"meituan_social","company":"美团","title":"中医问诊大客户销售经理","city":"上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4781310303&jobShareType=1","duty":"1. 中医问诊KA板块业务目标达成：负责KA板块目标策略拆解、进度跟踪与达成管理\n2. KA服务商的拓展与管理：基于业务服务商合作策略方案以及服务商管理规则，落地服务商药房的拓展、准入、签约与关系维护，持续引入优质药房服务商及医生资源\n3. KA医生运营与分层管理：负责服务商医生资源运营，包括医生排班、考核、培训、分层成长，通过医生问诊SOP、问诊服务质量管理等，通过商务拜访、洽谈等方式与服务商医生开展深度合作，推动其在平台的生态活跃\n4. 数据分析与策略调优：基于中医问诊不同业务模式，初诊/复诊、病症结构、流量入口、用户画像等维度进行数据复盘；定位转化、均价、问诊量等关键指标波动的根因并输出运营策略\n5. 其他合作拓展（营销活动）：基于KA业务板块的运营需求，对接合作资源（如 KOL/平台合作、名中医专科、品牌联名活动等），落地营销活动，拓展流量与转化增量","requirements":"5年以上互联网医疗 / 中医问诊 / 本地生活商务拓展或运营经验，有 KA 大客户管理、服务商管理经验者优先。\n具备优秀的商务谈判与关系维护能力，能有效推动服务商、医生、平台等多方协同；\n数据敏感度高，具备扎实的数据分析能力，从日常运营数据中发现问题与增长机会；\n具备较强的项目推进与落地能力，能统筹多服务商、多医生的复杂运营事项；\n具备中医/中药或医药线上问诊经验及行业资源，熟悉线上问诊、处方/抓药、复诊管理等链路者优先。\n综合素质","description":"部门介绍\n美团医药健康事业部是美团核心本地商业板块下专注健康领域的业务部门，涵盖美团买药、美团医美和美团医疗三大业务。自创立以来，美团医药健康致力于为用户提供全健康周期产品及服务，满足人民群众多层次多元化医疗健康需求，现已覆盖购药到家、居家检测、问诊挂号、医保支付、求医寻院、医疗美容等核心场景。此外，美团医药健康还为商户提供数字化转型创新解决方案，打造贯穿上游的联动机制，长期参与共建更透明、更可持续的医药健康产业生态圈，目前业务已覆盖25万家药店，收录27万家医疗机构。未来，美团医药康将协同更多行业伙伴，帮助大家变得更健康、更美丽、更养生。\n\n岗位职责\n1. 中医问诊KA板块业务目标达成：负责KA板块目标策略拆解、进度跟踪与达成管理\n2. KA服务商的拓展与管理：基于业务服务商合作策略方案以及服务商管理规则，落地服务商药房的拓展、准入、签约与关系维护，持续引入优质药房服务商及医生资源\n3. KA医生运营与分层管理：负责服务商医生资源运营，包括医生排班、考核、培训、分层成长，通过医生问诊SOP、问诊服务质量管理等，通过商务拜访、洽谈等方式与服务商医生开展深度合作，推动其在平台的生态活跃\n4. 数据分析与策略调优：基于中医问诊不同业务模式，初诊/复诊、病症结构、流量入口、用户画像等维度进行数据复盘；定位转化、均价、问诊量等关键指标波动的根因并输出运营策略\n5. 其他合作拓展（营销活动）：基于KA业务板块的运营需求，对接合作资源（如 KOL/平台合作、名中医专科、品牌联名活动等），落地营销活动，拓展流量与转化增量\n\n岗位基本要求\n5年以上互联网医疗 / 中医问诊 / 本地生活商务拓展或运营经验，有 KA 大客户管理、服务商管理经验者优先。\n具备优秀的商务谈判与关系维护能力，能有效推动服务商、医生、平台等多方协同；\n数据敏感度高，具备扎实的数据分析能力，从日常运营数据中发现问题与增长机会；\n具备较强的项目推进与落地能力，能统筹多服务商、多医生的复杂运营事项；\n具备中医/中药或医药线上问诊经验及行业资源，熟悉线上问诊、处方/抓药、复诊管理等链路者优先。\n综合素质\n\n岗位亮点\n1、业务前景：业务高速发展，市场发展机会好\n2、个人成长：可端到端闭环负责板块，在成熟平台上快速成长，同时鼓励创新尝试，可从0到1探索新机会点\n3、团队氛围：团队氛围开放，团队内协作紧密、高效可靠","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4750081582","sourceKey":"meituan_social","company":"美团","title":"仓储生产岗","city":"成都市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4750081582&jobShareType=1","duty":"1. 负责仓库日常货物的接收、入库、存储、拣选及出库操作，确保流程高效准确。  \n2. 执行库存盘点工作，核对系统数据与实际库存，及时发现并反馈差异。  \n3. 按照操作规范进行货物分类、标识及堆码，保障仓储安全与空间利用率。  \n4. 配合完成生产订单的物料准备与管理，支持生产计划顺利执行。  \n5. 遵守安全管理制度，维护作业区域整洁，及时上报设备异常或安全隐患。\n6. 理解公司制定的目标，并对目标进行拆解制定提升计划。","requirements":"1. 大学本科及以上学历，物流、供应链、仓储管理或相关专业优先。  \n2. 具备3年以上仓储或生产相关岗位工作经验，熟悉仓储作业流程。  \n3. 熟练使用仓储管理系统（WMS）及常用办公软件，具备基础数据分析能力。  \n4. 工作责任心强，具备良好的执行力和团队协作意识。  \n5. 能适应倒班或弹性工作安排，身体健康，能胜任体力劳动。","description":"部门介绍\n快驴进货是美团旗下的餐饮供应链平台，帮助餐饮商户以更低成本、更高效率来获取安全可靠的食材供应，让餐饮采购更简单。快驴进货同步发展“自营+平台”的业务模式，在采购环节一方面向上游供应商直采大宗商品，另一方面引入各地批发商，助力平台伙伴共同发展；在销售环节既有自建团队进行市场、客户拓展，又帮助各地批发商拓展业务；同时自建仓储管理系统、配送网络与团队，为客户提供优质履约服务。\n截至2022年，快驴进货布局了全国41个城市，为百万家商户提供“全、省、稳、好”的餐饮供应链服务。我们拥有3000+品牌食材、超5万SKU商品、超28万商品资质，并提供源头严审核、食品安全严把关、24小时无忧售后的全面保障，实现手机下单、送货上门的高效采购模式，帮百万商家节省了采购时间与成本，助力平台伙伴共同发展，在万亿市场共享机遇。\n在这里，你将收获完善的员工发展机制及学习体系，与各界专家一起深度参与餐饮供应链业务的发展。欢迎优秀的你加入美团快驴进货，与我们一起成长，一起更好！\n\n岗位职责\n1. 负责仓库日常货物的接收、入库、存储、拣选及出库操作，确保流程高效准确。  \n2. 执行库存盘点工作，核对系统数据与实际库存，及时发现并反馈差异。  \n3. 按照操作规范进行货物分类、标识及堆码，保障仓储安全与空间利用率。  \n4. 配合完成生产订单的物料准备与管理，支持生产计划顺利执行。  \n5. 遵守安全管理制度，维护作业区域整洁，及时上报设备异常或安全隐患。\n6. 理解公司制定的目标，并对目标进行拆解制定提升计划。\n\n岗位基本要求\n1. 大学本科及以上学历，物流、供应链、仓储管理或相关专业优先。  \n2. 具备3年以上仓储或生产相关岗位工作经验，熟悉仓储作业流程。  \n3. 熟练使用仓储管理系统（WMS）及常用办公软件，具备基础数据分析能力。  \n4. 工作责任心强，具备良好的执行力和团队协作意识。  \n5. 能适应倒班或弹性工作安排，身体健康，能胜任体力劳动。\n\n具备以下条件优先\n有生鲜仓储从业经验优先\n\n岗位亮点\n1. 工作地点位于成都市，交通便利，周边配套完善。  \n2. 提供完善的岗前培训与职业发展通道，助力个人成长。  \n3. 团队氛围融洽，注重员工关怀与工作生活平衡。  \n4. 享有具有竞争力的薪酬福利及绩效激励机制。  \n5. 参与现代化仓储运营，积累智能制造与物流融合经验。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4785113778","sourceKey":"meituan_social","company":"美团","title":"运输经理","city":"大连市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4785113778&jobShareType=1","duty":"1. 负责大连运输团队的整体运营管理，制定并执行运输计划，确保货物准时、安全送达。\n2. 管理运输成本，优化运输路线和车辆调度，提升运输效率并降低运营成本。\n3. 监督运输过程中的安全与合规，确保符合国家及公司相关法规要求。\n4. 带领并指导2人运输团队，进行日常培训、绩效考核与团队建设。\n5. 协调仓储、服务站及其他相关部门，保障运输环节与整体供应链的高效衔接。","requirements":"1. 大学专科及以上学历，物流、运输或相关专业优先。\n2. 具备8年以上物流运输管理经验，有仓储配送中心、运输管理背景者优先。\n3. 熟悉国内运输网络、车辆调度及成本控制，具备较强的数据分析与问题解决能力。\n4. 具备良好的团队管理能力与沟通协调能力，能够独立承担管理职责。\n5. 工作认真负责，适应灵活工作安排。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1. 负责大连运输团队的整体运营管理，制定并执行运输计划，确保货物准时、安全送达。\n2. 管理运输成本，优化运输路线和车辆调度，提升运输效率并降低运营成本。\n3. 监督运输过程中的安全与合规，确保符合国家及公司相关法规要求。\n4. 带领并指导2人运输团队，进行日常培训、绩效考核与团队建设。\n5. 协调仓储、服务站及其他相关部门，保障运输环节与整体供应链的高效衔接。\n\n岗位基本要求\n1. 大学专科及以上学历，物流、运输或相关专业优先。\n2. 具备8年以上物流运输管理经验，有仓储配送中心、运输管理背景者优先。\n3. 熟悉国内运输网络、车辆调度及成本控制，具备较强的数据分析与问题解决能力。\n4. 具备良好的团队管理能力与沟通协调能力，能够独立承担管理职责。\n5. 工作认真负责，适应灵活工作安排。\n\n岗位亮点\n1. 工作地点位于大连（前期在沈阳学习与办公），交通便利，生活配套完善。\n2. 提供具有竞争力的薪酬与完善的福利体系。\n3. 拥有清晰的职业发展路径与内部晋升机会。\n4. 团队氛围积极，注重员工成长与能力提升。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4777773399","sourceKey":"meituan_social","company":"美团","title":"快驴-合肥仓拣主管","city":"合肥市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4777773399&jobShareType=1","duty":"主要负责仓库夜间生产分拣工作，对指标能有敬畏之心，能够接受出勤班次的时间；\n1、负责分拣团队的团队培养与日常管理；\n2、监督监控各小组人员出勤计划与及时出勤情况，及时调控确保分拣无异常；\n3、对分拣效率、分拣准确率、分拣作业规范、差异率等作业指标负责，并能发现问题及时提出解决方案，落地改善；\n4、统筹分拣各小组间工作，确保整体分拣结果达成最优；\n5、联动上下游，发现并提出影响分拣作业异常，并推动上下游改善，从而实现作业质量有效保障；\n6、有较强的现场管控能力，协调能力、临场决策能力，临场调动氛围能力。","requirements":"1. 大学专科及以上，3年以上分拣、转运作业管理经验，熟悉仓库各环节作业流程；\n2. 熟练操作WMS系统及办公软件，具备口头表达能力，组织协调能力、落地执行能力、数据分析与问题解决能力；\n3. 有成本管控经验，善于现场管理，有突发事件处理经验。\n4. 具备较强的团队管理与沟通协调能力，能承受一定工作压力。","description":"部门介绍\n快驴进货是美团旗下的餐饮供应链平台，帮助餐饮商户以更低成本、更高效率来获取安全可靠的食材供应，让餐饮采购更简单。快驴进货同步发展“自营+平台”的业务模式，在采购环节一方面向上游供应商直采大宗商品，另一方面引入各地批发商，助力平台伙伴共同发展；在销售环节既有自建团队进行市场、客户拓展，又帮助各地批发商拓展业务；同时自建仓储管理系统、配送网络与团队，为客户提供优质履约服务。\n截至2022年，快驴进货布局了全国41个城市，为百万家商户提供“全、省、稳、好”的餐饮供应链服务。我们拥有3000+品牌食材、超5万SKU商品、超28万商品资质，并提供源头严审核、食品安全严把关、24小时无忧售后的全面保障，实现手机下单、送货上门的高效采购模式，帮百万商家节省了采购时间与成本，助力平台伙伴共同发展，在万亿市场共享机遇。\n在这里，你将收获完善的员工发展机制及学习体系，与各界专家一起深度参与餐饮供应链业务的发展。欢迎优秀的你加入美团快驴进货，与我们一起成长，一起更好！\n\n岗位职责\n主要负责仓库夜间生产分拣工作，对指标能有敬畏之心，能够接受出勤班次的时间；\n1、负责分拣团队的团队培养与日常管理；\n2、监督监控各小组人员出勤计划与及时出勤情况，及时调控确保分拣无异常；\n3、对分拣效率、分拣准确率、分拣作业规范、差异率等作业指标负责，并能发现问题及时提出解决方案，落地改善；\n4、统筹分拣各小组间工作，确保整体分拣结果达成最优；\n5、联动上下游，发现并提出影响分拣作业异常，并推动上下游改善，从而实现作业质量有效保障；\n6、有较强的现场管控能力，协调能力、临场决策能力，临场调动氛围能力。\n\n岗位基本要求\n1. 大学专科及以上，3年以上分拣、转运作业管理经验，熟悉仓库各环节作业流程；\n2. 熟练操作WMS系统及办公软件，具备口头表达能力，组织协调能力、落地执行能力、数据分析与问题解决能力；\n3. 有成本管控经验，善于现场管理，有突发事件处理经验。\n4. 具备较强的团队管理与沟通协调能力，能承受一定工作压力。\n\n岗位亮点\n1.在初创期投入生鲜电商领域，作为先驱者和公司共同摸索成长，锤炼对仓储管理的认识。\n2.知名互联网公司与传统物流行业的深度结合，与来自供应链领域的精英共事。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4783538443","sourceKey":"meituan_social","company":"美团","title":"小象—重庆—运输主管","city":"重庆市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4783538443&jobShareType=1","duty":"1. 负责重庆运输团队的整体运营管理，确保运输任务按时高效完成。\n2. 制定并优化运输路线与调度计划，提升运输效率并控制成本。\n3. 管理50人运输团队，包括司机、调度员等岗位的日常工作安排与绩效考核。\n4. 协调仓储、客服等部门，保障货物从出库到交付的全流程顺畅。\n5. 监控运输过程中的安全与合规性，处理突发异常情况并制定改进措施。","requirements":"1. 大学专科及以上学历，物流、运输或相关专业优先。  \n2. 具备5年以上物流或运输相关工作经验。  \n3. 熟悉重庆地区交通状况及物流网络布局。  \n4. 具备良好的沟通协调能力和团队管理经验。\n5. 熟练使用办公软件及运输管理系统（TMS）","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1. 负责重庆运输团队的整体运营管理，确保运输任务按时高效完成。\n2. 制定并优化运输路线与调度计划，提升运输效率并控制成本。\n3. 管理50人运输团队，包括司机、调度员等岗位的日常工作安排与绩效考核。\n4. 协调仓储、客服等部门，保障货物从出库到交付的全流程顺畅。\n5. 监控运输过程中的安全与合规性，处理突发异常情况并制定改进措施。\n\n岗位基本要求\n1. 大学专科及以上学历，物流、运输或相关专业优先。  \n2. 具备5年以上物流或运输相关工作经验。  \n3. 熟悉重庆地区交通状况及物流网络布局。  \n4. 具备良好的沟通协调能力和团队管理经验。\n5. 熟练使用办公软件及运输管理系统（TMS）\n\n岗位亮点\n1. 提供完善的培训体系和职业发展通道。  \n2. 享受具有竞争力的薪酬和绩效奖金。  \n3. 工作地点位于重庆市核心区域，交通便利。  \n4. 团队氛围积极，注重员工成长与关怀。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:2888718308","sourceKey":"meituan_social","company":"美团","title":"HR AI产品经理（数字人方向）","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=2888718308&jobShareType=1","duty":"1. 负责HR领域AI产品的规划与设计，聚焦招聘、人才发展、组织效能、员工服务等场景，推动大模型、AI Agent、数字人等能力在HR业务中的落地\n2. 深入HR业务方与一线用户，通过用户调研、流程梳理和数据分析识别高价值AI落地场景，将业务痛点转化为清晰的产品需求与方案设计\n3. 主导AI Agent产品设计，涵盖知识问答（RAG）、工具调用、多角色协同等产品模块，并设计可控的权限、确认与兜底机制\n4. 建立AI产品评测体系（评测集构建、效果标准定义），跟踪上线后的效率、质量、成本指标，基于用户反馈和Badcase持续迭代\n5. 与业务方高效协同，有PDE经验，能够独立完成方案在业务侧的部署落地和推广\n6. 协同HR业务、产研团队，推动产品高质量交付，沉淀可复用的AI产品设计方法论","requirements":"岗位要求\n1. 本科及以上学历，5年以上产品经理经验，有AI产品完整落地经验（有可复盘的上线案例和量化结果）\n2. 深入理解大模型、Agent、RAG等技术能力边界与典型应用模式，熟悉Prompt工程、评测方法，能与团队高效对焦，持续优化产品\n3. 具备较强的数据分析能力，能通过数据定义核心指标、评估产品效果\n4. 出色的跨团队协作与推进能力，能在快节奏环境中推动复杂问题闭环解决","description":"部门介绍\n美团HR的使命是“建设有生命力的组织，为客户和社会创造价值。” 我们认为HR的工作不是以自身“专业”为中心，而是要建设有助于员工发挥创造力的环境，支持他们更好地为外部客户和社会创造价值，也实现组织自身的进化和传承。在这个过程中，我们的每位HR同学都是“业务的战略合作伙伴、组织能力的建设者、美团精神的布道者、员工的成长伙伴”。我们要设计面向长期支撑组织有效运转的机制，我们要求真务实地帮业务解决发展中的问题和阵痛，我们要支持每一位员工历经磨炼收获成长。我们要影响和驱动让世界更美好的变化发生。如果这也是你追求的，欢迎加入美团HR，与我们一路同行！\n\n岗位职责\n1. 负责HR领域AI产品的规划与设计，聚焦招聘、人才发展、组织效能、员工服务等场景，推动大模型、AI Agent、数字人等能力在HR业务中的落地\n2. 深入HR业务方与一线用户，通过用户调研、流程梳理和数据分析识别高价值AI落地场景，将业务痛点转化为清晰的产品需求与方案设计\n3. 主导AI Agent产品设计，涵盖知识问答（RAG）、工具调用、多角色协同等产品模块，并设计可控的权限、确认与兜底机制\n4. 建立AI产品评测体系（评测集构建、效果标准定义），跟踪上线后的效率、质量、成本指标，基于用户反馈和Badcase持续迭代\n5. 与业务方高效协同，有PDE经验，能够独立完成方案在业务侧的部署落地和推广\n6. 协同HR业务、产研团队，推动产品高质量交付，沉淀可复用的AI产品设计方法论\n\n岗位基本要求\n岗位要求\n1. 本科及以上学历，5年以上产品经理经验，有AI产品完整落地经验（有可复盘的上线案例和量化结果）\n2. 深入理解大模型、Agent、RAG等技术能力边界与典型应用模式，熟悉Prompt工程、评测方法，能与团队高效对焦，持续优化产品\n3. 具备较强的数据分析能力，能通过数据定义核心指标、评估产品效果\n4. 出色的跨团队协作与推进能力，能在快节奏环境中推动复杂问题闭环解决\n\n具备以下条件优先\n- 理解招聘、绩效、人才发展等HR域至少一个方向的业务逻辑，有HR系统或HR产品经验者/企业级B端产品经验优先\n- 有AI创业公司产品经验优先\n\n岗位亮点\n作为HR产品经理助力海外业务蓬勃发展，了解到不同国家和地区的文化","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4760681659","sourceKey":"meituan_social","company":"美团","title":"餐饮SaaS技术支持服务管理","city":"成都市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4760681659&jobShareType=1","duty":"1、负责领导和管理餐饮SaaS远程技术支持、交付团队，确保团队高效运转并提供优质的技术支持和交付服务；\n2、制定并完善团队管理制度和流程，包括业务流程、人员招聘、培训、绩效考核等；\n督促团队成员完成技术支持、远程安装工作，包括故障排查、问题解决和客户咨询等；\n3、确保团队的工作质量和服务水平符合公司要求，及时处理和解决客户的问题；\n4、进行团队绩效评估和目标设定，给予团队成员指导和培训，推动团队整体提升；\n5、与其他部门沟通和协作，解决复杂问题和提供优质的技术支持及远程安装服务；\n及时收集用户反馈和市场需求，向上级领导汇报，并提出改进意见；\n快速解决复杂的技术问题，并对技术支持流程和工具进行优化和调整。","requirements":"1、本科及以上学历，计算机科学或相关专业背景；\n2、有餐饮行业相关工作经验，熟悉连锁餐饮业务流程优先；\n3、三年以上团队管理经验，能够有效指导团队成员，并激发团队积极性；\n4、良好的沟通能力和问题解决能力，能够与用户和团队有效互动；\n5、熟悉SaaS技术支持流程和工具，并熟练掌握常见的操作系统和网络知识；\n6、具备快速学习和自我驱动能力，能够迅速解决问题；\n7、具备良好的主人翁意识，能够在高强度的工作环境下保持积极和稳定的工作状态","description":"部门介绍\n美团餐饮系统为餐饮企业提供一站式IT解决方案，帮助餐饮商户实现从供应链管理、生产管理、前厅管理到外卖的数字化经营。美团餐饮系统不仅打通了餐厅和平台，更帮助餐厅连接客人，让商户更了解顾客需求，在帮助商户做商业决策的同时给顾客带来更好的消费体验。\n我们持续建设和提升产研、销售、服务的核心能力，通过全新升级的美团餐饮系统一体化软硬件产品，助力餐饮商户进行线上化经营，帮助商户在推广新店、提升效率、降低成本、会员营销、流量扶持、智慧选址、供应链管理等方面强化经营能力。团队汇集了餐饮和SaaS领域的优秀人才，秉持着“以客户为中心”的初心和“长期有耐心”的耕耘精神，求真、敬畏、敢于自我否定、善于快速学习。期待同样愿意长期致力于餐饮产业数字化、智能化的你加入我们的团队，共同进步共同成长！\n\n岗位职责\n1、负责领导和管理餐饮SaaS远程技术支持、交付团队，确保团队高效运转并提供优质的技术支持和交付服务；\n2、制定并完善团队管理制度和流程，包括业务流程、人员招聘、培训、绩效考核等；\n督促团队成员完成技术支持、远程安装工作，包括故障排查、问题解决和客户咨询等；\n3、确保团队的工作质量和服务水平符合公司要求，及时处理和解决客户的问题；\n4、进行团队绩效评估和目标设定，给予团队成员指导和培训，推动团队整体提升；\n5、与其他部门沟通和协作，解决复杂问题和提供优质的技术支持及远程安装服务；\n及时收集用户反馈和市场需求，向上级领导汇报，并提出改进意见；\n快速解决复杂的技术问题，并对技术支持流程和工具进行优化和调整。\n\n岗位基本要求\n1、本科及以上学历，计算机科学或相关专业背景；\n2、有餐饮行业相关工作经验，熟悉连锁餐饮业务流程优先；\n3、三年以上团队管理经验，能够有效指导团队成员，并激发团队积极性；\n4、良好的沟通能力和问题解决能力，能够与用户和团队有效互动；\n5、熟悉SaaS技术支持流程和工具，并熟练掌握常见的操作系统和网络知识；\n6、具备快速学习和自我驱动能力，能够迅速解决问题；\n7、具备良好的主人翁意识，能够在高强度的工作环境下保持积极和稳定的工作状态\n\n具备以下条件优先\n1、有团队管理经验，并成功带领团队完成任务；\n2、有餐饮SaaS产品的相关工作经验；\n3、有项目管理经验，能够有效规划和推动团队的工作进度。\n\n岗位亮点\n完善的培训、多管道晋升体系；大平台；六险一金；","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4764829537","sourceKey":"meituan_social","company":"美团","title":"Keeta Drone 产品和产品运营负责人","city":"迪拜","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4764829537&jobShareType=1","duty":"1. 负责Keeta Drone B/C端产品功能设计与迭代优化，并推动落地执行。  \n2. 搭建并管理产品运营体系，结合数据驱动提升用户活跃和商流转化。\n3. 协同国内产研、国外业务、Keeta产研团队等推动产品从0到1的孵化、规模增长。","requirements":"1. 大学本科及以上学历，计算机、工程、产品设计或相关专业优先。  \n2. 10年以上产品或产品运营相关工作经验，有产品和业务思维，具备成功主导复杂产品从规划到上线的完整经验。  \n3. 优秀的跨团队沟通与项目管理能力，能够高效推动多方协作。  \n4. 有一定英语沟通能力，适应中东工作环境。","description":"部门介绍\n为了更好地提升城市即时配送的效率与体验，2017年，美团启动了无人机配送服务的探索，通过科技创新推动履约工具变革，加快建设空地协同的本地即时配送网络。\n在过去的六年里，美团无人机完成了飞行器、自动化机场及智能调度系统的研发工作，实现了研发设计、生产制造、运营运维全链条布局，达成了城市复杂场景物流无人机高频次、高密度、多天时、多天侯运行。\n2023年7月，美团无人机在上海发布了自主研发的第四代无人机，跟此前机型相比，新机型升级了环境适应能力，可在“零下20度至50度”的中雨、中雪、6级风、弱光等环境中稳定飞行，能够适应97%以上国内城市的自然环境要求。\n截至2024年12月，美团无人机已在深圳、北京、上海、广州、南京、迪拜等城市开通53条航线，并累计完成订单超40万单。即时零售配送服务覆盖了办公、社区、景区、市政公园、校园、医疗、图书馆等多种场景。在医疗场景中，美团无人机可围绕医疗血液、检验样本、院前急救物资、特殊药品等医疗物资配送需求建设端到端的全天时急送网络。\n\n岗位职责\n1. 负责Keeta Drone B/C端产品功能设计与迭代优化，并推动落地执行。  \n2. 搭建并管理产品运营体系，结合数据驱动提升用户活跃和商流转化。\n3. 协同国内产研、国外业务、Keeta产研团队等推动产品从0到1的孵化、规模增长。\n\n岗位基本要求\n1. 大学本科及以上学历，计算机、工程、产品设计或相关专业优先。  \n2. 10年以上产品或产品运营相关工作经验，有产品和业务思维，具备成功主导复杂产品从规划到上线的完整经验。  \n3. 优秀的跨团队沟通与项目管理能力，能够高效推动多方协作。  \n4. 有一定英语沟通能力，适应中东工作环境。\n\n岗位亮点\n1. 加入前沿科技领域，主导创新型无人机产品的全球化布局。  \n2. 与前沿技术团队共事，参与定义未来智慧出行与物流解决方案。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4761633445","sourceKey":"meituan_social","company":"美团","title":"到餐业务专家","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4761633445&jobShareType=1","duty":"1.以业务负责人视角，负责所辖货盘（货架/特团/营销场）的增长、竞争与盈亏管理，对所辖货盘的经营结果负责\n2.制定并执行所辖货盘的新签策略与供给优化方案，确保规模持续增长、供给结构优化\n3.负责所辖货盘的数据分析与诊断，识别供给缺口，制定补齐方案，推进供给适配性改进\n4.定位pmf设计供给结构，明确业务定位，推进营销场供给测试\n5.设计并优化货盘管理政策与考核机制，提升一线BD的做工效率与质量\n6.负责物理世界验证（如实地走访、商户调研），确保供给策略贴合市场实际\n7.利用AI Agent优化货盘管理全流程，包括招货推荐、供给缺口自动诊断、效果测试等，将AI作为提升管理效率的核心工具","requirements":"1.3年以上供给管理、商户运营或业务管理相关经验，有货架/特团/营销场运营经验者优先\n2.具备业务负责人视角，能对所辖货盘的增长、竞争与盈亏负责，而非仅执行层面\n3.理解\"人货场\"理念，能基于pmf业务定位设计差异化的供给方案\n4.具备较强的数据分析能力，能通过数据诊断供给问题并制定优化策略\n5.有策略制定与考核设计经验，理解前线BD的做工逻辑与痛点\n6.具备物理世界验证意识，愿意深入一线了解市场实际情况\n7.有较强的项目管理能力，能推动跨团队协同落地\n8.对AI驱动的货盘管理有认知，愿意探索用Agent替代重复性工作，聚焦高价值决策","description":"部门介绍\n美团核心本地商业-下沉市场发展部于2015年成立，通过招募优质的合作商伙伴并对其业务经营能力、组织能力等赋能，以期为下沉城市提供一站式的本地生活服务。\n下沉市场发展部的业务场景涵盖了外卖餐饮、团购、拼好饭、闪购、医药等多元化的生活服务领域，同时搭建了一套稳定、高效的即时配送网络，为更多本地用户提供品质化、多样化、便捷高效的生活服务体验，为当地商户提供数字化发展机遇、提升数字化水平，为社会创造更多的就地就业机会。\n截至2024年6月，下沉市场发展部已开拓全国4000+县区市，帮助百万商户实现本地生活服务数字化，日订单量突破千万，为数十万名骑手提供就业岗位，让本地生活服务逐渐成长为地方新基建，实现美团“帮助大家吃得更好，生活更好”的使命！\n\n岗位职责\n1.以业务负责人视角，负责所辖货盘（货架/特团/营销场）的增长、竞争与盈亏管理，对所辖货盘的经营结果负责\n2.制定并执行所辖货盘的新签策略与供给优化方案，确保规模持续增长、供给结构优化\n3.负责所辖货盘的数据分析与诊断，识别供给缺口，制定补齐方案，推进供给适配性改进\n4.定位pmf设计供给结构，明确业务定位，推进营销场供给测试\n5.设计并优化货盘管理政策与考核机制，提升一线BD的做工效率与质量\n6.负责物理世界验证（如实地走访、商户调研），确保供给策略贴合市场实际\n7.利用AI Agent优化货盘管理全流程，包括招货推荐、供给缺口自动诊断、效果测试等，将AI作为提升管理效率的核心工具\n\n岗位基本要求\n1.3年以上供给管理、商户运营或业务管理相关经验，有货架/特团/营销场运营经验者优先\n2.具备业务负责人视角，能对所辖货盘的增长、竞争与盈亏负责，而非仅执行层面\n3.理解\"人货场\"理念，能基于pmf业务定位设计差异化的供给方案\n4.具备较强的数据分析能力，能通过数据诊断供给问题并制定优化策略\n5.有策略制定与考核设计经验，理解前线BD的做工逻辑与痛点\n6.具备物理世界验证意识，愿意深入一线了解市场实际情况\n7.有较强的项目管理能力，能推动跨团队协同落地\n8.对AI驱动的货盘管理有认知，愿意探索用Agent替代重复性工作，聚焦高价值决策\n\n岗位亮点\n1.管理核心货盘资产，直接对业务增长与盈亏负责\n2.深度参与AI驱动的货盘管理升级，推动行业前沿实践\n3.策略+执行+验证全链路参与，能力成长全面","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4358029217","sourceKey":"meituan_social","company":"美团","title":"医药健康-口腔和眼部健康区域客户大区-CKA","city":"北京市/石家庄市/上海市/苏州市/杭州市/福州市/厦门市/青岛市/郑州市/武汉市/广州市/深圳市/重庆市/成都市/西安市/济南市/潍坊市/临沂市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4358029217&jobShareType=1","duty":"1.负责口腔和眼镜和眼部健康行业产品在所负责区域的销售业绩达成。\n2.维护现有客户关系，提升客户满意度。\n3.负责制定销售计划和执行方案，确保销售目标的达成。\n4.协调内部资源，提供客户定制化的解决方案。\n5.分析市场竞争情况，及时调整销售策略，通过对行业经营诊断、投放指南、优化广告消耗计划，提升交易线上化、行业广告产品渗透率等。","requirements":"1.大学本科及以上学历，市场营销、KA经验优先。\n2.具备良好的沟通能力和团队合作精神。\n3.具备一定的销售经验，口腔、眼部健康和眼镜行业销售经验者优先。\n4.具备良好的学习能力和适应能力，能够适应高强度的工作压力。\n5.具备较强的市场洞察力和分析能力。","description":"部门介绍\n美团医药健康事业部是美团核心本地商业板块下专注健康领域的业务部门，涵盖美团买药、美团医美和美团医疗三大业务。自创立以来，美团医药健康致力于为用户提供全健康周期产品及服务，满足人民群众多层次多元化医疗健康需求，现已覆盖购药到家、居家检测、问诊挂号、医保支付、求医寻院、医疗美容等核心场景。此外，美团医药健康还为商户提供数字化转型创新解决方案，打造贯穿上游的联动机制，长期参与共建更透明、更可持续的医药健康产业生态圈，目前业务已覆盖25万家药店，收录27万家医疗机构。未来，美团医药康将协同更多行业伙伴，帮助大家变得更健康、更美丽、更养生。\n\n岗位职责\n1.负责口腔和眼镜和眼部健康行业产品在所负责区域的销售业绩达成。\n2.维护现有客户关系，提升客户满意度。\n3.负责制定销售计划和执行方案，确保销售目标的达成。\n4.协调内部资源，提供客户定制化的解决方案。\n5.分析市场竞争情况，及时调整销售策略，通过对行业经营诊断、投放指南、优化广告消耗计划，提升交易线上化、行业广告产品渗透率等。\n\n岗位基本要求\n1.大学本科及以上学历，市场营销、KA经验优先。\n2.具备良好的沟通能力和团队合作精神。\n3.具备一定的销售经验，口腔、眼部健康和眼镜行业销售经验者优先。\n4.具备良好的学习能力和适应能力，能够适应高强度的工作压力。\n5.具备较强的市场洞察力和分析能力。\n\n具备以下条件优先\n具备医疗行业经验，有过大客户服务经验优先\n\n岗位亮点\n1.在口腔和眼部健康领域有广阔的发展空间。\n2.薪资福利待遇优厚，晋升空间大。\n3.能够接触到新的产品和技术，不断提升专业能力。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4772415818","sourceKey":"meituan_social","company":"美团","title":"商业分析师（ 销售及绩效分析）","city":"上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4772415818&jobShareType=1","duty":"1. 负责所支持业务线的销售奖金全流程管理，包括激励政策设计、指标与规则梳理、方案测算、过程监控、核算复盘及政策迭代。\n2. 围绕业绩、人员规模、带户能力、产出效率及组织结构等关键问题，开展销售团队人效分析和专项诊断，输出激励与管理优化建议。\n3. 运用数据分析及 AI 工具，提升奖金政策编写、规则校验、方案测算、过程答疑、核算复盘和知识沉淀等环节的效率与交付质量。\n4. 协同业务、产品、数据、财务等跨部门团队，推动奖金相关流程、数据口径、系统能力及管理机制持续优化，保障政策有效落地。","requirements":"1. 本科及以上学历，3 年及以上相关工作经验；优先具备销售分析、销售管理或销售运营经验，有奖金激励、业绩指标管理经验者优先。\n2. 数据基本功扎实，具备较强的 SQL 和数据分析能力，能够独立完成复杂业务问题拆解、数据验证、方案测算及分析结论输出。\n3. 具备良好的业务理解和结构化思考能力，能够围绕销售人效、激励效果及组织效率等问题形成可执行的策略建议；有策略或经营分析经验者优先。\n4. 熟练使用常用数据分析工具，具备 AI 工具的实际使用经验，并具备良好的沟通协同和项目推动能力，能够协调多方资源推动事项闭环。","description":"部门介绍\n美团服务零售事业部下设乐生活业务部、易生活业务部、进场零售业务部以及中小城市发展部四大业务部门，旨在通过提供丰富、可靠、实惠的服务与商品满足用户各类生活需求。我们所处的服务零售行业是一个具有万亿规模的市场，覆盖足疗洗浴、酒吧KTV、运动健身、美发美甲、教育培训、亲子游乐、家政洗涤维修、摄影写真等数十个服务消费细分领域，同时延伸至超市便利、美妆个护、3C数码、服饰珠宝、运动户外、商场购物中心等实体零售到店消费场景，连接数十万品牌商户与线下门店。作为商家和行业的小帮手，我们持续深入服务零售与实体零售产业链，用AI等技术推动行业变革，帮助商家提升经营效率、实现高效的线上化经营与到店转化，优化消费者服务体验，提供安心、放心的履约保障。这里有着多元的业务布局，有着富有挑战和影响力的工作内容，为你提供丰富的视野、持续的成长和发展机会，引领你发现更多可能。期待和你在“随时随地，美好生活”的愿景指引下，共建美好的生活服务体验、健康的商家生态与高质量的经营结果。\n\n岗位职责\n1. 负责所支持业务线的销售奖金全流程管理，包括激励政策设计、指标与规则梳理、方案测算、过程监控、核算复盘及政策迭代。\n2. 围绕业绩、人员规模、带户能力、产出效率及组织结构等关键问题，开展销售团队人效分析和专项诊断，输出激励与管理优化建议。\n3. 运用数据分析及 AI 工具，提升奖金政策编写、规则校验、方案测算、过程答疑、核算复盘和知识沉淀等环节的效率与交付质量。\n4. 协同业务、产品、数据、财务等跨部门团队，推动奖金相关流程、数据口径、系统能力及管理机制持续优化，保障政策有效落地。\n\n岗位基本要求\n1. 本科及以上学历，3 年及以上相关工作经验；优先具备销售分析、销售管理或销售运营经验，有奖金激励、业绩指标管理经验者优先。\n2. 数据基本功扎实，具备较强的 SQL 和数据分析能力，能够独立完成复杂业务问题拆解、数据验证、方案测算及分析结论输出。\n3. 具备良好的业务理解和结构化思考能力，能够围绕销售人效、激励效果及组织效率等问题形成可执行的策略建议；有策略或经营分析经验者优先。\n4. 熟练使用常用数据分析工具，具备 AI 工具的实际使用经验，并具备良好的沟通协同和项目推动能力，能够协调多方资源推动事项闭环。\n\n具备以下条件优先\n1. 有较大规模销售团队的策略分析、经营分析、业绩管理、奖金激励或销售运营相关经验。\n2. 有参与奖金、佣金、提成等激励机制设计、测算、核算或复盘的经验。\n3. 数学、统计学、商科、计算机等相关专业背景优先。\n\n岗位亮点\n1. 独立负责单一业务线的销售策略分析工作，深度参与销售规划、奖金激励、经营诊断等核心管理事项，并有多业务线轮岗机会。\n2. 覆盖销售奖金从政策设计、测算落地到核算复盘和机制迭代的完整链路，能够理解激励策略如何真正影响业务和销售行为。\n3. 团队已将 AI 工具应用于奖金管理多个日常环节，可在真实业务场景中积累“数据分析 + AI 工具 + 管理策略”的复合型经验。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4780790464","sourceKey":"meituan_social","company":"美团","title":"质管部负责人","city":"武汉市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4780790464&jobShareType=1","duty":"1.负责药品批发企业质量管理体系动态持续建设及完善，对企业整体经营质量风险有较好的把控能力，对于无法解决的问题及时向质量负责人反馈。\n2.药品首营审核、变更审核及归档管理工作；负责质量档案：人员花名册、组织架构、质量职能、人事档案、培训档案、健康档案的建立及维护归档工作。\n3.对于质量体系关键要素发生重大变化时，牵头组织开展内审工作，对于发现的质量风险及时进行整改。\n4.迎接各级别药品监督管理部门监督检查，负责合理解答药监部门的问题。\n5.负责区域主体投诉举报的处理,负责区域主体证照的办理及变更事宜。\n6.组织安排的其他工作。","requirements":"1、本科以上学历\n2、执业药师资格\n3、3年以上药品经营质量管理工作经历","description":"部门介绍\n美团医药健康事业部是美团核心本地商业板块下专注健康领域的业务部门，涵盖美团买药、美团医美和美团医疗三大业务。自创立以来，美团医药健康致力于为用户提供全健康周期产品及服务，满足人民群众多层次多元化医疗健康需求，现已覆盖购药到家、居家检测、问诊挂号、医保支付、求医寻院、医疗美容等核心场景。此外，美团医药健康还为商户提供数字化转型创新解决方案，打造贯穿上游的联动机制，长期参与共建更透明、更可持续的医药健康产业生态圈，目前业务已覆盖25万家药店，收录27万家医疗机构。未来，美团医药康将协同更多行业伙伴，帮助大家变得更健康、更美丽、更养生。\n\n岗位职责\n1.负责药品批发企业质量管理体系动态持续建设及完善，对企业整体经营质量风险有较好的把控能力，对于无法解决的问题及时向质量负责人反馈。\n2.药品首营审核、变更审核及归档管理工作；负责质量档案：人员花名册、组织架构、质量职能、人事档案、培训档案、健康档案的建立及维护归档工作。\n3.对于质量体系关键要素发生重大变化时，牵头组织开展内审工作，对于发现的质量风险及时进行整改。\n4.迎接各级别药品监督管理部门监督检查，负责合理解答药监部门的问题。\n5.负责区域主体投诉举报的处理,负责区域主体证照的办理及变更事宜。\n6.组织安排的其他工作。\n\n岗位基本要求\n1、本科以上学历\n2、执业药师资格\n3、3年以上药品经营质量管理工作经历\n\n岗位亮点\n1.良好的团队氛围及晋升通道。\n2.具备良好发展前景的业务板块。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4775045128","sourceKey":"meituan_social","company":"美团","title":"无人车业务部-城市群增长负责人","city":"杭州市/苏州市/福州市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4775045128&jobShareType=1","duty":"1. 负责无人车业务城市群业务增长的整体规划与落地执行。  \n2. 带领团队开展地面商户拓展，推动无人车服务在本地商户中的合作与应用。  \n3. 建立并维护与商户及合作伙伴的长期合作关系，提升市场渗透率。  \n4. 分析区域市场动态与竞争格局，制定针对性业务策略并推动目标达成。\n5. 搭建城市群团队并做好日常管理，优化人才梯队和人才培养输出，共识团队目标并有监督落地","requirements":"1. 大学本科及以上学历，具备5年以上业务开发或地面拓展相关工作经验。  \n2. 熟悉当地市场环境，具备较强的商务谈判与资源整合能力。  \n3. 有团队管理经验，能够带领团队高效完成业务目标。  \n4. 具备创新思维和目标要性，适应快速变化的业务场景。\n5. 有物流、配送及共享出行行业工作经验者优先。","description":"部门介绍\n无人车业务部成立于2016年，旨在用无人驾驶技术提升物流配送的效率和体验。美团无人车以自研L4级自动驾驶软硬件技术为核心，与美团即时零售业务结合，形成满足公开道路、社区、工业园区等室外全场景下的无人配送整体解决方案。自2020年起，无人车已在北京、深圳等多地进入常态化试运营阶段，在城市复杂场景下提供针对餐饮外卖、生鲜食杂等货物的即时配送服务。2025年，美团无人车又踏上了同城货运的新探索，并在2026年持续扩大运营范围和车队数量，为更多城市带来智能配送服务。\n欢迎加入美团无人车团队，与我们一起用科技推动即时零售再升级！\n\n岗位职责\n1. 负责无人车业务城市群业务增长的整体规划与落地执行。  \n2. 带领团队开展地面商户拓展，推动无人车服务在本地商户中的合作与应用。  \n3. 建立并维护与商户及合作伙伴的长期合作关系，提升市场渗透率。  \n4. 分析区域市场动态与竞争格局，制定针对性业务策略并推动目标达成。\n5. 搭建城市群团队并做好日常管理，优化人才梯队和人才培养输出，共识团队目标并有监督落地\n\n岗位基本要求\n1. 大学本科及以上学历，具备5年以上业务开发或地面拓展相关工作经验。  \n2. 熟悉当地市场环境，具备较强的商务谈判与资源整合能力。  \n3. 有团队管理经验，能够带领团队高效完成业务目标。  \n4. 具备创新思维和目标要性，适应快速变化的业务场景。\n5. 有物流、配送及共享出行行业工作经验者优先。\n\n岗位亮点\n1. 参与前沿无人车技术在本地商业化落地的核心业务。  \n2. 拥有较大的业务自主权与成长空间，直接对区域业务结果负责。  \n3. 提供完善的培训体系与职业发展通道。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4777218291","sourceKey":"meituan_social","company":"美团","title":"产业带负责人","city":"北京市/深圳市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4777218291&jobShareType=1","duty":"1.工厂引入：完成产业带地图摸排，筛选合作的工厂，并制定对应的开发计划，完成工厂引入谈判，优胜劣汰，争取工厂促销资源；完善工厂商信息管理，确保合规性要求；\n\n2.品类管理：对于餐厨/调味品商品知识、商品价格及营销活动有较好的管理；对类目进行品类管理和规划，制定商品调整计划；完成所负责品类的销售额等目标。\n\n3.卖家运营：基于卖家经营分析及履约情况，找到机会点进行策略输出，制定商家运营策略，监督和跟进活动。\n\n4.协同工作：与团队密切协同，促进品类经营策略落地；跟其他相关部门配合好工作，积极筹备各种营销活动，诸如工厂促销商品的选择，促销方案的制定监督、执行等。","requirements":"1.有5年以上的餐厨/调味品行业采购或者销售经验，对类目有较深的专业认知和判断；\n\n2.具备餐厨/调味品产业经营及管理技术的知识，熟悉工厂动态、行业动态及市场变化；\n\n3.具备较强的谈判能力、研发产品的能力及供应链管理能力；\n\n4.具备丰富的产业带工厂资源，有开发和拓展源头工厂及产地资源的能力；\n\n5.有良好的数据分析和目标管理能力，学习能力较好，有责任心，有韧性；\n\n6.能能长期深耕产区，并推动后续链路环节从而打通从销地到产地的销售机会。","description":"部门介绍\n快驴进货是美团旗下的餐饮供应链平台，帮助餐饮商户以更低成本、更高效率来获取安全可靠的食材供应，让餐饮采购更简单。快驴进货同步发展“自营+平台”的业务模式，在采购环节一方面向上游供应商直采大宗商品，另一方面引入各地批发商，助力平台伙伴共同发展；在销售环节既有自建团队进行市场、客户拓展，又帮助各地批发商拓展业务；同时自建仓储管理系统、配送网络与团队，为客户提供优质履约服务。\n截至2022年，快驴进货布局了全国41个城市，为百万家商户提供“全、省、稳、好”的餐饮供应链服务。我们拥有3000+品牌食材、超5万SKU商品、超28万商品资质，并提供源头严审核、食品安全严把关、24小时无忧售后的全面保障，实现手机下单、送货上门的高效采购模式，帮百万商家节省了采购时间与成本，助力平台伙伴共同发展，在万亿市场共享机遇。\n在这里，你将收获完善的员工发展机制及学习体系，与各界专家一起深度参与餐饮供应链业务的发展。欢迎优秀的你加入美团快驴进货，与我们一起成长，一起更好！\n\n岗位职责\n1.工厂引入：完成产业带地图摸排，筛选合作的工厂，并制定对应的开发计划，完成工厂引入谈判，优胜劣汰，争取工厂促销资源；完善工厂商信息管理，确保合规性要求；\n\n2.品类管理：对于餐厨/调味品商品知识、商品价格及营销活动有较好的管理；对类目进行品类管理和规划，制定商品调整计划；完成所负责品类的销售额等目标。\n\n3.卖家运营：基于卖家经营分析及履约情况，找到机会点进行策略输出，制定商家运营策略，监督和跟进活动。\n\n4.协同工作：与团队密切协同，促进品类经营策略落地；跟其他相关部门配合好工作，积极筹备各种营销活动，诸如工厂促销商品的选择，促销方案的制定监督、执行等。\n\n岗位基本要求\n1.有5年以上的餐厨/调味品行业采购或者销售经验，对类目有较深的专业认知和判断；\n\n2.具备餐厨/调味品产业经营及管理技术的知识，熟悉工厂动态、行业动态及市场变化；\n\n3.具备较强的谈判能力、研发产品的能力及供应链管理能力；\n\n4.具备丰富的产业带工厂资源，有开发和拓展源头工厂及产地资源的能力；\n\n5.有良好的数据分析和目标管理能力，学习能力较好，有责任心，有韧性；\n\n6.能能长期深耕产区，并推动后续链路环节从而打通从销地到产地的销售机会。\n\n具备以下条件优先\n有品类集采经验、产业带业务开发经验优先\n\n岗位亮点\nB2B行业内首创，产区跃迁降本是目前最有价值的价格竞争力路径，团队发展空间巨大","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4744421283","sourceKey":"meituan_social","company":"美团","title":"电单车财务BP","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4744421283&jobShareType=1","duty":"1.财务支持：深入了解业务，与业务伙伴密切合作，建立合理有效的分析体系，给与有效建议并推进解决方案，深度支持业务决策和过程管理；\n2.财务分析：参与产品和项目的整体评估，包括商业定价、成本测算、健康度评估，并建立规范的通用模型；按期出具多维度的经营分析数据及业务运营情况，分析和挖掘公司的业务表现，结合业务特点制定关键业务指标及分析体系，与业务建立双向反馈机制；\n3.财务管理：对业务方案进行风险评估，建立定期的业务和财务数据跟踪体系，做好事前评估、事中跟踪、事后复盘，掌握业务的各环节盈利模式和盈利能力；\n4.财务预算：准确编制对应业务的财务预测及年度预算，并协助业务进行预算管理，监督和评估业务的业绩达成；\n5.财务日常工作：与账务、税务和报表团队积极协调，完成其他指定任务；\n6.负责流程优化及配合内控管理。","requirements":"1.本科及以上学历，财务相关专业。\n2.工作细致、严谨，具备独立思考和判断能力。\n3.具有较强的人际沟通和协调能力、计划与执行能力。\n4.具有高度责任责任感和较强的团队合作意识。\n5.对数字敏感，强逻辑思维能力，熟练使用常用办公软件，有AI应用经验优先。","description":"部门介绍\n财务平台负责公司整体和各业务层面的财务管理工作，通过建设专业、全面、复合的财务管理能力和与业务经营的紧密结合来支持公司健康发展。目前财务平台拥有财务会计、财务报告、资金管理、税务管理、财务共享、财务系统、规划分析、财务BP和内控内审等主要工作方向。我们的目标是建设业界一流的财务管理能力和经营支持体系，为公司战略的正确落地、投入效率的持续提升、业务价值的不断增长保驾护航。欢迎加入财务平台，携手一起向未来！\n\n岗位职责\n1.财务支持：深入了解业务，与业务伙伴密切合作，建立合理有效的分析体系，给与有效建议并推进解决方案，深度支持业务决策和过程管理；\n2.财务分析：参与产品和项目的整体评估，包括商业定价、成本测算、健康度评估，并建立规范的通用模型；按期出具多维度的经营分析数据及业务运营情况，分析和挖掘公司的业务表现，结合业务特点制定关键业务指标及分析体系，与业务建立双向反馈机制；\n3.财务管理：对业务方案进行风险评估，建立定期的业务和财务数据跟踪体系，做好事前评估、事中跟踪、事后复盘，掌握业务的各环节盈利模式和盈利能力；\n4.财务预算：准确编制对应业务的财务预测及年度预算，并协助业务进行预算管理，监督和评估业务的业绩达成；\n5.财务日常工作：与账务、税务和报表团队积极协调，完成其他指定任务；\n6.负责流程优化及配合内控管理。\n\n岗位基本要求\n1.本科及以上学历，财务相关专业。\n2.工作细致、严谨，具备独立思考和判断能力。\n3.具有较强的人际沟通和协调能力、计划与执行能力。\n4.具有高度责任责任感和较强的团队合作意识。\n5.对数字敏感，强逻辑思维能力，熟练使用常用办公软件，有AI应用经验优先。\n\n岗位亮点\n1.具备成熟的人才培养体系。\n2.财务团队整体工作氛围好，以结果为导向，学习型团队，有助于个人专业能力提升，助力职业发展。\n3.业务团队财务意识强，高度认可财务对于业务的支持价值，配合度高。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3109196067","sourceKey":"meituan_social","company":"美团","title":"收单线下渠道经理","city":"北京市/上海市/广州市/长沙市/南昌市/石家庄市/太原市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3109196067&jobShareType=1","duty":"1、负责属地内合作商的引入，基于业务目标制定属地拓展策略，为合作商培训赋能，指导协助合作商开展业务，充分激发合作商业务的持续增长\n2、负责总部合作商政策的上传下达，传达公司政策及市场活动等信息，引导合作商市场的正向发展，保持顺畅的合作关系\n3、对合作商的团队管理、盈亏状况等方面能给出指导建议，并能在业务运营层面给出有效的落地解决方案\n4、负责管辖区内市场及行业信息收集反馈","requirements":"1、大学专科以上学历，有较好的渠道销售业绩，1年以上saas渠道管理经历；\n2、良好的商务谈判能力，沟通协调能力，能够制定招商规划，对业务结果负责；\n3、具备良好的渠道维护意识，在合作商选、育、用、励、汰环节，具备有效的方法和技巧\n4、能接受区域内长期出差","description":"部门介绍\n美团餐饮系统为餐饮企业提供一站式IT解决方案，帮助餐饮商户实现从供应链管理、生产管理、前厅管理到外卖的数字化经营。美团餐饮系统不仅打通了餐厅和平台，更帮助餐厅连接客人，让商户更了解顾客需求，在帮助商户做商业决策的同时给顾客带来更好的消费体验。\n我们持续建设和提升产研、销售、服务的核心能力，通过全新升级的美团餐饮系统一体化软硬件产品，助力餐饮商户进行线上化经营，帮助商户在推广新店、提升效率、降低成本、会员营销、流量扶持、智慧选址、供应链管理等方面强化经营能力。团队汇集了餐饮和SaaS领域的优秀人才，秉持着“以客户为中心”的初心和“长期有耐心”的耕耘精神，求真、敬畏、敢于自我否定、善于快速学习。期待同样愿意长期致力于餐饮产业数字化、智能化的你加入我们的团队，共同进步共同成长！\n\n岗位职责\n1、负责属地内合作商的引入，基于业务目标制定属地拓展策略，为合作商培训赋能，指导协助合作商开展业务，充分激发合作商业务的持续增长\n2、负责总部合作商政策的上传下达，传达公司政策及市场活动等信息，引导合作商市场的正向发展，保持顺畅的合作关系\n3、对合作商的团队管理、盈亏状况等方面能给出指导建议，并能在业务运营层面给出有效的落地解决方案\n4、负责管辖区内市场及行业信息收集反馈\n\n岗位基本要求\n1、大学专科以上学历，有较好的渠道销售业绩，1年以上saas渠道管理经历；\n2、良好的商务谈判能力，沟通协调能力，能够制定招商规划，对业务结果负责；\n3、具备良好的渠道维护意识，在合作商选、育、用、励、汰环节，具备有效的方法和技巧\n4、能接受区域内长期出差\n\n岗位亮点\n1、销售+管理的工作属性，同序列更高的岗位称重\n2、双晋升通道（管理晋升&专业晋升）\n3、美团上升业务，未来有无限可能","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4708464542","sourceKey":"meituan_social","company":"美团","title":"仓储主管","city":"深圳市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4708464542&jobShareType=1","duty":"负责仓库日常运营管理，包括货物入库、出库、盘点、库存控制及运输协调，确保作业高效有序进行。\n制定并持续优化仓储及物流作业流程，提高运营效率、库存准确率和服务质量。\n负责团队管理与人员调度，包括排班、培训、绩效监督及现场作业管理。\n监督仓库安全管理及合规操作，确保符合公司制度及相关法规要求。\n协同采购、销售、物流等相关部门，保障供应链顺畅运作与交付效率。","requirements":"大专及以上学历，物流管理、仓储管理、运输管理等相关专业优先。\n具备5年以上物流或仓储运营管理经验，熟悉仓储、运输流程及现场管理。\n熟悉WMS等仓储管理系统及常用办公软件操作。\n具备良好的沟通协调能力、团队管理能力及问题解决能力。\n工作认真负责，执行力强，能够适应快节奏工作环境。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n负责仓库日常运营管理，包括货物入库、出库、盘点、库存控制及运输协调，确保作业高效有序进行。\n制定并持续优化仓储及物流作业流程，提高运营效率、库存准确率和服务质量。\n负责团队管理与人员调度，包括排班、培训、绩效监督及现场作业管理。\n监督仓库安全管理及合规操作，确保符合公司制度及相关法规要求。\n协同采购、销售、物流等相关部门，保障供应链顺畅运作与交付效率。\n\n岗位基本要求\n大专及以上学历，物流管理、仓储管理、运输管理等相关专业优先。\n具备5年以上物流或仓储运营管理经验，熟悉仓储、运输流程及现场管理。\n熟悉WMS等仓储管理系统及常用办公软件操作。\n具备良好的沟通协调能力、团队管理能力及问题解决能力。\n工作认真负责，执行力强，能够适应快节奏工作环境。\n\n岗位亮点\n1. 参与核心运营环节，快速积累行业经验。  \n2. 提供系统化培训，助力个人职业发展。  \n3. 团队氛围开放，注重员工成长与反馈。  \n4. 工作地点位于深圳，交通便利。  \n5. 有机会接触前沿物流技术与管理实践。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4785153532","sourceKey":"meituan_social","company":"美团","title":"运输主管","city":"大连市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4785153532&jobShareType=1","duty":"1. 负责大连运输团队日常运营管理，确保运输任务按时高效完成。\n2. 制定并优化运输路线与配送计划，提升运输效率并控制成本。\n3. 协调仓库、调度与客户之间的沟通，处理运输过程中的异常问题。\n4. 监督运输车辆及司机管理，确保合规运营与行车安全。\n5. 定期分析运输数据，提出改进建议并推动执行。","requirements":"1. 大学专科及以上学历，物流、运输或相关专业优先。\n2. 具备5年以上物流运输相关工作经验，有仓储配送管理经验者优先。\n3. 熟悉大连及周边地区路况与交通法规，具备较强的路线规划能力。\n4. 具备良好的沟通协调能力与团队管理能力，能承受一定工作压力。\n5. 熟练使用办公软件及物流管理系统。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1. 负责大连运输团队日常运营管理，确保运输任务按时高效完成。\n2. 制定并优化运输路线与配送计划，提升运输效率并控制成本。\n3. 协调仓库、调度与客户之间的沟通，处理运输过程中的异常问题。\n4. 监督运输车辆及司机管理，确保合规运营与行车安全。\n5. 定期分析运输数据，提出改进建议并推动执行。\n\n岗位基本要求\n1. 大学专科及以上学历，物流、运输或相关专业优先。\n2. 具备5年以上物流运输相关工作经验，有仓储配送管理经验者优先。\n3. 熟悉大连及周边地区路况与交通法规，具备较强的路线规划能力。\n4. 具备良好的沟通协调能力与团队管理能力，能承受一定工作压力。\n5. 熟练使用办公软件及物流管理系统。\n\n岗位亮点\n1. 提供具有竞争力的薪酬与完善的福利体系。\n2. 拥有清晰的职业发展路径与内部晋升机会。\n3. 团队氛围积极，注重员工成长与能力提升。\n4. 工作地点位于大连核心物流区域，交通便利。\n5. 公司提供专业培训和行业资源支持。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4780124321","sourceKey":"meituan_social","company":"美团","title":"仓经理","city":"苏州市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4780124321&jobShareType=1","duty":"1. 负责仓库日常运营管理，包括入库、出库、库存盘点及仓储流程优化。  \n2. 制定并执行仓库管理制度和操作规范，确保作业安全高效。  \n3. 管理仓储团队，进行人员培训、绩效考核及工作安排。  \n4. 监控库存水平，减少损耗，提升仓储空间利用率。  \n5. 协调物流、采购、销售等部门，保障供应链顺畅运行。","requirements":"1. 大学专科及以上学历，物流、供应链或相关专业优先。  \n2. 具备5年以上仓储管理经验，有大型仓库或电商仓储背景者优先。  \n3. 熟悉WMS系统及仓储自动化设备操作。  \n4. 具备较强的团队管理能力和沟通协调能力。  \n5. 工作责任心强，能承受一定工作压力。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1. 负责仓库日常运营管理，包括入库、出库、库存盘点及仓储流程优化。  \n2. 制定并执行仓库管理制度和操作规范，确保作业安全高效。  \n3. 管理仓储团队，进行人员培训、绩效考核及工作安排。  \n4. 监控库存水平，减少损耗，提升仓储空间利用率。  \n5. 协调物流、采购、销售等部门，保障供应链顺畅运行。\n\n岗位基本要求\n1. 大学专科及以上学历，物流、供应链或相关专业优先。  \n2. 具备5年以上仓储管理经验，有大型仓库或电商仓储背景者优先。  \n3. 熟悉WMS系统及仓储自动化设备操作。  \n4. 具备较强的团队管理能力和沟通协调能力。  \n5. 工作责任心强，能承受一定工作压力。\n\n岗位亮点\n1. 位于苏州市，交通便利，工作环境优良。  \n2. 提供完善的培训体系和职业发展通道。  \n3. 团队氛围积极，注重员工成长与关怀。  \n4. 具有市场竞争力的薪酬福利。  \n5. 参与公司核心物流体系建设，发展空间广阔。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4757615638","sourceKey":"meituan_social","company":"美团","title":"酒店供给方向产品经理","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4757615638&jobShareType=1","duty":"1. 负责酒店平台策略制定和产品的规划、设计和迭代；\n2. 与协同部门紧密合作，制定策略，推动产品从需求到上线的全流程落地；\n3. 分析市场供需，行业趋势和市场动态，制定产品策略并优化现有功能。","requirements":"1. 3年以上产品经验，逻辑清晰，基本功扎实，具备独立负责复杂产品的能力；\n2. 有较强的学习能力和业务理解能力，能够快速理解OTA行业运作模式和酒店商家经营逻辑；\n3. 有强烈的主人翁意识，并具有较强的沟通协调能力，能够以目标为导向主动协同协作方配合推进项目落地；\n4. 对新事物有探索欲望和学习意愿，有利用AI能力补全视野，帮助自己提升工作效率的经验。","description":"部门介绍\n美团酒店旅行业务涵盖酒店、民宿、机票、火车票、旅游度假、景点门票等各类住行游品类，通过与产业上下游的深度合作，为用户提供美好的旅游旅行体验。我们积极打造AI友好型组织，使用AI等新技术提升旅游服务的供需匹配效率，更好满足用户个性化、多样化的出游需求。我们持续深耕产业链，用数字化服务助力实体商家高质量经营，探索自有品牌等供给新模式，打造健康的商家生态，保障用户服务体验。为满足用户日益增长的跨境旅行需求，我们将聚焦亚太区域，打造高品质的住宿、交通、游玩等服务矩阵。\n这里有多元的业务布局、持续的成长空间，无论是向往的远方还是眼前的工作，一路都是风景相伴。加入我们，共同为用户创造旅游旅行中的高光时刻！\n\n岗位职责\n1. 负责酒店平台策略制定和产品的规划、设计和迭代；\n2. 与协同部门紧密合作，制定策略，推动产品从需求到上线的全流程落地；\n3. 分析市场供需，行业趋势和市场动态，制定产品策略并优化现有功能。\n\n岗位基本要求\n1. 3年以上产品经验，逻辑清晰，基本功扎实，具备独立负责复杂产品的能力；\n2. 有较强的学习能力和业务理解能力，能够快速理解OTA行业运作模式和酒店商家经营逻辑；\n3. 有强烈的主人翁意识，并具有较强的沟通协调能力，能够以目标为导向主动协同协作方配合推进项目落地；\n4. 对新事物有探索欲望和学习意愿，有利用AI能力补全视野，帮助自己提升工作效率的经验。\n\n具备以下条件优先\n有OTA或电商领域背景者优先\n\n岗位亮点\n1. 该岗位负责制定美团酒店相关策略，发展空间大；\n2. 核心业务，快速增长，团队稳定；\n3. 团队方法论沉淀好，个人学习和成长空间大；\n4. 公司内部提供完善的AI工具和基于AI能力的新工作范式，工作高效。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4500449212","sourceKey":"meituan_social","company":"美团","title":"Procurement Manager – Manpower & Labor Services","city":"利雅得","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4500449212&jobShareType=1","duty":"1、Manage the end-to-end procurement process for manpower and labor services across the Middle East, including needs assessment, supplier screening, contract negotiation, and performance oversight.\n2、Build and maintain partnerships with local and international labor service providers, ensuring service quality and delivery timelines meet company standards.\n3、Analyze market trends and cost structures to develop sourcing strategies, optimize procurement costs, and improve service efficiency.\n4、Collaborate with internal stakeholders to align manpower procurement with operational needs and support smooth project delivery.\n5、Monitor supplier performance, conduct regular evaluations, and drive continuous improvement to ensure compliance and risk control.","requirements":"1、Bachelor's degree or above in Procurement, Supply Chain Management, Human Resources, or a related field.\n5+ years of procurement experience; background in manpower and labor services procurement preferred.\n2、Familiar with labor regulations and the labor services market across the Middle East; strong cross-cultural communication and negotiation skills.\n3、Strong analytical and project management capabilities; proficient in office software and procurement systems.\nFluent in English; Arabic proficiency is a plus. High professional integrity and ability to work under pressure.","description":"部门介绍\n公司事务平台负责构建公司的公共战略体系，助力业务可持续发展及公司对外影响力的提升。通过内外部风险管理，确保公司合规发展；通过深耕公共战略，推动内外良好沟通，连接公司发展与社会期待，助力业务高质量发展；通过管理社会责任议题、公益投入等，助力公司创造更多社会价值；同时为公司提供行政、采购等基础服务。我们坚持“懂业务、拿结果，勇担当、善协同，不唯上、只唯真”的工作理念，期待具有公共战略素养、了解公司治理逻辑的你加入！\n\n岗位职责\n1、Manage the end-to-end procurement process for manpower and labor services across the Middle East, including needs assessment, supplier screening, contract negotiation, and performance oversight.\n2、Build and maintain partnerships with local and international labor service providers, ensuring service quality and delivery timelines meet company standards.\n3、Analyze market trends and cost structures to develop sourcing strategies, optimize procurement costs, and improve service efficiency.\n4、Collaborate with internal stakeholders to align manpower procurement with operational needs and support smooth project delivery.\n5、Monitor supplier performance, conduct regular evaluations, and drive continuous improvement to ensure compliance and risk control.\n\n岗位基本要求\n1、Bachelor's degree or above in Procurement, Supply Chain Management, Human Resources, or a related field.\n5+ years of procurement experience; background in manpower and labor services procurement preferred.\n2、Familiar with labor regulations and the labor services market across the Middle East; strong cross-cultural communication and negotiation skills.\n3、Strong analytical and project management capabilities; proficient in office software and procurement systems.\nFluent in English; Arabic proficiency is a plus. High professional integrity and ability to work under pressure.\n\n岗位亮点\n1、Based in Riyadh, with direct involvement in business expansion across the Middle East market.\n2、Directly support core business operations, offering high strategic value and strong growth potential.\n3、Work on an international platform alongside a multicultural team, broadening your professional skill set.","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4004499220","sourceKey":"meituan_social","company":"美团","title":"医药-区域连锁运营-大客户经理","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4004499220&jobShareType=1","duty":"1、助力医药连锁提升O2O业务运营能力，包含但不限于商品供给、用户增长、流量效率、履约体验、商品营销等，并在合作中建立良好客情关系；\n2、负责对应医药连锁的日常运营管理，对连锁客户在平台经营的GTV等业绩目标结果负责，过程中需要对线上用户用药习惯和需求进行分析，识别商品生意机会，为客户提供定制化商品增长策略；\n3、基于连锁增长策略联动药企及平台资源，对经营投资和效果进行统筹管理，以满足连锁和药企的经营目标；","requirements":"1、本科及以上学历，3年以上医药零售运营相关工作经验；\n2、逻辑性强，善于分析总结，有较强的数据分析能力和业务敏感度；\n3、自我驱动，结果导向，有良好的沟通、表达和跨团队协调能力；\n4、较好项目管理能力，具备主动思考和创造性思维。","description":"部门介绍\n美团医药健康事业部是美团核心本地商业板块下专注健康领域的业务部门，涵盖美团买药、美团医美和美团医疗三大业务。自创立以来，美团医药健康致力于为用户提供全健康周期产品及服务，满足人民群众多层次多元化医疗健康需求，现已覆盖购药到家、居家检测、问诊挂号、医保支付、求医寻院、医疗美容等核心场景。此外，美团医药健康还为商户提供数字化转型创新解决方案，打造贯穿上游的联动机制，长期参与共建更透明、更可持续的医药健康产业生态圈，目前业务已覆盖25万家药店，收录27万家医疗机构。未来，美团医药康将协同更多行业伙伴，帮助大家变得更健康、更美丽、更养生。\n\n岗位职责\n1、助力医药连锁提升O2O业务运营能力，包含但不限于商品供给、用户增长、流量效率、履约体验、商品营销等，并在合作中建立良好客情关系；\n2、负责对应医药连锁的日常运营管理，对连锁客户在平台经营的GTV等业绩目标结果负责，过程中需要对线上用户用药习惯和需求进行分析，识别商品生意机会，为客户提供定制化商品增长策略；\n3、基于连锁增长策略联动药企及平台资源，对经营投资和效果进行统筹管理，以满足连锁和药企的经营目标；\n\n岗位基本要求\n1、本科及以上学历，3年以上医药零售运营相关工作经验；\n2、逻辑性强，善于分析总结，有较强的数据分析能力和业务敏感度；\n3、自我驱动，结果导向，有良好的沟通、表达和跨团队协调能力；\n4、较好项目管理能力，具备主动思考和创造性思维。\n\n具备以下条件优先\n1、有药企新零售或连锁药店商品运营经验优先；\n2、有平台药品经验者优先；\n\n岗位亮点\n1.医药即时零售业务高速发展，业务市场机会大；\n2.团队氛围坦诚直接、能够在学习型组织中快速成长","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4779681468","sourceKey":"meituan_social","company":"美团","title":"整合营销设计师（零售方向）","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4779681468&jobShareType=1","duty":"1.国际市场营销视觉设计，围绕中东及其他国际市场的品牌与营销活动，结合当地市场特征、用户偏好及业务目标，提供专业的视觉判断与设计决策，打造具有差异化和记忆点的营销体验。\n\n2.创意视觉与动效探索，负责境外市场不同业务场景下的创意视觉表达，在扎实的平面设计能力基础上，探索动效、动态视觉及新型内容形式，提升营销内容的吸引力与传播效率。\n\n营销视觉策略制定，持续完善营销活动的视觉风格与设计体系，能够根据不同项目阶段制定设计策略、视觉方向及阶段性目标，并独立输出完整的营销视觉方案。\n\n3.AI 创意设计与效率提升，熟练运用 AIGC 等 AI 设计工具，探索 AI 在创意发散、视觉生成、实景合成及动态内容制作中的应用，并沉淀可复用的工方法或coding实用AI提效设计工具，提升团队创意产能与交付效率。\n\n4.跨团队协作与项目落地，理解业务需求并转化为有效的视觉解决方案，推动创意从概念到最终落地，适配多样且快速变化的业务场景。\n\n5.整体视觉品质把控，统筹画面风格、色彩体系、版式及动画节奏，对项目整体视觉品质负责，在保证品牌一致性的同时提升设计完成度、用户体验及商业传播效果。","requirements":"1.本科及以上学历，视觉传达、数字媒体、动画等相关专业优先；具备 3 年以上整合营销或视觉设计经验，有电商、零售、商超等行业经验者优先。\n\n2.具备良好的审美判断、创意能力与商业思维，能够从业务目标出发进行设计思考，并独立完成从概念、策略到落地的完整设计方案。\n\n3.具备扎实的平面设计基础，熟练使用主流设计及动效工具；熟悉 AIGC 辅助设计、AI 工作流、实景合成或动态视觉制作者优先。\n\n4.对国际化设计趋势保持敏感，具备跨文化视觉理解能力；有中东或其他海外市场项目经验者优先。\n\n5.具备良好的跨团队沟通与协作能力，有较强的项目推进意识和项目管理能力，能够在复杂、多任务的环境中推动项目高质量落地。\n\n6.具备较强的业务理解能力，能够通过专业的设计判断影响项目决策，并通过设计提升品牌认知、用户体验及营销效果。","description":"部门介绍\nKeeta是全球领先外卖平台美团旗下的独立品牌，肩负着“帮大家吃得更好，生活更好”的使命。依托美团深耕中国市场15年的技术与运营积淀，我们正引领全球餐饮与商品即时配送服务的创新与发展。\n\n自2023年成立以来，Keeta始终扎根社区并创造价值。我们为用户提供可靠的外卖体验，以智慧技术助餐厅提升经营效率，在为骑手拓宽收入来源的同时，也充分提供安全保障措施。基于这份多方共赢、共同成长的理念，我们的业务已从中国香港稳步拓展至中东及巴西，并持续向世界迈进。\n\n岗位职责\n1.国际市场营销视觉设计，围绕中东及其他国际市场的品牌与营销活动，结合当地市场特征、用户偏好及业务目标，提供专业的视觉判断与设计决策，打造具有差异化和记忆点的营销体验。\n\n2.创意视觉与动效探索，负责境外市场不同业务场景下的创意视觉表达，在扎实的平面设计能力基础上，探索动效、动态视觉及新型内容形式，提升营销内容的吸引力与传播效率。\n\n营销视觉策略制定，持续完善营销活动的视觉风格与设计体系，能够根据不同项目阶段制定设计策略、视觉方向及阶段性目标，并独立输出完整的营销视觉方案。\n\n3.AI 创意设计与效率提升，熟练运用 AIGC 等 AI 设计工具，探索 AI 在创意发散、视觉生成、实景合成及动态内容制作中的应用，并沉淀可复用的工方法或coding实用AI提效设计工具，提升团队创意产能与交付效率。\n\n4.跨团队协作与项目落地，理解业务需求并转化为有效的视觉解决方案，推动创意从概念到最终落地，适配多样且快速变化的业务场景。\n\n5.整体视觉品质把控，统筹画面风格、色彩体系、版式及动画节奏，对项目整体视觉品质负责，在保证品牌一致性的同时提升设计完成度、用户体验及商业传播效果。\n\n岗位基本要求\n1.本科及以上学历，视觉传达、数字媒体、动画等相关专业优先；具备 3 年以上整合营销或视觉设计经验，有电商、零售、商超等行业经验者优先。\n\n2.具备良好的审美判断、创意能力与商业思维，能够从业务目标出发进行设计思考，并独立完成从概念、策略到落地的完整设计方案。\n\n3.具备扎实的平面设计基础，熟练使用主流设计及动效工具；熟悉 AIGC 辅助设计、AI 工作流、实景合成或动态视觉制作者优先。\n\n4.对国际化设计趋势保持敏感，具备跨文化视觉理解能力；有中东或其他海外市场项目经验者优先。\n\n5.具备良好的跨团队沟通与协作能力，有较强的项目推进意识和项目管理能力，能够在复杂、多任务的环境中推动项目高质量落地。\n\n6.具备较强的业务理解能力，能够通过专业的设计判断影响项目决策，并通过设计提升品牌认知、用户体验及营销效果。\n\n具备以下条件优先\n优异的英语或阿拉伯语能力\n\n岗位亮点\n业务发展快，学习和发展空间大，可接触各国文化。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4778711941","sourceKey":"meituan_social","company":"美团","title":"快乐猴-供应链计划专家","city":"厦门市/成都市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4778711941&jobShareType=1","duty":"1、负责供应链品类计划：结合AI辅助需求预测模型，输出品类备货计划，通过持续提升计划准确度及备货弹性，保障商品稳定供给，提升用户体验；2、负责供应链产品优化：根据不同品类的独特发展需求及特点，借助数据驱动与智能决策手段，建立全链路供应链优化及解决方案，沉淀策略并推进产品化，提升自动化进程；3、负责供应链运营提效：通过管控输入及输出指标，结合智能监控工具实时跟踪库存现货率、周转、库龄，及时提出滞销、断货预警，识别风险点及机会点，提升现有供给链路效率。","requirements":"1、具备创业精神，积极主动，有较强的自驱力；2、熟练掌握各类办公软件及数据分析工具，具有较强的逻辑思考能力、数据分析能力、复杂问题的拆解能力；了解或有使用AI工具（如大模型辅助分析、智能预测平台等）提升工作效率的经验者优先；3、具备沟通、协同、推动影响力，能与算法、产品团队高效协作，共同推进供应链智能化落地。","description":"部门介绍\n快乐猴是美团自营社区超市，依托自有供应链和门店管理体系，聚焦家庭用户的三餐所需，为消费者提供高质价比的食杂商品。快乐猴以数字化能力与科学品控为基础，不断满足消费者对“省”和“便利”的需求。\n\n岗位职责\n1、负责供应链品类计划：结合AI辅助需求预测模型，输出品类备货计划，通过持续提升计划准确度及备货弹性，保障商品稳定供给，提升用户体验；2、负责供应链产品优化：根据不同品类的独特发展需求及特点，借助数据驱动与智能决策手段，建立全链路供应链优化及解决方案，沉淀策略并推进产品化，提升自动化进程；3、负责供应链运营提效：通过管控输入及输出指标，结合智能监控工具实时跟踪库存现货率、周转、库龄，及时提出滞销、断货预警，识别风险点及机会点，提升现有供给链路效率。\n\n岗位基本要求\n1、具备创业精神，积极主动，有较强的自驱力；2、熟练掌握各类办公软件及数据分析工具，具有较强的逻辑思考能力、数据分析能力、复杂问题的拆解能力；了解或有使用AI工具（如大模型辅助分析、智能预测平台等）提升工作效率的经验者优先；3、具备沟通、协同、推动影响力，能与算法、产品团队高效协作，共同推进供应链智能化落地。\n\n具备以下条件优先\n1、具备较强数据统计以及分析能力；\n2、参与过同类型业务，具备多门店库存管理经验优先； \n3、供应链管理、物流管理专业优先； \n4、有生鲜品类计划经验优先。\n\n岗位亮点\n1、供应链智能化转型核心阵地：公司持续投入即时零售供应链AI化建设，你将深度参与需求预测模型优化、智能补货策略落地等前沿课题，所积累的AI+供应链能力将成为行业稀缺竞争力。2、构建更宽广的职业发展图景：有机会全身心参与新零售业态，在高速发展的业务中，与电商、O2O、物流、零售、人工智能等多元化背景的团队协作，在AI与供应链深度融合的环境中持续学习、共同进步，打造独特的跨领域职业优势。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3348332465","sourceKey":"meituan_social","company":"美团","title":"AI型组织架构师","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3348332465&jobShareType=1","duty":"1. 以AI视角重构组织与人才策略\n1）深度理解AI技术的演进规律（大模型、Agent、具身智能等）及其对组织形态、岗位结构、协作模式的颠覆性影响，前瞻性地设计组织演进路线图。\n2）基于\"人机协同\"新范式，重新定义岗位价值链——识别哪些角色将被AI增强、哪些将被重组、哪些需要全新创建，推动组织从\"人力密集型\"向\"智力密集型\"转型。\n3）以经营和数据思维，建立AI时代的人效评估模型，量化AI工具对组织效能的提升，持续优化资源投入产出。\n\n2. 设计AI原生的组织架构与运作机制\n1）打破传统职能制/事业部制的局限，探索并落地适配AI业务的组织形态：敏捷作战单元、跨域融合团队、平台+前台的柔性组织等。\n2）设计AI项目从探索到规模化各阶段的组织支撑方案——探索期的小团队快速试错机制、验证期的跨团队资源协调、规模化期的组织固化与效率优化。\n3）搭建跨业务线的AI协同机制，解决技术能力复用、数据资产共享、模型平台协同等组织层面的卡点。\n\n3. 重塑AI时代的人才管理体系\n1）针对AI人才的特殊性（高稀缺、跨学科、成果周期长、市场定价波动大），设计差异化的评价、激励与发展机制。\n2）推动\"复合型人才\"标准落地——不是简单的\"技术+管理\"，而是\"AI素养+业务洞察+系统思维\"的新型能力模型。\n3）精细化运营人才管理项目，识别硬科技团队中的关键组织问题（技术leader梯队断层、AI人才流失、\"技术孤岛\"等），推动管理者优化提升。\n4）建立AI人才供应链：联动招聘、LD，构建从外部引进、内部转型到持续培养的全链路人才供给体系。\n\n4. 用AI手段革新OD自身的工作方式\n1）引入AI工具赋能组织诊断与决策——用数据驱动组织健康度评估，替代传统的纯经验判断和人工调研。\n2）以产品化思维，沉淀AI时代组织管理的方法论、流程、工具包，持续赋能管理者和BP。\n3）主导前沿组织专项研究（AI对组织形态的影响、全球科技企业组织对标、人机协同的管理范式等），输出可落地的洞察和方案。\n\n5. 推动管理者的AI领导力升级\n1）从理念、方案、落地三个层面，牵头推动管理者对AI的认知对齐和能力升级。\n2）设计管理者的AI素养发展路径——不是\"了解技术\"，而是\"能用AI思维重新定义问题和组织方式\"。\n3）联动OC、LD等，为业务提供组织架构、人才发展、薪酬激励等综合解决方案。","requirements":"1. 核心经验\n有硬科技业务（AI、自动驾驶、机器人、云计算、大模型等）的组织管理实战经验。\n有组织设计、组织诊断、人才盘点、人才发展机制等核心模块的深度落地经验，且能跳出传统方法论，结合技术业务特点创造性地解决问题。\n有推动过组织转型项目经验（如传统业务向AI转型、技术团队的组织重构、研发效能体系搭建等）。\n2. AI与技术理解力\n对AI行业有真实的体感——能理解大模型、Agent、具身智能等方向的基本逻辑，不惧与技术leader深度对话。\n对AI如何改变组织形态、岗位结构、工作方式有自己的思考和判断，而非停留在概念层面。\n本人是AI工具的深度使用者优先——用AI辅助自己的分析、方案设计和决策。\n3. 核心素质\n强自驱力，对\"AI+组织\"这个交叉领域有热情和好奇心，愿意做没有现成答案的事。\n优秀的系统思维和结构化表达能力，能将复杂的组织问题拆解为可执行的行动方案。\n强推动力和落地能力，能在高不确定性、快节奏的技术业务环境中拿到结果。\n善于在技术、产品、业务等不同语言体系间搭桥，有跨团队影响力。","description":"部门介绍\n美团HR的使命是“建设有生命力的组织，为客户和社会创造价值。” 我们认为HR的工作不是以自身“专业”为中心，而是要建设有助于员工发挥创造力的环境，支持他们更好地为外部客户和社会创造价值，也实现组织自身的进化和传承。在这个过程中，我们的每位HR同学都是“业务的战略合作伙伴、组织能力的建设者、美团精神的布道者、员工的成长伙伴”。我们要设计面向长期支撑组织有效运转的机制，我们要求真务实地帮业务解决发展中的问题和阵痛，我们要支持每一位员工历经磨炼收获成长。我们要影响和驱动让世界更美好的变化发生。如果这也是你追求的，欢迎加入美团HR，与我们一路同行！\n\n岗位职责\n1. 以AI视角重构组织与人才策略\n1）深度理解AI技术的演进规律（大模型、Agent、具身智能等）及其对组织形态、岗位结构、协作模式的颠覆性影响，前瞻性地设计组织演进路线图。\n2）基于\"人机协同\"新范式，重新定义岗位价值链——识别哪些角色将被AI增强、哪些将被重组、哪些需要全新创建，推动组织从\"人力密集型\"向\"智力密集型\"转型。\n3）以经营和数据思维，建立AI时代的人效评估模型，量化AI工具对组织效能的提升，持续优化资源投入产出。\n\n2. 设计AI原生的组织架构与运作机制\n1）打破传统职能制/事业部制的局限，探索并落地适配AI业务的组织形态：敏捷作战单元、跨域融合团队、平台+前台的柔性组织等。\n2）设计AI项目从探索到规模化各阶段的组织支撑方案——探索期的小团队快速试错机制、验证期的跨团队资源协调、规模化期的组织固化与效率优化。\n3）搭建跨业务线的AI协同机制，解决技术能力复用、数据资产共享、模型平台协同等组织层面的卡点。\n\n3. 重塑AI时代的人才管理体系\n1）针对AI人才的特殊性（高稀缺、跨学科、成果周期长、市场定价波动大），设计差异化的评价、激励与发展机制。\n2）推动\"复合型人才\"标准落地——不是简单的\"技术+管理\"，而是\"AI素养+业务洞察+系统思维\"的新型能力模型。\n3）精细化运营人才管理项目，识别硬科技团队中的关键组织问题（技术leader梯队断层、AI人才流失、\"技术孤岛\"等），推动管理者优化提升。\n4）建立AI人才供应链：联动招聘、LD，构建从外部引进、内部转型到持续培养的全链路人才供给体系。\n\n4. 用AI手段革新OD自身的工作方式\n1）引入AI工具赋能组织诊断与决策——用数据驱动组织健康度评估，替代传统的纯经验判断和人工调研。\n2）以产品化思维，沉淀AI时代组织管理的方法论、流程、工具包，持续赋能管理者和BP。\n3）主导前沿组织专项研究（AI对组织形态的影响、全球科技企业组织对标、人机协同的管理范式等），输出可落地的洞察和方案。\n\n5. 推动管理者的AI领导力升级\n1）从理念、方案、落地三个层面，牵头推动管理者对AI的认知对齐和能力升级。\n2）设计管理者的AI素养发展路径——不是\"了解技术\"，而是\"能用AI思维重新定义问题和组织方式\"。\n3）联动OC、LD等，为业务提供组织架构、人才发展、薪酬激励等综合解决方案。\n\n岗位基本要求\n1. 核心经验\n有硬科技业务（AI、自动驾驶、机器人、云计算、大模型等）的组织管理实战经验。\n有组织设计、组织诊断、人才盘点、人才发展机制等核心模块的深度落地经验，且能跳出传统方法论，结合技术业务特点创造性地解决问题。\n有推动过组织转型项目经验（如传统业务向AI转型、技术团队的组织重构、研发效能体系搭建等）。\n2. AI与技术理解力\n对AI行业有真实的体感——能理解大模型、Agent、具身智能等方向的基本逻辑，不惧与技术leader深度对话。\n对AI如何改变组织形态、岗位结构、工作方式有自己的思考和判断，而非停留在概念层面。\n本人是AI工具的深度使用者优先——用AI辅助自己的分析、方案设计和决策。\n3. 核心素质\n强自驱力，对\"AI+组织\"这个交叉领域有热情和好奇心，愿意做没有现成答案的事。\n优秀的系统思维和结构化表达能力，能将复杂的组织问题拆解为可执行的行动方案。\n强推动力和落地能力，能在高不确定性、快节奏的技术业务环境中拿到结果。\n善于在技术、产品、业务等不同语言体系间搭桥，有跨团队影响力。\n\n岗位亮点\n1.见证也建设一段互联网知名公司的管理变革历程。\n2.多种业务类型和多元业务场景，对话高级管理者，深入业务推动从理念、方案、到落地，更高更全局的视野。\n3.专业多模块，团队氛围轻松灵活。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4781164009","sourceKey":"meituan_social","company":"美团","title":"产品经理（联盟 C 端产品方向）","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4781164009&jobShareType=1","duty":"1. 负责美团联盟 C 端产品链路建设，覆盖用户从触达、浏览、交易到核销的全交易链路，持续优化转化效率与用户体验，提升联盟渠道的交易规模与用户质量。\n2. 深入理解联盟流量场景与站内承接的运营机制，识别交易链路中的断点与损耗，主导关键转化环节的产品设计与迭代。\n3. 在 AI 背景下探索联盟业务的新产品形态，如智能导购与商品推荐Agent、Skill，定义产品形态与衡量标准，并推动从 MVP 到规模化的落地。\n4. 建立并持续完善 C 端产品的数据指标体系（转化漏斗、用户留存、订单质量、ROI 等），通过数据分析与实验验证驱动产品决策，对核心业务指标负责。\n5. 与运营、研发等团队高效协同，平衡多方诉求，推动复杂链路下的跨端、跨业务线产品方案落地，并跟进上线后的效果回收与迭代。","requirements":"1. 本科及以上学历，5年以上互联网产品经验，有电商、本地生活、导购/CPS 联盟或交易类产品经验者优先。\n2. 对 AI 产品形态有真实的实践或深度思考，理解大模型/Agent 能力边界与工程化落地路径，能将 AI 能力转化为可衡量业务价值的 product。\n3. 具备优秀的抽象与结构化能力，能在多方依赖、链路复杂的场景下理清权责与优先级，有跨团队推进项目的成功经验。","description":"部门介绍\n美团平台为用户的基础产品体验负责，还承担了美团的用户增长、市场和品牌营销以及多条业务线的产品设计职责，建立了融合文字、图片、视频和直播等不同形式的內容生态系统，同时整合地图服务部、客户服务和体验部、企业业务部、网约车业务部等部门，致力于用科技提升美团数亿消费者、近千万商家、骑手、司机和团长的服务体验。美团平台拥有高并发、多业务的复杂场景，为技术深度优化提供了最佳实践可能。这里有简单、讲逻辑、有爱的团队，更是一块理想的实战场地，舞台广阔，欢迎你来尽情施展。\n\n岗位职责\n1. 负责美团联盟 C 端产品链路建设，覆盖用户从触达、浏览、交易到核销的全交易链路，持续优化转化效率与用户体验，提升联盟渠道的交易规模与用户质量。\n2. 深入理解联盟流量场景与站内承接的运营机制，识别交易链路中的断点与损耗，主导关键转化环节的产品设计与迭代。\n3. 在 AI 背景下探索联盟业务的新产品形态，如智能导购与商品推荐Agent、Skill，定义产品形态与衡量标准，并推动从 MVP 到规模化的落地。\n4. 建立并持续完善 C 端产品的数据指标体系（转化漏斗、用户留存、订单质量、ROI 等），通过数据分析与实验验证驱动产品决策，对核心业务指标负责。\n5. 与运营、研发等团队高效协同，平衡多方诉求，推动复杂链路下的跨端、跨业务线产品方案落地，并跟进上线后的效果回收与迭代。\n\n岗位基本要求\n1. 本科及以上学历，5年以上互联网产品经验，有电商、本地生活、导购/CPS 联盟或交易类产品经验者优先。\n2. 对 AI 产品形态有真实的实践或深度思考，理解大模型/Agent 能力边界与工程化落地路径，能将 AI 能力转化为可衡量业务价值的 product。\n3. 具备优秀的抽象与结构化能力，能在多方依赖、链路复杂的场景下理清权责与优先级，有跨团队推进项目的成功经验。\n\n岗位亮点\n1. 业务正处于 AI 重构用户链路的窗口期，有机会定义联盟 C 端在 AI 时代的新产品形态，个人影响力可见度高。\n2. 联盟连接外部媒体渠道与站内交易的独特生态位，天然接触“流量—内容—交易—履约”的全链路视角，可以积累跨端、跨业务线的复杂链路产品能力。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4720528388","sourceKey":"meituan_social","company":"美团","title":"小象超市-蔬菜采购（华中/西南区域）","city":"武汉市/重庆市/南昌市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4720528388&jobShareType=1","duty":"1、相关品类商品开发，制定品类策略和发展方向，完成公司的采购计划和目标；\n2、负责区域供应商的开发与评审，整合区域供应商资源及供货渠道，满足各城市的业务发展需求；\n3、不断优化和完善商品结构，满足不同业态客户的需求，提升品类的综合经营能力；\n4、建立供应体系包括但不限于：合同谈判、供应商管理及考核、成本管控、采购计划等各类流程；\n5、区域采购业务管理，保持与城市的良好沟通协作，改善城市端供应链，持续提升城市销售和毛利水平。","requirements":"1、大学专科及以上学历，具备较好的商品与供应链管理基础知识；\n2、4年以上相关品类采购经验，有专业的商品知识及行业知识；\n3、熟悉采购工作流程，对价格谈判、订单管理、供应商开发等具有丰富的经验；\n4、思路清晰，开展工作有计划性，有良好的执行力；\n5、诚实可靠，积极主动，具备良好的表达能力和沟通能力；\n6、有较强的数据分析能力，熟练掌握计算机操作。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1、相关品类商品开发，制定品类策略和发展方向，完成公司的采购计划和目标；\n2、负责区域供应商的开发与评审，整合区域供应商资源及供货渠道，满足各城市的业务发展需求；\n3、不断优化和完善商品结构，满足不同业态客户的需求，提升品类的综合经营能力；\n4、建立供应体系包括但不限于：合同谈判、供应商管理及考核、成本管控、采购计划等各类流程；\n5、区域采购业务管理，保持与城市的良好沟通协作，改善城市端供应链，持续提升城市销售和毛利水平。\n\n岗位基本要求\n1、大学专科及以上学历，具备较好的商品与供应链管理基础知识；\n2、4年以上相关品类采购经验，有专业的商品知识及行业知识；\n3、熟悉采购工作流程，对价格谈判、订单管理、供应商开发等具有丰富的经验；\n4、思路清晰，开展工作有计划性，有良好的执行力；\n5、诚实可靠，积极主动，具备良好的表达能力和沟通能力；\n6、有较强的数据分析能力，熟练掌握计算机操作。\n\n具备以下条件优先\n1、有大型供应商资源；\n2、有生鲜零售，线上，线下及大型超市采购经验。\n\n岗位亮点\n1、上市公司，平台大，行业整合能力强；\n2、自营重点项目，清晰的晋升路径，发展空间大；\n3、与各类供应商建立广泛的合作关系，拓展行业视角与资源积累。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4745286762","sourceKey":"meituan_social","company":"美团","title":"小象超市 - 禽类采购","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4745286762&jobShareType=1","duty":"1、负责类目的商品规划、采购管理、供应链管理等，为经营结果负责；\n2、负责采购的供应商资源开发及管理，通过供应商谈判获得地采&销售渠道的供应链优化，效能提升；\n3、通过资源整合、品牌谈判、供应链优化等行为综合提升达到利润及效能的提升；\n4、把握市场动态，及时调整资源配置、确保采购的竞争处于优势。具备行业信息收集及行业经验获取能力。","requirements":"1、本科及以上学历，有5年以上肉禽采购经验，有电商、线上业务经验者优先；\n2、对采购业务流程及体系有清晰的认识，对零售行业有很强的预判能力；\n3、擅长供应商寻找和开发经验，可有效管理供应商；\n4、买手型采购专家，具有较强的分析判断、前瞻思维、承压能力和团队合作意识，有采购管理经验；\n5、具备项目统筹能力，能够协调和推进公司各支持部门完成项目落地及后续效率优化；\n6、掌握基本的AI工具，使用工具提升工作流程效率。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1、负责类目的商品规划、采购管理、供应链管理等，为经营结果负责；\n2、负责采购的供应商资源开发及管理，通过供应商谈判获得地采&销售渠道的供应链优化，效能提升；\n3、通过资源整合、品牌谈判、供应链优化等行为综合提升达到利润及效能的提升；\n4、把握市场动态，及时调整资源配置、确保采购的竞争处于优势。具备行业信息收集及行业经验获取能力。\n\n岗位基本要求\n1、本科及以上学历，有5年以上肉禽采购经验，有电商、线上业务经验者优先；\n2、对采购业务流程及体系有清晰的认识，对零售行业有很强的预判能力；\n3、擅长供应商寻找和开发经验，可有效管理供应商；\n4、买手型采购专家，具有较强的分析判断、前瞻思维、承压能力和团队合作意识，有采购管理经验；\n5、具备项目统筹能力，能够协调和推进公司各支持部门完成项目落地及后续效率优化；\n6、掌握基本的AI工具，使用工具提升工作流程效率。\n\n岗位亮点\n能力突出者，晋升为团队管理岗，并在多岗位轮岗。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4507344576","sourceKey":"meituan_social","company":"美团","title":"快乐猴-北京地推主管","city":"北京市/天津市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4507344576&jobShareType=1","duty":"1. 负责所划分门店的获客拉新工作，为站点的订单量达成负责；\n2.负责深入所属站点覆盖的目标小区，收集社区资料，经营社区关系，开发点位，提升渗透率；\n3.负责社区客户的回访、客户交流会的组织和客户消费洞察；\n4.负责BD团队的招聘、培训、管理和绩效考核工作","requirements":"1. 3年以上销售管理经验；\n2. 热爱销售，对互联网公司兴趣强烈；\n3. 注重长远职业发展，有强烈的晋升欲望；\n4. 学习能力强且勤奋努力，吃苦耐劳，执行力强，有较强的进取心;\n5. 精力充沛，具备在压力下出色完成任务的能力。","description":"部门介绍\n快乐猴是美团自营社区超市，依托自有供应链和门店管理体系，聚焦家庭用户的三餐所需，为消费者提供高质价比的食杂商品。快乐猴以数字化能力与科学品控为基础，不断满足消费者对“省”和“便利”的需求。\n\n岗位职责\n1. 负责所划分门店的获客拉新工作，为站点的订单量达成负责；\n2.负责深入所属站点覆盖的目标小区，收集社区资料，经营社区关系，开发点位，提升渗透率；\n3.负责社区客户的回访、客户交流会的组织和客户消费洞察；\n4.负责BD团队的招聘、培训、管理和绩效考核工作\n\n岗位基本要求\n1. 3年以上销售管理经验；\n2. 热爱销售，对互联网公司兴趣强烈；\n3. 注重长远职业发展，有强烈的晋升欲望；\n4. 学习能力强且勤奋努力，吃苦耐劳，执行力强，有较强的进取心;\n5. 精力充沛，具备在压力下出色完成任务的能力。\n\n岗位亮点\n1. 成长空间：有机会接受美团的培养，经过学习，实践，指导，成为中国互联网的重要成员；\n2. 发展前景：该岗位为核心管理岗位，为日后重点的人才储备","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3155371276","sourceKey":"meituan_social","company":"美团","title":"Fresh Category Manager","city":"利雅得/迪拜/科威特城","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3155371276&jobShareType=1","duty":"1.Manage and oversee specific fresh category (fruits, vegetables, meat, seafood, dairy),developing category strategies and procurement plans;\n2.Analyze market trends, consumer demand, and competition to optimize product assortment and improve sales and profitability;\n3.Handle supply chain management, establish strong relationships with suppliers, conduct procurement negotiations, control costs, and optimize supply channels;\n4.Monitor inventory and product turnover, develop promotional strategies to enhance inventory turnover and reduce waste;\n5.Collaborate with various departments (e.g., procurement, logistics, marketing) to ensure smooth product supply, quality, and market promotion;\n6.Stay updated on industry trends, policies, and regulations to ensure business compliance and continuously optimize procurement and operational processes;\n7.Lead and train the team to enhance professional capabilities and work efficiency.","requirements":"1.Bachelor’s degree or above, preferably in marketing, supply chain management, food science, or related fields.\nAt least 5 years of experience in category management or procurement in the fresh food industry, preferably in retail,  quick commerce (Q-commerce),e-commerce, or supermarkets/hypermarkets\n2.Strong understanding of market trends, supply chain systems, and category management methods in the fresh food industry.\n3.Excellent negotiation, data analysis, and market insight skills.\n4.Strong communication, coordination, and team management experience.\n5.High sense of responsibility, strong ability to work under pressure, and keen business acumen with an innovative mindset.","description":"部门介绍\n美团的使命是“帮大家吃得更好，生活更好”，公司聚焦“零售 + 科技”战略，和广大商户与各类合作伙伴一起，努力为消费者提供品质生活，推动商品零售和服务零售在需求侧和供给侧的数字化转型。\n2018年9月20日，美团正式在港交所挂牌上市。美团将始终坚持以客户为中心，不断加大在科技研发方面的投入，更好承担社会责任，更多创造社会价值，与广大合作伙伴一起发展共赢。\n\n岗位职责\n1.Manage and oversee specific fresh category (fruits, vegetables, meat, seafood, dairy),developing category strategies and procurement plans;\n2.Analyze market trends, consumer demand, and competition to optimize product assortment and improve sales and profitability;\n3.Handle supply chain management, establish strong relationships with suppliers, conduct procurement negotiations, control costs, and optimize supply channels;\n4.Monitor inventory and product turnover, develop promotional strategies to enhance inventory turnover and reduce waste;\n5.Collaborate with various departments (e.g., procurement, logistics, marketing) to ensure smooth product supply, quality, and market promotion;\n6.Stay updated on industry trends, policies, and regulations to ensure business compliance and continuously optimize procurement and operational processes;\n7.Lead and train the team to enhance professional capabilities and work efficiency.\n\n岗位基本要求\n1.Bachelor’s degree or above, preferably in marketing, supply chain management, food science, or related fields.\nAt least 5 years of experience in category management or procurement in the fresh food industry, preferably in retail,  quick commerce (Q-commerce),e-commerce, or supermarkets/hypermarkets\n2.Strong understanding of market trends, supply chain systems, and category management methods in the fresh food industry.\n3.Excellent negotiation, data analysis, and market insight skills.\n4.Strong communication, coordination, and team management experience.\n5.High sense of responsibility, strong ability to work under pressure, and keen business acumen with an innovative mindset.\n\n岗位亮点\nAs a Fresh Food Category Manager, you will drive rapid business growth by spearheading new initiatives and enhancing your international perspective.","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4761785779","sourceKey":"meituan_social","company":"美团","title":"连锁业务专家","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4761785779&jobShareType=1","duty":"1.负责连锁KA的平台规则设计，包括合作准入、激励机制、考核政策等核心规则的制定与迭代\n2.负责连锁KA的产品策略设计，协同产品团队推动连锁专属功能与工具的规划与落地\n3.负责连锁KA的资源策略设计，包括平台资源分配、补贴政策、流量扶持等机制设计\n4.设计直营与下沉合作商的合作机制，明确分工与协同模式，确保直营KA品牌经理高效执行\n5.通过机制设计撬动品牌在营销、供给、活动等方面的投入，提升连锁商户的活跃度与GTV贡献\n6.利用AI工具提升机制设计效率，通过AI Agent辅助规则模拟、机制效果预测和数据分析，将AI融入日常决策","requirements":"1.具备业务经营意识，能为连锁业务在下沉市场的增长、竞争、盈亏负责\n2.3年以上平台规则设计、产品策略或KA管理相关经验，有大型平台KA机制设计经验者优先\n3.具备业务负责人视角，能从平台机制高度思考问题，擅长通过规则和机制撬动业务增长\n4.有直营团队联动经验，理解直营的协作模式，能设计高效的分工合作机制\n5.具备较强的机制设计能力与产品思维，能设计可落地的规则、政策与激励方案\n6.具备较强的数据分析能力，能通过数据评估机制效果并持续迭代\n7.对AI工具在机制设计中的应用有敏感度，愿意用AI提升决策质量和效率","description":"部门介绍\n美团核心本地商业-下沉市场发展部于2015年成立，通过招募优质的合作商伙伴并对其业务经营能力、组织能力等赋能，以期为下沉城市提供一站式的本地生活服务。\n下沉市场发展部的业务场景涵盖了外卖餐饮、团购、拼好饭、闪购、医药等多元化的生活服务领域，同时搭建了一套稳定、高效的即时配送网络，为更多本地用户提供品质化、多样化、便捷高效的生活服务体验，为当地商户提供数字化发展机遇、提升数字化水平，为社会创造更多的就地就业机会。\n截至2024年6月，下沉市场发展部已开拓全国4000+县区市，帮助百万商户实现本地生活服务数字化，日订单量突破千万，为数十万名骑手提供就业岗位，让本地生活服务逐渐成长为地方新基建，实现美团“帮助大家吃得更好，生活更好”的使命！\n\n岗位职责\n1.负责连锁KA的平台规则设计，包括合作准入、激励机制、考核政策等核心规则的制定与迭代\n2.负责连锁KA的产品策略设计，协同产品团队推动连锁专属功能与工具的规划与落地\n3.负责连锁KA的资源策略设计，包括平台资源分配、补贴政策、流量扶持等机制设计\n4.设计直营与下沉合作商的合作机制，明确分工与协同模式，确保直营KA品牌经理高效执行\n5.通过机制设计撬动品牌在营销、供给、活动等方面的投入，提升连锁商户的活跃度与GTV贡献\n6.利用AI工具提升机制设计效率，通过AI Agent辅助规则模拟、机制效果预测和数据分析，将AI融入日常决策\n\n岗位基本要求\n1.具备业务经营意识，能为连锁业务在下沉市场的增长、竞争、盈亏负责\n2.3年以上平台规则设计、产品策略或KA管理相关经验，有大型平台KA机制设计经验者优先\n3.具备业务负责人视角，能从平台机制高度思考问题，擅长通过规则和机制撬动业务增长\n4.有直营团队联动经验，理解直营的协作模式，能设计高效的分工合作机制\n5.具备较强的机制设计能力与产品思维，能设计可落地的规则、政策与激励方案\n6.具备较强的数据分析能力，能通过数据评估机制效果并持续迭代\n7.对AI工具在机制设计中的应用有敏感度，愿意用AI提升决策质量和效率\n\n具备以下条件优先\n有KA/CKA平台业务策略经验优先\n\n岗位亮点\n1.整合直营+合作商双重资源，撬动效应显著\n2.深度参与AI在客户管理中的前沿实践","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4783390872","sourceKey":"meituan_social","company":"美团","title":"自有品牌标准岗","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4783390872&jobShareType=1","duty":"1、负责标准体系搭建与落地：依据国家食品安全标准、餐饮B端流通标准及快驴自有品牌定位，独立搭建、修订并完善冻品全品类品质标准，涵盖原料验收、生产工艺、冷链仓储、出厂检验、退换货品质及标签合规等全套SOP文件；\n2、负责供应商全生命周期品质管理：统筹冻品自有品牌供应商的准入审核、现场稽核、首批跟产、年度评级及汰换迭代等全流程管理；\n3、负责异常问题定位与闭环处理：针对批次性品质异常、客诉质量问题及市场抽检不合格情况，开展根因溯源，制定并监督整改方案落实，有效规避批量性品质事故和合规风险；\n4、探索品质最佳实践调研与优化：持续追踪行业新工艺、质控技术、冷链管理方案及合规标准，结合快驴自有品牌业务场景，拆解并转化适配的品控机制，推动品质体系持续迭代升级。","requirements":"1、本科及以上学历，食品科学与工程、食品安全、农产品加工、供应链管理等相关专业；\n2、三年及以上自有品牌品控、供应商管理经验，熟悉B端餐饮供应链食材电商平台业务模式；\n3、熟悉速冻米面、调理制品、冻肉水产等全品类加工工艺及品质控制要点。","description":"部门介绍\n快驴进货是美团旗下的餐饮供应链平台，帮助餐饮商户以更低成本、更高效率来获取安全可靠的食材供应，让餐饮采购更简单。快驴进货同步发展“自营+平台”的业务模式，在采购环节一方面向上游供应商直采大宗商品，另一方面引入各地批发商，助力平台伙伴共同发展；在销售环节既有自建团队进行市场、客户拓展，又帮助各地批发商拓展业务；同时自建仓储管理系统、配送网络与团队，为客户提供优质履约服务。\n截至2022年，快驴进货布局了全国41个城市，为百万家商户提供“全、省、稳、好”的餐饮供应链服务。我们拥有3000+品牌食材、超5万SKU商品、超28万商品资质，并提供源头严审核、食品安全严把关、24小时无忧售后的全面保障，实现手机下单、送货上门的高效采购模式，帮百万商家节省了采购时间与成本，助力平台伙伴共同发展，在万亿市场共享机遇。\n在这里，你将收获完善的员工发展机制及学习体系，与各界专家一起深度参与餐饮供应链业务的发展。欢迎优秀的你加入美团快驴进货，与我们一起成长，一起更好！\n\n岗位职责\n1、负责标准体系搭建与落地：依据国家食品安全标准、餐饮B端流通标准及快驴自有品牌定位，独立搭建、修订并完善冻品全品类品质标准，涵盖原料验收、生产工艺、冷链仓储、出厂检验、退换货品质及标签合规等全套SOP文件；\n2、负责供应商全生命周期品质管理：统筹冻品自有品牌供应商的准入审核、现场稽核、首批跟产、年度评级及汰换迭代等全流程管理；\n3、负责异常问题定位与闭环处理：针对批次性品质异常、客诉质量问题及市场抽检不合格情况，开展根因溯源，制定并监督整改方案落实，有效规避批量性品质事故和合规风险；\n4、探索品质最佳实践调研与优化：持续追踪行业新工艺、质控技术、冷链管理方案及合规标准，结合快驴自有品牌业务场景，拆解并转化适配的品控机制，推动品质体系持续迭代升级。\n\n岗位基本要求\n1、本科及以上学历，食品科学与工程、食品安全、农产品加工、供应链管理等相关专业；\n2、三年及以上自有品牌品控、供应商管理经验，熟悉B端餐饮供应链食材电商平台业务模式；\n3、熟悉速冻米面、调理制品、冻肉水产等全品类加工工艺及品质控制要点。\n\n具备以下条件优先\n具备冻品工厂品控、SQE、自有品牌标准搭建或供应商稽核评级经验者优先。\n\n岗位亮点\n1、作为品控标准专家，将有机会参与公司品控体系的建设和优化，对公司产品质量起到关键作用。\n\n 2、深度参与平台质量管理策略和治理规则的制定，可学习并积累行业质量控制体系建设经验。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4614003351","sourceKey":"meituan_social","company":"美团","title":"Picker Strategy Operations","city":"科威特城","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4614003351&jobShareType=1","duty":"一、负责 Picker 全链路战略规划与体系建设，主导拣选流程 SOP 的从零搭建与持续迭代，包括拣选标准、作业规范、异常处理流程、品质管控节点等，确保体系可复制、可扩展至 Hypermarket 及多业态场景，而非局限于单店层面的执行管理。\nResponsible for the strategic planning and system-building of the entire Picker workflow, leading the development and continuous iteration of picking SOPs from scratch, including picking standards, operational procedures, exception handling protocols, and quality control checkpoints. Ensure the system is replicable and scalable across Hypermarket and multi-format scenarios, rather than limited to single-store execution management.\n\n二、负责 3PL 合作的端到端管理，涵盖供应商筛选准入、服务协议与 SLA 谈判签订、定价合理性监控与分析、产能调配与冗余管理、合作绩效定期评估，后续需统筹管理数十家 3PL 公司，建立分层分级管理机制，确保履约产能稳定且成本结构合理。\nManage the end-to-end 3PL partnership lifecycle, covering vendor screening and onboarding, service agreement and SLA negotiation, pricing rationality monitoring and analysis, capacity allocation and redundancy management, and periodic performance reviews. Scale to manage dozens of 3PL companies, establishing a tiered management framework to ensure fulfillment capacity stability and reasonable cost structures.\n\n三、主导 Picker 考核与治理体系的搭建，建立涵盖效率、质量、准时、满意度等多维度的核心 KPI 框架，制定明确的预警机制（如连续不达标自动预警）、整改流程、清退标准与执行路径，同时建立 3PL 层面的扣款机制与奖惩制度，将制度固化并形成可执行的运营手册。\nLead the design and implementation of the Picker performance and governance system, building a multi-dimensional core KPI framework covering efficiency, quality, on-time performance, and satisfaction. Establish clear warning mechanisms (e.g., automatic alerts for consecutive substandard performance), rectification processes, termination standards and execution paths, and formulate 3PL-level penalty mechanisms and incentive systems. Codify these into executable operational manuals.\n\n四、负责 Picker 定价策略的制定与优化，基于履约成本结构、市场水平、商家需求与产\n能供需关系等多维因素，建立科学的定价模型，对 3PL 报价进行合理性分析与审核，确保定价既有竞争力又可持续。\nFormulate and optimize Picker pricing strategies based on multi-dimensional factors including fulfillment cost structures, market competition, merchant demands, and capacity supply-demand dynamics. Build a scientific pricing model, and conduct rationality analysis and review of 3PL quotations to ensure pricing is both competitive and sustainable.\n\n五、搭建并持续优化履约全链路核心指标监控体系，覆盖从用户下单→商家接单→商品拣选→打包→配送→送达→售后的完整链路，包括订单取消率、准时率、缺货率、完单率、退款率、用户/商家满意度、投诉率等，建立异常自动识别与闭环解决机制。\nEstablish and continuously optimize the core KPI monitoring system for the end-to-end fulfillment process, covering the complete chain from user ordering → merchant accepting order → item picking → packaging → delivery → delivery confirmation → after-sales service, including order cancellation rate, on-time rate, stock-out rate, completion rate, refund rate, user/merchant satisfaction, complaint rate, etc. Build automated anomaly identification and closed-loop resolution mechanisms.\n\n六、重点协同客服部门与配送部门，建立跨部门协同机制：对接客服团队推动客诉问题分类与根因分析，协同配送团队优化配送时效与履约效率，确保端到端用户体验达标。定期组织巡店与一线调研，深入 Hypermarket 及 Dark Store 识别履约流程问题并推动优化落地。\nCollaborate closely with Customer Service and Delivery departments to establish cross-departmental coordination mechanisms: interface with customer service teams to drive issue classification and root cause analysis, collaborate with delivery teams to optimize delivery timeliness and fulfillment efficiency, ensuring end-to-end user experience standards are met. Regularly organize store inspections and frontline research, visiting Hypermarkets and Dark Stores to identify fulfillment process issues and drive optimization implementation.","requirements":"一、具备 5 年以上零售/电商履约运营或供应链管理经验，有从零搭建运营体系或 SOP 的实操经验，能清晰区分并适应 Hypermarket 与 Dark Store 不同业态的履约逻辑差异。\n5+ years of experience in retail/e-commerce fulfillment operations or supply chain management, with hands-on experience in building operational systems or SOPs from scratch. Ability to clearly differentiate and adapt to the different fulfillment logics of Hypermarket versus Dark Store formats.\n\n二、具备 3PL 供应商管理经验，包括但不限于合同谈判、SLA 制定、绩效评估、产能规划与成本分析，有管理多供应商（10 家以上）并行运营经验者优先。\nExperience in 3PL vendor management, including but not limited to contract negotiation, SLA formulation, performance evaluation, capacity planning, and cost analysis. Experience managing multiple vendors (10+) in parallel operations is preferred.\n\n三、具备数据驱动的决策能力，能独立设计 KPI 框架与考核制度，有将指标体系落地为可执行管理制度（预警、清退、扣款等）的实际经验。\nData-driven decision-making capability, with the ability to independently design KPI frameworks and assessment systems, and practical experience in translating metric systems into executable governance mechanisms (warnings, terminations, penalties, etc.).\n\n四、具备跨部门协同与推动能力，能高效对接客服、配送、产品、技术等团队，推动复杂问题的闭环解决。\nStrong cross-departmental collaboration and driving capability, able to efficiently coordinate with customer service, delivery, product, and technology teams to drive closed-loop resolution of complex issues.\n\n五、具备一线履约人员管理经验，有 Picker、Raider 或 Driver 管理背景均可，核心要求是具备对一线履约人员的大规模团队管理思路与体系化治理能力，而非仅限单店或小团队的人员调度。\nExperience in managing frontline fulfillment personnel, with a background in managing Pickers, Raiders, or Drivers all acceptable. The core requirement is the ability to manage large-scale frontline teams with a systematic governance approach, rather than being limited to single-store or small-team personnel scheduling","description":"部门介绍\nKeeta是全球领先外卖平台美团旗下的独立品牌，肩负着“帮大家吃得更好，生活更好”的使命。依托美团深耕中国市场15年的技术与运营积淀，我们正引领全球餐饮与商品即时配送服务的创新与发展。\n\n自2023年成立以来，Keeta始终扎根社区并创造价值。我们为用户提供可靠的外卖体验，以智慧技术助餐厅提升经营效率，在为骑手拓宽收入来源的同时，也充分提供安全保障措施。基于这份多方共赢、共同成长的理念，我们的业务已从中国香港稳步拓展至中东及巴西，并持续向世界迈进。\n\n岗位职责\n一、负责 Picker 全链路战略规划与体系建设，主导拣选流程 SOP 的从零搭建与持续迭代，包括拣选标准、作业规范、异常处理流程、品质管控节点等，确保体系可复制、可扩展至 Hypermarket 及多业态场景，而非局限于单店层面的执行管理。\nResponsible for the strategic planning and system-building of the entire Picker workflow, leading the development and continuous iteration of picking SOPs from scratch, including picking standards, operational procedures, exception handling protocols, and quality control checkpoints. Ensure the system is replicable and scalable across Hypermarket and multi-format scenarios, rather than limited to single-store execution management.\n\n二、负责 3PL 合作的端到端管理，涵盖供应商筛选准入、服务协议与 SLA 谈判签订、定价合理性监控与分析、产能调配与冗余管理、合作绩效定期评估，后续需统筹管理数十家 3PL 公司，建立分层分级管理机制，确保履约产能稳定且成本结构合理。\nManage the end-to-end 3PL partnership lifecycle, covering vendor screening and onboarding, service agreement and SLA negotiation, pricing rationality monitoring and analysis, capacity allocation and redundancy management, and periodic performance reviews. Scale to manage dozens of 3PL companies, establishing a tiered management framework to ensure fulfillment capacity stability and reasonable cost structures.\n\n三、主导 Picker 考核与治理体系的搭建，建立涵盖效率、质量、准时、满意度等多维度的核心 KPI 框架，制定明确的预警机制（如连续不达标自动预警）、整改流程、清退标准与执行路径，同时建立 3PL 层面的扣款机制与奖惩制度，将制度固化并形成可执行的运营手册。\nLead the design and implementation of the Picker performance and governance system, building a multi-dimensional core KPI framework covering efficiency, quality, on-time performance, and satisfaction. Establish clear warning mechanisms (e.g., automatic alerts for consecutive substandard performance), rectification processes, termination standards and execution paths, and formulate 3PL-level penalty mechanisms and incentive systems. Codify these into executable operational manuals.\n\n四、负责 Picker 定价策略的制定与优化，基于履约成本结构、市场水平、商家需求与产\n能供需关系等多维因素，建立科学的定价模型，对 3PL 报价进行合理性分析与审核，确保定价既有竞争力又可持续。\nFormulate and optimize Picker pricing strategies based on multi-dimensional factors including fulfillment cost structures, market competition, merchant demands, and capacity supply-demand dynamics. Build a scientific pricing model, and conduct rationality analysis and review of 3PL quotations to ensure pricing is both competitive and sustainable.\n\n五、搭建并持续优化履约全链路核心指标监控体系，覆盖从用户下单→商家接单→商品拣选→打包→配送→送达→售后的完整链路，包括订单取消率、准时率、缺货率、完单率、退款率、用户/商家满意度、投诉率等，建立异常自动识别与闭环解决机制。\nEstablish and continuously optimize the core KPI monitoring system for the end-to-end fulfillment process, covering the complete chain from user ordering → merchant accepting order → item picking → packaging → delivery → delivery confirmation → after-sales service, including order cancellation rate, on-time rate, stock-out rate, completion rate, refund rate, user/merchant satisfaction, complaint rate, etc. Build automated anomaly identification and closed-loop resolution mechanisms.\n\n六、重点协同客服部门与配送部门，建立跨部门协同机制：对接客服团队推动客诉问题分类与根因分析，协同配送团队优化配送时效与履约效率，确保端到端用户体验达标。定期组织巡店与一线调研，深入 Hypermarket 及 Dark Store 识别履约流程问题并推动优化落地。\nCollaborate closely with Customer Service and Delivery departments to establish cross-departmental coordination mechanisms: interface with customer service teams to drive issue classification and root cause analysis, collaborate with delivery teams to optimize delivery timeliness and fulfillment efficiency, ensuring end-to-end user experience standards are met. Regularly organize store inspections and frontline research, visiting Hypermarkets and Dark Stores to identify fulfillment process issues and drive optimization implementation.\n\n岗位基本要求\n一、具备 5 年以上零售/电商履约运营或供应链管理经验，有从零搭建运营体系或 SOP 的实操经验，能清晰区分并适应 Hypermarket 与 Dark Store 不同业态的履约逻辑差异。\n5+ years of experience in retail/e-commerce fulfillment operations or supply chain management, with hands-on experience in building operational systems or SOPs from scratch. Ability to clearly differentiate and adapt to the different fulfillment logics of Hypermarket versus Dark Store formats.\n\n二、具备 3PL 供应商管理经验，包括但不限于合同谈判、SLA 制定、绩效评估、产能规划与成本分析，有管理多供应商（10 家以上）并行运营经验者优先。\nExperience in 3PL vendor management, including but not limited to contract negotiation, SLA formulation, performance evaluation, capacity planning, and cost analysis. Experience managing multiple vendors (10+) in parallel operations is preferred.\n\n三、具备数据驱动的决策能力，能独立设计 KPI 框架与考核制度，有将指标体系落地为可执行管理制度（预警、清退、扣款等）的实际经验。\nData-driven decision-making capability, with the ability to independently design KPI frameworks and assessment systems, and practical experience in translating metric systems into executable governance mechanisms (warnings, terminations, penalties, etc.).\n\n四、具备跨部门协同与推动能力，能高效对接客服、配送、产品、技术等团队，推动复杂问题的闭环解决。\nStrong cross-departmental collaboration and driving capability, able to efficiently coordinate with customer service, delivery, product, and technology teams to drive closed-loop resolution of complex issues.\n\n五、具备一线履约人员管理经验，有 Picker、Raider 或 Driver 管理背景均可，核心要求是具备对一线履约人员的大规模团队管理思路与体系化治理能力，而非仅限单店或小团队的人员调度。\nExperience in managing frontline fulfillment personnel, with a background in managing Pickers, Raiders, or Drivers all acceptable. The core requirement is the ability to manage large-scale frontline teams with a systematic governance approach, rather than being limited to single-store or small-team personnel scheduling\n\n具备以下条件优先\n海外市场经验者优先\n\n岗位亮点\n从零到一参与业务，一起创造海外闪购的星辰大海\nJoin us to construct the overseas Grocery business from zero to one, and sail toward the boundless prospects of our business future together.","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4745361271","sourceKey":"meituan_social","company":"美团","title":"Experience Operation Specialist","city":"科威特城","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4745361271&jobShareType=1","duty":"体验看板搭建及监控：根据策略搭建体验看板，并对异常数据进行原因分析及下钻，输出分析报告\n\nExperience dashboard setup and monitoring: Build experience dashboards based on governance strategies, conduct root cause analysis and drill-down on anomalous data, and produce analysis reports.\n\n线下服务案例纠纷处理：负责线下服务态度类客诉纠纷处理\n\nOffline service dispute resolution: Responsible for handling customer complaints and disputes related to offline service attitude.\n\n商家营业保障：建立营业率盯盘机制，缺货率治理Merchant operations assurance: Establish a monitoring mechanism for store operation rates and manage out-of-stock rate governance.\n\n商责取消率管控：监控商责取消率，及时跟前线同事沟通解决取消率异常问题\n\nMerchant liability cancellation rate control: Monitor the merchant-fault cancellation rate, and promptly communicate with frontline colleagues to resolve abnormal cancellation rate issues.","requirements":"本科及以上学历，2年以上电商平台、即时零售或外卖行业运营经验，有体验看板搭建或数据监控相关经验者优先 Bachelor's degree or above, with 2+ years of experience in operations within e-commerce platforms, instant retail, or food delivery sectors; prior experience in experience dashboard development or data monitoring is preferred\n\n具备扎实的SQL能力，能够独立完成数据查询、多表关联及指标计算，熟练使用数据可视化工具搭建监控看板 Solid SQL skills with the ability to independently perform data queries, multi-table joins, and metric calculations; proficient in data visualization tools for building monitoring dashboards\n\n具备较强的数据敏感度与下钻诊断能力，能够追踪异常数据并分解根因，输出分析报告驱动运营决策 Strong data sensitivity and drill-down diagnostic skills, with the ability to track anomalous data, decompose root causes, and produce analysis reports that drive operational decisions\n\n具备线下服务纠纷处理经验，熟悉客诉处理流程，能够独立应对服务态度类投诉并推动闭环解决 Experience in offline service dispute resolution, familiar with customer complaint handling processes, with the ability to independently handle service attitude-related complaints and drive closed-loop resolution\n\n具备跨部门协作与沟通能力，能够与前线团队高效协同解决取消率、缺货率等异常问题；英语可作为工作语言熟练使用 Strong cross-functional collaboration and communication skills, with the ability to work efficiently with frontline teams to resolve anomalies in cancellation rate, out-of-stock rate, and other issues; strong English language proficiency as a working language","description":"部门介绍\nKeeta是全球领先外卖平台美团旗下的独立品牌，肩负着“帮大家吃得更好，生活更好”的使命。依托美团深耕中国市场15年的技术与运营积淀，我们正引领全球餐饮与商品即时配送服务的创新与发展。\n\n自2023年成立以来，Keeta始终扎根社区并创造价值。我们为用户提供可靠的外卖体验，以智慧技术助餐厅提升经营效率，在为骑手拓宽收入来源的同时，也充分提供安全保障措施。基于这份多方共赢、共同成长的理念，我们的业务已从中国香港稳步拓展至中东及巴西，并持续向世界迈进。\n\n岗位职责\n体验看板搭建及监控：根据策略搭建体验看板，并对异常数据进行原因分析及下钻，输出分析报告\n\nExperience dashboard setup and monitoring: Build experience dashboards based on governance strategies, conduct root cause analysis and drill-down on anomalous data, and produce analysis reports.\n\n线下服务案例纠纷处理：负责线下服务态度类客诉纠纷处理\n\nOffline service dispute resolution: Responsible for handling customer complaints and disputes related to offline service attitude.\n\n商家营业保障：建立营业率盯盘机制，缺货率治理Merchant operations assurance: Establish a monitoring mechanism for store operation rates and manage out-of-stock rate governance.\n\n商责取消率管控：监控商责取消率，及时跟前线同事沟通解决取消率异常问题\n\nMerchant liability cancellation rate control: Monitor the merchant-fault cancellation rate, and promptly communicate with frontline colleagues to resolve abnormal cancellation rate issues.\n\n岗位基本要求\n本科及以上学历，2年以上电商平台、即时零售或外卖行业运营经验，有体验看板搭建或数据监控相关经验者优先 Bachelor's degree or above, with 2+ years of experience in operations within e-commerce platforms, instant retail, or food delivery sectors; prior experience in experience dashboard development or data monitoring is preferred\n\n具备扎实的SQL能力，能够独立完成数据查询、多表关联及指标计算，熟练使用数据可视化工具搭建监控看板 Solid SQL skills with the ability to independently perform data queries, multi-table joins, and metric calculations; proficient in data visualization tools for building monitoring dashboards\n\n具备较强的数据敏感度与下钻诊断能力，能够追踪异常数据并分解根因，输出分析报告驱动运营决策 Strong data sensitivity and drill-down diagnostic skills, with the ability to track anomalous data, decompose root causes, and produce analysis reports that drive operational decisions\n\n具备线下服务纠纷处理经验，熟悉客诉处理流程，能够独立应对服务态度类投诉并推动闭环解决 Experience in offline service dispute resolution, familiar with customer complaint handling processes, with the ability to independently handle service attitude-related complaints and drive closed-loop resolution\n\n具备跨部门协作与沟通能力，能够与前线团队高效协同解决取消率、缺货率等异常问题；英语可作为工作语言熟练使用 Strong cross-functional collaboration and communication skills, with the ability to work efficiently with frontline teams to resolve anomalies in cancellation rate, out-of-stock rate, and other issues; strong English language proficiency as a working language\n\n岗位亮点\n从零到一参与业务，一起创造海外闪购的星辰大海\nJoin us to construct the overseas Grocery business from zero to one, and sail toward the boundless prospects of our business future together.","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4378750324","sourceKey":"meituan_social","company":"美团","title":"快乐猴-门店经营分析","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4378750324&jobShareType=1","duty":"1. 经营分析与诊断：定期汇总并分析门店销售数据，输出经营分析报告，追踪门店核心经营指标（营业额、客单价、客流量、转化率等），识别异常波动并提出预警；\n2. 归因分析与赋能：通过深度经营分析、数据挖掘和行业研究，定位业务问题与增长机会，输出可执行的策略建议，对高/低绩效门店进行差异化归因分析，提炼可复用的增长经验；\n3. 专项牵头与落地实践：推进关键复杂专项，如新品上线分析、区域市场分析等，解决跨团队协作中的瓶颈问题，推动闭环管理，实现从策略到实践的高效转化；\n4. 跨部门协作：与财务、商品、供应链、商分以及前线团队等部门协作，推动跨团队成果落地，确保业务目标达成，为门店店长、区域负责人提供数据解读支持，辅助业务决策。","requirements":"1. 本科及以上学历，统计学、数学、经济学等相关专业优先；\n2. 3年以上数据分析相关工作经验，极强的数据分析和逻辑推理能力，能独立完成复杂分析并撰写高质量报告；\n3. 具备良好的沟通协调能力，能够跨部门推动问题解决与策略落地；\n4. 工作细致、责任心强，能承受一定工作压力，具备良好的学习能力与自驱力；\n5. 有连锁零售/餐饮/服务行业经验者优先。\n6. 掌握基本的AI工具，使用工具提升工作流程效率。","description":"部门介绍\n快乐猴是美团自营社区超市，依托自有供应链和门店管理体系，聚焦家庭用户的三餐所需，为消费者提供高质价比的食杂商品。快乐猴以数字化能力与科学品控为基础，不断满足消费者对“省”和“便利”的需求。\n\n岗位职责\n1. 经营分析与诊断：定期汇总并分析门店销售数据，输出经营分析报告，追踪门店核心经营指标（营业额、客单价、客流量、转化率等），识别异常波动并提出预警；\n2. 归因分析与赋能：通过深度经营分析、数据挖掘和行业研究，定位业务问题与增长机会，输出可执行的策略建议，对高/低绩效门店进行差异化归因分析，提炼可复用的增长经验；\n3. 专项牵头与落地实践：推进关键复杂专项，如新品上线分析、区域市场分析等，解决跨团队协作中的瓶颈问题，推动闭环管理，实现从策略到实践的高效转化；\n4. 跨部门协作：与财务、商品、供应链、商分以及前线团队等部门协作，推动跨团队成果落地，确保业务目标达成，为门店店长、区域负责人提供数据解读支持，辅助业务决策。\n\n岗位基本要求\n1. 本科及以上学历，统计学、数学、经济学等相关专业优先；\n2. 3年以上数据分析相关工作经验，极强的数据分析和逻辑推理能力，能独立完成复杂分析并撰写高质量报告；\n3. 具备良好的沟通协调能力，能够跨部门推动问题解决与策略落地；\n4. 工作细致、责任心强，能承受一定工作压力，具备良好的学习能力与自驱力；\n5. 有连锁零售/餐饮/服务行业经验者优先。\n6. 掌握基本的AI工具，使用工具提升工作流程效率。\n\n岗位亮点\n1. 加入快速发展的连锁品牌，参与门店规模化扩张与运营优化核心工作；\n2. 与资深运营团队深度合作，积累一线实战经验与行业洞察；\n3. 扁平化管理，成长空间大，有机会参与核心运营项目；\n4. 团队氛围积极，注重数据驱动与结果导向。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4779065354","sourceKey":"meituan_social","company":"美团","title":"Keeta-商业分析师（经营分析）","city":"香港特别行政区","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4779065354&jobShareType=1","duty":"1、基于业务目标，建立经营监控和分析框架，洞察经营问题\n2、分析评估外卖业务的资源使用情况，推动效率优化\n3、探索外卖业务收入增长机会，设计策略推动落地，优化单位经济模型\n4、积极探索AI工具应用","requirements":"1、4年及以上互联网商业分析经验，对所在领域的商业和业务逻辑有深刻理解\n2、逻辑思维能力强，具备较强的全局视角和细节把控能力\n3、具备项目推进能力，擅长与业务方沟通，跨团队协作能力强\n4、强目标导向，高自我驱动","description":"部门介绍\nKeeta是全球领先外卖平台美团旗下的独立品牌，肩负着“帮大家吃得更好，生活更好”的使命。依托美团深耕中国市场15年的技术与运营积淀，我们正引领全球餐饮与商品即时配送服务的创新与发展。\n\n自2023年成立以来，Keeta始终扎根社区并创造价值。我们为用户提供可靠的外卖体验，以智慧技术助餐厅提升经营效率，在为骑手拓宽收入来源的同时，也充分提供安全保障措施。基于这份多方共赢、共同成长的理念，我们的业务已从中国香港稳步拓展至中东及巴西，并持续向世界迈进。\n\n岗位职责\n1、基于业务目标，建立经营监控和分析框架，洞察经营问题\n2、分析评估外卖业务的资源使用情况，推动效率优化\n3、探索外卖业务收入增长机会，设计策略推动落地，优化单位经济模型\n4、积极探索AI工具应用\n\n岗位基本要求\n1、4年及以上互联网商业分析经验，对所在领域的商业和业务逻辑有深刻理解\n2、逻辑思维能力强，具备较强的全局视角和细节把控能力\n3、具备项目推进能力，擅长与业务方沟通，跨团队协作能力强\n4、强目标导向，高自我驱动\n\n具备以下条件优先\n有收益管理、补贴资源管理、经营分析相关经验优先\n\n岗位亮点\n1.美团出海业务，能跟全球各地精英共同推进美团全球化\n2.负责管理核心业务策略，能有抓手较好地影响业务拿结果\n3. 团队配备完善的AI工具体系，鼓励成员将AI能力融入日常工作流","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4545781274","sourceKey":"meituan_social","company":"美团","title":"美团骑行-运营主管（西安）","city":"西安市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4545781274&jobShareType=1","duty":"1.负责所属区域的车辆运营管理工作，对有效运营车辆和活跃车辆等指标负责。\n2.通过实地观察和数据分析，了解城市不同区域的车辆供需状况，制定合理的车辆投放及调度策略。\n3.根据故障车辆及未骑行车辆的数量及分布数据，制定并优化车辆干预管理的策略。\n4.配合治理者部门对城市运营问题进行管理。\n5.管理城市运营团队，提升团队工作效率和结果。","requirements":"1.本科及以上学历，2年以上团队管理经验，善于用开拓性思维解决问题。\n2.有共享单车行业经验且过往业绩优秀。\n3.善于数据分析，并能通过数据分析的结果不断优化调整工作。","description":"部门介绍\n美团骑行事业部在全国各个城市开展美团单车、电单车业务，提供绿色、便捷的共享出行服务，是美团出行板块重要的组成部分。我们力求为城市可持续发展提供低碳智能的解决方案，通过技术创新和硬件升级，不断优化全流程骑行体验，为低碳出行提供更好的服务。其中，美团单车旨在为城市居民提供通勤接驳服务，满足用户短途接驳出行需求；美团电单车则满足用户中短途多场景低碳出行需求。\n我们有开放的工作氛围，也有充满韧劲和创造力，心系低碳出行的伙伴。加入我们，一起为用户创造更好的出行体验。\n\n岗位职责\n1.负责所属区域的车辆运营管理工作，对有效运营车辆和活跃车辆等指标负责。\n2.通过实地观察和数据分析，了解城市不同区域的车辆供需状况，制定合理的车辆投放及调度策略。\n3.根据故障车辆及未骑行车辆的数量及分布数据，制定并优化车辆干预管理的策略。\n4.配合治理者部门对城市运营问题进行管理。\n5.管理城市运营团队，提升团队工作效率和结果。\n\n岗位基本要求\n1.本科及以上学历，2年以上团队管理经验，善于用开拓性思维解决问题。\n2.有共享单车行业经验且过往业绩优秀。\n3.善于数据分析，并能通过数据分析的结果不断优化调整工作。\n\n岗位亮点\n美团单车是美团出行板块重要的组成部分，我们有清晰完善的晋升机制和通道，开放扁平的工作氛围，期待你的加入，与优秀的人共事，一起见证美团单车的重要时刻。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4779387964","sourceKey":"meituan_social","company":"美团","title":"美团小象超市线上店店长-杭州/宁波/嘉兴/绍兴/金华/温州/台州/湖州/舟山","city":"南京市/杭州市/宁波市/温州市/嘉兴市/绍兴市/金华市/合肥市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4779387964&jobShareType=1","duty":"1.负责线上店的商品管理,对于商品的效期管理、品质管理、损耗管理负责,负责门店的水产养殖和销售的整体管理;\n2.负责线上店的进销存管理,负责线上店内门店的收货、上架、库存、库位的管理工作,优化库内的动线和库位,对于商品的周转和资产、设备的安全准确负责;\n3.负责线上店订单的履约,保证在更快的时间保质保量履约客户的订单,不断追求降本提效,致力于为客户提供更好的服务,不断精益求精;配合总部各项营销策略的实施,负责线上各品类商品的日常的促销活动实施;\n4.负责线上店现场的人员管理,包括招聘、培训和效率管理,负责数据管理和异常事件处理,维护周边社区关系;进行日常经营管理工作,包含对各项运营指标进行监控和分析,确保销售达成；\n5.新开门店开业前期筹备相关工作。","requirements":"1.大专及以上学历，3-5年连锁门店经营管理经验/仓储运营管理经验；\n2.对生鲜商品有一定的认知，熟悉门店促销管理、损耗控制管理、品类管理等，了解仓储的进销存管理，了解互联网的生产管理；\n3.良好的沟通能力及跨部门团队合作精神，学习能力佳，责任心强，愿意接受挑战，以结果为导向；\n4.善于劳务人员的管理工作，熟悉与零售相关的法律法规；\n5.熟练操作办公软件。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1.负责线上店的商品管理,对于商品的效期管理、品质管理、损耗管理负责,负责门店的水产养殖和销售的整体管理;\n2.负责线上店的进销存管理,负责线上店内门店的收货、上架、库存、库位的管理工作,优化库内的动线和库位,对于商品的周转和资产、设备的安全准确负责;\n3.负责线上店订单的履约,保证在更快的时间保质保量履约客户的订单,不断追求降本提效,致力于为客户提供更好的服务,不断精益求精;配合总部各项营销策略的实施,负责线上各品类商品的日常的促销活动实施;\n4.负责线上店现场的人员管理,包括招聘、培训和效率管理,负责数据管理和异常事件处理,维护周边社区关系;进行日常经营管理工作,包含对各项运营指标进行监控和分析,确保销售达成；\n5.新开门店开业前期筹备相关工作。\n\n岗位基本要求\n1.大专及以上学历，3-5年连锁门店经营管理经验/仓储运营管理经验；\n2.对生鲜商品有一定的认知，熟悉门店促销管理、损耗控制管理、品类管理等，了解仓储的进销存管理，了解互联网的生产管理；\n3.良好的沟通能力及跨部门团队合作精神，学习能力佳，责任心强，愿意接受挑战，以结果为导向；\n4.善于劳务人员的管理工作，熟悉与零售相关的法律法规；\n5.熟练操作办公软件。\n\n具备以下条件优先\n有前置仓、线上店、零售、物流管理工作经验优先。\n\n岗位亮点\n业务快速扩张快，管理岗位晋升通道宽阔；\n独立负责商品、库存、履约、团队全链路运营，能力得到全方位锻炼；\n有完善的培训体系助力加速成长；\n与互联网大咖及零售业专家共同发展。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4761099022","sourceKey":"meituan_social","company":"美团","title":"生产加工主管","city":"西安市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4761099022&jobShareType=1","duty":"1）通过熟悉掌握的生鲜加工、库存管理以及品质管控相关专业能力，带领PC团队达成业绩目标；\n2）面对原料供给快速变化和预测浮动的情况，做出灵活的判断及应对决策提升团队效率；\n3）在团队落地执行生鲜加工商品的储存条件及规范作业流程，并持续提出优化建议；\n4）连接业务链路上下游间的协同沟通意识，并建立与维护供应商之间良好的供需关系；\n5）快速解读业务策略，制定执行方案带领业务团队高效达成业绩指标；\n6）落实公司制定的各项考核制度，对团队进行有效激励。","requirements":"1）大专及以上学历，物流管理、供应链管理专业优先；\n2）具备5年以上大型生鲜零售、大型仓储物流相关工作经历和管理经验，80人以上团队管理经验优先；\n3）思维清晰沟通表达流畅，数据敏感性，有业务分析能力，帮助团队快速发现问题，并制定问题解决方策；\n4）对生鲜商品有一定认知，有原料进行审核、管控经验优先。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1）通过熟悉掌握的生鲜加工、库存管理以及品质管控相关专业能力，带领PC团队达成业绩目标；\n2）面对原料供给快速变化和预测浮动的情况，做出灵活的判断及应对决策提升团队效率；\n3）在团队落地执行生鲜加工商品的储存条件及规范作业流程，并持续提出优化建议；\n4）连接业务链路上下游间的协同沟通意识，并建立与维护供应商之间良好的供需关系；\n5）快速解读业务策略，制定执行方案带领业务团队高效达成业绩指标；\n6）落实公司制定的各项考核制度，对团队进行有效激励。\n\n岗位基本要求\n1）大专及以上学历，物流管理、供应链管理专业优先；\n2）具备5年以上大型生鲜零售、大型仓储物流相关工作经历和管理经验，80人以上团队管理经验优先；\n3）思维清晰沟通表达流畅，数据敏感性，有业务分析能力，帮助团队快速发现问题，并制定问题解决方策；\n4）对生鲜商品有一定认知，有原料进行审核、管控经验优先。\n\n具备以下条件优先\n有行业管理和生鲜包装加工经验的优先；\n\n岗位亮点\n生产岗位，负责人设备及生产运营交付，管理宽幅大，属于核心业务，后期净菜，包材规模会逐渐提升，晋升机会多；","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4699320884","sourceKey":"meituan_social","company":"美团","title":"小象财务BP-站配财务BP","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4699320884&jobShareType=1","duty":"1、业务深度支持与决策支持：深入理解前置仓业务模式以及站内运营全流程，能够识别业务关键驱动因素及财务影响点，为业务负责人提供及时、准确的财务洞察和决策建议。\n2、财务建模及经营分析：参与业务模式优化、定价策略、补贴投入等相关财务评估及模型搭建。\n3、成本管控及效率提升：密切监控仓配各项成本动因及关键指标，识别降本增效机会点，跟踪项目进展及财务收益。建立成本预警机制，对异常波动挖掘本质原因并提出解决方案。\n4、AI赋能运营财务：探索AI技术在前置仓成本管控、风险预警、财务建模等场景中的应用，推动智能财务管理实践落地。","requirements":"1、财务经验：8年及以上财务相关工作经验，其中至少5年以上财务BP、经营分析相关经验。\n2、行业经验：具有前置仓业务或零售行业经验者优先，熟悉该模式的运营逻辑、成本结构和关键指标。\n3、核心能力：精通财务建模，能够构建复杂的前置仓财务模型。优秀的数据分析能力，能够从业务运营和财务数据中提取关键信息，进行多维度分析，洞察业务问题，并转化为可落地的建议。\n4、优秀的跨部门沟通和协调能力，同时，需要具备较强责任心，对工作结果负责。\n5、具备AI工具应用能力，能将AI技术融入仓配业务的财务分析与风险管理工作，有AI+供应链/仓配财务实践经验者优先。","description":"部门介绍\n财务平台负责公司整体和各业务层面的财务管理工作，通过建设专业、全面、复合的财务管理能力和与业务经营的紧密结合来支持公司健康发展。目前财务平台拥有财务会计、财务报告、资金管理、税务管理、财务共享、财务系统、规划分析、财务BP和内控内审等主要工作方向。我们的目标是建设业界一流的财务管理能力和经营支持体系，为公司战略的正确落地、投入效率的持续提升、业务价值的不断增长保驾护航。欢迎加入财务平台，携手一起向未来！\n\n岗位职责\n1、业务深度支持与决策支持：深入理解前置仓业务模式以及站内运营全流程，能够识别业务关键驱动因素及财务影响点，为业务负责人提供及时、准确的财务洞察和决策建议。\n2、财务建模及经营分析：参与业务模式优化、定价策略、补贴投入等相关财务评估及模型搭建。\n3、成本管控及效率提升：密切监控仓配各项成本动因及关键指标，识别降本增效机会点，跟踪项目进展及财务收益。建立成本预警机制，对异常波动挖掘本质原因并提出解决方案。\n4、AI赋能运营财务：探索AI技术在前置仓成本管控、风险预警、财务建模等场景中的应用，推动智能财务管理实践落地。\n\n岗位基本要求\n1、财务经验：8年及以上财务相关工作经验，其中至少5年以上财务BP、经营分析相关经验。\n2、行业经验：具有前置仓业务或零售行业经验者优先，熟悉该模式的运营逻辑、成本结构和关键指标。\n3、核心能力：精通财务建模，能够构建复杂的前置仓财务模型。优秀的数据分析能力，能够从业务运营和财务数据中提取关键信息，进行多维度分析，洞察业务问题，并转化为可落地的建议。\n4、优秀的跨部门沟通和协调能力，同时，需要具备较强责任心，对工作结果负责。\n5、具备AI工具应用能力，能将AI技术融入仓配业务的财务分析与风险管理工作，有AI+供应链/仓配财务实践经验者优先。\n\n岗位亮点\n1. 深入参与核心业务，与业务团队紧密协作，快速积累行业经验。  \n2. 团队氛围开放，注重专业能力提升与个人职业发展。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4682754436","sourceKey":"meituan_social","company":"美团","title":"沙特-异业合作策略运营专家","city":"利雅得","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4682754436&jobShareType=1","duty":"1.针对不同异业合作渠道进行运营，发掘不同渠道用户特征，制定差异化的商务、补贴等策略，达成业务目标；\n2.基于数据分析，建立渠道价值和效果评估体系，明确各渠道规模潜力及增量ROI；\n3.设计渠道的增长策略，以补贴、活动等作为抓手，推动异业合作渠道的持续增长；\n4.可独立完成异业合作产品MRD撰写，协调产品、研发等各部门资源，共同实现产品验证；\n5.关注竞争对手、行业重要玩家的关键策略，通过市场调研、数据分析等方式，洞察业务增长点。","requirements":"1.本科及以上学历，3-5年以上互联网用户/渠道运营相关经验，熟悉用户增长工具、通过渠道、用户策略，实现流量增长；\n2.数据驱动，熟练掌握相关分析工具和方法，能独自闭环策略制定、实验设计、效果复盘、策略迭代的全流程；\n3.英语可作为工作语言，心态开放，能快速理解和适应不同文化背景的工作环境、运营方法、用户需求；\n4.较强的沟通表达和项目管理能力，能积极推动跨部门团队促成项目落地。","description":"部门介绍\nKeeta是全球领先外卖平台美团旗下的独立品牌，肩负着“帮大家吃得更好，生活更好”的使命。依托美团深耕中国市场15年的技术与运营积淀，我们正引领全球餐饮与商品即时配送服务的创新与发展。\n\n自2023年成立以来，Keeta始终扎根社区并创造价值。我们为用户提供可靠的外卖体验，以智慧技术助餐厅提升经营效率，在为骑手拓宽收入来源的同时，也充分提供安全保障措施。基于这份多方共赢、共同成长的理念，我们的业务已从中国香港稳步拓展至中东及巴西，并持续向世界迈进。\n\n岗位职责\n1.针对不同异业合作渠道进行运营，发掘不同渠道用户特征，制定差异化的商务、补贴等策略，达成业务目标；\n2.基于数据分析，建立渠道价值和效果评估体系，明确各渠道规模潜力及增量ROI；\n3.设计渠道的增长策略，以补贴、活动等作为抓手，推动异业合作渠道的持续增长；\n4.可独立完成异业合作产品MRD撰写，协调产品、研发等各部门资源，共同实现产品验证；\n5.关注竞争对手、行业重要玩家的关键策略，通过市场调研、数据分析等方式，洞察业务增长点。\n\n岗位基本要求\n1.本科及以上学历，3-5年以上互联网用户/渠道运营相关经验，熟悉用户增长工具、通过渠道、用户策略，实现流量增长；\n2.数据驱动，熟练掌握相关分析工具和方法，能独自闭环策略制定、实验设计、效果复盘、策略迭代的全流程；\n3.英语可作为工作语言，心态开放，能快速理解和适应不同文化背景的工作环境、运营方法、用户需求；\n4.较强的沟通表达和项目管理能力，能积极推动跨部门团队促成项目落地。\n\n具备以下条件优先\n1.有O2O行业站外异业合作渠道运营或用户运营工作经验\n2.有海外工作经历和背景\n\n岗位亮点\n1.创新业务的操盘手，挑战与机会并存；\n2.能够全方位了解外卖业务模式，有足够的空间和灵活度全面发挥你的才能；\n3.核心业务的核心部门，团队气氛好，学习成长型团队。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4776750036","sourceKey":"meituan_social","company":"美团","title":"推荐策略产品经理","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4776750036&jobShareType=1","duty":"1. 基于用户、时空环境场景划分，联动业务、供给、运营、研发等团队，整体推动推荐场景的人货场匹配效率，提升团交易规模\n2. 深入分析用户需求和场景，制定推荐策略的迭代方案，提升推荐效果和用户体验。  \n3. 负责推荐策略产品的设计与优化，提升用户推荐内容的精准度与用户体验。 \n4. 关注行业动态趋势，同时关注AI在推荐领域的应用，探索创新推荐模式，提升产品影响力。","requirements":"1. 5年以上产品经验，具备本地生活、电商、推荐策略、AI在推荐系统中应用等相关背景优先。\n2. 熟悉推荐系统基本原理，了解协同过滤、深度学习等常见算法。\n3.有大型独立负责的策略专项，并获得明确项目增量收益。\n4. 具备优秀的逻辑思维和数据敏感度，能敏锐发现问题和准确归因。\n5.结果导向、热爱思考、良好的横向沟通协同能力。\n6. 有AI工具的应用相关的经验，能借助AI能力做产品设计及提效优化的解决方案。","description":"部门介绍\n美团平台为用户的基础产品体验负责，还承担了美团的用户增长、市场和品牌营销以及多条业务线的产品设计职责，建立了融合文字、图片、视频和直播等不同形式的內容生态系统，同时整合地图服务部、客户服务和体验部、企业业务部、网约车业务部等部门，致力于用科技提升美团数亿消费者、近千万商家、骑手、司机和团长的服务体验。美团平台拥有高并发、多业务的复杂场景，为技术深度优化提供了最佳实践可能。这里有简单、讲逻辑、有爱的团队，更是一块理想的实战场地，舞台广阔，欢迎你来尽情施展。\n\n岗位职责\n1. 基于用户、时空环境场景划分，联动业务、供给、运营、研发等团队，整体推动推荐场景的人货场匹配效率，提升团交易规模\n2. 深入分析用户需求和场景，制定推荐策略的迭代方案，提升推荐效果和用户体验。  \n3. 负责推荐策略产品的设计与优化，提升用户推荐内容的精准度与用户体验。 \n4. 关注行业动态趋势，同时关注AI在推荐领域的应用，探索创新推荐模式，提升产品影响力。\n\n岗位基本要求\n1. 5年以上产品经验，具备本地生活、电商、推荐策略、AI在推荐系统中应用等相关背景优先。\n2. 熟悉推荐系统基本原理，了解协同过滤、深度学习等常见算法。\n3.有大型独立负责的策略专项，并获得明确项目增量收益。\n4. 具备优秀的逻辑思维和数据敏感度，能敏锐发现问题和准确归因。\n5.结果导向、热爱思考、良好的横向沟通协同能力。\n6. 有AI工具的应用相关的经验，能借助AI能力做产品设计及提效优化的解决方案。\n\n岗位亮点\n1.深度参与AI驱动的亿级用户推荐系统建设，直接影响平台核心指标与用户体验。\n2.鼓励AI创新实验，提供资源支持探索生成式推荐、个性化大模型等方向。\n3.扁平化管理，有足够的空间探索交易增量的机会，成长空间大。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4777548911","sourceKey":"meituan_social","company":"美团","title":"大客户运营-Agent 方向","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4777548911&jobShareType=1","duty":"-负责 Agent 产品企业客户全生命周期客户成功管理，包括入驻培训、持续答疑和定期回访，确保客户从产品中获得持续价值；\n-深入理解客户的研发流程和业务场景，帮助客户梳理痛点、定义需求，并输出可落地的 AI 应用方案；\n-与客户共创 POC Demo，从 0 到 1 构建面向客户场景的验证案例，展示产品能力并推动签署；\n-主导客户培训与启动，设计培训课程、编写最佳实践文档，帮助客户团队快速上手产品；\n-收集并整理客户反馈，驱动产品迭代和优先级排序；\n-维护客户关系，定期与客户一线团队和中层管理者对齐，主动识别续约和增购机会；\n-跟踪行业动态和先进产品，为客户提供 AI 编程领域的最佳实践建议","requirements":"-本科及以上学历，计算机、软件工程或相关专业优先，3 年以上 ToB 产品客户成功、解决方案或技术咨询相关经验；\n-具备良好的技术背景，熟悉软件开发流程和常见工具链，对 Agent / LLM / AI Coding 领域有深入理解和实践经验；\n-出色的沟通表达能力，能够切换语境与开发者、技术负责人、中层管理者等不同层级的客户高效对话；\n-拥有强烈的客户服务意识和主人翁精神，能主动推动问题解决并在多任并行环境下保持高效输出；\n-具备结构化思维和方案设计能力，能将客户模糊需求转化为清晰可执行的落地计划；\n-有较强的文案组织和汇报能力，能独立编写培训课程、最佳实践文档和项目报告。","description":"部门介绍\n基础研发平台是美团的核心技术平台，立足于“零售+科技”的战略定位，通过打造人工智能、大数据、云计算、安全等核心技术能力，以及研发效能平台、企业应用平台等公共服务，为业务提供稳定安全、扩展易用、技术领先的平台技术和产品服务。\n在这里，我们会参与到最前沿的技术研发和探索；能够接触超规模集群、海量数据，挑战高复杂业务场景，有机会与业界一流的工程师一起并肩前行。\n在这里，我们有超强的技术氛围，持续向社区贡献业界实践，加速行业技术发展；我们有完善的互联网学习生态圈，重视底层逻辑和方法论，助力职业生涯的非线性成长。\n真诚地邀请你，和我们一起驱动技术发展，创造行业价值。\n\n岗位职责\n-负责 Agent 产品企业客户全生命周期客户成功管理，包括入驻培训、持续答疑和定期回访，确保客户从产品中获得持续价值；\n-深入理解客户的研发流程和业务场景，帮助客户梳理痛点、定义需求，并输出可落地的 AI 应用方案；\n-与客户共创 POC Demo，从 0 到 1 构建面向客户场景的验证案例，展示产品能力并推动签署；\n-主导客户培训与启动，设计培训课程、编写最佳实践文档，帮助客户团队快速上手产品；\n-收集并整理客户反馈，驱动产品迭代和优先级排序；\n-维护客户关系，定期与客户一线团队和中层管理者对齐，主动识别续约和增购机会；\n-跟踪行业动态和先进产品，为客户提供 AI 编程领域的最佳实践建议\n\n岗位基本要求\n-本科及以上学历，计算机、软件工程或相关专业优先，3 年以上 ToB 产品客户成功、解决方案或技术咨询相关经验；\n-具备良好的技术背景，熟悉软件开发流程和常见工具链，对 Agent / LLM / AI Coding 领域有深入理解和实践经验；\n-出色的沟通表达能力，能够切换语境与开发者、技术负责人、中层管理者等不同层级的客户高效对话；\n-拥有强烈的客户服务意识和主人翁精神，能主动推动问题解决并在多任并行环境下保持高效输出；\n-具备结构化思维和方案设计能力，能将客户模糊需求转化为清晰可执行的落地计划；\n-有较强的文案组织和汇报能力，能独立编写培训课程、最佳实践文档和项目报告。\n\n具备以下条件优先\n-有 AI Coding 产品的使用或客户服务经验；\n-有企业级软件的部署、集成和定制化项目经验，熟悉私有化部署、SSO、RBAC 等企业特性；\n-熟悉金融、制造、互联网等某一 ToB 垂直行业的 AI 落地场景；\n-有 POC 项目从 0 到 1 的成功案例，能提供具体案例说明；\n-拥有优秀的英文沟通能力，能支持海外客户或外企客户场景。\n\n岗位亮点\n-与一支经验丰富的创业团队共事，在 AI + 办公这个最前沿的领域上打磨自己的专业能力；\n-有机会深入最头部企业客户的真实研发现场，理解不同行业的开发范式和工程文化；\n-平坦的团队氛围和快速的成长通道，你的声音会被认真对待并直接影响产品方向。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4761127446","sourceKey":"meituan_social","company":"美团","title":"呼和浩特市运维主管","city":"呼和浩特市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4761127446&jobShareType=1","duty":"1.负责所属区域的车辆运营管理工作，对有效运营车辆和活跃车辆等指标负责；\n2.通过实地观察和数据分析，了解区域的车辆供需状况，制定合理的车辆投放及调度策略；\n3.根据故障车辆及未骑行车辆的数量及分布数据，制定并优化车辆干预管理的策略；\n4.配合治理者对城市运营问题进行管理；\n5.协助运营经理管理运营团队，提升团队工作效率和结果。","requirements":"1.本科及以上学历，3年工作经验，1年以上团队管理经验，善于用开拓性思维解决问题；\n2.有快消品区域覆盖或互联网城市地推管理经验者优先；\n3.善于数据分析，并能通过数据分析的结果不断优化调整工作。","description":"部门介绍\n美团骑行事业部在全国各个城市开展美团单车、电单车业务，提供绿色、便捷的共享出行服务，是美团出行板块重要的组成部分。我们力求为城市可持续发展提供低碳智能的解决方案，通过技术创新和硬件升级，不断优化全流程骑行体验，为低碳出行提供更好的服务。其中，美团单车旨在为城市居民提供通勤接驳服务，满足用户短途接驳出行需求；美团电单车则满足用户中短途多场景低碳出行需求。\n我们有开放的工作氛围，也有充满韧劲和创造力，心系低碳出行的伙伴。加入我们，一起为用户创造更好的出行体验。\n\n岗位职责\n1.负责所属区域的车辆运营管理工作，对有效运营车辆和活跃车辆等指标负责；\n2.通过实地观察和数据分析，了解区域的车辆供需状况，制定合理的车辆投放及调度策略；\n3.根据故障车辆及未骑行车辆的数量及分布数据，制定并优化车辆干预管理的策略；\n4.配合治理者对城市运营问题进行管理；\n5.协助运营经理管理运营团队，提升团队工作效率和结果。\n\n岗位基本要求\n1.本科及以上学历，3年工作经验，1年以上团队管理经验，善于用开拓性思维解决问题；\n2.有快消品区域覆盖或互联网城市地推管理经验者优先；\n3.善于数据分析，并能通过数据分析的结果不断优化调整工作。\n\n具备以下条件优先\n有共享单车、网约车相关运营经营的优先\n\n岗位亮点\n清晰完善的晋升机制和通道，开放扁平的工作氛围。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4735469952","sourceKey":"meituan_social","company":"美团","title":"闪购-卖场业务财务BP","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4735469952&jobShareType=1","duty":"1. 财务分析： 参与项目投资评估、成本费用管控及盈利模型搭建；按期出具多维度的经营分析数据，结合业务特点制定关键业务指标及分析体系。通过日常对业财指标的追踪分析，发现并提示风险和机会点，支持业务决策，提供财务数据洞察和预测；\n2. 预算制定：参与年度预算规划工作，结合业务策略制定相应的预算，同时支持业务将预算目标拆解到具体的实施路径并追踪达成；\n3. 业务支持：包括支持业务新场景落地，协同财税法提供财务解决方案；熟悉掌握数据口径和计算逻辑，搭建看板进行数据分析；了解行业动态，提供对标分析支持；  \n4. 与业务团队紧密协作，推动业财一体化落地；\n5. 财务流程优化及配合内控风险扫描。","requirements":"1. 大学本科及以上学历，5年以上财务分析或财务BP相关工作经验，有零售、互联网工作背景优先；\n2. 具备扎实的财务分析能力，熟练使用办公软件及数据工具；\n3. 具备良好的逻辑思维、沟通能力和跨部门协作能力；\n4. 对数据敏感，具备较强的业务理解力和问题解决能力；\n5. AI工具应用：主动将AI工具融入日常工作，例如工作流优化、数据处理与分析、报表/看板搭建，知识库建设。","description":"部门介绍\n财务平台负责公司整体和各业务层面的财务管理工作，通过建设专业、全面、复合的财务管理能力和与业务经营的紧密结合来支持公司健康发展。目前财务平台拥有财务会计、财务报告、资金管理、税务管理、财务共享、财务系统、规划分析、财务BP和内控内审等主要工作方向。我们的目标是建设业界一流的财务管理能力和经营支持体系，为公司战略的正确落地、投入效率的持续提升、业务价值的不断增长保驾护航。欢迎加入财务平台，携手一起向未来！\n\n岗位职责\n1. 财务分析： 参与项目投资评估、成本费用管控及盈利模型搭建；按期出具多维度的经营分析数据，结合业务特点制定关键业务指标及分析体系。通过日常对业财指标的追踪分析，发现并提示风险和机会点，支持业务决策，提供财务数据洞察和预测；\n2. 预算制定：参与年度预算规划工作，结合业务策略制定相应的预算，同时支持业务将预算目标拆解到具体的实施路径并追踪达成；\n3. 业务支持：包括支持业务新场景落地，协同财税法提供财务解决方案；熟悉掌握数据口径和计算逻辑，搭建看板进行数据分析；了解行业动态，提供对标分析支持；  \n4. 与业务团队紧密协作，推动业财一体化落地；\n5. 财务流程优化及配合内控风险扫描。\n\n岗位基本要求\n1. 大学本科及以上学历，5年以上财务分析或财务BP相关工作经验，有零售、互联网工作背景优先；\n2. 具备扎实的财务分析能力，熟练使用办公软件及数据工具；\n3. 具备良好的逻辑思维、沟通能力和跨部门协作能力；\n4. 对数据敏感，具备较强的业务理解力和问题解决能力；\n5. AI工具应用：主动将AI工具融入日常工作，例如工作流优化、数据处理与分析、报表/看板搭建，知识库建设。\n\n岗位亮点\n1. 深入参与核心业务，与业务团队共同成长，发展空间广阔。  \n2. 团队氛围开放，鼓励创新与主动担当。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4773978247","sourceKey":"meituan_social","company":"美团","title":"客户运营（非餐方向）","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4773978247&jobShareType=1","duty":"负责非餐方向服务产品建设与迭代： 洞察非餐方向的客户需求与市场动态，利用AI交互，不断提升行业认知，主导服务产品的设计、建设及迭代，确保服务产品满足客户需求，具备市场竞争力；\n\n提供非标客户的解决方案：根据非标客户的特殊需求及痛点问题，调研外部市场玩法，利用AI工具（如数据分析，沉淀策略自动匹配等）识别内部现状，联动各团队输出专属的定制化解决方案，满足客户需求，提升业务影响力；\n\n推动服务产品落地推广应用： 负责建设的服务产品落地推广应用，不断提高服务产品的价值，并协同销售、履约、产研等跨职能团队，解决落地应用中的卡点问题，将服务产品收益扩到最大化；\n\n主导内部外协作与资源整合： 作为客户需求与内部团队的纽带，需主动协调各部门资源，确保服务产品在整个生命周期内的高效运转，同时利用AI工具对确定性场景进行自动化升级，提升协作的效率。","requirements":"本科及以上学历，有解决方案、客户运营相关工作经验，有过履约相关的解决方案者优先；\n\n思维逻辑清晰，具备较强的数据敏感性及优秀的数据分析能力，能够从数据中发现业务痛点并提出有效应对策略；\n\n行业视野广，具备出色的执行力以及良好的沟通、组织、协同和推进能力，能借助 AI 工具做充分的行业分析；\n\n具备将 AI 工具融入日常工作流的实践经验，能探索 AI 辅助运营提效的落地路径。\n\n责任心强，应变能力突出，具备良好的团队合作精神；","description":"部门介绍\n美团配送是以科技为内核的即时物流品牌，利用高效、稳定、广阔的配送网络和前沿科技能力为各行业客户提供涵盖商流物流一体化、流量赋能、行业定制化即时配送、末端配送、前置仓等服务在内的全方位同城物流综合解决方案。\n作为科技创新和智慧物流的实践者，美团配送在人工智能（AI）、5G应用、物联网（IoT）、云计算等多维度不断探索科创蓝海，让同城物流进入数智化时代。美团配送在IoT智能设备、外卖柜、换电网络、无人配送体系等硬件设施与服务上不断推陈出新，持续优化骑手、消费者、商家体验；自研同城物流系统，通过智能分析为用户提供更便捷的生活方式，为商家提供更高效的履约服务。\n加入我们，一起把世界送到消费者手中！\n\n岗位职责\n负责非餐方向服务产品建设与迭代： 洞察非餐方向的客户需求与市场动态，利用AI交互，不断提升行业认知，主导服务产品的设计、建设及迭代，确保服务产品满足客户需求，具备市场竞争力；\n\n提供非标客户的解决方案：根据非标客户的特殊需求及痛点问题，调研外部市场玩法，利用AI工具（如数据分析，沉淀策略自动匹配等）识别内部现状，联动各团队输出专属的定制化解决方案，满足客户需求，提升业务影响力；\n\n推动服务产品落地推广应用： 负责建设的服务产品落地推广应用，不断提高服务产品的价值，并协同销售、履约、产研等跨职能团队，解决落地应用中的卡点问题，将服务产品收益扩到最大化；\n\n主导内部外协作与资源整合： 作为客户需求与内部团队的纽带，需主动协调各部门资源，确保服务产品在整个生命周期内的高效运转，同时利用AI工具对确定性场景进行自动化升级，提升协作的效率。\n\n岗位基本要求\n本科及以上学历，有解决方案、客户运营相关工作经验，有过履约相关的解决方案者优先；\n\n思维逻辑清晰，具备较强的数据敏感性及优秀的数据分析能力，能够从数据中发现业务痛点并提出有效应对策略；\n\n行业视野广，具备出色的执行力以及良好的沟通、组织、协同和推进能力，能借助 AI 工具做充分的行业分析；\n\n具备将 AI 工具融入日常工作流的实践经验，能探索 AI 辅助运营提效的落地路径。\n\n责任心强，应变能力突出，具备良好的团队合作精神；\n\n具备以下条件优先\n具备商超SKA解决方案者优先；\n\n岗位亮点\n服务于企业客户，业务复杂度高，岗位技术含量高，个人能力提升帮助大。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4659782410","sourceKey":"meituan_social","company":"美团","title":"国内IT现场服务运营专家（会议室运营方向）","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4659782410&jobShareType=1","duty":"1. 会议室运营体系建设与管理： 负责公司会议室整体运营体系的规划、搭建和持续优化。围绕Zoom等视频会议平台及配套音视频硬件，制定会议室使用规范、巡检标准和应急预案，建立覆盖\"预防—监控—响应—复盘\"全链路的运营保障机制，确保会议室服务的高可用性和稳定性。定期对会议室使用数据（利用率、故障率、用户满意度等）进行统计分析，输出运营报告并驱动持续改进。\n2. 会议室软硬件管理与Zoom平台运维： 深度负责Zoom Rooms及相关视频会议系统的日常运维、版本升级、账号与许可管理、安全策略配置。熟悉会议室音视频硬件（如摄像头、麦克风阵列、显示屏、编解码器、无线投屏设备等）的选型、部署、调试和生命周期管理。制定并维护会议室设备台账，建立定期巡检和预防性维护机制，保障设备健康运行。\n3. 现场服务管理与用户支持： 根据业务需求制定并优化会议室现场服务流程和运营指标。领导和管理现场技术支持团队，合理安排人员排班，保证对员工会议相关的技术咨询与故障问题的及时响应。建立有效的服务质量监控体系，跟踪关键指标（如首次响应时长、故障恢复时长、用户满意度），定期进行数据复盘以持续提升服务水平。\n\n4. 供应商管理与资源整合： 制定服务级别协议（SLA），明确服务范围、质量标准、响应时间等关键条款，并监督供应商严格履行协议。对供应商的服务表现进行定期考核与评估，推动服务持续改善。\n5. 知识运营与标准化建设： 搭建和完善会议室运营知识管理体系，组织编写并持续更新Zoom使用指南、会议室设备操作手册、常见问题FAQ等知识文档，确保内容准确、易用、及时。优化知识分类和检索机制，降低用户自助解决问题的门槛，减少重复性工单。","requirements":"1. 精通Zoom（含Zoom Rooms、Zoom Webinar等）产品体系，熟悉其后台管理、策略配置、API对接及故障排查，有大规模企业Zoom部署和运营经验者优先。\n2. 熟悉主流会议室音视频硬件（如Poly、Neat、Logitech、Crestron、Shure等品牌），具备独立完成设备选型评估、方案设计、部署调试的能力。\n3. 具备扎实的运营基本功，能够从0到1设计运营体系，擅长通过数据分析发现问题、驱动优化；熟悉ITIL等IT服务管理框架，能运用相关理念持续提升服务质量和效率。\n4. 拥有出色的团队领导和管理能力，能够有效组织、协调和激励团队成员，推动团队达成目标；具备良好的人员发展和绩效管理经验，能够培养和提升团队整体技术水平和服务意识。\n5. 具有较强的沟通协调能力和跨部门合作能力，能够与公司内部各业务部门、IT团队以及外部供应商建立良好的合作关系，有效整合资源，解决复杂的跨区域会议室技术问题和业务需求。","description":"部门介绍\n基础研发平台是美团的核心技术平台，立足于“零售+科技”的战略定位，通过打造人工智能、大数据、云计算、安全等核心技术能力，以及研发效能平台、企业应用平台等公共服务，为业务提供稳定安全、扩展易用、技术领先的平台技术和产品服务。\n在这里，我们会参与到最前沿的技术研发和探索；能够接触超规模集群、海量数据，挑战高复杂业务场景，有机会与业界一流的工程师一起并肩前行。\n在这里，我们有超强的技术氛围，持续向社区贡献业界实践，加速行业技术发展；我们有完善的互联网学习生态圈，重视底层逻辑和方法论，助力职业生涯的非线性成长。\n真诚地邀请你，和我们一起驱动技术发展，创造行业价值。\n\n岗位职责\n1. 会议室运营体系建设与管理： 负责公司会议室整体运营体系的规划、搭建和持续优化。围绕Zoom等视频会议平台及配套音视频硬件，制定会议室使用规范、巡检标准和应急预案，建立覆盖\"预防—监控—响应—复盘\"全链路的运营保障机制，确保会议室服务的高可用性和稳定性。定期对会议室使用数据（利用率、故障率、用户满意度等）进行统计分析，输出运营报告并驱动持续改进。\n2. 会议室软硬件管理与Zoom平台运维： 深度负责Zoom Rooms及相关视频会议系统的日常运维、版本升级、账号与许可管理、安全策略配置。熟悉会议室音视频硬件（如摄像头、麦克风阵列、显示屏、编解码器、无线投屏设备等）的选型、部署、调试和生命周期管理。制定并维护会议室设备台账，建立定期巡检和预防性维护机制，保障设备健康运行。\n3. 现场服务管理与用户支持： 根据业务需求制定并优化会议室现场服务流程和运营指标。领导和管理现场技术支持团队，合理安排人员排班，保证对员工会议相关的技术咨询与故障问题的及时响应。建立有效的服务质量监控体系，跟踪关键指标（如首次响应时长、故障恢复时长、用户满意度），定期进行数据复盘以持续提升服务水平。\n\n4. 供应商管理与资源整合： 制定服务级别协议（SLA），明确服务范围、质量标准、响应时间等关键条款，并监督供应商严格履行协议。对供应商的服务表现进行定期考核与评估，推动服务持续改善。\n5. 知识运营与标准化建设： 搭建和完善会议室运营知识管理体系，组织编写并持续更新Zoom使用指南、会议室设备操作手册、常见问题FAQ等知识文档，确保内容准确、易用、及时。优化知识分类和检索机制，降低用户自助解决问题的门槛，减少重复性工单。\n\n岗位基本要求\n1. 精通Zoom（含Zoom Rooms、Zoom Webinar等）产品体系，熟悉其后台管理、策略配置、API对接及故障排查，有大规模企业Zoom部署和运营经验者优先。\n2. 熟悉主流会议室音视频硬件（如Poly、Neat、Logitech、Crestron、Shure等品牌），具备独立完成设备选型评估、方案设计、部署调试的能力。\n3. 具备扎实的运营基本功，能够从0到1设计运营体系，擅长通过数据分析发现问题、驱动优化；熟悉ITIL等IT服务管理框架，能运用相关理念持续提升服务质量和效率。\n4. 拥有出色的团队领导和管理能力，能够有效组织、协调和激励团队成员，推动团队达成目标；具备良好的人员发展和绩效管理经验，能够培养和提升团队整体技术水平和服务意识。\n5. 具有较强的沟通协调能力和跨部门合作能力，能够与公司内部各业务部门、IT团队以及外部供应商建立良好的合作关系，有效整合资源，解决复杂的跨区域会议室技术问题和业务需求。\n\n具备以下条件优先\n有IT现场服务团队管理经验、会议室运维经验优先\n\n岗位亮点\n1. 我们有开放、直接的工作氛围，以逻辑和事实说话;\n2. 尊重知识和常识，努力以用户视角和业务视角思考。\n3. 团队有多元化背景的服务人，共建项目、共同进步。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3930470211","sourceKey":"meituan_social","company":"美团","title":"Integration Solution-Team Leader","city":"圣保罗","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3930470211&jobShareType=1","duty":"Job Responsibilities:\n\n1.Team Management & Goal Achievement: Oversee daily operations and team management of the integration solution group, allocate resources reasonably, and lead the team to achieve goals in system integration, product optimization, and customer support.\n2.Integration Project Coordination & Delivery: Lead the planning, implementation, and delivery of integration projects involving external API service providers, hardware devices (such as printers), and internal systems, ensuring compliant and efficient execution.\n3.Technical Solution Design & Optimization: Analyze customer and business needs, coordinate with technical teams to implement system connectivity, process optimization, and new feature development, continuously improving the quality and stability of overall integration solutions.\n4.Quality & Process Control: Establish and optimize team collaboration, product testing, launch processes, and integration standards; monitor key indicators to ensure high-standard deliverables.\n5.Complex Problem Solving & Technical Challenges: Lead the team to analyze and resolve complex technical issues in project integration and device operation, promote targeted technical solutions, and ensure successful client implementation.\n6.Cross-Departmental Communication & Collaboration: Act as the core liaison within the team, work closely with sales, technical, product, and operation teams to coordinate project progress and improve business synergy.\n7.Team Development & Capability Building: Develop and organize systematic training and growth plans for team members, continuously identify and cultivate talents, and build a high-performing and cohesive team.\n8.Industry Trend Insights & Innovation: Stay updated on order-taking solution development in the restaurant/merchant industry, including APIs, hardware, and apps; drive innovation in integration solutions and lead the professional advancement of the team.","requirements":"Job Requirements:\n\n1.Bachelor’s degree or above, preferably in Computer Science, Information Management, E-commerce, or related fields.\n2.At least 3 years of experience in technical integration, system implementation, product operations, or related team management, with a preference for experience in large-scale API, hardware, or integrated solution project management.\n3.Strong technical solution analysis, design, and optimization abilities; able to systematically solve complex technical and business problems.\n4.Familiar with API interfaces, hardware products (such as printers), apps, and various integration methods; deep understanding of overall solutions for the merchant industry is a plus.\n5.Outstanding cross-team communication, coordination, and project management skills; able to drive collaboration and achieve project goals.\n6.Ability to organize team training and development, nurture talent, and build a high-performing team.\n7.Results-oriented, highly resilient, and self-driven, with awareness of process optimization and high-standard quality control.\n8.Native-level Portuguese and strong proficiency in English (listening, speaking, reading, and writing); able to communicate efficiently in an international and diverse environment.\n9.Experience in restaurant/merchant integration projects or industry solution operations is a plus.","description":"部门介绍\nKeeta是全球领先外卖平台美团旗下的独立品牌，肩负着“帮大家吃得更好，生活更好”的使命。依托美团深耕中国市场15年的技术与运营积淀，我们正引领全球餐饮与商品即时配送服务的创新与发展。\n\n自2023年成立以来，Keeta始终扎根社区并创造价值。我们为用户提供可靠的外卖体验，以智慧技术助餐厅提升经营效率，在为骑手拓宽收入来源的同时，也充分提供安全保障措施。基于这份多方共赢、共同成长的理念，我们的业务已从中国香港稳步拓展至中东及巴西，并持续向世界迈进。\n\n岗位职责\nJob Responsibilities:\n\n1.Team Management & Goal Achievement: Oversee daily operations and team management of the integration solution group, allocate resources reasonably, and lead the team to achieve goals in system integration, product optimization, and customer support.\n2.Integration Project Coordination & Delivery: Lead the planning, implementation, and delivery of integration projects involving external API service providers, hardware devices (such as printers), and internal systems, ensuring compliant and efficient execution.\n3.Technical Solution Design & Optimization: Analyze customer and business needs, coordinate with technical teams to implement system connectivity, process optimization, and new feature development, continuously improving the quality and stability of overall integration solutions.\n4.Quality & Process Control: Establish and optimize team collaboration, product testing, launch processes, and integration standards; monitor key indicators to ensure high-standard deliverables.\n5.Complex Problem Solving & Technical Challenges: Lead the team to analyze and resolve complex technical issues in project integration and device operation, promote targeted technical solutions, and ensure successful client implementation.\n6.Cross-Departmental Communication & Collaboration: Act as the core liaison within the team, work closely with sales, technical, product, and operation teams to coordinate project progress and improve business synergy.\n7.Team Development & Capability Building: Develop and organize systematic training and growth plans for team members, continuously identify and cultivate talents, and build a high-performing and cohesive team.\n8.Industry Trend Insights & Innovation: Stay updated on order-taking solution development in the restaurant/merchant industry, including APIs, hardware, and apps; drive innovation in integration solutions and lead the professional advancement of the team.\n\n岗位基本要求\nJob Requirements:\n\n1.Bachelor’s degree or above, preferably in Computer Science, Information Management, E-commerce, or related fields.\n2.At least 3 years of experience in technical integration, system implementation, product operations, or related team management, with a preference for experience in large-scale API, hardware, or integrated solution project management.\n3.Strong technical solution analysis, design, and optimization abilities; able to systematically solve complex technical and business problems.\n4.Familiar with API interfaces, hardware products (such as printers), apps, and various integration methods; deep understanding of overall solutions for the merchant industry is a plus.\n5.Outstanding cross-team communication, coordination, and project management skills; able to drive collaboration and achieve project goals.\n6.Ability to organize team training and development, nurture talent, and build a high-performing team.\n7.Results-oriented, highly resilient, and self-driven, with awareness of process optimization and high-standard quality control.\n8.Native-level Portuguese and strong proficiency in English (listening, speaking, reading, and writing); able to communicate efficiently in an international and diverse environment.\n9.Experience in restaurant/merchant integration projects or industry solution operations is a plus.\n\n岗位亮点\nJob Highlights:\n\n1.Early-Stage Business: Opportunity to participate in early-stage planning, design, and implementation of team and projects, driving core technology and product innovation.\n2.International Team: Work with colleagues from 26 countries, experience a diverse and open work environment, and expand your global perspective.","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4737878111","sourceKey":"meituan_social","company":"美团","title":"Keeta技术-用户画像算法工程师","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4737878111&jobShareType=1","duty":"1. 负责 Keeta 用户理解与画像算法建设，基于用户多行为序列建模长期兴趣、短期意图、品类与商户偏好、价格敏感度、生命周期和长期价值，持续提升画像的准确性、覆盖率和时效性。\n2. 建设新用户和低活跃用户的冷启动能力，结合有限行为、本地供给、上下文与人群先验，提升新客转化和早期留存。\n3. 推动用户画像与统一用户表征在推荐、搜索、用户增长、人群圈选、优惠策略和消息触达等场景落地，产生可验证的业务增量。\n4. 建设面向运营的 AI 员工，结合用户理解、业务目标和运营经验，辅助运营完成问题诊断、策略制定、执行跟进和效果复盘，提升运营操盘效率与业务效果。\n5. 建立覆盖离线评测、A/B 实验、增量分析和线上监控的评测体系，并参与模型训练与在线推理链路建设，兼顾模型效果、服务效率和系统稳定性。","requirements":"1. 计算机、人工智能、数学、统计学或相关专业本科及以上学历，具有 3 年及以上机器学习、推荐、广告、增长或用户理解相关经验。\n2. 具备扎实的机器学习、深度学习和概率统计基础，熟悉分类、排序、表征学习及序列建模方法。\n3. 熟练掌握 Python 和 SQL，熟悉至少一种深度学习框架，具备大规模数据处理、模型训练、上线及问题排查能力。\n4. 具备大模型和 AI Agent 应用经验，能够结合实际业务问题设计并落地面向运营的智能化解决方案。\n5. 在推荐、搜索、广告、用户增长或智能营销方向有完整项目经验，具备良好的实验设计和效果分析能力。\n6. 具备较强的业务理解、问题拆解、沟通协作和项目推动能力，能够对最终效果负责。","description":"部门介绍\n美团核心本地商业下业务研发平台，基于公司“零售+科技”的战略导向，通过从底层架构到应用系统、从软件到硬件、从传统算法到GenAI的全方位技术研究，以及开发、运维、安全等全流程能力建设，致力于推动美团核心本地商业下需求侧与供给侧的数字化和智能化升级，助力业务实现高质量增长，优化用户使用体验，提升商户经营水平，促进行业生态伙伴关系的持续健康发展。团队秉持务实、自驱、开放以及追求卓越的工程师文化，一方面通过系统和技术体系的持续迭代升级，帮助业务高质量增长；另一方面，密切关注前沿技术趋势变化，积极创新技术能力，为业务未来发展创造新的可能性。期待优秀的你加入我们，在夯实专业、深耕平台的基础上与业务携手同行，一起用技术 “帮大家吃得更好，生活更好”。\n\n岗位职责\n1. 负责 Keeta 用户理解与画像算法建设，基于用户多行为序列建模长期兴趣、短期意图、品类与商户偏好、价格敏感度、生命周期和长期价值，持续提升画像的准确性、覆盖率和时效性。\n2. 建设新用户和低活跃用户的冷启动能力，结合有限行为、本地供给、上下文与人群先验，提升新客转化和早期留存。\n3. 推动用户画像与统一用户表征在推荐、搜索、用户增长、人群圈选、优惠策略和消息触达等场景落地，产生可验证的业务增量。\n4. 建设面向运营的 AI 员工，结合用户理解、业务目标和运营经验，辅助运营完成问题诊断、策略制定、执行跟进和效果复盘，提升运营操盘效率与业务效果。\n5. 建立覆盖离线评测、A/B 实验、增量分析和线上监控的评测体系，并参与模型训练与在线推理链路建设，兼顾模型效果、服务效率和系统稳定性。\n\n岗位基本要求\n1. 计算机、人工智能、数学、统计学或相关专业本科及以上学历，具有 3 年及以上机器学习、推荐、广告、增长或用户理解相关经验。\n2. 具备扎实的机器学习、深度学习和概率统计基础，熟悉分类、排序、表征学习及序列建模方法。\n3. 熟练掌握 Python 和 SQL，熟悉至少一种深度学习框架，具备大规模数据处理、模型训练、上线及问题排查能力。\n4. 具备大模型和 AI Agent 应用经验，能够结合实际业务问题设计并落地面向运营的智能化解决方案。\n5. 在推荐、搜索、广告、用户增长或智能营销方向有完整项目经验，具备良好的实验设计和效果分析能力。\n6. 具备较强的业务理解、问题拆解、沟通协作和项目推动能力，能够对最终效果负责。\n\n具备以下条件优先\n1. 有跨国家、跨城市业务经验，了解模型迁移、用户数据治理及跨地区数据合规问题。\n2. 主导过面向营销、增长或运营场景的 AI Agent、AI 员工从 0 到 1 建设，并完成业务效果验证。\n3. 有将 LLM 用于用户意图理解、标签生成或画像解释，并完成线上效果验证的经验。\n\n岗位亮点\n1. 核心算法底座建设：参与 Keeta 用户理解与统一画像体系建设，能力将服务推荐、搜索、用户增长和营销决策等多个核心场景；\n2. AI 员工真实业务场景：将用户理解与 AI Agent 结合，辅助运营制定策略和开展操盘，参与从方案设计、业务落地到效果验证的完整过程；\n3. 国际化算法挑战：面对不同国家和城市的用户、供给及数据差异，解决冷启动、画像时效性和跨市场泛化等问题；\n4. 完整成长空间：参与从模型设计、训练上线到业务落地和效果验证的完整链路，并有机会独立负责关键方向。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4767371442","sourceKey":"meituan_social","company":"美团","title":"高级Java开发工程师（作者研发方向）-点评技术部","city":"上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4767371442&jobShareType=1","duty":"1. 负责大众点评作者成长与作者激励等核心系统的研发工作，构建体系化的作者侧系统能力，支撑业务迭代与增长；\n2. 深入理解业务，承接相关需求的技术设计与开发，与产品、运营等团队高效协作，将业务需求拆解细化并落地实施，持续关注用户体验和转化效果；\n3. 负责系统的架构演进，对复杂问题进行拆解和落地，持续优化核心架构，保障系统架构的合理性与前瞻性，提升可扩展性和可维护性；\n4. 负责领域系统的稳定性与资损防控体系建设，建立健全风险识别与防控机制，保障系统长期稳定运行；\n5. 持续探索并推动AI技术在作者成长与激励等业务场景及日常研发中的深度结合与落地，以技术创新驱动业务指标增长与团队效能提升。","requirements":"1. 本科及以上学历，计算机及相关专业，3年以上互联网研发经验；\n2. Java基础扎实，理解IO、多线程、集合等基础框架，对JVM原理有一定了解，熟悉Spring、MyBatis等主流开源框架并清楚其实现原理，能编写高质量、简洁清晰的代码；\n3. 熟悉分布式系统的设计和应用，熟悉分布式、缓存、消息等常用机制，能对常用技术进行合理应用解决实际问题，具备线上服务稳定性保障能力；\n4. 具备业务架构、领域驱动、设计模式、系统重构等控制系统复杂度的实践经验；\n5. 具备优秀的业务理解能力，能够主动从业务问题出发提出技术解决方案；\n6. 具备良好的问题分析和解决能力、沟通协作能力，有较强的主人翁意识和自驱力；\n7. 能熟练应用AI辅助需求分析、代码开发与效能提升，具备推动AI技术在业务场景中落地的经验或强烈意愿。","description":"部门介绍\n美团核心本地商业下业务研发平台，基于公司“零售+科技”的战略导向，通过从底层架构到应用系统、从软件到硬件、从传统算法到GenAI的全方位技术研究，以及开发、运维、安全等全流程能力建设，致力于推动美团核心本地商业下需求侧与供给侧的数字化和智能化升级，助力业务实现高质量增长，优化用户使用体验，提升商户经营水平，促进行业生态伙伴关系的持续健康发展。团队秉持务实、自驱、开放以及追求卓越的工程师文化，一方面通过系统和技术体系的持续迭代升级，帮助业务高质量增长；另一方面，密切关注前沿技术趋势变化，积极创新技术能力，为业务未来发展创造新的可能性。期待优秀的你加入我们，在夯实专业、深耕平台的基础上与业务携手同行，一起用技术 “帮大家吃得更好，生活更好”。\n\n岗位职责\n1. 负责大众点评作者成长与作者激励等核心系统的研发工作，构建体系化的作者侧系统能力，支撑业务迭代与增长；\n2. 深入理解业务，承接相关需求的技术设计与开发，与产品、运营等团队高效协作，将业务需求拆解细化并落地实施，持续关注用户体验和转化效果；\n3. 负责系统的架构演进，对复杂问题进行拆解和落地，持续优化核心架构，保障系统架构的合理性与前瞻性，提升可扩展性和可维护性；\n4. 负责领域系统的稳定性与资损防控体系建设，建立健全风险识别与防控机制，保障系统长期稳定运行；\n5. 持续探索并推动AI技术在作者成长与激励等业务场景及日常研发中的深度结合与落地，以技术创新驱动业务指标增长与团队效能提升。\n\n岗位基本要求\n1. 本科及以上学历，计算机及相关专业，3年以上互联网研发经验；\n2. Java基础扎实，理解IO、多线程、集合等基础框架，对JVM原理有一定了解，熟悉Spring、MyBatis等主流开源框架并清楚其实现原理，能编写高质量、简洁清晰的代码；\n3. 熟悉分布式系统的设计和应用，熟悉分布式、缓存、消息等常用机制，能对常用技术进行合理应用解决实际问题，具备线上服务稳定性保障能力；\n4. 具备业务架构、领域驱动、设计模式、系统重构等控制系统复杂度的实践经验；\n5. 具备优秀的业务理解能力，能够主动从业务问题出发提出技术解决方案；\n6. 具备良好的问题分析和解决能力、沟通协作能力，有较强的主人翁意识和自驱力；\n7. 能熟练应用AI辅助需求分析、代码开发与效能提升，具备推动AI技术在业务场景中落地的经验或强烈意愿。\n\n具备以下条件优先\n1. 有作者成长和激励相关系统设计开发经验者优先。\n\n岗位亮点\n1. 驱动业务增长的核心技术方向，能积累体系化的领域知识和复杂业务系统研发经验，显著锻炼和提升专业能力；\n2. 团队正积极推进AI化转型，鼓励将AI等前沿技术深度融入业务场景与日常研发，智能化的工作环境与浓厚的技术探索氛围，将助你实现个人能力与技术视野的双重跃升。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4214244552","sourceKey":"meituan_social","company":"美团","title":"Keemart-配送时效与运力管理策略运营","city":"利雅得","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4214244552&jobShareType=1","duty":"1. 构建运力需求与HC配置模型\n\n建立单量预测与人效模型，形成标准化HC配置框架\n\n拆解人效波动与运力满足率之间的关系\n\n设计合理的运力冗余（Buffer）策略，平衡成本与时效\n\n2. 优化排班与出勤策略\n\n设计峰值班、短班及弹性班次结构\n\n优化出勤率与排班匹配度\n\n提升小时人效与全天资源利用率、\n\n\n3. 提升履约时效与服务稳定性\n\n监控并优化履约时效相关指标\n\n拆解履约链路关键节点并输出针对性改善方案并推动落地\n\n\n4. 协同派单逻辑与运力调度策略\n\n与产品/算法协作优化派单规则\n\n识别异常订单分布与运力错配问题\n\n推动多单合并与高峰期策略优化","requirements":"基础要求\n\n本科及以上学历，理工科、运筹学、数据相关专业优先\n\n3年以上履约优化、运力策略或排班管理经验\n\n具备较强的数据分析与结构化思维能力","description":"部门介绍\n美团的使命是“帮大家吃得更好，生活更好”，公司聚焦“零售 + 科技”战略，和广大商户与各类合作伙伴一起，努力为消费者提供品质生活，推动商品零售和服务零售在需求侧和供给侧的数字化转型。\n2018年9月20日，美团正式在港交所挂牌上市。美团将始终坚持以客户为中心，不断加大在科技研发方面的投入，更好承担社会责任，更多创造社会价值，与广大合作伙伴一起发展共赢。\n\n岗位职责\n1. 构建运力需求与HC配置模型\n\n建立单量预测与人效模型，形成标准化HC配置框架\n\n拆解人效波动与运力满足率之间的关系\n\n设计合理的运力冗余（Buffer）策略，平衡成本与时效\n\n2. 优化排班与出勤策略\n\n设计峰值班、短班及弹性班次结构\n\n优化出勤率与排班匹配度\n\n提升小时人效与全天资源利用率、\n\n\n3. 提升履约时效与服务稳定性\n\n监控并优化履约时效相关指标\n\n拆解履约链路关键节点并输出针对性改善方案并推动落地\n\n\n4. 协同派单逻辑与运力调度策略\n\n与产品/算法协作优化派单规则\n\n识别异常订单分布与运力错配问题\n\n推动多单合并与高峰期策略优化\n\n岗位基本要求\n基础要求\n\n本科及以上学历，理工科、运筹学、数据相关专业优先\n\n3年以上履约优化、运力策略或排班管理经验\n\n具备较强的数据分析与结构化思维能力\n\n具备以下条件优先\n即时配送 / 本地生活 / 物流行业经验\n\n有排班模型或线性规划经验\n\n熟悉A/B Test与策略验证方法\n\n有跨部门协作或项目管理经验\n\n岗位亮点\n1. 核心业务中枢岗位，直接影响经营结果\n\n2. 国际化业务环境","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:2993005551","sourceKey":"meituan_social","company":"美团","title":"Keemart-配送成本定价专家","city":"北京市/利雅得","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=2993005551&jobShareType=1","duty":"一、配送成本模型搭建与管理\n搭建并维护单均配送成本模型（人力、补贴、车型等维度）\n进行城市/站点成本结构拆解与分析\n建立成本波动预警机制\n输出月度/季度成本复盘报告\n二、薪资与激励方案设计\n设计不同类型骑手的薪资结构\n制定基础薪资、门槛激励、峰值激励与临时补贴策略\n评估薪资方案对人效、出勤率与流失率的影响\n定期优化计费模型与补贴结构\n三、骑手结构与车型结构优化\n不同城市骑手类型占比规划\n成本效率评估\n运力结构优化与成本平衡方案\n四、价格调整与策略试点\n设计价格调整策略及补贴机制\n推动A/B Test试点项目\n输出策略效果分析与决策建议\n五、跨部门协作与决策支持\n与时效、排班、商管、结算及财务团队协同\n提供经营决策数据支持\n支撑管理层汇报与战略规划","requirements":"本科及以上学历，物流管理或供应链管理专业或3年以上配送运营相关工作经验；\n具有良好的沟通协调和跨团队合作能力，能与其他部门或者外部单位良好的沟通，踏实认真、有责任感；\n熟练使用各类办公软件，具备良好的数据处理分析、文档整理总结能力；","description":"部门介绍\n美团的使命是“帮大家吃得更好，生活更好”，公司聚焦“零售 + 科技”战略，和广大商户与各类合作伙伴一起，努力为消费者提供品质生活，推动商品零售和服务零售在需求侧和供给侧的数字化转型。\n2018年9月20日，美团正式在港交所挂牌上市。美团将始终坚持以客户为中心，不断加大在科技研发方面的投入，更好承担社会责任，更多创造社会价值，与广大合作伙伴一起发展共赢。\n\n岗位职责\n一、配送成本模型搭建与管理\n搭建并维护单均配送成本模型（人力、补贴、车型等维度）\n进行城市/站点成本结构拆解与分析\n建立成本波动预警机制\n输出月度/季度成本复盘报告\n二、薪资与激励方案设计\n设计不同类型骑手的薪资结构\n制定基础薪资、门槛激励、峰值激励与临时补贴策略\n评估薪资方案对人效、出勤率与流失率的影响\n定期优化计费模型与补贴结构\n三、骑手结构与车型结构优化\n不同城市骑手类型占比规划\n成本效率评估\n运力结构优化与成本平衡方案\n四、价格调整与策略试点\n设计价格调整策略及补贴机制\n推动A/B Test试点项目\n输出策略效果分析与决策建议\n五、跨部门协作与决策支持\n与时效、排班、商管、结算及财务团队协同\n提供经营决策数据支持\n支撑管理层汇报与战略规划\n\n岗位基本要求\n本科及以上学历，物流管理或供应链管理专业或3年以上配送运营相关工作经验；\n具有良好的沟通协调和跨团队合作能力，能与其他部门或者外部单位良好的沟通，踏实认真、有责任感；\n熟练使用各类办公软件，具备良好的数据处理分析、文档整理总结能力；\n\n岗位亮点\n新业务新团队，挑战与机会并存，未来机会无限！","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4776484793","sourceKey":"meituan_social","company":"美团","title":"Quality Assurance BP for Brazil","city":"北京市/上海市/深圳市/圣保罗/广州市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4776484793&jobShareType=1","duty":"1. Quality system tools implementation:\nWork with other function team to implement tools in global scale to support quality system to be able to scalable and localize such as transaction monitoring tool, coaching tool, DSAT analysis etc… \n2. Regulation on transaction monitoring:\nMaintain quality standard to ensure the ability to drive for customer experience and business adherence and develop corresponding policy to ensure the effectiveness. \n3. Close with business and drive the change: \nUnderstand the overall service operation performance status combine opportunity in customer journey to identify key area and drive the change to enhance customer experience with targeted quality audit approach.\n4. Stay connected with regional team:\nWork close with regional team and provide quality intelligence from global perspective.","requirements":"1. Proven experience (at least 3+ years) in quality manager or senior quality assurance role, preferably within a contact center environment.\n2. Fluency in both Portuguese & English. \n3. Strong understanding of quality assurance methodologies and best practices in Customer Service.\n4. Experience of work with cross function team and projects.\n5. Excellent communication and interpersonal skills for delivering constructive feedback.\n6. Ability to work independently and collaboratively in a fast-paced environment.\n7. A genuine passion for delivering exceptional customer experience.","description":"部门介绍\nKeeta是全球领先外卖平台美团旗下的独立品牌，肩负着“帮大家吃得更好，生活更好”的使命。依托美团深耕中国市场15年的技术与运营积淀，我们正引领全球餐饮与商品即时配送服务的创新与发展。\n\n自2023年成立以来，Keeta始终扎根社区并创造价值。我们为用户提供可靠的外卖体验，以智慧技术助餐厅提升经营效率，在为骑手拓宽收入来源的同时，也充分提供安全保障措施。基于这份多方共赢、共同成长的理念，我们的业务已从中国香港稳步拓展至中东及巴西，并持续向世界迈进。\n\n岗位职责\n1. Quality system tools implementation:\nWork with other function team to implement tools in global scale to support quality system to be able to scalable and localize such as transaction monitoring tool, coaching tool, DSAT analysis etc… \n2. Regulation on transaction monitoring:\nMaintain quality standard to ensure the ability to drive for customer experience and business adherence and develop corresponding policy to ensure the effectiveness. \n3. Close with business and drive the change: \nUnderstand the overall service operation performance status combine opportunity in customer journey to identify key area and drive the change to enhance customer experience with targeted quality audit approach.\n4. Stay connected with regional team:\nWork close with regional team and provide quality intelligence from global perspective.\n\n岗位基本要求\n1. Proven experience (at least 3+ years) in quality manager or senior quality assurance role, preferably within a contact center environment.\n2. Fluency in both Portuguese & English. \n3. Strong understanding of quality assurance methodologies and best practices in Customer Service.\n4. Experience of work with cross function team and projects.\n5. Excellent communication and interpersonal skills for delivering constructive feedback.\n6. Ability to work independently and collaboratively in a fast-paced environment.\n7. A genuine passion for delivering exceptional customer experience.\n\n具备以下条件优先\nWorking experience on service organization HQ team\nExperience study or work in Brazil with culture understand\n\n岗位亮点\nJoin us in shaping the future of Keeta's offshore strategic initiatives! As a key player, you will have the unique opportunity to contribute to the foundational blueprint of our operations while exploring innovative directions for business development.\nCollaborate alongside top-tier professionals from around the globe, working together to create impactful strategies that will define our success in new markets. Your insights and expertise will be instrumental in designing a roadmap that not only meets our goals but also elevates the customer experience.\nWe look forward to welcoming you to our team and embarking on this exciting journey together!","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4777854549","sourceKey":"meituan_social","company":"美团","title":"大众点评信息流产品负责人","city":"上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4777854549&jobShareType=1","duty":"负责点评业务信息流的内容供给与推荐分发，围绕 POI 决策场景建设可持续、可规模化、可信任的内容供给底盘，提升用户决策效率与长期健康增长。\n1. 负责点评信息流内容供给体系的整体规划与建设，围绕 POI 决策场景，完善 UGC、达人、商户等多类型内容的生产机制、准入标准与质量分层体系（真实性、信息密度、可决策性、时效性等），持续提升内容规模、覆盖广度与供给结构健康度；\n2. 负责 POI 覆盖与长尾供给能力建设，提升长尾城市、品类、POI 的内容覆盖率与更新频率，完善新 POI、新商户的内容冷启动机制，降低\"有店无内容/内容不可用\"的问题；\n3. 负责内容可信与治理机制建设，完善虚假内容、软广、低质搬运、刷量等识别与处置的产品闭环，推动算法、风控、审核与业务协同，保障内容长期可信与合规安全；\n4. 主导供给分层与流量分发联动策略建设，制定不同内容池的流量策略与配额，提升新内容探索效率、长尾覆盖与整体消费效率，对用户规模与消费、转化的长期健康增长负责；\n5. 负责信息流基础体验与搜索联动方向的产品规划，围绕呈现效率、浏览交互、搜索引导、推荐、发现等场景，提升内容可发现性与可决策性，强化\"内容—搜索—决策—到店/下单\"的闭环；\n6. 统筹信息流在 POI、榜单、搜索、频道/同城、交易链路等多业务场域中的协同机制，建立清晰的产品判断标准与决策原则，推动算法、工程、运营、风控等团队形成一致目标并交付结果。","requirements":"1. 7年以上工作经验，本科及以上学历，具备成熟的C端策略产品能力，对本地生活POI决策链路与信息供给有长期积累的判断力；\n2. 有独立负责复杂供给体系或核心流量、内容分发、推荐场景经验，对结果具备强ownership，能在多团队协作中定义方向并推动关键问题落地；\n3. 对内容供给有体系化方法论，能在覆盖、质量、时效、治理与成本之间做取舍并形成可复用机制；有内容治理、反作弊、风控合规经验者优先；\n4. 数据驱动，具备较强的数据分析能力与实验设计能力，能用A/B实验与因果评估推动策略迭代；\n5. 具备AI产品能力，能将大模型/多模态/结构化理解等技术能力落地到内容供给与分发场景中（如内容质量自动评估、POI信息结构化提取、搜索摘要/推荐解释等），推动AI能力从\"加分项\"变成供给体系的核心基础设施。","description":"部门介绍\n大众点评作为国内重要的本地生活消费决策参考平台，多年来深耕本地生活消费领域，深受广大用户的信任和喜爱。我们的业务覆盖了吃喝玩乐游购娱等生活场景，通过极具辨识度和公信力的”星级“和”评价“产品，为数亿用户提供了全面、可信的消费决策依据。为更好满足用户探索城市的需求，大众点评在原有星级和评价的基础上，以信息流产品形式，助力用户发现更多好去处。大量优秀年轻同学的加入，为我们的团队注入了澎湃活力。我们相信，真实的生活是不可替代的，真实的感受是值得记录的，真实的美好是要被看到的。希望优秀的你能和我们一起，帮助广大用户在大众点评上发现更多好去处，找到属于自己的人间烟火气，共创美好生活。\n\n岗位职责\n负责点评业务信息流的内容供给与推荐分发，围绕 POI 决策场景建设可持续、可规模化、可信任的内容供给底盘，提升用户决策效率与长期健康增长。\n1. 负责点评信息流内容供给体系的整体规划与建设，围绕 POI 决策场景，完善 UGC、达人、商户等多类型内容的生产机制、准入标准与质量分层体系（真实性、信息密度、可决策性、时效性等），持续提升内容规模、覆盖广度与供给结构健康度；\n2. 负责 POI 覆盖与长尾供给能力建设，提升长尾城市、品类、POI 的内容覆盖率与更新频率，完善新 POI、新商户的内容冷启动机制，降低\"有店无内容/内容不可用\"的问题；\n3. 负责内容可信与治理机制建设，完善虚假内容、软广、低质搬运、刷量等识别与处置的产品闭环，推动算法、风控、审核与业务协同，保障内容长期可信与合规安全；\n4. 主导供给分层与流量分发联动策略建设，制定不同内容池的流量策略与配额，提升新内容探索效率、长尾覆盖与整体消费效率，对用户规模与消费、转化的长期健康增长负责；\n5. 负责信息流基础体验与搜索联动方向的产品规划，围绕呈现效率、浏览交互、搜索引导、推荐、发现等场景，提升内容可发现性与可决策性，强化\"内容—搜索—决策—到店/下单\"的闭环；\n6. 统筹信息流在 POI、榜单、搜索、频道/同城、交易链路等多业务场域中的协同机制，建立清晰的产品判断标准与决策原则，推动算法、工程、运营、风控等团队形成一致目标并交付结果。\n\n岗位基本要求\n1. 7年以上工作经验，本科及以上学历，具备成熟的C端策略产品能力，对本地生活POI决策链路与信息供给有长期积累的判断力；\n2. 有独立负责复杂供给体系或核心流量、内容分发、推荐场景经验，对结果具备强ownership，能在多团队协作中定义方向并推动关键问题落地；\n3. 对内容供给有体系化方法论，能在覆盖、质量、时效、治理与成本之间做取舍并形成可复用机制；有内容治理、反作弊、风控合规经验者优先；\n4. 数据驱动，具备较强的数据分析能力与实验设计能力，能用A/B实验与因果评估推动策略迭代；\n5. 具备AI产品能力，能将大模型/多模态/结构化理解等技术能力落地到内容供给与分发场景中（如内容质量自动评估、POI信息结构化提取、搜索摘要/推荐解释等），推动AI能力从\"加分项\"变成供给体系的核心基础设施。\n\n具备以下条件优先\n具备内容理解和内容供给经验优先\n\n岗位亮点\n1. 建设点评平台级POI内容供给底盘，做的是长期机制能力，不是单点功能优化，影响深远；\n2. 供给×分发×搜索联动的组合挑战，直接影响用户决策效率与交易转化，结果可被业务强感知；\n3. 在内容可信、用户体验与商业目标多重约束下做关键取舍，复杂度高、成长上限高。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4718765677","sourceKey":"meituan_social","company":"美团","title":"渠道运营专家","city":"上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4718765677&jobShareType=1","duty":"1. 运营产品化设计：围绕服务商赋能设计和迭代可落地的运营产品方案，将数据洞察转化为服务商可执行的行动指令，打通\"资源→方案→落地\"链路。\n2. 数据诊断与问题定位：建立并维护服务商经营指标体系，通过数据分析定位落地实施中的具体问题，搭建从数据发现→问题归因→行动建议的完整闭环，支撑业务决策，对服务商分层经营数据进行持续监测，输出诊断报告并推动改善动作落地。\n3. 一线经验沉淀：深入服务商经营一线，识别运营痛点与能力缺口，将一线跑通的经验提炼为可复制的运营方案和标准，反哺团队方法论，推动赋能体系从有到优的迭代。\n4. 跨团队协同：协同渠道经理、系统、机制设计等角色，确保运营方案从设计到落地的完整闭环，将资源整合为服务商可使用的标准服务方案。","requirements":"1、本科及以上学历，3~5年以上策略运营中台经验，具备民宿、酒店相关线下运营经验者优先，有0-1项目、AI应用经验者优先；\n2、有较强的数据分析能力，熟练使用SQL，能通过数据驱动业务优化；\n3、具备市场分析及策略运营方案制定能力；\n4、逻辑清晰、沟通高效，具备较强的责任意识和团队协作能力。","description":"部门介绍\n美团酒店旅行业务涵盖酒店、民宿、机票、火车票、旅游度假、景点门票等各类住行游品类，通过与产业上下游的深度合作，为用户提供美好的旅游旅行体验。我们积极打造AI友好型组织，使用AI等新技术提升旅游服务的供需匹配效率，更好满足用户个性化、多样化的出游需求。我们持续深耕产业链，用数字化服务助力实体商家高质量经营，探索自有品牌等供给新模式，打造健康的商家生态，保障用户服务体验。为满足用户日益增长的跨境旅行需求，我们将聚焦亚太区域，打造高品质的住宿、交通、游玩等服务矩阵。\n这里有多元的业务布局、持续的成长空间，无论是向往的远方还是眼前的工作，一路都是风景相伴。加入我们，共同为用户创造旅游旅行中的高光时刻！\n\n岗位职责\n1. 运营产品化设计：围绕服务商赋能设计和迭代可落地的运营产品方案，将数据洞察转化为服务商可执行的行动指令，打通\"资源→方案→落地\"链路。\n2. 数据诊断与问题定位：建立并维护服务商经营指标体系，通过数据分析定位落地实施中的具体问题，搭建从数据发现→问题归因→行动建议的完整闭环，支撑业务决策，对服务商分层经营数据进行持续监测，输出诊断报告并推动改善动作落地。\n3. 一线经验沉淀：深入服务商经营一线，识别运营痛点与能力缺口，将一线跑通的经验提炼为可复制的运营方案和标准，反哺团队方法论，推动赋能体系从有到优的迭代。\n4. 跨团队协同：协同渠道经理、系统、机制设计等角色，确保运营方案从设计到落地的完整闭环，将资源整合为服务商可使用的标准服务方案。\n\n岗位基本要求\n1、本科及以上学历，3~5年以上策略运营中台经验，具备民宿、酒店相关线下运营经验者优先，有0-1项目、AI应用经验者优先；\n2、有较强的数据分析能力，熟练使用SQL，能通过数据驱动业务优化；\n3、具备市场分析及策略运营方案制定能力；\n4、逻辑清晰、沟通高效，具备较强的责任意识和团队协作能力。\n\n岗位亮点\n1、薪资福利待遇良好；\n2、提供广阔的发展空间和晋升机会。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4757754732","sourceKey":"meituan_social","company":"美团","title":"IT operation engineer","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4757754732&jobShareType=1","duty":"1. 服务基础设施规划与交付\n根据 IT 架构技术标准和建设规范，负责新开业务 IT 基础设施的本地化规划、测试验证及落地实施；推动设备选型、采购执行、到货验收和上线交付，保障建设质量、成本和交付周期。\n2. 本地化 IT 解决方案支持\n制定并实施本地化 IT 基础设施解决方案，覆盖办公网络、机房/弱电间、终端接入及相关配套系统的建设、维护和运营；能够适配当地办公环境、合规要求和业务发展需要。负责本地 IT 系统集成建设，确保技术方案、安全要求及运维规范在当地有效实施；结合现场条件、供应商能力及业务需求，持续优化建设方案、交付质量和实施效率。\n3. 新产品设计\n结合海外业务发展的实际需求，识别 IT 基础设施、现场服务和智能化运维中的新需求与痛点；负责新产品、新服务能力的方案设计、试点验证和规模化推广。包括需求调研、用户旅程梳理、技术方案评估、MVP试点、上线验收、效果复盘及持续迭代，推动成熟方案沉淀为可标准化、可复制的全球交付能力。\n4. AI Native 运维与智能化建设\n结合 AI 能力推动基础设施运维模式升级，探索并落地 AI 在网络告警分析、故障定位、知识库、工单处理、配置核查、容量趋势分析等IT场景中的应用，提升问题响应效率和服务稳定性。\n\n1. IT Infrastructure Planning and Delivery\nBased on IT architecture standards and construction guidelines, lead the localized planning, testing, validation, and implementation of IT infrastructure for new business launches. Drive equipment selection, procurement execution, delivery acceptance, and go-live handover, ensuring delivery quality, cost control, and project timelines.\n2. Localized IT Solutions and System Integration\nDevelop and implement localized IT infrastructure solutions covering office networks, server rooms/telecom rooms, end-user connectivity, and supporting systems, ensuring alignment with local office environments, regulatory requirements, and business needs.\nLead local IT system integration to ensure that technical solutions, security requirements, and operational standards are effectively implemented. Continuously optimize solution design, delivery quality, and implementation efficiency by considering site conditions, vendor capabilities, and business requirements.\n3. New Product and Service Design\nIdentify emerging needs and pain points across IT infrastructure, onsite services, and intelligent operations based on the evolving requirements of overseas businesses. Design, pilot, validate, and scale new products and service capabilities.\nResponsibilities include requirements research, user journey mapping, technical solution assessment, MVP pilots, go-live acceptance, performance reviews, and continuous iteration. Mature solutions should be standardized into scalable and repeatable global delivery capabilities.\n4. AI-Native Operations and Intelligent Infrastructure\nLeverage AI capabilities to upgrade the IT infrastructure operations model. Explore and implement AI use cases across IT scenarios, including network alert analysis, fault diagnosis, knowledge management, ticket processing, configuration compliance checks, and capacity trend analysis, in order to improve incident response efficiency and service reliability.","requirements":"1. 计算机科学、信息技术、通信工程、网络工程或相关工程类专业，本科及以上学历。\n2. 具备3 年及以上企业 IT 服务建设、网络、机房建设、系统集成或服务运维相关经验；有出海项目经验者优先。\n3. 熟悉企业级弱电及网络架构、网络设备部署及运维管理，掌握交换、路由、无线网络、网络安全知识。\n4. 对 AI 技术及其在 IT 运维领域的应用有较强兴趣和实践意识，能够合理使用 AI 工具辅助进行日志分析、告警归因、故障排查、知识检索、方案撰写和自动化脚本开发。\n5. 具备 IT 解决方案制定和实施经验，能够综合考虑总部标准、现场条件、成本、交付周期及业务需求，推动方案高质量落地。\n6. 具备良好的英文跨文化沟通、项目协调及供应商管理能力，能够与跨区域 IT 团队、当地服务商和业务团队高效协作。\n\n1. Bachelor’s degree or above in Computer Science, Information Technology, Telecommunications Engineering, Network Engineering, or a related engineering discipline.\n2. At least 3 years of relevant experience in enterprise IT service delivery, network infrastructure, data center/server room construction, system integration, or IT service operations. Experience supporting international expansion or overseas projects is preferred.\n3. Familiarity with enterprise low-voltage systems and network architecture, network device deployment, and operations management. Solid knowledge of switching, routing, wireless networking, and network security is required.\n4. Strong interest in and practical awareness of AI technologies and their application in IT operations. Able to leverage AI tools appropriately to support log analysis, alert correlation and root cause analysis, troubleshooting, knowledge retrieval, solution documentation, and automation script development.\n5. Experience in developing and implementing IT solutions, with the ability to balance headquarters standards, on-site conditions, cost, delivery timelines, and business requirements to drive high-quality solution delivery.\n6. Strong English communication skills in a cross-cultural environment, along with project coordination and vendor management capabilities. Able to collaborate effectively with cross-regional IT teams, local service providers, and business stakeholders.","description":"部门介绍\n基础研发平台是美团的核心技术平台，立足于“零售+科技”的战略定位，通过打造人工智能、大数据、云计算、安全等核心技术能力，以及研发效能平台、企业应用平台等公共服务，为业务提供稳定安全、扩展易用、技术领先的平台技术和产品服务。\n在这里，我们会参与到最前沿的技术研发和探索；能够接触超规模集群、海量数据，挑战高复杂业务场景，有机会与业界一流的工程师一起并肩前行。\n在这里，我们有超强的技术氛围，持续向社区贡献业界实践，加速行业技术发展；我们有完善的互联网学习生态圈，重视底层逻辑和方法论，助力职业生涯的非线性成长。\n真诚地邀请你，和我们一起驱动技术发展，创造行业价值。\n\n岗位职责\n1. 服务基础设施规划与交付\n根据 IT 架构技术标准和建设规范，负责新开业务 IT 基础设施的本地化规划、测试验证及落地实施；推动设备选型、采购执行、到货验收和上线交付，保障建设质量、成本和交付周期。\n2. 本地化 IT 解决方案支持\n制定并实施本地化 IT 基础设施解决方案，覆盖办公网络、机房/弱电间、终端接入及相关配套系统的建设、维护和运营；能够适配当地办公环境、合规要求和业务发展需要。负责本地 IT 系统集成建设，确保技术方案、安全要求及运维规范在当地有效实施；结合现场条件、供应商能力及业务需求，持续优化建设方案、交付质量和实施效率。\n3. 新产品设计\n结合海外业务发展的实际需求，识别 IT 基础设施、现场服务和智能化运维中的新需求与痛点；负责新产品、新服务能力的方案设计、试点验证和规模化推广。包括需求调研、用户旅程梳理、技术方案评估、MVP试点、上线验收、效果复盘及持续迭代，推动成熟方案沉淀为可标准化、可复制的全球交付能力。\n4. AI Native 运维与智能化建设\n结合 AI 能力推动基础设施运维模式升级，探索并落地 AI 在网络告警分析、故障定位、知识库、工单处理、配置核查、容量趋势分析等IT场景中的应用，提升问题响应效率和服务稳定性。\n\n1. IT Infrastructure Planning and Delivery\nBased on IT architecture standards and construction guidelines, lead the localized planning, testing, validation, and implementation of IT infrastructure for new business launches. Drive equipment selection, procurement execution, delivery acceptance, and go-live handover, ensuring delivery quality, cost control, and project timelines.\n2. Localized IT Solutions and System Integration\nDevelop and implement localized IT infrastructure solutions covering office networks, server rooms/telecom rooms, end-user connectivity, and supporting systems, ensuring alignment with local office environments, regulatory requirements, and business needs.\nLead local IT system integration to ensure that technical solutions, security requirements, and operational standards are effectively implemented. Continuously optimize solution design, delivery quality, and implementation efficiency by considering site conditions, vendor capabilities, and business requirements.\n3. New Product and Service Design\nIdentify emerging needs and pain points across IT infrastructure, onsite services, and intelligent operations based on the evolving requirements of overseas businesses. Design, pilot, validate, and scale new products and service capabilities.\nResponsibilities include requirements research, user journey mapping, technical solution assessment, MVP pilots, go-live acceptance, performance reviews, and continuous iteration. Mature solutions should be standardized into scalable and repeatable global delivery capabilities.\n4. AI-Native Operations and Intelligent Infrastructure\nLeverage AI capabilities to upgrade the IT infrastructure operations model. Explore and implement AI use cases across IT scenarios, including network alert analysis, fault diagnosis, knowledge management, ticket processing, configuration compliance checks, and capacity trend analysis, in order to improve incident response efficiency and service reliability.\n\n岗位基本要求\n1. 计算机科学、信息技术、通信工程、网络工程或相关工程类专业，本科及以上学历。\n2. 具备3 年及以上企业 IT 服务建设、网络、机房建设、系统集成或服务运维相关经验；有出海项目经验者优先。\n3. 熟悉企业级弱电及网络架构、网络设备部署及运维管理，掌握交换、路由、无线网络、网络安全知识。\n4. 对 AI 技术及其在 IT 运维领域的应用有较强兴趣和实践意识，能够合理使用 AI 工具辅助进行日志分析、告警归因、故障排查、知识检索、方案撰写和自动化脚本开发。\n5. 具备 IT 解决方案制定和实施经验，能够综合考虑总部标准、现场条件、成本、交付周期及业务需求，推动方案高质量落地。\n6. 具备良好的英文跨文化沟通、项目协调及供应商管理能力，能够与跨区域 IT 团队、当地服务商和业务团队高效协作。\n\n1. Bachelor’s degree or above in Computer Science, Information Technology, Telecommunications Engineering, Network Engineering, or a related engineering discipline.\n2. At least 3 years of relevant experience in enterprise IT service delivery, network infrastructure, data center/server room construction, system integration, or IT service operations. Experience supporting international expansion or overseas projects is preferred.\n3. Familiarity with enterprise low-voltage systems and network architecture, network device deployment, and operations management. Solid knowledge of switching, routing, wireless networking, and network security is required.\n4. Strong interest in and practical awareness of AI technologies and their application in IT operations. Able to leverage AI tools appropriately to support log analysis, alert correlation and root cause analysis, troubleshooting, knowledge retrieval, solution documentation, and automation script development.\n5. Experience in developing and implementing IT solutions, with the ability to balance headquarters standards, on-site conditions, cost, delivery timelines, and business requirements to drive high-quality solution delivery.\n6. Strong English communication skills in a cross-cultural environment, along with project coordination and vendor management capabilities. Able to collaborate effectively with cross-regional IT teams, local service providers, and business stakeholders.\n\n具备以下条件优先\nCandidates with CCIE, PgMP, or other relevant networking or project management certifications are preferred.\n\n岗位亮点\n1. 参与全球化新业务建设：直接参与海外新开城市、 IT 基建从 0 到 1 的规划和落地，服务美团全球化业务发展。\n2. AI Native 的 IT 实践场景：不仅建设和维护，更有机会将 AI 融入网络运维、故障处理、知识管理和自动化流程，推动传统现场 IT 服务向智能化运维演进。\n3. 覆盖完整基础设施链路：接触企业网络、无线、弱电、机房配套、视频安防、门禁、资产与供应商管理等多元技术场景。\n4. 直接开放的工作氛围：以逻辑、事实和结果说话，而非岗位级别和层级。\n5. 国际化协作与成长：与跨区域当地服务商及多元文化背景的同事协作，共建项目、共同进步。\n\n1. Contribute to Global Business Expansion: Directly participate in the end-to-end planning and delivery of IT infrastructure for new overseas cities and business launches, supporting Meituan’s global growth.\n2. AI-Native IT Practice: Go beyond infrastructure buildout and maintenance by applying AI to network operations, incident management, knowledge management, and automation workflows—helping evolve traditional onsite IT services into intelligent operations.\n3. End-to-End Infrastructure Exposure: Gain hands-on experience across a broad range of technical domains, including enterprise networks, wireless connectivity, low-voltage systems, server room infrastructure, video surveillance, access control, asset management, and vendor management.\n4. Open and Direct Work Environment: We value logic, facts, and results over titles or hierarchy.\n5. International Collaboration and Growth: Work closely with cross-regional teams, local service providers, and colleagues from diverse cultural backgrounds to build projects together and grow collectively.","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4762752684","sourceKey":"meituan_social","company":"美团","title":"加工主管-三方工厂管理","city":"北京市/深圳市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4762752684&jobShareType=1","duty":"1. 负责三方工厂的加工生产计划制定与执行，确保按时交付。  \n2. 协调工厂资源，优化加工流程，提升生产效率与质量。  \n3. 监督工厂现场运营，确保符合安全、环保及合规要求。  \n4. 对接三方工厂与内部团队，及时反馈生产进度与异常情况。","requirements":"1. 大学专科及以上学历，物流、供应链或相关专业优先。  \n2. 具备3年以上物流运营或工厂管理经验，熟悉三方工厂运作模式。  \n3. 具备良好的沟通协调能力与问题解决能力。  \n4. 能适应北京或深圳地区工作。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1. 负责三方工厂的加工生产计划制定与执行，确保按时交付。  \n2. 协调工厂资源，优化加工流程，提升生产效率与质量。  \n3. 监督工厂现场运营，确保符合安全、环保及合规要求。  \n4. 对接三方工厂与内部团队，及时反馈生产进度与异常情况。\n\n岗位基本要求\n1. 大学专科及以上学历，物流、供应链或相关专业优先。  \n2. 具备3年以上物流运营或工厂管理经验，熟悉三方工厂运作模式。  \n3. 具备良好的沟通协调能力与问题解决能力。  \n4. 能适应北京或深圳地区工作。\n\n具备以下条件优先\n有烘焙背景或者HM、DD加工、仓储背景的人员优先。\n\n岗位亮点\n1. 参与核心供应链环节，积累三方工厂管理经验。  \n2. 提供完善的培训体系与职业发展通道。  \n3. 工作地点覆盖一线城市，资源丰富，发展空间大。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4777207902","sourceKey":"meituan_social","company":"美团","title":"华西-大客户经理","city":"重庆市/成都市/贵阳市/昆明市/西安市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4777207902&jobShareType=1","duty":"1、销售目标：在达成门票在线销售合作基础上，挖掘客户需求，与客户开展整合营销、会员运营等深度合作。\n2、销售模式：厘清客户决策机制，挖掘研判客户需求，协同售前销售团队整合美团平台及生态合作伙伴在系统、产品、整合营销等方面的资源形成满足客户需求的解决方案，沟通谈判确保项目整体收益达标，风险可控，完成内部立项评估，最终达成项目签约；\n\n在合作推进过程中，大客户销售经理核心负责如下内容：\n1、对销售结果负责：大客户销售经理需要对负责客户做整体优先级的规划，完成周期内公司下达的销售目标；\n2、对合同内容负责：确保签署合同与立项一致；完整约定了双方权益，并规避了相关风险；\n3、对收益回收负责：项目交付后，关注客户履约的及时性和稳定性，如期回收收益；\n4、对客户关系负责：具体包括两个阶段，在售前阶段能给主动服务客户，理解客户需求（包含客户组织需求以及客户决策链关键角色的需求），为客户提供顾问式服务；在售后阶段能给保障项目履约，持续关注客户成功，赢得客户信赖。","requirements":"1.行业知识：了解OTA同行的各自优劣势，景区的运营模式，景区智慧化建设情况，行业主要的解决方案提供商情况等；\n2.客户管理：能够厘清客户的组织架构和决策链，在客户需求挖掘和识别上有方法，通过服务意识和专业知识赢取客户信赖，在决策者关系建设以及教练培养上有方法；\n3.谈判能力：有过充分的客户谈判训练，能够根据不同的拜访目标制定拜访策略。在与客户信息交互过程中能够准确传递价值，控制客户预期，处理突发异议，预判和管理合作风险，把控合作进程；\n4.解决方案：能够准确学习掌握已有解决方案的内容和价值，并能准确挖掘客户的需求，做到需求与解决方案的精准匹配；\n5.学习能力：好学，有开放的心态和对未知领域的好奇心和求知欲；学习有方法，具备学习意识，有总结复盘的能力。","description":"部门介绍\n美团酒店旅行业务涵盖酒店、民宿、机票、火车票、旅游度假、景点门票等各类住行游品类，通过与产业上下游的深度合作，为用户提供美好的旅游旅行体验。我们积极打造AI友好型组织，使用AI等新技术提升旅游服务的供需匹配效率，更好满足用户个性化、多样化的出游需求。我们持续深耕产业链，用数字化服务助力实体商家高质量经营，探索自有品牌等供给新模式，打造健康的商家生态，保障用户服务体验。为满足用户日益增长的跨境旅行需求，我们将聚焦亚太区域，打造高品质的住宿、交通、游玩等服务矩阵。\n这里有多元的业务布局、持续的成长空间，无论是向往的远方还是眼前的工作，一路都是风景相伴。加入我们，共同为用户创造旅游旅行中的高光时刻！\n\n岗位职责\n1、销售目标：在达成门票在线销售合作基础上，挖掘客户需求，与客户开展整合营销、会员运营等深度合作。\n2、销售模式：厘清客户决策机制，挖掘研判客户需求，协同售前销售团队整合美团平台及生态合作伙伴在系统、产品、整合营销等方面的资源形成满足客户需求的解决方案，沟通谈判确保项目整体收益达标，风险可控，完成内部立项评估，最终达成项目签约；\n\n在合作推进过程中，大客户销售经理核心负责如下内容：\n1、对销售结果负责：大客户销售经理需要对负责客户做整体优先级的规划，完成周期内公司下达的销售目标；\n2、对合同内容负责：确保签署合同与立项一致；完整约定了双方权益，并规避了相关风险；\n3、对收益回收负责：项目交付后，关注客户履约的及时性和稳定性，如期回收收益；\n4、对客户关系负责：具体包括两个阶段，在售前阶段能给主动服务客户，理解客户需求（包含客户组织需求以及客户决策链关键角色的需求），为客户提供顾问式服务；在售后阶段能给保障项目履约，持续关注客户成功，赢得客户信赖。\n\n岗位基本要求\n1.行业知识：了解OTA同行的各自优劣势，景区的运营模式，景区智慧化建设情况，行业主要的解决方案提供商情况等；\n2.客户管理：能够厘清客户的组织架构和决策链，在客户需求挖掘和识别上有方法，通过服务意识和专业知识赢取客户信赖，在决策者关系建设以及教练培养上有方法；\n3.谈判能力：有过充分的客户谈判训练，能够根据不同的拜访目标制定拜访策略。在与客户信息交互过程中能够准确传递价值，控制客户预期，处理突发异议，预判和管理合作风险，把控合作进程；\n4.解决方案：能够准确学习掌握已有解决方案的内容和价值，并能准确挖掘客户的需求，做到需求与解决方案的精准匹配；\n5.学习能力：好学，有开放的心态和对未知领域的好奇心和求知欲；学习有方法，具备学习意识，有总结复盘的能力。\n\n具备以下条件优先\n具备行业经验和G端资源人优先。\n\n岗位亮点\n1.五险一金。\n2.团队氛围好，有明确的晋升通道路径。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:3563898345","sourceKey":"meituan_social","company":"美团","title":"用户策略分析专家/User Strategy & Analytics Specialist","city":"利雅得","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=3563898345&jobShareType=1","duty":"1.业务监控与目标管理：负责用户侧核心KPI体系的搭建与维护，构建并持续优化周/月度经营监控框架，追踪业务目标达成进展。\n2.战略研究与洞察：综合运用数据分析、用户研究及市场调研等方法，深入研究关键业务问题，输出清晰的策略建议。\n3.运营策略支持：与运营团队紧密协作，参与用户侧补贴、活动、流量等策略的设计、分析与评估，推动A/B测试与迭代优化。\n4.数据产品管理：统筹内部数据产品需求（看板、取数、用户标签等），协调产品与技术团队，保障高质量数据基础设施的稳定交付。\n5.运用 AI 工具（如 ChatGPT、Copilot 等）辅助日常工作，提升产出效率与质量，主动探索 AI 在本岗位的应用最佳实践。\n\n1.Business Monitoring & Goal Management:Own and maintain the user-side KPI system; build and continuously optimize weekly/monthly performance monitoring frameworks to track progress against business targets.\n2.Strategic Research & Insights:Conduct in-depth studies on key business challenges using data analysis, user research, and market studies; deliver clear strategy .\n3.Operations Strategy Support:Partner with operations teams to design, analyze, and evaluate user-side initiatives including subsidies, campaigns, and traffic strategies; drive A/B testing and iterative optimization.\n4.Data Product Management:Manage internal data product requests (dashboards, data extraction, user tagging); coordinate with product and engineering teams to deliver reliable, high-quality data infrastructure.\n5.Leverage AI tools (e.g., ChatGPT, Copilot) to enhance daily workflows, improve content quality, and actively explore AI-driven best practices in marketing and brand operations.","requirements":"1.3年以上互联网、咨询或相关行业经验，具备运营、数据科学或商业分析背景。\n2.逻辑思维清晰，结构化解决问题能力强，能够清晰有力地呈现工作成果。\n3.沟通协作能力出色，善于主动推动跨部门对齐。\n4.自驱力强，结果导向，能够在快节奏、高度不确定的环境中从容应对。\n5.熟练掌握SQL及数据分析工具，有看板搭建或数据可视化经验者优先。\n6.英语沟通能力强。\n7.对于深度了解沙特消费者行为、本地文化及市场动态有热情。\n\n1.3+ years of experience in internet, consulting, or related industries, with a background in operations, data science, or business analytics.\n2.Strong logical thinking and structured problem-solving skills; able to present work clearly and persuasively.\n3.Excellent communication and collaboration skills; proactive in driving cross-functional alignment.\n4.Self-motivated, results-driven, and comfortable working in a fast-paced, ambiguous environment.\n5.Proficiency in SQL and data analysis tools; experience with dashboards or data visualization is a plus.\n6.Native-level Arabic proficiency required, with strong English communication skills.\n7.Deep understanding of Saudi consumer behavior, local culture, and market dynamics.","description":"部门介绍\nKeeta是全球领先外卖平台美团旗下的独立品牌，肩负着“帮大家吃得更好，生活更好”的使命。依托美团深耕中国市场15年的技术与运营积淀，我们正引领全球餐饮与商品即时配送服务的创新与发展。\n\n自2023年成立以来，Keeta始终扎根社区并创造价值。我们为用户提供可靠的外卖体验，以智慧技术助餐厅提升经营效率，在为骑手拓宽收入来源的同时，也充分提供安全保障措施。基于这份多方共赢、共同成长的理念，我们的业务已从中国香港稳步拓展至中东及巴西，并持续向世界迈进。\n\n岗位职责\n1.业务监控与目标管理：负责用户侧核心KPI体系的搭建与维护，构建并持续优化周/月度经营监控框架，追踪业务目标达成进展。\n2.战略研究与洞察：综合运用数据分析、用户研究及市场调研等方法，深入研究关键业务问题，输出清晰的策略建议。\n3.运营策略支持：与运营团队紧密协作，参与用户侧补贴、活动、流量等策略的设计、分析与评估，推动A/B测试与迭代优化。\n4.数据产品管理：统筹内部数据产品需求（看板、取数、用户标签等），协调产品与技术团队，保障高质量数据基础设施的稳定交付。\n5.运用 AI 工具（如 ChatGPT、Copilot 等）辅助日常工作，提升产出效率与质量，主动探索 AI 在本岗位的应用最佳实践。\n\n1.Business Monitoring & Goal Management:Own and maintain the user-side KPI system; build and continuously optimize weekly/monthly performance monitoring frameworks to track progress against business targets.\n2.Strategic Research & Insights:Conduct in-depth studies on key business challenges using data analysis, user research, and market studies; deliver clear strategy .\n3.Operations Strategy Support:Partner with operations teams to design, analyze, and evaluate user-side initiatives including subsidies, campaigns, and traffic strategies; drive A/B testing and iterative optimization.\n4.Data Product Management:Manage internal data product requests (dashboards, data extraction, user tagging); coordinate with product and engineering teams to deliver reliable, high-quality data infrastructure.\n5.Leverage AI tools (e.g., ChatGPT, Copilot) to enhance daily workflows, improve content quality, and actively explore AI-driven best practices in marketing and brand operations.\n\n岗位基本要求\n1.3年以上互联网、咨询或相关行业经验，具备运营、数据科学或商业分析背景。\n2.逻辑思维清晰，结构化解决问题能力强，能够清晰有力地呈现工作成果。\n3.沟通协作能力出色，善于主动推动跨部门对齐。\n4.自驱力强，结果导向，能够在快节奏、高度不确定的环境中从容应对。\n5.熟练掌握SQL及数据分析工具，有看板搭建或数据可视化经验者优先。\n6.英语沟通能力强。\n7.对于深度了解沙特消费者行为、本地文化及市场动态有热情。\n\n1.3+ years of experience in internet, consulting, or related industries, with a background in operations, data science, or business analytics.\n2.Strong logical thinking and structured problem-solving skills; able to present work clearly and persuasively.\n3.Excellent communication and collaboration skills; proactive in driving cross-functional alignment.\n4.Self-motivated, results-driven, and comfortable working in a fast-paced, ambiguous environment.\n5.Proficiency in SQL and data analysis tools; experience with dashboards or data visualization is a plus.\n6.Native-level Arabic proficiency required, with strong English communication skills.\n7.Deep understanding of Saudi consumer behavior, local culture, and market dynamics.\n\n具备以下条件优先\n1.有区域性或国际化公司工作经验。\n2.熟悉电商、外卖或消费互联网商业模式。\n3.熟练使用 AI 工具（如 ChatGPT、Copilot 等）辅助日常工作；具备 AI 学习意愿，能主动探索 AI 在业务场景中的应用。\n\n1.Experience working with regional or international companies\n2.Familiarity with e-commerce, food delivery, or consumer internet business models\n3.Proficiency in AI tools (e.g., ChatGPT, Copilot) for day-to-day work; a proactive learning mindset with eagerness to explore AI applications in marketing scenarios.\n\n岗位亮点\n1.参与市场塑造——加入创始团队，共同打造沙特阿拉伯下一个优秀的外卖平台。\n2.全链路业务主导——深度参与用户增长、留存与变现全链路，拥有真正的决策影响力。\n3.高速成长环境——学习曲线陡峭，团队文化优秀，直接接触高层管理。\n4.国际平台，本地影响——将全球最佳实践引入沙特市场，并将其转化为属于你的成果。\n5.身处 AI 赋能的工作环境，配备前沿 AI 工具与资源，帮助你在 AI 时代持续提升竞争力、加速职业成长。\n\n1.Shape a market — Be part of a founding team building Saudi Arabia's next leading food delivery platform.\n2.Full-funnel ownership — Work across user growth, retention, and monetization with real decision-making influence.\n3.High-growth environment — Fast learning curve, strong team culture, direct exposure to senior leadership.\n4.International platform, local impact — Bring global best practices to the Saudi market and make them yours.\n5.AI-empowered workplace with access to cutting-edge AI tools and resources, helping you stay competitive and accelerate your career in the AI era.","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4777203989","sourceKey":"meituan_social","company":"美团","title":"Agent 评测产品经理","city":"北京市/上海市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4777203989&jobShareType=1","duty":"CatPaw 是面向工作与生产场景的 AI Agent 产品矩阵，覆盖通用办公、云端助理、AI 编程、NoCode 应用生成及企业级 Agent 平台。我们正在寻找一位对 AI 产品效果高度敏感、兼具产品判断力和技术理解力的产品经理。你将负责 CatPaw 系列产品的效果评测、同类产品对标和持续调优，建立从“发现差距—定位原因—推动优化—验证结果”到“沉淀标准”的完整闭环。\n\n\n1、负责 CatPaw 系列产品的效果评测体系建设，覆盖通用办公 Agent、云端助理、Coding Agent、NoCode 及企业级 Agent 等产品方向。\n2、根据真实用户场景建立任务分类、评测数据集、评分标准和基准线，持续完善离线评测、人工评测、自动化评测和在线效果观测机制。\n3、持续跟踪国内外主流 AI Agent 产品，设计公平、可复现的横向对比方案，评估任务完成质量、成功率、稳定性、交互体验、执行效率、成本及安全性等关键维度。\n4、深入分析评测失败案例和用户负反馈，结合会话、Trace、模型输出及工具调用过程，判断问题来自模型、Prompt、上下文、知识库、工具、Skill、执行环境还是产品交互。\n5、与算法、研发、设计及业务团队协作，推动模型策略、Agent Harness、Prompt、Context、Memory、RAG、工具调用和交互体验等方向的调优。\n6、设计并推动 A/B 实验、回归测试和版本验收，验证优化方案的真实收益，避免局部指标提升但整体用户体验下降。\n7、将评测结果转化为清晰的产品判断和优先级建议，为产品路线图、模型选型、能力建设及版本发布提供决策依据。","requirements":"1、3 年以上 AI、开发者工具、企业软件或效率产品相关经验，其中至少 1 年大模型或 AI Agent 产品经验。\n2、深度使用过多款国内外大模型及 Agent 产品，能够识别“看起来能完成”和“真实场景下稳定完成”之间的差异。\n3、理解大模型及 Agent 的基本工作机制，熟悉 Prompt、Context、RAG、Memory、Tool Calling、MCP、Skills、Sandbox 等概念。\n4、具备较强的评测设计能力，能够将模糊的“效果好不好”拆解为可执行的测试任务、评价维度和度量指标。\n5、具备良好的数据分析和问题归因能力，能够从大量案例中识别共性问题，并提出可验证的优化假设。\n6、有较强的动手能力和好奇心，愿意高频体验产品、复现问题，并持续跟踪快速变化的 AI 产品与技术趋势。","description":"部门介绍\n基础研发平台是美团的核心技术平台，立足于“零售+科技”的战略定位，通过打造人工智能、大数据、云计算、安全等核心技术能力，以及研发效能平台、企业应用平台等公共服务，为业务提供稳定安全、扩展易用、技术领先的平台技术和产品服务。\n在这里，我们会参与到最前沿的技术研发和探索；能够接触超规模集群、海量数据，挑战高复杂业务场景，有机会与业界一流的工程师一起并肩前行。\n在这里，我们有超强的技术氛围，持续向社区贡献业界实践，加速行业技术发展；我们有完善的互联网学习生态圈，重视底层逻辑和方法论，助力职业生涯的非线性成长。\n真诚地邀请你，和我们一起驱动技术发展，创造行业价值。\n\n岗位职责\nCatPaw 是面向工作与生产场景的 AI Agent 产品矩阵，覆盖通用办公、云端助理、AI 编程、NoCode 应用生成及企业级 Agent 平台。我们正在寻找一位对 AI 产品效果高度敏感、兼具产品判断力和技术理解力的产品经理。你将负责 CatPaw 系列产品的效果评测、同类产品对标和持续调优，建立从“发现差距—定位原因—推动优化—验证结果”到“沉淀标准”的完整闭环。\n\n\n1、负责 CatPaw 系列产品的效果评测体系建设，覆盖通用办公 Agent、云端助理、Coding Agent、NoCode 及企业级 Agent 等产品方向。\n2、根据真实用户场景建立任务分类、评测数据集、评分标准和基准线，持续完善离线评测、人工评测、自动化评测和在线效果观测机制。\n3、持续跟踪国内外主流 AI Agent 产品，设计公平、可复现的横向对比方案，评估任务完成质量、成功率、稳定性、交互体验、执行效率、成本及安全性等关键维度。\n4、深入分析评测失败案例和用户负反馈，结合会话、Trace、模型输出及工具调用过程，判断问题来自模型、Prompt、上下文、知识库、工具、Skill、执行环境还是产品交互。\n5、与算法、研发、设计及业务团队协作，推动模型策略、Agent Harness、Prompt、Context、Memory、RAG、工具调用和交互体验等方向的调优。\n6、设计并推动 A/B 实验、回归测试和版本验收，验证优化方案的真实收益，避免局部指标提升但整体用户体验下降。\n7、将评测结果转化为清晰的产品判断和优先级建议，为产品路线图、模型选型、能力建设及版本发布提供决策依据。\n\n岗位基本要求\n1、3 年以上 AI、开发者工具、企业软件或效率产品相关经验，其中至少 1 年大模型或 AI Agent 产品经验。\n2、深度使用过多款国内外大模型及 Agent 产品，能够识别“看起来能完成”和“真实场景下稳定完成”之间的差异。\n3、理解大模型及 Agent 的基本工作机制，熟悉 Prompt、Context、RAG、Memory、Tool Calling、MCP、Skills、Sandbox 等概念。\n4、具备较强的评测设计能力，能够将模糊的“效果好不好”拆解为可执行的测试任务、评价维度和度量指标。\n5、具备良好的数据分析和问题归因能力，能够从大量案例中识别共性问题，并提出可验证的优化假设。\n6、有较强的动手能力和好奇心，愿意高频体验产品、复现问题，并持续跟踪快速变化的 AI 产品与技术趋势。\n\n岗位亮点\n1、站在 AI Agent 产品演进的一线，持续体验和研究全球优秀产品，定义什么是“真正好用的 Agent”。\n2、不只是发现问题和输出报告，还能深入 Agent 核心链路，直接推动模型、Prompt、Context、Memory、工具与交互体验优化。\n3、评测结论将直接影响产品路线、模型选型和版本发布，能够把个人的产品判断沉淀为 CatPaw 的产品标准。\n4、与优秀的产品、算法和工程团队紧密协作，共同探索企业级 AI Agent 的能力边界。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4754655165","sourceKey":"meituan_social","company":"美团","title":"快乐猴物流经理","city":"杭州市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4754655165&jobShareType=1","duty":"1.仓储运营KPI数据监控与效率问题诊断\n\n持续监控出入库准时率、准确率、人效、损耗率等核心运营指标，定期输出运营分析报告\n\n及时发现数据异常，深入诊断效率瓶颈，制定改善方案并跟踪闭环，确保仓储运营KPI持续达成\n\n2. 人员排班调度与仓储作业任务分配执行\n\n根据业务量预测科学制定排班计划，合理分配收货、上架、拣选、出库、加工等各环节作业任务\n\n负责一线仓储团队建设、人才梯队搭建、人员选用育励汰实施\n\n督导员工按照作业标准规范执行，灵活应对业务波动，激励团队士气，持续提升整体人效水平\n\n3. 库存盘点组织与盘差原因分析处理\n\n制定并执行日常及周期性库存盘点计划，确保账实数据准确一致\n\n对盘差原因进行系统分析，制定针对性整改措施并推动闭环\n\n建立盘差预防机制，有效管控损耗，监控临期/滞销商品并推动及时处置\n\n4. 仓储安全生产检查与隐患整改推动\n\n建立并执行安全生产巡检机制，定期开展安全检查，及时发现隐患并推动限期整改\n\n监督食品安全与卫生标准日常落地，落实消防及设备设施安全管理要求，组织安全培训与应急演练，确保安全生产零事故\n\n5. 仓储流程优化方案制定与标准推广\n\n定期梳理仓储各环节作业流程，识别痛点与优化空间，制定可落地的优化方案并推动试点\n\n将成熟优化成果整理为操作手册，在全仓统一推广执行，持续迭代提升作业效率与规范化水平","requirements":"1、学历专业：大学专科及以上学历，物流管理、供应链、仓储管理等相关专业优先。\n\n2、工作经验：具备5年以上物流/仓储运营管理经验，其中至少3年担任仓储管理岗位，有大型仓储中心管理经验者优先；具备生鲜或快消品行业背景者优充先考虑。\n\n3、专业技能：熟悉PC/RDC生产线运作流程及物流操作规范；熟悉WMS系统操作及仓储自动化设备应用；具备较强的流程优化与精益改善能力。\n\n4、通用能力：具备良好的数据分析和问题解决能力，能够准确分析问题并提出解决方案；具备优秀的团队管理能力与沟通协调能力，能跨部门有效协作。","description":"部门介绍\n快乐猴是美团自营社区超市，依托自有供应链和门店管理体系，聚焦家庭用户的三餐所需，为消费者提供高质价比的食杂商品。快乐猴以数字化能力与科学品控为基础，不断满足消费者对“省”和“便利”的需求。\n\n岗位职责\n1.仓储运营KPI数据监控与效率问题诊断\n\n持续监控出入库准时率、准确率、人效、损耗率等核心运营指标，定期输出运营分析报告\n\n及时发现数据异常，深入诊断效率瓶颈，制定改善方案并跟踪闭环，确保仓储运营KPI持续达成\n\n2. 人员排班调度与仓储作业任务分配执行\n\n根据业务量预测科学制定排班计划，合理分配收货、上架、拣选、出库、加工等各环节作业任务\n\n负责一线仓储团队建设、人才梯队搭建、人员选用育励汰实施\n\n督导员工按照作业标准规范执行，灵活应对业务波动，激励团队士气，持续提升整体人效水平\n\n3. 库存盘点组织与盘差原因分析处理\n\n制定并执行日常及周期性库存盘点计划，确保账实数据准确一致\n\n对盘差原因进行系统分析，制定针对性整改措施并推动闭环\n\n建立盘差预防机制，有效管控损耗，监控临期/滞销商品并推动及时处置\n\n4. 仓储安全生产检查与隐患整改推动\n\n建立并执行安全生产巡检机制，定期开展安全检查，及时发现隐患并推动限期整改\n\n监督食品安全与卫生标准日常落地，落实消防及设备设施安全管理要求，组织安全培训与应急演练，确保安全生产零事故\n\n5. 仓储流程优化方案制定与标准推广\n\n定期梳理仓储各环节作业流程，识别痛点与优化空间，制定可落地的优化方案并推动试点\n\n将成熟优化成果整理为操作手册，在全仓统一推广执行，持续迭代提升作业效率与规范化水平\n\n岗位基本要求\n1、学历专业：大学专科及以上学历，物流管理、供应链、仓储管理等相关专业优先。\n\n2、工作经验：具备5年以上物流/仓储运营管理经验，其中至少3年担任仓储管理岗位，有大型仓储中心管理经验者优先；具备生鲜或快消品行业背景者优充先考虑。\n\n3、专业技能：熟悉PC/RDC生产线运作流程及物流操作规范；熟悉WMS系统操作及仓储自动化设备应用；具备较强的流程优化与精益改善能力。\n\n4、通用能力：具备良好的数据分析和问题解决能力，能够准确分析问题并提出解决方案；具备优秀的团队管理能力与沟通协调能力，能跨部门有效协作。\n\n岗位亮点\n互联网一线公司，大平台，业务前景好，个人成长发展空间大","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4477143991","sourceKey":"meituan_social","company":"美团","title":"小象超市-杭州前置品控负责人","city":"杭州市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4477143991&jobShareType=1","duty":"1. 负责小象超市供应链环节的前置商品及供应商全链路质量管控体系管理及落地执行，预防和优化商品质量问题，整体提升供应商的品质供给能力；\n2. 负责前置品控团队的管理，并完成下属团队的培养和能力的提升；\n3. 与协同部门共同推动供应商及商品的品质提升及稳定，建立良好的合作关系，共同保障业务的到货供给；","requirements":"1. 5年以上商超零售电商质量管理经验或供应链质量管理经验；\n2. 具备较好的跨部门沟通表达及协作能力，能快速落地执行；\n3. 有较好的责任心，自驱力强；\n4. 具备正直诚信的价值观，有较强的原则性。","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n1. 负责小象超市供应链环节的前置商品及供应商全链路质量管控体系管理及落地执行，预防和优化商品质量问题，整体提升供应商的品质供给能力；\n2. 负责前置品控团队的管理，并完成下属团队的培养和能力的提升；\n3. 与协同部门共同推动供应商及商品的品质提升及稳定，建立良好的合作关系，共同保障业务的到货供给；\n\n岗位基本要求\n1. 5年以上商超零售电商质量管理经验或供应链质量管理经验；\n2. 具备较好的跨部门沟通表达及协作能力，能快速落地执行；\n3. 有较好的责任心，自驱力强；\n4. 具备正直诚信的价值观，有较强的原则性。\n\n具备以下条件优先\n具有极强的快速学习能力，有拿结果的决心；\n有较强的质量管理方法论且可以快速结合业务特点落地能力。\n\n岗位亮点\n美团大平台，即时零售风口，开放的管理模式，发展空间大 。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4712991313","sourceKey":"meituan_social","company":"美团","title":"小象超市-工厂品控专员","city":"北京市/深圳市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4712991313&jobShareType=1","duty":"岗位职责：  \n1. 负责烘焙工厂生产过程中的质量监控，确保产品符合公司及行业标准。  \n2. 执行原材料、半成品及成品的抽样检验，记录并反馈质量问题。  \n3. 协助制定和完善品控流程与作业指导书，推动质量改进措施落地。  \n4. 配合处理客户质量投诉，参与根本原因分析并提出整改建议。","requirements":"岗位基本要求：  \n1. 大学专科及以上学历，质量管理、食品科学、化工、生物工程等相关专业优先。  \n2. 具备2年以上工厂品控或质量管理相关工作经验。  \n3. 熟悉ISO9001、HACCP等质量管理体系，了解国家相关法规标准。  \n4. 工作细致严谨，具备较强的沟通协调能力和问题解决能力。  \n5. 能适应工厂车间环境","description":"部门介绍\n小象超市为美团自营零售业务，定位为社区居民的“30分钟快送超市”，采用“手机App+线下服务站”的模式，通过在社区设立的集存储、分拣、配送为一体的便民服务站，为社区居民提供生鲜食杂日用及配送服务。目前，小象超市已在北京、上海、深圳、广州、武汉、苏州、杭州等多个城市上线。在美团“零售+科技”战略聚焦下，小象超市承载着“深耕即时零售，提升消费体验”的任务，是公司在线上零售探索的核心业态之一，给一二线城市用户带来线上零售即时达的消费体验，解决城市家庭追求快速、品质服务的需求。在这里，我们有来自国内外知名零售公司的大牛和一群热爱零售，胸怀使命，心系民生的伙伴，小象超市欢迎你的加入！\n\n岗位职责\n岗位职责：  \n1. 负责烘焙工厂生产过程中的质量监控，确保产品符合公司及行业标准。  \n2. 执行原材料、半成品及成品的抽样检验，记录并反馈质量问题。  \n3. 协助制定和完善品控流程与作业指导书，推动质量改进措施落地。  \n4. 配合处理客户质量投诉，参与根本原因分析并提出整改建议。\n\n岗位基本要求\n岗位基本要求：  \n1. 大学专科及以上学历，质量管理、食品科学、化工、生物工程等相关专业优先。  \n2. 具备2年以上工厂品控或质量管理相关工作经验。  \n3. 熟悉ISO9001、HACCP等质量管理体系，了解国家相关法规标准。  \n4. 工作细致严谨，具备较强的沟通协调能力和问题解决能力。  \n5. 能适应工厂车间环境\n\n具备以下条件优先\n烘焙/蛋糕制造经验优先\n\n岗位亮点\n1. 提供系统的质量管理培训，助力个人专业能力提升。  \n2. 团队氛围积极，注重员工成长与职业发展。","jdComplete":true,"sourceStatus":"000"},{"id":"meituan_social:4757682689","sourceKey":"meituan_social","company":"美团","title":"综合内控专家","city":"北京市","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://zhaopin.meituan.com/web/position/detail?jobUnionId=4757682689&jobShareType=1","duty":"1、承担综合内控管理的专家职责，落地公司层的管理体系化建设、高风险域治理等的工作，提升管理体系化、通用风险治理的成熟度。\n\n2、组织开展内控评价、ERM 企业风险管理体系建设与落地工作，评估企业内部控制情况与风险管控效果，用于企业内部风险管控落地与对外披露。\n\n3、制定整体内控、风险管理方案，确定重点领域，推进包括风险治理在内的各类内控项目，体系化的解决业务的实际问题，并对各类咨询进行专业解答。\n\n4、推进 AI 在内控评价、ERM、合规检查、知识库及报告自动化等场景的落地，参与建设内控风险管理相关 AI Agent 撰写数字化产品需求，推动落地应用。\n\n5、负责风险预警与数智化风控建设，将业务风险经验转化为规则、指标、监控机制，建设风险管理业务策略，并通过数字化产品或AI Agent落地监控。","requirements":"1、本科及以上学历，5年以上大中型企业、事务所、咨询公司内控、审计、财经等的甲乙方的工作经验；熟悉内控内审方法论，如COSO，SOX，港股上市规范及相关指引等。\n\n2、负责过大型的内控、ERM项目，能快速识别高风险领域和关键控制点，具备构建风控矩阵及内控评价的能力及经验。\n\n3、了解大模型、知识库、智能体及本体模型，有主导或参与 AI 场景需求定义、数据准备、规则梳理及效果评估的落地经验。\n\n4、有丰富的项目管理经验，担任过大型复杂项目的PMO，有较强的对模糊度高、复杂度高、跨部门项目的沟通与推动力。\n\n5、客户意识强，深入理解客户需求，从体系上解决问题，而非碎片/散点的处理个案；好奇心强，可以主动复盘迭代；有责无界，沟通坦诚、透明。","description":"部门介绍\n财务平台负责公司整体和各业务层面的财务管理工作，通过建设专业、全面、复合的财务管理能力和与业务经营的紧密结合来支持公司健康发展。目前财务平台拥有财务会计、财务报告、资金管理、税务管理、财务共享、财务系统、规划分析、财务BP和内控内审等主要工作方向。我们的目标是建设业界一流的财务管理能力和经营支持体系，为公司战略的正确落地、投入效率的持续提升、业务价值的不断增长保驾护航。欢迎加入财务平台，携手一起向未来！\n\n岗位职责\n1、承担综合内控管理的专家职责，落地公司层的管理体系化建设、高风险域治理等的工作，提升管理体系化、通用风险治理的成熟度。\n\n2、组织开展内控评价、ERM 企业风险管理体系建设与落地工作，评估企业内部控制情况与风险管控效果，用于企业内部风险管控落地与对外披露。\n\n3、制定整体内控、风险管理方案，确定重点领域，推进包括风险治理在内的各类内控项目，体系化的解决业务的实际问题，并对各类咨询进行专业解答。\n\n4、推进 AI 在内控评价、ERM、合规检查、知识库及报告自动化等场景的落地，参与建设内控风险管理相关 AI Agent 撰写数字化产品需求，推动落地应用。\n\n5、负责风险预警与数智化风控建设，将业务风险经验转化为规则、指标、监控机制，建设风险管理业务策略，并通过数字化产品或AI Agent落地监控。\n\n岗位基本要求\n1、本科及以上学历，5年以上大中型企业、事务所、咨询公司内控、审计、财经等的甲乙方的工作经验；熟悉内控内审方法论，如COSO，SOX，港股上市规范及相关指引等。\n\n2、负责过大型的内控、ERM项目，能快速识别高风险领域和关键控制点，具备构建风控矩阵及内控评价的能力及经验。\n\n3、了解大模型、知识库、智能体及本体模型，有主导或参与 AI 场景需求定义、数据准备、规则梳理及效果评估的落地经验。\n\n4、有丰富的项目管理经验，担任过大型复杂项目的PMO，有较强的对模糊度高、复杂度高、跨部门项目的沟通与推动力。\n\n5、客户意识强，深入理解客户需求，从体系上解决问题，而非碎片/散点的处理个案；好奇心强，可以主动复盘迭代；有责无界，沟通坦诚、透明。\n\n具备以下条件优先\n1、头部互联网公司/港股上市公司内控工作经验，咨询公司或四大内控、风险咨询相关工作经验。\n\n2、有企业级 AI Agent 建设落地经历，熟练使用AI工具（Claude Code/CodeX/OpenCode/DeepSeek Harness/Cursor等）辅助日常工作。\n\n3、有将AI能力主动引入风险识别、数据分析、治理措施等内控日常工作场景中，整合业务场景，通过vibecoding输出Demo，推动实现从技术到产品的落地闭环。\n\n4、持有CPA、CISA、CIA、FRM、CFA、ACCA等证书。\n\n岗位亮点\n1、头部互联网公司的公司层面内控团队，提供内外多元化学习交流的机会，有充分的专家学习资源与氛围，成长空间大。\n\n2、探索AI在内控领域应用的前沿方法与落地实践，并在业务流程改造与AI Agent建设应用中积累实战经验。\n\n3、多元化背景团队活泼良好的团队氛围，开放多元化的成长空间，共同思考探索行业前沿方法，拓展能力边界。\n\n4、公司内部AI工具完善、应用广泛，能够在具体业务场景中积累实战经验。","jdComplete":true,"sourceStatus":"000"}];
